    // A session's Prepare block: the piece's path, straight into its run-through.
    async function startPrepareInSession(scoreId, movement) {
        try { await loadPieceLevels(scoreId); } catch (e) { showWarningToast('Piece not loaded: ' + e.message); switchView('sessionRunView'); return; }
        levels.scope = levelsScopeFor(movement); // ML-530: a list's one movement
        prep.onlyPrepare = false;
        switchView('piecePathView');
        renderPiecePath();
        prep.fromSession = true;
        openPrepareRun();
    }
    // A Play-through block: the part given, or - for a piece whose parts aren't made yet - the first part
    // once saving the piece's Levels has made them.
    async function startPlaythroughBlock(b) {
        let chunk = b.chunk;
        if (!chunk) {
            await loadPieceLevels(b.scoreId);
            levels.scope = levelsScopeFor(b.movement); // ML-530: a list's one movement - its own parts
            if (levels.scope && !scopedGroups().length) {
                await savePlaythroughParts(FlowJourney.playthroughParts(levels.blocks, PracticePlan.TARGET_LEVEL).filter(([a, z]) => inLevelsScope({ startBar: a, endBar: z })));
            } else if (!levels.groups.length) {
                const body = levels.chunks.map(c => ({ id: c.id, kind: c.kind, startBar: c.startBar, endBar: c.endBar, level: c.level, label: c.label }));
                applyPieceLevels(await API.levels.save(levels.flowId, body));
            }
            const part = nextPart();
            if (!part) throw new Error('there is nothing to play through yet');
            chunk = { ...part, scoreId: b.scoreId, title: b.title };
            b.chunk = chunk;
        }
        await startChunkPractice(chunk);
    }
    // Open a chunk's piece and practise it at its Level (ML-317), from a session.
    async function startChunkPractice(chunk) {
        await loadPieceLevels(chunk.scoreId);
        setShown('flowPlayMenuEditDetails', currentFlowDetail.canEdit);
        setShown('flowPlayMenuEditFlow', currentFlowDetail.canEdit);
        setShown('flowPlayMenuCopy', (!currentFlowDetail.canEdit && currentFlowDetail.isPublic) || !!currentFlowDetail.ownerBandId);
        setShown('flowPlayMenuReport', !!currentFlowDetail.isPublic || !!currentFlowDetail.ownerBandId);
        setShown('flowPlayMenuLevels', isFeatureEnabled('practice_levels'));
        const c = [...levels.chunks, ...levels.groups].find(x => x && x.id === chunk.id);
        if (!c) throw new Error('those bars have changed - check the piece\'s Levels');
        const level = c.level != null ? c.level : c.kind === 'group' ? PracticePlan.TARGET_LEVEL : null;
        if (level == null) throw new Error('those bars have no Level yet');
        startLevelPractice({ ...c, level });
    }
    async function finishPracticeRun(early, timeUp) {
        const r = practiceRun;
        if (!r || r.done) return;
        if (early && r.phase !== 'rest') { const b = r.blocks[r.index]; b.seconds += runElapsed(); b.started = true; }
        if (!early || timeUp) window.Usage?.finish('session'); // ML-22: every block played, or the time was up
        r.done = true;
        renderUpdateBanner(); // ML-564: the session is over, so a waiting "new version" strip can show now
        clearInterval(practiceTick);
        stopSessionTimer(); // ML-421
        API.practice.clearActive().catch(() => { /* gone when it goes stale */ });
        if (flowSession) endLevelPractice();
        const played = r.blocks.filter(b => b.started && b.seconds > 0);
        const minutes = Math.max(1, Math.round(played.reduce((s, b) => s + b.seconds, 0) / 60));
        document.getElementById('sessRunDoneTitle').textContent = timeUp ? "Time's up - well played!" : early ? 'Session ended' : 'Session done - well played!';
        document.getElementById('sessRunDoneText').textContent = `${minutes} minute${minutes === 1 ? '' : 's'}, ${played.length} block${played.length === 1 ? '' : 's'}. Saving to your practice history...`;
        switchView('sessionRunView');
        renderPracticeRun();
        if (!played.length) { document.getElementById('sessRunDoneText').textContent = 'Nothing was played, so nothing was saved.'; return; }
        try {
            await API.practice.saveSession({
                minutes, endedAt: new Date().toISOString(),
                segments: played.map(b => ({ kind: b.kind, plannedMinutes: b.minutes, actualSeconds: b.seconds, chunkId: b.chunk ? b.chunk.id : null, tool: b.kind === 'skills' ? (b.skill ? (SKILLS[b.skill.key] || {}).tool || null : b.tool) : null }))
            });
            document.getElementById('sessRunDoneText').textContent = `${minutes} minute${minutes === 1 ? '' : 's'}, ${played.length} block${played.length === 1 ? '' : 's'} - saved to your practice history.`;
            fetchDataAndRender(); // Stats and history pick up the new session
        } catch (e) {
            document.getElementById('sessRunDoneText').textContent = `${minutes} minutes - not saved: ${e.message}. Add it with Add session time.`;
        }
    }
    function renderPracticeRun() {
        const r = practiceRun;
        const bar = document.getElementById('sessionBar');
        const top = viewStack[viewStack.length - 1];
        setShown(bar, !!r && !r.done && top !== 'sessionRunView' && top !== 'sessionRestView');
        if (!r) return;
        const strip = sessStripHtml(r.blocks, r.done ? r.blocks.length : r.index);
        document.getElementById('sessRunStrip').innerHTML = strip;
        document.getElementById('sessionBarStrip').innerHTML = strip;
        setShown('sessRunActive', !r.done);
        setShown('sessRunDone', r.done);
        if (r.done) return;
        const b = r.blocks[r.index];
        const count = r.open ? `Block ${r.index + 1} · open ended` : `Block ${r.index + 1} of ${r.blocks.length}`;
        const isPrepare = b.kind === 'rehearsal' && b.stage === 'prepare';
        const resting = r.phase === 'rest';
        const time = resting ? `${Math.max(0, restLength() - restElapsed())}s` : isPrepare ? fmtMinSec(runElapsed()) : fmtMinSec(Math.max(0, (Number.isFinite(r.nudgeAt) ? r.nudgeAt : 0) - runElapsed()));
        document.getElementById('sessRunCount').textContent = count;
        setKindIcon(document.getElementById('sessRunIcon'), b);
        document.getElementById('sessRunKind').textContent = resting ? 'Rest' : blockTitle(b);
        document.getElementById('sessRunDetail').textContent = resting ? 'The rest is part of the music.' : sessBlockText(b);
        document.getElementById('sessRunTime').textContent = time;
        document.getElementById('sessRunTimeSub').textContent = r.pausedAt ? 'paused - press play on the timer to carry on' : resting ? 'of rest left' : isPrepare ? 'so far - take as long as you need' : 'left in this block';
        const go = document.getElementById('sessRunGoBtn');
        go.textContent = resting ? 'Back to the rest' : isPrepare ? (b.started ? 'Back to preparing' : 'Start preparing') : b.started ? 'Back to this block' : 'Start this block';
        const next = r.blocks[r.index + 1];
        document.getElementById('sessRunUpNext').textContent = next ? `Up next: ${sessBlockName(next)}` : 'This is the last block.';
        const nextBtn = document.getElementById('sessRunNextBtn');
        nextBtn.textContent = next ? 'Next block' : 'Finish the session';
        setShown(nextBtn, !resting);
        document.getElementById('sessionBarText').textContent = `${count} · ${resting ? 'Rest' : blockTitle(b)}`;
        document.getElementById('sessionBarTime').textContent = r.pausedAt ? `Paused · ${time}` : r.finishingGo ? 'Last go' : time; // ML-541: time's up, the go is finishing
        // While a block plays, the bar names the piece and the bars being played now (ML-540 - it named the
        // piece coming next, so the bars to play were only ever on the rest screen before).
        const music = !resting && nextMusic(b);
        const barNow = document.getElementById('sessionBarNext');
        barNow.textContent = music ? `Now: ${music.title}${music.to ? ` · ${levelsRange(music.from, music.to)}` : ''}` : '';
        setShown(barNow, !!music);
        // The block you're on fills in as its time goes (owner, 1 Oct 2026) - full in the rest after it, and
        // full for a Prepare, which has no end.
        const fill = resting || isPrepare || !(r.nudgeAt > 0) ? 1 : Math.min(1, Math.max(0, runElapsed() / r.nudgeAt));
        document.querySelectorAll('#sessRunStrip .session-seg.is-now, #sessionBarStrip .session-seg.is-now').forEach(s => s.style.setProperty('--seg-fill', fill.toFixed(3)));
    }

    document.getElementById('startPracticeSessionBtn')?.addEventListener('click', () => (practiceRun && !practiceRun.done ? switchView(practiceRun.phase === 'rest' ? 'sessionRestView' : 'sessionRunView') : openSessionSetup({})));
    document.getElementById('sessRunGoBtn')?.addEventListener('click', () => { if (practiceRun && practiceRun.phase === 'rest') switchView('sessionRestView'); else startSessionBlock(); });
    document.getElementById('sessRunNextBtn')?.addEventListener('click', () => sessionTimeUp());
    document.getElementById('sessRunEndBtn')?.addEventListener('click', () => finishPracticeRun(true));
    document.getElementById('sessRunDoneBtn')?.addEventListener('click', () => { practiceRun = null; renderPracticeRun(); switchView('mainView'); });
    document.getElementById('sessionBar')?.addEventListener('click', () => switchView(practiceRun && practiceRun.phase === 'rest' ? 'sessionRestView' : 'sessionRunView'));
    // Practice session test hook - LOCAL DEVELOPMENT ONLY, the same switch as the Flow and Theory hooks
    // (localhost + localStorage 'tml.testClock' = '1'): read the run and move a block's (or the rest's) clock on.
    (function sessionTestHook() {
        let on = false;
        try { on = ['localhost', '127.0.0.1'].includes(location.hostname) && localStorage.getItem('tml.testClock') === '1'; } catch (e) { on = false; }
        if (!on) return;
        window.__sessionTest = {
            run: () => (practiceRun ? JSON.parse(JSON.stringify({ ...practiceRun, elapsed: practiceRun.phase === 'rest' ? restElapsed() : runElapsed() })) : null),
            plan: () => JSON.parse(JSON.stringify(sessPlan)),
            skip: (seconds) => { if (!practiceRun) return; if (practiceRun.phase === 'rest') practiceRun.restStart -= seconds * 1000; else practiceRun.blockStart -= seconds * 1000; practiceRunTick(); },
            skills: () => JSON.parse(JSON.stringify(skillsData.map(x => ({ key: x.key, stepIndex: x.stepIndex, done: x.done, step: x.step })))),
            skillContext: () => skillContext,
            drillSaved: (tool, level, grade) => skillDrillSaved(tool, level, grade)
        };
    })();


    // ===== ML-319 (epic ML-314): practice lists and the readiness forecast =====
    // A list is a concert's pieces with its date, sessions a week and session length (saved as you type).
    // The forecast is PracticePlan.forecast: one block moves one chunk up one Level; anything not set up
    // is named, not guessed; when behind it suggests the first change that gets you there. "Plan a
    // session for this" opens the planner with only this list's pieces for the Rehearsal blocks.
    const plState = { list: null, saveTimer: null, picked: null };
    const MONTHS_SHORT = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const DAYS_SHORT = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    // ML-476: the biggest recording or document a piece can hold (the server's MAX_PIECE_FILE_BYTES, blobUrls.js).
    // Said on the upload buttons, and checked here so a big file is refused before it starts uploading.
    const MAX_PIECE_FILE_MB = 25;
    // ML-278: before a member's first upload of music they confirm, once, that they have the right to
    // upload it. The terms of use already say so; this puts it in front of them when it matters, and the
    // day they agreed is kept on their account (accounts.upload_rights_confirmed_on). Every button that
    // opens a file chooser for music goes through here. go() runs first, inside the tap, because a
    // browser only opens a file chooser from the member's own tap; the day is saved straight after.
    // The server asks for it too (security re-check 21 Oct 2026), so an upload waits for the day to be saved
    // (uploadToStore) - the file chooser is open while it is, so nobody waits in practice.
    let uploadRightsSaving = Promise.resolve();
    // The sign-in token goes to our upload-token route as a header (ML-574) - never in the address, where it
    // would reach request logs and the browser's history. upload() sends these headers to that route only,
    // never on to the file store.
    async function uploadToStore(pathname, body, options) {
        await uploadRightsSaving;
        return window.vercelBlobUpload(pathname, body, { ...options, headers: { ...(options.headers || {}), Authorization: `Bearer ${auth.token}` } });
    }
    function withUploadRights(go) {
        if (accountProfile && accountProfile.uploadRightsConfirmedOn) { go(); return; }
        showConfirmModal('Before you upload',
            'Only upload music you have the right to use: your own, your band\'s, or something you have permission for. Printed music and recordings are usually someone\'s copyright. If it is a recording of people, make sure they know it is being shared - and if any of them are under 16, that a parent has agreed.',
            () => {
                if (accountProfile) accountProfile.uploadRightsConfirmedOn = todayIso();
                go();
                uploadRightsSaving = apiCall('/api/account/upload-rights', 'POST').catch(() => { if (accountProfile) accountProfile.uploadRightsConfirmedOn = null; });
            }, false, 'I have the right to upload it');
    }
    function pieceFileTooBig(file) {
        if (!file || file.size <= MAX_PIECE_FILE_MB * 1024 * 1024) return false;
        showWarningToast(`"${file.name}" is ${(file.size / (1024 * 1024)).toFixed(0)} MB. The most a piece can hold is ${MAX_PIECE_FILE_MB} MB - for a long recording or a video, add a YouTube link instead.`);
        return true;
    }
    function todayIso() { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; }
    function plDateText(iso) {
        if (!iso) return 'No target date';
        const d = new Date(`${iso}T12:00:00`);
        const days = Math.round((Date.parse(`${iso}T00:00:00Z`) - Date.parse(`${todayIso()}T00:00:00Z`)) / 86400000);
        const when = days < 0 ? 'past' : days === 0 ? 'today' : `${days} day${days === 1 ? '' : 's'} to go`;
        return `${DAYS_SHORT[d.getDay()]} ${d.getDate()} ${MONTHS_SHORT[d.getMonth()]} · ${when}`;
    }
    // ML-403: Rehearse and My music both show Pieces and Practice lists as tabs, from this one place.
    // 'rehearse' / 'mymusic' -> which tab is showing. Pieces opens first; a way in can ask for the other
    // (musicTabNext - after adding a piece to a list, My music opens on Practice lists).
    const musicTab = { rehearse: 'pieces', mymusic: 'pieces' };
    let musicTabNext = null; // { screen, tab } for the next time that screen opens
    function setMusicTab(screen, tab) {
        const on = isFeatureEnabled('practice_levels');
        musicTab[screen] = on ? tab : 'pieces';
        const bar = document.querySelector(`[data-music-tabs="${screen}"]`);
        setShown(bar, on);
        bar?.querySelectorAll('[data-music-tab]').forEach(b => {
            const active = b.dataset.musicTab === musicTab[screen];
            b.classList.toggle('active', active);
            b.setAttribute('aria-selected', String(active));
        });
        document.querySelectorAll(`[data-music-panel][data-music-screen="${screen}"]`).forEach(p => setShown(p, p.dataset.musicPanel === musicTab[screen]));
    }
    // Opening the screen fresh starts on Pieces (or what was asked for); coming Back keeps the tab you left
    function openMusicTabs(screen, isBack) {
        const asked = musicTabNext && musicTabNext.screen === screen ? musicTabNext.tab : null;
        if (asked) musicTabNext = null;
        setMusicTab(screen, asked || (isBack ? musicTab[screen] : 'pieces'));
        renderPracticeListRows();
    }
    document.querySelectorAll('[data-music-tabs]').forEach(bar => bar.addEventListener('click', (e) => {
        const b = e.target.closest('[data-music-tab]');
        if (b) setMusicTab(bar.dataset.musicTabs, b.dataset.musicTab);
    }));
    document.querySelectorAll('[data-new-list]').forEach(b => b.addEventListener('click', () => newPracticeList()));
    // The practice lists, drawn into both screens' Practice lists tab
    // ML-595: the one Filter - whose list, and the archived lists (a switch: shown instead of the others). There once
    // there is something to filter by. Per visit, the same on both screens.
    let plListState = {};
    let plCurrentLists = []; // also for the pieces' filter "On a practice list"
    const plShowsArchived = () => (plListState.archived || []).includes('yes') && plArchivedLists.length > 0;
    const plListBase = () => (plShowsArchived() ? plArchivedLists : plCurrentLists);
    function plListGroups() {
        const all = [...plCurrentLists, ...plArchivedLists];
        const bands = [...new Map(all.filter(l => l.bandId).map(l => [l.bandId, l.bandName || 'Band'])).entries()].map(([id, name]) => ({ value: `band:${id}`, label: name })).sort((a, b) => a.label.localeCompare(b.label));
        const whose = [...(all.some(l => !l.bandId) ? [{ value: 'mine', label: 'Mine' }] : []), ...bands];
        return [{ key: 'whose', label: 'Whose', options: whose.length > 1 ? whose : [] },
            { key: 'archived', label: 'Archived', toggle: true, apply: false, help: 'Show the lists you have archived instead', options: plArchivedLists.length ? [{ value: 'yes', label: 'Archived lists', count: plArchivedLists.length }] : [] }];
    }
    const plListMatch = (l, key, v) => (key === 'whose' ? (v === 'mine' ? !l.bandId : `band:${l.bandId}` === v) : true);
    async function renderPracticeListRows() {
        if (!isFeatureEnabled('practice_levels')) return;
        const boxes = document.querySelectorAll('[data-practice-lists]');
        try {
            const { lists: current } = await API.practiceLists.list();
            plCurrentLists = current;
            const lists = Filters.apply(plListBase(), plListGroups(), plListState, plListMatch);
            const filterable = plListGroups().some(g => g.options.length);
            const rows = lists.length ? lists.map(l => `
                <div class="history-item">
                    <button type="button" class="level-row-body grow text-left" data-list="${l.id}">
                        <span><strong>${escapeHtml(l.name)}</strong><br><span class="text-sm text-muted">${l.bandName ? `${escapeHtml(l.bandName)} · ` : ''}${plDateText(l.eventDate)} · ${l.pieceCount} piece${l.pieceCount === 1 ? '' : 's'}</span></span>
                    </button>
                </div>`).join('') : plListBase().length ? '<p class="text-sm text-muted">No lists match.</p>' : '<p class="text-sm text-muted">A list is the pieces you\'re working towards - give it a target date and it shows the pace you need.</p>';
            boxes.forEach((box, i) => {
                box.innerHTML = (filterable ? `<div class="filter-bar" id="plListsFilter${i}"></div>` : '') + rows;
                if (filterable) {
                    renderFilterBar({
                        id: `plListsFilter${i}`, title: 'Show practice lists', allLabel: 'All lists', noun: 'lists',
                        groups: plListGroups, state: () => plListState, setState: (s) => { plListState = s; }, items: plListBase, match: plListMatch,
                        shown: () => Filters.apply(plListBase(), plListGroups(), plListState, plListMatch).length, total: () => plCurrentLists.length,
                        onChange: renderPracticeListRows
                    });
                }
                box.querySelectorAll('[data-list]').forEach(b => b.addEventListener('click', () => openPracticeList(Number(b.dataset.list))));
            });
            document.querySelectorAll('[data-list-count]').forEach(el => { el.textContent = current.length ? String(current.length) : ''; });
        } catch (e) {
            boxes.forEach(box => { box.innerHTML = ''; });
        }
    }
    async function openPracticeList(id) {
        // Forget the list shown before, so nothing tapped while this one loads acts on that one (Archive, the date...)
        plState.list = null;
        document.getElementById('plPieces').innerHTML = ''; // and its piece rows, so none can be tapped
        switchView('practiceListView');
        try {
            plState.list = await API.practiceLists.get(id);
            renderPracticeList();
            loadPlPace(); // ML-557
        } catch (e) {
            showWarningToast('List not loaded: ' + e.message);
        }
    }
    // An archived piece stays on its lists but isn't counted: the forecast is worked out without it, and its
    // place in the answer (pieces[i] lines up with list.pieces[i]) says so.
    // ML-557: SmartLearn uses the member's own pace (blocks per Level) once there are 10 Level-ups to go on
    let plPace = null;
    const plPaceUsed = () => (isFeatureEnabled('theory_smart_learn') && plPace && plPace.ready ? plPace.blocksPerLevel : null);
    async function loadPlPace() {
        if (!isFeatureEnabled('theory_smart_learn')) return;
        try { plPace = await API.levels.pace(); if (plState.list) renderPracticeList(); } catch { /* the plain forecast stands */ }
    }
    function plForecast(list) {
        const f = PracticePlan.forecast({ pieces: list.pieces.filter(p => !p.archived), eventDate: list.eventDate, today: todayIso(), pace: plPaceUsed() });
        let k = 0;
        return { ...f, pieces: list.pieces.map(p => (p.archived ? { title: p.title, archived: true, prep: false, blocks: 0 } : f.pieces[k++])) };
    }
    // ML-332: the target date button and its pop-up - no target date, or pick one. ML-348: dd mmm yy,
    // so the longest date still fits the button's fixed quarter width.
    function plDateLabel(iso) {
        if (!iso) return 'None';
        const d = new Date(`${iso}T12:00:00`);
        return `${String(d.getDate()).padStart(2, '0')} ${MONTHS_SHORT[d.getMonth()]} ${String(d.getFullYear()).slice(2)}`;
    }
    function openPlDateModal() {
        const l = plState.list;
        if (!l) return;
        const has = !!l.eventDate;
        document.getElementById('plDateNoneBtn').classList.toggle('selected', !has);
        document.getElementById('plDateNoneBtn').setAttribute('aria-pressed', String(!has));
        document.getElementById('plDateSetBtn').classList.toggle('selected', has);
        document.getElementById('plDateSetBtn').setAttribute('aria-pressed', String(has));
        document.getElementById('plDate').value = l.eventDate || '';
        setShown('plDatePickGroup', has);
        document.getElementById('plDateBtn').setAttribute('aria-expanded', 'true');
        showModal('plDateModal');
    }
    function closePlDateModal() {
        hideModal('plDateModal');
        document.getElementById('plDateBtn').setAttribute('aria-expanded', 'false');
    }
    async function plSaveDate(iso) {
        closePlDateModal();
        const l = plState.list;
        if (!l || (l.eventDate || null) === (iso || null)) return;
        try { plState.list = await API.practiceLists.update(l.id, { name: l.name, eventDate: iso || null }); renderPracticeList(); }
        catch (e) { showWarningToast('List not saved: ' + e.message); }
    }
    // ===== ML-557: my own weekly plan for a practice list =====
    // Three value boxes beside the target date - sessions a week, minutes a session, the warm-up in it - each a
    // pop-up. My own, even on a band's list (how often someone practises is never shown to the band). With the
    // first two set: about how many weeks it takes, and how far I've come since I made the plan - never "behind".
    function renderPlPlan(l, f) {
        const plan = l.plan || {};
        document.getElementById('plWeekLbl').textContent = plan.sessionsPerWeek || 'None';
        document.getElementById('plMinsLbl').textContent = plan.sessionMinutes || 'None';
        document.getElementById('plWarmLbl').textContent = plan.warmupMinutes ? `${plan.warmupMinutes} min` : 'None';
        document.getElementById('plWeekBtn').setAttribute('aria-label', `Sessions a week: ${plan.sessionsPerWeek || 'none'} - tap to change`);
        document.getElementById('plMinsBtn').setAttribute('aria-label', `Minutes a session: ${plan.sessionMinutes || 'none'} - tap to change`);
        document.getElementById('plWarmBtn').setAttribute('aria-label', `Warm-up: ${plan.warmupMinutes ? plan.warmupMinutes + ' minutes' : 'none'} - tap to change`);
        const text = document.getElementById('plPlanText');
        const wp = l.plan ? PracticePlan.weeklyPlan({ blocks: f.total, ...plan }) : null;
        text.textContent = !l.plan ? ''
            : !plan.sessionsPerWeek || !plan.sessionMinutes ? 'Set sessions a week and minutes to see how many weeks it takes.'
            : !wp ? 'The warm-up takes the whole session - leave time for the pieces.'
            : !f.total ? 'Everything counted is ready.'
            : `${plural(plan.sessionsPerWeek, 'session')} a week of ${plan.sessionMinutes} minutes${plan.warmupMinutes ? ` (${plan.warmupMinutes} of them warming up)` : ''} is ${plural(wp.perSession, 'block')} on the pieces a session: about ${plural(wp.weeks, 'week')} to be ready.`;
        setShown(text, !!text.textContent);
        // How far I've come since making the plan - the blocks done, out of done and still to do
        const done = l.plan ? l.plan.blocksSince || 0 : 0;
        const since = document.getElementById('plPlanSince');
        setShown('plPlanTrack', !!l.plan && done > 0);
        setShown(since, !!l.plan && (done > 0 || (l.plan.sessionsSince || 0) > 0));
        if (l.plan) {
            document.getElementById('plPlanTrackFill').style.setProperty('--pct', `${Math.round((done / Math.max(1, done + f.total)) * 100)}%`);
            since.textContent = `Since you made the plan on ${new Date(l.plan.setAt).toLocaleDateString(undefined, { day: 'numeric', month: 'long' })}: ${plural(l.plan.sessionsSince || 0, 'practice session')} and ${plural(done, 'block')} on these pieces.`;
        }
        const pace = document.getElementById('plPaceText');
        const used = plPaceUsed();
        pace.textContent = used ? `Worked out from your own pace: about ${used} block${used === 1 ? '' : 's'} to move a focus section up a Level.`
            : isFeatureEnabled('theory_smart_learn') && plPace && !plPace.ready ? `After ${plPace.needed} Level-ups this uses your own pace (${plPace.levelUps} so far).` : '';
        setShown(pace, !!pace.textContent);
    }
    // Each choice shows at once and the saves go one after another, so two boxes set quickly don't undo each other
    let plPlanSaving = Promise.resolve();
    function plSavePlan(change) {
        const l = plState.list;
        if (!l) return;
        const plan = { sessionsPerWeek: null, sessionMinutes: null, warmupMinutes: 0, ...(l.plan || {}), ...change };
        l.plan = plan;
        renderPracticeList();
        const body = { sessionsPerWeek: plan.sessionsPerWeek, sessionMinutes: plan.sessionMinutes, warmupMinutes: plan.warmupMinutes };
        plPlanSaving = plPlanSaving.then(async () => {
            try {
                const saved = await API.practiceLists.setPlan(l.id, body);
                if (plState.list && plState.list.id === saved.id && plState.list.plan === plan) { plState.list = saved; renderPracticeList(); }
            } catch (e) { showWarningToast('Plan not saved: ' + e.message); }
        });
    }
    function plPlanChoice(title, key, values, word) {
        const cur = (plState.list && plState.list.plan && plState.list.plan[key]) || null;
        openFlowChoiceModal(title, [
            { value: null, label: 'None', selected: !cur },
            ...values.map(v => ({ value: v, label: word(v), selected: cur === v }))
        ], (opt) => plSavePlan({ [key]: opt.value === null && key === 'warmupMinutes' ? 0 : opt.value }));
    }
    document.getElementById('plWeekBtn')?.addEventListener('click', () => plPlanChoice('Sessions a week', 'sessionsPerWeek', [1, 2, 3, 4, 5, 6, 7], v => plural(v, 'session') + ' a week'));
    document.getElementById('plMinsBtn')?.addEventListener('click', () => plPlanChoice('Minutes a session', 'sessionMinutes', [10, 15, 20, 25, 30, 40, 45, 60, 90, 120], v => `${v} minutes`));
    document.getElementById('plWarmBtn')?.addEventListener('click', () => plPlanChoice('Warm-up in each session', 'warmupMinutes', [5, 10, 15, 20], v => `${v} minutes`));

    document.getElementById('plDateBtn')?.addEventListener('click', openPlDateModal);
    document.getElementById('plDateCloseBtn')?.addEventListener('click', closePlDateModal);
    document.getElementById('plDateNoneBtn')?.addEventListener('click', () => plSaveDate(null));
    document.getElementById('plDateSetBtn')?.addEventListener('click', () => {
        document.getElementById('plDateSetBtn').classList.add('selected');
        document.getElementById('plDateSetBtn').setAttribute('aria-pressed', 'true');
        document.getElementById('plDateNoneBtn').classList.remove('selected');
        document.getElementById('plDateNoneBtn').setAttribute('aria-pressed', 'false');
        setShown('plDatePickGroup', true);
        const input = document.getElementById('plDate');
        if (!input.value) input.value = todayIso();
        input.focus();
    });
    document.getElementById('plDateDoneBtn')?.addEventListener('click', () => {
        const v = document.getElementById('plDate').value;
        if (!v) return showWarningToast('Pick a date first');
        plSaveDate(v);
    });
    function renderPracticeList() {
        const l = plState.list;
        if (!l) return;
        document.getElementById('topTitle').innerText = l.name;
        const setVal = (id, v) => { const el = document.getElementById(id); if (document.activeElement !== el) el.value = v == null ? '' : v; };
        setVal('plName', l.name);
        // ML-473: a band list, for a member who can play but not change the band's music - they plan from it as it is
        const canEdit = l.canEdit !== false;
        document.getElementById('plName').disabled = !canEdit;
        document.getElementById('plDateBtn').disabled = !canEdit;
        ['plAddPiecesBtn', 'plDeleteBtn', 'plPieceMenuDelete'].forEach(id => setShown(id, canEdit));
        // Archive / Restore: anyone, for themselves; a list archived for the whole band comes back only for someone who can change it
        setShown('plArchiveBtn', !l.archived || !l.archivedForAll || canEdit);
        document.getElementById('plArchiveBtn').textContent = l.archived ? 'Restore this list' : 'Archive this list';
        setShown('plReportBtn', !!l.bandId); // ML-510: a band's list; always there, whatever the account type
        setShown('plClearRecordingsBtn', isFeatureEnabled('rehearsal_recordings') && l.pieces.length > 0); // ML-489: your own uploads, so not tied to canEdit
        document.getElementById('plDateBtnText').textContent = plDateLabel(l.eventDate);
        document.getElementById('plDateBtn').setAttribute('aria-label', `Target date: ${l.eventDate ? plDateText(l.eventDate) : 'none'} - tap to change`);
        const f = plForecast(l);
        const verdict = document.getElementById('plVerdict');
        const text = document.getElementById('plVerdictText');
        // ML-333: the blocks it takes, and with a target date the daily pace that gets there.
        const blocks = (n) => `${n} five-minute block${n === 1 ? '' : 's'}`;
        if (!l.pieces.length) { verdict.textContent = 'Add the pieces'; text.textContent = 'Add the pieces you\'re working towards and this works out how much practice they need.'; }
        else if (f.total === 0) { verdict.textContent = 'Ready'; text.textContent = 'Everything counted is at Level 5.'; }
        else {
            verdict.textContent = `${blocks(f.total)} to be ready`;
            text.textContent = f.days === null ? `That's ${f.minutes} minutes of rehearsal. Add a target date to see the pace you need.`
                : f.days === 0 ? `That's ${f.minutes} minutes of rehearsal - and the target date is today.`
                : `About ${blocks(f.perDay)} (${f.perDayMinutes} minutes) a day. ${plDateText(l.eventDate)}.`;
        }
        const nc = document.getElementById('plNotCounted');
        setShown(nc, f.notCounted.length > 0);
        nc.textContent = `Not counted: ${f.notCounted.join('; ')}.`;
        renderPlPlan(l, f);
        const box = document.getElementById('plPieces');
        const shownMaps = []; // the bars drawn - the key's empty box only when one of them has bars with no level (ML-548)
        box.innerHTML = l.pieces.length ? l.pieces.map((p, i) => {
            // ML-530: a piece on the list as one movement - that movement's bars only
            const m = p.movement;
            const map = m ? FlowJourney.barLevels(m.endBar, p.chunks).slice(m.startBar - 1) : FlowJourney.barLevels(p.totalBars, p.chunks);
            if (!f.pieces[i].archived && !f.pieces[i].prep) shownMaps.push(map);
            const name = m ? `${p.title} · ${FlowJourney.movementLabel(m, true)}` : p.title;
            const pb = f.pieces[i];
            // ML-334: a piece not set up yet is fine on a list - its first block is preparation for
            // practice (giving it Levels), which you can do now.
            const note = pb.archived ? 'Archived - not counted' : pb.prep ? 'Not prepared yet - a Prepare block first' : pb.blocks === 0 ? 'Ready' : `${pb.blocks} block${pb.blocks === 1 ? '' : 's'} to be ready`;
            return `<div class="history-item">
                <button type="button" class="level-row-body grow text-left" data-piece="${p.scoreId}" aria-label="${escapeHtml(name)} - ${note}. ${pb.prep ? 'Prepare it now' : 'Open its path'}">
                    <span class="grow"><strong>${escapeHtml(name)}</strong><br><span class="text-sm text-muted">${note}</span>
                    ${pb.archived ? '' : pb.prep ? '<span class="text-sm fw-bold">Prepare it now &rsaquo;</span>' : levelBarHtml(map, { label: false, cls: 'mt-1' })}</span>
                </button>
                <button type="button" class="list-item-menu-btn" data-piece-menu="${p.scoreId}" aria-label="Options for ${escapeHtml(p.title)}" aria-haspopup="menu" aria-expanded="false"><span class="material-symbols-outlined" aria-hidden="true">more_vert</span></button>
            </div>`;
        }).join('') + (shownMaps.length ? levelLegendHtml(shownMaps, undefined, 'bar') : '') : '<p class="text-sm text-muted">No pieces yet.</p>';
        sizeLevelBars(box);
        box.querySelectorAll('[data-piece]').forEach(b => b.addEventListener('click', () => { const id = Number(b.dataset.piece); openPiecePath(id, { movement: (l.pieces.find(p => p.scoreId === id) || {}).movement }); }));
        box.querySelectorAll('[data-piece-menu]').forEach(b => b.addEventListener('click', (e) => {
            e.stopPropagation();
            openPlPieceMenu(b, Number(b.dataset.pieceMenu));
        }));
        document.getElementById('plPlanBtn').disabled = !l.pieces.some(p => !p.archived);
    }
    // ML-349: a piece row's ⋮ menu - Prepare levels / Edit levels, then Delete (asks first, then Undo).
    let plPieceMenuTargetId = null;
    function openPlPieceMenu(btnEl, id) {
        if (!plState.list) return; // still loading
        const menu = document.getElementById('plPieceMenu');
        const i = plState.list.pieces.findIndex(p => p.scoreId === id);
        if (!menu || i < 0) return;
        plPieceMenuTargetId = id;
        document.getElementById('plPieceMenuLevelsText').textContent = plForecast(plState.list).pieces[i].prep ? 'Prepare this piece' : 'Its path and Levels';
        // ML-530: a piece in movements - the whole piece on this list, or one movement (someone who can change the list)
        setShown('plPieceMenuMovement', plState.list.canEdit !== false && (plState.list.pieces[i].movements || []).length > 1);
        menu.classList.add('show');
        const r = btnEl.getBoundingClientRect();
        placeAt(menu, Math.max(8, Math.min(r.right - menu.offsetWidth, window.innerWidth - menu.offsetWidth - 8)),
            Math.min(r.bottom + 4, window.innerHeight - menu.offsetHeight - 8));
    }
    function closePlPieceMenu() { document.getElementById('plPieceMenu')?.classList.remove('show'); }
    document.addEventListener('click', closePlPieceMenu);
    document.getElementById('plPieceMenuLevels')?.addEventListener('click', (e) => {
        e.stopPropagation();
        closePlPieceMenu();
        openPiecePath(plPieceMenuTargetId, { movement: (plState.list.pieces.find(p => p.scoreId === plPieceMenuTargetId) || {}).movement });
    });
    // ML-530: the list holds the whole piece or one of its movements - a concert that plays only one
    const plItems = (pieces) => pieces.map(p => ({ scoreId: p.scoreId, movement: p.movement ? p.movement.number : null }));
    document.getElementById('plPieceMenuMovement')?.addEventListener('click', (e) => {
        e.stopPropagation();
        closePlPieceMenu();
        const piece = plState.list.pieces.find(p => p.scoreId === plPieceMenuTargetId);
        if (!piece) return;
        const cur = piece.movement ? piece.movement.number : null;
        openFlowChoiceModal('Which movement is on this list?', [
            { n: null, selected: !cur, html: addPieceRow('The whole piece', `All ${piece.movements.length} movements`) },
            ...piece.movements.map(m => ({ n: m.number, selected: cur === m.number, html: addPieceRow(FlowJourney.movementLabel(m, true), `Bars ${m.startBar}-${m.endBar}`) }))
        ], (opt) => {
            if (opt.n === cur) return;
            plSetPieces(plItems(plState.list.pieces).map(x => (x.scoreId === piece.scoreId ? { ...x, movement: opt.n } : x)));
        });
    });
    document.getElementById('plPieceMenuDelete')?.addEventListener('click', (e) => {
        e.stopPropagation();
        closePlPieceMenu();
        const id = plPieceMenuTargetId;
        const piece = plState.list.pieces.find(p => p.scoreId === id);
        if (!piece) return;
        showConfirmModal('Delete piece', `Take "${piece.title}" off this list? It stays in My music.`, async () => {
            const listId = plState.list.id, before = plItems(plState.list.pieces);
            if (await plSetPieces(before.filter(x => x.scoreId !== id))) showUndoToast(`${piece.title} taken off the list`, () => { if (plState.list?.id === listId) plSetPieces(before); });
        }, true, 'Delete');
    });
    async function plSetPieces(ids) {
        try { plState.list = await API.practiceLists.setPieces(plState.list.id, ids); renderPracticeList(); return true; }
        catch (e) { showWarningToast('List not saved: ' + e.message); return false; }
    }
    // The name saves a moment after you stop typing (the target date saves from its pop-up).
    function plFieldChanged() {
        clearTimeout(plState.saveTimer);
        plState.saveTimer = setTimeout(async () => {
            const l = plState.list;
            if (!l) return;
            const body = { name: document.getElementById('plName').value.trim() || l.name, eventDate: l.eventDate || null };
            try { plState.list = await API.practiceLists.update(l.id, body); renderPracticeList(); }
            catch (e) { showWarningToast('List not saved: ' + e.message); }
        }, 600);
    }
    // ML-351: Add pieces - a pick list of the pieces not on the list yet, filtered like My music (All /
    // Mine / each band / Public, plus a title/composer search; flowLibraryFilterKey), both per visit.
    // ML-595: the one Filter, opening in place inside the pop-up.
    const plPick = { state: {}, query: '' };
    function openPlPiecesModal() {
        if (!plState.list) return; // still loading
        plState.picked = new Set();
        plPick.state = {};
        plPick.query = '';
        document.getElementById('plPiecesSearch').value = '';
        closeFilterInPopup('plPiecesModal');
        renderPlPiecesModal();
        showModal('plPiecesModal');
        if (!Object.keys(flowLibraryBandNames).length) loadFlowLibraryBandNames().then(renderPlPiecesModal);
    }
    const plOffered = () => { const onList = new Set(plState.list.pieces.map(p => p.scoreId)); return ((typeof rehearsePlayable === 'function' ? rehearsePlayable() : flowsListCache) || []).filter(f => !onList.has(f.id)); };
    function renderPlPiecesModal() {
        const onList = new Set(plState.list.pieces.map(p => p.scoreId));
        const offered = plOffered();
        const ownerName = (key) => key === 'mine' ? 'Mine' : key === 'public' ? 'Public' : (flowLibraryBandNames[Number(key.slice(5))] || 'Band');
        const groups = () => pieceFilterGroups(plOffered(), { prepared: true });
        const q = plPick.query;
        const shown = Filters.apply(offered, groups(), plPick.state, pieceFilterMatch).filter(f => pieceSearchMatch(f, q));
        renderFilterBar({
            id: 'plPiecesFilterBar', title: 'Show pieces', allLabel: 'All pieces', noun: 'pieces', modal: 'plPiecesModal',
            groups, state: () => plPick.state, setState: (s) => { plPick.state = s; }, items: plOffered, match: pieceFilterMatch,
            shown: () => Filters.apply(plOffered(), groups(), plPick.state, pieceFilterMatch).filter(f => pieceSearchMatch(f, plPick.query)).length,
            total: () => plOffered().length, onChange: renderPlPiecesModal
        });
        const rows = shown.map(f => ({ key: f.id, html: `<strong>${escapeHtml(f.title)}</strong><br><span class="text-sm text-muted">${f.composer ? escapeHtml(f.composer) + ' · ' : ''}${f.totalBars} bar${f.totalBars === 1 ? '' : 's'} · ${escapeHtml(ownerName(flowLibraryFilterKey(f)))}</span>` }));
        renderPickList(document.getElementById('plPiecesOptions'), document.getElementById('plPiecesPickBar'), rows, plState.picked, renderPlPiecesDone,
            `<p class="metro-help-text">${!offered.length ? (onList.size ? 'Every piece is on this list already.' : 'No pieces yet - add one in My music.') : 'No pieces match.'}</p>`);
    }
    function renderPlPiecesDone() {
        const btn = document.getElementById('plPiecesDoneBtn');
        btn.disabled = !plState.picked.size;
        btn.textContent = pickCountLabel(plState.picked.size, 'piece');
    }
    document.getElementById('plPiecesSearch')?.addEventListener('input', (e) => { plPick.query = e.target.value.trim().toLowerCase(); renderPlPiecesModal(); });
    document.getElementById('plName')?.addEventListener('input', plFieldChanged);
    document.getElementById('plAddPiecesBtn')?.addEventListener('click', () => { if (!flowsListCache.length) rehearseRefresh(); openPlPiecesModal(); });
    document.getElementById('plPiecesCloseBtn')?.addEventListener('click', () => hideModal('plPiecesModal'));
    document.getElementById('plPiecesDoneBtn')?.addEventListener('click', () => {
        if (!plState.picked.size) return;
        hideModal('plPiecesModal');
        plSetPieces([...plState.list.pieces.map(p => p.scoreId), ...plState.picked]);
    });
    document.getElementById('plPlanBtn')?.addEventListener('click', () => {
        // ML-333/342: a session for a list is the Concert plan (Warm-up, then Pieces) on its pieces (ML-390: the steps).
        const l = plState.list;
        openSessionSetup({ source: { type: 'list', listId: l.id, listName: l.name }, template: 'concert' });
    });
    // Archive a list that is done with (or bring it back): it leaves the Practice lists tab, the session
    // builder and the home screen's next-concert line until Archived is chosen. Its pieces are not touched.
    async function plSetArchived(l, archived, forAll) {
        try {
            plState.list = await API.practiceLists.setArchived(l.id, archived, forAll);
            renderPracticeList();
            renderPracticeListRows();
            showSuccessToast(!archived ? 'Back in your practice lists' : forAll ? `Archived for everyone in ${l.bandName || 'the band'}` : 'Archived - switch on Archived lists in the Filter on the Practice lists tab to see it again');
        } catch (e) { showWarningToast((archived ? 'Not archived: ' : 'Not brought back: ') + e.message); }
    }
    document.getElementById('plArchiveBtn')?.addEventListener('click', () => {
        const l = plState.list;
        if (!l) return;
        if (l.archived) return plSetArchived(l, false, l.archivedForAll && l.canEdit !== false);
        if (!(l.bandId && l.canEdit !== false)) return plSetArchived(l, true, false);
        const band = l.bandName || 'the band';
        openFlowChoiceModal('Archive it for who?', [
            { forAll: false, html: addPieceRow('Just me', `It stays in ${band}'s lists for everyone else`) },
            { forAll: true, html: addPieceRow(`Everyone in ${band}`, 'Nobody in the band sees it until it is brought back') }
        ], (c) => plSetArchived(l, true, c.forAll));
    });
    document.getElementById('plDeleteBtn')?.addEventListener('click', () => {
        const l = plState.list;
        showConfirmModal('Delete this list?', `"${l.name}" goes, but its pieces and your Levels stay.`, async () => {
            try { await API.practiceLists.remove(l.id); plState.list = null; goBack(); renderPracticeListRows(); }
            catch (e) { showWarningToast('List not deleted: ' + e.message); }
        }, true, 'Delete');
    });

    // (ML-390: join-up groups are now a piece's play-through parts - chosen on its path, piecePathView.)

    // ===== ML-321 (epic ML-314): your skills list =====
    // A skill is a playing tool plus its steps in order (SKILLS below - Range ML-305 and Rhythm ML-306
    // plug in here when they're built). Tempo, Pulse and Pitch pass a step at grade 4 or 5 (the drill's
    // own score, caught in saveDrill); Warm-ups and Scales ask "Got it?". The list, where you're up to
    // and every go are on the server (/api/practice/skills*).
    const SKILL_PASS_GRADE = 4;
    // maxAccidentals (ML-338): a grade's scales go up to that many sharps or flats; null = every key.
    function scalesSkillSteps(mode, maxAccidentals = null) {
        return TheoryEngine.ALL_KEYS.filter(k => k.mode === mode && (maxAccidentals === null || k.count <= maxAccidentals))
            .sort((a, b) => a.count - b.count || (a.type === 'sharp' ? -1 : 1) - (b.type === 'sharp' ? -1 : 1))
            .map(k => ({ id: k.id, label: `${k.tonic} ${mode}` }));
    }
    // ML-338: grades 1-5 - the exam grades a skill belongs to ([first, last]), so Add skills can filter
    // by grade. Scales also come grade-sized: a grade's major keys go up to that many sharps or flats
    // (Grade 5: all of them), and minor keys start at Grade 2, up to one fewer. See docs/practice-sessions.md.
    const SKILL_GRADES = [1, 2, 3, 4, 5];
    const WARMUP_KIND_GRADES = { 'long-tones': [1, 5], 'lip-slurs': [2, 5], flexibility: [3, 5], articulation: [1, 5], fingers: [1, 5], melodic: [1, 3] };
    const RHYTHM_SET_GRADES = { words: [1, 2], beat: [1, 3], two: [2, 4], triplets: [3, 5], six8: [4, 5] };
    const SKILLS = {
        tapTempo: { label: 'Tempo', tool: 'tapTempo', graded: true, grades: [1, 5], steps: () => Drills.TAP.LEVELS.map(l => ({ id: l.id, label: l.label })) },
        gapTrainer: { label: 'Pulse', tool: 'gapTrainer', graded: true, grades: [1, 5], steps: () => Drills.GAP.PATTERNS.map(p => ({ id: p.id, label: p.label })) },
        'ear:playback': { label: 'Pitch - Play it back', tool: 'ear', graded: true, grades: [1, 5], steps: () => Drills.EAR.NOTE_SETS.map(s => ({ id: `playback:${s.id}`, set: s.id, label: s.label })) },
        'scales:major': { label: 'Scales - major keys', tool: 'scales', mode: 'major', graded: false, grades: [1, 5], steps: () => scalesSkillSteps('major') },
        'scales:minor': { label: 'Scales - minor keys (harmonic)', tool: 'scales', mode: 'minor', graded: false, grades: [2, 5], steps: () => scalesSkillSteps('minor') },
        ...Object.fromEntries(SKILL_GRADES.map(g => [`scales:major-g${g}`, {
            label: `Scales - Grade ${g} major keys`, tool: 'scales', mode: 'major', graded: false, grades: [g, g],
            steps: () => scalesSkillSteps('major', g >= 5 ? null : g)
        }])),
        ...Object.fromEntries(SKILL_GRADES.filter(g => g >= 2).map(g => [`scales:minor-g${g}`, {
            label: `Scales - Grade ${g} minor keys (harmonic)`, tool: 'scales', mode: 'minor', graded: false, grades: [g, g],
            steps: () => scalesSkillSteps('minor', g >= 5 ? null : g - 1)
        }])),
        ...Object.fromEntries(Warmups.KINDS.map(k => [`warmups:${k.id}`, {
            label: `Warm-ups - ${k.label.toLowerCase()}`, tool: 'warmups', graded: false, kind: k.id, grades: WARMUP_KIND_GRADES[k.id] || [1, 5],
            steps: () => (warmupsAll || []).filter(ex => ex.kind === k.id).map(ex => ({ id: ex.id, label: ex.title }))
        }])),
        // ML-306: Rhythm (feature rhythm_trainer), one entry per set; its steps are the set's rhythms,
        // passed at grade 4 or 5 (saveDrill -> skillDrillSaved, the rhythm id is the drill level).
        ...Object.fromEntries(Rhythm.SETS.map(set => [`rhythm:${set.id}`, {
            label: `Rhythm - ${set.label.toLowerCase()}`, tool: 'rhythm', graded: true, set: set.id, feature: 'rhythm_trainer', grades: RHYTHM_SET_GRADES[set.id] || [1, 5],
            steps: () => Rhythm.patternsIn(set.id).map(p => ({ id: p.id, label: p.name }))
        }])),
        // ML-305: Range (feature range_trainer). The step is always the note just beyond your range on
        // your main instrument - it moves with your range (rangeSkillSteps), so it isn't a fixed ladder.
        ...Object.fromEntries(['up', 'down'].map(dir => [`range:${dir}`, {
            label: dir === 'up' ? 'Range - top notes' : 'Range - bottom notes', tool: 'range', graded: false, direction: dir, rolling: true, feature: 'range_trainer', grades: [1, 5],
            desc: 'moves on when a note reaches Level 5 and you move your range',
            steps: () => rangeSkillSteps(dir)
        }]))
    };
    let skillsData = [];        // the skills list you're on (ML-339), with each skill's steps and your progress attached
    let skillLists = [];        // ML-339: your named skills lists [{ id, name, keys }]
    let skillProgress = [];     // where you're up to on every skill you've had on a list
    const SKILL_LIST_STORE = 'tml.skills.list'; // the list you're on - per device
    let skillListId = (() => { try { return Number(localStorage.getItem(SKILL_LIST_STORE)) || null; } catch (e) { return null; } })();
    function currentSkillList() { return skillLists.find(l => l.id === skillListId) || skillLists[0] || null; }
    function setSkillList(id) {
        skillListId = id;
        try { localStorage.setItem(SKILL_LIST_STORE, String(id)); } catch (e) { /* per-device convenience */ }
        buildSkillsData();
    }
    function buildSkillsData() {
        const list = currentSkillList();
        const byKey = new Map(skillProgress.map(p => [p.key, p]));
        skillsData = list ? list.keys.map(k => skillWithSteps(byKey.get(k) || { key: k, stepIndex: 0, lastPractised: null })).filter(Boolean) : [];
    }
    function applySkillsResponse(out) {
        if (out && Array.isArray(out.lists)) skillLists = out.lists;
        if (out && Array.isArray(out.skills)) skillProgress = out.skills;
        buildSkillsData();
    }
    var skillContext = null;    // var: saveDrill checks it - { key, stepIndex, stepId, tool } while practising a step
    var skillWarmupsKind = null; // var: warmupsList reads it - a Warm-ups skill shows only its own kind
    function skillWithSteps(item) {
        const def = SKILLS[item.key];
        if (!def) return null;
        const steps = def.steps();
        if (def.rolling) return { ...item, stepIndex: 0, def, steps, done: steps.length === 0, step: steps[0] || null };
        return { ...item, def, steps, done: steps.length > 0 && item.stepIndex >= steps.length, step: steps[Math.min(item.stepIndex, Math.max(0, steps.length - 1))] || null };
    }
    async function loadSkills() {
        await warmupsLoad(); // the Warm-ups skills' steps are the exercises
        if (isFeatureEnabled('range_trainer') && !rangeData) await rangeLoad(); // Range's step is the note beyond your range
        try { applySkillsResponse(await API.skills.list()); }
        catch (e) { skillLists = []; skillProgress = []; buildSkillsData(); }
        await loadWarmupLists();
        return skillsData;
    }
    const skillStepText = (s) => (s.done ? 'All done' : s.def.rolling ? `Now: ${s.step ? s.step.label : ''}` : `Step ${s.stepIndex + 1} of ${s.steps.length}: ${s.step ? s.step.label : ''}`);
    // ML-339: a pill per skills list (+ New list), then the list's skills - name and where you're up to
    // (ML-341: no step strip or buttons - sessions do the practising).
    function renderSkills() {
        const box = document.getElementById('skillsList');
        if (!box) return;
        const list = currentSkillList();
        const pills = document.getElementById('skillListPills');
        pills.innerHTML = skillLists.map(l => `<button type="button" class="filter-pill${list && l.id === list.id ? ' active' : ''}" aria-pressed="${!!list && l.id === list.id}" data-skill-list="${l.id}">${escapeHtml(l.name)}</button>`).join('')
            + '<button type="button" class="filter-pill" id="skillListNewBtn" aria-haspopup="dialog">+ New list</button>';
        pills.querySelectorAll('[data-skill-list]').forEach(b => b.addEventListener('click', () => { setSkillList(Number(b.dataset.skillList)); renderSkills(); }));
        document.getElementById('skillListNewBtn').addEventListener('click', newSkillList);
        setShown('skillListActions', !!list);
        box.innerHTML = !list ? '<p class="text-sm text-muted">No skills lists yet. Start one with + New list.</p>'
            : skillsData.length ? skillsData.map((s, i) => `
            <div class="history-item">
                <div class="grow">
                    <strong>${escapeHtml(s.def.label)}</strong><br><span class="text-sm text-muted">${escapeHtml(skillStepText(s))}</span>
                </div>
                <button type="button" class="flow-delete-btn" data-skill-remove="${i}" aria-label="Take ${escapeHtml(s.def.label)} off ${escapeHtml(list.name)}"><span class="material-symbols-outlined" aria-hidden="true">close</span></button>
            </div>`).join('') : '<p class="text-sm text-muted">No skills on this list yet. Add the ones you want to work on.</p>';
        box.querySelectorAll('[data-skill-remove]').forEach(b => b.addEventListener('click', () => {
            const keys = skillsData.map(s => s.key).filter((k, j) => j !== Number(b.dataset.skillRemove));
            saveSkillListKeys(keys);
        }));
        renderWarmupLists();
    }
    async function saveSkillListKeys(keys) {
        const list = currentSkillList();
        if (!list) return;
        try { applySkillsResponse(await API.skills.updateList(list.id, { keys })); renderSkills(); }
        catch (e) { showWarningToast('Not saved: ' + e.message); }
    }
    function newSkillList() {
        showPromptModal('Name the new skills list', '', async (name) => {
            const n = String(name || '').trim();
            if (!n) return;
            try {
                applySkillsResponse(await API.skills.createList(n, []));
                const made = skillLists[skillLists.length - 1];
                if (made) setSkillList(made.id);
                renderSkills();
            } catch (e) { showWarningToast('Not saved: ' + e.message); }
        });
    }
    document.getElementById('skillListRenameBtn')?.addEventListener('click', () => {
        const list = currentSkillList();
        if (!list) return;
        showPromptModal('Rename this list', list.name, async (name) => {
            const n = String(name || '').trim();
            if (!n || n === list.name) return;
            try { applySkillsResponse(await API.skills.updateList(list.id, { name: n })); renderSkills(); }
            catch (e) { showWarningToast('Not saved: ' + e.message); }
        });
    });
    document.getElementById('skillListDeleteBtn')?.addEventListener('click', () => {
        const list = currentSkillList();
        if (!list) return;
        showConfirmModal('Delete this list?', `"${list.name}" goes. Where you're up to on each skill is kept for your other lists.`, async () => {
            try { applySkillsResponse(await API.skills.deleteList(list.id)); if (skillLists[0]) setSkillList(skillLists[0].id); renderSkills(); }
            catch (e) { showWarningToast('Not deleted: ' + e.message); }
        }, true);
    });
    async function openSkillsView() {
        switchView('skillsView');
        renderSkills();
        await loadSkills();
        renderSkills();
    }
    // ML-351/353: a pick list - rows you tick (tapping anywhere on a row toggles its tick box), and a
    // Select all / Unselect all bar that acts only on the rows showing (the current filter/search).
    // rows: [{ key, html }]; picked: a Set of keys, kept by the caller across filter changes;
    // onChange runs after any change (to update the "Add N ..." button). barEl null = no Select all bar
    // (Theory's Clef, which always keeps one ticked).
    function renderPickList(listEl, barEl, rows, picked, onChange, emptyHtml) {
        listEl.innerHTML = rows.length ? rows.map((r, i) => `<button type="button" class="flow-choice-option level-answer pick-row" data-pick-row="${i}"><span class="material-symbols-outlined pick-row-check" aria-hidden="true"></span><span class="grow">${r.html}</span></button>`).join('') : emptyHtml;
        const sync = () => {
            listEl.querySelectorAll('[data-pick-row]').forEach(b => {
                const on = picked.has(rows[Number(b.dataset.pickRow)].key);
                b.classList.toggle('selected', on);
                b.setAttribute('aria-pressed', String(on));
                b.querySelector('.pick-row-check').textContent = on ? 'check_box' : 'check_box_outline_blank';
            });
            onChange();
        };
        listEl.querySelectorAll('[data-pick-row]').forEach(b => b.addEventListener('click', () => {
            const k = rows[Number(b.dataset.pickRow)].key;
            if (picked.has(k)) picked.delete(k); else picked.add(k);
            sync();
        }));
        if (barEl) {
            barEl.innerHTML = '<button type="button" class="btn-text" data-pick-all>Select all</button><button type="button" class="btn-text" data-pick-none>Unselect all</button>';
            setShown(barEl, rows.length > 1);
            barEl.querySelector('[data-pick-all]').addEventListener('click', () => { rows.forEach(r => picked.add(r.key)); sync(); });
            barEl.querySelector('[data-pick-none]').addEventListener('click', () => { rows.forEach(r => picked.delete(r.key)); sync(); });
        }
        sync();
    }
    const pickCountLabel = (n, word) => n ? `Add ${n} ${word}${n === 1 ? '' : 's'}` : 'Add';

    // ML-340: tick several skills, then Add. ML-338: All or Grade 1-5 - a grade shows the skills that
    // belong to it (SKILLS[k].grades). With no list yet, adding starts "My skills". ML-353: a pick list.
    // ML-595: the grade is the one Filter (a chip once chosen), opening in place inside the pop-up.
    const skillsAdd = { state: {}, picked: new Set() };
    function openSkillsAddModal() {
        skillsAdd.picked = new Set();
        closeFilterInPopup('skillsAddModal');
        renderSkillsAddModal();
        showModal('skillsAddModal');
    }
    const skillsAddOffered = () => { const have = new Set(skillsData.map(s => s.key)); return Object.keys(SKILLS).filter(k => !have.has(k) && (!SKILLS[k].feature || isFeatureEnabled(SKILLS[k].feature))
        && !(SKILLS[k].tool === 'scales' && scaleLevelsOn())); }; // ML-391: scales belong to the Scales block's Levels
    const skillsAddGroups = () => [{ key: 'grade', label: 'Grade', single: true, options: SKILL_GRADES.map(n => ({ value: String(n), label: `Grade ${n}` })) }];
    const skillsAddMatch = (k, key, v) => SKILLS[k].grades[0] <= Number(v) && Number(v) <= SKILLS[k].grades[1];
    function renderSkillsAddModal() {
        const box = document.getElementById('skillsAddOptions');
        const keys = Filters.apply(skillsAddOffered(), skillsAddGroups(), skillsAdd.state, skillsAddMatch);
        renderFilterBar({
            id: 'skillsAddFilterBar', title: 'Show skills for', allLabel: 'All grades', noun: 'skills', modal: 'skillsAddModal',
            groups: skillsAddGroups, state: () => skillsAdd.state, setState: (s) => { skillsAdd.state = s; }, items: skillsAddOffered, match: skillsAddMatch,
            shown: () => Filters.apply(skillsAddOffered(), skillsAddGroups(), skillsAdd.state, skillsAddMatch).length, total: () => skillsAddOffered().length, onChange: renderSkillsAddModal
        });
        const g = Number((skillsAdd.state.grade || [])[0] || 0);
        const gradeText = (d) => (d.grades[0] === d.grades[1] ? `Grade ${d.grades[0]}` : `Grades ${d.grades[0]}-${d.grades[1]}`);
        const rows = keys.map(k => {
            const d = SKILLS[k];
            return { key: k, html: `<strong>${escapeHtml(d.label)}</strong><br><span class="text-sm text-muted">${gradeText(d)} · ${d.rolling ? d.desc : `${d.steps().length} steps · ${d.graded ? 'moves on at grade 4 or 5' : 'you say when you\'ve got it'}`}</span>` };
        });
        renderPickList(box, document.getElementById('skillsAddPickBar'), rows, skillsAdd.picked, renderSkillsAddDone,
            `<p class="metro-help-text">${g ? `Every Grade ${g} skill is on this list already.` : 'Every skill is on this list already.'}</p>`);
    }
    function renderSkillsAddDone() {
        const n = skillsAdd.picked.size;
        const btn = document.getElementById('skillsAddDoneBtn');
        btn.disabled = !n;
        btn.textContent = pickCountLabel(n, 'skill');
    }
    document.getElementById('skillsAddDoneBtn')?.addEventListener('click', async () => {
        const add = [...skillsAdd.picked];
        if (!add.length) return;
        hideModal('skillsAddModal');
        try {
            const list = currentSkillList();
            if (list) applySkillsResponse(await API.skills.updateList(list.id, { keys: [...skillsData.map(s => s.key), ...add] }));
            else { applySkillsResponse(await API.skills.createList('My skills', add)); if (skillLists[0]) setSkillList(skillLists[0].id); }
            renderSkills();
        } catch (e) { showWarningToast('Not saved: ' + e.message); }
    });

    // ===== ML-343: warm-up lists - the standard four and your own; a session's Warm-up blocks play one =====
    let myWarmupLists = [];
    const WARMUP_LIST_STORE = 'tml.warmups.list'; // the one sessions use - per device ('std:each', 'own:12')
    let warmupListKey = (() => { try { return localStorage.getItem(WARMUP_LIST_STORE) || 'std:each'; } catch (e) { return 'std:each'; } })();
    async function loadWarmupLists() {
        try { myWarmupLists = (await API.warmupLists.list()).lists || []; } catch (e) { myWarmupLists = []; }
    }
    function allWarmupLists() {
        return [...PracticePlan.WARMUP_LISTS.map(l => ({ ...l, key: `std:${l.id}` })),
            ...myWarmupLists.map(l => ({ ...l, key: `own:${l.id}`, own: true, desc: `${l.kinds.map(k => (Warmups.KINDS.find(x => x.id === k) || {}).label || k).join(', ')}${l.random ? ', random' : ', in order'}` }))];
    }
    function currentWarmupList() { const all = allWarmupLists(); return all.find(l => l.key === warmupListKey) || all.find(l => l.key === 'std:each'); }
    function setWarmupList(key) {
        warmupListKey = key;
        try { localStorage.setItem(WARMUP_LIST_STORE, key); } catch (e) { /* per-device convenience */ }
    }
    function renderWarmupLists() {
        const box = document.getElementById('warmupListsList');
        if (!box) return;
        const cur = currentWarmupList();
        box.innerHTML = allWarmupLists().map(l => `
            <div class="history-item">
                ${l.own ? `<button type="button" class="level-row-body grow text-left" data-warmup-edit="${l.id}" aria-haspopup="dialog" aria-label="${escapeHtml(l.name)} - ${escapeHtml(l.desc)}. Edit">` : '<div class="grow">'}
                    <span><strong>${escapeHtml(l.name)}</strong>${cur && cur.key === l.key ? ' <span class="text-sm text-muted">(sessions use this)</span>' : ''}<br><span class="text-sm text-muted">${escapeHtml(l.desc)}</span></span>
                ${l.own ? '</button>' : '</div>'}
            </div>`).join('');
        box.querySelectorAll('[data-warmup-edit]').forEach(b => b.addEventListener('click', () => openWarmupListModal(Number(b.dataset.warmupEdit))));
    }
    let warmupListEditId = null;
    function openWarmupListModal(id) {
        const l = id ? myWarmupLists.find(x => x.id === id) : null;
        warmupListEditId = l ? l.id : null;
        document.getElementById('warmupListTitle').textContent = l ? 'Edit warm-up list' : 'New warm-up list';
        document.getElementById('warmupListName').value = l ? l.name : '';
        document.getElementById('warmupListKinds').innerHTML = Warmups.KINDS.map(k => `<input type="checkbox" id="warmupListKind-${k.id}" name="warmupListKinds" value="${k.id}"${!l || l.kinds.includes(k.id) ? ' checked' : ''}><label for="warmupListKind-${k.id}">${escapeHtml(k.label)}</label>`).join('');
        document.getElementById(`warmupListOrder-${l && l.random ? 'random' : 'listed'}`).checked = true;
        setShown('warmupListDeleteBtn', !!l);
        showModal('warmupListModal');
        document.getElementById('warmupListName').focus();
    }
    document.getElementById('warmupListNewBtn')?.addEventListener('click', () => openWarmupListModal(null));
    document.getElementById('warmupListCloseBtn')?.addEventListener('click', () => hideModal('warmupListModal'));
    document.getElementById('warmupListSaveBtn')?.addEventListener('click', async () => {
        const name = document.getElementById('warmupListName').value.trim();
        const kinds = [...document.querySelectorAll('input[name="warmupListKinds"]:checked')].map(x => x.value);
        if (!name) return showWarningToast('Give the list a name');
        if (!kinds.length) return showWarningToast('Choose at least one kind of warm-up');
        const body = { name, kinds, random: document.getElementById('warmupListOrder-random').checked };
        try {
            myWarmupLists = (warmupListEditId ? await API.warmupLists.update(warmupListEditId, body) : await API.warmupLists.create(body)).lists || [];
            hideModal('warmupListModal');
            renderWarmupLists();
        } catch (e) { showWarningToast('Not saved: ' + e.message); }
    });
    document.getElementById('warmupListDeleteBtn')?.addEventListener('click', () => {
        const l = myWarmupLists.find(x => x.id === warmupListEditId);
        if (!l) return;
        hideModal('warmupListModal');
        showConfirmModal('Delete this warm-up list?', `"${l.name}" goes. The warm-ups themselves stay.`, async () => {
            try { myWarmupLists = (await API.warmupLists.remove(l.id)).lists || []; if (warmupListKey === `own:${l.id}`) setWarmupList('std:each'); renderWarmupLists(); }
            catch (e) { showWarningToast('Not deleted: ' + e.message); }
        }, true);
    });
    // While a session's Warm-up block plays a list, the Warm-ups tool goes through just these exercises.
    var sessionWarmupIds = null; // var: warmupsList reads it
    // ML-390: a session's Warm-up block plays its list on a loop until the block ends - { round }.
    var sessionWarmupLoop = null;
    // Open a skill's tool at the step you're on.
    function openSkillStep(s) {
        if (!s || s.done || !s.step) return;
        skillContext = { key: s.key, stepIndex: s.stepIndex, stepId: s.step.id, tool: s.def.tool, stepCount: s.steps.length };
        const st = s.step;
        if (s.def.tool === 'tapTempo') { tapState.level = st.id; drillStore('tapTempo', tapState); switchView('tapTempoView'); }
        else if (s.def.tool === 'gapTrainer') { gapState.pattern = st.id; drillStore('gapTrainer', gapState); switchView('gapTrainerView'); }
        else if (s.def.tool === 'ear') { earState.mode = 'playback'; earState.sets.playback = st.set; drillStore('ear', earState); switchView('earView'); }
        else if (s.def.tool === 'scales') {
            switchView('scalesView');
            scales.keyId = st.id;
            scales.form = s.def.mode === 'minor' ? 'harmonic' : 'major';
            if (scales.form !== 'major') scales.minorForm = 'harmonic';
            scales.type = 'scale';
            scales.pattern = null;
            scales.tonicOctave = null; // ML-357: the usual placement, not one a grade list chose
            scales.extended = null;
            scalesChanged();
        } else if (s.def.tool === 'rhythm') {
            rhythmState.set = s.def.set;
            rhythmState.pattern = st.id;
            drillStore('rhythm', rhythmState);
            switchView('rhythmView');
        } else if (s.def.tool === 'range') {
            rangeState.direction = s.def.direction;
            rangeStore();
            switchView('rangeView');
        } else if (s.def.tool === 'warmups') {
            skillWarmupsKind = s.def.kind;
            warmups.currentId = st.id;
            switchView('warmupsView');
        }
        showSuccessToast(`${s.def.label}: ${st.label}`);
    }
    async function recordSkillStep(s, passed, grade) {
        try {
            const out = await API.skills.result({ key: s.key, stepIndex: s.stepIndex, passed, grade, stepCount: s.steps.length });
            if (out.queued) { showSuccessToast(out.message); return (skillsData || []).find(x => x.key === s.key) || null; } // ML-220
            applySkillsResponse({ skills: out.skills });
            const now = skillsData.find(x => x.key === s.key);
            if (passed) showSuccessToast(now && now.done ? `${s.def.label}: all steps done` : `${s.def.label}: on to ${now && now.step ? now.step.label : 'the next step'}`);
            renderSkills();
            return now;
        } catch (e) {
            showWarningToast('Not saved: ' + e.message);
            return null;
        }
    }
    // A drill round was saved: if it's the skill step you're on, grade 4+ passes it.
    function skillDrillSaved(tool, level, grade) {
        const c = skillContext;
        if (!c || c.tool !== tool || c.stepId !== level) return;
        const s = skillsData.find(x => x.key === c.key) || { key: c.key, stepIndex: c.stepIndex, steps: new Array(c.stepCount), def: SKILLS[c.key] };
        const passed = grade >= SKILL_PASS_GRADE;
        recordSkillStep({ ...s, stepIndex: c.stepIndex }, passed, grade).then(now => {
            if (practiceRun && practiceRun.blocks[practiceRun.index] && practiceRun.blocks[practiceRun.index].skill) practiceRun.blocks[practiceRun.index].skillRated = true;
            if (passed && now && !now.done && now.step) skillContext = { key: now.key, stepIndex: now.stepIndex, stepId: now.step.id, tool: now.def.tool, stepCount: now.steps.length };
            else if (passed) skillContext = null;
        });
        if (!passed) showSuccessToast(`Grade ${grade} - a 4 or 5 moves you on to the next step.`);
    }
    // Warm-ups / Scales at the end of a Skills block: "Got it?" (then on to the next block).
    function askSkillRating(s, then) {
        document.getElementById('skillRateTitle').textContent = `${s.def.label}: got it?`;
        document.getElementById('skillRateSub').textContent = s.step ? s.step.label : '';
        const next = s.steps[s.stepIndex + 1];
        document.getElementById('skillRateNext').textContent = next ? `Next time: ${next.label}` : 'That\'s the last step';
        const done = (passed) => { hideModal('skillRateModal'); (passed === null ? Promise.resolve() : recordSkillStep(s, passed, null)).then(() => then && then()); };
        document.getElementById('skillRateYesBtn').onclick = () => done(true);
        document.getElementById('skillRateNoBtn').onclick = () => done(false);
        document.getElementById('skillRateCloseBtn').onclick = () => done(null);
        showModal('skillRateModal');
    }
    document.getElementById('skillsAddBtn')?.addEventListener('click', openSkillsAddModal);
    document.getElementById('skillsAddCloseBtn')?.addEventListener('click', () => hideModal('skillsAddModal'));

    // ===== ML-320 follow-up: your own session templates - "plans" since ML-390 (made in Build my plan) =====
    let sessTemplates = [];
    async function loadTemplates() {
        try { sessTemplates = (await API.practice.templates()).templates || []; } catch (e) { sessTemplates = []; }
        return sessTemplates;
    }

    // ===== ML-320 follow-up: a running session carries on after a reload, or on another device =====
    // The runner's state is kept on the server (active_practice_sessions) whenever it changes; the
    // current block's start is by the server's clock, so the time left is right wherever you open it.
    // A session left for 3 hours or more is saved as it stood (the block you stopped in counted up to its
    // 5 minutes) and cleared.
    const PRACTICE_STALE_SECONDS = 3 * 3600;
    function practiceRunSave() {
        const r = practiceRun;
        if (!r || r.done) return;
        // ML-390: the rest (phase 'rest', timed from its own start), Keep going (open + the plan to follow)
        // and where the pieces come from are kept too. A Prepare's endless nudgeAt is kept as null.
        const state = {
            blocks: r.blocks, index: r.index, nudgeAt: Number.isFinite(r.nudgeAt) ? r.nudgeAt : null, nudged: r.nudged, startedAt: r.startedAt,
            phase: r.phase, restMessage: r.restMessage, open: !!r.open, template: r.template, focus: r.focus, auto: r.auto, source: r.source || null
        };
        API.practice.putActive({ state, blockElapsedSeconds: r.phase === 'rest' ? restElapsed() : runElapsed() }).catch(() => { /* not kept - it still runs here */ });
    }
    async function resumePracticeRun() {
        if (!isFeatureEnabled('practice_levels') || practiceRun) return;
        let active = null;
        try { active = (await API.practice.getActive()).active; } catch (e) { return; }
        if (!active || !active.state || !Array.isArray(active.state.blocks)) return;
        const st = active.state;
        if (active.idleSeconds >= PRACTICE_STALE_SECONDS) {
            const blocks = st.blocks.map((b, i) => (i === st.index ? { ...b, seconds: (b.seconds || 0) + Math.min(active.elapsedSeconds, PracticePlan.BLOCK_MINUTES * 60), started: true } : b));
            const played = blocks.filter(b => b.started && b.seconds > 0);
            API.practice.clearActive().catch(() => {});
            if (!played.length) return;
            const minutes = Math.max(1, Math.round(played.reduce((s, b) => s + b.seconds, 0) / 60));
            try {
                await API.practice.saveSession({ minutes, endedAt: new Date().toISOString(), segments: played.map(b => ({ kind: b.kind, plannedMinutes: b.minutes, actualSeconds: b.seconds, chunkId: b.chunk ? b.chunk.id : null, tool: b.kind === 'skills' ? (b.skill ? b.skill.def && b.skill.def.tool || SKILLS[b.skill.key]?.tool : b.tool) : null })) });
                showSuccessToast(`Your unfinished practice session was saved (${minutes} minutes).`);
                fetchDataAndRender();
            } catch (e) { /* nothing to save it to */ }
            return;
        }
        const at = Date.now() - active.elapsedSeconds * 1000;
        const resting = st.phase === 'rest';
        practiceRun = {
            blocks: st.blocks, index: st.index, blockStart: resting ? Date.now() : at, restStart: resting ? at : 0, phase: resting ? 'rest' : 'play',
            restMessage: st.restMessage || null, nudgeAt: st.nudgeAt == null ? PracticePlan.playSeconds(st.blocks, st.index) : st.nudgeAt, nudged: !!st.nudged && !resting,
            startedAt: st.startedAt, done: false, open: !!st.open, template: st.template || 'standard', focus: st.focus || 'both', auto: st.auto !== false, source: st.source || { type: 'all' }
        };
        if (timerState) { timerState.forSession = true; if (!timerState.running) practiceRun.pausedAt = Date.now(); } // ML-421: the timer that came back with it is the session's (ML-422: still paused if it was)
        loadSkills().catch(() => {}); // Skills blocks need your list (their steps, and Got it? for Warm-ups / Scales)
        sessPlan.source = practiceRun.source;
        if (practiceRun.open) refreshSessionPieces().catch(() => {}); // Keep going plans new Pieces blocks from them
        clearInterval(practiceTick);
        practiceTick = setInterval(practiceRunTick, 1000);
        renderPracticeRun();
        renderUpdateBanner(); // ML-564
        showSuccessToast(`Practice session carried on - block ${st.index + 1}${practiceRun.open ? '' : ` of ${st.blocks.length}`}. Tap the bar at the top.`);
    }

    // ===== ML-319 follow-up: band practice lists =====
    async function newPracticeList() {
        let bands = [];
        try { bands = (await API.account.getBands()).myBands || []; } catch (e) { bands = []; }
        const create = async (bandId) => {
            hideModal('plOwnerModal');
            try {
                const list = await API.practiceLists.create({ name: 'New practice list', bandId });
                await openPracticeList(list.id);
                document.getElementById('plName')?.select();
            } catch (e) { showWarningToast('List not created: ' + e.message); }
        };
        if (!bands.length) { create(null); return; }
        const box = document.getElementById('plOwnerOptions');
        box.innerHTML = [`<button type="button" class="flow-choice-option level-answer" data-owner=""><span><strong>Just me</strong><br><span class="text-sm text-muted">Only you see it</span></span></button>`,
            ...bands.map(b => `<button type="button" class="flow-choice-option level-answer" data-owner="${b.id}"><span><strong>${escapeHtml(b.name)}</strong><br><span class="text-sm text-muted">Everyone in the band will see it</span></span></button>`)].join('');
        box.querySelectorAll('[data-owner]').forEach(b => b.addEventListener('click', () => create(b.dataset.owner ? Number(b.dataset.owner) : null)));
        showModal('plOwnerModal');
    }
    document.getElementById('plOwnerCloseBtn')?.addEventListener('click', () => hideModal('plOwnerModal'));

    function flowOwnershipLabel(flow) {
        if (flow.isPublic) return 'Public';
        if (flow.ownerBandId) return 'Band';
        return 'Personal';
    }

    // Reuses the exact list container/row shape the old ad-hoc "Load from library" screen used
    // (#metroBlkSetupsList, .history-item) - just populated with Flows and opening openFlow instead
    // of openMetroBlkSetup. Duplicate/Delete are personal-flows-only for now (band/public sharing
    // makes "delete" a much bigger question - who's allowed to - that's a deliberate follow-up, not
    // an oversight), same "list-item-menu-btn + one shared floating menu" pattern as session history.
    // ML-310 / ML-329: All / Mine (your own) / one pill per band / Public, plus a title/composer search -
    // both per visit only. A band pill shows once one of its pieces is in the list.
    // ===== ML-595: FILTERS - one Filter button on every list (owner, 23 Oct 2026) =====
    // The button says how many filters are on and how many things show ("4 filters on · showing 3 of 42"); the filters
    // on are chips under it, each with an x that takes just that one off, and Clear all. Tapping it lists every way of
    // filtering in one pop-up - a group's choices are pills that wrap, a yes/no is a switch - each choice saying how
    // many it would show, and the list behind changes as you tap. Inside a pop-up (a pick list) the filters open in place
    // of the list, never as a second pop-up. The rules are public/filters.js; specs/components/filter-bar.md.
    // cfg: { id (the bar's element), title ('Show pieces'), allLabel ('All pieces'), noun ('pieces'), groups(), state(),
    //        setState(s), items() (what the groups count over), match(item, key, value), shown(), total(), onChange(),
    //        modal (the pick list's pop-up id, to open in place) }
    const filterCfgs = {};
    let filterPanelOpen = null; // { id, redraw, drawing } while a filter pop-up (or in-place panel) is showing
    const filterPlural = (n) => `${n} filter${n === 1 ? '' : 's'} on`;
    function renderFilterBar(cfg) {
        filterCfgs[cfg.id] = cfg;
        const bar = document.getElementById(cfg.id);
        if (!bar) return;
        const groups = cfg.groups();
        const state = Filters.clean(groups, cfg.state());
        const n = Filters.activeCount(groups, state);
        const showing = n ? `showing ${cfg.shown()} of ${cfg.total()}` : `showing ${cfg.total()}`;
        bar.innerHTML = `<div class="filter-bar-row">
                <button type="button" class="metroBlk-ctrl-value-btn${n ? ' metroBlk-ctrl-value-btn-on' : ''}" data-filter-open aria-haspopup="dialog" aria-label="${n ? filterPlural(n) : escapeHtml(cfg.allLabel)}, ${showing} - tap to ${n ? 'change' : 'filter'}"><span class="material-symbols-outlined" aria-hidden="true">filter_list</span><span class="filter-bar-text"><strong>${n ? filterPlural(n) : escapeHtml(cfg.allLabel)}</strong><span class="metroBlk-ctrl-value-label">${showing} · tap to ${n ? 'change' : 'filter'}</span></span></button>
                ${n ? '<button type="button" class="btn-text" data-filter-clear>Clear all</button>' : ''}
            </div>
            ${n ? `<div class="filter-bar-chips" role="group" aria-label="Filters on">${Filters.chips(groups, state).map(c => `<button type="button" class="filter-pill active filter-chip" data-filter-chip="${escapeHtml(c.group)}" data-value="${escapeHtml(c.value)}" aria-label="Take off the filter ${escapeHtml(c.label)}">${escapeHtml(c.label)}<span class="material-symbols-outlined" aria-hidden="true">close</span></button>`).join('')}</div>` : ''}`;
        bar.querySelector('[data-filter-open]').addEventListener('click', () => openFilterPanel(cfg.id));
        bar.querySelector('[data-filter-clear]')?.addEventListener('click', () => { cfg.setState({}); cfg.onChange(); });
        // the list changed under an open pop-up (it finished loading, a piece was archived): its choices and counts follow
        if (filterPanelOpen && filterPanelOpen.id === cfg.id && !filterPanelOpen.drawing) filterPanelOpen.redraw();
        bar.querySelectorAll('[data-filter-chip]').forEach(b => b.addEventListener('click', () => { cfg.setState(Filters.toggle(state, groups, b.dataset.filterChip, b.dataset.value)); cfg.onChange(); }));
    }
    // Every way of filtering: a heading and pills for a group, a switch for a yes/no (toggle: true), each choice with
    // how many it would show (a group the screen handles itself gives its own count)
    function filterPanelHtml(cfg) {
        const groups = cfg.groups();
        const state = Filters.clean(groups, cfg.state());
        const items = cfg.items();
        return groups.filter(g => g.options.length).map((g) => {
            if (g.toggle) {
                const o = g.options[0];
                const on = (state[g.key] || []).includes(o.value);
                return `<div class="display-toggle-row warmups-settings-row"><span id="flt-${cfg.id}-${g.key}">${escapeHtml(o.label)}${g.help ? `<span class="display-toggle-help">${escapeHtml(g.help)}</span>` : ''}</span><label class="toggle-switch"><input type="checkbox" data-filter-pick="${escapeHtml(g.key)}" data-value="${escapeHtml(o.value)}" aria-labelledby="flt-${cfg.id}-${g.key}"${on ? ' checked' : ''}><span class="toggle-slider"></span></label></div>`;
            }
            return `<h3 class="warmups-settings-head" id="fltg-${cfg.id}-${g.key}">${escapeHtml(g.label)}</h3><div class="filter-panel-choices" role="group" aria-labelledby="fltg-${cfg.id}-${g.key}">${g.options.map((o) => {
                const on = (state[g.key] || []).includes(o.value);
                const count = g.apply === false ? (o.count ?? '') : Filters.count(items, groups, state, cfg.match, g.key, o.value);
                return `<button type="button" class="filter-pill${on ? ' active' : ''}" data-filter-pick="${escapeHtml(g.key)}" data-value="${escapeHtml(o.value)}" aria-pressed="${on}">${on ? '<span class="material-symbols-outlined" aria-hidden="true">check</span>' : ''}${escapeHtml(o.label)} <span class="filter-pill-count">${count}</span></button>`;
            }).join('')}</div>`;
        }).join('') || '<p class="text-sm text-muted">Nothing to filter by yet.</p>';
    }
    function wireFilterPanel(box, cfg, redraw) {
        const pick = (key, value) => {
            const groups = cfg.groups();
            cfg.setState(Filters.toggle(Filters.clean(groups, cfg.state()), groups, key, value));
            cfg.onChange();
            redraw();
        };
        box.querySelectorAll('button[data-filter-pick]').forEach(b => b.addEventListener('click', () => pick(b.dataset.filterPick, b.dataset.value)));
        box.querySelectorAll('input[data-filter-pick]').forEach(b => b.addEventListener('change', () => pick(b.dataset.filterPick, b.dataset.value)));
        box.querySelector('[data-filter-clear-all]')?.addEventListener('click', () => { cfg.setState({}); cfg.onChange(); redraw(); });
    }
    const filterClearAllHtml = (cfg) => (Filters.activeCount(cfg.groups(), cfg.state()) ? '<button type="button" class="btn-text" data-filter-clear-all>Clear all</button>' : '');
    function openFilterPanel(id) {
        const cfg = filterCfgs[id];
        if (!cfg) return;
        if (cfg.modal) { openFilterInPopup(cfg); return; }
        document.getElementById('flowChoiceTitle').innerText = cfg.title;
        const inlineExtra = document.getElementById('flowChoiceInlineExtra');
        inlineExtra.classList.add('hidden-group');
        inlineExtra.innerHTML = '';
        const box = document.getElementById('flowChoiceOptions');
        const redraw = () => {
            if (!isShown(document.getElementById('flowChoiceModal')) && filterPanelOpen && filterPanelOpen.shown) { filterPanelOpen = null; return; } // closed since
            box.innerHTML = filterPanelHtml(cfg) + filterClearAllHtml(cfg);
            wireFilterPanel(box, cfg, guarded);
            document.getElementById('flowChoiceCancelBtn').textContent = `Show ${cfg.shown()} ${cfg.noun}`;
        };
        const guarded = () => { if (!filterPanelOpen) return; filterPanelOpen.drawing = true; try { redraw(); } finally { if (filterPanelOpen) filterPanelOpen.drawing = false; } };
        filterPanelOpen = { id, redraw: guarded, drawing: false, shown: false };
        guarded();
        showModal('flowChoiceModal');
        filterPanelOpen.shown = true;
    }
    // In a pick list's own pop-up: the list steps aside and the filters take its place - Done brings it back
    function openFilterInPopup(cfg) {
        const modal = document.getElementById(cfg.modal);
        const area = modal && modal.querySelector('.metroSeg-scroll-area');
        if (!area) return;
        closeFilterInPopup(cfg.modal);
        const footer = modal.querySelector('.metroSeg-sticky-footer');
        [...area.children, footer].filter(Boolean).forEach(el => { if (isShown(el)) { el.dataset.filterHid = '1'; setShown(el, false); } });
        const panel = document.createElement('div');
        panel.dataset.filterPanel = '1';
        area.appendChild(panel);
        const backTo = (modal.querySelector('h2')?.textContent || 'the list').trim();
        const redraw = () => {
            if (!panel.isConnected) { filterPanelOpen = null; return; } // closed since
            if (filterPanelOpen) filterPanelOpen.drawing = true;
            try { drawPanel(); } finally { if (filterPanelOpen) filterPanelOpen.drawing = false; }
        };
        filterPanelOpen = { id: cfg.id, redraw, drawing: false };
        const drawPanel = () => {
            panel.innerHTML = `<button type="button" class="btn-text flex-row items-center gap-sm" data-filter-back><span class="material-symbols-outlined" aria-hidden="true">arrow_back</span>${escapeHtml(backTo)}</button>
                <h2>${escapeHtml(cfg.title)}</h2>${filterPanelHtml(cfg)}${filterClearAllHtml(cfg)}
                <button type="button" class="btn-submit" data-filter-back>Done - show ${cfg.shown()}</button>`;
            wireFilterPanel(panel, cfg, redraw);
            panel.querySelectorAll('[data-filter-back]').forEach(b => b.addEventListener('click', () => closeFilterInPopup(cfg.modal)));
        };
        redraw();
        area.scrollTop = 0;
    }
    function closeFilterInPopup(modalId) {
        const modal = document.getElementById(modalId);
        if (!modal) return;
        modal.querySelectorAll('[data-filter-panel]').forEach(p => p.remove());
        modal.querySelectorAll('[data-filter-hid]').forEach(el => { delete el.dataset.filterHid; setShown(el, true); });
    }

    // The ways a list of pieces can be filtered - the same groups wherever pieces are listed. opts: { prepared, lists,
    // archived: the archived pieces (a switch - they are a different list) }. Only choices that something has are offered.
    function pieceFilterGroups(items, opts = {}) {
        const whoseKeys = new Set(items.map(flowLibraryFilterKey));
        const bands = [...whoseKeys].filter(k => k.startsWith('band:')).map(k => ({ value: k, label: flowLibraryBandNames[Number(k.slice(5))] || 'Band' })).sort((a, b) => a.label.localeCompare(b.label));
        const whose = [...(whoseKeys.has('mine') ? [{ value: 'mine', label: 'Mine' }] : []), ...bands, ...(whoseKeys.has('public') ? [{ value: 'public', label: 'Public' }] : [])];
        const has = [...(items.some(f => f.recordingCount > 0) ? [{ value: 'recording', label: 'A recording' }] : []), ...(items.some(f => f.documentCount > 0) ? [{ value: 'sheet', label: 'Sheet music' }] : [])];
        const groups = [{ key: 'whose', label: 'Whose', options: whose.length > 1 ? whose : [] }, { key: 'has', label: 'Has', options: has }];
        if (opts.prepared) groups.push({ key: 'prepared', label: 'Prepared', single: true, options: [{ value: 'yes', label: 'Prepared' }, { value: 'no', label: 'Not prepared yet' }] });
        if (opts.lists) groups.push({ key: 'list', label: 'On a practice list', options: (plCurrentLists.length ? plCurrentLists : (sessPracticeLists || [])).filter(l => items.some(f => (f.listIds || []).includes(l.id))).map(l => ({ value: String(l.id), label: l.name })) });
        if (opts.archived) groups.push({ key: 'archived', label: 'Archived', toggle: true, apply: false, help: 'Show the pieces you have archived instead', options: opts.archived.length ? [{ value: 'yes', label: 'Archived pieces', count: opts.archived.length }] : [] });
        return groups;
    }
    function pieceFilterMatch(f, key, value) {
        if (key === 'whose') return flowLibraryFilterKey(f) === value;
        if (key === 'has') return value === 'recording' ? f.recordingCount > 0 : f.documentCount > 0;
        if (key === 'prepared') return !!f.prepared === (value === 'yes');
        if (key === 'list') return (f.listIds || []).includes(Number(value));
        return true;
    }
    const pieceSearchMatch = (f, q) => !q || `${f.title || ''} ${f.composer || ''}`.toLowerCase().includes(q);

    let flowLibraryState = {};
    let flowLibraryQuery = '';
    let flowLibraryBandNames = {};
    const flowLibraryShowsArchived = () => (flowLibraryState.archived || []).includes('yes') && flowsArchivedCache.length > 0;
    async function loadFlowLibraryBandNames() {
        try {
            const bands = (await API.account.getBands()).myBands || [];
            flowLibraryBandNames = Object.fromEntries(bands.map(b => [Number(b.id), b.displayName || b.name]));
        } catch { /* the pills fall back to "Band" */ }
    }
    // " • 2 recordings" on a piece's row, when it has any (ML-489)
    const recordingCountText = (f) => (f.recordingCount > 0 ? ` &bull; ${f.recordingCount} recording${f.recordingCount === 1 ? '' : 's'}` : '');
    function flowLibraryFilterKey(f) {
        if (f.isPublic) return 'public';
        return f.ownerBandId ? 'band:' + f.ownerBandId : 'mine';
    }
    // ML-595: My music's Filter - whose, has, prepared, on a practice list, and the archived pieces (a switch: they are
    // shown instead of the others, still narrowed by the rest). Per visit only.
    const flowLibraryBase = () => (flowLibraryShowsArchived() ? flowsArchivedCache : flowsListCache);
    const flowLibraryGroups = () => pieceFilterGroups(flowLibraryBase(), { prepared: true, lists: isFeatureEnabled('practice_levels'), archived: flowsArchivedCache });
    function renderFlowLibraryFilter() {
        renderFilterBar({
            id: 'flowLibraryFilterBar', title: 'Show pieces', allLabel: 'All pieces', noun: 'pieces',
            groups: flowLibraryGroups, state: () => flowLibraryState, setState: (s) => { flowLibraryState = s; },
            items: flowLibraryBase, match: pieceFilterMatch,
            shown: () => flowLibraryVisible().length, total: () => flowsListCache.length,
            onChange: renderFlowsList
        });
    }
    document.getElementById('flowLibrarySearch')?.addEventListener('input', (e) => {
        flowLibraryQuery = e.target.value.trim().toLowerCase();
        renderFlowsList();
    });
    function flowLibraryVisible() {
        return Filters.apply(flowLibraryBase(), flowLibraryGroups(), flowLibraryState, pieceFilterMatch).filter(f => pieceSearchMatch(f, flowLibraryQuery))
        // By name, A to Z (owner, 4 Oct 2026) - not the order they were added; capitals don't matter and "Piece 2" comes before "Piece 10"
            .sort((a, b) => (a.title || '').localeCompare(b.title || '', undefined, { sensitivity: 'base', numeric: true }));
    }

    function renderFlowsList() {
        const ui = document.getElementById('metroBlkSetupsList');
        if (!ui) return;
        renderFlowLibraryFilter();
        setShown('flowBulkDeleteBtn', flowsListCache.some(flowCanDelete));
        renderFlowBulkArchiveBtn(); // ML-570
        renderMyMusicMenuBtn(); // ML-593
        if (!flowsListCache.length && !flowsArchivedCache.length) { ui.innerHTML = '<p>No pieces yet - tap "Add a piece" to make one.</p>'; return; }
        const visible = flowLibraryVisible();
        if (!visible.length) { ui.innerHTML = '<p class="text-muted">No pieces match.</p>'; return; }
        ui.innerHTML = visible.map(f => `
            <div class="history-item clickable" data-flow-library-id="${f.id}">
                <div role="button" tabindex="0" class="grow" data-act="flow-open" data-arg="${f.id}">
                    <strong>${escapeHtml(f.title)}</strong>
                    <div class="text-sm text-muted">${f.composer ? escapeHtml(f.composer) + ' &bull; ' : ''}${f.totalBars} bar${f.totalBars === 1 ? '' : 's'} &bull; ${flowOwnershipLabel(f)}${recordingCountText(f)}${flowArchivedText(f)}</div>
                </div>
                ${flowLibraryMenuItemsFor(f).length ? `<button type="button" class="list-item-menu-btn" data-flow-library-menu-btn aria-label="Options for ${escapeHtml(f.title)}" aria-haspopup="menu" aria-expanded="false"><span class="material-symbols-outlined">more_vert</span></button>` : ''}
            </div>
        `).join('');
        ui.querySelectorAll('[data-flow-library-menu-btn]').forEach(btn => {
            btn.addEventListener('click', (e) => {
                e.stopPropagation();
                const id = Number(btn.closest('[data-flow-library-id]').dataset.flowLibraryId);
                openFlowLibraryItemMenu(e.currentTarget, id);
            });
        });
    }

    // Which ⋮ menu items a library row gets: Edit wherever the server says you can edit (canEdit - your
    // own, your band's, and public pieces for a super admin, ML-310); Duplicate stays personal-only
    // (see the renderFlowsList comment); Delete is for a piece of your own or a band piece you added
    // (flowCanDelete, ML-411 - the server decides: canDelete); a public piece can be copied into your own library to change
    // it (ML-310); ML-204's Export covers band flows too, but never public library flows (the server
    // refuses those anyway - exportFlowForUser).
    // An archived piece: Play, Restore (not when it was archived for the whole band and you can't change the
    // band's music), Delete and Report - the rest come back with it.
    const flowById = (id) => flowsListCache.find(f => f.id === id) || flowsArchivedCache.find(f => f.id === id);
    const flowArchivedText = (f) => (!f.archived ? '' : ` &bull; Archived${f.archivedForAll && f.ownerBandId ? ' for the band' : ''}`);
    function flowLibraryMenuItemsFor(flow) {
        const ownership = flowOwnershipLabel(flow);
        const items = flow.totalBars > 0 ? ['Play'] : []; // ML-329
        if (flow.archived) {
            if (!flow.archivedForAll || flow.canEdit) items.push('Restore');
            if (flowCanDelete(flow)) items.push('Delete');
            if (ownership === 'Public' || ownership === 'Band') items.push('Report');
            return items;
        }
        if (flow.canEdit) items.push('Edit');
        if (ownership === 'Personal') items.push('Duplicate');
        if (flowCanDelete(flow)) items.push('Delete');
        if (ownership === 'Public' || ownership === 'Band') items.push('Copy'); // a band piece too (ML-441): your own copy to adjust
        if (ownership !== 'Public' && isFeatureEnabled('flow_export_musicxml')) items.push('Export');
        if (flow.ownerBandId && flow.isBandLeader && bandSummaryOn()) items.push('BandSummary'); // ML-581
        items.push('Archive');
        if (ownership === 'Public' || ownership === 'Band') items.push('Report'); // ML-507: anything other people can see
        return items;
    }

    // ===== ML-404: delete several pieces at once =====
    // The pieces a row's ⋮ offers Delete for: your own, and band pieces you added (ML-411 - the server
    // says which, canDelete; a super admin gets every piece of a band they're in). Never a public piece.
    // One confirmation for the lot: how many, which are on a practice list (they come off it) and which
    // are band pieces (everyone in the band loses them).
    const flowCanDelete = (f) => !!f.canDelete && !f.isPublic;
    const flowBandName = (f) => flowLibraryBandNames[Number(f.ownerBandId)] || 'your band';
    const flowBulkDelete = { picked: new Set() };
    const piecesWord = (n) => `${n} piece${n === 1 ? '' : 's'}`;
    function renderFlowBulkDeleteDone() {
        const n = flowBulkDelete.picked.size;
        const btn = document.getElementById('flowBulkDeleteDoneBtn');
        btn.disabled = !n;
        btn.textContent = n ? `Delete ${piecesWord(n)}` : 'Delete';
    }
    function openFlowBulkDelete() {
        flowBulkDelete.picked = new Set();
        const rows = flowsListCache.filter(flowCanDelete).map(f => ({
            key: f.id,
            html: `<strong>${escapeHtml(f.title)}</strong><br><span class="text-sm text-muted">${f.composer ? escapeHtml(f.composer) + ' &bull; ' : ''}${f.totalBars} bar${f.totalBars === 1 ? '' : 's'}${f.ownerBandId ? ' &bull; ' + escapeHtml(flowBandName(f)) : ''}${f.listCount ? ` &bull; on ${f.listCount} practice list${f.listCount === 1 ? '' : 's'}` : ''}</span>`
        }));
        renderPickList(document.getElementById('flowBulkDeleteOptions'), document.getElementById('flowBulkDeletePickBar'), rows, flowBulkDelete.picked, renderFlowBulkDeleteDone,
            '<p class="metro-help-text">There are no pieces here that you can delete.</p>');
        showModal('flowBulkDeleteModal');
    }
    document.getElementById('flowBulkDeleteBtn')?.addEventListener('click', openFlowBulkDelete);
    document.getElementById('flowBulkDeleteDoneBtn')?.addEventListener('click', () => {
        const flows = flowsListCache.filter(f => flowBulkDelete.picked.has(f.id) && flowCanDelete(f));
        if (!flows.length) return;
        const inBand = flows.filter(f => f.ownerBandId).length;
        const bandLine = !inBand ? '' : flows.length === 1 ? ' It is a band piece, so everyone in the band loses it and their Levels for it.'
            : ` ${inBand === 1 ? 'One is a band piece' : `${inBand} are band pieces`}, so everyone in the band loses ${inBand === 1 ? 'it and their Levels for it' : 'them and their Levels for them'}.`;
        const listed = flows.filter(f => f.listCount > 0);
        const names = listed.slice(0, 3).map(f => f.title).join(', ') + (listed.length > 3 ? ` and ${listed.length - 3} more` : '');
        const onLists = listed.length ? ` ${listed.length === 1 ? 'One is' : `${listed.length} are`} on a practice list (${names}) and will come off it.` : '';
        hideModal('flowBulkDeleteModal');
        showConfirmModal(`Delete ${piecesWord(flows.length)}`, `Delete ${flows.length === 1 ? `"${flows[0].title}"` : piecesWord(flows.length)} and all ${flows.length === 1 ? 'its' : 'their'} bars, recordings and documents?${onLists}${bandLine} This can't be undone.`, async () => {
            let done = 0;
            try {
                for (const f of flows) { await API.flows.delete(f.id); done++; }
                showSuccessToast(`${piecesWord(done)} deleted`);
            } catch (error) {
                showWarningToast(`${done ? piecesWord(done) + ' deleted, then it stopped: ' : 'Error deleting pieces: '}${error.message}`);
            }
            await loadFlowsList();
        }, true, `Delete ${piecesWord(flows.length)}`);
    });

    // ===== ML-570: archive (or bring back) several pieces at once =====
    // The pick list of Add pieces (filter by owner, search, Select all) over the pieces in My music - or, with the
    // Archived filter showing, over the archived ones that can be brought back. Archiving is for you, as from a
    // row's ⋮; band pieces you may change ask once for all of them: just me, or everyone in the band. One call
    // for the lot (each piece checked on its own), then one toast with Undo. Nothing is deleted.
    const flowBulkArchive = { restore: false, state: {}, query: '', picked: new Set() }; // ML-595: state - the one Filter
    const flowCanRestore = (f) => !f.archivedForAll || f.canEdit; // as the ⋮ menu's Restore
    const flowBulkArchiveOffered = () => (flowBulkArchive.restore ? flowsArchivedCache.filter(flowCanRestore) : flowsListCache);
    function renderFlowBulkArchiveBtn() {
        const restore = flowLibraryShowsArchived();
        const btn = document.getElementById('flowBulkArchiveBtn');
        if (!btn) return;
        document.getElementById('flowBulkArchiveText').textContent = restore ? 'Restore several pieces' : 'Archive several pieces';
        document.getElementById('flowBulkArchiveIcon').textContent = restore ? 'unarchive' : 'archive';
        setShown(btn, restore ? flowsArchivedCache.some(flowCanRestore) : flowsListCache.length > 0);
    }
    // ML-593: My music's ⋮ menu - there when it has something in it
    function renderMyMusicMenuBtn() {
        setShown('myMusicMenuBtn', ['flowBulkArchiveBtn', 'flowBulkDeleteBtn'].some(id => isShown(document.getElementById(id))));
    }
    function closeMyMusicMenu() {
        document.getElementById('myMusicMenu')?.classList.remove('show');
        document.getElementById('myMusicMenuBtn')?.setAttribute('aria-expanded', 'false');
    }
    document.addEventListener('click', closeMyMusicMenu);
    document.getElementById('myMusicMenuBtn')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const open = document.getElementById('myMusicMenu').classList.toggle('show');
        e.currentTarget.setAttribute('aria-expanded', String(open));
    });
    function openFlowBulkArchive() {
        flowBulkArchive.restore = flowLibraryShowsArchived();
        flowBulkArchive.state = {};
        flowBulkArchive.query = '';
        closeFilterInPopup('flowBulkArchiveModal');
        flowBulkArchive.picked = new Set();
        document.getElementById('flowBulkArchiveSearch').value = '';
        document.getElementById('flowBulkArchiveTitle').textContent = flowBulkArchive.restore ? 'Restore pieces' : 'Archive pieces';
        document.getElementById('flowBulkArchiveIntro').textContent = flowBulkArchive.restore
            ? 'Tick the pieces to bring back to My music.'
            : 'Tick the pieces you are done with. They leave My music until you switch on Archived pieces in its Filter - nothing is deleted, and they stay on their practice lists.';
        renderFlowBulkArchive();
        showModal('flowBulkArchiveModal');
    }
    function renderFlowBulkArchive() {
        const offered = flowBulkArchiveOffered();
        const ownerName = (key) => key === 'mine' ? 'Mine' : key === 'public' ? 'Public' : (flowLibraryBandNames[Number(key.slice(5))] || 'Band');
        const groups = () => pieceFilterGroups(flowBulkArchiveOffered(), { prepared: true });
        const filtered = () => Filters.apply(flowBulkArchiveOffered(), groups(), flowBulkArchive.state, pieceFilterMatch).filter(f => pieceSearchMatch(f, flowBulkArchive.query));
        renderFilterBar({
            id: 'flowBulkArchiveFilterBar', title: 'Show pieces', allLabel: 'All pieces', noun: 'pieces', modal: 'flowBulkArchiveModal',
            groups, state: () => flowBulkArchive.state, setState: (s) => { flowBulkArchive.state = s; }, items: flowBulkArchiveOffered,
            match: pieceFilterMatch, shown: () => filtered().length, total: () => flowBulkArchiveOffered().length, onChange: renderFlowBulkArchive
        });
        const shown = filtered()
            .sort((a, b) => (a.title || '').localeCompare(b.title || '', undefined, { sensitivity: 'base', numeric: true }));
        const rows = shown.map(f => ({ key: f.id, html: `<strong>${escapeHtml(f.title)}</strong><br><span class="text-sm text-muted">${f.composer ? escapeHtml(f.composer) + ' &bull; ' : ''}${f.totalBars} bar${f.totalBars === 1 ? '' : 's'} &bull; ${escapeHtml(ownerName(flowLibraryFilterKey(f)))}${flowArchivedText(f)}</span>` }));
        renderPickList(document.getElementById('flowBulkArchiveOptions'), document.getElementById('flowBulkArchivePickBar'), rows, flowBulkArchive.picked, renderFlowBulkArchiveDone,
            `<p class="metro-help-text">${offered.length ? 'No pieces match.' : 'There are no pieces here to choose.'}</p>`);
    }
    function renderFlowBulkArchiveDone() {
        const n = flowBulkArchive.picked.size;
        const verb = flowBulkArchive.restore ? 'Restore' : 'Archive';
        const btn = document.getElementById('flowBulkArchiveDoneBtn');
        btn.disabled = !n;
        btn.textContent = n ? `${verb} ${piecesWord(n)}` : verb;
    }
    // items: [{ id, forAll }]. Undo sends the same pieces back the other way.
    async function flowBulkSetArchived(items, archived, undoable) {
        let result;
        try {
            result = await API.flows.setArchivedMany(items, archived);
        } catch (error) {
            showWarningToast((archived ? 'Not archived: ' : 'Not brought back: ') + error.message);
            return;
        }
        await loadFlowsList();
        const done = result.done.length;
        const word = archived ? 'archived' : 'brought back';
        if (result.failed.length) {
            showWarningToast(`${done ? `${piecesWord(done)} ${word}, but ` : ''}${piecesWord(result.failed.length)} couldn't be: ${result.failed[0].error}`);
            return;
        }
        const doneIds = new Set(result.done.map(d => d.id));
        const back = items.filter(i => doneIds.has(Number(i.id)));
        if (undoable) showUndoToast(`${piecesWord(done)} ${word}`, () => flowBulkSetArchived(back, !archived, false));
        else showSuccessToast(`${piecesWord(done)} ${word}`);
    }
    document.getElementById('flowBulkArchiveBtn')?.addEventListener('click', openFlowBulkArchive);
    document.getElementById('flowBulkArchiveSearch')?.addEventListener('input', (e) => { flowBulkArchive.query = e.target.value.trim().toLowerCase(); renderFlowBulkArchive(); });
    document.getElementById('flowBulkArchiveDoneBtn')?.addEventListener('click', () => {
        const flows = flowBulkArchiveOffered().filter(f => flowBulkArchive.picked.has(f.id));
        if (!flows.length) return;
        hideModal('flowBulkArchiveModal');
        // Bringing back: a piece archived for the whole band comes back for the band when you may change it (the ⋮ menu's rule)
        if (flowBulkArchive.restore) return flowBulkSetArchived(flows.map(f => ({ id: f.id, forAll: !!(f.archivedForAll && f.canEdit) })), false, true);
        const bandOnes = new Set(flows.filter(f => f.ownerBandId && f.canEdit && !f.isPublic).map(f => f.id));
        if (!bandOnes.size) return flowBulkSetArchived(flows.map(f => ({ id: f.id, forAll: false })), true, true);
        const bands = [...new Set(flows.filter(f => bandOnes.has(f.id)).map(flowBandName))];
        const band = bands.length === 1 ? bands[0] : 'their band';
        const them = bandOnes.size === 1 ? 'it' : 'them';
        openFlowChoiceModal(`Archive ${bandOnes.size === 1 ? 'the band piece' : `the ${bandOnes.size} band pieces`} for who?`, [
            { forAll: false, html: addPieceRow('Just me', `${bandOnes.size === 1 ? 'It stays' : 'They stay'} in ${band}'s music for everyone else`) },
            { forAll: true, html: addPieceRow(bands.length === 1 ? `Everyone in ${band}` : 'Everyone in the band', `Nobody in the band sees ${them} until ${bandOnes.size === 1 ? 'it is' : 'they are'} brought back`) }
        ], (c) => flowBulkSetArchived(flows.map(f => ({ id: f.id, forAll: c.forAll && bandOnes.has(f.id) })), true, true));
    });

    let flowLibraryMenuTargetId = null;
    function openFlowLibraryItemMenu(btnEl, id) {
        flowLibraryMenuTargetId = id;
        const menu = document.getElementById('flowLibraryItemMenu');
        if (!menu) return;
        const flow = flowById(id);
        const items = flow ? flowLibraryMenuItemsFor(flow) : [];
        ['Play', 'Edit', 'Duplicate', 'Copy', 'Delete', 'Export', 'BandSummary', 'Archive', 'Restore', 'Report'].forEach(item => {
            document.getElementById('flowLibraryItemMenu' + item)?.classList.toggle('hidden-group', !items.includes(item));
        });
        menu.classList.add('show');
        const btnRect = btnEl.getBoundingClientRect();
        const menuWidth = menu.offsetWidth;
        const menuHeight = menu.offsetHeight;
        let left = btnRect.right - menuWidth;
        left = Math.max(8, Math.min(left, window.innerWidth - menuWidth - 8));
        let top = btnRect.bottom + 4;
        top = Math.min(top, window.innerHeight - menuHeight - 8);
        placeAt(menu, left, top);
    }
    function closeFlowLibraryItemMenu() {
        document.getElementById('flowLibraryItemMenu')?.classList.remove('show');
    }
    document.addEventListener('click', closeFlowLibraryItemMenu);

    // Lands on the Details tab regardless of whether this flow already has bars (unlike openFlow's
    // own tap-the-row behaviour, which sends a non-empty flow straight to Play Flow) - the whole
    // point of this menu item is to edit, not play, so it always opens the Hub first (flowEditRequestedTab,
    // same mechanism Play Flow's own 3-dot menu uses), leaving Media/Blocks a tab tap away.
    // ML-329: Play - straight to Play Flow, whether or not you can edit it.
    document.getElementById('flowLibraryItemMenuPlay')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const id = flowLibraryMenuTargetId;
        closeFlowLibraryItemMenu();
        if (id === null) return;
        currentFlowId = id;
        goToFlowPlayView(id);
    });
    document.getElementById('flowLibraryItemMenuEdit')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const id = flowLibraryMenuTargetId;
        closeFlowLibraryItemMenu();
        if (id === null) return;
        currentFlowId = id;
        flowEditMode = 'edit';
        flowEditRequestedTab = 'details';
        switchView('flowDetailsHubView');
    });
    document.getElementById('flowLibraryItemMenuDuplicate')?.addEventListener('click', async (e) => {
        e.stopPropagation();
        const id = flowLibraryMenuTargetId;
        closeFlowLibraryItemMenu();
        try {
            await API.flows.duplicate(id);
            await loadFlowsList();
            showSuccessToast('Flow duplicated');
        } catch (error) {
            showWarningToast('Error duplicating flow: ' + error.message);
        }
    });
    // ML-310: copies a public piece (details + bars, not recordings/documents) into your own library.
    async function copyFlowToMyLibrary(id) {
        try {
            const copy = await API.flows.duplicate(id);
            await loadFlowsList();
            showSuccessToast('Copied to your library as "' + copy.title + '"');
            return copy;
        } catch (error) {
            showWarningToast('Error copying piece: ' + error.message);
            return null;
        }
    }
    document.getElementById('flowLibraryItemMenuCopy')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const id = flowLibraryMenuTargetId;
        closeFlowLibraryItemMenu();
        if (id !== null) copyFlowToMyLibrary(id);
    });
    // ML-204: downloads the flow as .musicxml - fetched with the auth header (a plain link can't carry
    // one), then saved under the name the server chose (Content-Disposition's UTF-8 filename*).
    // ML-581: the band leader's summary of a band piece - numbers per bar and for the piece, never a person
    // (GET /api/flows/:id/band-summary, server/services/bandLevelsSummary.js).
    const bandSummary = { flowId: null, title: 'Band summary', bandName: 'the band', data: null };
    const levelText = (n) => String(Math.round(n * 10) / 10);
    async function openBandSummary(id) {
        const f = flowById(id);
        Object.assign(bandSummary, { flowId: id, title: f ? f.title : 'Band summary', bandName: f ? flowBandName(f) : 'the band', data: null });
        setShown('bandSummaryBody', false);
        setShown('bandSummaryNotYet', false);
        document.getElementById('bandSummarySub').textContent = 'Loading...';
        switchView('bandSummaryView');
        try {
            bandSummary.data = await API.flows.bandSummary(id);
            renderBandSummary();
        } catch (error) {
            document.getElementById('bandSummarySub').textContent = '';
            showWarningToast(error.message);
        }
    }
    function renderBandSummary() {
        const d = bandSummary.data;
        if (!d) return;
        document.getElementById('bandSummarySub').textContent = `Made from the Levels players in ${bandSummary.bandName} chose to share with the band leader - never anyone by name.`;
        setShown('bandSummaryNotYet', !d.enough);
        setShown('bandSummaryBody', d.enough);
        if (!d.enough) return;
        document.getElementById('bandSummaryPiece').textContent = `Average Level ${levelText(d.piece.avg)}, from Level ${levelText(d.piece.lo)} to Level ${levelText(d.piece.hi)}.`;
        const bars = (r) => (r.from === r.to ? `Bar ${r.from}` : `Bars ${r.from}-${r.to}`);
        document.getElementById('bandSummaryMostWork').innerHTML = d.mostWork.length
            ? d.mostWork.map(r => `<p class="mb-2"><strong>${bars(r)}</strong> - average Level ${levelText(r.avg)}</p>`).join('')
            : '<p class="metro-help-text">Every bar is at full speed.</p>';
        const map = document.getElementById('bandSummaryMap');
        map.innerHTML = d.bars.map((b, i) => {
            const label = i % 10 === 0 ? `<span class="level-map-bars" aria-hidden="true">${i + 1}<span class="level-map-bars-to"> - ${Math.min(i + 10, d.bars.length)}</span></span>` : '';
            return label + (b
                ? `<span class="band-summary-cell"><span class="band-summary-range lv-${Math.round(b.avg)}" data-lo="${b.lo}" data-hi="${b.hi}"></span><span class="band-summary-avg" data-avg="${b.avg}"></span></span>`
                : '<span class="band-summary-cell is-empty"></span>');
        }).join('');
        // (where each column's shading and line sit is only known now - custom properties the classes read)
        map.querySelectorAll('[data-lo]').forEach(el => { el.style.setProperty('--lo', el.dataset.lo); el.style.setProperty('--hi', el.dataset.hi); });
        map.querySelectorAll('[data-avg]').forEach(el => el.style.setProperty('--avg', el.dataset.avg));
        const shown = d.bars.filter(Boolean).length;
        map.setAttribute('aria-label', `Bar by bar: ${shown} of ${d.bars.length} bars have a summary${d.mostWork.length ? `; the most work is in ${d.mostWork.map(r => `${bars(r).toLowerCase()} (average Level ${levelText(r.avg)})`).join(', ')}` : ''}.`);
        document.getElementById('bandSummaryLegend').innerHTML = levelLegendHtml([[1]]);
    }
    document.getElementById('flowLibraryItemMenuBandSummary')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const id = flowLibraryMenuTargetId;
        closeFlowLibraryItemMenu();
        if (id !== null) openBandSummary(id);
    });

    document.getElementById('flowLibraryItemMenuExport')?.addEventListener('click', async (e) => {
        e.stopPropagation();
        const id = flowLibraryMenuTargetId;
        closeFlowLibraryItemMenu();
        if (id === null) return;
        try {
            const response = await fetch(API_BASE_URL + '/api/flows/' + id + '/musicxml', {
                headers: { Authorization: 'Bearer ' + auth.token }
            });
            if (!response.ok) {
                const err = await response.json().catch(() => ({}));
                throw new Error(err.error || 'Export failed (' + response.status + ')');
            }
            const disposition = response.headers.get('Content-Disposition') || '';
            const encoded = disposition.match(/filename\*=UTF-8''([^;]+)/);
            const fileName = encoded ? decodeURIComponent(encoded[1]) : 'flow.musicxml';
            const url = URL.createObjectURL(await response.blob());
            const a = document.createElement('a');
            a.href = url;
            a.download = fileName;
            document.body.appendChild(a);
            a.click();
            a.remove();
            setTimeout(() => URL.revokeObjectURL(url), 1000);
            showSuccessToast('Exported ' + fileName);
        } catch (error) {
            showWarningToast('Error exporting flow: ' + error.message);
        }
    });
    // ML-507: "Report this" - tells the owner about a piece other people can see (its recordings, documents
    // and links go with it). Always there, whatever features an account type has. The note is optional.
    // ML-510: the same pop-up reports a band's name ('band': its shared space) or a band's practice list
    // ('list') - only the words about what is sent change.
    const REPORT_WORDS = {
        piece: { why: 'it is not theirs to share, it is not suitable, or someone in a recording does not want to be', lead: '', after: ' - with its recordings and documents -' },
        band: { why: 'the name is not suitable, or is not theirs to use', lead: 'The band\'s name, ', after: ',' },
        list: { why: 'the name is not suitable, or is not theirs to use', lead: 'The practice list\'s name, ', after: ',' },
        notice: { why: 'it is not suitable, or it should not have been sent to the band', lead: 'The notice ', after: ',' } // ML-498
    };
    let reporting = null; // { kind, id }
    function openReport(kind, id, title) {
        reporting = { kind, id };
        const words = REPORT_WORDS[kind];
        document.getElementById('reportWhy').textContent = words.why;
        document.getElementById('reportLead').textContent = words.lead;
        document.getElementById('reportWhat').textContent = title;
        document.getElementById('reportWith').textContent = words.after;
        document.getElementById('reportNote').value = '';
        showModal('reportModal');
        document.getElementById('reportNote').focus();
    }
    document.getElementById('flowLibraryItemMenuReport')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const id = flowLibraryMenuTargetId;
        closeFlowLibraryItemMenu();
        const flow = flowById(id);
        if (flow) openReport('piece', id, flow.title);
    });
    // the play screen: report what you are looking at or hearing without going back to the list
    document.getElementById('flowPlayMenuReport')?.addEventListener('click', (e) => {
        e.stopPropagation();
        closeFlowPlayMenu();
        if (currentFlowDetail) openReport('piece', currentFlowDetail.id, currentFlowDetail.title);
    });
    document.getElementById('accountBandMenuReport')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const band = myBandById(accountBandMenuTargetId);
        closeAccountBandMenu();
        if (band && band.shared) openReport('band', band.shared.bandId, band.shared.name || band.displayName);
    });
    document.getElementById('plReportBtn')?.addEventListener('click', () => {
        const l = plState.list;
        if (l && l.bandId) openReport('list', l.id, l.name);
    });
    document.getElementById('reportCancelBtn')?.addEventListener('click', () => { hideModal('reportModal'); reporting = null; });
    document.getElementById('reportSendBtn')?.addEventListener('click', async () => {
        if (!reporting) return;
        const btn = document.getElementById('reportSendBtn');
        btn.disabled = true;
        try {
            await apiCall('/api/reports', 'POST', { kind: reporting.kind, id: reporting.id, note: document.getElementById('reportNote').value });
            hideModal('reportModal');
            reporting = null;
            showSuccessToast('Reported. Thank you - we will look at it.');
        } catch (error) {
            showWarningToast(error.message);
        } finally {
            btn.disabled = false;
        }
    });
    // Archive: the piece leaves every list until Archived is chosen in My music; nothing is deleted. Your own
    // piece, or a public one, is archived for you. A band's piece is archived for you too - unless you may
    // change the band's music, when you are asked: just me, or everyone in the band.
    async function flowSetArchived(flow, archived, forAll) {
        try {
            await API.flows.setArchived(flow.id, archived, forAll);
            await loadFlowsList();
            showSuccessToast(!archived ? 'Back in My music' : forAll ? `Archived for everyone in ${flowBandName(flow)}` : 'Archived - switch on Archived pieces in My music\'s Filter to see it again');
        } catch (error) {
            showWarningToast((archived ? 'Not archived: ' : 'Not brought back: ') + error.message);
        }
    }
    document.getElementById('flowLibraryItemMenuArchive')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const flow = flowById(flowLibraryMenuTargetId);
        closeFlowLibraryItemMenu();
        if (!flow) return;
        if (!(flow.ownerBandId && flow.canEdit && !flow.isPublic)) return flowSetArchived(flow, true, false);
        const band = flowBandName(flow);
        openFlowChoiceModal('Archive it for who?', [
            { forAll: false, html: addPieceRow('Just me', `It stays in ${band}'s music for everyone else`) },
            { forAll: true, html: addPieceRow(`Everyone in ${band}`, 'Nobody in the band sees it until it is brought back') }
        ], (c) => flowSetArchived(flow, true, c.forAll));
    });
    document.getElementById('flowLibraryItemMenuRestore')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const flow = flowById(flowLibraryMenuTargetId);
        closeFlowLibraryItemMenu();
        if (flow) flowSetArchived(flow, false, flow.archivedForAll && flow.canEdit);
    });
    document.getElementById('flowLibraryItemMenuDelete')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const id = flowLibraryMenuTargetId;
        closeFlowLibraryItemMenu();
        const flow = flowById(id);
        // ML-411: a band piece goes for the whole band, so the question says so
        const message = flow && flow.ownerBandId
            ? `Delete "${flow.title}" from ${flowBandName(flow)}? Everyone in the band loses it: it comes off their practice lists and their Levels for it go too. This can't be undone.`
            : `Delete "${flow ? flow.title : 'this piece'}" and all its bars, recordings and documents? This can't be undone.`;
        showConfirmModal('Delete piece', message, async () => {
            try {
                await API.flows.delete(id);
                await loadFlowsList();
                showSuccessToast('Piece deleted');
            } catch (error) {
                showWarningToast('Error deleting piece: ' + error.message);
            }
        }, true);
    });

    // Fetches the flow's metadata + full block list together and lands on Play Flow - shared by
    // "Load from library" (below) and the Hub's own "Play flow" button/3-dot menu. currentFlowDetail
    // is refetched here rather than trusted from wherever it was last loaded, same "don't trust it's
    // still current" caution as loadAndRenderFlowDetailsHub's own fetch.
    async function goToFlowPlayView(id) {
        try {
            const [detail, blocks] = await Promise.all([API.flows.get(id), API.flows.blocks.list(id)]);
            currentFlowDetail = detail;
            flowLeadInBlock = blocks.find(b => b.isLeadIn) || null;
            currentFlowBlocks = blocks.filter(b => !b.isLeadIn);
            setShown('flowPlayMenuEditDetails', detail.canEdit);
            setShown('flowPlayMenuEditFlow', detail.canEdit);
            setShown('flowPlayMenuCopy', (!detail.canEdit && detail.isPublic) || !!detail.ownerBandId);
            setShown('flowPlayMenuReport', !!detail.isPublic || !!detail.ownerBandId); // ML-510: anything other people can see
            setShown('flowPlayMenuLevels', isFeatureEnabled('practice_levels'));
            switchView('flowPlayView');
        } catch (error) {
            showWarningToast('Error loading flow: ' + error.message);
        }
    }

    // Only sets which flow is open before deciding where to land - switchView's own flowDetailsHubView/
    // flowPlayView cases are what actually fetch and render, so returning here via the back button
    // (goBack -> switchView(..., true), never through openFlow/createAndOpenFlow again) still picks up
    // whatever changed there instead of showing a stale snapshot.
    // Selecting an existing flow from the library lands straight on Play Flow - the whole point of
    // loading one is to play already-built content. Only a flow with nothing to play yet
    // (blockCount === 0) falls back to the Hub, the same destination "Create your own" always uses
    // for a brand new flow (see createAndOpenFlow below).
    window.openFlow = function(id) {
        currentFlowId = id;
        flowEditMode = 'edit';
        const listEntry = flowById(id);
        if (listEntry && listEntry.blockCount > 0) {
            goToFlowPlayView(id);
        } else if (listEntry && !listEntry.canEdit) {
            showWarningToast('This piece has no bars yet.');
        } else {
            switchView('flowDetailsHubView');
        }
    };

    // No name required up front. ML-400: `target` is the Add a piece screen's answers - the piece is
    // made in that band (else personal) and put on that practice list. The Add a piece screen comes
    // off the back stack, so Back from the new piece doesn't land on a form that would make another.
    async function createAndOpenFlow(target = null) {
        try {
            const created = await API.flows.create(target && target.bandId ? { bandId: target.bandId } : {});
            // ML-404: what it starts as, so leaving without changing anything can take it away again
            flowCreateFresh = { id: created.id, title: created.title, blocks: JSON.stringify(await API.flows.blocks.list(created.id)) };
            addPieceTarget = target;
            await addPieceToTargetList(created.id);
            currentFlowId = created.id;
            flowEditMode = 'create';
            flowStatsPendingKind = 'create';
            if (viewStack[viewStack.length - 1] === 'addPieceView') viewStack.pop();
            switchView('flowDetailsHubView');
        } catch (error) {
            showWarningToast('Error creating flow: ' + error.message);
        }
    }
    // ML-404: "Create your own" saves the piece the moment it's tapped (a default name and one default
    // bar). Leaving the journey without naming it, changing a bar or adding anything takes it away again,
    // so backing out doesn't leave empty pieces in My music (or in a band, or on a practice list). Checked
    // twice: what's on the screen (a name still being typed counts as a change), then what the server
    // has - only a piece that still matches what it was made as is removed. An import is never removed.
    let flowCreateFresh = null; // { id, title, blocks } of the piece "Create your own" just made
    // The pieces taken away this visit. A list that was asked for before one went, and arrives after,
    // would otherwise show it again (API.flows.list drops them).
    const flowsGoneIds = new Set();
    function flowsStillThere(list) { return flowsGoneIds.size ? list.filter(f => !flowsGoneIds.has(f.id)) : list; }
    const flowDetailUntouched = (d, fresh) => d.title === fresh.title && !d.composer && !d.arranger && !d.publisher && !d.description
        && !(d.recordings || []).length && !(d.documents || []).length;
    function flowCreateLeft() {
        const fresh = flowCreateFresh;
        flowCreateFresh = null;
        if (!fresh || fresh.id !== currentFlowId || !currentFlowDetail) return;
        const typed = ['flowTitleInput', 'flowComposerInput', 'flowArrangerInput', 'flowPublisherInput', 'flowDescriptionInput'].map(id => document.getElementById(id)?.value.trim() || '');
        if (typed[0] !== fresh.title || typed.slice(1).some(Boolean) || !flowDetailUntouched(currentFlowDetail, fresh)) return;
        // It can't be come back to, so it leaves the back stack as well
        for (let i = viewStack.length - 1; i >= 0; i--) if (viewStack[i] === 'flowDetailsHubView') viewStack.splice(i, 1);
        addPieceTarget = null;
        (async () => {
            try {
                const [detail, blocks] = await Promise.all([API.flows.get(fresh.id), API.flows.blocks.list(fresh.id)]);
                if (!flowDetailUntouched(detail, fresh) || JSON.stringify(blocks) !== fresh.blocks) return;
                await API.flows.delete(fresh.id);
                flowsGoneIds.add(fresh.id);
                flowsListCache = flowsListCache.filter(f => f.id !== fresh.id);
                if (isShown(document.getElementById('metroBuilderView'))) renderFlowsList();
                showSuccessToast("Nothing was added, so the new piece wasn't kept.");
            } catch { /* it stays in My music, where it can be deleted */ }
        })();
    }
    // ML-400: the end of the Create flow journey - My music, with the new piece in the list (it used to
    // open the player). The journey's own screens come off the back stack first, so Back from My music
    // goes to wherever the journey was started from, not back into it.
    function flowCreateDone() {
        flowCreateFresh = null; // finished on purpose: it's kept
        const title = currentFlowDetail?.title || 'Your piece';
        const listName = addPieceTarget?.listName || null;
        addPieceTarget = null;
        while (['flowDetailsHubView', 'flowFromFileView', 'addPieceView'].includes(viewStack[viewStack.length - 1])) viewStack.pop();
        const back = viewStack[viewStack.length - 1] === 'metroBuilderView';
        switchView('metroBuilderView', back);
        showSuccessToast(listName ? `${title} is in My music and on ${listName}.` : `${title} is in My music.`);
    }

    // ========================================
    // FLOW AUTHORING STATS (Jira ML-199) - measures how long building a Flow actually takes, so
    // manual bar entry has a real baseline to compare a redesigned Bars tab against instead of an
    // after-the-fact impression that it feels quicker. Server side:
    // server/services/flowAuthoringStats.js; table reasoning: db/migrations/044_flow_authoring_stats.sql.
    //
    // Two rules this whole section is built around:
    //
    // 1. It measures ACTIVE time, not wall clock. The ticker below only counts a second if the page
    //    is visible AND there's been some input within the last FLOW_STATS_IDLE_THRESHOLD_SECONDS.
    //    Raw wall clock is kept too (elapsedSeconds) but it's a sanity check, never the headline -
    //    one session where the phone rang would otherwise wreck an average built from a handful of
    //    runs. Using a 1s interval rather than differencing timestamps also means a laptop suspend
    //    simply doesn't tick, which is exactly the desired behaviour and awkward to get any other way.
    //
    // 2. It must never interfere with authoring. Every request here is fire-and-forget and silent -
    //    no toasts, no thrown errors reaching a caller, no awaiting before a navigation. Losing a
    //    measurement is fine; blocking or interrupting someone building a flow is not.
    // ========================================
    const FLOW_STATS_IDLE_THRESHOLD_SECONDS = 60;
    const FLOW_STATS_HEARTBEAT_SECONDS = 15;

    // Consumed-once handoffs, same pattern as flowEditRequestedTab above: an entry point sets these
    // immediately before switchView, and the Hub's own switchView case reads and clears them. That
    // keeps "which session is this" at the entry points that actually know the answer, rather than
    // re-deriving it from flowEditMode - which stays 'create' even after you've come back from the
    // player, and would otherwise log a second 'create' row for a flow that already exists.
    let flowStatsPendingKind = null;
    let flowStatsPendingSource = null;
    let flowStats = null;

    // Classified off the short edge so rotating a phone can't reclassify it as a tablet mid-session.
    function flowStatsDeviceKind() {
        const shortEdge = Math.min(window.innerWidth, window.innerHeight);
        if (shortEdge < 600) return 'mobile';
        if (shortEdge < 900) return 'tablet';
        return 'desktop';
    }

    // Deliberately not apiCall(): that shows a "Not authenticated" toast and throws, both of which
    // are exactly wrong for a background stopwatch. Also needs `keepalive`, so the last write can
    // still go out as the page is being torn down. Swallows everything - see rule 2 above.
    async function flowStatsRequest(endpoint, method, body, keepalive = false) {
        try {
            if (!auth.isAuthenticated) return null;
            const response = await fetch(`${API_BASE_URL}${endpoint}`, {
                method,
                cache: 'no-store',
                keepalive,
                headers: {
                    'Content-Type': 'application/json',
                    ...(auth.token ? { 'Authorization': `Bearer ${auth.token}` } : {})
                },
                body: JSON.stringify(body || {})
            });
            // 204 = the flow_authoring_stats feature gate is off. No body to parse, and nothing to
            // report: not recording is a valid configuration, not a failure.
            if (!response.ok || response.status === 204) return null;
            return await response.json().catch(() => null);
        } catch {
            return null;
        }
    }

    // Starts the client-side clock immediately, before the server row exists. The row is created a
    // moment later by flowStatsRegister, once the block list has loaded and blockCountStart is
    // actually knowable - but every duration reported is computed here, so that round trip costs
    // nothing in accuracy. It only means started_at lags the "Create your own" tap by the length of
    // one fetch, which nothing reads a duration from.
    function flowStatsBegin() {
        // Defensive: the Hub re-entered while a session is somehow still live shouldn't silently
        // run two clocks. The old one is closed honestly rather than dropped.
        if (flowStats) flowStatsFinish('abandoned');
        const kind = flowStatsPendingKind || 'edit';
        const creationSource = flowStatsPendingSource || 'manual';
        flowStatsPendingKind = null;
        flowStatsPendingSource = null;
        flowStats = {
            sessionId: null,
            flowId: currentFlowId,
            kind,
            creationSource,
            startedAtMs: Date.now(),
            lastInputAtMs: Date.now(),
            activeSeconds: 0,
            barsActiveSeconds: 0,
            blocksAdded: 0,
            taps: 0,
            keys: 0,
            // A Set, not a counter: "average seconds per block" wants the number of distinct blocks
            // touched, not the number of individual field tweaks (one block can easily take a dozen
            // - bpm, bar count, time signature, a repeat flag), which would make the per-block
            // figure meaningless.
            blocksEditedIds: new Set(),
            blocksDeleted: 0,
            onBarsTab: false,
            tickHandle: null,
            heartbeatHandle: null
        };
        flowStats.tickHandle = setInterval(flowStatsTick, 1000);
        flowStats.heartbeatHandle = setInterval(() => flowStatsSync(null, false), FLOW_STATS_HEARTBEAT_SECONDS * 1000);
    }

    function flowStatsTick() {
        const s = flowStats;
        if (!s) return;
        if (document.visibilityState !== 'visible') return;
        if (Date.now() - s.lastInputAtMs > FLOW_STATS_IDLE_THRESHOLD_SECONDS * 1000) return;
        s.activeSeconds += 1;
        if (s.onBarsTab) s.barsActiveSeconds += 1;
    }

    // Capture phase, so a handler that stops propagation (the block tiles do, for swipe/drag) can't
    // make real input look like idleness. Registered once for the life of the page rather than
    // per-session - cheap, and there's no teardown to get wrong.
    ['pointerdown', 'keydown', 'wheel', 'input', 'change'].forEach(evt => {
        document.addEventListener(evt, () => {
            if (!flowStats) return;
            flowStats.lastInputAtMs = Date.now();
            if (evt === 'pointerdown') flowStats.taps += 1; // ML-424: how much work it was, not just how long
            if (evt === 'keydown') flowStats.keys += 1;
        }, { capture: true, passive: true });
    });

    function flowStatsPayload() {
        const s = flowStats;
        return {
            activeSeconds: s.activeSeconds,
            barsActiveSeconds: s.barsActiveSeconds,
            elapsedSeconds: Math.round((Date.now() - s.startedAtMs) / 1000),
            blockCountEnd: currentFlowBlocks.length,
            totalBarsEnd: currentFlowBlocks.reduce((sum, b) => sum + (b.barCount || 0), 0),
            blocksAdded: s.blocksAdded,
            blocksEdited: s.blocksEditedIds.size,
            blocksDeleted: s.blocksDeleted,
            tapCount: s.taps,
            keyCount: s.keys
        };
    }

    // Called at the end of loadAndRenderFlowDetailsHub, i.e. once the real block list is in hand.
    // A failure (or the feature being switched off) leaves sessionId null, and every later write
    // quietly no-ops - the clock keeps running harmlessly and nothing is ever reported.
    async function flowStatsRegister() {
        const s = flowStats;
        if (!s || s.sessionId) return;
        const created = await flowStatsRequest(`/api/flows/${s.flowId}/authoring-sessions`, 'POST', {
            kind: s.kind,
            creationSource: s.creationSource,
            deviceKind: flowStatsDeviceKind(),
            idleThresholdSeconds: FLOW_STATS_IDLE_THRESHOLD_SECONDS,
            blockCountStart: currentFlowBlocks.length
        });
        // Guard against the session having been finished/replaced while that request was in flight.
        if (created && flowStats === s) s.sessionId = created.id;
    }

    function flowStatsSync(outcome, keepalive) {
        const s = flowStats;
        if (!s || !s.sessionId) return;
        const body = flowStatsPayload();
        if (outcome) body.outcome = outcome;
        flowStatsRequest(`/api/flows/authoring-sessions/${s.sessionId}`, 'PUT', body, keepalive);
    }

    // Idempotent and synchronous up to the fire-and-forget write: the first call wins. That's what
    // lets the two success paths (Create's "Open player", Edit's Save) mark themselves completed
    // just before navigating, while switchView's generic leave-the-Hub hook marks everything else
    // abandoned without having to know which case it's in.
    function flowStatsFinish(outcome) {
        const s = flowStats;
        if (!s) return;
        clearInterval(s.tickHandle);
        clearInterval(s.heartbeatHandle);
        flowStatsSync(outcome, false);
        flowStats = null;
    }

    function flowStatsSetTab(tab) {
        if (flowStats) flowStats.onBarsTab = tab === 'blocks';
    }

    function flowStatsNoteBlockAdded() {
        if (flowStats) flowStats.blocksAdded += 1;
    }
    function flowStatsNoteBlockEdited(blockId) {
        if (flowStats) flowStats.blocksEditedIds.add(String(blockId));
    }
    function flowStatsNoteBlockDeleted() {
        if (flowStats) flowStats.blocksDeleted += 1;
    }

    // A closed tab or a backgrounded-then-killed mobile app has no reliable end event, so this
    // deliberately sends the numbers WITHOUT an outcome rather than guessing 'abandoned' - the user
    // may well be coming straight back (mobile fires pagehide on any app switch). The row stays
    // 'in_progress' with its seconds intact; the admin view treats a stale in_progress row as
    // abandoned, which is a reporting decision rather than a claim made here.
    window.addEventListener('pagehide', () => flowStatsSync(null, true));

    // --- ML-79 Phase 1: "Import from MusicXML" (MusicXML/.mxl) - one upload-then-parse path
    // (handleFromFileUpload) behind the dropzone. The heavy lifting (parsing, creating the
    // flow/blocks, attaching the file to Media) all happens server-side in one call
    // (API.flows.fromFile.create) - see server/routes/api.js's /flows/from-file and
    // server/services/musicXmlImport.js. ---
    let flowFromFilePendingId = null;

    function resetFlowFromFileScreen() {
        flowFromFilePendingId = null;
        document.getElementById('flowFromFileInput').value = '';
        document.getElementById('flowFromFileProgress')?.classList.add('hidden-group');
        document.getElementById('flowFromFileResult')?.classList.add('hidden-group');
        document.getElementById('flowFromFileResultWarnings')?.classList.add('hidden-group');
        document.getElementById('flowFromFileDropBtn')?.classList.remove('hidden-group');
    }

    async function handleFromFileUpload(file) {
        const progressBox = document.getElementById('flowFromFileProgress');
        const labelEl = document.getElementById('flowFromFileProgressLabel');
        const percentEl = document.getElementById('flowFromFileProgressPercent');
        const fillEl = document.getElementById('flowFromFileProgressFill');
        // Hides the picker while a file's in flight - nothing sensible happens if you tap it again
        // mid-upload, so it's out of the way rather than merely disabled.
        document.getElementById('flowFromFileDropBtn')?.classList.add('hidden-group');
        document.getElementById('flowFromFileResult')?.classList.add('hidden-group');
        labelEl.innerText = 'Uploading…';
        percentEl.innerText = '0%';
        fillEl.style.setProperty('--progress', '0%');
        progressBox.classList.remove('hidden-group');

        try {
            const blob = await uploadToStore(`flows/from-file/${(accountProfile || await API.account.get()).id}/${Date.now()}-${file.name}`, file, { // the member's own import folder
                access: 'public',
                handleUploadUrl: `${API_BASE_URL}/api/flows/from-file/upload-token`,
                onUploadProgress: (progress) => {
                    const pct = Math.round(progress.percentage);
                    percentEl.innerText = `${pct}%`;
                    fillEl.style.setProperty('--progress', `${pct}%`);
                }
            });
            // The upload's own progress has nothing to report during the parse itself (one request,
            // no incremental feedback from the server) - the bar just holds at 100% with a relabel
            // so it doesn't look stuck/finished right as the slower part actually starts.
            labelEl.innerText = 'Parsing score…';
            percentEl.innerText = '100%';
            fillEl.style.setProperty('--progress', '100%');

            const flow = await API.flows.fromFile.create({
                blobUrl: blob.url, blobPathname: blob.pathname,
                fileName: file.name, fileSizeBytes: file.size, mimeType: blob.contentType || file.type,
                bandId: addPieceTarget?.bandId || undefined // ML-400: the band chosen on Add a piece
            });
            await addPieceToTargetList(flow.id);

            flowFromFilePendingId = flow.id;
            document.getElementById('flowFromFileResultTitle').innerText = flow.title ? 'Extracted' : 'Not found';
            setShown('flowFromFileResultMedia', flow.fileKept !== false); // ML-578: a MuseScore file isn't kept
            document.getElementById('flowFromFileResultBlocks').innerText =
                `${flow.blocksSummary.count} block${flow.blocksSummary.count === 1 ? '' : 's'} detected`;
            // ML-204: whatever the reader couldn't represent exactly - listed so it can be checked on
            // the next screen, rather than discovered later during playback.
            const warnings = flow.importWarnings || [];
            document.getElementById('flowFromFileResultWarningsList').innerHTML = warnings.map(w => `<li>${escapeHtml(w)}</li>`).join('');
            document.getElementById('flowFromFileResultWarnings')?.classList.toggle('hidden-group', !warnings.length);
            progressBox.classList.add('hidden-group');
            document.getElementById('flowFromFileResult')?.classList.remove('hidden-group');
        } catch (error) {
            progressBox.classList.add('hidden-group');
            document.getElementById('flowFromFileDropBtn')?.classList.remove('hidden-group');
            showWarningToast('Error importing score: ' + error.message);
        }
    }

    document.getElementById('flowFromFileDropBtn')?.addEventListener('click', () => {
        withUploadRights(() => document.getElementById('flowFromFileInput')?.click()); // ML-278
    });
    document.getElementById('flowFromFileInput')?.addEventListener('change', (e) => {
        const file = e.target.files[0];
        e.target.value = '';
        if (file) handleFromFileUpload(file);
    });
    // ML-204: from here on an import IS a Create flow journey - the same Create mode, tabs and
    // sticky-bar buttons as "Create your own" (createAndOpenFlow), landing on Details first. The file
    // has only pre-filled the flow; the one visible difference is "Review bars >" instead of
    // "Add bars >" when the import found bars (flowCreateFromImport, updateFlowEditStickyBar).
    document.getElementById('flowFromFileContinueBtn')?.addEventListener('click', () => {
        if (!flowFromFilePendingId) return;
        currentFlowId = flowFromFilePendingId;
        flowEditMode = 'create';
        flowCreateFromImportRequested = true;
        flowFromFilePendingId = null;
        // The import screen has done its job - taken off the back stack so Back from the flow lands
        // on the Flow start screen, the same place Back from "Create your own" does.
        if (viewStack[viewStack.length - 1] === 'flowFromFileView') viewStack.pop();
        if (viewStack[viewStack.length - 1] === 'addPieceView') viewStack.pop(); // ML-400: nor on Add a piece
        // ML-199: still the flow's initial creation, just import-assisted rather than typed - so
        // kind stays 'create' and creationSource carries the difference. Keeping these in one
        // bucket would quietly drag the manual-entry baseline down towards import speed.
        flowStatsPendingKind = 'create';
        flowStatsPendingSource = 'from_file';
        switchView('flowDetailsHubView');
    });

    function formatFlowDate(dateStr) {
        if (!dateStr) return '–';
        const d = new Date(dateStr);
        const months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
        return `${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()}`;
    }

    // --- Edit Flow tabs (Details/Media/Blocks) ---
    // Just show/hide panels + active-tab styling - no data fetching here, so it's safe to call
    // before loadAndRenderFlowDetailsHub's own fetch resolves (switchView's flowDetailsHubView case
    // does exactly that, so the right panel is visible immediately even while the network request
    // is still in flight).
    let flowEditActiveTab = 'details';
    function setFlowEditTab(tab) {
        flowEditActiveTab = tab;
        // ML-199: bars_active_seconds only accumulates while this is the Bars tab - see the stats
        // section above for why bar entry is measured separately from the journey as a whole.
        flowStatsSetTab(tab);
        document.getElementById('flowEditTabDetailsBtn')?.classList.toggle('active', tab === 'details');
        document.getElementById('flowEditTabMediaBtn')?.classList.toggle('active', tab === 'media');
        document.getElementById('flowEditTabBlocksBtn')?.classList.toggle('active', tab === 'blocks');
        document.getElementById('flowEditTabDetailsBtn')?.setAttribute('aria-selected', String(tab === 'details'));
        document.getElementById('flowEditTabMediaBtn')?.setAttribute('aria-selected', String(tab === 'media'));
        document.getElementById('flowEditTabBlocksBtn')?.setAttribute('aria-selected', String(tab === 'blocks'));
        const detailsPanel = document.getElementById('flowEditDetailsTab');
        const mediaPanel = document.getElementById('flowEditMediaTab');
        const blocksPanel = document.getElementById('flowEditBlocksTab');
        setShown(detailsPanel, tab === 'details');
        setShown(mediaPanel, tab === 'media');
        setShown(blocksPanel, tab === 'blocks');
        updateFlowEditStickyBar();
    }
    // Guards leaving the Details tab (via a tab click or the sticky bar button) on an empty flow
    // name - same "required" rule the field itself already enforces on blur (wireFlowMetadataField),
    // just also blocking navigation so an empty name doesn't silently carry through to Media/Blocks.
    // Only meaningful for Create mode's guided chain - Edit mode has no chain to gate (tabs are
    // freely switchable there; the name is validated once, at Save time - see saveFlowEdit).
    function flowNameRequiredToLeaveDetails() {
        if (flowEditMode === 'edit' || flowEditActiveTab !== 'details') return true;
        const nameEl = document.getElementById('flowTitleInput');
        if (nameEl && nameEl.value.trim()) return true;
        showWarningToast('Enter a flow name first.');
        nameEl?.focus();
        return false;
    }
    // One pinned sticky bottom bar shared across all 3 tabs (app.html) instead of a separate
    // in-flow button at the end of each tab's own content. Its contents swap by *mode*, not just by
    // tab: Create mode is the guided Details->Bars->Media chain - one primary button shared across
    // all 3 tabs (label/action swaps with the active tab), plus a secondary "Add media" button that
    // only appears on the Bars tab, alongside the primary "Open player", as a second optional path
    // straight from Bars to Media. Edit mode replaces both of those with a fixed Cancel/Save row +
    // Delete link, shown identically regardless of which tab is active. Re-run on every
    // setFlowEditTab call, and separately from renderFlowBlocksStudio whenever Create mode's
    // "nothing to play yet" gate might have changed (a bar added/removed while already on the Bars
    // tab, not just on arrival).
    function updateFlowEditStickyBar() {
        const createBarActions = document.getElementById('flowEditCreateBarActions');
        const primaryBtn = document.getElementById('flowEditStickyActionBtn');
        const secondaryBtn = document.getElementById('flowEditStickySecondaryBtn');
        const saveBarActions = document.getElementById('flowEditSaveBarActions');
        if (!createBarActions || !primaryBtn || !secondaryBtn || !saveBarActions) return;

        if (flowEditMode === 'edit') {
            createBarActions.classList.add('hidden-group');
            saveBarActions.classList.remove('hidden-group');
            return;
        }

        createBarActions.classList.remove('hidden-group');
        saveBarActions.classList.add('hidden-group');
        if (flowEditActiveTab === 'details') {
            secondaryBtn.classList.add('hidden-group');
            const reviewing = flowCreateFromImport && (currentFlowBlocks.length > 0 || !!flowLeadInBlock);
            primaryBtn.innerHTML = `${reviewing ? 'Review bars' : 'Add bars'} <span class="btn-nav-arrow">&gt;</span>`;
            primaryBtn.classList.remove('hidden-group');
        } else if (flowEditActiveTab === 'blocks') {
            secondaryBtn.classList.remove('hidden-group');
            primaryBtn.innerHTML = 'Done'; // ML-400: ends on My music, not the player
            // Same "nothing to play yet" gate as before - a lead-in alone still isn't playable.
            primaryBtn.classList.toggle('hidden-group', currentFlowBlocks.length === 0);
        } else {
            secondaryBtn.classList.add('hidden-group');
            primaryBtn.innerHTML = 'Done';
            primaryBtn.classList.toggle('hidden-group', currentFlowBlocks.length === 0);
        }
    }
    document.getElementById('flowEditTabDetailsBtn')?.addEventListener('click', () => setFlowEditTab('details'));
    document.getElementById('flowEditTabMediaBtn')?.addEventListener('click', () => { if (flowNameRequiredToLeaveDetails()) setFlowEditTab('media'); });
    document.getElementById('flowEditTabBlocksBtn')?.addEventListener('click', () => { if (flowNameRequiredToLeaveDetails()) setFlowEditTab('blocks'); });
    document.getElementById('flowEditStickySecondaryBtn')?.addEventListener('click', () => setFlowEditTab('media'));
    document.getElementById('flowEditStickyActionBtn')?.addEventListener('click', () => {
        if (flowEditActiveTab === 'details') {
            if (flowNameRequiredToLeaveDetails()) setFlowEditTab('blocks');
        } else if (currentFlowId) {
            // ML-199: this is the "through to the Play option" end point the ticket asks for -
            // marked completed BEFORE switchView, so the leave-the-Hub hook in there finds the
            // session already closed rather than recording it as abandoned.
            flowReviewBeforeLeaving(() => {
                flowStatsFinish('completed');
                flowCreateDone();
            }, 'Finish anyway');
        }
    });
    // Cancel needs no *server* revert - in Edit mode nothing is written to the server until Save
    // (see the Details/Media/Blocks sections below). But the in-memory currentFlowDetail/
    // currentFlowBlocks/flowLeadInBlock were mutated directly while staging the draft (same objects
    // other views read from without refetching - e.g. flowPlayView's own switchView case rebuilds
    // its queue straight off currentFlowBlocks), so those still need restoring from the snapshot
    // before leaving, or a cancelled add/edit would still show up wherever you land next. Exactly
    // a full restore of name/segments.
    document.getElementById('flowEditCancelBtn')?.addEventListener('click', () => {
        if (flowEditSnapshot && currentFlowDetail) {
            currentFlowDetail.title = flowEditSnapshot.title;
            currentFlowDetail.composer = flowEditSnapshot.composer;
            currentFlowDetail.arranger = flowEditSnapshot.arranger;
            currentFlowDetail.publisher = flowEditSnapshot.publisher;
            currentFlowDetail.description = flowEditSnapshot.description;
            currentFlowDetail.recordings = flowEditSnapshot.recordings;
            currentFlowDetail.documents = flowEditSnapshot.documents;
            flowLeadInBlock = flowEditSnapshot.leadIn;
            currentFlowBlocks = flowEditSnapshot.blocks;
        }
        flowEditSnapshot = null;
        goBack();
    });

    // Media's tab count is recordings (audio + YouTube) plus documents together - Blocks' is the
    // playable block count (lead-in excluded, same convention as everywhere else it's counted).
    function updateFlowEditTabCounts() {
        const recordings = currentFlowDetail?.recordings || [];
        const documents = currentFlowDetail?.documents || [];
        const mediaCountEl = document.getElementById('flowEditTabMediaCount');
        if (mediaCountEl) mediaCountEl.innerText = `(${recordings.length + documents.length})`;
        const blocksCountEl = document.getElementById('flowEditTabBlocksCount');
        if (blocksCountEl) blocksCountEl.innerText = `(${currentFlowBlocks.length})`;
    }

    // The single entry point into Edit Flow - see openFlow's own comment for why fetching lives here
    // rather than at each caller. Fetches the flow's metadata AND its block list together (unlike the
    // old separate Hub/Blocks Studio views) since Blocks is just a tab away now, not a fresh navigation.
    async function loadAndRenderFlowDetailsHub() {
        if (!currentFlowId) return;
        try {
            const [detail, blocks] = await Promise.all([API.flows.get(currentFlowId), API.flows.blocks.list(currentFlowId)]);
            currentFlowDetail = detail;
            flowLeadInBlock = blocks.find(b => b.isLeadIn) || null;
            currentFlowBlocks = blocks.filter(b => !b.isLeadIn);
            flowCheckActive = false; // ML-248: a fresh editing session starts without the review's outlines
            // Edit mode only - Create mode has no Cancel to revert to, so nothing to stage. Shallow
            // clone per item (not a deep JSON clone) is enough: every mutation below reassigns
            // fields/arrays rather than mutating one in place, so the snapshot's own references never
            // get touched by later edits - same reasoning metroBuilderView's own
            // an edit snapshot relies on.
            flowEditSnapshot = flowEditMode === 'edit' ? {
                title: currentFlowDetail.title, composer: currentFlowDetail.composer, arranger: currentFlowDetail.arranger,
                publisher: currentFlowDetail.publisher, description: currentFlowDetail.description,
                recordings: (currentFlowDetail.recordings || []).map(r => ({ ...r })),
                documents: (currentFlowDetail.documents || []).map(d => ({ ...d })),
                leadIn: flowLeadInBlock ? { ...flowLeadInBlock } : null,
                blocks: currentFlowBlocks.map(b => ({ ...b }))
            } : null;
            renderFlowDetailsHub();
            renderFlowBlocksStudio();
            // ML-199: deliberately after the block list has landed - block_count_start is only
            // knowable now, and an edit session that starts from 8 bars is a different measurement
            // from one that starts from 1.
            flowStatsRegister();
        } catch (error) {
            showWarningToast('Error loading flow: ' + error.message);
        }
    }

    function renderFlowDetailsHub() {
        const f = currentFlowDetail;
        if (!f) return;
        // A brand new flow already arrives with a real, ready-to-keep name (the server computes a
        // unique "Untitled"/"Untitled 1"/... via getUniqueDefaultFlowName) - shown verbatim, not
        // blanked out, so there's something sensible here even if the user never touches this field.
        document.getElementById('flowTitleInput').value = f.title || '';
        document.getElementById('flowComposerInput').value = f.composer || '';
        document.getElementById('flowArrangerInput').value = f.arranger || '';
        document.getElementById('flowPublisherInput').value = f.publisher || '';
        document.getElementById('flowDescriptionInput').value = f.description || '';
        document.getElementById('flowUploadedPill').innerText = `Created: ${formatFlowDate(f.createdAt)}`;

        renderFlowRecordingsList();
        renderFlowDocumentsList();
        updateFlowEditTabCounts();
        renderFlowVisibility();
        loadFlowAudienceBands();
    }

    // ML-441 (was ML-310's Visibility card): who the piece is for - just me, one of my bands, or everyone - as
    // one value box that opens the choice pop-up, the same as Add a piece asks it. It changes there and then
    // (after a "sure?"), in one step whichever way it goes. Who may change it: whoever may delete the piece
    // (f.canDelete - its owner, the person who added it to the band, a super admin for a public piece); only a
    // super admin is offered Everyone. Anyone else reads it as a line of text.
    let flowAudienceBands = [];
    const flowAudienceBandName = (id) => { const b = flowAudienceBands.find(x => Number(x.id) === Number(id)); return b ? (b.displayName || b.name) : 'A band'; };
    const flowAudienceIs = (f) => (f.isPublic ? 'public' : f.ownerBandId ? `band:${f.ownerBandId}` : 'me');
    function flowAudienceChoices() {
        return [{ key: 'me', to: 'me', title: 'Just me', sub: 'Only you see it' },
            ...flowAudienceBands.map(b => ({ key: `band:${Number(b.id)}`, to: 'band', bandId: Number(b.id), title: b.displayName || b.name, sub: 'Anyone who has joined the band on this app can see and play it' })),
            ...(currentAccountIsSuperAdmin ? [{ key: 'public', to: 'public', title: 'Everyone', sub: 'Public - everyone can play it and copy it' }] : [])];
    }
    function renderFlowVisibility() {
        const f = currentFlowDetail;
        if (!f) return;
        const now = f.isPublic ? 'Everyone' : f.ownerBandId ? flowAudienceBandName(f.ownerBandId) : 'Just me';
        const canChange = !!f.canDelete && flowEditMode === 'edit' && (flowAudienceBands.length > 0 || currentAccountIsSuperAdmin || flowAudienceIs(f) !== 'me');
        setShown('flowAudienceBtn', canChange);
        setShown('flowVisibilityText', !canChange);
        document.getElementById('flowAudienceValue').innerText = now;
        document.getElementById('flowAudienceBtn').setAttribute('aria-label', `Who it's for: ${now} - tap to change`);
        document.getElementById('flowVisibilityText').innerText = now;
        document.getElementById('flowAudienceNote').innerText = f.isPublic ? 'Public - everyone can play it and copy it.'
            : f.ownerBandId ? (f.canDelete ? 'Everyone in the band can see and play it, with its recordings and documents, or copy it into their own library. Members who can change the band\'s music can change it.' : 'Everyone in the band can see and play it, with its recordings and documents, or copy it into their own library. Members who can change the band\'s music can change it. Only the person who added it to the band can change who it\'s for.')
                : 'Only you see it.';
    }
    // The bands you are in, for the box's name and the pop-up - asked for once a visit to the screen
    async function loadFlowAudienceBands() {
        try { flowAudienceBands = (await API.account.getBands()).myBands || []; } catch (e) { /* the box still works with the bands it had */ }
        renderFlowVisibility();
    }
    document.getElementById('flowAudienceBtn')?.addEventListener('click', () => {
        const f = currentFlowDetail;
        if (!f) return;
        const current = flowAudienceIs(f);
        const choices = flowAudienceChoices();
        openFlowChoiceModal('Who is it for?', choices.map(c => ({ ...c, html: addPieceRow(c.title, c.sub), selected: c.key === current })), (c) => {
            if (c.key === current) return;
            const name = '"' + f.title + '"';
            const was = f.ownerBandId && !f.isPublic ? flowAudienceBandName(f.ownerBandId) : null;
            const ask = c.to === 'public' ? [`Make ${name} public?`, 'Everyone will see it in their library and Rehearse, and can copy it.', 'Make public']
                : c.to === 'band' ? [`Give ${name} to ${c.title}?`, `Everyone in ${c.title} will be able to see and play it, including its recordings and documents, and members who can change the band's music can change it. It stays with the band if you leave. Only you can take it out again.${was ? ` ${was} won't see it any more.` : ''}`, 'Give to the band']
                    : [`Make ${name} just yours?`, f.isPublic ? 'It leaves everyone\'s library and becomes your own piece.' : `${was || 'The band'} won't see it any more.`, 'Just me'];
            showConfirmModal(ask[0], ask[1], async () => {
                try {
                    const updated = await API.flows.setAudience(f.id, c.to, c.bandId);
                    // Only the ownership fields - the rest of currentFlowDetail may hold unsaved edits.
                    currentFlowDetail = { ...currentFlowDetail, isPublic: updated.isPublic, ownerBandId: updated.ownerBandId, ownerAccountId: updated.ownerAccountId, canEdit: updated.canEdit, canDelete: updated.canDelete };
                    renderFlowVisibility();
                    rehearseRefresh();
                    showSuccessToast(c.to === 'public' ? 'Now public' : c.to === 'band' ? `Now for ${c.title}` : 'Now just yours');
                } catch (error) {
                    showWarningToast('Not changed: ' + error.message);
                }
            }, false, ask[2]);
        });
    });

    // On-blur save (no separate Save button for this card in Create mode - see the plan's own note
    // on why) - skips the request entirely when the value hasn't actually changed. In Edit mode,
    // this only ever updates currentFlowDetail locally (no API call) - saveFlowEdit sends every
    // field in one PATCH when Save is pressed; Cancel just never calls it, so nothing here needs
    // reverting on Cancel either.
    function wireFlowMetadataField(inputId, field, required) {
        const el = document.getElementById(inputId);
        if (!el) return;
        el.addEventListener('blur', async () => {
            if (!currentFlowId) return;
            const value = el.value;
            if (required && !value.trim()) {
                showWarningToast('Flow name is required.');
                el.value = currentFlowDetail?.[field] || '';
                return;
            }
            if (currentFlowDetail && currentFlowDetail[field] === value) return;
            if (flowEditMode === 'edit') {
                if (currentFlowDetail) currentFlowDetail[field] = value;
                return;
            }
            try {
                currentFlowDetail = await API.flows.update(currentFlowId, { [field]: value });
            } catch (error) {
                showWarningToast('Error saving flow: ' + error.message);
            }
        });
    }
    wireFlowMetadataField('flowTitleInput', 'title', true);
    wireFlowMetadataField('flowComposerInput', 'composer');
    wireFlowMetadataField('flowArrangerInput', 'arranger');
    wireFlowMetadataField('flowPublisherInput', 'publisher');
    wireFlowMetadataField('flowDescriptionInput', 'description');

    // --- Delete flow - a plain text link (Details tab, below Next), not the old 3-dot dropdown item.
    // Move to a band/Remove from band/Publish/Unpublish used to live in that same dropdown - they're
    // dropped for now, pending a follow-up that wires them to the Visibility card instead (see its
    // own comment in app.html); the API methods themselves (API.flows.moveToBand etc.) are
    // untouched, just nothing in this view calls them at the moment. ---
    // ML-302 follow-up: no Delete on the edit screen - a piece is deleted from My music's list (its ⋮ menu),
    // which is where pieces are managed; this screen is for editing one.

    // Edit mode's local-only recording/document rows get a string temp id (`tmp1`, `tmp2`, ...)
    // instead of a real numeric one until saveFlowEdit creates them for real - same convention as
    // flowTempBlockCounter below.
    let flowTempMediaCounter = 0;
    // Recording adds normally resolve youtubeVideoId server-side (addYouTube just takes the raw
    // url) - Edit mode stages the row locally instead, so this does that same parse client-side
    // for preview purposes only. Handles the common watch/short/embed URL shapes.
    function flowParseYouTubeId(url) {
        const match = url.match(/(?:youtube\.com\/(?:watch\?v=|embed\/|shorts\/)|youtu\.be\/)([\w-]{11})/);
        return match ? match[1] : '';
    }

    // --- Audio tracks / Video links cards (one "recordings" list from the API, split into two
    // cards by type - see the Media tab's own layout note in app.html) ---
    function flowMediaItemHtml(r, isYoutube) {
        const isVideo = !isYoutube && (r.mimeType || '').startsWith('video/');
        const icon = isYoutube ? 'smart_display' : (isVideo ? 'movie' : 'music_note');
        const meta = isYoutube ? 'YouTube video' : (r.mimeType || 'Audio/video file');
        // Inline player per row (native <audio>/<video> controls for an upload, an embedded
        // YouTube iframe for a link) rather than an "open in a new tab" button - the point of
        // this card is quick playback while looking at the rest of the flow, not a detour to
        // another tab/app for a "small set of controls" you'd get there anyway.
        // ML-312: the preview keeps to the recording's start and end too - YouTube by its own start/end
        // settings, an upload by the standard "#t=start,end" on its address.
        const clip = recordingClip(r);
        let playerHtml;
        if (isYoutube) {
            playerHtml = `<div class="flow-media-player-video"><iframe src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(r.youtubeVideoId)}${youTubeClipQuery(clip, '?')}" title="${escapeHtml(r.title)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></div>`;
        } else if (isVideo) {
            playerHtml = `<div class="flow-media-player-video"><video controls preload="metadata" src="${escapeHtml(r.blobUrl + uploadClipFragment(clip))}"></video></div>`;
        } else {
            playerHtml = `<audio class="flow-media-player-audio" controls preload="metadata" src="${escapeHtml(r.blobUrl + uploadClipFragment(clip))}"></audio>`;
        }
        // One button showing the answer, opening the pop-up that changes it ("one button, one pop-up").
        // ML-597: with the rehearsal score on it is the start, the bars and the end - one pop-up for all three, here
        // only (not on the play screen) - and under it how long each stretch takes against the piece (ML-598).
        let clipHtml = '';
        if (isFeatureEnabled('rehearsal_score')) {
            const marked = (r.marks || []).length ? FlowJourney.usableMarks(FlowJourney.journeyPlaces(currentFlowBlocks || [], recOpts(r)), r.marks).length : 0;
            const barsText = marked ? `${marked} bar${marked === 1 ? '' : 's'} marked` : 'no bars marked';
            const lines = (currentFlowBlocks || []).length ? recordingStretchLines(currentFlowBlocks, r, r.marks || [], clip) : [];
            const kept = currentFlowDetail && currentFlowDetail.speedsBeforeMatch;
            const matched = kept && kept.recordingId !== null && String(kept.recordingId) === String(r.id);
            clipHtml = `<button type="button" class="metroBlk-ctrl-value-btn w-full" data-act="rec-map" data-arg="${escapeHtml(r.id)}" aria-haspopup="dialog" aria-label="${escapeHtml(r.title)}: ${escapeHtml(FlowJourney.clipLabel(clip))}, ${barsText} - tap to change"><strong>${escapeHtml(FlowJourney.clipLabel(clip))} · ${barsText}</strong><span class="metroBlk-ctrl-value-label">start, bars and end</span></button>`
                + lines.map(l => `<p class="text-sm text-muted mt-2">${escapeHtml(l)}</p>`).join('')
                + (matched ? `<p class="text-sm mt-2">The piece's speeds are matched to this recording.</p><button type="button" class="btn-text" data-act="flow-speeds-restore">Put the original speeds back</button>` : '');
        } else if (isFeatureEnabled('recording_clip')) {
            clipHtml = `<button type="button" class="metroBlk-ctrl-value-btn w-full" data-act="flow-recording-clip" data-arg="${escapeHtml(r.id)}" aria-haspopup="dialog" aria-label="Start and end of ${escapeHtml(r.title)}: ${escapeHtml(FlowJourney.clipLabel(clip))} - tap to change"><strong>${escapeHtml(FlowJourney.clipLabel(clip))}</strong><span class="metroBlk-ctrl-value-label">start and end</span></button>`;
        }
        // ML-531: which movement it is of, for a piece in movements
        const moves = FlowJourney.movements(currentFlowBlocks || []);
        const mv = r.movementNumber && moves.length > 1 ? moves.find(m => m.number === r.movementNumber) : null;
        const movementHtml = moves.length > 1
            ? `<button type="button" class="metroBlk-ctrl-value-btn w-full mt-2" data-act="flow-recording-movement" data-arg="${escapeHtml(r.id)}" aria-haspopup="dialog" aria-label="${escapeHtml(r.title)} is of ${mv ? escapeHtml(FlowJourney.movementLabel(mv, true)) : 'the whole piece'} - tap to change"><strong>${mv ? mv.number : 'all'}</strong><span class="metroBlk-ctrl-value-label">movement</span></button>`
            : '';
        return `
            <div class="history-item flow-media-item">
                <div class="flow-media-item-top">
                    <div class="history-details">
                        <span class="flow-media-icon ${isYoutube ? 'type-youtube' : 'type-audio'}"><span class="material-symbols-outlined icon-md">${icon}</span></span>
                        <div><strong>${escapeHtml(r.title)}</strong><span>${escapeHtml(meta)}</span></div>
                    </div>
                    <button type="button" class="flow-delete-btn" data-act="flow-recording-delete" data-arg="${escapeHtml(r.id)}" aria-label="Delete ${escapeHtml(r.title)}"><span class="material-symbols-outlined">delete</span></button>
                </div>
                ${playerHtml}
                ${clipHtml}
                ${movementHtml}
            </div>
        `;
    }
    // ML-531: which movement a recording is of - the whole piece, or one movement. Its marks were made against the old
    // first bar, so a change clears them (the pop-up says so when there are any). Kept until Save in Edit, like the clip.
    function openRecordingMovementChoice(recordingId) {
        const rec = (currentFlowDetail?.recordings || []).find(x => String(x.id) === String(recordingId));
        if (!rec) return;
        const moves = FlowJourney.movements(currentFlowBlocks || []);
        const cur = rec.movementNumber || null;
        const marks = (rec.marks || []).length;
        openFlowChoiceModal(marks ? `Which movement is it of? Changing it takes off its ${marks} bar mark${marks === 1 ? '' : 's'}.` : 'Which movement is it of?', [
            { n: null, selected: !cur, html: addPieceRow('The whole piece', 'Its start is bar 1') },
            ...moves.map(m => ({ n: m.number, selected: cur === m.number, html: addPieceRow(FlowJourney.movementLabel(m, true), `Its start is bar ${m.startBar}`) }))
        ], async (opt) => {
            if ((opt.n || null) === cur) return;
            try {
                if (flowEditMode === 'edit' || typeof rec.id === 'string') {
                    currentFlowDetail.recordings = (currentFlowDetail.recordings || []).map(x => (String(x.id) === String(rec.id) ? { ...x, movementNumber: opt.n || null, marks: [] } : x));
                } else {
                    currentFlowDetail = await API.flows.recordings.setMovement(currentFlowId, rec.id, opt.n || null);
                }
                renderFlowRecordingsList();
            } catch (e) { showWarningToast('Not saved: ' + e.message); }
        });
    }

    // ===== ML-312: where a recording or video starts and ends on the piece (the rehearsal score, step A) =====
    // The file is never changed: a cut is two numbers kept beside the recording (clipStartMs, clipEndMs;
    // null = the very start / the very end). The rules are FlowJourney.cleanClip and friends, which the
    // server runs too. docs/rehearsal-score.md; specs/components/recording-clip.md.
    const recordingClip = (r) => ({ startMs: r && r.clipStartMs ? r.clipStartMs : null, endMs: r && r.clipEndMs ? r.clipEndMs : null });
    // YouTube takes whole seconds: the start rounded down and the end rounded up, so nothing is cut short.
    function youTubeClipQuery(clip, lead) {
        const parts = [];
        if (clip.startMs) parts.push(`start=${Math.floor(clip.startMs / 1000)}`);
        if (clip.endMs) parts.push(`end=${Math.ceil(clip.endMs / 1000)}`);
        return parts.length ? lead + parts.join('&') : '';
    }
    function uploadClipFragment(clip) {
        if (!clip.startMs && !clip.endMs) return '';
        const sec = (ms) => (ms / 1000).toFixed(2);
        return `#t=${sec(clip.startMs || 0)}${clip.endMs ? `,${sec(clip.endMs)}` : ''}`;
    }
    // Make an <audio>/<video> keep to a clip: go to the start when Play is pressed outside it, stop at
    // the end. clipOf is asked each time, so a change to the clip is picked up without re-wiring.
    function keepPlayerToClip(el, clipOf) {
        const check = (playing) => {
            const clip = clipOf();
            if (!clip || (!clip.startMs && !clip.endMs)) return;
            const action = FlowJourney.clipAction(clip, el.currentTime * 1000, playing);
            if (action === 'seek') el.currentTime = (clip.startMs || 0) / 1000;
            else if (action === 'stop') { el.pause(); el.currentTime = (clip.startMs || 0) / 1000; }
        };
        el.addEventListener('play', () => check(false));
        el.addEventListener('timeupdate', () => { if (!el.paused) check(true); });
    }

    // The pop-up. One recording at a time; its player is made when it opens and thrown away when it
    // closes, so nothing is left playing behind it (ML-487's lesson).
    let clipEdit = null; // { recordingId, clip: { startMs, endMs }, media: <audio>|<video>|null, yt: YT.Player|null }
    const clipPositionMs = () => {
        if (!clipEdit) return 0;
        if (clipEdit.media) return (clipEdit.media.currentTime || 0) * 1000;
        try { return (clipEdit.yt && clipEdit.yt.getCurrentTime ? clipEdit.yt.getCurrentTime() : 0) * 1000; } catch (error) { return 0; }
    };
    const clipDurationMs = () => {
        if (!clipEdit) return null;
        let seconds = 0;
        if (clipEdit.media) seconds = clipEdit.media.duration;
        else { try { seconds = clipEdit.yt && clipEdit.yt.getDuration ? clipEdit.yt.getDuration() : 0; } catch (error) { seconds = 0; } }
        return Number.isFinite(seconds) && seconds > 0 ? seconds * 1000 : null;
    };
    function clipSeekAndPlay(ms) {
        if (!clipEdit) return;
        if (clipEdit.media) { clipEdit.media.currentTime = ms / 1000; clipEdit.media.play().catch(() => { /* the browser wants a tap on the player first */ }); }
        else if (clipEdit.yt && clipEdit.yt.seekTo) { try { clipEdit.yt.seekTo(ms / 1000, true); clipEdit.yt.playVideo(); } catch (error) { /* not ready yet */ } }
    }
    function renderClipModal() {
        if (!clipEdit) return;
        const { clip } = clipEdit;
        document.getElementById('clipStartTime').textContent = clip.startMs ? FlowJourney.clockText(clip.startMs) : 'The very start';
        document.getElementById('clipEndTime').textContent = clip.endMs ? FlowJourney.clockText(clip.endMs) : 'The very end';
        document.getElementById('clipSummary').textContent = `Plays: ${FlowJourney.clipLabel(clip).toLowerCase()}.`;
        setShown(document.getElementById('clipClearBtn'), !!(clip.startMs || clip.endMs));
    }
    // From a recording's row on a piece's Media tab. In Edit the answer is kept until Save, like everything
    // else there (and always for a recording that hasn't been saved yet); otherwise it is saved at once.
    function openClipModal(recordingId) {
        const rec = (currentFlowDetail?.recordings || []).find(x => String(x.id) === String(recordingId));
        if (!rec) return;
        stopFlowEditorMedia(); // the row's own preview must not play over the pop-up's
        openClipPopup({
            ...rec, clip: recordingClip(rec),
            onSave: async (checked) => {
                if (flowEditMode === 'edit' || typeof rec.id === 'string') {
                    currentFlowDetail.recordings = (currentFlowDetail.recordings || []).map(x => (String(x.id) === String(rec.id) ? { ...x, clipStartMs: checked.startMs, clipEndMs: checked.endMs } : x));
                } else {
                    currentFlowDetail = await API.flows.recordings.setClip(currentFlowId, rec.id, { startMs: checked.startMs, endMs: checked.endMs });
                }
                renderFlowRecordingsList();
            }
        });
    }
    // The pop-up itself, for anything that can be played: r is { title, type, youtubeVideoId | blobUrl,
    // mimeType, clip, onSave(clip) }. The Recordings tool (ML-489) opens it the same way.
    function openClipPopup(r) {
        const isYoutube = r.type === 'youtube';
        const isVideo = !isYoutube && (r.mimeType || '').startsWith('video/');
        clipEdit = { clip: r.clip || { startMs: null, endMs: null }, media: null, yt: null, onSave: r.onSave };
        document.getElementById('clipModalTitle').textContent = 'Set start and end';
        document.getElementById('clipModalName').textContent = r.title;
        const host = document.getElementById('clipPlayerHost');
        if (isYoutube) {
            host.innerHTML = `<div class="flow-media-player-video"><iframe id="clipYtFrame" src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(r.youtubeVideoId)}?enablejsapi=1&amp;origin=${encodeURIComponent(location.origin)}" title="${escapeHtml(r.title)}" allow="accelerometer; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></div>`;
            const mine = clipEdit;
            ensureFlowYtApi().then((YT) => {
                const frame = document.getElementById('clipYtFrame');
                if (clipEdit !== mine || !frame) return; // closed, or another opened, before YouTube was ready
                mine.yt = new YT.Player(frame, {});
            });
        } else {
            host.innerHTML = isVideo
                ? `<div class="flow-media-player-video"><video id="clipMedia" controls preload="metadata" src="${escapeHtml(r.blobUrl)}"></video></div>`
                : `<audio id="clipMedia" class="flow-media-player-audio" controls preload="metadata" src="${escapeHtml(r.blobUrl)}"></audio>`;
            clipEdit.media = document.getElementById('clipMedia');
        }
        renderClipModal();
        showModal('clipModal');
    }
    function closeClipModal() {
        if (clipEdit) {
            try { if (clipEdit.media) clipEdit.media.pause(); } catch (error) { /* nothing playing */ }
            try { if (clipEdit.yt && clipEdit.yt.destroy) clipEdit.yt.destroy(); } catch (error) { /* already gone */ }
        }
        clipEdit = null;
        document.getElementById('clipPlayerHost').innerHTML = '';
        hideModal('clipModal');
    }
    // "Starts here" / "Ends here": the mark goes where the player is now.
    function clipMarkHere(which) {
        if (!clipEdit) return;
        const at = Math.round(clipPositionMs());
        const next = { ...clipEdit.clip, [which === 'start' ? 'startMs' : 'endMs']: at };
        // A start put after the end (or an end before the start) lets go of the other mark - the one
        // just tapped is the one meant.
        if (next.startMs && next.endMs && next.endMs - next.startMs < FlowJourney.CLIP_MIN_LENGTH_MS) next[which === 'start' ? 'endMs' : 'startMs'] = null;
        const checked = FlowJourney.cleanClip(next, clipDurationMs());
        if (!checked.ok) { showWarningToast(which === 'end' && at < FlowJourney.CLIP_MIN_LENGTH_MS ? 'Play it to where the piece ends, then tap Ends here.' : checked.message); return; }
        clipEdit.clip = { startMs: checked.startMs, endMs: checked.endMs };
        renderClipModal();
    }
    function clipNudge(which, deltaMs) {
        if (!clipEdit) return;
        clipEdit.clip = FlowJourney.nudgeClip(clipEdit.clip, which, deltaMs, clipDurationMs());
        renderClipModal();
        // Hear where the mark now is: the start plays from it; the end plays its last two seconds.
        clipSeekAndPlay(which === 'start' ? (clipEdit.clip.startMs || 0) : Math.max(clipEdit.clip.startMs || 0, (clipEdit.clip.endMs || clipDurationMs() || 0) - 2000));
    }
    function clipPlayFromStart() {
        if (clipEdit) clipSeekAndPlay(clipEdit.clip.startMs || 0);
    }
    function clipClear() {
        if (!clipEdit) return;
        clipEdit.clip = { startMs: null, endMs: null };
        renderClipModal();
    }
    async function saveClipModal() {
        if (!clipEdit) return;
        const checked = FlowJourney.cleanClip(clipEdit.clip, clipDurationMs());
        if (!checked.ok) { showWarningToast(checked.message); return; }
        const { onSave } = clipEdit;
        try {
            await onSave({ startMs: checked.startMs, endMs: checked.endMs });
        } catch (error) {
            showWarningToast('That couldn\'t be saved: ' + error.message);
            return;
        }
        closeClipModal();
    }

    // ML-487: stop whatever the editor's Media tab is playing. Leaving the editor only hides it, so a
    // recording or video left playing carried on with nothing on screen to stop it. An upload is
    // paused where it is. A YouTube preview is a plain embed with no player to tell to stop (unlike
    // the play screen's, see pauseAllFlowMedia), so its frame is loaded afresh: that stops it and
    // leaves it ready to play again.
    function pauseFlowEditorUploads() {
        document.querySelectorAll('#flowAudioTracksList audio, #flowAudioTracksList video, #flowVideoLinksList video').forEach((el) => {
            try { el.pause(); } catch (error) { /* nothing was playing */ }
        });
    }
    function stopFlowEditorMedia() {
        pauseFlowEditorUploads();
        document.querySelectorAll('#flowVideoLinksList iframe').forEach((frame) => {
            frame.setAttribute('src', frame.getAttribute('src'));
        });
    }
    // ML-579: putting a stored file on a piece - free on a band's piece (the server checks who may change it),
    // on your own pieces with "Files on a piece" (Premium). The server refuses it too (assertCanAddFiles).
    function pieceFilesAllowed() { return !!(currentFlowDetail && currentFlowDetail.ownerBandId) || isFeatureEnabled('piece_files'); }
    function showPieceFileButtons() {
        const allowed = pieceFilesAllowed();
        setShown('flowUploadRecordingBtn', allowed);
        setShown('flowRecordingFilesNote', !allowed);
        setShown('flowUploadDocumentBtn', allowed);
        setShown('flowDocumentFilesNote', !allowed);
    }
    function renderFlowRecordingsList() {
        showPieceFileButtons();
        // A player taken off the page while playing carries on with nothing to stop it (ML-487)
        pauseFlowEditorUploads();
        const recordings = currentFlowDetail?.recordings || [];
        const audioTracks = recordings.filter(r => r.type !== 'youtube');
        const videoLinks = recordings.filter(r => r.type === 'youtube');

        const audioList = document.getElementById('flowAudioTracksList');
        const audioCountPill = document.getElementById('flowAudioTracksCountPill');
        if (audioCountPill) audioCountPill.innerText = `${audioTracks.length} file${audioTracks.length === 1 ? '' : 's'}`;
        if (audioList) audioList.innerHTML = audioTracks.length ? audioTracks.map(r => flowMediaItemHtml(r, false)).join('') : '<p class="text-muted">No audio uploaded yet.</p>';

        const videoList = document.getElementById('flowVideoLinksList');
        const videoCountPill = document.getElementById('flowVideoLinksCountPill');
        if (videoCountPill) videoCountPill.innerText = `${videoLinks.length} linked`;
        if (videoList) videoList.innerHTML = videoLinks.length ? videoLinks.map(r => flowMediaItemHtml(r, true)).join('') : '<p class="text-muted">No video linked yet.</p>';

        // ML-597: speeds matched to a recording that's no longer on the piece can still be put back - under the videos
        const kept = currentFlowDetail && currentFlowDetail.speedsBeforeMatch;
        const orphan = kept && isFeatureEnabled('rehearsal_score') && !recordings.some(r => kept.recordingId !== null && String(r.id) === String(kept.recordingId));
        if (videoList && orphan) videoList.insertAdjacentHTML('beforeend', '<p class="text-sm mt-3">The piece\'s speeds were matched to a recording that is no longer here.</p><button type="button" class="btn-text" data-act="flow-speeds-restore">Put the original speeds back</button>');

        updateFlowEditTabCounts();
    }

    window.deleteFlowRecording = function(recordingId) {
        if (!currentFlowId) return;
        showConfirmModal('Delete recording', 'Remove this recording from the flow?', async () => {
            // recordingId arrives as a string (quoted in the onclick so a temp id like "tmp3" isn't
            // a broken bare identifier) - String() both sides so a real numeric id still matches.
            if (flowEditMode === 'edit') {
                currentFlowDetail.recordings = (currentFlowDetail.recordings || []).filter(r => String(r.id) !== String(recordingId));
                renderFlowRecordingsList();
                offerSpeedsBack(recordingId, 'it has been taken off'); // ML-597
                return;
            }
            try {
                const kept = currentFlowDetail.speedsBeforeMatch; // the answer below no longer knows the recording
                currentFlowDetail = await API.flows.recordings.delete(currentFlowId, recordingId);
                renderFlowRecordingsList();
                if (kept) { currentFlowDetail.speedsBeforeMatch = currentFlowDetail.speedsBeforeMatch || kept; offerSpeedsBack(recordingId, 'it has been taken off'); }
            } catch (error) {
                showWarningToast('Error deleting recording: ' + error.message);
            }
        }, true);
    };

    document.getElementById('flowUploadRecordingBtn')?.addEventListener('click', () => {
        withUploadRights(() => document.getElementById('flowRecordingFileInput')?.click()); // ML-278
    });
    document.getElementById('flowRecordingFileInput')?.addEventListener('change', async (e) => {
        const file = e.target.files[0];
        e.target.value = '';
        if (!file || !currentFlowId || pieceFileTooBig(file)) return;
        const progressBox = document.getElementById('flowRecordingUploadProgress');
        const nameEl = document.getElementById('flowRecordingUploadName');
        const percentEl = document.getElementById('flowRecordingUploadPercent');
        const fillEl = document.getElementById('flowRecordingUploadFill');
        nameEl.innerText = file.name;
        percentEl.innerText = '0%';
        fillEl.style.setProperty('--progress', '0%');
        progressBox.classList.remove('hidden-group');
        try {
            // Goes straight from this browser to Blob storage (window.vercelBlobUpload, loaded via
            // the module script in app.html) - never through our own server, which is why the
            // separate confirm call below exists (see the upload-token route's own comment for why
            // it can't just rely on Blob's onUploadCompleted webhook).
            const blob = await uploadToStore(`flows/${currentFlowId}/recordings/${file.name}`, file, {
                access: 'public',
                // The sign-in token goes as a header (uploadToStore), not in this address (ML-574).
                handleUploadUrl: `${API_BASE_URL}/api/flows/${currentFlowId}/recordings/upload-token`,
                onUploadProgress: (progress) => {
                    const pct = Math.round(progress.percentage);
                    percentEl.innerText = `${pct}%`;
                    fillEl.style.setProperty('--progress', `${pct}%`);
                }
            });
            // The blob upload itself always happens immediately either way (it's just getting the
            // file into storage) - only "attach it to the flow" is staged in Edit mode.
            const uploaded = { blobUrl: blob.url, blobPathname: blob.pathname, fileName: file.name, fileSizeBytes: file.size, mimeType: blob.contentType || file.type };
            if (flowEditMode === 'edit') {
                currentFlowDetail.recordings = [...(currentFlowDetail.recordings || []), { id: `tmp${++flowTempMediaCounter}`, type: 'upload', title: file.name, ...uploaded }];
            } else {
                currentFlowDetail = await API.flows.recordings.addUploaded(currentFlowId, uploaded);
            }
            renderFlowRecordingsList();
            showSuccessToast('Recording uploaded');
        } catch (error) {
            showWarningToast('Error uploading recording: ' + error.message);
        } finally {
            progressBox.classList.add('hidden-group');
        }
    });

    // ML-532: the same pop-up adds a YouTube video to the Recordings tool - ytModalFor says which
    let ytModalFor = 'piece';
    function openYouTubeModal(forWhat) {
        ytModalFor = forWhat;
        const tool = forWhat === 'recordings';
        document.getElementById('flowYouTubeModalTitle').textContent = tool ? 'Add a YouTube video' : 'Add YouTube reference';
        document.getElementById('flowYouTubeSaveBtn').textContent = tool ? 'Add it to my recordings' : 'Add video to flow';
        document.getElementById('flowYouTubeUrlInput').value = '';
        document.getElementById('flowYouTubeTitleInput').value = '';
        showModal('flowYouTubeModal');
    }
    document.getElementById('flowAddYouTubeBtn')?.addEventListener('click', () => openYouTubeModal('piece'));
    document.getElementById('recordingsYouTubeBtn')?.addEventListener('click', () => openYouTubeModal('recordings'));
    document.getElementById('flowYouTubeSaveBtn')?.addEventListener('click', async () => {
        const url = document.getElementById('flowYouTubeUrlInput').value.trim();
        const title = document.getElementById('flowYouTubeTitleInput').value.trim();
        if (!url) return showWarningToast('YouTube link required.');
        if (ytModalFor === 'recordings') {
            try {
                recordingsData = await apiCall('/api/recordings/youtube', 'POST', { url, title });
                hideModal('flowYouTubeModal');
                renderRecordings();
                showSuccessToast('Added. Now give it to a piece.');
            } catch (error) { showWarningToast(error.message); }
            return;
        }
        if (!currentFlowId) return;
        try {
            if (flowEditMode === 'edit') {
                const youtubeVideoId = flowParseYouTubeId(url);
                if (!youtubeVideoId) return showWarningToast("Couldn't recognize that as a YouTube link.");
                currentFlowDetail.recordings = [...(currentFlowDetail.recordings || []), {
                    id: `tmp${++flowTempMediaCounter}`, type: 'youtube', title: title || 'YouTube video', sourceUrl: url, youtubeVideoId
                }];
            } else {
                currentFlowDetail = await API.flows.recordings.addYouTube(currentFlowId, { url, title });
            }
            hideModal('flowYouTubeModal');
            renderFlowRecordingsList();
            showSuccessToast('YouTube video added');
        } catch (error) {
            showWarningToast('Error adding YouTube video: ' + error.message);
        }
    });

    // --- Documents & scores card ---
    function renderFlowDocumentsList() {
        showPieceFileButtons();
        const list = document.getElementById('flowDocumentsList');
        const countPill = document.getElementById('flowDocumentsCountPill');
        const documents = currentFlowDetail?.documents || [];
        if (countPill) countPill.innerText = `${documents.length} file${documents.length === 1 ? '' : 's'}`;
        if (list) {
            list.innerHTML = documents.length ? documents.map(d => {
                const ext = (d.fileName.split('.').pop() || '?').toUpperCase();
                const sizeText = d.fileSizeBytes ? `${(d.fileSizeBytes / (1024 * 1024)).toFixed(1)} MB` : '';
                return `
                    <div class="history-item flow-doc-item">
                        <div class="history-details">
                            <span class="flow-doc-icon">${escapeHtml(ext.slice(0, 4))}</span>
                            <div><strong>${escapeHtml(d.fileName)}</strong><span>${sizeText}</span></div>
                        </div>
                        <div class="flow-doc-item-actions">
                            <button type="button" class="list-item-menu-btn" data-open-url="${escapeHtml(d.blobUrl)}" data-act="open-url" aria-label="View ${escapeHtml(d.fileName)}"><span class="material-symbols-outlined">visibility</span></button>
                            <button type="button" class="flow-delete-btn" data-act="flow-document-delete" data-arg="${escapeHtml(d.id)}" aria-label="Delete ${escapeHtml(d.fileName)}"><span class="material-symbols-outlined">delete</span></button>
                        </div>
                    </div>
                `;
            }).join('') : '<p class="text-muted">No documents uploaded yet.</p>';
        }
        updateFlowEditTabCounts();
    }

    window.deleteFlowDocument = function(documentId) {
        if (!currentFlowId) return;
        showConfirmModal('Delete document', 'Remove this document from the flow?', async () => {
            if (flowEditMode === 'edit') {
                currentFlowDetail.documents = (currentFlowDetail.documents || []).filter(d => String(d.id) !== String(documentId));
                renderFlowDocumentsList();
                return;
            }
            try {
                currentFlowDetail = await API.flows.documents.delete(currentFlowId, documentId);
                renderFlowDocumentsList();
            } catch (error) {
                showWarningToast('Error deleting document: ' + error.message);
            }
        }, true);
    };

    document.getElementById('flowUploadDocumentBtn')?.addEventListener('click', () => {
        withUploadRights(() => document.getElementById('flowDocumentFileInput')?.click()); // ML-278
    });
    document.getElementById('flowDocumentFileInput')?.addEventListener('change', async (e) => {
        const file = e.target.files[0];
        e.target.value = '';
        if (!file || !currentFlowId || pieceFileTooBig(file)) return;
        const progressBox = document.getElementById('flowDocumentUploadProgress');
        const nameEl = document.getElementById('flowDocumentUploadName');
        const percentEl = document.getElementById('flowDocumentUploadPercent');
        const fillEl = document.getElementById('flowDocumentUploadFill');
        nameEl.innerText = file.name;
        percentEl.innerText = '0%';
        fillEl.style.setProperty('--progress', '0%');
        progressBox.classList.remove('hidden-group');
        try {
            const blob = await uploadToStore(`flows/${currentFlowId}/documents/${file.name}`, file, {
                access: 'public',
                // The sign-in token goes as a header (uploadToStore), not in this address (ML-574).
                handleUploadUrl: `${API_BASE_URL}/api/flows/${currentFlowId}/documents/upload-token`,
                onUploadProgress: (progress) => {
                    const pct = Math.round(progress.percentage);
                    percentEl.innerText = `${pct}%`;
                    fillEl.style.setProperty('--progress', `${pct}%`);
                }
            });
            const uploaded = { blobUrl: blob.url, blobPathname: blob.pathname, fileName: file.name, fileSizeBytes: file.size, mimeType: blob.contentType || file.type };
            if (flowEditMode === 'edit') {
                currentFlowDetail.documents = [...(currentFlowDetail.documents || []), { id: `tmp${++flowTempMediaCounter}`, ...uploaded }];
            } else {
                currentFlowDetail = await API.flows.documents.add(currentFlowId, uploaded);
            }
            renderFlowDocumentsList();
            showSuccessToast('Document uploaded');
        } catch (error) {
            showWarningToast('Error uploading document: ' + error.message);
        } finally {
            progressBox.classList.add('hidden-group');
        }
    });

    // ========================================
    // BLOCKS STUDIO (Jira ML-179 Phase 2) - Full density view for score-backed Flow blocks
    // (parent_score_id on metronome_segments). The 2-col/4-col compact density views, and a
    // separate tap-to-open Block Inspector Modal for them, are a deferred follow-up - Full
    // already shows every one of the 12 parameters directly editable inline on each block's own
    // card (per the ticket's own Full-view spec), so there's nothing a modal would add here.
    // Create mode: every tile edit applies immediately (updateFlowBlock already merges partial
    // changes safely and re-validates the whole row), same as always. Edit mode: every mutation
    // below (flowUpdateBlock, create/delete/duplicate/reorder, lead-in create/delete) instead
    // stages locally with zero API calls, synced in one batch by saveFlowEdit - same
    // "stage-then-sync" pattern throughout, so Cancel needs no revert logic at all.
    // ========================================
    let currentFlowBlocks = [];
    let flowLeadInBlock = null;
    let flowBlockMenuTargetId = null;
    // ML-206/ML-208: Bars tab layout - '1' (full cards), '2' (detail tiles) or '4' (compact tiles);
    // 2 and 4 both open the bar popup. A per-device convenience, so it's remembered in localStorage
    // and falls back to '1' if that's unavailable.
    const FLOW_BAR_LAYOUT_KEY = 'flowBarLayout';
    const FLOW_BAR_LAYOUTS = ['1', '2', '4'];
    let flowBarLayout = (() => {
        try {
            const saved = localStorage.getItem(FLOW_BAR_LAYOUT_KEY);
            return FLOW_BAR_LAYOUTS.includes(saved) ? saved : '1';
        } catch (e) { return '1'; }
    })();
    let flowBarPopupBlockId = null; // the bar the popup is showing, or null when it's closed
    let flowBarDrag = null; // the 4-column grid's press-and-hold drag in progress (flowBarGridStartHold)
    let flowFermataTargetBlockId = null;
    // Which block (if any) currently has its swipe-to-delete underlay revealed - at most one at a
    // time, same as Quick Play's own qpOpenSwipeIndex. Tracked by id rather than a DOM reference
    // since renderFlowBlocksList throws every node away on each render, which resets this to null too.
    let flowOpenSwipeBlockId = null;
    // Edit mode's locally-staged blocks get a string temp id (`tmp1`, `tmp2`, ...) instead of a
    // real numeric one until saveFlowEdit creates them for real.
    let flowTempBlockCounter = 0;

    // Every optional block field, at its natural falsy/null default - exactly what a fresh
    // server-created row already looks like. Spread first so `data` (the caller's actual values)
    // always wins for whatever it sets.
    function flowDefaultBlockFields() {
        return {
            isRepeatStart: false, isRepeatEnd: false, isSectionBoundary: false, isFinalBarline: false, repeatPlayCount: null,
            repeatEndingNumbers: [], repeatEndingStartBar: null, isFirstTimeBar: false, isSecondTimeBar: false,
            introStartBarOffset: null, introStartBeatOffset: null, introEndBarOffset: null, introEndBeatOffset: null,
            rampStartBarOffset: null, rampStartBeatOffset: null, rampDurationBars: null,
            isSegno: false, isCoda: false, gotoSegno: false, gotoSegnoThenCoda: false, gotoCoda: false, gotoStartDc: false,
            gotoStartDcThenCoda: false, isFine: false, movementStart: false, movementTitle: null,
            rehearsalMark: null, rehearsalMarks: [], fermatas: [], ramps: [],
            pickupBeats: null, repeatLeadIn: false, quietSecondsBeforeLeadIn: 0, noteValue: null
        };
    }
    // Resolves the display fields (timeSignatureLabel/numerator/denominator) a locally-staged block
    // needs for rendering, off its raw timeSignatureId/accountTimeSignatureId - mirrors what the
    // server's own getBlockDtoById does via SQL join, done client-side since Edit mode stages block
    // changes locally instead of round-tripping to the server for every one. Shared by
    // buildLocalFlowBlockDto (a fresh block) and flowUpdateBlock's edit-mode branch (an existing one
    // whose time signature just changed) - both need the same re-resolution, or a picked signature
    // stays invisible/inert until the whole card rebuilds from a fresh server fetch.
    function flowResolveTimeSigFields(timeSignatureId, accountTimeSignatureId) {
        const list = timeSignatureId != null ? metroBlkTimeSigCache.public : metroBlkTimeSigCache.custom;
        const sig = list.find(t => t.id === (timeSignatureId ?? accountTimeSignatureId));
        return { timeSignatureLabel: sig ? sig.label : '', numerator: sig ? sig.numerator : 4, denominator: sig ? sig.denominator : 4 };
    }
    function buildLocalFlowBlockDto(data, existingId) {
        return {
            ...flowDefaultBlockFields(), ...data,
            id: existingId ?? `tmp${++flowTempBlockCounter}`,
            ...flowResolveTimeSigFields(data.timeSignatureId, data.accountTimeSignatureId)
        };
    }
    // Exactly the fields the block create/update API accepts, off a local (possibly draft) block
    // object - shared by saveFlowEdit's create and update calls. Field list mirrors
    // updateFlowBlock's own mergeKeys (server/services/flowBlocks.js) plus fermatas/rehearsalMarks.
    function flowBlockPayload(b) {
        return {
            barCount: b.barCount, bpm: b.bpm, isLeadIn: !!b.isLeadIn, repeatLeadIn: !!b.repeatLeadIn,
            quietSecondsBeforeLeadIn: b.quietSecondsBeforeLeadIn || 0, pickupBeats: b.pickupBeats,
            timeSignatureId: b.timeSignatureId, accountTimeSignatureId: b.accountTimeSignatureId, noteValue: b.noteValue,
            rehearsalMark: b.rehearsalMark, isRepeatStart: !!b.isRepeatStart, isRepeatEnd: !!b.isRepeatEnd,
            isSectionBoundary: !!b.isSectionBoundary, isFinalBarline: !!b.isFinalBarline, repeatPlayCount: b.repeatPlayCount,
            gotoCoda: !!b.gotoCoda, gotoStartDc: !!b.gotoStartDc, isCoda: !!b.isCoda, isSegno: !!b.isSegno,
            gotoSegno: !!b.gotoSegno, gotoSegnoThenCoda: !!b.gotoSegnoThenCoda,
            gotoStartDcThenCoda: !!b.gotoStartDcThenCoda, isFine: !!b.isFine,
            movementStart: !!b.movementStart, movementTitle: b.movementTitle || null,
            isFirstTimeBar: !!b.isFirstTimeBar, isSecondTimeBar: !!b.isSecondTimeBar,
            repeatEndingNumbers: b.repeatEndingNumbers || [], repeatEndingStartBar: b.repeatEndingStartBar ?? null,
            introStartBarOffset: b.introStartBarOffset, introStartBeatOffset: b.introStartBeatOffset,
            introEndBarOffset: b.introEndBarOffset, introEndBeatOffset: b.introEndBeatOffset,
            rampStartBarOffset: b.rampStartBarOffset, rampStartBeatOffset: b.rampStartBeatOffset, rampDurationBars: b.rampDurationBars,
            fermatas: b.fermatas || [], ramps: b.ramps || [], rehearsalMarks: b.rehearsalMarks || []
        };
    }
    // A block id read off a DOM dataset is always a string - numify it only when it's a real,
    // purely-numeric id, so a temp id (e.g. "tmp3") passes through unchanged and still compares
    // correctly (===) against b.id (a string for a draft block, a Number for a real one).
    function flowBlockIdFromDataset(raw) {
        return /^\d+$/.test(raw) ? Number(raw) : raw;
    }

    const FLOW_NOTE_VALUES = [
        { value: 'semibreve', label: 'Semibreve' },
        { value: 'minim', label: 'Minim' },
        { value: 'crotchet', label: 'Crotchet' },
        { value: 'dotted-crotchet', label: 'Dotted crotchet' },
        { value: 'quaver', label: 'Quaver' }
    ];
    const FLOW_NOTE_ABBREV = { semibreve: 'o', minim: 'h', crotchet: 'q', 'dotted-crotchet': 'q.', quaver: 'e' };

    function flowFindBlockById(id) {
        if (flowLeadInBlock && flowLeadInBlock.id === id) return flowLeadInBlock;
        return currentFlowBlocks.find(b => b.id === id);
    }

    // A rough one-pass figure: bars x the time signature's top number x beat length. It counts every
    // written beat, so compound time (6/8, 9/8, 12/8 - played in dotted beats) came out up to 3 times too
    // long: The Snowman read 30m 10s for 24m 41s of music. Now only the fallback for flowPlaySeconds.
    function flowTotalRuntimeSeconds(blocks) {
        return blocks.reduce((total, b) => total + (b.bpm && b.numerator ? (b.barCount * b.numerator * 60) / b.bpm : 0), 0);
    }
    // How long the piece - or one movement (its number) - takes as played: the journey engine's own sum
    // (FlowJourney.pieceRunSeconds - repeats, jumps, holds, rit./accel., compound time in its dotted beats),
    // the same one Prepare's run-through uses. Not the lead-in. Kept until the bars change, as the bar list
    // redraws often and asks once per movement heading.
    let flowPlaySecondsMemo = { key: '', times: new Map() };
    function flowPlaySeconds(movement) {
        const key = JSON.stringify(currentFlowBlocks);
        if (flowPlaySecondsMemo.key !== key) flowPlaySecondsMemo = { key, times: new Map() };
        const k = movement || 0;
        if (!flowPlaySecondsMemo.times.has(k)) {
            let secs;
            try { secs = FlowJourney.pieceRunSeconds(currentFlowBlocks, 100, movement || null); } catch (e) { secs = flowTotalRuntimeSeconds(currentFlowBlocks); }
            flowPlaySecondsMemo.times.set(k, secs);
        }
        return flowPlaySecondsMemo.times.get(k);
    }
    const flowTimeText = (seconds) => { const t = Math.round(seconds); return `~${Math.floor(t / 60)}m ${t % 60}s`; };

    // "Block 1"/"Block 2" never actually identified anything - the written bar range does. Lead-in
    // is excluded from the count (it isn't numbered), same convention as Play Flow's own tile
    // headline (flowStartingBarNumber's logic, inlined here since a card needs the range's end too,
    // not just its start). Recomputed on every render, so a drag reorder updates it for free.
    function flowBlockBarRange(index) {
        let start = 1;
        for (let i = 0; i < index; i++) start += currentFlowBlocks[i].barCount || 0;
        const barCount = currentFlowBlocks[index] ? (currentFlowBlocks[index].barCount || 1) : 1;
        return { start, end: start + barCount - 1 };
    }
    function flowBarRangeLabel(index) {
        const { start, end } = flowBlockBarRange(index);
        return start === end ? `Bar ${start}` : `Bars ${start} to ${end}`;
    }

    // Shared by the Blocks studio summary and the Play screen's subtitle (ML-237), so the two always
    // agree. Bar count excludes the lead-in (a count-in, not part of the piece); the runtime estimate
    // still includes it, since it does play. The piece as played (flowPlaySeconds) - repeats and jumps counted.
    function flowSummaryFigures() {
        const totalBars = currentFlowBlocks.reduce((sum, b) => sum + (b.barCount || 0), 0);
        const totalSeconds = Math.round((totalBars ? flowPlaySeconds() : 0) + (flowLeadInBlock ? flowTotalRuntimeSeconds([flowLeadInBlock]) : 0));
        return { totalBars, mins: Math.floor(totalSeconds / 60), secs: totalSeconds % 60, barsLabel: `${totalBars} bar${totalBars === 1 ? '' : 's'}` };
    }
    function renderFlowPlaySummary() {
        const el = document.getElementById('flowPlaySummary');
        if (!el) return;
        const { totalBars, mins, secs, barsLabel } = flowSummaryFigures();
        el.innerText = totalBars ? `~${mins}m ${secs}s • ${barsLabel}` : '';
    }

    function renderFlowBlocksStudio() {
        const { mins, secs, barsLabel } = flowSummaryFigures();
        document.getElementById('flowStudioSummaryText').innerText = `${barsLabel} • ~${mins}m ${secs}s total`;
        // The sticky bar's "Use flow" state (hidden-group when there's nothing to play yet) depends
        // on currentFlowBlocks, which just changed - refresh it here too, not only on tab switch.
        updateFlowEditStickyBar();
        renderFlowLeadIn();
        renderFlowBlocksList();
        updateFlowEditTabCounts();
    }

    async function flowUpdateBlock(blockId, data) {
        // ML-199: recorded here rather than at each of the many callers - this is the single funnel
        // every block field edit goes through, in both modes. Counted as a distinct block touched,
        // not per field change: see flowStatsBegin's note on why.
        flowStatsNoteBlockEdited(blockId);
        // Edit mode: merge the partial update straight onto the local object (same "merge only
        // what's present" shape the server's own updateFlowBlock does) - no API call until Save.
        if (flowEditMode === 'edit') {
            const target = flowFindBlockById(blockId);
            if (!target) return;
            Object.assign(target, data);
            // Time signature is stored as an id but displayed via derived fields resolved from the
            // catalog (flowResolveTimeSigFields) - without this, picking a signature (a preset, or a
            // custom one just created) leaves the tile showing whatever was there before, since
            // Object.assign only touched timeSignatureId/accountTimeSignatureId, not the label/
            // numerator/denominator the card actually renders.
            if (data.timeSignatureId !== undefined || data.accountTimeSignatureId !== undefined) {
                Object.assign(target, flowResolveTimeSigFields(target.timeSignatureId, target.accountTimeSignatureId));
            }
            renderFlowBlocksStudio();
            return;
        }
        try {
            const updated = await API.flows.blocks.update(blockId, data);
            if (flowLeadInBlock && flowLeadInBlock.id === blockId) {
                flowLeadInBlock = updated;
            } else {
                currentFlowBlocks = currentFlowBlocks.map(b => b.id === blockId ? updated : b);
            }
            renderFlowBlocksStudio();
        } catch (error) {
            showWarningToast('Error updating bar: ' + error.message);
        }
    }

    // --- Lead-in (ML-113): a yes/no switch. On = one full bar before bar 1; its time signature and
    // tempo always come from bar 1 (metroBlkEffectiveBlock), so there's nothing else to set. Looping
    // and rests between repeats are Rehearse's repeat control (ML-302), not part of the piece. ---
    function renderFlowLeadIn() {
        const toggle = document.getElementById('flowLeadInToggle');
        if (toggle) toggle.checked = !!flowLeadInBlock;
    }

    async function addFlowLeadIn() {
        if (!currentFlowId) return;
        const firstBlock = currentFlowBlocks[0];
        const data = {
            barCount: 1,
            bpm: firstBlock ? firstBlock.bpm : 120,
            timeSignatureId: firstBlock ? firstBlock.timeSignatureId : (metroBlkTimeSigCache.public[0] ? metroBlkTimeSigCache.public[0].id : null),
            accountTimeSignatureId: firstBlock ? firstBlock.accountTimeSignatureId : null,
            isLeadIn: true
        };
        if (flowEditMode === 'edit') {
            flowLeadInBlock = buildLocalFlowBlockDto(data);
            renderFlowBlocksStudio();
            return;
        }
        try {
            flowLeadInBlock = await API.flows.blocks.create(currentFlowId, data);
        } catch (error) {
            showWarningToast('Error adding lead-in: ' + error.message);
        }
        renderFlowBlocksStudio();
    }

    async function removeFlowLeadIn() {
        if (!flowLeadInBlock) return;
        if (flowEditMode === 'edit') {
            flowLeadInBlock = null;
            renderFlowBlocksStudio();
            return;
        }
        try {
            await API.flows.blocks.delete(flowLeadInBlock.id);
            flowLeadInBlock = null;
        } catch (error) {
            showWarningToast('Error removing lead-in: ' + error.message);
        }
        renderFlowBlocksStudio();
    }

    document.getElementById('flowLeadInToggle')?.addEventListener('change', (e) => {
        if (e.target.checked) addFlowLeadIn(); else removeFlowLeadIn();
    });

    // --- Musical symbol glyphs (segno/coda) - the real Unicode Musical Symbols characters (U+1D10B
    // Segno, U+1D10C Coda), rendered in Noto Music (loaded in app.html) rather than hand-drawn SVG -
    // a properly designed notation glyph beats an approximation, and Noto Music actually covers these
    // two codepoints (most fonts don't, which is why a webfont is loaded for them specifically instead
    // of trusting whatever's on the system). Plain currentColor-inheriting text, so it themes/sizes
    // itself for free wherever it's dropped - no separate light/dark or selected-state handling
    // needed. `inline` sizes it to sit inline with text (the jump tile's "D.<segno>"/"al <coda>"
    // labels); otherwise it's the picker's own larger glyph size. ---
    function flowSignIconSvg(kind, inline) {
        const cls = inline ? 'flow-sign-svg-inline' : 'flow-sign-svg';
        if (kind === 'segno') return `<span class="${cls}">\u{1D10B}</span>`;
        // Noto Music draws the coda glyph's own ink noticeably smaller within its character box than
        // segno's, even at an identical font-size - flow-sign-svg-coda bumps it back up to read as
        // the same visual size as segno alongside it.
        if (kind === 'coda') return `<span class="${cls} flow-sign-svg-coda">\u{1D10C}</span>`;
        return '';
    }
    // Fermata/caesura glyphs - same real-Unicode-Musical-Symbols-via-Noto-Music approach as segno/coda
    // above (U+1D110 fermata, U+1D113 caesura - the actual "//" break mark), reusing the same
    // .flow-sign-svg(-inline) classes since they're generic Noto Music glyph renderers, not
    // sign-specific despite the name.
    function flowPauseIconSvg(kind, inline) {
        const cls = inline ? 'flow-sign-svg-inline' : 'flow-sign-svg';
        if (kind === 'fermata') return `<span class="${cls}">\u{1D110}</span>`;
        if (kind === 'caesura') return `<span class="${cls}">\u{1D113}</span>`;
        return '';
    }

    // Barline glyphs - same hand-drawn SVG approach as flowSignIconSvg above, real notation rather
    // than standing in with "|"/"|:" characters. `muted` (plain barline only, used by the pickers
    // below) draws it in the same label colour as an unset tile, deliberately lighter/less bold than
    // the other options it sits next to.
    function flowBarlineIconSvg(kind, cls, muted) {
        const c = cls ? ` class="${cls}"` : '';
        if (kind === 'repeatStart') {
            // Thick line on the outside (left - the very start of the repeated section), thin line
            // just inside it, dots facing further right into the section that repeats.
            return `<svg viewBox="0 0 32 56"${c}><line x1="10" y1="6" x2="10" y2="50" stroke="currentColor" stroke-width="5"/><line x1="18" y1="6" x2="18" y2="50" stroke="currentColor" stroke-width="2"/><circle cx="26" cy="20" r="2.4" fill="currentColor"/><circle cx="26" cy="36" r="2.4" fill="currentColor"/></svg>`;
        }
        if (kind === 'repeatEnd') {
            // Mirror of repeatStart - dots face left into the section that just played, thin line
            // then the thick line on the outside (right - the far edge of the repeated section).
            return `<svg viewBox="0 0 32 56"${c}><circle cx="6" cy="20" r="2.4" fill="currentColor"/><circle cx="6" cy="36" r="2.4" fill="currentColor"/><line x1="14" y1="6" x2="14" y2="50" stroke="currentColor" stroke-width="2"/><line x1="22" y1="6" x2="22" y2="50" stroke="currentColor" stroke-width="5"/></svg>`;
        }
        if (kind === 'fine') {
            // The final barline (end of the piece) - a thin line followed by a thick line, no dots.
            return `<svg viewBox="0 0 32 56"${c}><line x1="12" y1="6" x2="12" y2="50" stroke="currentColor" stroke-width="2"/><line x1="20" y1="6" x2="20" y2="50" stroke="currentColor" stroke-width="5"/></svg>`;
        }
        if (kind === 'section') {
            // A plain double barline (a mid-piece section boundary) - two thin lines, same weight,
            // distinct from "fine" above where the second line is heavy.
            return `<svg viewBox="0 0 32 56"${c}><line x1="12" y1="6" x2="12" y2="50" stroke="currentColor" stroke-width="2"/><line x1="20" y1="6" x2="20" y2="50" stroke="currentColor" stroke-width="2"/></svg>`;
        }
        const color = muted ? 'var(--label-color)' : 'currentColor';
        return `<svg viewBox="0 0 32 56"${c}><line x1="16" y1="6" x2="16" y2="50" stroke="${color}" stroke-width="3" stroke-linecap="round"/></svg>`;
    }

    // --- Reorderable blocks: label helpers (each mirrors a small slice of the schema - see
    // docs/database-schema.md's "Journey/repeat wiring" note for what each column means). Repeats/
    // intro and Changes/jumps tiles deliberately stay standard-input coloured regardless of value -
    // no gold-filled state - unlike Core's own tiles, which never had one either. ---
    function flowStartLabel(b) { return flowBarlineIconSvg(b.isRepeatStart ? 'repeatStart' : 'plain'); }
    // 2x is the implicit default (same as picking "Repeat" with no count at all) - never shown, in
    // the picker or here, so the card matches exactly what was selected there.
    function flowRepeatCountLabel(n) { return n === 2 ? '' : `${n}x`; }
    function flowEndLabel(b) {
        if (b.isRepeatEnd) {
            const icon = flowBarlineIconSvg('repeatEnd');
            // Same smaller, vertically-centered-with-the-icon count as the End of bar picker's own
            // tiles (.flow-picker-tile-count) - not full tile-value size/baseline.
            const countLabel = flowRepeatCountLabel(b.repeatPlayCount || 2);
            return countLabel
                ? `<span class="flow-barline-value-row">${icon}<span class="flow-barline-value-count">${countLabel}</span></span>`
                : icon;
        }
        if (b.isFinalBarline) return flowBarlineIconSvg('fine');
        // Fine reuses Section's plain double-bar glyph plus a "Fine" tag, same .flow-barline-value-row/
        // -count pattern isRepeatEnd's own count uses above - not a distinct barline shape of its own.
        if (b.isFine) return `<span class="flow-barline-value-row">${flowBarlineIconSvg('section')}<span class="flow-barline-value-count">Fine</span></span>`;
        if (b.isSectionBoundary) return flowBarlineIconSvg('section');
        return flowBarlineIconSvg('plain');
    }
    // Generic status glyph (Repeat bar/volta's stale start-bar warning today, reusable wherever else
    // a value needs flagging as "needs fixing" rather than silently wrong or silently clamped).
    function flowWarningIconSvg(cls) {
        const c = cls ? ` class="${cls}"` : '';
        return `<svg viewBox="0 0 24 24"${c} fill="none"><path d="M12 4L22 20H2L12 4Z" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/><line x1="12" y1="10" x2="12" y2="15" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><circle cx="12" cy="18" r="1.2" fill="currentColor"/></svg>`;
    }
    // Tempo ramp glyph - a rising diagonal (accelerando) by default, mirrored into a falling one
    // (ritardando) when the direction is known - same hand-drawn-SVG approach as
    // flowBarlineIconSvg/flowWarningIconSvg above. 'flat' (the target bpm resolves to exactly the
    // current one - unusual, but not itself invalid) gets a plain rightward arrow instead of either.
    function flowRampIconSvg(direction, cls) {
        const c = cls ? ` class="${cls}"` : '';
        if (direction === 'down') {
            return `<svg viewBox="0 0 24 24"${c} fill="none"><path d="M4 6L18 18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/><path d="M10 18H18V10" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
        }
        if (direction === 'flat') {
            return `<svg viewBox="0 0 24 24"${c} fill="none"><path d="M3 12H17" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/><path d="M12 7L19 12L12 17" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
        }
        return `<svg viewBox="0 0 24 24"${c} fill="none"><path d="M4 18L18 6" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/><path d="M10 6H18V14" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
    }
    // Resolves whether a ramp speeds up, slows down, or holds - null only when the target itself
    // can't be resolved yet (a 'next_block' target with no next block - always caught by
    // flowRampInvalid before this is reached, so callers can treat null as "can't happen" in
    // practice, not a case they need their own fallback for).
    function flowRampDirection(r, block, nextBlock) {
        const fromBpm = Number(block.bpm);
        const toBpm = r.targetMode === 'custom' ? Number(r.targetBpm) : (nextBlock ? Number(nextBlock.bpm) : null);
        if (toBpm === null || !Number.isFinite(toBpm) || !Number.isFinite(fromBpm)) return null;
        if (toBpm > fromBpm) return 'up';
        if (toBpm < fromBpm) return 'down';
        return 'flat';
    }
    // "1-3,5&7-9." - consecutive runs collapse to a range ([1,2,3] -> "1-3", a lone number stays
    // bare), commas between all but the last two tokens, "&" joining the final pair, and a single
    // full stop at the very end (not one per number/range) - squashed up, no spaces.
    function flowFormatRepeatPasses(nums) {
        const sorted = [...nums].sort((a, b) => a - b);
        if (!sorted.length) return '';
        const tokens = [];
        let rangeStart = sorted[0];
        let rangeEnd = sorted[0];
        for (let i = 1; i < sorted.length; i++) {
            if (sorted[i] === rangeEnd + 1) { rangeEnd = sorted[i]; continue; }
            tokens.push(rangeStart === rangeEnd ? `${rangeStart}` : `${rangeStart}-${rangeEnd}`);
            rangeStart = rangeEnd = sorted[i];
        }
        tokens.push(rangeStart === rangeEnd ? `${rangeStart}` : `${rangeStart}-${rangeEnd}`);
        const joined = tokens.length <= 1 ? (tokens[0] || '') : `${tokens.slice(0, -1).join(',')}&${tokens[tokens.length - 1]}`;
        return `${joined}.`;
    }
    // Repeat-ending numbers (ML-179 follow-up, db/migrations/034_repeat_ending_numbers.sql) - a
    // superset of the old binary 1st/2nd pair, e.g. [1,3,5] for "plays on passes 1, 3 and 5 only".
    // Empty state is a plain "+" (matching flowBlockMarkEmpty's own muted-tile language) rather than
    // the word "None" every other tile's empty state uses - this tile opens straight into a form,
    // not a list of named options, so "+" reads as "add one" instead.
    // Start/end bars aren't DB-bounded against bar count (db/migrations/037_volta_start_bar.sql) - if
    // the block is shortened after one's set, it's left stranded outside the block. Rather than a
    // small inline warning icon next to otherwise-stale content, the whole tile flags this: a big
    // triangle + "Update" replaces the tile's normal value, and .flow-tile-warning reddens the tile
    // itself (flowBlockCardHtml) - same treatment for the alt-ending tile and the intro tile.
    function flowRepeatBarInvalid(b) { return FlowJourney.repeatBarInvalid(b); } // ML-193: one rule, shared with the ML-248 checker
    function flowIntroInvalid(b) { return FlowJourney.introInvalid(b); }
    function flowPauseInvalid(b) { return FlowJourney.pauseInvalid(b); }
    function flowTileUpdateWarning() {
        return `<span class="flow-tile-value-warning">${flowWarningIconSvg('flow-tile-warning-icon')}<span class="flow-tile-value-warning-text">Update</span></span>`;
    }
    function flowRepeatBarLabel(b) {
        if (flowRepeatBarInvalid(b)) return flowTileUpdateWarning();
        const nums = b.repeatEndingNumbers || [];
        if (!nums.length) return '<span class="flow-tile-value-empty">+</span>';
        const text = escapeHtml(flowFormatRepeatPasses(nums));
        // Real volta-bracket notation (the corner drawn by .flow-volta-bracket::before in CSS) - a
        // line above the figures with a downward tick immediately to their left, running alongside
        // them - not just plain text, same "hand-drawn real notation" language as flowBarlineIconSvg.
        const bracket = `<span class="flow-volta-bracket"><span class="flow-volta-bracket-numbers">${text}</span></span>`;
        const fromBar = b.repeatEndingStartBar
            ? `<span class="flow-volta-from-bar">from bar ${b.repeatEndingStartBar}</span>`
            : '';
        return `${bracket}${fromBar}`;
    }
    function flowIntroLabel(b) {
        if (flowIntroInvalid(b)) return flowTileUpdateWarning();
        const hasStart = b.introStartBarOffset !== null && b.introStartBarOffset !== undefined;
        const hasEnd = b.introEndBarOffset !== null && b.introEndBarOffset !== undefined;
        if (!hasStart && !hasEnd) return '<span class="flow-tile-value-empty">+</span>';
        const spansMultiple = hasStart && hasEnd && b.introStartBarOffset !== b.introEndBarOffset;
        const text = spansMultiple ? `Bars ${b.introStartBarOffset}-${b.introEndBarOffset}`
            : hasStart ? `Bar ${b.introStartBarOffset}`
            : `Bar ${b.introEndBarOffset}`;
        // Real-notation cue bracket (the corner drawn by .flow-intro-bracket's ::before/::after in
        // CSS) - a tall tick to the left of the text and a line underneath, same "hand-drawn real
        // notation" language as flowBarlineIconSvg/the volta bracket. The right-hand tick only shows
        // once an end bar is actually set ("End intro early?" on) - left open when it isn't, since
        // that reads more clearly as "runs through to the end of the section" than any text would.
        const openEndClass = hasEnd ? '' : ' flow-intro-bracket-open-end';
        return `<span class="flow-intro-bracket${openEndClass}"><span class="flow-intro-bracket-text">${text}</span></span>`;
    }
    // A block can carry more than one ramp (b.ramps, metronome_segment_ramps) - same "stale until
    // fixed, flagged rather than silently wrong" precedent as flowPauseInvalid/flowIntroInvalid.
    // Stale start/end bars mean the block shrank after the ramp was set; a "next block" target with
    // no next block (this is the last block in the flow) can't resolve to anything, per the user's
    // own request that this be surfaced before Saving rather than silently ignored at playback time.
    function flowRampInvalid(b, nextBlock) { return FlowJourney.rampInvalid(b, nextBlock); }
    function flowChangeLabel(b, nextBlock) {
        if (flowRampInvalid(b, nextBlock)) return flowTileUpdateWarning();
        const ramps = b.ramps || [];
        if (!ramps.length) return '<span class="flow-tile-value-empty">+</span>';
        // A block can mix speed-ups and slow-downs, so this tallies by direction rather than just
        // showing one combined count - up first, then down, then flat (equal bpm, unusual but not
        // invalid), each only shown when the block actually has one. flow-ramp-tile-icon shrinks the
        // icon down from .flow-tile-value svg's default 1.6em (tuned for the taller/narrower barline
        // glyphs) - up to three icon+count groups need to fit in the same tile now.
        const counts = { up: 0, down: 0, flat: 0 };
        ramps.forEach(r => { counts[flowRampDirection(r, b, nextBlock) || 'flat']++; });
        const groups = ['up', 'down', 'flat']
            .filter(dir => counts[dir])
            .map(dir => `${flowRampIconSvg(dir, 'flow-ramp-tile-icon')}<span class="flow-barline-value-count">×${counts[dir]}</span>`)
            .join('');
        return `<span class="flow-barline-value-row flow-ramp-tile-row">${groups}</span>`;
    }
    function flowSignLabel(b) {
        if (b.isSegno) return flowSignIconSvg('segno');
        if (b.isCoda) return flowSignIconSvg('coda');
        return '<span class="flow-tile-value-empty">+</span>';
    }
    // "D.S. al <coda>"/"To <coda>" - the real coda symbol at the same size as the surrounding text
    // (flowSignIconSvg's inline variant), but "D.S."/"D.C." spelled with a plain letter S/C rather
    // than the segno symbol - these are jump instructions, not a claim that the segno sign itself is
    // printed on this bar (that's the separate "sign" tile/flowSignLabel, openFlowSignPicker).
    function flowJumpLabel(b) {
        // .flow-tile-value is flex-direction:column, so raw sibling text+glyph content becomes two
        // separate flex items and stacks onto two lines instead of flowing inline - wrapping them
        // together in one .flow-barline-value-row (already inline-flex, row direction) keeps text and
        // glyph on a single line, same fix flowEndLabel's own icon+count pairing already relies on.
        if (b.gotoSegnoThenCoda) return `<span class="flow-barline-value-row">D.S. al ${flowSignIconSvg('coda', true)}</span>`;
        if (b.gotoStartDcThenCoda) return `<span class="flow-barline-value-row">D.C. al ${flowSignIconSvg('coda', true)}</span>`;
        if (b.gotoCoda) return `<span class="flow-barline-value-row">To ${flowSignIconSvg('coda', true)}</span>`;
        if (b.gotoSegno) return 'D.S.';
        if (b.gotoStartDc) return 'D.C.';
        return '<span class="flow-tile-value-empty">+</span>';
    }
    function flowPauseLabel(b) {
        if (flowPauseInvalid(b)) return flowTileUpdateWarning();
        const pauses = b.fermatas || [];
        const fermataCount = pauses.filter(p => (p.kind || 'fermata') === 'fermata').length;
        const caesuraCount = pauses.filter(p => p.kind === 'caesura').length;
        if (!fermataCount && !caesuraCount) return '<span class="flow-tile-value-empty">+</span>';
        // Wrapped in one .flow-barline-value-row so the fermata group and caesura group (each itself
        // an icon+count pair) flow side by side on one line rather than stacking - .flow-tile-value's
        // flex-direction:column would otherwise turn each into its own flex item, same bug already
        // fixed once for flowJumpLabel/flowEndLabel.
        let inner = '';
        if (fermataCount) inner += `${flowPauseIconSvg('fermata', true)}<span class="flow-barline-value-count">×${fermataCount}</span>`;
        if (caesuraCount) inner += `${flowPauseIconSvg('caesura', true)}<span class="flow-barline-value-count">×${caesuraCount}</span>`;
        return `<span class="flow-barline-value-row">${inner}</span>`;
    }

    // The 12 setting tiles (Core / Repeats+Intro / Tempo+Jumps) - shared by the 1-column card
    // (flowBlockCardHtml) and the 4-column layout's bar popup (renderFlowBarPopup, ML-206), so a change
    // to a tile shows up in both. Every tile carries data-block-tile; the caller wires the clicks.
    function flowBlockTileSectionsHtml(b, nextBlock) {
        const timeSig = b.timeSignatureLabel || `${b.numerator}/${b.denominator}`;
        return `
                <div class="flow-tile-section">
                    <span class="flow-tile-section-label">Core</span>
                    <div class="flow-tile-grid flow-tile-grid-4">
                        <button type="button" class="flow-tile" data-block-tile="time"><span class="flow-tile-value">${escapeHtml(timeSig)}</span><span class="flow-tile-label">time</span></button>
                        <button type="button" class="flow-tile" data-block-tile="beatUnit"><span class="flow-tile-value">${metroNoteIconSvg(b.noteValue || 'crotchet')}</span><span class="flow-tile-label">beat note</span></button>
                        <button type="button" class="flow-tile" data-block-tile="bpm"><span class="flow-tile-value">${b.bpm}</span><span class="flow-tile-label">bpm</span></button>
                        <button type="button" class="flow-tile" data-block-tile="bars"><span class="flow-tile-value">${b.barCount}</span><span class="flow-tile-label">bars</span></button>
                    </div>
                </div>
                <div class="flow-tile-section">
                    <div class="flow-tile-section-split-labels flow-tile-section-split-labels-3-1">
                        <span class="flow-tile-section-label">Repeats</span>
                        <span class="flow-tile-section-label">Intro</span>
                    </div>
                    <div class="flow-tile-grid flow-tile-grid-4">
                        <button type="button" class="flow-tile" data-block-tile="start"><span class="flow-tile-value">${flowStartLabel(b)}</span><span class="flow-tile-label">start</span></button>
                        <button type="button" class="flow-tile" data-block-tile="end"><span class="flow-tile-value">${flowEndLabel(b)}</span><span class="flow-tile-label">end</span></button>
                        <button type="button" class="flow-tile${flowRepeatBarInvalid(b) ? ' flow-tile-warning' : ''}" data-block-tile="repeatBar"><span class="flow-tile-value">${flowRepeatBarLabel(b)}</span><span class="flow-tile-label">alt ending</span></button>
                        <button type="button" class="flow-tile${flowIntroInvalid(b) ? ' flow-tile-warning' : ''}" data-block-tile="intro"><span class="flow-tile-value">${flowIntroLabel(b)}</span><span class="flow-tile-label">bar range</span></button>
                    </div>
                </div>
                <div class="flow-tile-section">
                    <div class="flow-tile-section-split-labels">
                        <span class="flow-tile-section-label">Tempo</span>
                        <span class="flow-tile-section-label">Jumps</span>
                    </div>
                    <div class="flow-tile-grid flow-tile-grid-4">
                        <button type="button" class="flow-tile${flowPauseInvalid(b) ? ' flow-tile-warning' : ''}" data-block-tile="pause"><span class="flow-tile-value">${flowPauseLabel(b)}</span><span class="flow-tile-label">pause</span></button>
                        <button type="button" class="flow-tile${flowRampInvalid(b, nextBlock) ? ' flow-tile-warning' : ''}" data-block-tile="change"><span class="flow-tile-value">${flowChangeLabel(b, nextBlock)}</span><span class="flow-tile-label">ramp</span></button>
                        <button type="button" class="flow-tile" data-block-tile="sign"><span class="flow-tile-value">${flowSignLabel(b)}</span><span class="flow-tile-label">sign</span></button>
                        <button type="button" class="flow-tile" data-block-tile="jump"><span class="flow-tile-value">${flowJumpLabel(b)}</span><span class="flow-tile-label">jump</span></button>
                    </div>
                </div>
        `;
    }

    // Rehearsal-mark box in a bar's header (card and popup) - "+ RM" when there isn't one (ML-219).
    function flowBlockMarkBoxHtml(b) {
        return b.rehearsalMark
            ? `<button type="button" class="flow-block-mark-box" data-block-tile="rehearsalMark" aria-label="Rehearsal mark: ${escapeHtml(b.rehearsalMark)} - tap to change" title="${escapeHtml(b.rehearsalMark)}">${escapeHtml(b.rehearsalMark)}</button>`
            : `<button type="button" class="flow-block-mark-empty" data-block-tile="rehearsalMark" aria-label="Add rehearsal mark">+ RM</button>`;
    }

    function flowBlockCardHtml(b, idx, nextBlock) {
        const markBox = flowBlockMarkBoxHtml(b);
        // Grab handle/delete-underlay only render once there's more than one block to reorder/delete -
        // same "hide, don't just no-op" precedent as the 3-dot menu's own Move up/down/Delete
        // (openFlowBlockMenu) and Quick Play's own qp-bar-grab-handle/qp-block-delete-underlay.
        const canReorderOrDelete = currentFlowBlocks.length > 1;
        const grabHandle = canReorderOrDelete
            ? `<button type="button" class="flow-block-grab-handle" data-block-grab-handle aria-label="Drag to reorder ${flowBarRangeLabel(idx)}"><span class="material-symbols-outlined">drag_indicator</span></button>`
            : '';
        const deleteUnderlay = canReorderOrDelete
            ? `<div role="button" tabindex="0" class="flow-block-delete-underlay" data-block-delete-btn aria-label="Delete ${flowBarRangeLabel(idx)}">
                <span class="material-symbols-outlined">delete</span>
                <span>Delete</span>
            </div>`
            : '';
        // .flow-block-box is a plain clipping wrapper (delete underlay behind, the actual card in
        // front and sliding) - same split as Quick Play's own qp-block-box/qp-block-surface
        // (wireQpBarSwipe), which this mirrors so scrolling from anywhere on a bar card works exactly
        // the same way here as it does there (see wireFlowBlockSwipe/wireFlowBlockGrabHandle below).
        return `
            <div class="flow-block-box" data-block-index="${idx}" data-block-id="${b.id}">
                ${deleteUnderlay}
                <div class="flow-block-card">
                <div class="flow-block-card-header">
                    <div class="flow-block-card-title">
                        ${grabHandle}
                        ${markBox}
                        <span class="flow-block-name">${flowBarRangeLabel(idx)}</span>
                    </div>
                    <button type="button" class="list-item-menu-btn" data-block-menu-btn aria-label="${flowBarRangeLabel(idx)} options" aria-haspopup="menu" aria-expanded="false"><span class="material-symbols-outlined">more_vert</span></button>
                </div>
                ${flowBlockTileSectionsHtml(b, nextBlock)}
                </div>
            </div>
        `;
    }

    function renderFlowBlocksList() {
        queueMicrotask(flowRefreshIssueHighlights); // ML-248: once whichever layout below has rendered
        const container = document.getElementById('flowBlocksList');
        if (!container) return;
        const grid = flowBarLayout !== '1';
        const hasBars = currentFlowBlocks.length > 0;
        container.classList.toggle('metroBlk-tile-strip', flowBarLayout === '4' && hasBars);
        container.classList.toggle('flow-bar-grid-2', flowBarLayout === '2' && hasBars);
        container.classList.toggle('flow-bar-grid', grid && hasBars);
        renderFlowBarLayoutToggle();
        // The popup mirrors whatever the list shows, so it refreshes on every list render - an edit
        // made from inside it (tile picker, move, duplicate) lands here via renderFlowBlocksStudio.
        renderFlowBarPopup();
        if (!currentFlowBlocks.length) {
            container.innerHTML = '<p class="text-muted text-center p-5">No bars yet - add your first one below.</p>';
            return;
        }
        if (grid) {
            renderFlowBarGrid(container);
            return;
        }
        container.innerHTML = currentFlowBlocks.map((b, idx) => flowMovementHeadHtml(idx) + flowBlockCardHtml(b, idx, currentFlowBlocks[idx + 1])).join('');

        // Same gesture split as Quick Play's own bar boxes (wireQpBarGrabHandle/wireQpBarSwipe) -
        // reordering is scoped strictly to the grab handle, deleting to a horizontal swipe that only
        // intercepts the gesture once it's confirmed horizontal, and neither touches the page's own
        // vertical scroll otherwise (see .flow-block-box's touch-action:pan-y in style.css). Replaces
        // the old whole-card HTML5 draggable attribute, whose touch-action:none on the entire card blocked
        // native scroll from ever starting on a bar card at all.
        container.querySelectorAll('.flow-block-box').forEach((boxEl) => {
            const blockId = flowBlockIdFromDataset(boxEl.dataset.blockId);
            wireFlowBlockGrabHandle(boxEl.querySelector('[data-block-grab-handle]'), boxEl, blockId);
            wireFlowBlockSwipe(boxEl, blockId);
        });

        container.querySelectorAll('[data-block-tile]').forEach(btn => {
            const blockId = flowBlockIdFromDataset(btn.closest('.flow-block-box').dataset.blockId);
            btn.addEventListener('click', () => handleFlowBlockTileClick(blockId, btn.dataset.blockTile));
        });
        container.querySelectorAll('[data-block-menu-btn]').forEach(btn => {
            btn.addEventListener('click', (e) => {
                e.stopPropagation();
                openFlowBlockMenu(e.currentTarget, flowBlockIdFromDataset(btn.closest('.flow-block-box').dataset.blockId));
            });
        });
    }

    // ========================================
    // ML-206: Bars tab 4-column layout. Each bar is a Play Flow tile (flowBarSummaryTile). Tapping one
    // opens the bar popup (the 1-column card's tiles plus previous/next, move, duplicate and delete);
    // pressing and holding picks it up to drag anywhere in the grid, the other tiles sliding along and
    // up to make room. No swipe-to-delete here - Delete lives in the popup.
    // ========================================
    function setFlowBarLayout(layout) {
        if (layout === flowBarLayout) return;
        flowBarLayout = layout;
        try { localStorage.setItem(FLOW_BAR_LAYOUT_KEY, layout); } catch (e) { /* not remembered - fine */ }
        renderFlowBlocksList();
    }
    function renderFlowBarLayoutToggle() {
        document.querySelectorAll('[data-flow-layout]').forEach(btn => {
            btn.setAttribute('aria-pressed', String(btn.dataset.flowLayout === flowBarLayout));
        });
    }
    document.querySelectorAll('[data-flow-layout]').forEach(btn => {
        btn.addEventListener('click', () => setFlowBarLayout(btn.dataset.flowLayout));
    });

    function renderFlowBarGrid(container) {
        let startBar = 1;
        // data-block-id is what flowAnimateBlocksChange's FLIP matches on, so moves made from the popup
        // (flowMoveBlockUp/Down) slide the tiles here exactly as they slide the cards in 1-column.
        // Both grid layouts share .flow-bar-grid-tile, so the tap/hold/drag wiring below is identical.
        container.innerHTML = currentFlowBlocks.map((b, idx) => {
            if (flowBarLayout === '2') return flowMovementHeadHtml(idx) + flowBarDetailTileHtml(b, idx, currentFlowBlocks[idx + 1]);
            const tile = flowBarSummaryTile(b, startBar);
            startBar += b.barCount || 0;
            return flowMovementHeadHtml(idx) + `<button type="button" class="metroBlk-tile flow-bar-grid-tile" data-block-id="${b.id}" title="${tile.name}" aria-label="Edit ${tile.name}" aria-haspopup="dialog">${tile.inner}</button>`;
        }).join('');
        container.querySelectorAll('.flow-bar-grid-tile').forEach(tile => {
            const blockId = flowBlockIdFromDataset(tile.dataset.blockId);
            tile.addEventListener('click', () => openFlowBarPopup(blockId));
            // a11y: only records where a press starts - dragging needs a hold first (WCAG 2.5.2); the
            // popup's Move earlier/later is the single-tap alternative (gestures.json)
            tile.addEventListener('pointerdown', (e) => {
                if (e.button !== 0 || currentFlowBlocks.length < 2) return;
                flowBarGridStartHold(container, tile, e);
            });
            tile.addEventListener('contextmenu', (e) => e.preventDefault()); // Android long-press menu
        });
        // Once per container, not per render: swallows the click that follows a drag so dropping a
        // tile doesn't also open its popup (same guard as setupMetroBlkDragAndDrop).
        if (!container.dataset.dragClickGuardBound) {
            container.dataset.dragClickGuardBound = '1';
            container.addEventListener('click', (e) => {
                if (container.dataset.suppressNextClick === '1') {
                    delete container.dataset.suppressNextClick;
                    e.stopPropagation();
                    e.preventDefault();
                }
            }, true);
        }
    }

    // The pieces of a bar "read like music" - shared by the 2-column tile (flowBarDetailTileHtml) and
    // Play Flow's 1-column bar (flowBarFullTileHtml), so the two can't drift apart. Each piece is ready
    // HTML, or '' when the bar doesn't have it; ramps is a list (one chip per direction).
    function flowBarReadingParts(b, nextBlock) {
        const sign = b.isSegno ? flowSignIconSvg('segno', true) : b.isCoda ? flowSignIconSvg('coda', true) : '';
        const startLine = b.isRepeatStart
            ? flowBarlineIconSvg('repeatStart', 'flow-bar-detail-barline')
            : flowBarlineIconSvg('plain', 'flow-bar-detail-barline', true);
        // Same end-of-bar precedence as flowEndLabel; 2x is the implicit default and never shown.
        let endLine = flowBarlineIconSvg('plain', 'flow-bar-detail-barline', true);
        let endExtra = '';
        if (b.isRepeatEnd) {
            endLine = flowBarlineIconSvg('repeatEnd', 'flow-bar-detail-barline');
            endExtra = flowRepeatCountLabel(b.repeatPlayCount || 2);
        } else if (b.isFinalBarline) {
            endLine = flowBarlineIconSvg('fine', 'flow-bar-detail-barline');
        } else if (b.isFine) {
            endLine = flowBarlineIconSvg('section', 'flow-bar-detail-barline');
            endExtra = 'Fine';
        } else if (b.isSectionBoundary) {
            endLine = flowBarlineIconSvg('section', 'flow-bar-detail-barline');
        }

        const passes = b.repeatEndingNumbers || [];
        const volta = passes.length
            ? `<span class="flow-volta-bracket"><span class="flow-volta-bracket-numbers">${escapeHtml(flowFormatRepeatPasses(passes))}</span></span>`
            : '';
        let intro = '';
        const hasIntroStart = b.introStartBarOffset !== null && b.introStartBarOffset !== undefined;
        const hasIntroEnd = b.introEndBarOffset !== null && b.introEndBarOffset !== undefined;
        if (hasIntroStart || hasIntroEnd) {
            const from = hasIntroStart ? b.introStartBarOffset : b.introEndBarOffset;
            const to = hasIntroEnd ? b.introEndBarOffset : from;
            intro = `<span class="flow-intro-bracket${hasIntroEnd ? '' : ' flow-intro-bracket-open-end'}"><span class="flow-intro-bracket-text">Intro ${from === to ? from : `${from}–${to}`}</span></span>`;
        }
        let pauses = '';
        const pauseList = b.fermatas || [];
        const fermatas = pauseList.filter(p => (p.kind || 'fermata') === 'fermata').length;
        const caesuras = pauseList.filter(p => p.kind === 'caesura').length;
        // Fermatas and caesuras each get their own chip, so with both they sit apart (the row's normal
        // gap between marks) rather than reading as one combined mark.
        if (fermatas) pauses += `<span class="flow-bar-detail-chip">${flowPauseIconSvg('fermata', true)}<span class="flow-bar-detail-times">×${fermatas}</span></span>`;
        if (caesuras) pauses += `<span class="flow-bar-detail-chip">${flowPauseIconSvg('caesura', true)}<span class="flow-bar-detail-times">×${caesuras}</span></span>`;
        const rampCounts = { up: 0, down: 0, flat: 0 };
        (b.ramps || []).forEach(r => { rampCounts[flowRampDirection(r, b, nextBlock) || 'flat']++; });
        const rampWords = { up: 'accel.', down: 'rit.', flat: '' };
        const ramps = ['up', 'down', 'flat'].filter(dir => rampCounts[dir]).map(dir => {
            const times = rampCounts[dir] > 1 ? `<span class="flow-bar-detail-times">×${rampCounts[dir]}</span>` : '';
            return `<span class="flow-bar-detail-chip">${rampWords[dir]}${flowRampIconSvg(dir, 'flow-bar-detail-ramp')}${times}</span>`;
        });
        const jump = (b.gotoSegno || b.gotoStartDc || b.gotoCoda || b.gotoSegnoThenCoda || b.gotoStartDcThenCoda)
            ? `<span class="flow-bar-detail-chip">${flowJumpLabel(b)}</span>`
            : '';
        return { sign, startLine, endLine, endExtra, volta, intro, pauses, ramps, jump };
    }

    // ML-207: one bar on Play Flow's 1-column view - read-only, all 12 settings, each roughly where it
    // sits on a score:
    //   header:          rehearsal mark, "Bars 1–8" ................................ "8 bars"
    //   top of the bar:  sign (left) · pauses (centre) · alternate ending, jump (right)
    //   the bar:         start barline | time signature  ♩ = 100 bpm | end barline (+ count / Fine)
    //   under the bar:   intro, ramps (type and count only)
    // Both "on the music" rows are always there, even when empty, so every bar is the same height. No
    // needs-updating state - Play only reads the bar. Tap jumps playback, like the other Play views.
    function flowBarFullTileHtml(b, idx, nextBlock, { active = false } = {}) {
        const name = flowBarPopupRangeLabel(idx);
        const mark = b.rehearsalMark ? `<span class="flow-bar-detail-mark" title="${escapeHtml(b.rehearsalMark)}">${escapeHtml(b.rehearsalMark)}</span>` : '';
        const label = `${b.rehearsalMark ? `${escapeHtml(b.rehearsalMark)}, ` : ''}${name}`;
        const bars = `${b.barCount} bar${b.barCount === 1 ? '' : 's'}`;
        const { sign, startLine, endLine, endExtra, volta, intro, pauses, ramps, jump } = flowBarReadingParts(b, nextBlock);
        const noteKey = b.noteValue || 'crotchet';
        const noteLabel = (METRO_NOTE_TYPES.find(t => t.key === noteKey) || {}).label || noteKey;
        return `<button type="button" class="flow-bar-full-tile${active ? ' metroBlk-tile-active' : ''}" data-block-id="${b.id}" aria-label="Jump to ${label}"${active ? ' aria-current="true"' : ''} data-act="flow-jump" data-arg="${b.id}">
            <span class="flow-bar-full-head">${mark}<span class="flow-bar-detail-name">${name}</span><span class="flow-bar-full-bars">${bars}</span></span>
            <span class="flow-bar-full-row flow-bar-full-top">
                <span class="flow-bar-full-zone">${sign ? `<span class="flow-bar-full-sign">${sign}</span>` : ''}</span>
                <span class="flow-bar-full-zone flow-bar-full-zone-mid">${pauses}</span>
                <span class="flow-bar-full-zone flow-bar-full-zone-end">${volta}${jump}</span>
            </span>
            <span class="flow-bar-full-mid">
                <span class="flow-bar-detail-edge">${startLine}</span>
                <span class="flow-bar-full-meter">
                    <span class="flow-bar-full-time">${escapeHtml(b.timeSignatureLabel || `${b.numerator}/${b.denominator}`)}</span>
                    <span class="flow-bar-full-tempo"><span class="flow-bar-full-note" role="img" aria-label="${escapeHtml(noteLabel)}">${metroNoteIconSvg(noteKey)}</span><span class="flow-bar-full-eq">=</span><span class="flow-bar-full-bpm">${b.bpm}</span><span class="flow-bar-full-unit">bpm</span></span>
                </span>
                <span class="flow-bar-detail-edge flow-bar-full-edge-end">${endLine}${endExtra ? `<span class="flow-bar-full-count">${endExtra}</span>` : ''}</span>
            </span>
            <span class="flow-bar-full-row flow-bar-full-bottom">${intro}${ramps.join('')}</span>
        </button>`;
    }

    // ML-113: the lead-in as an ordinary Play Flow tile (1 or 2 columns), the same shape as the bars
    // after it - named "Lead-in", in bar 1's time, beat note and tempo, plain barlines, nothing else.
    // Returns '' when there's no lead-in.
    function flowLeadInPlayTileHtml(layout, active) {
        const first = currentFlowBlocks[0];
        if (!flowLeadInBlock || !first) return '';
        const b = {
            ...flowDefaultBlockFields(), id: flowLeadInBlock.id, barCount: 1, bpm: first.bpm, noteValue: first.noteValue,
            numerator: first.numerator, denominator: first.denominator, timeSignatureLabel: first.timeSignatureLabel
        };
        const { startLine, endLine } = flowBarReadingParts(b, null);
        const time = escapeHtml(b.timeSignatureLabel || `${b.numerator}/${b.denominator}`);
        const open = (cls) => `<button type="button" class="${cls}${active ? ' metroBlk-tile-active' : ''}" data-block-id="${b.id}" aria-label="Jump to the lead-in, ${b.bpm} bpm, 1 bar"${active ? ' aria-current="true"' : ''} data-act="flow-jump" data-arg="${b.id}">`;
        if (layout === '2') {
            return `${open('flow-bar-detail-tile')}
                <span class="flow-bar-detail-head"><span class="flow-bar-detail-name">Lead-in</span></span>
                <span class="flow-bar-detail-mid">
                    <span class="flow-bar-detail-edge">${startLine}</span>
                    <span class="flow-bar-detail-meter"><span class="flow-bar-detail-time">${time}</span><span class="flow-bar-detail-bpm">${b.bpm} bpm</span></span>
                    <span class="flow-bar-detail-edge">${endLine}</span>
                </span>
                <span class="flow-bar-detail-strip"></span>
            </button>`;
        }
        const noteKey = b.noteValue || 'crotchet';
        const noteLabel = (METRO_NOTE_TYPES.find(t => t.key === noteKey) || {}).label || noteKey;
        return `${open('flow-bar-full-tile')}
            <span class="flow-bar-full-head"><span class="flow-bar-detail-name">Lead-in</span><span class="flow-bar-full-bars">1 bar</span></span>
            <span class="flow-bar-full-row flow-bar-full-top"><span class="flow-bar-full-zone"></span><span class="flow-bar-full-zone flow-bar-full-zone-mid"></span><span class="flow-bar-full-zone flow-bar-full-zone-end"></span></span>
            <span class="flow-bar-full-mid">
                <span class="flow-bar-detail-edge">${startLine}</span>
                <span class="flow-bar-full-meter">
                    <span class="flow-bar-full-time">${time}</span>
                    <span class="flow-bar-full-tempo"><span class="flow-bar-full-note" role="img" aria-label="${escapeHtml(noteLabel)}">${metroNoteIconSvg(noteKey)}</span><span class="flow-bar-full-eq">=</span><span class="flow-bar-full-bpm">${b.bpm}</span><span class="flow-bar-full-unit">bpm</span></span>
                </span>
                <span class="flow-bar-detail-edge flow-bar-full-edge-end">${endLine}</span>
            </span>
            <span class="flow-bar-full-row flow-bar-full-bottom"></span>
        </button>`;
    }

    // ML-208: one bar as a 2-column detail tile - a reading of the bar rather than a list of settings.
    //   header: segno/coda sign, rehearsal mark, "Bars 1–8" (fixed height, so every row's middles line up)
    //   middle: start barline | time signature over bpm | end barline (+ repeat count / Fine)
    //   strip:  alt ending, intro, pauses, ramps, jump - blank (but still there) when the bar has none
    // A bar with a stale setting (the same checks that turn a card tile red) shows only its mark and
    // range, a large ⚠ Update in the middle and a blank strip. Beat note is deliberately left out.
    // ML-209: Play Flow uses the very same tile ({ play: true }) - a button that jumps playback to the
    // bar (jumpFlowToPlayIndex, same as a 4-column Play tile), gold-edged while it's the bar sounding
    // (`active`), and none of the Bars tab's popup/drag wiring (.flow-bar-grid-tile).
    function flowBarDetailTileHtml(b, idx, nextBlock, { play = false, active = false } = {}) {
        const name = flowBarPopupRangeLabel(idx);
        const mark = b.rehearsalMark ? `<span class="flow-bar-detail-mark" title="${escapeHtml(b.rehearsalMark)}">${escapeHtml(b.rehearsalMark)}</span>` : '';
        const label = `${b.rehearsalMark ? `${escapeHtml(b.rehearsalMark)}, ` : ''}${name}`;
        const open = play
            ? `<button type="button" class="flow-bar-detail-tile{CLS}${active ? ' metroBlk-tile-active' : ''}" data-block-id="${b.id}" aria-label="Jump to ${label}{ARIA}"${active ? ' aria-current="true"' : ''} data-act="flow-jump" data-arg="${b.id}">`
            : `<button type="button" class="flow-bar-grid-tile flow-bar-detail-tile{CLS}" data-block-id="${b.id}" aria-label="Edit ${label}{ARIA}" aria-haspopup="dialog">`;
        const warning = flowRepeatBarInvalid(b) || flowIntroInvalid(b) || flowPauseInvalid(b) || flowRampInvalid(b, nextBlock);
        if (warning) {
            return `${open.replace('{CLS}', ' flow-bar-detail-tile-warning').replace('{ARIA}', ' - needs updating')}
                <span class="flow-bar-detail-head">${mark}<span class="flow-bar-detail-name">${name}</span></span>
                <span class="flow-bar-detail-mid flow-bar-detail-mid-warning">${flowWarningIconSvg('flow-bar-detail-warning-icon')}<span class="flow-bar-detail-warning-text">Update</span></span>
                <span class="flow-bar-detail-strip"></span>
            </button>`;
        }
        const { sign, startLine, endLine, endExtra, volta, intro, pauses, ramps, jump } = flowBarReadingParts(b, nextBlock);
        const strip = [volta, intro, pauses, ...ramps, jump].filter(Boolean);

        return `${open.replace('{CLS}', '').replace('{ARIA}', '')}
            <span class="flow-bar-detail-head">${sign ? `<span class="flow-bar-detail-sign">${sign}</span>` : ''}${mark}<span class="flow-bar-detail-name">${name}</span></span>
            <span class="flow-bar-detail-mid">
                <span class="flow-bar-detail-edge">${startLine}</span>
                <span class="flow-bar-detail-meter"><span class="flow-bar-detail-time">${escapeHtml(b.timeSignatureLabel || `${b.numerator}/${b.denominator}`)}</span><span class="flow-bar-detail-bpm">${b.bpm} bpm</span></span>
                <span class="flow-bar-detail-edge">${endLine}${endExtra ? `<span class="flow-bar-detail-count">${endExtra}</span>` : ''}</span>
            </span>
            <span class="flow-bar-detail-strip">${strip.join('')}</span>
        </button>`;
    }

    // --- Press-and-hold drag. The held tile stays in the DOM the whole time (moved with insertBefore,
    // never re-rendered) so the touch keeps its target and the page's scroll stays blocked; slot
    // positions are measured once when the drag starts, so a tile sliding under the finger can't
    // flip the order back and forth. On drop the array is reordered and flowAnimateBlocksChange
    // re-renders, sliding the held tile from wherever it was let go into its new slot. ---
    const FLOW_BAR_GRID_HOLD_MS = 350;
    const FLOW_BAR_GRID_HOLD_SLOP_PX = 8;
    const FLOW_BAR_GRID_EDGE_PX = 64; // auto-scroll zone at the top/bottom of the screen while dragging

    function flowBarGridStartHold(container, tile, e) {
        const rect = tile.getBoundingClientRect();
        const d = flowBarDrag = {
            container, pointerId: e.pointerId, blockId: tile.dataset.blockId,
            startX: e.clientX, startY: e.clientY, x: e.clientX, y: e.clientY,
            grabDX: e.clientX - rect.left, grabDY: e.clientY - rect.top,
            active: false, slots: [], scrollY0: 0, timer: null
        };
        d.timer = setTimeout(() => flowBarGridBeginDrag(d), FLOW_BAR_GRID_HOLD_MS);
        document.addEventListener('pointermove', flowBarGridOnMove, { passive: false });
        document.addEventListener('pointerup', flowBarGridEnd);
        document.addEventListener('pointercancel', flowBarGridEnd);
        document.addEventListener('touchmove', flowBarGridBlockScroll, { passive: false });
    }
    function flowBarGridBlockScroll(e) {
        if (flowBarDrag && flowBarDrag.active) e.preventDefault();
    }
    function flowBarGridTiles(d) { return [...d.container.querySelectorAll('.flow-bar-grid-tile')]; }
    function flowBarGridHeld(d) { return d.container.querySelector(`.flow-bar-grid-tile[data-block-id="${d.blockId}"]`); }

    function flowBarGridBeginDrag(d) {
        if (flowBarDrag !== d) return;
        const held = flowBarGridHeld(d);
        if (!held) return;
        d.active = true;
        d.scrollY0 = window.scrollY;
        d.slots = flowBarGridTiles(d).map(t => t.getBoundingClientRect());
        // ML-529: the slots it can go to - its own movement's
        d.range = flowMovementRange(flowBarGridTiles(d).indexOf(held));
        d.places = flowMovementPlaces();
        held.classList.add('flow-bar-grid-tile-held');
        flowBarGridUpdate(d);
        requestAnimationFrame(() => flowBarGridAutoScroll(d));
    }
    function flowBarGridOnMove(e) {
        const d = flowBarDrag;
        if (!d || e.pointerId !== d.pointerId) return;
        d.x = e.clientX;
        d.y = e.clientY;
        if (!d.active) {
            // Moved before the hold finished - a scroll or a tap, never a drag.
            if (Math.hypot(d.x - d.startX, d.y - d.startY) > FLOW_BAR_GRID_HOLD_SLOP_PX) flowBarGridEnd();
            return;
        }
        e.preventDefault();
        flowBarGridUpdate(d);
    }
    // Keeps the held tile under the finger and moves it to whichever slot the finger is over.
    function flowBarGridUpdate(d) {
        const held = flowBarGridHeld(d);
        if (!held) return;
        const scrolled = window.scrollY - d.scrollY0;
        const slotAt = (i) => { const r = d.slots[i]; return { left: r.left, top: r.top - scrolled, right: r.right, bottom: r.bottom - scrolled }; };
        const target = d.slots.findIndex((_, i) => {
            const r = slotAt(i);
            return d.x >= r.left && d.x <= r.right && d.y >= r.top && d.y <= r.bottom;
        });
        const tiles = flowBarGridTiles(d);
        const from = tiles.indexOf(held);
        const inRange = !d.range || (target >= d.range[0] && target <= d.range[1]);
        if (target >= 0 && target !== from && inRange) {
            const others = tiles.filter(t => t !== held);
            const before = new Map(others.map(t => [t, t.getBoundingClientRect()]));
            // At the end of a movement, it goes before the next movement's heading, not after it
            let ref = others[target] || null;
            if (ref && target !== (d.range ? d.range[0] : 0) && ref.previousElementSibling?.classList.contains('flow-movement-head')) ref = ref.previousElementSibling;
            d.container.insertBefore(held, ref);
            // FLIP the tiles that shifted: jump back to where they were, then slide to the new slot.
            others.forEach(t => {
                t.classList.remove('flow-bar-grid-tile-shuffling');
                clearMove(t);
                const prev = before.get(t);
                const now = t.getBoundingClientRect();
                if (prev.left === now.left && prev.top === now.top) return;
                setMove(t, prev.left - now.left, prev.top - now.top);
                void t.offsetWidth; // commit the inverted position before transitioning away from it
                t.classList.add('flow-bar-grid-tile-shuffling');
                clearMove(t);
            });
        }
        // Measure the held tile's real slot rather than reusing d.slots: in 2 columns rows can change
        // height as tiles move, so the recorded positions (still right for choosing a target) drift.
        clearMove(held);
        const slot = held.getBoundingClientRect();
        setMove(held, d.x - d.grabDX - slot.left, d.y - d.grabDY - slot.top);
    }
    function flowBarGridAutoScroll(d) {
        if (flowBarDrag !== d || !d.active) return;
        const edge = FLOW_BAR_GRID_EDGE_PX;
        let step = 0;
        if (d.y < edge) step = -(edge - d.y) / 4;
        else if (d.y > window.innerHeight - edge) step = (d.y - (window.innerHeight - edge)) / 4;
        if (step) {
            window.scrollBy(0, step);
            flowBarGridUpdate(d);
        }
        requestAnimationFrame(() => flowBarGridAutoScroll(d));
    }
    function flowBarGridEnd() {
        const d = flowBarDrag;
        if (!d) return;
        clearTimeout(d.timer);
        flowBarDrag = null;
        document.removeEventListener('pointermove', flowBarGridOnMove);
        document.removeEventListener('pointerup', flowBarGridEnd);
        document.removeEventListener('pointercancel', flowBarGridEnd);
        document.removeEventListener('touchmove', flowBarGridBlockScroll);
        if (!d.active) return;
        d.container.dataset.suppressNextClick = '1';
        // Fallback: not every browser fires a click after a long drag, so the flag can't wait for one.
        setTimeout(() => { delete d.container.dataset.suppressNextClick; }, 400);
        const domIds = flowBarGridTiles(d).map(t => t.dataset.blockId);
        const changed = domIds.some((id, i) => String(currentFlowBlocks[i]?.id) !== id);
        flowAnimateBlocksChange(() => {
            if (!changed) return;
            const byId = new Map(currentFlowBlocks.map(b => [String(b.id), b]));
            currentFlowBlocks = domIds.map(id => byId.get(id)).filter(Boolean);
            if (d.places) flowRestoreMovementPlaces(d.places);
        }, { raiseUid: d.blockId });
        if (changed) flowPersistBlockOrder();
    }

    // --- Bar popup ---
    function openFlowBarPopup(blockId) {
        flowBarPopupBlockId = blockId;
        renderFlowBarPopup();
        showModal('flowBarPopupModal');
    }
    function closeFlowBarPopup() {
        flowBarPopupBlockId = null;
        const modal = document.getElementById('flowBarPopupModal');
        hideModal(modal);
    }
    function renderFlowBarPopup() {
        const content = document.getElementById('flowBarPopupContent');
        if (!content || flowBarPopupBlockId === null) return;
        const idx = currentFlowBlocks.findIndex(b => b.id === flowBarPopupBlockId);
        // Deleted, or a different Flow loaded underneath - nothing left to show.
        if (idx < 0 || flowBarLayout === '1') { closeFlowBarPopup(); return; }
        const b = currentFlowBlocks[idx];
        const first = idx === 0;
        const last = idx === currentFlowBlocks.length - 1;
        // Re-rendering replaces every button, so put keyboard focus back on the one that was used.
        const focusedAction = content.contains(document.activeElement) ? document.activeElement.dataset.barPopup : null;
        const icon = (name) => `<span class="material-symbols-outlined">${name}</span>`;
        content.innerHTML = `
            <div class="flow-bar-popup-header">
                <button type="button" class="flow-bar-popup-icon-btn" data-bar-popup="prev" aria-label="Previous bar"${first ? ' disabled' : ''}>${icon('chevron_left')}</button>
                ${flowBlockMarkBoxHtml(b)}
                <div class="flow-bar-popup-title">
                    <span class="flow-block-name" id="flowBarPopupTitle">${flowBarPopupRangeLabel(idx).replace('–', '⁠–⁠') /* ML-606: wraps as "Bars" over "473–487", never after the dash */}</span>
                    <span class="flow-bar-popup-pos">${idx + 1} of ${currentFlowBlocks.length}</span>
                </div>
                <button type="button" class="flow-bar-popup-icon-btn" data-bar-popup="next" aria-label="Next bar"${last ? ' disabled' : ''}>${icon('chevron_right')}</button>
                <button type="button" class="flow-bar-popup-icon-btn flow-bar-popup-close" data-bar-popup="close" data-modal-close aria-label="Close">${icon('close')}</button>
            </div>
            ${flowBlockTileSectionsHtml(b, currentFlowBlocks[idx + 1])}
            <div class="flow-tile-grid flow-tile-grid-3-centered flow-bar-popup-actions">
                <button type="button" class="flow-bar-popup-action" data-bar-popup="earlier"${flowCanMoveUp(idx) ? '' : ' disabled'}>Move earlier</button>
                <button type="button" class="flow-bar-popup-action" data-bar-popup="duplicate">Duplicate</button>
                <button type="button" class="flow-bar-popup-action" data-bar-popup="later"${flowCanMoveDown(idx) ? '' : ' disabled'}>Move later</button>
            </div>
            ${currentFlowBlocks.length > 1 ? '<button type="button" class="btn-text btn-text-danger flow-bar-popup-delete" data-bar-popup="delete">Delete this bar</button>' : ''}
        `;
        content.querySelectorAll('[data-block-tile]').forEach(btn => {
            btn.addEventListener('click', () => handleFlowBlockTileClick(b.id, btn.dataset.blockTile));
        });
        content.querySelectorAll('[data-bar-popup]').forEach(btn => {
            btn.addEventListener('click', () => flowBarPopupAction(btn.dataset.barPopup));
        });
        if (focusedAction) {
            const again = content.querySelector(`[data-bar-popup="${focusedAction}"]:not([disabled])`);
            (again || content).focus({ preventScroll: true });
        }
    }
    // "Bars 9–14" rather than the card's "Bars 9 to 14" - the popup header also holds ‹, › and ✕, and
    // the shorter form is what keeps "+ RM" from being squeezed on a 390px phone.
    function flowBarPopupRangeLabel(index) {
        const { start, end } = flowBlockBarRange(index);
        return start === end ? `Bar ${start}` : `Bars ${start}–${end}`;
    }
    function flowBarPopupAction(action) {
        const blockId = flowBarPopupBlockId;
        const idx = currentFlowBlocks.findIndex(b => b.id === blockId);
        if (idx < 0) return;
        if (action === 'close') closeFlowBarPopup();
        else if (action === 'prev' && idx > 0) { flowBarPopupBlockId = currentFlowBlocks[idx - 1].id; renderFlowBarPopup(); }
        else if (action === 'next' && idx < currentFlowBlocks.length - 1) { flowBarPopupBlockId = currentFlowBlocks[idx + 1].id; renderFlowBarPopup(); }
        else if (action === 'earlier') flowMoveBlockUp(blockId);
        else if (action === 'later') flowMoveBlockDown(blockId);
        else if (action === 'duplicate') flowDuplicateBlock(blockId);
        else if (action === 'delete') flowDeleteBlockConfirm(blockId); // the popup closes itself once the bar's gone
    }

    // --- Block card reorder/delete gestures - directly mirrors Quick Play's own bar-box gestures
    // (wireQpBarGrabHandle/wireQpBarSwipe): reordering is a single-step move (same as the 3-dot
    // menu's own Move up/down), scoped strictly to the small grab handle so it never competes with
    // the page's vertical scroll; deleting is a horizontal swipe that only ever intercepts the
    // gesture once it's confirmed horizontal (>30px horizontal travel while vertical travel is still
    // under 15px) - a clearly-vertical drag before that point is left alone entirely so the browser's
    // own touch-action:pan-y scroll handles it, same reasoning as Quick Play's own. ---
    // Raw position swap (no bounds checking) - the one place the actual array mutation for a move
    // happens, animated via flowAnimateBlocksChange (FLIP) so the displaced block visibly slides into
    // its new spot instead of the re-render just snapping it there - same "swap, don't just rebuild"
    // shape as Quick Play's own qpSwapBarPositions.
    // --- ML-529: a piece in movements. A bar is moved only within its own movement (owner, 19 Oct 2026), and where
    // a movement starts belongs to the place, not the bar: after a move, the bar now first in a movement starts it
    // and carries its name. ---
    // The block indexes [first, last] of the movement block i is in (the whole piece when it has none).
    function flowMovementRange(i) {
        const m = FlowJourney.movements(currentFlowBlocks).find(x => i >= x.startBlock && i <= x.endBlock);
        return m ? [m.startBlock, m.endBlock] : [0, currentFlowBlocks.length - 1];
    }
    const flowSameMovement = (i, j) => { const [s, e] = flowMovementRange(i); return j >= s && j <= e; };
    // Where each movement starts, by position, to put back after the order changes
    function flowMovementPlaces() {
        return FlowJourney.movements(currentFlowBlocks).map(m => ({ at: m.startBlock, start: !!currentFlowBlocks[m.startBlock].movementStart, title: currentFlowBlocks[m.startBlock].movementTitle || null }));
    }
    function flowRestoreMovementPlaces(places) {
        const changed = [];
        currentFlowBlocks.forEach((b, k) => {
            const p = places.find(x => x.at === k);
            const start = p ? p.start : false, title = p ? p.title : null;
            if (!!b.movementStart !== start || (b.movementTitle || null) !== title) { b.movementStart = start; b.movementTitle = title; changed.push(b); }
        });
        // Outside the staged edit, each bar is saved as it changes
        if (flowEditMode !== 'edit') changed.forEach(b => API.flows.blocks.update(b.id, { movementStart: b.movementStart, movementTitle: b.movementTitle }).catch(error => showWarningToast('Error saving the movement: ' + error.message)));
    }
    function flowSwapBlockPositions(i, j) {
        if (!flowSameMovement(i, j)) return;
        const movedId = currentFlowBlocks[i].id;
        const places = flowMovementPlaces();
        flowAnimateBlocksChange(() => {
            [currentFlowBlocks[i], currentFlowBlocks[j]] = [currentFlowBlocks[j], currentFlowBlocks[i]];
            flowRestoreMovementPlaces(places);
        }, { raiseUid: movedId });
        flowPersistBlockOrder();
    }
    // Can block idx move earlier / later? Not past the start or end of the piece, or of its movement.
    const flowCanMoveUp = (idx) => idx > 0 && flowSameMovement(idx, idx - 1);
    const flowCanMoveDown = (idx) => idx >= 0 && idx < currentFlowBlocks.length - 1 && flowSameMovement(idx, idx + 1);
    function flowMoveBlockUp(blockId) {
        const idx = currentFlowBlocks.findIndex(b => b.id === blockId);
        if (!flowCanMoveUp(idx)) return;
        flowSwapBlockPositions(idx, idx - 1);
    }
    function flowMoveBlockDown(blockId) {
        const idx = currentFlowBlocks.findIndex(b => b.id === blockId);
        if (!flowCanMoveDown(idx)) return;
        flowSwapBlockPositions(idx, idx + 1);
    }
    // Same confirm-before-delete flow the 3-dot menu's own Delete item already used - shared so the
    // swipe-revealed delete button below behaves identically, not a lighter no-confirm shortcut.
    function flowDeleteBlockConfirm(blockId) {
        showConfirmModal('Delete bar', "Delete this bar? This can't be undone.", async () => {
            // ML-529: a movement keeps its start and name when its first bar is deleted - the next bar in it takes them
            const idx = currentFlowBlocks.findIndex(b => b.id === blockId);
            const places = flowMovementPlaces().filter(p => p.at !== idx || flowMovementRange(idx)[1] > idx).map(p => (p.at > idx ? { ...p, at: p.at - 1 } : p));
            const keepPlaces = () => flowRestoreMovementPlaces(places);
            if (flowEditMode === 'edit') {
                currentFlowBlocks = currentFlowBlocks.filter(b => b.id !== blockId);
                keepPlaces();
                flowStatsNoteBlockDeleted();
                renderFlowBlocksStudio();
                return;
            }
            try {
                await API.flows.blocks.delete(blockId);
                currentFlowBlocks = currentFlowBlocks.filter(b => b.id !== blockId);
                keepPlaces();
                flowStatsNoteBlockDeleted();
                renderFlowBlocksStudio(); // not just renderFlowBlocksList - the total bars/runtime summary needs refreshing too
            } catch (error) {
                showWarningToast('Error deleting bar: ' + error.message);
            }
        }, true);
    }

    const FLOW_BLOCK_REORDER_THRESHOLD_PX = 40;
    const FLOW_BLOCK_SWIPE_LOCK_X_PX = 30;
    const FLOW_BLOCK_SWIPE_LOCK_Y_MAX_PX = 15;
    const FLOW_BLOCK_SWIPE_OPEN_PX = 96; // keep in sync with .flow-block-delete-underlay's width in style.css
    const FLOW_BLOCK_SWIPE_SNAP_THRESHOLD_PX = 48;
    const FLOW_BLOCK_SWIPE_EXCLUDE_SELECTOR = 'button, input, [role="slider"], [role="button"], .slider-track, .slider-thumb';

    function flowBlockSurfaceFor(blockId) {
        return document.querySelector(`.flow-block-box[data-block-id="${blockId}"] .flow-block-card`);
    }
    function flowSetSwipeOffset(blockId, offset, animate) {
        const surface = flowBlockSurfaceFor(blockId);
        if (!surface) return;
        swipeTo(surface, offset, animate);
    }
    function flowCloseOpenSwipe(animate = true) {
        if (flowOpenSwipeBlockId === null) return;
        flowSetSwipeOffset(flowOpenSwipeBlockId, 0, animate);
        flowOpenSwipeBlockId = null;
    }
    // Tapping anywhere outside an open card snaps it back - a document-level listener rather than a
    // per-card blur/outside-click check, same pattern as closeQpBarMenu/qpOpenSwipeIndex's own.
    // a11y: closes an open swipe card when tapping elsewhere - harmless and reversible, not an activation (WCAG 2.5.2)
    document.addEventListener('pointerdown', (e) => {
        if (flowOpenSwipeBlockId === null) return;
        const openBoxEl = document.querySelector(`.flow-block-box[data-block-id="${flowOpenSwipeBlockId}"]`);
        if (openBoxEl && !openBoxEl.contains(e.target)) flowCloseOpenSwipe();
    });

    // Vertical reordering, scoped strictly to the grab handle. Single-step swap
    // (flowMoveBlockUp/Down), same as the menu's own Move up/down - this is about where the gesture
    // is allowed to start, not a full drag-to-arbitrary-position sortable list. wireVerticalDragHandle
    // (shared with Quick Play's own wireQpBarGrabHandle) owns the actual gesture/animation handoff.
    function wireFlowBlockGrabHandle(handleEl, boxEl, blockId) {
        wireVerticalDragHandle(handleEl, boxEl, FLOW_BLOCK_REORDER_THRESHOLD_PX,
            () => flowMoveBlockUp(blockId), () => flowMoveBlockDown(blockId), '.flow-block-card');
    }

    // Horizontal swipe-to-reveal delete. Doesn't touch anything (no transform, no preventDefault)
    // until the gesture actually locks into "this is a horizontal swipe" - a clearly-vertical drag
    // before that point is treated as a scroll attempt and left alone entirely.
    function wireFlowBlockSwipe(boxEl, blockId) {
        const surfaceEl = boxEl.querySelector('.flow-block-card');
        let startX = 0, startY = 0, tracking = false, locked = false, abandoned = false;

        function currentBaseOffset() { return flowOpenSwipeBlockId === blockId ? -FLOW_BLOCK_SWIPE_OPEN_PX : 0; }

        function onMove(e) {
            if (!tracking || abandoned) return;
            const dx = e.clientX - startX;
            const dy = e.clientY - startY;
            if (!locked) {
                if (Math.abs(dx) > FLOW_BLOCK_SWIPE_LOCK_X_PX && Math.abs(dy) < FLOW_BLOCK_SWIPE_LOCK_Y_MAX_PX) {
                    locked = true;
                    // Only one card open at a time - starting a fresh swipe elsewhere closes any other.
                    if (flowOpenSwipeBlockId !== null && flowOpenSwipeBlockId !== blockId) flowCloseOpenSwipe(false);
                } else if (Math.abs(dy) >= FLOW_BLOCK_SWIPE_LOCK_Y_MAX_PX) {
                    abandoned = true; // a scroll, not a swipe - stop tracking, never transform
                    return;
                } else {
                    return; // not enough travel yet either way
                }
            }
            e.preventDefault();
            const offset = Math.min(0, Math.max(-FLOW_BLOCK_SWIPE_OPEN_PX, currentBaseOffset() + dx));
            swipeTo(surfaceEl, offset, false, true);
        }
        function onUp(e) {
            if (!tracking) return;
            tracking = false;
            document.removeEventListener('pointermove', onMove);
            document.removeEventListener('pointerup', onUp);
            if (!locked) return;
            const dx = e.clientX - startX;
            const finalOffset = Math.min(0, Math.max(-FLOW_BLOCK_SWIPE_OPEN_PX, currentBaseOffset() + dx));
            if (Math.abs(finalOffset) > FLOW_BLOCK_SWIPE_SNAP_THRESHOLD_PX) {
                flowSetSwipeOffset(blockId, -FLOW_BLOCK_SWIPE_OPEN_PX, true);
                flowOpenSwipeBlockId = blockId;
            } else {
                flowSetSwipeOffset(blockId, 0, true);
                if (flowOpenSwipeBlockId === blockId) flowOpenSwipeBlockId = null;
            }
        }
        // a11y: only records where a swipe/drag gesture starts - nothing activates on press (WCAG 2.5.2)
        boxEl.addEventListener('pointerdown', (e) => {
            if (e.target.closest(FLOW_BLOCK_SWIPE_EXCLUDE_SELECTOR)) return;
            startX = e.clientX;
            startY = e.clientY;
            tracking = true;
            locked = false;
            abandoned = false;
            document.addEventListener('pointermove', onMove);
            document.addEventListener('pointerup', onUp);
        });
        boxEl.querySelector('[data-block-delete-btn]')?.addEventListener('click', (e) => {
            e.stopPropagation();
            flowOpenSwipeBlockId = null;
            flowDeleteBlockConfirm(blockId);
        });
    }

    // --- Generic choice-list modal - every discrete-option tile shares this one modal rather
    // than each getting its own bespoke picker. An option can pass `html` instead of `label` for
    // cases that need more than plain escaped text (the jump tile's inline segno/coda glyphs). An
    // option with `extra(el, close)` needs more than a tap (ML-400's "+ New practice list" - its name):
    // picking it keeps the pop-up open and turns its row into a box (the same selected look, stacked -
    // .plan-card) holding the row's words and, under them, its own fields and Save, so it's plain what
    // they belong to (owner, 3 Oct 2026); it calls close() itself when it's done. ---
    function openFlowChoiceModal(title, options, onSelect) {
        document.getElementById('flowChoiceTitle').innerText = title;
        const inlineExtra = document.getElementById('flowChoiceInlineExtra');
        inlineExtra.classList.add('hidden-group');
        inlineExtra.innerHTML = '';
        const container = document.getElementById('flowChoiceOptions');
        container.innerHTML = options.map((opt, i) => `
            <button type="button" class="flow-choice-option${opt.selected ? ' selected' : ''}" data-choice-idx="${i}" aria-pressed="${!!opt.selected}">
                ${opt.html ? opt.html : `<span>${escapeHtml(opt.label)}</span>`}
                ${opt.selected && !opt.html ? '<span class="material-symbols-outlined" aria-hidden="true">check</span>' : ''}
            </button>
        `).join('');
        container.querySelectorAll('[data-choice-idx]').forEach(el => {
            el.addEventListener('click', () => {
                const opt = options[Number(el.dataset.choiceIdx)];
                if (opt.extra) {
                    container.querySelectorAll('[data-choice-idx]').forEach(o => { o.classList.remove('selected'); o.setAttribute('aria-pressed', 'false'); });
                    const box = document.createElement('div');
                    box.className = 'flow-choice-option plan-card selected';
                    box.setAttribute('role', 'group');
                    box.setAttribute('aria-label', el.innerText.split('\n')[0].trim());
                    box.innerHTML = `${opt.html ? opt.html : `<span>${escapeHtml(opt.label)}</span>`}<div></div>`;
                    el.replaceWith(box);
                    opt.extra(box.lastElementChild, () => hideModal('flowChoiceModal'));
                    return;
                }
                hideModal('flowChoiceModal');
                onSelect(opt);
            });
        });
        filterPanelOpen = null; // ML-595: the choice pop-up is something else now
        document.getElementById('flowChoiceCancelBtn').textContent = 'Cancel';
        showModal('flowChoiceModal');
    }
    function closeFlowChoiceModal() {
        hideModal('flowChoiceModal');
    }
    // Closes on its X, Cancel, or a tap on the backdrop (ML-400 - as the other pop-ups).
    document.getElementById('flowChoiceModal')?.addEventListener('click', (e) => { if (e.target === e.currentTarget) closeFlowChoiceModal(); });

    // --- A choice list you can search (ML-517): the same pop-up as openFlowChoiceModal, for a list too long
    // to scroll - every instrument, every band in the directory. items: [{ label, sub, group, value }] in
    // the order to show them (a group's name is a heading above its first item). The box at the top narrows
    // the list as you type; with nothing typed a long list shows its first rows and says how many more
    // there are. opts.other is one last row that needs typing ("My band isn't on the list") - it grows its
    // own box in the pop-up, as an 'extra' option does: { label, sub, build(el, close) }.
    const SEARCH_CHOICE_ROWS = 40;
    function openSearchChoiceModal(title, items, onSelect, opts = {}) {
        document.getElementById('flowChoiceTitle').innerText = title;
        const inlineExtra = document.getElementById('flowChoiceInlineExtra');
        inlineExtra.classList.add('hidden-group');
        inlineExtra.innerHTML = '';
        const container = document.getElementById('flowChoiceOptions');
        container.innerHTML = `<input type="search" class="mb-4" id="flowChoiceSearch" placeholder="${escapeHtml(opts.placeholder || 'Search')}" aria-label="${escapeHtml(opts.placeholder || 'Search')}" autocomplete="off"><div id="flowChoiceSearchList"></div>`;
        const input = document.getElementById('flowChoiceSearch');
        const list = document.getElementById('flowChoiceSearchList');
        const words = (it) => `${it.label} ${it.sub || ''} ${it.group || ''}`.toLowerCase();
        const draw = () => {
            const q = input.value.trim().toLowerCase();
            const hits = items.filter(it => !q || q.split(/\s+/).every(w => words(it).includes(w)));
            const shown = q ? hits.slice(0, SEARCH_CHOICE_ROWS * 2) : hits.slice(0, opts.all ? hits.length : SEARCH_CHOICE_ROWS);
            let group = null;
            list.innerHTML = shown.map(it => {
                const head = it.group && it.group !== group ? `<span class="flow-tile-section-label">${escapeHtml(it.group)}</span>` : '';
                group = it.group || group;
                return `${head}<button type="button" class="flow-choice-option${it.selected ? ' selected' : ''}" data-search-idx="${items.indexOf(it)}" aria-pressed="${!!it.selected}">${it.sub ? addPieceRow(it.label, it.sub) : `<span><strong>${escapeHtml(it.label)}</strong></span>`}${it.selected ? '<span class="material-symbols-outlined" aria-hidden="true">check</span>' : ''}</button>`;
            }).join('')
                + (hits.length > shown.length ? `<p class="text-sm text-muted">${hits.length - shown.length} more - type a few letters to find one.</p>` : '')
                + (hits.length ? '' : '<p class="text-sm text-muted">Nothing matches that.</p>')
                + (opts.other ? `<button type="button" class="flow-choice-option" data-search-other>${addPieceRow(opts.other.label, opts.other.sub || '')}</button>` : '');
        };
        input.addEventListener('input', draw);
        list.onclick = (e) => {
            const other = e.target.closest('[data-search-other]');
            if (other) {
                const box = document.createElement('div');
                box.className = 'flow-choice-option plan-card selected';
                box.setAttribute('role', 'group');
                box.setAttribute('aria-label', opts.other.label);
                box.innerHTML = `${addPieceRow(opts.other.label, opts.other.sub || '')}<div></div>`;
                other.replaceWith(box);
                opts.other.build(box.lastElementChild, () => hideModal('flowChoiceModal'), input.value.trim());
                return;
            }
            const row = e.target.closest('[data-search-idx]');
            if (!row) return;
            hideModal('flowChoiceModal');
            onSelect(items[Number(row.dataset.searchIdx)]);
        };
        draw();
        filterPanelOpen = null; // ML-595: the choice pop-up is something else now
        document.getElementById('flowChoiceCancelBtn').textContent = 'Cancel';
        showModal('flowChoiceModal');
    }

    // ---------------------------------------------------------------- SET-UP (ML-517)
    // Three short steps the first time a new member signs in - what they play, how the app looks, who they
    // play with - so the app suits them from the start. Decided with the owner on 12 Oct 2026:
    //  - every step can be left empty: Next just carries on, and nothing here is asked twice;
    //  - it is a page, not a pop-up that must be answered - the < at the top (or the menu) leaves it;
    //  - finishing or leaving it marks it done on the account (accounts.setup_done_on), so it never comes up
    //    by itself again; "Set up again" in Settings goes through it whenever you like;
    //  - each choice is saved as it is made, by the code that My instruments, Display and reading and
    //    My bands already use - set-up keeps nothing of its own;
    //  - range is left out for now, and the bands step stops at "on my own list" (private): it never leads
    //    into sharing. The switch is member_setup. specs/components/setup.md.
    const SETUP_STEPS = [
        { key: 'play', name: 'What I play', next: 'how it looks', question: 'What do you play?' },
        { key: 'look', name: 'How it looks', next: 'who I play with', question: 'How do you like it to look?' },
        { key: 'bands', name: 'Who I play with', next: null, question: 'Who do you play with?' }
    ];
    let setup = null; // { step, first } while the page is open - first: it came up by itself after signing in
    const setupOn = () => isFeatureEnabled('member_setup');
    const setupValueBox = (act, value, label) => `<button type="button" class="metroBlk-ctrl-value-btn w-full" data-setup="${act}" aria-haspopup="dialog"><strong>${escapeHtml(value)}</strong><span class="metroBlk-ctrl-value-label">${escapeHtml(label)}</span></button>`;
    const SETUP_LOOK = {
        theme: { label: 'light or dark', title: 'Light or dark?', key: 'darkMode', options: [[false, 'Light', 'Dark words on a light page'], [true, 'Dark', 'Light words on a dark page']] },
        textSize: { label: 'text size', title: 'Text size', key: 'textSize', options: [['standard', 'Standard', ''], ['large', 'Large', ''], ['larger', 'Extra large', '']] },
        font: { label: 'font', title: 'Font', key: 'font', options: [['standard', 'Standard', 'The app\'s own'], ['lexend', 'Lexend', 'Wider letters, made to be easier to read'], ['opendyslexic', 'OpenDyslexic', 'Weighted letters, made for dyslexic readers']] },
        background: { label: 'background tint', title: 'Background tint', key: 'background', options: [['standard', 'Standard', ''], ['cream', 'Cream', ''], ['blue', 'Pale blue', ''], ['green', 'Pale green', ''], ['yellow', 'Soft yellow', ''], ['peach', 'Peach', '']] }
    };
    const setupLookValue = (id) => { const c = SETUP_LOOK[id]; return (c.options.find(([v]) => v === displayPrefs[c.key]) || c.options[0])[1]; };
    const setupMain = () => (myInstruments || []).find(i => i.isPrimary) || (myInstruments || [])[0] || null;
    const setupNeedsName = () => !((accountProfile && accountProfile.firstName) || '').trim();
    function setupPlayHtml() {
        const main = setupMain();
        const hello = setup.first
            ? `Welcome${accountProfile && (accountProfile.displayName || accountProfile.firstName) ? `, ${escapeHtml(accountProfile.displayName || accountProfile.firstName)}` : ''}. Three quick things so the app suits you. Leave any of them empty - you can come back to this in Settings.`
            : 'Change anything here - each choice is saved as you make it.';
        return `
            <p class="text-sm text-muted no-margin">${hello}</p>
            ${setupNeedsName() || setup.nameAsked ? `<div class="form-group no-margin"><label for="setupFirstName">My first name</label><input type="text" id="setupFirstName" autocomplete="given-name" maxlength="60" value="${escapeHtml((accountProfile && accountProfile.firstName) || '')}"></div>` : ''}
            ${setupValueBox('instrument', main ? main.name : 'Choose', 'my instrument')}
            ${instrumentHasClefChoice(main) ? setupValueBox('clef', CLEF_NAMES[main.theoryClef] || main.theoryClef, 'the clef I read') : ''}
            <p class="text-sm text-muted no-margin">${(myInstruments || []).length > 1 ? `You also play ${escapeHtml(myInstruments.filter(i => i !== main).map(i => i.name).join(', '))}. ` : ''}Play more than one? Add the others in My instruments, on the menu.</p>`;
    }
    function setupLookHtml() {
        return `
            <p class="text-sm text-muted no-margin">Each choice shows straight away. There is more in My app settings, under Display and reading.</p>
            <div class="outline-pair">${['theme', 'textSize', 'font', 'background'].map(id => setupValueBox(`look:${id}`, setupLookValue(id), SETUP_LOOK[id].label)).join('')}</div>
            <div class="display-toggle-row">
                <span id="setupSpacingLabel">More space between lines and letters<span class="display-toggle-help">And no italics</span></span><label class="toggle-switch"><input type="checkbox" id="setupSpacing" aria-labelledby="setupSpacingLabel"${displayPrefs.dyslexia ? ' checked' : ''}><span class="toggle-slider"></span></label>
            </div>
            <div class="display-toggle-row">
                <span id="setupMotionLabel">Reduce motion<span class="display-toggle-help">${escapeHtml(motionHelpText())}</span></span><label class="toggle-switch"><input type="checkbox" id="setupMotion" aria-labelledby="setupMotionLabel"${displayPrefs.reduceMotion ? ' checked' : ''}><span class="toggle-slider"></span></label>
            </div>`;
    }
    function setupBandsHtml() {
        const mine = myBandsShown();
        return `
            <p class="text-sm text-muted no-margin">The bands or groups you play with. This list is private to you: it is who you can say a rehearsal or a performance was with.</p>
            ${mine.map(b => `<div class="history-item"><span class="grow"><strong>${escapeHtml(b.displayName || b.name)}</strong></span><span class="material-symbols-outlined" aria-hidden="true">check</span></div>`).join('')}
            <button type="button" class="outline-add" data-setup="band" aria-haspopup="dialog">+ ${mine.length ? 'Add another band' : 'Add a band'}</button>`;
    }
    function renderSetup() {
        if (!setup) return;
        const total = SETUP_STEPS.length, cur = SETUP_STEPS[setup.step];
        const bar = document.getElementById('setupBar');
        bar.setAttribute('aria-label', `Step ${setup.step + 1} of ${total}: ${cur.name}`);
        bar.innerHTML = SETUP_STEPS.map((s, i) => `<span class="step-bar-piece${i < setup.step ? ' is-done' : i === setup.step ? ' is-now' : ''}"></span>`).join('');
        document.getElementById('setupWhereText').innerHTML = `<strong>${escapeHtml(cur.name)}</strong> · step ${setup.step + 1} of ${total}`;
        document.getElementById('setupQuestion').textContent = cur.question;
        document.getElementById('setupBody').innerHTML = { play: setupPlayHtml, look: setupLookHtml, bands: setupBandsHtml }[cur.key]();
        document.getElementById('setupFoot').innerHTML = `${setup.step > 0 ? '<button type="button" class="btn-cancel btn-nav no-margin" data-setup="back">Back</button>' : ''}<button type="button" class="btn-submit no-margin" data-setup="next">${cur.next ? `Next: ${cur.next}` : 'Finish'}</button>`;
    }
    // Redraws the step and puts the keyboard back on the button that was used (its pop-up has closed)
    function setupRedraw(act) {
        renderSetup();
        if (act) document.querySelector(`#setupView [data-setup="${act}"]`)?.focus();
    }
    // The name box is saved on the way out of its step - only if something was typed and it has changed
    async function setupSaveName() {
        const box = document.getElementById('setupFirstName');
        if (!box) return;
        const typed = box.value.trim();
        if (!typed || typed === ((accountProfile && accountProfile.firstName) || '')) return;
        try {
            await API.account.update({ firstName: typed });
            accountProfile = { ...(accountProfile || {}), firstName: typed };
            renderHomeGreeting();
        } catch (error) { showWarningToast('Name not saved: ' + error.message); }
    }
    async function setupPickInstrument() {
        try { if (!instrumentCatalogue) instrumentCatalogue = await API.instruments.list(); }
        catch (error) { showWarningToast('Instruments not loaded: ' + error.message); return; }
        const main = setupMain();
        openSearchChoiceModal('What do you play?', instrumentCatalogue.map(i => ({ label: i.name, group: i.family, value: i.id, selected: !!main && main.id === i.id })), async (it) => {
            // the one chosen becomes the main instrument; any others already on the list stay
            const ids = [...new Set([...(myInstruments || []).map(i => i.id), it.value])];
            try { myInstruments = await API.account.setInstruments(ids, it.value); }
            catch (error) { showWarningToast('Instrument not saved: ' + error.message); }
            setupRedraw('instrument');
        }, { placeholder: 'Search instruments', all: true });
    }
    function setupPickLook(id) {
        const c = SETUP_LOOK[id];
        openFlowChoiceModal(c.title, c.options.map(([value, title, sub]) => ({ value, selected: displayPrefs[c.key] === value, html: sub ? addPieceRow(title, sub) : `<span><strong>${title}</strong></span>` })), async (opt) => {
            await saveDisplayPrefs({ [c.key]: opt.value });
            setupRedraw(`look:${id}`);
        });
    }
    async function setupPickBand() {
        const mineIds = new Set(myBandsShown().map(b => b.directoryBandId));
        const items = (accountBandsData.allBands || []).filter(b => !mineIds.has(b.id))
            .map(b => ({ label: b.listName || b.displayName, sub: [b.town, b.parentName ? `part of ${b.parentName}` : ''].filter(Boolean).join(' · '), value: b.id }))
            .sort((a, b) => a.label.localeCompare(b.label, 'en', { sensitivity: 'base' }));
        const added = async (work) => {
            try { await work(); await loadAccountBands(); }
            catch (error) { showWarningToast('Band not added: ' + error.message); }
            setupRedraw('band');
        };
        openSearchChoiceModal('Who do you play with?', items, (it) => added(() => API.account.joinBand(it.value)), {
            placeholder: 'Search bands by name or town',
            other: {
                label: 'My band isn\'t on the list', sub: 'Type its name',
                build(el, close, typed) {
                    el.innerHTML = '<div class="form-group"><label for="setupNewBandName">Band name</label><input type="text" id="setupNewBandName" maxlength="120" autocomplete="off"></div><button type="button" class="btn-submit no-margin" id="setupNewBandAdd">Add it</button>';
                    const box = el.querySelector('#setupNewBandName');
                    box.value = typed || '';
                    box.focus();
                    el.querySelector('#setupNewBandAdd').addEventListener('click', () => {
                        const name = box.value.trim();
                        if (!name) { showWarningToast('Type the band\'s name.'); box.focus(); return; }
                        close();
                        added(() => API.account.addBand(name, ''));
                    });
                }
            }
        });
    }
    // Opens set-up. first: it came up by itself for a new member (the welcome says so).
    async function openSetup(first) {
        setup = { step: 0, first: !!first, nameAsked: false };
        window.Usage?.begin('setup'); // ML-22: finished if Finish is pressed
        setup.nameAsked = setupNeedsName();
        switchView('setupView');
        // what each step shows, fresh: my instruments, and my bands with the directory to pick from
        await Promise.all([loadMyInstruments(), API.account.getBands().then(d => { accountBandsData = d; }).catch(() => {})]);
        if (setup) renderSetup();
    }
    // Leaving set-up, by Finish or any other way: the name box is kept, and the account is marked so it
    // doesn't come up by itself again.
    function setupLeft() {
        if (!setup) return;
        setupSaveName();
        setup = null;
        if (accountProfile && !accountProfile.setupDoneOn) {
            accountProfile.setupDoneOn = new Date().toISOString().slice(0, 10);
            apiCall('/api/account/setup-done', 'POST').catch(() => { /* it comes up once more next time */ });
        }
    }
    // After signing in: a new member who hasn't seen set-up goes to it. Needs a connection (every choice is
    // saved on the account), and never gets in the way of a band's invitation, which opens My bands instead -
    // or, with band_welcome on, the band's welcome, which starts set-up as soon as they join (ML-534).
    async function maybeStartSetup() {
        if (!setupOn() || !navigator.onLine) return;
        try {
            if (!accountProfile) accountProfile = await API.account.get();
            if (accountProfile.setupDoneOn) return;
            openSetup(true);
        } catch (e) { /* not this time */ }
    }
    document.getElementById('setupView')?.addEventListener('click', async (e) => {
        const t = e.target.closest('[data-setup]');
        if (!t || !setup) return;
        const act = t.dataset.setup;
        if (act === 'instrument') return setupPickInstrument();
        if (act === 'clef') return openInstrumentClefChoice(setupMain(), () => setupRedraw('clef'));
        if (act.startsWith('look:')) return setupPickLook(act.slice(5));
        if (act === 'band') return setupPickBand();
        if (act === 'back' || act === 'next') {
            await setupSaveName();
            if (!setup) return;
            if (act === 'next' && setup.step === SETUP_STEPS.length - 1) {
                const first = setup.first;
                switchView('mainView'); // (leaving the page is what marks it done - setupLeft)
                window.Usage?.finish('setup');
                showSuccessToast(first ? 'All set. Welcome!' : 'All set.');
                return;
            }
            setup.step += act === 'next' ? 1 : -1;
            renderSetup();
            window.scrollTo({ top: 0 });
            document.getElementById('setupQuestion')?.focus();
        }
    });
    document.getElementById('setupView')?.addEventListener('change', async (e) => {
        if (!setup) return;
        if (e.target.id === 'setupSpacing') await saveDisplayPrefs({ dyslexia: e.target.checked });
        if (e.target.id === 'setupMotion') { await saveDisplayPrefs({ reduceMotion: e.target.checked }); setupRedraw(); document.getElementById('setupMotion')?.focus(); }
    });
    document.getElementById('settingsSetupLink')?.addEventListener('click', () => openSetup(false));

    // --- Repeat bar / volta - which repeat pass(es) (1-9) this bar plays on, multi-select rather
    // than the old binary 1st/2nd pair (some pieces use a section on passes 1, 3, 5 and a different
    // one on 2, 4 - see db/migrations/034_repeat_ending_numbers.sql), plus which bar (within this
    // block) a multi-bar ending starts at (037_volta_start_bar.sql). Own modal/state, own Save -
    // never written until committed, same reasoning as every other picker here. The toggle is
    // presentation only (hides/shows the fields below); what actually gets saved is derived from it
    // on Save, not stored as its own field. ---
    let flowRepeatBarTargetId = null;
    let flowRepeatBarDraft = null; // { on, startBar, maxBar, numbers: Set }

    function renderFlowRepeatBarModal() {
        const draft = flowRepeatBarDraft;
        if (!draft) return;
        document.getElementById('flowRepeatBarToggle').checked = draft.on;
        document.getElementById('flowRepeatBarFields').classList.toggle('hidden-group', !draft.on);
        // Both halves are required together once the volta's switched on - a start bar with no
        // repeat pass (or vice versa) isn't a usable alternate ending.
        document.getElementById('flowRepeatBarSaveBtn').disabled = draft.on && draft.numbers.size === 0;
        if (!draft.on) return;

        const invalid = draft.startBar > draft.maxBar;
        const valueEl = document.getElementById('flowRepeatBarStartValue');
        valueEl.classList.toggle('flow-bar-readout-invalid', invalid);
        // "of Y" is this block's own bar count - shows how far the ending could run without leaving
        // the block, not just the raw start-bar number on its own.
        const startText = `Bar ${draft.startBar} of ${draft.maxBar}`;
        valueEl.innerHTML = invalid ? `${flowWarningIconSvg('flow-warning-icon')}${startText}` : startText;

        const grid = document.getElementById('flowRepeatBarPassesGrid');
        grid.innerHTML = Array.from({ length: 9 }, (_, i) => i + 1).map(n => `
            <button type="button" class="flow-multiselect-num${draft.numbers.has(n) ? ' selected' : ''}" data-pass="${n}">${n}</button>
        `).join('');
        grid.querySelectorAll('[data-pass]').forEach(btn => {
            btn.addEventListener('click', () => {
                const n = Number(btn.dataset.pass);
                if (draft.numbers.has(n)) draft.numbers.delete(n); else draft.numbers.add(n);
                renderFlowRepeatBarModal();
            });
        });
    }
    function openFlowRepeatBarPicker(blockId) {
        const b = flowFindBlockById(blockId);
        if (!b) return;
        flowRepeatBarTargetId = blockId;
        const idx = currentFlowBlocks.findIndex(x => x.id === blockId);
        document.getElementById('flowRepeatBarPill').innerText = idx === -1 ? '' : flowBarRangeLabel(idx);
        flowRepeatBarDraft = {
            on: !!(b.repeatEndingNumbers && b.repeatEndingNumbers.length),
            startBar: b.repeatEndingStartBar || 1,
            maxBar: Math.max(1, b.barCount || 1),
            numbers: new Set(b.repeatEndingNumbers || [])
        };
        renderFlowRepeatBarModal();
        showModal('flowRepeatBarModal');
    }
    function closeFlowRepeatBarModal() {
        hideModal('flowRepeatBarModal');
        flowRepeatBarTargetId = null;
        flowRepeatBarDraft = null;
    }
    document.getElementById('flowRepeatBarToggle')?.addEventListener('change', (e) => {
        if (!flowRepeatBarDraft) return;
        flowRepeatBarDraft.on = e.target.checked;
        renderFlowRepeatBarModal();
    });
    setupHoldStepper(document.getElementById('flowRepeatBarStartMinus'), -1, (amount) => {
        if (!flowRepeatBarDraft) return;
        flowRepeatBarDraft.startBar = Math.max(1, flowRepeatBarDraft.startBar + amount);
        renderFlowRepeatBarModal();
    });
    setupHoldStepper(document.getElementById('flowRepeatBarStartPlus'), 1, (amount) => {
        if (!flowRepeatBarDraft) return;
        flowRepeatBarDraft.startBar = Math.max(1, Math.min(flowRepeatBarDraft.maxBar, flowRepeatBarDraft.startBar + amount));
        renderFlowRepeatBarModal();
    });
    document.getElementById('flowRepeatBarCloseBtn')?.addEventListener('click', closeFlowRepeatBarModal);
    document.getElementById('flowRepeatBarCancelBtn')?.addEventListener('click', closeFlowRepeatBarModal);
    document.getElementById('flowRepeatBarSaveBtn')?.addEventListener('click', () => {
        if (!flowRepeatBarDraft || flowRepeatBarTargetId === null) return closeFlowRepeatBarModal();
        const draft = flowRepeatBarDraft;
        const targetId = flowRepeatBarTargetId;
        const numbers = draft.on ? Array.from(draft.numbers).sort((a, b) => a - b) : [];
        closeFlowRepeatBarModal();
        flowUpdateBlock(targetId, {
            repeatEndingNumbers: numbers,
            repeatEndingStartBar: draft.on ? draft.startBar : null,
            isFirstTimeBar: false, isSecondTimeBar: false
        });
    });

    // --- Intro picker (#flowIntroModal) - which bar (within this block) the intro starts at, and
    // optionally which bar it finishes at if it ends before the block's own final bar. Reuses
    // introStartBarOffset/introEndBarOffset (shared columns with the ad-hoc Metronome Blocks tool -
    // see metroSegIntroCard elsewhere in this file) as plain 1-based bar-within-block numbers; the
    // beat-offset half of those columns is a pickup-beat concept that tool uses and this picker
    // doesn't touch - validateSegmentPayload (metronomeSegments.js) defaults it to beat 1 server-side
    // whenever a bar offset is set. End is gated behind Start (can't end early without
    // an intro to end) and bounded so it can never sit before the start bar. Never written until
    // committed, same "own modal, own draft" pattern as every other picker here. ---
    let flowIntroTargetId = null;
    let flowIntroDraft = null; // { startOn, startBar, endOn, endBar, maxBar }

    function renderFlowIntroModal() {
        const draft = flowIntroDraft;
        if (!draft) return;
        document.getElementById('flowIntroStartToggle').checked = draft.startOn;
        document.getElementById('flowIntroStartFields').classList.toggle('hidden-group', !draft.startOn);
        const startInvalid = draft.startOn && draft.startBar > draft.maxBar;
        const startValueEl = document.getElementById('flowIntroStartValue');
        startValueEl.classList.toggle('flow-bar-readout-invalid', startInvalid);
        const startText = `Bar ${draft.startBar} of ${draft.maxBar}`;
        startValueEl.innerHTML = startInvalid ? `${flowWarningIconSvg('flow-warning-icon')}${startText}` : startText;

        const endToggle = document.getElementById('flowIntroEndToggle');
        endToggle.checked = draft.endOn;
        endToggle.disabled = !draft.startOn;
        document.getElementById('flowIntroEndToggleRow').classList.toggle('flow-toggle-row-disabled', !draft.startOn);
        document.getElementById('flowIntroEndToggleHelp').innerText = !draft.startOn ? 'Enable start intro first'
            : draft.endOn ? '' : `Default plays through to final bar (Bar ${draft.maxBar})`;
        document.getElementById('flowIntroEndFields').classList.toggle('hidden-group', !(draft.startOn && draft.endOn));
        if (draft.startOn && draft.endOn) {
            const endInvalid = draft.endBar > draft.maxBar;
            const endValueEl = document.getElementById('flowIntroEndValue');
            endValueEl.classList.toggle('flow-bar-readout-invalid', endInvalid);
            const endText = `Bar ${draft.endBar} of ${draft.maxBar}`;
            endValueEl.innerHTML = endInvalid ? `${flowWarningIconSvg('flow-warning-icon')}${endText}` : endText;
        }
    }
    function openFlowIntroPicker(blockId) {
        const b = flowFindBlockById(blockId);
        if (!b) return;
        flowIntroTargetId = blockId;
        const idx = currentFlowBlocks.findIndex(x => x.id === blockId);
        document.getElementById('flowIntroPill').innerText = idx === -1 ? '' : flowBarRangeLabel(idx);
        const maxBar = Math.max(1, b.barCount || 1);
        const startOn = b.introStartBarOffset !== null && b.introStartBarOffset !== undefined;
        const endOn = startOn && b.introEndBarOffset !== null && b.introEndBarOffset !== undefined;
        // Not clamped to maxBar here - a stale value (the block shortened after this was set) shows
        // as-is, flagged red by renderFlowIntroModal, same as the alt-ending picker's own start bar.
        flowIntroDraft = {
            startOn,
            startBar: startOn ? Math.max(1, b.introStartBarOffset) : 1,
            endOn,
            endBar: endOn ? Math.max(1, b.introEndBarOffset) : maxBar,
            maxBar
        };
        renderFlowIntroModal();
        showModal('flowIntroModal');
    }
    function closeFlowIntroModal() {
        hideModal('flowIntroModal');
        flowIntroTargetId = null;
        flowIntroDraft = null;
    }
    document.getElementById('flowIntroStartToggle')?.addEventListener('change', (e) => {
        if (!flowIntroDraft) return;
        flowIntroDraft.startOn = e.target.checked;
        if (!flowIntroDraft.startOn) flowIntroDraft.endOn = false;
        renderFlowIntroModal();
    });
    document.getElementById('flowIntroEndToggle')?.addEventListener('change', (e) => {
        if (!flowIntroDraft || !flowIntroDraft.startOn) return;
        flowIntroDraft.endOn = e.target.checked;
        if (flowIntroDraft.endOn) flowIntroDraft.endBar = Math.max(flowIntroDraft.endBar, flowIntroDraft.startBar);
        renderFlowIntroModal();
    });
    setupHoldStepper(document.getElementById('flowIntroStartMinus'), -1, (amount) => {
        if (!flowIntroDraft) return;
        flowIntroDraft.startBar = Math.max(1, flowIntroDraft.startBar + amount);
        if (flowIntroDraft.endOn) flowIntroDraft.endBar = Math.max(flowIntroDraft.endBar, flowIntroDraft.startBar);
        renderFlowIntroModal();
    });
    setupHoldStepper(document.getElementById('flowIntroStartPlus'), 1, (amount) => {
        if (!flowIntroDraft) return;
        flowIntroDraft.startBar = Math.max(1, Math.min(flowIntroDraft.maxBar, flowIntroDraft.startBar + amount));
        if (flowIntroDraft.endOn) flowIntroDraft.endBar = Math.max(flowIntroDraft.endBar, flowIntroDraft.startBar);
        renderFlowIntroModal();
    });
    setupHoldStepper(document.getElementById('flowIntroEndMinus'), -1, (amount) => {
        if (!flowIntroDraft) return;
        flowIntroDraft.endBar = Math.max(flowIntroDraft.startBar, flowIntroDraft.endBar + amount);
        renderFlowIntroModal();
    });
    setupHoldStepper(document.getElementById('flowIntroEndPlus'), 1, (amount) => {
        if (!flowIntroDraft) return;
        flowIntroDraft.endBar = Math.max(flowIntroDraft.startBar, Math.min(flowIntroDraft.maxBar, flowIntroDraft.endBar + amount));
        renderFlowIntroModal();
    });
    document.getElementById('flowIntroCloseBtn')?.addEventListener('click', closeFlowIntroModal);
    document.getElementById('flowIntroCancelBtn')?.addEventListener('click', closeFlowIntroModal);
    document.getElementById('flowIntroSaveBtn')?.addEventListener('click', () => {
        if (!flowIntroDraft || flowIntroTargetId === null) return closeFlowIntroModal();
        const draft = flowIntroDraft;
        const targetId = flowIntroTargetId;
        closeFlowIntroModal();
        flowUpdateBlock(targetId, {
            introStartBarOffset: draft.startOn ? draft.startBar : null,
            introEndBarOffset: draft.startOn && draft.endOn ? draft.endBar : null
        });
    });

    // --- Time signature / beat unit pickers - literally the same shared modals Quick Play's own
    // per-block pickers reuse (qpOpenTimeSigPicker/qpOpenNotePicker), not a Flow-only copy - per the
    // request, the same popup/images/functionality, just wired to update a Flow block instead of a
    // qpBlocks entry. Flow's own timeSignatureId/accountTimeSignatureId split is translated to/from
    // the shared modal's "public:<id>"/"custom:<id>" string shape (same parse qpBlockTimeSig uses). ---
    function flowTimeSigValueFor(b) {
        if (b.timeSignatureId) return `public:${b.timeSignatureId}`;
        if (b.accountTimeSignatureId) return `custom:${b.accountTimeSignatureId}`;
        return null;
    }
    function flowOpenTimeSigPicker(blockId) {
        const b = flowFindBlockById(blockId);
        if (!b) return;
        metroSegTimeSigValue = flowTimeSigValueFor(b);
        metroSegTimeSigOnSelect = (value) => {
            const [type, id] = value.split(':');
            flowUpdateBlock(blockId, type === 'public'
                ? { timeSignatureId: Number(id), accountTimeSignatureId: null }
                : { timeSignatureId: null, accountTimeSignatureId: Number(id) });
        };
        renderMetroSegTimeSigPicker();
        showModal('metroSegTimeSigModal');
    }
    function flowOpenNotePicker(blockId) {
        const b = flowFindBlockById(blockId);
        if (!b) return;
        const el = document.getElementById('metroSegNotePicker');
        if (!el) return;
        el.innerHTML = METRO_NOTE_TYPES.map(t => `
            <button type="button" class="metroBlk-note-btn${t.key === b.noteValue ? ' selected' : ''}" data-note="${t.key}" aria-label="${t.label}" aria-pressed="${t.key === b.noteValue}">
                ${metroNoteIconSvg(t.key)}
            </button>
        `).join('');
        el.querySelectorAll('.metroBlk-note-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                flowUpdateBlock(blockId, { noteValue: btn.dataset.note });
                hideModal('metroSegNoteModal');
            }, { once: true });
        });
        showModal('metroSegNoteModal');
    }

    // Start-of-bar picker - same "Beat unit" modal format (title/help text/close-x, a row of
    // .metroBlk-note-btn icon cards) as flowOpenNotePicker above, just its own modal/picker element
    // and two barline options (flowBarlineIconSvg) instead of five note-duration ones.
    function flowOpenBarStartPicker(blockId) {
        const b = flowFindBlockById(blockId);
        if (!b) return;
        const el = document.getElementById('flowBarStartPicker');
        if (!el) return;
        const options = [
            { key: 'plain', label: 'Plain barline', selected: !b.isRepeatStart, apply: { isRepeatStart: false } },
            { key: 'repeatStart', label: 'Repeat start', selected: !!b.isRepeatStart, apply: { isRepeatStart: true } }
        ];
        el.innerHTML = options.map(o => `
            <button type="button" class="metroBlk-note-btn${o.selected ? ' selected' : ''}" data-start-option="${o.key}" aria-label="${o.label}" aria-pressed="${o.selected}">
                ${flowBarlineIconSvg(o.key, 'metroBlk-note-svg', o.key === 'plain')}
            </button>
        `).join('');
        el.querySelectorAll('[data-start-option]').forEach(btn => {
            btn.addEventListener('click', () => {
                const opt = options.find(o => o.key === btn.dataset.startOption);
                flowUpdateBlock(blockId, opt.apply);
                hideModal('flowBarStartModal');
            }, { once: true });
        });
        flowBarStartMovementRender(blockId);
        showModal('flowBarStartModal');
    }
    // ML-529: a movement starts at the start of a bar - a switch (the first bar always starts the first
    // movement, so it has none) and the movement's name. Shown with the piece_movements feature, or when the
    // piece is already in movements. The switch and the name save as they change; the pop-up stays open.
    function flowBarStartMovementRender(blockId) {
        const box = document.getElementById('flowBarStartMovement');
        if (!box) return;
        const b = flowFindBlockById(blockId);
        const first = currentFlowBlocks[0] === b;
        const inMovements = FlowJourney.movements(currentFlowBlocks).length > 1;
        if (!b || b.isLeadIn || (!isFeatureEnabled('piece_movements') && !inMovements) || (first && !inMovements)) { box.innerHTML = ''; return; }
        const on = first || !!b.movementStart;
        box.innerHTML = `
            ${first ? '' : `<div class="display-toggle-row">
                <span id="flowMovementStartLabel">A movement starts here<span class="display-toggle-help">The bar numbers carry on; the repeats and jumps stay inside each movement</span></span><label class="toggle-switch"><input type="checkbox" id="flowMovementStart" aria-labelledby="flowMovementStartLabel"${on ? ' checked' : ''}><span class="toggle-slider"></span></label>
            </div>`}
            ${on ? `<div class="form-group"><label for="flowMovementTitle">${first ? 'The first movement is called' : 'The movement is called'}</label>
            <input type="text" id="flowMovementTitle" maxlength="80" autocomplete="off" placeholder="e.g. Harvest" value="${escapeHtml(b.movementTitle || '')}"></div>` : ''}`;
        document.getElementById('flowMovementStart')?.addEventListener('change', async (e) => {
            await flowUpdateBlock(blockId, { movementStart: e.target.checked, ...(e.target.checked ? {} : { movementTitle: null }) });
            flowBarStartMovementRender(blockId);
            if (e.target.checked) document.getElementById('flowMovementTitle')?.focus();
        });
        document.getElementById('flowMovementTitle')?.addEventListener('change', (e) => {
            flowUpdateBlock(blockId, { movementTitle: e.target.value.trim() || null, ...(first ? { movementStart: true } : {}) });
        });
    }

    // Shared option-card markup for the End-of-bar picker below - icon (+ a repeat count next to
    // it, when it has one - never stacked above, so the card's height doesn't change either way)
    // and a caption underneath.
    function flowBarlinePickerTileHtml(o) {
        return `
            <button type="button" class="flow-picker-tile${o.selected ? ' selected' : ''}" data-option="${usageOptionKey(o.caption)}" aria-label="${escapeHtml(o.caption)}${o.countLabel ? ' ' + o.countLabel : ''}" aria-pressed="${o.selected}">
                <span class="flow-picker-tile-icon-row">
                    ${flowBarlineIconSvg(o.kind, 'metroBlk-note-svg')}
                    ${o.countLabel ? `<span class="flow-picker-tile-count">${escapeHtml(o.countLabel)}</span>` : ''}
                </span>
                <span class="flow-picker-tile-label">${escapeHtml(o.caption)}</span>
            </button>
        `;
    }

    // End-of-bar picker - "Structure" (Normal/Section/Fine/Final, mutually exclusive with a repeat
    // end) plus "Repeats" (a direct 2x-9x grid - tapping one both marks this a repeat end and sets
    // its count in one step, replacing the old two-step "pick Repeat end, then drag a count slider"
    // flow). The 2x tile shows no count of its own - it's the implicit default, same as how neither
    // Normal/Section/Fine/Final ever show one of their own. Fine reuses Section's plain double-bar
    // glyph (a Fine mark isn't a different-shaped barline, just a plain one with "Fine" printed by
    // it) with a "Fine" tag alongside it, same .flow-picker-tile-count slot the Repeats grid's own
    // "2x"/"3x" labels use.
    function flowOpenBarEndPicker(blockId) {
        const b = flowFindBlockById(blockId);
        if (!b) return;
        const structureOptions = [
            { kind: 'plain', caption: 'Normal', selected: !b.isRepeatEnd && !b.isSectionBoundary && !b.isFinalBarline && !b.isFine,
                apply: { isRepeatEnd: false, isSectionBoundary: false, isFinalBarline: false, isFine: false, repeatPlayCount: null } },
            { kind: 'section', caption: 'Section', selected: !b.isRepeatEnd && b.isSectionBoundary,
                apply: { isRepeatEnd: false, isSectionBoundary: true, isFinalBarline: false, isFine: false, repeatPlayCount: null } },
            { kind: 'section', caption: 'Fine', countLabel: 'Fine', selected: !b.isRepeatEnd && b.isFine,
                apply: { isRepeatEnd: false, isSectionBoundary: false, isFinalBarline: false, isFine: true, repeatPlayCount: null } },
            { kind: 'fine', caption: 'Final', selected: !b.isRepeatEnd && b.isFinalBarline,
                apply: { isRepeatEnd: false, isSectionBoundary: false, isFinalBarline: true, isFine: false, repeatPlayCount: null } }
        ];
        const repeatOptions = Array.from({ length: 8 }, (_, i) => i + 2).map(n => ({
            kind: 'repeatEnd', caption: 'Repeat', countLabel: flowRepeatCountLabel(n),
            selected: b.isRepeatEnd && (b.repeatPlayCount || 2) === n,
            apply: { isRepeatEnd: true, isSectionBoundary: false, isFinalBarline: false, isFine: false, repeatPlayCount: n }
        }));
        function render(elId, options) {
            const el = document.getElementById(elId);
            if (!el) return;
            el.innerHTML = options.map(flowBarlinePickerTileHtml).join('');
            el.querySelectorAll('.flow-picker-tile').forEach((btn, i) => {
                btn.addEventListener('click', () => {
                    flowUpdateBlock(blockId, options[i].apply);
                    hideModal('flowBarEndModal');
                }, { once: true });
            });
        }
        render('flowBarEndStructureGrid', structureOptions);
        render('flowBarEndRepeatsGrid', repeatOptions);
        showModal('flowBarEndModal');
    }

    // --- Shared "tap a glyph tile to select & close, no Save/Cancel" picker shape, used by both the
    // Jump sign picker (#flowSignModal - None/Segno/Coda) and the Jump instruction picker
    // (#flowJumpModal - None plus 5 D.S./D.C./Coda combinations). Its own tile builder (rather than
    // reusing flowBarlinePickerTileHtml above) because these tiles carry a single centered icon/glyph
    // (no repeat count row) plus a caption under every option. "None" is obvious enough on its own -
    // it's the big icon-row text instead, no caption underneath (ariaLabel covers the button's
    // accessible name when caption is blank). ---
    function flowGlyphPickerTileHtml(o) {
        const ariaLabel = o.ariaLabel || o.caption;
        return `
            <button type="button" class="flow-picker-tile${o.selected ? ' selected' : ''}" data-option="${usageOptionKey(o.value !== undefined ? o.value : ariaLabel)}" aria-label="${escapeHtml(ariaLabel)}" aria-pressed="${o.selected}">
                <span class="flow-picker-tile-icon-row">${o.icon || ''}</span>
                <span class="flow-picker-tile-label">${escapeHtml(o.caption)}</span>
            </button>
        `;
    }
    function openFlowGlyphPicker(modalId, gridId, options, onSelect) {
        const grid = document.getElementById(gridId);
        grid.innerHTML = options.map(flowGlyphPickerTileHtml).join('');
        grid.querySelectorAll('.flow-picker-tile').forEach((btn, i) => {
            btn.addEventListener('click', () => {
                onSelect(options[i]);
                hideModal(modalId);
            }, { once: true });
        });
        showModal(modalId);
    }
    function openFlowSignPicker(blockId) {
        const b = flowFindBlockById(blockId);
        if (!b) return;
        const options = [
            { icon: 'None', caption: '', ariaLabel: 'None', selected: !b.isSegno && !b.isCoda, apply: { isSegno: false, isCoda: false } },
            { icon: flowSignIconSvg('segno'), caption: 'Segno', selected: b.isSegno, apply: { isSegno: true, isCoda: false } },
            { icon: flowSignIconSvg('coda'), caption: 'Coda', selected: b.isCoda, apply: { isSegno: false, isCoda: true } }
        ];
        openFlowGlyphPicker('flowSignModal', 'flowSignOptions', options, (opt) => flowUpdateBlock(blockId, opt.apply));
    }
    document.getElementById('flowSignCloseBtn')?.addEventListener('click', () => {
        hideModal('flowSignModal');
    });

    // --- Jump instruction picker (#flowJumpModal) - None, then the 5 core jump instructions, a clean
    // 2x3 grid (.flow-tile-grid-3-centered). All 5 flags are mutually exclusive - every option clears
    // the other 4 alongside setting its own. Marking THIS bar as the Fine stopping point itself is a
    // separate concern, not a jump instruction - that's the End-of-bar Structure picker's own "Fine"
    // tile (isFine), not this one. Captions are the plain-English action (not the notation the icon
    // above already spells out), matching what each instruction actually does on playback:
    // - D.S. al Coda: jump to the Segno, play until a "To Coda" bar, then jump to the Coda.
    // - D.C. al Coda: jump to bar 1, play until a "To Coda" bar, then jump to the Coda.
    // - To Coda: the mid-piece exit ramp a D.S./D.C. al Coda jumps to on replay.
    // - D.S. al Fine: jump to the Segno, play through to the bar marked Fine.
    // - D.C. al Fine: jump to bar 1, play through to the bar marked Fine. ---
    function openFlowJumpPicker(blockId) {
        const b = flowFindBlockById(blockId);
        if (!b) return;
        const clear = { gotoSegno: false, gotoSegnoThenCoda: false, gotoCoda: false, gotoStartDc: false, gotoStartDcThenCoda: false };
        const options = [
            { icon: 'None', caption: '', ariaLabel: 'None',
                selected: !b.gotoSegno && !b.gotoSegnoThenCoda && !b.gotoCoda && !b.gotoStartDc && !b.gotoStartDcThenCoda,
                apply: { ...clear } },
            { icon: `D.S. al ${flowSignIconSvg('coda', true)}`, caption: 'Segno to Coda',
                selected: b.gotoSegnoThenCoda, apply: { ...clear, gotoSegnoThenCoda: true } },
            { icon: `D.C. al ${flowSignIconSvg('coda', true)}`, caption: 'Start to Coda',
                selected: b.gotoStartDcThenCoda, apply: { ...clear, gotoStartDcThenCoda: true } },
            { icon: `To ${flowSignIconSvg('coda', true)}`, caption: 'Jump to Coda',
                selected: b.gotoCoda, apply: { ...clear, gotoCoda: true } },
            { icon: 'D.S.', caption: 'Segno to Fine',
                selected: b.gotoSegno, apply: { ...clear, gotoSegno: true } },
            { icon: 'D.C.', caption: 'Start to Fine',
                selected: b.gotoStartDc, apply: { ...clear, gotoStartDc: true } }
        ];
        openFlowGlyphPicker('flowJumpModal', 'flowJumpOptions', options, (opt) => flowUpdateBlock(blockId, opt.apply));
    }
    document.getElementById('flowJumpCloseBtn')?.addEventListener('click', () => {
        hideModal('flowJumpModal');
    });

    // --- BPM popup - same tiered-slider mechanic as the ad-hoc/Quick Play BPM controls
    // (METRO_MIN_BPM/METRO_MAX_BPM/METRO_SLIDER_TIERS, metroBestFitTier, setupSliderInteraction/
    // makeSliderReadoutEditable - all already value-agnostic), own copy of the small stepping state
    // machine per this file's usual "own copy per feature" precedent, just presented as its own
    // single-field popup rather than embedded inline on a card. ---
    let flowBpmModalTargetId = null;
    let flowBpmOnApply = null;
    let flowBpmSliderMax = METRO_SLIDER_TIERS[0];
    let flowBpmTierChangeCooldownUntil = 0;
    // The value the block actually had when this popup opened - only committed to the server (and
    // re-rendered onto the card behind the modal) once on close, not on every slider tick. Dragging
    // around and landing back here, or just opening and closing without touching anything, writes
    // nothing at all.
    let flowBpmOriginalValue = null;
    function flowBpmStepTier(value) {
        const now = Date.now();
        if (now < flowBpmTierChangeCooldownUntil) return;
        const idx = METRO_SLIDER_TIERS.indexOf(flowBpmSliderMax);
        if (idx < METRO_SLIDER_TIERS.length - 1 && value >= METRO_SLIDER_TIERS[idx]) {
            flowBpmSliderMax = METRO_SLIDER_TIERS[idx + 1];
            flowBpmTierChangeCooldownUntil = now + 350;
        } else if (idx > 0 && value < METRO_SLIDER_TIERS[idx - 1]) {
            flowBpmSliderMax = METRO_SLIDER_TIERS[idx - 1];
            flowBpmTierChangeCooldownUntil = now + 350;
        }
    }
    function renderFlowBpmSlider(value) {
        const pct = ((value - METRO_MIN_BPM) / (flowBpmSliderMax - METRO_MIN_BPM)) * 100;
        document.getElementById('flowBpmSliderFill').style.setProperty('--pct', `${pct}%`);
        const thumb = document.getElementById('flowBpmSliderThumb');
        thumb.style.setProperty('--pct', `${pct}%`);
        thumb.setAttribute('aria-valuenow', value);
        thumb.setAttribute('aria-valuemax', flowBpmSliderMax);
        document.getElementById('flowBpmSliderMaxLbl').innerText = flowBpmSliderMax;
        document.getElementById('flowBpmPopupValue').innerText = value;
    }
    function setFlowBpmFromDisplayed(value, opts = {}) {
        const clamped = Math.round(Math.min(METRO_MAX_BPM, Math.max(METRO_MIN_BPM, value)));
        if (opts.dragging) flowBpmStepTier(clamped); else flowBpmSliderMax = metroBestFitTier(clamped);
        renderFlowBpmSlider(clamped);
    }
    // opts.value/opts.onApply let a caller other than the block's own bpm tile reuse this same
    // popup (the Tempo ramps modal's "Set custom tempo" row, flowRampCustomTempoBtn) - defaults to
    // exactly the original blockId-only behaviour when neither is passed.
    function flowOpenBpmModal(blockId, opts = {}) {
        const value = opts.value !== undefined ? opts.value : flowFindBlockById(blockId)?.bpm;
        if (value === undefined || value === null) return;
        flowBpmModalTargetId = blockId;
        flowBpmOnApply = opts.onApply || null;
        flowBpmOriginalValue = value;
        flowBpmSliderMax = metroBestFitTier(value);
        renderFlowBpmSlider(value);
        showModal('flowBpmModal');
        // ML-435: for a caller that mostly wants a number typed (Quick entry), a number key typed anywhere in the
        // pop-up starts a new number, and Enter both takes it and closes the pop-up. The pop-up no longer opens
        // with the number box in use (owner, 5 Oct 2026): that put the slider and the +/- a tap away and wasn't
        // how any other pop-up opens. A phone has no keys to type until the number is tapped, as before.
        flowBpmTypeAnywhere = !!opts.typeFirst;
    }
    let flowBpmTypeAnywhere = false;
    document.getElementById('flowBpmModal')?.addEventListener('keydown', (e) => {
        if (!flowBpmTypeAnywhere || e.ctrlKey || e.metaKey || e.altKey) return;
        if (e.target.classList && e.target.classList.contains('slider-readout-input')) {
            if (e.key === 'Enter') setTimeout(closeFlowBpmModal, 0);
            return;
        }
        if (!/^[0-9]$/.test(e.key)) return;
        e.preventDefault();
        document.getElementById('flowBpmPopupValue')?.click(); // the number becomes a box to type in
        const input = document.querySelector('#flowBpmModal .slider-readout-input');
        if (!input) return;
        input.value = e.key;
        input.focus();
    });
    setupHoldStepper(document.getElementById('flowBpmMinus'), -1, (amount) => setFlowBpmFromDisplayed(Number(document.getElementById('flowBpmPopupValue').innerText) + amount, { dragging: true }));
    setupHoldStepper(document.getElementById('flowBpmPlus'), 1, (amount) => setFlowBpmFromDisplayed(Number(document.getElementById('flowBpmPopupValue').innerText) + amount, { dragging: true }));
    setupSliderInteraction(document.getElementById('flowBpmSliderTrack'), document.getElementById('flowBpmSliderThumb'), {
        onDragRatio: (ratio) => setFlowBpmFromDisplayed(METRO_MIN_BPM + ratio * (flowBpmSliderMax - METRO_MIN_BPM), { dragging: true }),
        onArrowStep: (dir) => setFlowBpmFromDisplayed(Number(document.getElementById('flowBpmPopupValue').innerText) + dir, { dragging: true })
    });
    makeSliderReadoutEditable('flowBpmPopupValue', () => Number(document.getElementById('flowBpmPopupValue').innerText), (v) => setFlowBpmFromDisplayed(v), { label: 'Tempo', min: METRO_MIN_BPM, max: METRO_MAX_BPM });
    // Commits once here, on close, whatever the popup ended up showing - not on every drag tick.
    // If it's unchanged from what the block already had (opened and closed without touching it,
    // or dragged back to the start), there's nothing to write.
    function closeFlowBpmModal() {
        hideModal('flowBpmModal');
        const finalValue = Number(document.getElementById('flowBpmPopupValue').innerText);
        if (finalValue === flowBpmOriginalValue) return;
        if (flowBpmOnApply) flowBpmOnApply(finalValue);
        else if (flowBpmModalTargetId) flowUpdateBlock(flowBpmModalTargetId, { bpm: finalValue });
    }
    document.getElementById('flowBpmCloseBtn')?.addEventListener('click', closeFlowBpmModal);
    document.getElementById('flowBpmModal')?.addEventListener('click', (e) => { if (e.target === e.currentTarget) closeFlowBpmModal(); });

    // --- Bar count popup - same tiered-slider mechanic as BPM's own above, its own tier list
    // (50/250/500) per the request rather than reusing METRO_SLIDER_TIERS. ---
    const FLOW_BARS_MIN = 1;
    const FLOW_BARS_MAX = 500;
    const FLOW_BARS_TIERS = [50, 250, 500];
    let flowBarsModalTargetId = null;
    let flowBarsSliderMax = FLOW_BARS_TIERS[0];
    let flowBarsTierChangeCooldownUntil = 0;
    let flowBarsOriginalValue = null;
    function flowBarsStepTier(value) {
        const now = Date.now();
        if (now < flowBarsTierChangeCooldownUntil) return;
        const idx = FLOW_BARS_TIERS.indexOf(flowBarsSliderMax);
        if (idx < FLOW_BARS_TIERS.length - 1 && value >= FLOW_BARS_TIERS[idx]) {
            flowBarsSliderMax = FLOW_BARS_TIERS[idx + 1];
            flowBarsTierChangeCooldownUntil = now + 350;
        } else if (idx > 0 && value < FLOW_BARS_TIERS[idx - 1]) {
            flowBarsSliderMax = FLOW_BARS_TIERS[idx - 1];
            flowBarsTierChangeCooldownUntil = now + 350;
        }
    }
    function flowBarsBestFitTier(value) {
        return FLOW_BARS_TIERS.find(t => value <= t) || FLOW_BARS_TIERS[FLOW_BARS_TIERS.length - 1];
    }
    function renderFlowBarsSlider(value) {
        const pct = ((value - FLOW_BARS_MIN) / (flowBarsSliderMax - FLOW_BARS_MIN)) * 100;
        document.getElementById('flowBarsSliderFill').style.setProperty('--pct', `${pct}%`);
        const thumb = document.getElementById('flowBarsSliderThumb');
        thumb.style.setProperty('--pct', `${pct}%`);
        thumb.setAttribute('aria-valuenow', value);
        thumb.setAttribute('aria-valuemax', flowBarsSliderMax);
        document.getElementById('flowBarsSliderMaxLbl').innerText = flowBarsSliderMax;
        document.getElementById('flowBarsPopupValue').innerText = value;
    }
    function setFlowBarsFromDisplayed(value, opts = {}) {
        const clamped = Math.round(Math.min(FLOW_BARS_MAX, Math.max(FLOW_BARS_MIN, value)));
        if (opts.dragging) flowBarsStepTier(clamped); else flowBarsSliderMax = flowBarsBestFitTier(clamped);
        renderFlowBarsSlider(clamped);
    }
    function flowOpenBarsModal(blockId) {
        const b = flowFindBlockById(blockId);
        if (!b) return;
        flowBarsModalTargetId = blockId;
        flowBarsOriginalValue = b.barCount;
        flowBarsSliderMax = flowBarsBestFitTier(b.barCount);
        renderFlowBarsSlider(b.barCount);
        showModal('flowBarsModal');
    }
    setupHoldStepper(document.getElementById('flowBarsMinus'), -1, (amount) => setFlowBarsFromDisplayed(Number(document.getElementById('flowBarsPopupValue').innerText) + amount, { dragging: true }));
    setupHoldStepper(document.getElementById('flowBarsPlus'), 1, (amount) => setFlowBarsFromDisplayed(Number(document.getElementById('flowBarsPopupValue').innerText) + amount, { dragging: true }));
    setupSliderInteraction(document.getElementById('flowBarsSliderTrack'), document.getElementById('flowBarsSliderThumb'), {
        onDragRatio: (ratio) => setFlowBarsFromDisplayed(FLOW_BARS_MIN + ratio * (flowBarsSliderMax - FLOW_BARS_MIN), { dragging: true }),
        onArrowStep: (dir) => setFlowBarsFromDisplayed(Number(document.getElementById('flowBarsPopupValue').innerText) + dir, { dragging: true })
    });
    makeSliderReadoutEditable('flowBarsPopupValue', () => Number(document.getElementById('flowBarsPopupValue').innerText), (v) => setFlowBarsFromDisplayed(v), { label: 'Number of bars', min: FLOW_BARS_MIN, max: FLOW_BARS_MAX });
    function closeFlowBarsModal() {
        hideModal('flowBarsModal');
        const finalValue = Number(document.getElementById('flowBarsPopupValue').innerText);
        if (flowBarsModalTargetId && finalValue !== flowBarsOriginalValue) flowUpdateBlock(flowBarsModalTargetId, { barCount: finalValue });
    }
    document.getElementById('flowBarsCloseBtn')?.addEventListener('click', closeFlowBarsModal);
    document.getElementById('flowBarsModal')?.addEventListener('click', (e) => { if (e.target === e.currentTarget) closeFlowBarsModal(); });

    // --- Tile tap dispatch - one branch per Block Inspector tile (see flowBlockCardHtml above). ---
    function handleFlowBlockTileClick(blockId, tileKey) {
        const b = flowFindBlockById(blockId);
        if (!b) return;

        if (tileKey === 'rehearsalMark') {
            showPromptModal('Rehearsal mark', b.rehearsalMark || '', (val) => {
                flowUpdateBlock(blockId, { rehearsalMark: val.trim() || null });
            });
            return;
        }

        if (tileKey === 'time') {
            flowOpenTimeSigPicker(blockId);
            return;
        }

        if (tileKey === 'beatUnit') {
            flowOpenNotePicker(blockId);
            return;
        }

        if (tileKey === 'bpm') {
            flowOpenBpmModal(blockId);
            return;
        }

        if (tileKey === 'bars') {
            flowOpenBarsModal(blockId);
            return;
        }

        if (tileKey === 'start') {
            flowOpenBarStartPicker(blockId);
            return;
        }

        if (tileKey === 'end') {
            flowOpenBarEndPicker(blockId);
            return;
        }

        if (tileKey === 'repeatBar') {
            openFlowRepeatBarPicker(blockId);
            return;
        }

        if (tileKey === 'intro') {
            openFlowIntroPicker(blockId);
            return;
        }

        if (tileKey === 'change') {
            openFlowRampModal(blockId);
            return;
        }

        if (tileKey === 'sign') {
            openFlowSignPicker(blockId);
            return;
        }

        if (tileKey === 'jump') {
            openFlowJumpPicker(blockId);
            return;
        }

        if (tileKey === 'pause') {
            openFlowFermataModal(blockId);
        }
    }

    // --- Pauses list (#flowFermataModal) - fermata (held beat) and caesura (silent break) entries
    // for this block, each on its own bar/beat within it. The one Block Inspector tile that's a
    // list, not a single value, so it gets its own small modal rather than fitting the generic
    // choice-list shape. List edits (add/remove/replace) write immediately via flowUpdateBlock, same
    // as before; only the "Add new pause" fields below are a local draft, reset after each
    // insert/save. Existing entries have no id of their own (child rows, full-replace-on-save, see
    // replaceFermatas server-side) - identified by object reference within b.fermatas instead, same
    // as the row delete already relied on before Edit existed. ---
    let flowFermataDraft = null; // { kind: 'fermata'|'caesura', bar, beat, duration, maxBar, maxBeat }
    let flowFermataEditTarget = null; // the b.fermatas entry currently being edited, or null when adding new
    let flowFermataRowMenuTarget = null;
    // Collapsed by default once the block has at least one pause (the list + a "+ Add pause" button
    // is the scannable view then) - open by default when it has none, so a user who opened this
    // modal specifically to add one isn't made to tap an extra button on an empty screen first.
    // Always forced open while editing/adding (openFlowFermataModal/the row menu/openFormBtn set it).
    let flowFermataFormOpen = true;

    // Time-delivered order - earliest bar, then earliest beat within it - regardless of the order
    // entries were added in.
    function flowPauseSorted(fermatas) {
        return [...fermatas].sort((a, b) => (a.barOffset || 0) - (b.barOffset || 0) || a.beatOffset - b.beatOffset);
    }
    // ML-365: a pause's position counted in the bar's pause steps (FlowJourney.pauseStepsPerBeat) - whole
    // written beats, or beat notes when they're shorter: in 2/2 counted in crotchets, beat 1.5 is "beat 2 of 4".
    const flowPauseStep = (b) => 1 / FlowJourney.pauseStepsPerBeat(b);
    const flowPauseBeatNumber = (b, beat) => Math.round((beat - 1) / flowPauseStep(b)) + 1;
    const flowPauseBeatCount = (b) => Math.max(1, (b && b.numerator) || 4) * FlowJourney.pauseStepsPerBeat(b);
    function renderFlowFermataList() {
        const b = flowFindBlockById(flowFermataTargetBlockId);
        const list = document.getElementById('flowFermataList');
        if (!b || !list) return;
        const fermatas = b.fermatas || [];
        // A round-trip through the server (non-edit-mode) replaces b.fermatas with fresh objects -
        // if the entry an in-progress edit pointed at no longer exists by reference, drop back to
        // "add new" rather than silently discarding the edit on Save (renderFlowFermataAddSection
        // reflects this back into the label/button text).
        if (flowFermataEditTarget && !fermatas.includes(flowFermataEditTarget)) {
            flowFermataEditTarget = null;
        }
        // "Current pauses" header (+ count) only makes sense once there's something to count - the
        // empty-block state shows nothing here at all, just the form (no placeholder text either).
        document.getElementById('flowFermataListHeader')?.classList.toggle('hidden-group', !fermatas.length);
        const countBadge = document.getElementById('flowFermataCountBadge');
        if (countBadge) countBadge.innerText = String(fermatas.length);
        if (!fermatas.length) {
            list.innerHTML = '';
            return;
        }
        const maxBar = Math.max(1, b.barCount || 1);
        const sorted = flowPauseSorted(fermatas);
        // A fresh render throws every row away - any swipe left open on the previous render is
        // already gone with it, same as Quick Play's own qpOpenSwipeIndex/Flow block's own
        // flowOpenSwipeBlockId reset on their own re-renders.
        flowOpenSwipePauseIndex = null;
        list.innerHTML = sorted.map((f, i) => {
            const kind = f.kind || 'fermata';
            const durationTag = `${kind === 'caesura' ? 'Silence' : 'Hold'} ${f.holdBeats} beat${f.holdBeats === 1 ? '' : 's'}`;
            // Flags a pause left stranded on a bar that no longer exists after the block was
            // shortened - same "show the stale value in red with a warning icon" treatment as the
            // Intro/Alt ending pickers' own stepper readouts, rather than hiding or clamping it.
            const invalid = ((f.barOffset || 0) + 1) > maxBar;
            // .flow-fermata-box is the same clipping-wrapper-with-delete-underlay-behind shape as
            // Flow's own block cards/Quick Play's bar boxes (wireFlowBlockSwipe/wireQpBarSwipe) - the
            // row itself (.flow-fermata-row) is what slides, the 3-dot menu keeps offering Edit/Delete
            // too, this is just a second way to reach the same delete.
            return `
                <div class="flow-fermata-box" data-pause-index="${i}">
                    <div role="button" tabindex="0" class="flow-fermata-delete-underlay" data-pause-swipe-delete aria-label="Delete pause">
                        <span class="material-symbols-outlined">delete</span>
                        <span>Delete</span>
                    </div>
                    <div class="flow-fermata-row">
                        <button type="button" class="flow-list-row-body flow-fermata-row-text${invalid ? ' flow-fermata-row-text-invalid' : ''}" data-pause-edit>
                            ${invalid ? flowWarningIconSvg('flow-warning-icon') : flowPauseIconSvg(kind, true)}
                            <span>Bar ${(f.barOffset || 0) + 1}, beat ${flowPauseBeatNumber(b, f.beatOffset)} &middot; <span class="flow-fermata-row-tag">${durationTag}</span></span>
                        </button>
                        <button type="button" class="list-item-menu-btn" data-pause-menu aria-label="Pause options" aria-haspopup="menu" aria-expanded="false"><span class="material-symbols-outlined">more_vert</span></button>
                    </div>
                </div>
            `;
        }).join('');
        list.querySelectorAll('[data-pause-menu]').forEach((btn, i) => {
            btn.addEventListener('click', (e) => {
                e.stopPropagation();
                openFlowFermataRowMenu(btn, sorted[i]);
            });
        });
        // ML-286: the whole row is the tappable surface - a tap opens the pause for editing (the ⋮ menu
        // still has Edit and Delete). A tap on a row slid open to Delete just closes it.
        list.querySelectorAll('[data-pause-edit]').forEach((body, i) => {
            body.addEventListener('click', (e) => {
                e.stopPropagation();
                if (Date.now() - flowPauseSwipeEndedAt < 400) return;
                if (flowOpenSwipePauseIndex !== null) { flowCloseOpenPauseSwipe(); return; }
                flowEditPause(sorted[i]);
            });
        });
        list.querySelectorAll('.flow-fermata-box').forEach((boxEl, i) => {
            const target = sorted[i];
            wireFlowPauseSwipe(boxEl, i, async () => {
                await flowUpdateBlock(b.id, { fermatas: fermatas.filter(x => x !== target) });
                renderFlowFermataList();
            });
        });
    }
    // --- Pause row swipe-to-delete - same shape as wireFlowBlockSwipe/wireQpBarSwipe (only intercepts
    // once the gesture is confirmed horizontal, so the page's own vertical scroll is untouched), just
    // without the reorder half those two also have (pauses aren't reorderable). Tracked by index
    // within the current render's sorted list, not object identity - renderFlowFermataList already
    // resets flowOpenSwipePauseIndex to null on every re-render, so a stale index never lingers. ---
    let flowOpenSwipePauseIndex = null;
    const FLOW_PAUSE_SWIPE_LOCK_X_PX = 30;
    const FLOW_PAUSE_SWIPE_LOCK_Y_MAX_PX = 15;
    const FLOW_PAUSE_SWIPE_OPEN_PX = 96; // keep in sync with .flow-fermata-delete-underlay's width in style.css
    const FLOW_PAUSE_SWIPE_SNAP_THRESHOLD_PX = 48;
    // The row body (data-pause-edit) is a button too (ML-286: tap the row to edit it), but a swipe may start on it.
    const FLOW_PAUSE_SWIPE_EXCLUDE_SELECTOR = 'button:not([data-pause-edit]), input, [role="slider"], [role="button"]';
    let flowPauseSwipeEndedAt = 0; // a swipe's own pointerup is followed by a click on the body - that click isn't a tap
    function flowPauseSurfaceFor(index) {
        return document.querySelector(`#flowFermataList [data-pause-index="${index}"] .flow-fermata-row`);
    }
    function flowSetPauseSwipeOffset(index, offset, animate) {
        const surface = flowPauseSurfaceFor(index);
        if (!surface) return;
        swipeTo(surface, offset, animate);
    }
    function flowCloseOpenPauseSwipe(animate = true) {
        if (flowOpenSwipePauseIndex === null) return;
        flowSetPauseSwipeOffset(flowOpenSwipePauseIndex, 0, animate);
        flowOpenSwipePauseIndex = null;
    }
    // a11y: closes an open swipe card when tapping elsewhere - harmless and reversible, not an activation (WCAG 2.5.2)
    document.addEventListener('pointerdown', (e) => {
        if (flowOpenSwipePauseIndex === null) return;
        const openBoxEl = document.querySelector(`#flowFermataList [data-pause-index="${flowOpenSwipePauseIndex}"]`);
        if (openBoxEl && !openBoxEl.contains(e.target)) flowCloseOpenPauseSwipe();
    });
    function wireFlowPauseSwipe(boxEl, index, onDelete) {
        const surfaceEl = boxEl.querySelector('.flow-fermata-row');
        let startX = 0, startY = 0, tracking = false, locked = false, abandoned = false;
        function currentBaseOffset() { return flowOpenSwipePauseIndex === index ? -FLOW_PAUSE_SWIPE_OPEN_PX : 0; }
        function onMove(e) {
            if (!tracking || abandoned) return;
            const dx = e.clientX - startX;
            const dy = e.clientY - startY;
            if (!locked) {
                if (Math.abs(dx) > FLOW_PAUSE_SWIPE_LOCK_X_PX && Math.abs(dy) < FLOW_PAUSE_SWIPE_LOCK_Y_MAX_PX) {
                    locked = true;
                    if (flowOpenSwipePauseIndex !== null && flowOpenSwipePauseIndex !== index) flowCloseOpenPauseSwipe(false);
                } else if (Math.abs(dy) >= FLOW_PAUSE_SWIPE_LOCK_Y_MAX_PX) {
                    abandoned = true;
                    return;
                } else {
                    return;
                }
            }
            e.preventDefault();
            const offset = Math.min(0, Math.max(-FLOW_PAUSE_SWIPE_OPEN_PX, currentBaseOffset() + dx));
            swipeTo(surfaceEl, offset, false, true);
        }
        function onUp(e) {
            if (!tracking) return;
            tracking = false;
            document.removeEventListener('pointermove', onMove);
            document.removeEventListener('pointerup', onUp);
            if (!locked) return;
            flowPauseSwipeEndedAt = Date.now();
            const dx = e.clientX - startX;
            const finalOffset = Math.min(0, Math.max(-FLOW_PAUSE_SWIPE_OPEN_PX, currentBaseOffset() + dx));
            if (Math.abs(finalOffset) > FLOW_PAUSE_SWIPE_SNAP_THRESHOLD_PX) {
                flowSetPauseSwipeOffset(index, -FLOW_PAUSE_SWIPE_OPEN_PX, true);
                flowOpenSwipePauseIndex = index;
            } else {
                flowSetPauseSwipeOffset(index, 0, true);
                if (flowOpenSwipePauseIndex === index) flowOpenSwipePauseIndex = null;
            }
        }
        // a11y: only records where a swipe/drag gesture starts - nothing activates on press (WCAG 2.5.2)
        boxEl.addEventListener('pointerdown', (e) => {
            if (e.target.closest(FLOW_PAUSE_SWIPE_EXCLUDE_SELECTOR)) return;
            startX = e.clientX;
            startY = e.clientY;
            tracking = true;
            locked = false;
            abandoned = false;
            document.addEventListener('pointermove', onMove);
            document.addEventListener('pointerup', onUp);
        });
        boxEl.querySelector('[data-pause-swipe-delete]')?.addEventListener('click', (e) => {
            e.stopPropagation();
            flowOpenSwipePauseIndex = null;
            onDelete();
        });
    }
    // Shows/hides the form vs. the "+ Add pause" button - separate from renderFlowFermataAddSection
    // (which fills in the form's own content) since the two toggle independently: closing the form
    // doesn't touch the draft, and re-rendering the draft doesn't touch open/closed state.
    function renderFlowFermataFormState() {
        document.getElementById('flowFermataAddBox')?.classList.toggle('hidden-group', !flowFermataFormOpen);
        document.getElementById('flowFermataOpenFormBtn')?.classList.toggle('hidden-group', flowFermataFormOpen);
    }
    function renderFlowFermataAddSection() {
        const draft = flowFermataDraft;
        if (!draft) return;
        const b = flowFindBlockById(flowFermataTargetBlockId);
        const editing = !!flowFermataEditTarget;
        const hasPauses = !!(b && b.fermatas && b.fermatas.length);
        // Leads with the plain-English effect ("Hold note"/"Silent pause"), the musical term
        // ("Fermata"/"Caesura") second and smaller - most users recognise the symbol, not the term.
        document.getElementById('flowFermataKindGrid').innerHTML = [
            { key: 'fermata', title: 'Hold note', sub: 'Fermata' },
            { key: 'caesura', title: 'Silent pause', sub: 'Caesura' }
        ].map(o => `
            <button type="button" class="flow-pause-kind-btn${draft.kind === o.key ? ' selected' : ''}" data-pause-kind="${o.key}">
                ${flowPauseIconSvg(o.key)}
                <span class="flow-pause-kind-title">${o.title}</span>
                <span class="flow-pause-kind-sub">${o.sub}</span>
            </button>
        `).join('');
        document.getElementById('flowFermataKindGrid').querySelectorAll('[data-pause-kind]').forEach(btn => {
            btn.addEventListener('click', () => {
                draft.kind = btn.dataset.pauseKind;
                renderFlowFermataAddSection();
            });
        });
        // Editing a pause already stranded on a bar the block no longer has (see the row list's own
        // flow-fermata-row-text-invalid) carries the same red flag into the form - the warning icon
        // sits to the left of the minus button (flowFermataBarWarning), not inside the readout, so
        // it reads as "this whole row needs fixing" while still letting the stepper walk the value
        // back down into range (not clamped, same "flag, don't clamp" rule as everywhere else).
        const barInvalid = draft.bar > draft.maxBar;
        const barValueEl = document.getElementById('flowFermataBarValue');
        barValueEl.classList.toggle('flow-bar-readout-invalid', barInvalid);
        barValueEl.innerText = `Bar ${draft.bar} of ${draft.maxBar}`;
        document.getElementById('flowFermataBarWarning').innerHTML = barInvalid ? flowWarningIconSvg('flow-warning-icon') : '';
        const pauseBlock = flowFindBlockById(flowFermataTargetBlockId);
        document.getElementById('flowFermataBeatValue').innerText = `Beat ${flowPauseBeatNumber(pauseBlock, draft.beat)} of ${flowPauseBeatCount(pauseBlock)}`;
        document.getElementById('flowFermataDurationValue').innerText = `${draft.duration} beat${draft.duration === 1 ? '' : 's'}`;
        document.getElementById('flowFermataBeatLabel').innerText = draft.kind === 'caesura' ? 'After beat' : 'On beat';
        document.getElementById('flowFermataDurationLabel').innerText = draft.kind === 'caesura' ? 'Silence duration' : 'Hold duration';
        // No caption at all on the empty-block form (nothing to distinguish it from) - "Add another
        // pause"/"Edit pause" once the block already has at least one, matching how this form was
        // reached (the +Add another pause button vs. a row's Edit menu item).
        const addBoxLabel = document.getElementById('flowFermataAddBoxLabel');
        addBoxLabel.classList.toggle('hidden-group', !hasPauses);
        addBoxLabel.innerText = editing ? 'Edit pause' : 'Add another pause';
        // Three distinct button copies: the very first pause on an empty block ("+ Insert pause into
        // block"), an additional one once the list is already populated ("+ Add pause"), and editing
        // an existing one ("Update pause") - matches how each of those states was reached.
        document.getElementById('flowFermataAddBtn').innerText = editing ? 'Update pause' : (hasPauses ? '+ Add pause' : '+ Insert pause into block');
        // Only meaningful when there's a collapsed list view to cancel back to - the empty-block
        // form has nowhere to collapse to, so no Cancel there.
        document.getElementById('flowFermataCancelEditBtn').classList.toggle('hidden-group', !hasPauses);
    }
    function flowFermataResetDraft(kind) {
        const b = flowFindBlockById(flowFermataTargetBlockId);
        flowFermataDraft = {
            kind: kind || 'fermata', bar: 1, beat: 1, duration: 2,
            maxBar: Math.max(1, (b && b.barCount) || 1), maxBeat: Math.max(1, (b && b.numerator) || 4)
        };
    }
    function openFlowFermataModal(blockId) {
        const b = flowFindBlockById(blockId);
        if (!b) return;
        flowFermataTargetBlockId = blockId;
        const idx = currentFlowBlocks.findIndex(x => x.id === blockId);
        document.getElementById('flowFermataPill').innerText = idx === -1 ? '' : flowBarRangeLabel(idx);
        flowFermataEditTarget = null;
        flowFermataResetDraft();
        flowFermataFormOpen = !(b.fermatas && b.fermatas.length);
        renderFlowFermataList();
        renderFlowFermataAddSection();
        renderFlowFermataFormState();
        showModal('flowFermataModal');
    }
    function closeFlowFermataModal() {
        hideModal('flowFermataModal');
        flowFermataTargetBlockId = null;
        flowFermataDraft = null;
        flowFermataEditTarget = null;
    }
    document.getElementById('flowFermataOpenFormBtn')?.addEventListener('click', () => {
        flowFermataEditTarget = null;
        flowFermataResetDraft();
        flowFermataFormOpen = true;
        renderFlowFermataAddSection();
        renderFlowFermataFormState();
    });
    // --- Per-row options menu (Edit/Delete) - same shared floating dropdown-menu + measure-then-
    // clamp positioning as openFlowBlockMenu/openQpHistoryItemMenu. ---
    function openFlowFermataRowMenu(btnEl, target) {
        flowFermataRowMenuTarget = target;
        const menu = document.getElementById('flowFermataRowMenu');
        menu.classList.add('show');
        const btnRect = btnEl.getBoundingClientRect();
        const menuWidth = menu.offsetWidth;
        const menuHeight = menu.offsetHeight;
        let left = btnRect.right - menuWidth;
        left = Math.max(8, Math.min(left, window.innerWidth - menuWidth - 8));
        let top = btnRect.bottom + 4;
        top = Math.min(top, window.innerHeight - menuHeight - 8);
        placeAt(menu, left, top);
    }
    function closeFlowFermataRowMenu() {
        document.getElementById('flowFermataRowMenu')?.classList.remove('show');
    }
    document.addEventListener('click', closeFlowFermataRowMenu);
    document.getElementById('flowFermataRowMenuEdit')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const target = flowFermataRowMenuTarget;
        closeFlowFermataRowMenu();
        if (target) flowEditPause(target);
    });
    function flowEditPause(target) {
        flowFermataEditTarget = target;
        const kind = target.kind || 'fermata';
        flowFermataResetDraft(kind);
        flowFermataDraft.bar = (target.barOffset || 0) + 1;
        flowFermataDraft.beat = target.beatOffset;
        flowFermataDraft.duration = target.holdBeats;
        flowFermataFormOpen = true;
        renderFlowFermataAddSection();
        renderFlowFermataFormState();
    }
    document.getElementById('flowFermataRowMenuDelete')?.addEventListener('click', async (e) => {
        e.stopPropagation();
        const target = flowFermataRowMenuTarget;
        closeFlowFermataRowMenu();
        const b = flowFindBlockById(flowFermataTargetBlockId);
        if (!b || !target) return;
        if (flowFermataEditTarget === target) {
            flowFermataEditTarget = null;
            flowFermataResetDraft(flowFermataDraft ? flowFermataDraft.kind : undefined);
        }
        const remaining = (b.fermatas || []).filter(f => f !== target);
        await flowUpdateBlock(b.id, { fermatas: remaining });
        // Back to the empty-state "form always open" behaviour once the last pause is gone.
        if (!remaining.length) flowFermataFormOpen = true;
        renderFlowFermataList();
        renderFlowFermataAddSection();
        renderFlowFermataFormState();
    });
    document.getElementById('flowFermataCancelEditBtn')?.addEventListener('click', () => {
        flowFermataEditTarget = null;
        flowFermataResetDraft(flowFermataDraft ? flowFermataDraft.kind : undefined);
        flowFermataFormOpen = false;
        renderFlowFermataAddSection();
        renderFlowFermataFormState();
    });
    setupHoldStepper(document.getElementById('flowFermataBarMinus'), -1, (amount) => {
        if (!flowFermataDraft) return;
        flowFermataDraft.bar = Math.max(1, flowFermataDraft.bar + amount);
        renderFlowFermataAddSection();
    });
    setupHoldStepper(document.getElementById('flowFermataBarPlus'), 1, (amount) => {
        if (!flowFermataDraft) return;
        flowFermataDraft.bar = Math.max(1, Math.min(flowFermataDraft.maxBar, flowFermataDraft.bar + amount));
        renderFlowFermataAddSection();
    });
    setupHoldStepper(document.getElementById('flowFermataBeatMinus'), -1, (amount) => {
        if (!flowFermataDraft) return;
        flowFermataDraft.beat = Math.max(1, flowFermataDraft.beat + amount * flowPauseStep(flowFindBlockById(flowFermataTargetBlockId)));
        renderFlowFermataAddSection();
    });
    setupHoldStepper(document.getElementById('flowFermataBeatPlus'), 1, (amount) => {
        if (!flowFermataDraft) return;
        const step = flowPauseStep(flowFindBlockById(flowFermataTargetBlockId)); // ML-365: in the bar's pause steps
        flowFermataDraft.beat = Math.max(1, Math.min(flowFermataDraft.maxBeat + 1 - step, flowFermataDraft.beat + amount * step));
        renderFlowFermataAddSection();
    });
    setupHoldStepper(document.getElementById('flowFermataDurationMinus'), -1, (amount) => {
        if (!flowFermataDraft) return;
        flowFermataDraft.duration = Math.max(2, flowFermataDraft.duration + amount);
        renderFlowFermataAddSection();
    });
    setupHoldStepper(document.getElementById('flowFermataDurationPlus'), 1, (amount) => {
        if (!flowFermataDraft) return;
        flowFermataDraft.duration = Math.max(2, Math.min(4, flowFermataDraft.duration + amount));
        renderFlowFermataAddSection();
    });
    document.getElementById('flowFermataAddBtn')?.addEventListener('click', async () => {
        const b = flowFindBlockById(flowFermataTargetBlockId);
        if (!b || !flowFermataDraft) return;
        const draft = flowFermataDraft;
        const entry = {
            kind: draft.kind, barOffset: draft.bar - 1, beatOffset: draft.beat, holdBeats: draft.duration,
            playbackMode: draft.kind === 'caesura' ? 'silent' : 'tone'
        };
        const existing = b.fermatas || [];
        const fermatas = flowFermataEditTarget
            ? existing.map(f => f === flowFermataEditTarget ? entry : f)
            : [...existing, entry];
        await flowUpdateBlock(b.id, { fermatas });
        flowFermataEditTarget = null;
        flowFermataResetDraft(draft.kind);
        // Collapse back to the list + "+ Add pause" button - fermatas is never empty at this point
        // (an entry was just inserted/updated into it), so this always lands in the populated state.
        flowFermataFormOpen = false;
        renderFlowFermataList();
        renderFlowFermataAddSection();
        renderFlowFermataFormState();
    });
    document.getElementById('flowFermataCloseBtn')?.addEventListener('click', closeFlowFermataModal);

    // --- Tempo ramps list (#flowRampModal) - same shape as the Pauses list directly above (list +
    // count once populated, "+ Add another ramp" collapses the form, row Edit/Delete via the 3-dot
    // menu plus swipe-to-delete), one ramp entry being { startBarOffset, startBeatOffset, endMode:
    // 'block_end'|'specific', endBarOffset, endBeatOffset, targetMode: 'next_block'|'custom',
    // targetBpm } (metronome_segment_ramps - a block can hold more than one, ML-179 follow-up).
    // List edits write immediately via flowUpdateBlock, same as Pauses; only the form below is a
    // local draft, reset after each insert/save. ---
    let flowRampDraft = null; // { bar, beat, endMode, endBar, endBeat, targetMode, targetBpm, maxBar, maxBeat }
    let flowRampEditTarget = null; // the b.ramps entry currently being edited, or null when adding new
    let flowRampRowMenuTarget = null;
    let flowRampTargetBlockId = null;
    let flowRampFormOpen = true;

    // The block right after the one this modal is open for, in sequence - what a 'next_block'
    // target mode actually resolves to (and, if undefined, why that target mode is flagged invalid).
    function flowRampNextBlock() {
        const idx = currentFlowBlocks.findIndex(x => x.id === flowRampTargetBlockId);
        return idx === -1 ? undefined : currentFlowBlocks[idx + 1];
    }
    function flowRampSorted(ramps) {
        return [...ramps].sort((a, b) => (a.startBarOffset || 0) - (b.startBarOffset || 0) || a.startBeatOffset - b.startBeatOffset);
    }
    function flowRampEndLabel(r) {
        return r.endMode === 'specific' ? `Bar ${(r.endBarOffset || 0) + 1}, beat ${r.endBeatOffset}` : 'End of block';
    }
    function flowRampTargetLabel(r, nextBlock) {
        if (r.targetMode === 'custom') return `${r.targetBpm} bpm`;
        return nextBlock ? `${nextBlock.bpm} bpm` : 'next block';
    }
    function flowRampRowInvalid(r, maxBar, nextBlock) {
        if (((r.startBarOffset || 0) + 1) > maxBar) return true;
        if (r.endMode === 'specific' && ((r.endBarOffset || 0) + 1) > maxBar) return true;
        if (r.targetMode === 'next_block' && !nextBlock) return true;
        return false;
    }
    function renderFlowRampList() {
        const b = flowFindBlockById(flowRampTargetBlockId);
        const list = document.getElementById('flowRampList');
        if (!b || !list) return;
        const ramps = b.ramps || [];
        if (flowRampEditTarget && !ramps.includes(flowRampEditTarget)) {
            flowRampEditTarget = null;
        }
        document.getElementById('flowRampListHeader')?.classList.toggle('hidden-group', !ramps.length);
        const countBadge = document.getElementById('flowRampCountBadge');
        if (countBadge) countBadge.innerText = String(ramps.length);
        if (!ramps.length) {
            list.innerHTML = '';
            return;
        }
        const maxBar = Math.max(1, b.barCount || 1);
        const nextBlock = flowRampNextBlock();
        const sorted = flowRampSorted(ramps);
        flowOpenSwipeRampIndex = null;
        list.innerHTML = sorted.map((r, i) => {
            const invalid = flowRampRowInvalid(r, maxBar, nextBlock);
            return `
                <div class="flow-ramp-box" data-ramp-index="${i}">
                    <div role="button" tabindex="0" class="flow-ramp-delete-underlay" data-ramp-swipe-delete aria-label="Delete ramp">
                        <span class="material-symbols-outlined">delete</span>
                        <span>Delete</span>
                    </div>
                    <div class="flow-ramp-row">
                        <button type="button" class="flow-list-row-body flow-ramp-row-text${invalid ? ' flow-ramp-row-text-invalid' : ''}" data-ramp-edit>
                            <span class="flow-ramp-row-icon${invalid ? ' invalid' : ''}">${invalid ? flowWarningIconSvg() : flowRampIconSvg(flowRampDirection(r, b, nextBlock))}</span>
                            <span class="flow-ramp-row-lines">
                                <span class="flow-ramp-row-title">Bar ${(r.startBarOffset || 0) + 1}, beat ${r.startBeatOffset} &rarr; ${flowRampEndLabel(r)}</span>
                                <span class="flow-ramp-row-tag">Tempo change &middot; To ${flowRampTargetLabel(r, nextBlock)}</span>
                            </span>
                        </button>
                        <button type="button" class="list-item-menu-btn" data-ramp-menu aria-label="Ramp options" aria-haspopup="menu" aria-expanded="false"><span class="material-symbols-outlined">more_vert</span></button>
                    </div>
                </div>
            `;
        }).join('');
        list.querySelectorAll('[data-ramp-menu]').forEach((btn, i) => {
            btn.addEventListener('click', (e) => {
                e.stopPropagation();
                openFlowRampRowMenu(btn, sorted[i]);
            });
        });
        // ML-286: tap the row to edit the ramp - same as the pause rows above.
        list.querySelectorAll('[data-ramp-edit]').forEach((body, i) => {
            body.addEventListener('click', (e) => {
                e.stopPropagation();
                if (Date.now() - flowRampSwipeEndedAt < 400) return;
                if (flowOpenSwipeRampIndex !== null) { flowCloseOpenRampSwipe(); return; }
                flowEditRamp(sorted[i]);
            });
        });
        list.querySelectorAll('.flow-ramp-box').forEach((boxEl, i) => {
            const target = sorted[i];
            wireFlowRampSwipe(boxEl, i, async () => {
                await flowUpdateBlock(b.id, { ramps: ramps.filter(x => x !== target) });
                renderFlowRampList();
            });
        });
    }
    // --- Ramp row swipe-to-delete - own copy of wireFlowPauseSwipe's own shape (which is itself its
    // own copy of wireFlowBlockSwipe/wireQpBarSwipe, minus their reorder half - see that function's
    // own comment for why this isn't shared code). ---
    let flowOpenSwipeRampIndex = null;
    const FLOW_RAMP_SWIPE_LOCK_X_PX = 30;
    const FLOW_RAMP_SWIPE_LOCK_Y_MAX_PX = 15;
    const FLOW_RAMP_SWIPE_OPEN_PX = 96; // keep in sync with .flow-ramp-delete-underlay's width in style.css
    const FLOW_RAMP_SWIPE_SNAP_THRESHOLD_PX = 48;
    // The row body (data-ramp-edit) is a button too (ML-286: tap the row to edit it), but a swipe may start on it.
    const FLOW_RAMP_SWIPE_EXCLUDE_SELECTOR = 'button:not([data-ramp-edit]), input, [role="slider"], [role="button"]';
    let flowRampSwipeEndedAt = 0; // a swipe's own pointerup is followed by a click on the body - that click isn't a tap
    function flowRampSurfaceFor(index) {
        return document.querySelector(`#flowRampList [data-ramp-index="${index}"] .flow-ramp-row`);
    }
    function flowSetRampSwipeOffset(index, offset, animate) {
        const surface = flowRampSurfaceFor(index);
        if (!surface) return;
        swipeTo(surface, offset, animate);
    }
    function flowCloseOpenRampSwipe(animate = true) {
        if (flowOpenSwipeRampIndex === null) return;
        flowSetRampSwipeOffset(flowOpenSwipeRampIndex, 0, animate);
        flowOpenSwipeRampIndex = null;
    }
    // a11y: closes an open swipe card when tapping elsewhere - harmless and reversible, not an activation (WCAG 2.5.2)
    document.addEventListener('pointerdown', (e) => {
        if (flowOpenSwipeRampIndex === null) return;
        const openBoxEl = document.querySelector(`#flowRampList [data-ramp-index="${flowOpenSwipeRampIndex}"]`);
        if (openBoxEl && !openBoxEl.contains(e.target)) flowCloseOpenRampSwipe();
    });
    function wireFlowRampSwipe(boxEl, index, onDelete) {
        const surfaceEl = boxEl.querySelector('.flow-ramp-row');
        let startX = 0, startY = 0, tracking = false, locked = false, abandoned = false;
        function currentBaseOffset() { return flowOpenSwipeRampIndex === index ? -FLOW_RAMP_SWIPE_OPEN_PX : 0; }
        function onMove(e) {
            if (!tracking || abandoned) return;
            const dx = e.clientX - startX;
            const dy = e.clientY - startY;
            if (!locked) {
                if (Math.abs(dx) > FLOW_RAMP_SWIPE_LOCK_X_PX && Math.abs(dy) < FLOW_RAMP_SWIPE_LOCK_Y_MAX_PX) {
                    locked = true;
                    if (flowOpenSwipeRampIndex !== null && flowOpenSwipeRampIndex !== index) flowCloseOpenRampSwipe(false);
                } else if (Math.abs(dy) >= FLOW_RAMP_SWIPE_LOCK_Y_MAX_PX) {
                    abandoned = true;
                    return;
                } else {
                    return;
                }
            }
            e.preventDefault();
            const offset = Math.min(0, Math.max(-FLOW_RAMP_SWIPE_OPEN_PX, currentBaseOffset() + dx));
            swipeTo(surfaceEl, offset, false, true);
        }
        function onUp(e) {
            if (!tracking) return;
            tracking = false;
            document.removeEventListener('pointermove', onMove);
            document.removeEventListener('pointerup', onUp);
            if (!locked) return;
            flowRampSwipeEndedAt = Date.now();
            const dx = e.clientX - startX;
            const finalOffset = Math.min(0, Math.max(-FLOW_RAMP_SWIPE_OPEN_PX, currentBaseOffset() + dx));
            if (Math.abs(finalOffset) > FLOW_RAMP_SWIPE_SNAP_THRESHOLD_PX) {
                flowSetRampSwipeOffset(index, -FLOW_RAMP_SWIPE_OPEN_PX, true);
                flowOpenSwipeRampIndex = index;
            } else {
                flowSetRampSwipeOffset(index, 0, true);
                if (flowOpenSwipeRampIndex === index) flowOpenSwipeRampIndex = null;
            }
        }
        // a11y: only records where a swipe/drag gesture starts - nothing activates on press (WCAG 2.5.2)
        boxEl.addEventListener('pointerdown', (e) => {
            if (e.target.closest(FLOW_RAMP_SWIPE_EXCLUDE_SELECTOR)) return;
            startX = e.clientX;
            startY = e.clientY;
            tracking = true;
            locked = false;
            abandoned = false;
            document.addEventListener('pointermove', onMove);
            document.addEventListener('pointerup', onUp);
        });
        boxEl.querySelector('[data-ramp-swipe-delete]')?.addEventListener('click', (e) => {
            e.stopPropagation();
            flowOpenSwipeRampIndex = null;
            onDelete();
        });
    }
    function renderFlowRampFormState() {
        document.getElementById('flowRampAddBox')?.classList.toggle('hidden-group', !flowRampFormOpen);
        document.getElementById('flowRampOpenFormBtn')?.classList.toggle('hidden-group', flowRampFormOpen);
    }
    function renderFlowRampAddSection() {
        const draft = flowRampDraft;
        if (!draft) return;
        const editing = !!flowRampEditTarget;
        const b = flowFindBlockById(flowRampTargetBlockId);
        const hasRamps = !!(b && b.ramps && b.ramps.length);
        const nextBlock = flowRampNextBlock();

        const barInvalid = draft.bar > draft.maxBar;
        const barValueEl = document.getElementById('flowRampBarValue');
        barValueEl.classList.toggle('flow-bar-readout-invalid', barInvalid);
        barValueEl.innerText = `Bar ${draft.bar} of ${draft.maxBar}`;
        document.getElementById('flowRampBeatValue').innerText = `Beat ${draft.beat} of ${draft.maxBeat}`;

        document.querySelectorAll('#flowRampEndModeToggle [data-ramp-end-mode]').forEach(btn => {
            btn.classList.toggle('selected', btn.dataset.rampEndMode === draft.endMode);
        });
        const specific = draft.endMode === 'specific';
        document.getElementById('flowRampEndBarCard')?.classList.toggle('hidden-group', !specific);
        document.getElementById('flowRampEndBeatCard')?.classList.toggle('hidden-group', !specific);
        if (specific) {
            const endBarInvalid = draft.endBar > draft.maxBar;
            const endBarValueEl = document.getElementById('flowRampEndBarValue');
            endBarValueEl.classList.toggle('flow-bar-readout-invalid', endBarInvalid);
            endBarValueEl.innerText = `Bar ${draft.endBar} of ${draft.maxBar}`;
            document.getElementById('flowRampEndBarWarning').innerHTML = endBarInvalid ? flowWarningIconSvg('flow-warning-icon') : '';
            document.getElementById('flowRampEndBeatValue').innerText = `Beat ${draft.endBeat} of ${draft.maxBeat}`;
            // A ramp landing at a specific mid-block beat can't defer to "whatever the next block's
            // bpm turns out to be" - same forced-value rule validateSegmentPayload enforces server-side.
            if (draft.targetMode === 'next_block') draft.targetMode = 'custom';
        }

        document.getElementById('flowRampTargetSubtitle').innerText = specific ? 'Only custom bpm allowed before block end' : 'Final tempo to reach';
        document.getElementById('flowRampTargetGrid').innerHTML = [
            { key: 'next_block', title: 'Next block', sub: nextBlock ? `${nextBlock.bpm} bpm` : 'No next block', disabled: specific || !nextBlock },
            { key: 'custom', title: 'Custom bpm', sub: `${draft.targetBpm} bpm` }
        ].map(o => `
            <button type="button" class="flow-pause-kind-btn${draft.targetMode === o.key ? ' selected' : ''}" data-ramp-target="${o.key}"${o.disabled ? ' disabled' : ''}>
                <span class="flow-pause-kind-title">${o.title}</span>
                <span class="flow-pause-kind-sub">${o.sub}</span>
            </button>
        `).join('');
        document.querySelectorAll('#flowRampTargetGrid [data-ramp-target]:not(:disabled)').forEach(btn => {
            btn.addEventListener('click', () => {
                draft.targetMode = btn.dataset.rampTarget;
                renderFlowRampAddSection();
            });
        });

        const showCustomTempo = draft.targetMode === 'custom';
        document.getElementById('flowRampCustomTempoCard')?.classList.toggle('hidden-group', !showCustomTempo);
        document.getElementById('flowRampCustomTempoValue').innerText = draft.targetBpm;

        const addBoxLabel = document.getElementById('flowRampAddBoxLabel');
        addBoxLabel.classList.toggle('hidden-group', !hasRamps);
        addBoxLabel.innerText = editing ? 'Edit ramp' : 'Add another ramp';
        document.getElementById('flowRampAddBtn').innerText = editing ? 'Update ramp' : (hasRamps ? '+ Add ramp' : '+ Insert ramp into block');
        document.getElementById('flowRampCancelEditBtn').classList.toggle('hidden-group', !hasRamps);
    }
    function flowRampResetDraft() {
        const b = flowFindBlockById(flowRampTargetBlockId);
        const nextBlock = flowRampNextBlock();
        flowRampDraft = {
            bar: 1, beat: 1,
            endMode: 'block_end', endBar: 1, endBeat: 1,
            // "Next block" is the more useful default when there is one (matches the old single-ramp
            // field's own implicit "lands on the next segment's bpm" behaviour) - falls back to
            // custom when there isn't, since "next block" would have nothing to resolve to.
            targetMode: nextBlock ? 'next_block' : 'custom',
            targetBpm: (b && b.bpm) || 120,
            maxBar: Math.max(1, (b && b.barCount) || 1), maxBeat: Math.max(1, (b && b.numerator) || 4)
        };
    }
    function openFlowRampModal(blockId) {
        const b = flowFindBlockById(blockId);
        if (!b) return;
        flowRampTargetBlockId = blockId;
        const idx = currentFlowBlocks.findIndex(x => x.id === blockId);
        document.getElementById('flowRampPill').innerText = idx === -1 ? '' : flowBarRangeLabel(idx);
        flowRampEditTarget = null;
        flowRampResetDraft();
        flowRampFormOpen = !(b.ramps && b.ramps.length);
        renderFlowRampList();
        renderFlowRampAddSection();
        renderFlowRampFormState();
        showModal('flowRampModal');
    }
    function closeFlowRampModal() {
        hideModal('flowRampModal');
        flowRampTargetBlockId = null;
        flowRampDraft = null;
        flowRampEditTarget = null;
    }
    document.getElementById('flowRampOpenFormBtn')?.addEventListener('click', () => {
        flowRampEditTarget = null;
        flowRampResetDraft();
        flowRampFormOpen = true;
        renderFlowRampAddSection();
        renderFlowRampFormState();
    });
    function openFlowRampRowMenu(btnEl, target) {
        flowRampRowMenuTarget = target;
        const menu = document.getElementById('flowRampRowMenu');
        menu.classList.add('show');
        const btnRect = btnEl.getBoundingClientRect();
        const menuWidth = menu.offsetWidth;
        const menuHeight = menu.offsetHeight;
        let left = btnRect.right - menuWidth;
        left = Math.max(8, Math.min(left, window.innerWidth - menuWidth - 8));
        let top = btnRect.bottom + 4;
        top = Math.min(top, window.innerHeight - menuHeight - 8);
        placeAt(menu, left, top);
    }
    function closeFlowRampRowMenu() {
        document.getElementById('flowRampRowMenu')?.classList.remove('show');
    }
    document.addEventListener('click', closeFlowRampRowMenu);
    document.getElementById('flowRampRowMenuEdit')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const target = flowRampRowMenuTarget;
        closeFlowRampRowMenu();
        if (target) flowEditRamp(target);
    });
    function flowEditRamp(target) {
        flowRampEditTarget = target;
        flowRampResetDraft();
        flowRampDraft.bar = (target.startBarOffset || 0) + 1;
        flowRampDraft.beat = target.startBeatOffset;
        flowRampDraft.endMode = target.endMode;
        flowRampDraft.endBar = (target.endBarOffset || 0) + 1;
        flowRampDraft.endBeat = target.endBeatOffset || 1;
        flowRampDraft.targetMode = target.targetMode;
        flowRampDraft.targetBpm = target.targetBpm || flowRampDraft.targetBpm;
        flowRampFormOpen = true;
        renderFlowRampAddSection();
        renderFlowRampFormState();
    }
    document.getElementById('flowRampRowMenuDelete')?.addEventListener('click', async (e) => {
        e.stopPropagation();
        const target = flowRampRowMenuTarget;
        closeFlowRampRowMenu();
        const b = flowFindBlockById(flowRampTargetBlockId);
        if (!b || !target) return;
        if (flowRampEditTarget === target) {
            flowRampEditTarget = null;
            flowRampResetDraft();
        }
        const remaining = (b.ramps || []).filter(r => r !== target);
        await flowUpdateBlock(b.id, { ramps: remaining });
        // Back to the empty-state "form always open" behaviour once the last ramp is gone.
        if (!remaining.length) flowRampFormOpen = true;
        renderFlowRampList();
        renderFlowRampAddSection();
        renderFlowRampFormState();
    });
    document.getElementById('flowRampCancelEditBtn')?.addEventListener('click', () => {
        flowRampEditTarget = null;
        flowRampResetDraft();
        flowRampFormOpen = false;
        renderFlowRampAddSection();
        renderFlowRampFormState();
    });
    setupHoldStepper(document.getElementById('flowRampBarMinus'), -1, (amount) => {
        if (!flowRampDraft) return;
        flowRampDraft.bar = Math.max(1, flowRampDraft.bar + amount);
        renderFlowRampAddSection();
    });
    setupHoldStepper(document.getElementById('flowRampBarPlus'), 1, (amount) => {
        if (!flowRampDraft) return;
        flowRampDraft.bar = Math.max(1, Math.min(flowRampDraft.maxBar, flowRampDraft.bar + amount));
        renderFlowRampAddSection();
    });
    setupHoldStepper(document.getElementById('flowRampBeatMinus'), -1, (amount) => {
        if (!flowRampDraft) return;
        flowRampDraft.beat = Math.max(1, flowRampDraft.beat + amount);
        renderFlowRampAddSection();
    });
    setupHoldStepper(document.getElementById('flowRampBeatPlus'), 1, (amount) => {
        if (!flowRampDraft) return;
        flowRampDraft.beat = Math.max(1, Math.min(flowRampDraft.maxBeat, flowRampDraft.beat + amount));
        renderFlowRampAddSection();
    });
    setupHoldStepper(document.getElementById('flowRampEndBarMinus'), -1, (amount) => {
        if (!flowRampDraft) return;
        flowRampDraft.endBar = Math.max(1, flowRampDraft.endBar + amount);
        renderFlowRampAddSection();
    });
    setupHoldStepper(document.getElementById('flowRampEndBarPlus'), 1, (amount) => {
        if (!flowRampDraft) return;
        flowRampDraft.endBar = Math.max(1, Math.min(flowRampDraft.maxBar, flowRampDraft.endBar + amount));
        renderFlowRampAddSection();
    });
    setupHoldStepper(document.getElementById('flowRampEndBeatMinus'), -1, (amount) => {
        if (!flowRampDraft) return;
        flowRampDraft.endBeat = Math.max(1, flowRampDraft.endBeat + amount);
        renderFlowRampAddSection();
    });
    setupHoldStepper(document.getElementById('flowRampEndBeatPlus'), 1, (amount) => {
        if (!flowRampDraft) return;
        flowRampDraft.endBeat = Math.max(1, Math.min(flowRampDraft.maxBeat, flowRampDraft.endBeat + amount));
        renderFlowRampAddSection();
    });
    document.querySelectorAll('#flowRampEndModeToggle [data-ramp-end-mode]').forEach(btn => {
        btn.addEventListener('click', () => {
            if (!flowRampDraft) return;
            flowRampDraft.endMode = btn.dataset.rampEndMode;
            renderFlowRampAddSection();
        });
    });
    document.getElementById('flowRampCustomTempoBtn')?.addEventListener('click', () => {
        if (!flowRampDraft) return;
        flowOpenBpmModal(null, {
            value: flowRampDraft.targetBpm,
            onApply: (v) => {
                flowRampDraft.targetBpm = v;
                renderFlowRampAddSection();
            }
        });
    });
    document.getElementById('flowRampAddBtn')?.addEventListener('click', async () => {
        const b = flowFindBlockById(flowRampTargetBlockId);
        if (!b || !flowRampDraft) return;
        const draft = flowRampDraft;
        const entry = {
            startBarOffset: draft.bar - 1, startBeatOffset: draft.beat,
            endMode: draft.endMode,
            endBarOffset: draft.endMode === 'specific' ? draft.endBar - 1 : null,
            endBeatOffset: draft.endMode === 'specific' ? draft.endBeat : null,
            targetMode: draft.targetMode,
            targetBpm: draft.targetMode === 'custom' ? draft.targetBpm : null
        };
        const existing = b.ramps || [];
        const ramps = flowRampEditTarget
            ? existing.map(r => r === flowRampEditTarget ? entry : r)
            : [...existing, entry];
        await flowUpdateBlock(b.id, { ramps });
        flowRampEditTarget = null;
        flowRampResetDraft();
        // Collapse back to the list + "+ Add ramp" button - ramps is never empty at this point (an
        // entry was just inserted/updated into it), so this always lands in the populated state.
        flowRampFormOpen = false;
        renderFlowRampList();
        renderFlowRampAddSection();
        renderFlowRampFormState();
    });
    document.getElementById('flowRampCloseBtn')?.addEventListener('click', closeFlowRampModal);

    // --- Per-block options menu (Duplicate/Move up/Move down/Delete) - same shared floating
    // dropdown-menu + measure-then-clamp positioning as openMetroBlkTileMenu/openQpBarMenu. ---
    function openFlowBlockMenu(btnEl, blockId) {
        flowBlockMenuTargetId = blockId;
        const idx = currentFlowBlocks.findIndex(b => b.id === blockId);
        document.getElementById('flowBlockMenuMoveUp')?.classList.toggle('hidden-group', !flowCanMoveUp(idx));
        document.getElementById('flowBlockMenuMoveDown')?.classList.toggle('hidden-group', !flowCanMoveDown(idx));
        // A flow always has to keep at least one block (matches "Create your own" always seeding
        // one) - same "hide, don't just no-op" precedent as Quick Play's own qpBarMenuDelete.
        document.getElementById('flowBlockMenuDelete')?.classList.toggle('hidden-group', currentFlowBlocks.length <= 1);
        const menu = document.getElementById('flowBlockMenu');
        menu.classList.add('show');
        const btnRect = btnEl.getBoundingClientRect();
        const menuWidth = menu.offsetWidth;
        const menuHeight = menu.offsetHeight;
        let left = btnRect.right - menuWidth;
        left = Math.max(8, Math.min(left, window.innerWidth - menuWidth - 8));
        let top = btnRect.bottom + 4;
        top = Math.min(top, window.innerHeight - menuHeight - 8);
        placeAt(menu, left, top);
    }
    function closeFlowBlockMenu() {
        document.getElementById('flowBlockMenu')?.classList.remove('show');
    }
    document.addEventListener('click', closeFlowBlockMenu);

    document.getElementById('flowBlockMenuDuplicate')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const blockId = flowBlockMenuTargetId;
        closeFlowBlockMenu();
        flowDuplicateBlock(blockId);
    });
    // Shared by the ⋮ menu above and the 4-column layout's bar popup (ML-206). The copy goes straight
    // after the original.
    async function flowDuplicateBlock(blockId) {
        const idx = currentFlowBlocks.findIndex(b => b.id === blockId);
        if (idx < 0) return;
        if (flowEditMode === 'edit') {
            const source = currentFlowBlocks[idx];
            const dup = { ...source, id: `tmp${++flowTempBlockCounter}`, fermatas: [...(source.fermatas || [])], rehearsalMarks: [...(source.rehearsalMarks || [])], movementStart: false, movementTitle: null }; // ML-529: in the same movement
            currentFlowBlocks.splice(idx + 1, 0, dup);
            flowStatsNoteBlockAdded();
            renderFlowBlocksStudio();
            return;
        }
        try {
            const dup = await API.flows.blocks.duplicate(blockId);
            currentFlowBlocks.splice(idx + 1, 0, dup);
            flowStatsNoteBlockAdded();
            renderFlowBlocksStudio(); // not just renderFlowBlocksList - the total bars/runtime summary needs refreshing too
        } catch (error) {
            showWarningToast('Error duplicating bar: ' + error.message);
        }
    }

    async function flowPersistBlockOrder() {
        // Edit mode: the local splice already happened at each call site - saveFlowEdit does one
        // reorder call with the final order when Save is pressed.
        if (flowEditMode === 'edit') return;
        try {
            await API.flows.blocks.reorder(currentFlowId, currentFlowBlocks.map(b => b.id));
        } catch (error) {
            showWarningToast('Error saving order: ' + error.message);
        }
    }

    document.getElementById('flowBlockMenuMoveUp')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const blockId = flowBlockMenuTargetId;
        closeFlowBlockMenu();
        flowMoveBlockUp(blockId);
    });

    document.getElementById('flowBlockMenuMoveDown')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const blockId = flowBlockMenuTargetId;
        closeFlowBlockMenu();
        flowMoveBlockDown(blockId);
    });

    document.getElementById('flowBlockMenuDelete')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const blockId = flowBlockMenuTargetId;
        closeFlowBlockMenu();
        flowDeleteBlockConfirm(blockId);
    });

    // After adding a bar, bring it and "+ Add bar" into view (as Quick Play does) - the button is the
    // last thing on the page, so scrolling to the bottom shows both above the pinned Cancel/Save bar.
    function scrollFlowBarsToEnd() {
        requestAnimationFrame(() => window.scrollTo({ top: document.documentElement.scrollHeight, behavior: scrollMotion() }));
    }
    document.getElementById('flowAddBlockBtn')?.addEventListener('click', async () => {
        if (!currentFlowId) return;
        const lastBlock = currentFlowBlocks[currentFlowBlocks.length - 1];
        const data = {
            barCount: lastBlock ? lastBlock.barCount : 4,
            bpm: lastBlock ? lastBlock.bpm : 120,
            // The new bar copies the last bar's time signature - public OR your own, never both. ML-423: when the
            // last bar had one of your own (no public id), this fell back to the first public one as well, so the
            // new bar asked for two and the server refused it ("Choose exactly one time signature").
            timeSignatureId: lastBlock ? (lastBlock.accountTimeSignatureId ? null : lastBlock.timeSignatureId) : (metroBlkTimeSigCache.public[0] ? metroBlkTimeSigCache.public[0].id : null),
            accountTimeSignatureId: lastBlock ? lastBlock.accountTimeSignatureId ?? null : null,
            // ML-362: the beat note (the note the bpm counts - crotchet, minim...) carries on too, so a new
            // bar at the same bpm plays at the same speed
            noteValue: lastBlock ? lastBlock.noteValue ?? null : null
        };
        if (flowEditMode === 'edit') {
            currentFlowBlocks.push(buildLocalFlowBlockDto(data));
            flowStatsNoteBlockAdded();
            renderFlowBlocksStudio();
            scrollFlowBarsToEnd();
            return;
        }
        try {
            const newBlock = await API.flows.blocks.create(currentFlowId, data);
            currentFlowBlocks.push(newBlock);
            flowStatsNoteBlockAdded();
            renderFlowBlocksStudio(); // not just renderFlowBlocksList - the total bars/runtime summary needs refreshing too
            scrollFlowBarsToEnd();
        } catch (error) {
            showWarningToast('Error adding bar: ' + error.message);
        }
    });

    // "Use flow" (Blocks tab's own state of the shared sticky bar button) is wired above, next to
    // the rest of the Edit Flow tab logic - currentFlowBlocks/flowLeadInBlock are already current
    // (this is the screen editing them directly), no need for goToFlowPlayView's own refetch.

    // --- Save (Edit mode only) - commits everything staged since loadAndRenderFlowDetailsHub's own
    // snapshot in one batch: Details (one PATCH), Media (diff recordings/documents against the
    // snapshot by id - delete what's gone, add what's new), then Blocks (diff the combined lead-in
    // + blocks list against the snapshot by id - delete/create/update, then one reorder call).
    // A diff-and-sync in one batch. Leaves the draft/Edit mode intact on
    // error so nothing already staged is lost - the user can retry Save or explicitly Cancel. ---
    // curRecordings/curDocuments are passed in rather than read fresh off currentFlowDetail here -
    // by the time this runs, currentFlowDetail has already been reassigned to the Details PATCH's
    // response (saveFlowEdit), which reflects the server's pre-save state and would silently drop
    // whatever was staged locally (bug: a YouTube link added in Edit mode, then Save, never
    // actually reached the server - saveFlowMediaEdits saw an empty list and had nothing to sync).
    async function saveFlowMediaEdits(curRecordings, curDocuments) {
        const snapRecordings = flowEditSnapshot.recordings;
        const snapDocuments = flowEditSnapshot.documents;

        const deletedRecordingIds = snapRecordings.filter(r => !curRecordings.some(cr => cr.id === r.id)).map(r => r.id);
        const deletedDocumentIds = snapDocuments.filter(d => !curDocuments.some(cd => cd.id === d.id)).map(d => d.id);
        await Promise.all([
            ...deletedRecordingIds.map(id => API.flows.recordings.delete(currentFlowId, id)),
            ...deletedDocumentIds.map(id => API.flows.documents.delete(currentFlowId, id))
        ]);

        const newRecordings = curRecordings.filter(r => typeof r.id === 'string');
        const newDocuments = curDocuments.filter(d => typeof d.id === 'string');
        const known = new Set(curRecordings.filter(r => typeof r.id !== 'string').map(r => String(r.id)));
        for (const r of newRecordings) {
            const clip = { clipStartMs: r.clipStartMs || null, clipEndMs: r.clipEndMs || null, movementNumber: r.movementNumber || null }; // ML-312, ML-531
            const detail = r.type === 'youtube'
                ? await API.flows.recordings.addYouTube(currentFlowId, { url: r.sourceUrl, title: r.title, ...clip })
                : await API.flows.recordings.addUploaded(currentFlowId, { blobUrl: r.blobUrl, blobPathname: r.blobPathname, fileName: r.fileName, fileSizeBytes: r.fileSizeBytes, mimeType: r.mimeType, ...clip });
            // ML-597: which one it became, so marks made on it before Save can follow it (saveFlowMarkEdits)
            const made = (detail && detail.recordings || []).find(x => !known.has(String(x.id)));
            if (made) { r.savedId = made.id; known.add(String(made.id)); }
        }
        // ML-312: a start and end changed on a recording that was already there
        // ML-531: the movement changed on a recording that was already there (its marks go)
        for (const r of curRecordings.filter(cr => typeof cr.id !== 'string')) {
            const before = snapRecordings.find(sr => sr.id === r.id);
            if (before && (before.movementNumber || null) !== (r.movementNumber || null)) await API.flows.recordings.setMovement(currentFlowId, r.id, r.movementNumber || null);
        }
        for (const r of curRecordings.filter(cr => typeof cr.id !== 'string')) {
            const before = snapRecordings.find(sr => sr.id === r.id);
            if (!before || ((before.clipStartMs || null) === (r.clipStartMs || null) && (before.clipEndMs || null) === (r.clipEndMs || null))) continue;
            await API.flows.recordings.setClip(currentFlowId, r.id, { startMs: r.clipStartMs || null, endMs: r.clipEndMs || null });
        }
        for (const d of newDocuments) {
            await API.flows.documents.add(currentFlowId, { blobUrl: d.blobUrl, blobPathname: d.blobPathname, fileName: d.fileName, fileSizeBytes: d.fileSizeBytes, mimeType: d.mimeType });
        }
    }

    // ML-597: bar marks made in Edit are kept until Save - and saved after the bars, which the server checks them
    // against. A recording added in this edit has its new id by now (saveFlowMediaEdits).
    async function saveFlowMarkEdits(curRecordings) {
        const same = (a, b) => JSON.stringify((a || []).map(m => [m.place, m.number, m.pass, m.atMs])) === JSON.stringify((b || []).map(m => [m.place, m.number, m.pass, m.atMs]));
        for (const r of curRecordings) {
            const id = typeof r.id === 'string' ? r.savedId : r.id;
            if (!id) continue;
            const before = flowEditSnapshot.recordings.find(sr => sr.id === r.id);
            if (typeof r.id === 'string' ? !(r.marks || []).length : (before && same(before.marks, r.marks))) continue;
            // only the marks that still fit the bars as saved - a bar changed after marking leaves its mark behind
            const marks = FlowJourney.usableMarks(FlowJourney.journeyPlaces(currentFlowBlocks, recOpts(r)), r.marks || []);
            await API.flows.recordings.setMarks(currentFlowId, id, { marks });
        }
    }

    async function saveFlowBlockEdits() {
        const snapshotAll = flowEditSnapshot.leadIn ? [flowEditSnapshot.leadIn, ...flowEditSnapshot.blocks] : flowEditSnapshot.blocks;
        const currentAll = flowLeadInBlock ? [flowLeadInBlock, ...currentFlowBlocks] : currentFlowBlocks;
        const currentRealIds = new Set(currentAll.filter(b => typeof b.id !== 'string').map(b => b.id));
        const deletedIds = snapshotAll.filter(b => !currentRealIds.has(b.id)).map(b => b.id);
        if (deletedIds.length) await Promise.all(deletedIds.map(id => API.flows.blocks.delete(id)));

        // Sequential, not Promise.all - lead-in first, then in display order, so the reorder call
        // right after has every real id to work with.
        for (const b of currentAll) {
            if (typeof b.id === 'string') {
                const created = await API.flows.blocks.create(currentFlowId, flowBlockPayload(b));
                b.id = created.id;
            }
        }

        // Every surviving/created entry, unconditionally - harmless no-op if a given block actually
        // didn't change.
        await Promise.all(currentAll.map(b => API.flows.blocks.update(b.id, flowBlockPayload(b))));

        if (currentFlowBlocks.length) await API.flows.blocks.reorder(currentFlowId, currentFlowBlocks.map(b => b.id));
    }

    async function saveFlowEdit() {
        if (!currentFlowId || !flowEditSnapshot) return;
        const nameEl = document.getElementById('flowTitleInput');
        if (!nameEl?.value.trim()) {
            showWarningToast('Flow name is required.');
            setFlowEditTab('details');
            nameEl?.focus();
            return;
        }
        const btn = document.getElementById('flowEditSaveBtn');
        if (btn) { btn.disabled = true; btn.innerText = 'Saving...'; }
        // Captured before the Details PATCH below reassigns currentFlowDetail - see
        // saveFlowMediaEdits's own comment on why reading them fresh off currentFlowDetail there
        // would silently miss whatever's staged.
        const stagedRecordings = currentFlowDetail.recordings || [];
        const stagedDocuments = currentFlowDetail.documents || [];
        const stagedSpeedsBeforeMatch = currentFlowDetail.speedsBeforeMatch ?? null; // ML-597
        try {
            currentFlowDetail = await API.flows.update(currentFlowId, {
                title: nameEl.value.trim(),
                composer: document.getElementById('flowComposerInput').value,
                arranger: document.getElementById('flowArrangerInput').value,
                publisher: document.getElementById('flowPublisherInput').value,
                description: document.getElementById('flowDescriptionInput').value,
                speedsBeforeMatch: stagedSpeedsBeforeMatch
            });
            await saveFlowMediaEdits(stagedRecordings, stagedDocuments);
            await saveFlowBlockEdits();
            await saveFlowMarkEdits(stagedRecordings); // ML-597: after the bars, which the marks are checked against
            // Refreshed once more at the end - the Details PATCH's own response (above) predates
            // the media/block syncing that just happened, so it's stale by now (missing real ids
            // for anything just created). Whatever view goBack() lands on next (e.g. Play Flow's
            // media carousel) reads currentFlowDetail/currentFlowBlocks directly, not a fetch of
            // its own, so this has to be the true final state.
            const [freshDetail, freshBlocks] = await Promise.all([API.flows.get(currentFlowId), API.flows.blocks.list(currentFlowId)]);
            currentFlowDetail = freshDetail;
            flowLeadInBlock = freshBlocks.find(b => b.isLeadIn) || null;
            currentFlowBlocks = freshBlocks.filter(b => !b.isLeadIn);
            flowEditSnapshot = null;
            showSuccessToast('Flow saved');
            // ML-199: an edit session has no "Play" to end on - Edit mode replaces the whole
            // Next-chain with Cancel/Save - so a successful Save is its completion. Cancel and the
            // back button fall through to switchView's abandoned hook, which is the right reading:
            // time was spent, nothing was kept. Finalised after the block sync above so the block
            // counts reported are the ones that actually landed.
            flowStatsFinish('completed');
            goBack();
        } catch (error) {
            showWarningToast('Error saving flow: ' + error.message);
        } finally {
            if (btn) { btn.disabled = false; btn.innerText = 'Save'; }
        }
    }
    document.getElementById('flowEditSaveBtn')?.addEventListener('click', () => flowReviewBeforeLeaving(saveFlowEdit, 'Save anyway'));

    // ========================================
    // ML-248: a final review of the bar settings when a Flow is finished (Save in Edit mode, Open
    // player in Create mode). FlowJourney.checkFlow lists what doesn't make sense together - errors
    // (it won't play as written) and warnings (something is ignored or never reached). With nothing
    // to report it carries straight on. Otherwise a review lists them, the bars involved are outlined
    // in the Bars tab (whichever layout), and the user chooses: go back and fix, or carry on anyway.
    // The outlines stay (updated live as things are fixed) for the rest of that editing session.
    // ========================================
    let flowCheckActive = false;
    let flowCheckContinue = null;
    function flowRunCheck() {
        return FlowJourney.checkFlow(currentFlowBlocks, { leadIn: flowLeadInBlock });
    }
    // Outlines every bar an issue mentions - called at the end of every Bars tab render.
    function flowRefreshIssueHighlights() {
        const flagged = new Set();
        if (flowCheckActive) flowRunCheck().forEach(i => i.blockIds.forEach(id => flagged.add(String(id))));
        document.querySelectorAll('#flowBlocksList [data-block-id]').forEach(el => {
            el.classList.toggle('flow-block-has-issue', flagged.has(el.dataset.blockId));
        });
    }
    function flowReviewBeforeLeaving(onContinue, continueLabel) {
        const issues = flowRunCheck();
        if (!issues.length) { onContinue(); return; }
        flowCheckActive = true;
        renderFlowBlocksList();
        flowShowCheckReview(issues, onContinue, continueLabel);
    }
    function flowShowCheckReview(issues, onContinue, continueLabel) {
        const errors = issues.filter(i => i.severity === 'error');
        const warnings = issues.filter(i => i.severity !== 'error');
        const item = (i) => `<li><button type="button" class="flow-check-item" data-check-block="${i.blockIds[0] ?? ''}">${escapeHtml(i.message)}</button></li>`;
        const group = (title, list) => (list.length ? `<h3 class="flow-check-group-title">${title}</h3><ul class="flow-check-list">${list.map(item).join('')}</ul>` : '');
        document.getElementById('flowCheckIntro').innerText = errors.length
            ? "Some bar settings don't fit together, so this Flow won't play the way it's written. The bars involved are outlined in red."
            : 'A few things are worth a look before you go on. The bars involved are outlined in red.';
        document.getElementById('flowCheckList').innerHTML = group("Won't play as written", errors) + group('Worth checking', warnings);
        document.getElementById('flowCheckContinueBtn').innerText = continueLabel;
        flowCheckContinue = onContinue;
        showModal('flowCheckModal');
    }
    function closeFlowCheckReview() {
        hideModal('flowCheckModal');
        flowCheckContinue = null;
    }
    // Go back and fix: the Bars tab, scrolled to the bar the item is about (or the first outlined one).
    function flowCheckGoToBlock(blockId) {
        closeFlowCheckReview();
        setFlowEditTab('blocks');
        const target = blockId ? document.querySelector(`#flowBlocksList [data-block-id="${blockId}"]`) : null;
        (target || document.querySelector('#flowBlocksList .flow-block-has-issue'))?.scrollIntoView({ block: 'center' });
    }
    document.getElementById('flowCheckFixBtn')?.addEventListener('click', () => flowCheckGoToBlock(''));
    document.getElementById('flowCheckCloseBtn')?.addEventListener('click', closeFlowCheckReview);
    document.getElementById('flowCheckContinueBtn')?.addEventListener('click', () => {
        const go = flowCheckContinue;
        closeFlowCheckReview();
        if (go) go();
    });
    document.getElementById('flowCheckList')?.addEventListener('click', (e) => {
        const btn = e.target.closest('[data-check-block]');
        if (btn) flowCheckGoToBlock(btn.dataset.checkBlock);
    });

    // ========================================
    // PLAY FLOW (Jira ML-179 follow-up, rebuilt on the journey engine for ML-193) - the playback
    // screen. Reuses the same now-playing dot display/transport as Quick Play/Metronome Blocks (own
    // player instance, own element ids), with sub-beats/speed%/volume.
    //
    // What plays, in what order and at what tempo, comes from public/flowJourney.js: the Flow is
    // turned into a journey (lead-in, intro, every bar with its repeat pass, jumps) and merged into
    // passages - runs of bars the metronome plays in one go. The player runs in sequence mode
    // (createMetronomePlayer): its scheduler asks for the next passage exactly when the current one
    // ends, and tags every click with its passage and position, so this screen reads where it is from
    // each click rather than counting (ML-254). Reaching the end of the piece stops and resets to the
    // start (ML-250). Repeats, alternate endings, intro, jumps, Fine, ramps and caesuras all play
    // (ML-249..253).
    // ========================================
    const flowPlayer = createMetronomePlayer();
    flowPlayerRef = flowPlayer;
    flowPlayer.setVisualLatencyMs(metroState.latencyMs);
    let flowJourney = { steps: [], end: 'end' };
    // Passages: { kind: 'leadIn'|'intro'|'main'|'rest', blockIndex, blockId, block, fromBar, toBar, pass, via,
    // loopPass, restIndex } - 'rest', loopPass and restIndex only while repeating bars (ML-302).
    let flowPlayQueue = [];
    let flowPlayIndex = 0;      // the passage on screen: the last click heard, or where Reset/a tap put it
    let flowSchedIndex = 0;     // the passage the scheduler is on - can be a click ahead of the screen
    let flowPosClick = -1;      // the last click heard within flowPlayIndex's passage (-1: none yet)
    let flowCurrentBpm = null;  // the tempo of the last click heard (ramps change it beat by beat)
    let flowRepeatedBlockIds = new Set(); // blocks the journey plays more than once - their label shows "1st time"/"2nd time"

    // Sub-beats mode is a playback-only overlay, same idea as Quick Play's own qpSubBeatsMode/
    // qpSubdivideOverride - one setting applies across the whole sequence, not stored per block. The
    // lead-in never subdivides.
    let flowSubBeatsMode = 'off';
    let flowSubdivideOverride = null;
    // ML-317: a Levels practice (set by startLevelPractice, cleared by endLevelPractice) - the Level
    // sets the loop, the speed and the sub-beats, and the player's own settings come back afterwards.
    var flowSession = null; // var: switchView checks it before this line has run
    function flowShouldSubdivide(block) {
        const info = metroBlkMeterInfo(block);
        if (!info) return false; // lead-in
        // In a practice session, sub-beats come on by themselves when the bar's beat is slow at this speed.
        if (flowSubBeatsMode === 'session') return FlowJourney.sessionSubBeats(block.bpm, flowSpeedPercent, flowSession ? flowSession.subBeatsBelow : null);
        return flowSubBeatsMode !== 'off';
    }
    function flowSubFactorFor(block) {
        if (!block || block.isLeadIn || !flowShouldSubdivide(block)) return 1;
        if (flowSubBeatsMode === 'fixed' && flowSubdivideOverride) return flowSubdivideOverride;
        return metroBlkMeterInfo(block).subdivisionFactor;
    }

    // The block a passage plays as - a lead-in borrows the first regular block's metre and tempo; a
    // rest bar (ML-302) is its loop's start bar.
    function flowPassageBlock(p) {
        if (!p) return null;
        return p.kind === 'leadIn' ? metroBlkEffectiveBlock(p.block, [p.block, ...currentFlowBlocks]) : p.block;
    }
    // Lead-in and rest bars never subdivide.
    function flowPassageSubFactor(p, b) {
        return p.kind === 'leadIn' || p.kind === 'rest' ? 1 : flowSubFactorFor(b);
    }
    function flowClicksPerBar(p) {
        const b = flowPassageBlock(p);
        if (p.kind === 'leadIn') return b.numerator;
        return metroBlkBeatsPerBarFor(b) * flowPassageSubFactor(p, b);
    }
    // The player settings for passage `index`, optionally starting part-way in (from bar
    // `startBarInPassage`, used when sub-beats change mid-play).
    function flowPassageConfig(index, startBarInPassage = 0) {
        const p = flowPlayQueue[index];
        const b = flowPassageBlock(p);
        const sub = flowPassageSubFactor(p, b);
        const cpb = flowClicksPerBar(p);
        const bars = p.toBar - p.fromBar + 1;
        const startClick = startBarInPassage * cpb;
        const boundaryClicks = bars * cpb;
        const fermatas = [];
        const gaps = new Map();
        if (p.kind !== 'leadIn' && p.kind !== 'rest') {
            for (let bar = p.fromBar; bar <= p.toBar; bar++) {
                const base = (bar - p.fromBar) * cpb;
                FlowJourney.pausesInBar(p.block, bar, cpb).forEach(pause => {
                    if (pause.kind === 'fermata') {
                        fermatas.push({ triggerClick: base + pause.click, holdBeats: pause.holdBeats, holdClicks: pause.holdBeats * sub });
                    } else {
                        // A caesura's silence comes after the last click of its written beat.
                        const f = p.block.fermatas.find(x => x.kind === 'caesura' && (x.barOffset || 0) === bar && FlowJourney.writtenBeatToClick(p.block, x.beatOffset, cpb) === pause.click);
                        // ML-365: "after beat" means after one of the bar's pause steps - a whole written beat, or
                        // one beat note when it's shorter (2/2 counted in crotchets: after that crotchet).
                        const w = FlowJourney.writtenBeatsPerBar(p.block);
                        const next = f ? f.beatOffset + 1 / FlowJourney.pauseStepsPerBeat(p.block) : null;
                        const lastClick = f && next < w + 1 ? FlowJourney.writtenBeatToClick(p.block, next, cpb) - 1 : cpb - 1;
                        gaps.set(base + Math.max(pause.click, lastClick), pause.holdBeats);
                    }
                });
            }
        }
        // A rest bar holds the tempo its loop starts at.
        const restBpm = p.kind === 'rest' ? FlowJourney.tempoAt(currentFlowBlocks, p.blockIndex, p.fromBar * FlowJourney.writtenBeatsPerBar(p.block)) : null;
        const tempoAt = p.kind === 'leadIn' ? () => b.bpm
            : p.kind === 'rest' ? () => restBpm
            : (idx) => FlowJourney.tempoAt(currentFlowBlocks, p.blockIndex, (p.fromBar + idx / cpb) * FlowJourney.writtenBeatsPerBar(p.block));
        return {
            bpm: tempoAt(startClick),
            beatsPerBar: p.kind === 'leadIn' ? b.numerator : metroBlkBeatsPerBarFor(b),
            notesPerBeat: sub,
            lowPitch: p.kind === 'leadIn' || p.kind === 'rest',
            startClick, boundaryClicks, fermatas,
            fermataMode: fermataPlaybackModeSetting(),
            gapAfter: (idx) => gaps.get(idx) || 0,
            tempoAt,
            tag: index
        };
    }
    function flowNextPassageConfig() {
        flowSchedIndex++;
        // ML-302: repeating bars never runs out - the next pass (rest bars, then the loop) is added as
        // the scheduler reaches the end of this one.
        if (flowSchedIndex >= flowPlayQueue.length && flowLoopPlan) flowAppendLoopPass();
        return flowSchedIndex < flowPlayQueue.length ? flowPassageConfig(flowSchedIndex) : null;
    }
    // Puts both the scheduler and the screen at passage `index` (bar `startBarInPassage` of it).
    function flowStartSequenceAt(index, startBarInPassage = 0) {
        if (!flowPlayQueue.length) return;
        flowPlayIndex = flowSchedIndex = index;
        const cfg = flowPassageConfig(index, startBarInPassage);
        flowPosClick = cfg.startClick - 1;
        flowCurrentBpm = cfg.bpm;
        flowPlayer.setSequence(cfg, flowNextPassageConfig);
    }
    function jumpFlowToStart() {
        flowResetPlayQueue();
        flowStartSequenceAt(0);
    }

    // currentFlowBlocks/flowLeadInBlock are the same arrays Blocks Studio edits directly - rebuilt
    // fresh every time this view is entered (see the switchView case) rather than cached, so an
    // edit made there is never stale here.
    function buildFlowPlayQueue() {
        flowLoadMovementForPiece(); // ML-530: the whole piece, or the movement chosen for it
        flowJourney = FlowJourney.movementJourney(currentFlowBlocks, { leadIn: flowLeadInBlock }, flowMovementNow());
        renderFlowMovementButton();
        flowLoadLoopForPiece();
        const seen = new Map();
        flowJourney.steps.forEach(s => { if (s.kind === 'main' && s.pass > 1) seen.set(s.blockId, true); });
        flowRepeatedBlockIds = new Set(seen.keys());
        if (flowPlayer.isPlaying()) { flowPlayer.pause(); updateFlowPlayIcon(); } // ML-563
        jumpFlowToStart();
    }

    // Tapping a tile jumps playback to that bar's first appearance in the piece proper (not the intro).
    // While repeating bars (ML-302) it jumps within the current pass, and only to a bar in the loop.
    window.jumpFlowToPlayIndex = function(id) {
        if (recJumpToBlock(id)) return; // ML-488: a recording's slide is showing - the tap starts it at that bar
        if (flowLoopPlan) {
            const pass = flowPlayQueue[flowPlayIndex] ? flowPlayQueue[flowPlayIndex].loopPass : 1;
            const index = flowPlayQueue.findIndex(p => p.loopPass === pass && p.blockId === id && p.kind !== 'rest');
            if (index === -1) {
                showWarningToast(`${flowLoopRangeText()} are repeating - turn repeat off to play from there.`);
                return;
            }
            flowStartSequenceAt(index);
            renderFlowPlaybackRow();
            return;
        }
        let index = flowPlayQueue.findIndex(p => p.blockId === id && p.kind === 'main');
        if (index === -1) index = flowPlayQueue.findIndex(p => p.blockId === id);
        if (index === -1) {
            const m = flowChosenMovement();
            if (m) showWarningToast(`${FlowJourney.movementLabel(m, false)} is chosen - choose the whole piece to play from there.`);
            return;
        }
        flowStartSequenceAt(index);
        renderFlowPlaybackRow();
    };

    // Where the screen is: passage, 0-based bar within its block, and click within that bar.
    function flowScreenPosition() {
        const p = flowPlayQueue[flowPlayIndex];
        if (!p) return null;
        const cpb = flowClicksPerBar(p);
        const click = Math.max(0, flowPosClick);
        const barInPassage = p.kind === 'leadIn' || p.kind === 'rest' ? 0 : Math.floor(click / cpb);
        return { p, cpb, bar: p.fromBar + barInPassage, clickInBar: click % cpb };
    }

    const FLOW_ORDINALS = ['1st', '2nd', '3rd'];
    // The piece's own number (1-based) of a block's first bar - what its tile shows when it has no mark.
    function flowBlockStartBar(blockId) {
        let startBar = 1;
        for (const s of currentFlowBlocks) {
            if (s.id === blockId) return startBar;
            startBar += s.barCount || 0;
        }
        return null;
    }
    // "Intro · Bar 11 · [A] · 2nd time · 3/4 · 96 bpm · 𝄐" - HTML (the mark is boxed as on its tile; the
    // fermata suffix is a glyph). The bar is the piece's own bar number, then which block it is in: its
    // rehearsal mark, or "bars 33 to 40" when it has none (the owner, 12 Oct 2026).
    function flowNowPlayingLabel() {
        const pos = flowScreenPosition();
        if (!pos) return '';
        const { p } = pos;
        const block = flowPassageBlock(p);
        const bpm = Math.round(flowCurrentBpm ?? block.bpm);
        const timeSig = escapeHtml(block.timeSignatureLabel || `${block.numerator}/${block.denominator}`); // HTML, so escaped like every other label
        // ML-302: "Repeat 3 · ..." while repeating; rest bars count in before the first pass.
        const loopPrefix = flowLoopPlan ? `Repeat ${p.loopPass} · ` : '';
        if (p.kind === 'rest') {
            // The first pass's clicking bars are the count-in (in a practice or run-through, the number you chose);
            // ML-587: every pass's, when the count-in comes every time round
            const first = p.loopPass === 1 || !flowLoopPlan || flowCountInEveryGo();
            const restBars = first && flowSession ? practiceCountInBars() : flowLoop ? flowLoop.restBars : 1;
            return `${loopPrefix}${first ? 'Count-in' : 'Rest'} ${p.restIndex + 1} of ${restBars} · ${timeSig} · ${bpm} bpm`;
        }
        if (p.kind === 'leadIn') {
            return `${loopPrefix}Lead-in · ${escapeHtml(block.timeSignatureLabel)} · ${bpm} bpm`;
        }
        const parts = [];
        if (flowLoopPlan) parts.push(`Repeat ${p.loopPass}`);
        if (p.kind === 'intro') parts.push('Intro');
        const startBar = flowBlockStartBar(p.blockId);
        // ML-529: in a piece in movements, which movement this is ("Mvt 2 · Bar 93 · A")
        if (startBar !== null && FlowJourney.movements(currentFlowBlocks).length > 1) parts.push(FlowJourney.movementLabel(FlowJourney.movementOfBar(currentFlowBlocks, startBar), false));
        if (startBar === null) parts.push(`${pos.bar + 1} of ${block.barCount} bar${block.barCount === 1 ? '' : 's'}`);
        else parts.push(`Bar ${startBar + pos.bar}`);
        if (block.rehearsalMark) parts.push(`<span class="flow-bar-detail-mark">${escapeHtml(block.rehearsalMark)}</span>`);
        else if (startBar !== null && block.barCount > 1) parts.push(`bars ${startBar} to ${startBar + block.barCount - 1}`);
        if (p.kind === 'main' && flowRepeatedBlockIds.has(p.blockId)) parts.push(`${FLOW_ORDINALS[p.pass - 1] || `${p.pass}th`} time`);
        parts.push(timeSig, `${bpm} bpm`);
        return parts.join(' · ') + metroBlkFermataLabelSuffix(block);
    }

    function onFlowBeat(beatInfo) {
        // ML-390: a Prepare run-through that has reached the end goes on to painting the bars.
        if (beatInfo.ended && flowSession && flowSession.mode === 'runthrough') { flowPlayer.stop(); updateFlowPlayIcon(); jumpFlowToStart(); runThroughDone(); return; }
        if (beatInfo.ended) window.Usage?.finish('rehearse'); // ML-22: played to the end
        if (beatInfo.ended) {
            // ML-250: the end of the piece - stop and go back to the start, ready to play again.
            flowPlayer.stop();
            jumpFlowToStart();
            updateFlowPlayIcon();
            renderFlowPlaybackRow();
            return;
        }
        // ML-541: the block's time ran out during a go - the next go's gap bar has begun, so that go is finished
        const finishing = practiceRun && practiceRun.finishingGo;
        if (finishing && finishing.kind === 'flow' && flowPlayQueue[beatInfo.tag] && flowPlayQueue[beatInfo.tag].loopPass > finishing.pass) { sessionGoFinished(); return; }
        const passageChanged = beatInfo.tag !== flowPlayIndex;
        const isFermataRepeat = !!(beatInfo.fermataHold && !beatInfo.fermataHold.isFirst);
        const prevBar = flowScreenPosition()?.bar;
        flowPlayIndex = beatInfo.tag;
        flowPosClick = beatInfo.clickIndex;
        flowCurrentBpm = beatInfo.bpm;
        const pos = flowScreenPosition();
        if (!pos) return;
        const block = flowPassageBlock(pos.p);
        const subFactor = flowPassageSubFactor(pos.p, block);
        // ML-542: the count-in (the rest bars before the first go - not the gap bars between goes) counts down big.
        // ML-587: in a practice with the count-in every time round, the bars between goes are a count-in too.
        const cp = pos.p;
        if (cp.kind === 'rest' && (cp.loopPass === 1 || !flowLoopPlan || flowCountInEveryGo())) {
            if (beatInfo.isConductorBeat) {
                const bpb = beatInfo.conductorBeatsPerBar;
                const total = flowPlayQueue.filter(q => q.kind === 'rest' && q.loopPass === cp.loopPass).length * bpb;
                showCountIn('flowCountIn', total - (cp.restIndex * bpb + beatInfo.conductorBeatIndex), total);
            }
        } else showCountIn('flowCountIn', 0);

        // A new passage (a new block, a repeat, a jump) redraws the whole row; a new bar within the same
        // passage only refreshes its label and fermata/caesura glyphs - at the new bar's first click,
        // not at the start of the previous bar's last beat (ML-254).
        if (passageChanged) renderFlowPlaybackRow();
        else if (!isFermataRepeat && pos.bar !== prevBar && pos.p.kind !== 'rest') {
            renderFermataMarkers('flowPlayRowDots', block, pos.bar, subFactor);
        }
        const labelEl = document.getElementById('flowPlayRowLabel');
        if (labelEl && beatInfo.isConductorBeat) labelEl.innerHTML = flowNowPlayingLabel();

        flashTierDot('flowPlayRowDots', beatInfo.clickIndexInBar);
        updateFermataDotState('flowPlayRowDots', beatInfo);
        if (isFermataRepeat) return;

        if (beatInfo.isConductorBeat) {
            const totalBaseClicks = beatInfo.conductorBeatsPerBar * subFactor;
            const nextIndex = (beatInfo.conductorBeatIndex + 1) % beatInfo.conductorBeatsPerBar;
            const trackUnit = 100 / (totalBaseClicks + 1);
            const trackLeftPct = (k) => k * trackUnit + trackUnit / 2;
            metroScrollFollow('flowPlayRowViewport', 'flowPlayRowContent', trackLeftPct(beatInfo.conductorBeatIndex * subFactor), trackLeftPct(nextIndex * subFactor), beatInfo.secondsPerConductorBeat);
        }
    }
    flowPlayer.onBeat(onFlowBeat);

    // ========================================
    // ML-166: swipeable media carousel (Metronome + one slide per attached audio track/video
    // link). Slide 0 is always the metronome (the view's own always-present markup, app.html) -
    // audio/video slides are built fresh from currentFlowDetail.recordings every time Play Flow
    // loads (buildFlowMediaSlides, called from switchView's flowPlayView case, same "don't trust
    // it's stale" reasoning as buildFlowPlayQueue). Dots + swipe chrome only ever render when
    // there's more than the one metronome slide (renderFlowMediaDots) - a media-less flow looks
    // exactly like it always has.
    // ========================================
    let flowMediaSlides = [{ type: 'metronome' }];
    let flowMediaActiveIndex = 0;
    let flowYtPlayers = {}; // recording id -> YT.Player, video slides only
    let flowYtApiPromise = null;

    // Same path data as the Home screen's own "Metronome" tool icon (public/icons/quick-play.svg) -
    // used instead of a generic Material Symbol wherever this carousel represents the metronome
    // slide (the dots row, and the decorative wrap-around preview below).
    const FLOW_METRONOME_ICON_SVG = '<svg viewBox="0 0 883 1025" preserveAspectRatio="xMidYMid meet" aria-hidden="true" fill="currentColor"><g transform="translate(-2956 -1363)"><path d="M3299.02 1831.86 3528.57 1965.12 3299.02 2098.38ZM3329.89 1454.01 3064.12 2264.42 3731.24 2264.42 3465.47 1454.01ZM3297.05 1363 3499.94 1363C3518.77 1363 3534.93 1374.46 3541.83 1390.79L3544.05 1401.79 3839 2301.17 3837.74 2301.58 3839 2309.93C3839 2328.77 3827.55 2344.95 3811.23 2351.86L3795.05 2355.12 3795.05 2355.43 3793.53 2355.43 3793.53 2355.43 3793.53 2355.43 3702.53 2355.43 3701.57 2360.21C3694.67 2376.54 3678.51 2388 3659.68 2388 3640.84 2388 3624.68 2376.54 3617.78 2360.21L3616.82 2355.43 3186.33 2355.43 3185.37 2360.21C3178.47 2376.54 3162.31 2388 3143.47 2388 3124.64 2388 3108.48 2376.54 3101.58 2360.21L3100.62 2355.43 3008.1 2355.43 3008.1 2354.09 3001.47 2355.43C2976.36 2355.43 2956 2335.06 2956 2309.93L2957.68 2301.6 2956.37 2301.17 3254.77 1391.26 3255.04 1391.35 3255.16 1390.79C3262.06 1374.46 3278.22 1363 3297.05 1363Z" fill-rule="evenodd"/></g></svg>';

    function buildFlowMediaSlides() {
        Object.values(flowYtPlayers).forEach(player => { try { player.destroy(); } catch (error) { /* already gone */ } });
        flowYtPlayers = {};
        // ML-531: with one movement chosen, a recording of another movement isn't offered (one of the whole piece is)
        const only = flowChosenMovement();
        const recordings = (currentFlowDetail?.recordings || []).filter(r => !only || !recMovement(r) || r.movementNumber === only.number);
        const audioTracks = recordings.filter(r => r.type !== 'youtube');
        const videoLinks = recordings.filter(r => r.type === 'youtube');
        flowMediaSlides = [
            { type: 'metronome' },
            ...audioTracks.map(r => ({ type: 'audio', data: r })),
            ...videoLinks.map(r => ({ type: 'video', data: r }))
        ];
        flowMediaActiveIndex = 0;
        recTileBlockId = null; // ML-488: a new piece, or the play screen opened again - no recording has been played yet
    }

    function flowMediaSlideKey(slide) {
        return slide.type === 'metronome' ? 'metronome' : `${slide.type}-${slide.data.id}`;
    }

    // Loads the YouTube IFrame API script exactly once, only when a flow actually has a video
    // attached - most flows don't, no reason to pull in third-party JS for them. Chains onto
    // whatever onYouTubeIframeAPIReady already exists (there isn't one elsewhere in this app
    // today, but this is the polite way to add a global callback regardless).
    function ensureFlowYtApi() {
        if (flowYtApiPromise) return flowYtApiPromise;
        flowYtApiPromise = new Promise((resolve) => {
            if (window.YT && window.YT.Player) { resolve(window.YT); return; }
            const prevCallback = window.onYouTubeIframeAPIReady;
            window.onYouTubeIframeAPIReady = () => {
                if (typeof prevCallback === 'function') prevCallback();
                resolve(window.YT);
            };
            if (!document.getElementById('youtubeIframeApiScript')) {
                const script = document.createElement('script');
                script.id = 'youtubeIframeApiScript';
                script.src = 'https://www.youtube.com/iframe_api';
                document.head.appendChild(script);
            }
        });
        return flowYtApiPromise;
    }

    function flowMediaSlideHtml(slide) {
        if (slide.type === 'audio') {
            const r = slide.data;
            return `
                <div class="flow-media-slide" data-slide-key="${flowMediaSlideKey(slide)}">
                    ${recCountInCoverHtml(slide)}
                    <div class="metroBlk-row">
                        <div class="flow-media-slide-header">
                            <span class="flow-media-icon type-audio"><span class="material-symbols-outlined icon-md">music_note</span></span>
                            <div><strong>${escapeHtml(r.title)}</strong><span>${escapeHtml(recMovement(r) ? FlowJourney.movementLabel(recMovement(r), true) : (r.mimeType || 'Audio file'))}</span></div>
                        </div>
                        <audio class="flow-media-player-audio" controls preload="metadata" src="${escapeHtml(r.blobUrl)}" data-flow-media-key="${flowMediaSlideKey(slide)}"></audio>
                        ${recScoreControlsHtml(slide)}
                    </div>
                </div>
            `;
        }
        if (slide.type === 'video') {
            const r = slide.data;
            const origin = encodeURIComponent(location.origin);
            return `
                <div class="flow-media-slide" data-slide-key="${flowMediaSlideKey(slide)}">
                    ${recCountInCoverHtml(slide)}
                    <div class="metroBlk-row">
                        <!-- No icon, title or "YouTube video" line above it (the owner, 12 Oct 2026): the video shows its own title, and the room is for the bars -->
                        <div class="flow-media-player-video"><iframe id="flowYtFrame-${r.id}" src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(r.youtubeVideoId)}?enablejsapi=1&amp;origin=${origin}${youTubeClipQuery(recordingClip(r), "&amp;")}" title="${escapeHtml(r.title)}" allow="accelerometer; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></div>
                        ${recScoreControlsHtml(slide)}
                    </div>
                </div>
            `;
        }
        return '';
    }

    // Non-interactive stand-in for a slide (header only - icon/title/subtitle, no player) used to
    // pad either end of the track so wrap-around swiping has something to animate into. Deliberately
    // not a clone of the real slide's DOM: the real metronome slide's transport controls and a real
    // video slide's YT iframe both rely on singular ids (flowPlayBtn, flowYtFrame-<id>, ...) that a
    // true clone would duplicate. These previews are only ever on screen for the tail end of a single
    // swipe gesture before goToFlowMediaSlide snaps the track back onto the real slide in its place.
    function flowMediaSlidePreviewHtml(slide) {
        let iconHtml, title, subtitle;
        if (slide.type === 'metronome') {
            iconHtml = `<span class="flow-media-icon type-metronome">${FLOW_METRONOME_ICON_SVG}</span>`;
            title = 'Metronome';
            subtitle = '';
        } else {
            const r = slide.data;
            iconHtml = slide.type === 'audio'
                ? '<span class="flow-media-icon type-audio"><span class="material-symbols-outlined icon-md">music_note</span></span>'
                : '<span class="flow-media-icon type-youtube"><span class="material-symbols-outlined icon-md">smart_display</span></span>';
            title = r.title;
            subtitle = slide.type === 'audio' ? (recMovement(r) ? FlowJourney.movementLabel(recMovement(r), true) : (r.mimeType || 'Audio file')) : 'YouTube video'; // ML-531
        }
        return `
            <div class="flow-media-slide flow-media-slide-preview" data-clone="true" aria-hidden="true">
                <div class="metroBlk-row">
                    <div class="flow-media-slide-header">
                        ${iconHtml}
                        <div><strong>${escapeHtml(title)}</strong>${subtitle ? `<span>${escapeHtml(subtitle)}</span>` : ''}</div>
                    </div>
                </div>
            </div>
        `;
    }

    // "Exclusive Playback" (ticket's own term) - called whenever any one source starts, whether
    // that's the metronome's own Play button, an <audio> element's native play event, or a
    // YT.Player moving into the PLAYING state. sourceKey is 'metronome', or flowMediaSlideKey's
    // own 'audio-<id>'/'video-<id>' shape for whichever one just started.
    function stopAllFlowMediaExcept(sourceKey) {
        if (sourceKey !== 'metronome' && flowPlayer.isPlaying()) pauseFlow();
        document.querySelectorAll('#flowMediaTrack audio[data-flow-media-key]').forEach(el => {
            if (el.dataset.flowMediaKey !== sourceKey && !el.paused) el.pause();
        });
        Object.entries(flowYtPlayers).forEach(([id, player]) => {
            if (`video-${id}` === sourceKey || !player || typeof player.pauseVideo !== 'function') return;
            try {
                if (player.getPlayerState && player.getPlayerState() === window.YT.PlayerState.PLAYING) player.pauseVideo();
            } catch (error) { /* not ready yet - nothing playing to stop */ }
        });
    }

    // Pauses whatever's active on one specific slide - used both when swiping/tapping away from it
    // (the ticket's "swiping away... pause or mute the outgoing media") and when leaving Play Flow
    // entirely (see switchView's own flowPlayView leave-check, pauseAllFlowMedia below).
    function pauseFlowMediaSlide(slide) {
        if (!slide) return;
        if (slide.type !== 'metronome' && recCounting && recCounting.slideKey === flowMediaSlideKey(slide)) recCountInStop(); // ML-587
        if (slide.type === 'metronome') {
            if (flowPlayer.isPlaying()) pauseFlow();
        } else if (slide.type === 'audio') {
            const el = document.querySelector(`audio[data-flow-media-key="${flowMediaSlideKey(slide)}"]`);
            if (el && !el.paused) el.pause();
        } else if (slide.type === 'video') {
            const player = flowYtPlayers[slide.data.id];
            if (player && typeof player.pauseVideo === 'function') {
                try { player.pauseVideo(); } catch (error) { /* not ready yet */ }
            }
        }
    }
    function pauseAllFlowMedia() {
        flowMediaSlides.forEach(pauseFlowMediaSlide);
    }

    // ===== ML-488: the rehearsal score - a recording or video follows the piece's bars (step C) =====
    // On a recording's slide: repeat (the piece's own repeat-bars setting, the one the metronome uses),
    // play speed, and "bars" - the pop-up where whoever can change the piece marks where a few bars fall.
    // Where every bar is in the recording is FlowJourney.recordingMap: the marks, the recording's start
    // and end (ML-312), and the piece's own speeds and pauses. Nothing listens to the sound.
    // docs/rehearsal-score.md; specs/components/rehearsal-score.md.
    const recScoreOn = () => isFeatureEnabled('rehearsal_score');
    const REC_LOOP_LEAD_MS = 400;      // a repeat starts this much early, so a map a touch out still catches the first note
    let recTicker = null;
    let recTileBlockId = null;         // the block the recording is in now - its tile lights up, as the metronome's does
    const recDroppedTold = new Set();  // ML-531: recordings whose left-out marks have been mentioned this visit
    const recActiveSlide = () => { const s = flowMediaSlides[flowMediaActiveIndex]; return s && s.type !== 'metronome' ? s : null; };
    // ML-531: a recording of one movement is mapped onto that movement's bars - its start mark is the movement's first bar
    const recOpts = (r) => ({ leadIn: flowLeadInBlock, movement: r.movementNumber || null });
    const recMovement = (r) => (r.movementNumber ? FlowJourney.movements(currentFlowBlocks).find(m => m.number === r.movementNumber && FlowJourney.movements(currentFlowBlocks).length > 1) || null : null);
    const recMapFor = (r) => FlowJourney.recordingMap(currentFlowBlocks, recOpts(r), r.marks || [], recordingClip(r));
    // One way to drive either kind of player. null until the player is there (YouTube arrives late).
    function recPlayerOf(slide) {
        if (!slide) return null;
        if (slide.type === 'audio') {
            const el = document.querySelector(`#flowMediaTrack audio[data-flow-media-key="${flowMediaSlideKey(slide)}"]`);
            if (!el) return null;
            return {
                positionMs: () => el.currentTime * 1000, playing: () => !el.paused,
                seek: (ms) => { el.currentTime = ms / 1000; }, play: () => el.play().catch(() => { /* wants a tap on the player first */ }),
                setSpeed: (pct) => { el.playbackRate = pct / 100; }
            };
        }
        const yt = flowYtPlayers[slide.data.id];
        if (!yt || typeof yt.getCurrentTime !== 'function') return null;
        return {
            positionMs: () => yt.getCurrentTime() * 1000, playing: () => yt.getPlayerState() === window.YT.PlayerState.PLAYING,
            seek: (ms) => yt.seekTo(ms / 1000, true), play: () => yt.playVideo(),
            setSpeed: (pct) => yt.setPlaybackRate(pct / 100)
        };
    }
    // ML-596/599: a recording plays at the metronome's play speed (flowSpeedPercent) - one speed for the visit, as
    // repeat is one - from the one list of play speeds. An upload plays at any speed. A YouTube video only plays at its
    // own speeds (what it says it can - usually YT_RATES), so it offers the list's speeds it can play and plays the
    // nearest of them: 70% on the metronome is 75% on a video, and the metronome stays at 70%.
    const YT_RATES = [25, 50, 75, 100, 125, 150, 175, 200];
    function recSpeedsFor(slide) {
        const all = playSpeedChoices();
        if (!slide || slide.type === 'audio') return all;
        let rates = YT_RATES;
        try {
            const yt = flowYtPlayers[slide.data.id];
            const said = yt && typeof yt.getAvailablePlaybackRates === 'function' ? yt.getAvailablePlaybackRates() : null;
            if (said && said.length) rates = said.map(r => Math.round(r * 100));
        } catch (error) { /* not ready yet - YouTube's usual speeds */ }
        const playable = all.filter(p => rates.includes(p));
        return playable.length ? playable : [100];
    }
    function recSpeedOf(slide) {
        const speeds = recSpeedsFor(slide);
        return speeds.reduce((best, p) => (Math.abs(p - flowSpeedPercent) < Math.abs(best - flowSpeedPercent) ? p : best), speeds[0]);
    }
    // The showing recording takes the speed now, and every recording's box says what it plays at
    function recApplySpeed() {
        if (!recScoreOn()) return;
        const slide = recActiveSlide();
        const player = recPlayerOf(slide);
        if (player) { try { player.setSpeed(recSpeedOf(slide)); } catch (error) { /* not ready yet */ } }
        renderRecScoreControls();
    }
    function recScoreControlsHtml(slide) {
        if (!recScoreOn()) return '';
        const key = flowMediaSlideKey(slide);
        // ML-597: marking the bars (and matching the speeds) is on the piece's Edit -> Media tab only - set up there, not
        // changed while playing. ML-587: in a practice, a Play of its own - it counts you in (the practice's count-in),
        // then plays the bars being practised; the repeat is the practice's bars, shown but not changed here.
        // ML-598: under the boxes, how long the stretch it's in takes on the recording against the piece's speeds.
        return `
            <div class="metro-transport-grid" data-rec-controls="${key}">
                <button type="button" class="metroBlk-ctrl-value-btn" data-act="rec-loop" data-rec-loop-btn aria-haspopup="dialog"><strong data-rec-loop-lbl>off</strong><span class="metroBlk-ctrl-value-label">repeat</span></button>
                <button type="button" class="metro-play-grid-btn hidden-group" data-act="rec-play" data-rec-play-btn aria-label="Count in, then play"><span class="material-symbols-outlined" data-rec-play-icon>play_arrow</span><span class="metroBlk-ctrl-value-label">play</span></button>
                <button type="button" class="metroBlk-ctrl-value-btn" data-act="rec-speed" data-rec-speed-btn aria-haspopup="dialog"><strong data-rec-speed-lbl>100%</strong><span class="metroBlk-ctrl-value-label">play speed</span></button>
            </div>
            <p class="theory-best-line" data-rec-bar-line="${key}" role="status" aria-live="off"></p>
            <p class="text-sm text-muted" data-rec-stretch-line="${key}"></p>`;
    }
    // ML-598: the stretch the recording is in (the first, before it's played) - on the recording and at the piece's speeds
    function recStretchText(slide, atMs) {
        const r = slide.data;
        const stretches = FlowJourney.recordingStretches(currentFlowBlocks, recOpts(r), r.marks || [], recordingClip(r));
        if (!stretches.length) return '';
        const lines = recordingStretchLines(currentFlowBlocks, r, r.marks || [], recordingClip(r));
        if (atMs === null) return lines[0];
        const map = recMapFor(r);
        const place = map ? FlowJourney.placeAt(map, atMs) : -1;
        const k = stretches.findIndex(s => place >= s.fromPlace && place <= s.toPlace);
        return lines[k === -1 ? 0 : k];
    }
    // What the three boxes say on every recording slide - after the repeat, the speed or a map changes.
    function renderRecScoreControls() {
        if (!recScoreOn()) return;
        const loopOn = !!flowLoopPlan;
        document.querySelectorAll('#flowMediaTrack [data-rec-controls]').forEach((box) => {
            const slide = flowMediaSlides.find(s => s.type !== 'metronome' && flowMediaSlideKey(s) === box.dataset.recControls);
            if (!slide) return;
            const loopBtn = box.querySelector('[data-rec-loop-btn]');
            setLoopLabel(box.querySelector('[data-rec-loop-lbl]'), loopOn);
            loopBtn.classList.toggle('metroBlk-ctrl-value-btn-on', loopOn);
            // ML-587: in a practice the repeat is the practice's own bars - shown, not changed here (nor on the metronome)
            const practice = recInPractice();
            loopBtn.disabled = practice;
            loopBtn.setAttribute('aria-label', practice ? `Repeating the bars being practised - ${flowLoopRangeText()}` : loopOn ? `Repeat bars - ${flowLoopRangeText()}. Tap to change` : 'Repeat bars - off. Tap to set up');
            const playBtn = box.querySelector('[data-rec-play-btn]');
            if (playBtn) {
                setShown(playBtn, practice);
                let going = !!(recCounting && recCounting.slideKey === box.dataset.recControls);
                if (!going && slide === recActiveSlide()) { try { going = !!recPlayerOf(slide)?.playing(); } catch (error) { going = false; } }
                playBtn.querySelector('[data-rec-play-icon]').textContent = going ? 'pause' : 'play_arrow';
                playBtn.setAttribute('aria-label', going ? 'Pause' : practiceCountInWhen() === 'off' ? 'Play the bars being practised' : 'Count in, then play the bars being practised');
            }
            const speed = recSpeedOf(slide);
            box.querySelector('[data-rec-speed-lbl]').textContent = `${speed}%`;
            box.querySelector('[data-rec-speed-btn]').setAttribute('aria-label', `Play speed - ${speed}%. Tap to change`);
            // ML-531: the marks that still fit the piece - a change to its bars (or making it a piece in movements) can
            // leave some that don't; they are left out, and whoever can change the piece is told once
            const stored = (slide.data.marks || []).length;
            const usable = stored ? FlowJourney.usableMarks(FlowJourney.journeyPlaces(currentFlowBlocks, recOpts(slide.data)), slide.data.marks).length : 0;
            if (stored > usable && !recDroppedTold.has(slide.data.id) && currentFlowDetail && currentFlowDetail.canEdit) {
                recDroppedTold.add(slide.data.id);
                const k = stored - usable;
                showWarningToast(`${k} bar mark${k === 1 ? '' : 's'} on ${slide.data.title} no longer fit${k === 1 ? 's' : ''} the piece's bars and ${k === 1 ? 'is' : 'are'} left out. Mark ${k === 1 ? 'it' : 'them'} again on the piece's Media tab if you need to.`);
            }
            const stretchLine = document.querySelector(`#flowMediaTrack [data-rec-stretch-line="${box.dataset.recControls}"]`);
            if (stretchLine && !stretchLine.textContent) stretchLine.textContent = recStretchText(slide, null);
        });
    }
    // While a recording plays, a few times a second: keep it inside the bars being repeated, and say
    // which bar it is on. Stops itself when nothing is playing.
    function recTick() {
        const slide = recActiveSlide();
        const player = recPlayerOf(slide);
        if (!slide || !player) return;
        let playing = false;
        let at = 0;
        try { playing = player.playing(); at = player.positionMs(); } catch (error) { return; }
        const map = recMapFor(slide.data);
        if (map && playing && flowLoopPlan) {
            const loop = FlowJourney.mapLoop(map, flowLoop.startBar, flowLoop.endBar, REC_LOOP_LEAD_MS);
            if (loop.ok && at >= loop.endMs && flowCountInEveryGo()) {
                // ML-587: the count-in every time round - stop at the end of the go, count in, go again
                pauseFlowMediaSlide(slide);
                player.seek(loop.startMs);
                recCountInThen(slide, () => { try { player.seek(loop.startMs); player.play(); } catch (error) { /* not ready yet */ } recStartTicker(); renderRecScoreControls(); });
                renderRecScoreControls();
                return;
            }
            if (loop.ok && (at >= loop.endMs || at < loop.startMs - 300)) { player.seek(loop.startMs); at = loop.startMs; }
        }
        const line = document.querySelector(`#flowMediaTrack [data-rec-bar-line="${flowMediaSlideKey(slide)}"]`);
        if (map) {
            // The bar tile for where the recording is lights up - the same tile the metronome would light
            const k = FlowJourney.placeAt(map, at);
            const blockId = k === -1 ? null : map.places[k].blockId;
            if (blockId !== recTileBlockId) { recTileBlockId = blockId; renderFlowPlaybackTiles(); }
        }
        const stretchLine = document.querySelector(`#flowMediaTrack [data-rec-stretch-line="${flowMediaSlideKey(slide)}"]`);
        if (stretchLine && playing) { const t = recStretchText(slide, at); if (stretchLine.textContent !== t) stretchLine.textContent = t; } // ML-598
        if (line && map) {
            const place = FlowJourney.placeAt(map, at);
            const mv = recMovement(slide.data);
            const text = place === -1 ? '' : mv ? `${FlowJourney.placeLabel(map.places, place)} · ${FlowJourney.movementLabel(mv, false)}, bars ${mv.startBar}-${mv.endBar}` : `${FlowJourney.placeLabel(map.places, place)} of ${FlowJourney.totalBars(currentFlowBlocks)}`;
            if (line.textContent !== text) line.textContent = text;
        }
        if (playing !== recWasPlaying) { if (playing) window.Usage?.begin('recording'); else window.Usage?.end('recording'); } // ML-22: finished after 30 seconds
        if (playing !== recWasPlaying) { recWasPlaying = playing; if (recInPractice()) renderRecScoreControls(); } // ML-587: Play / Pause
        if (!playing && recTicker) { clearInterval(recTicker); recTicker = null; }
    }
    let recWasPlaying = false;
    function recStartTicker() {
        if (!recScoreOn()) return;
        const slide = recActiveSlide();
        const player = recPlayerOf(slide);
        if (player) { try { player.setSpeed(recSpeedOf(slide)); } catch (error) { /* not ready yet */ } }
        if (!recTicker) recTicker = setInterval(recTick, 100);
        recTick();
    }
    // Pressing Play with repeat on starts at the repeat, wherever the slider was.
    function recGoToLoopStart() {
        const slide = recActiveSlide();
        const player = recPlayerOf(slide);
        if (!slide || !player || !flowLoopPlan) return;
        const loop = FlowJourney.mapLoop(recMapFor(slide.data), flowLoop.startBar, flowLoop.endBar, REC_LOOP_LEAD_MS);
        if (loop.ok) { try { player.seek(loop.startMs); } catch (error) { /* not ready yet */ } }
    }
    // Tapping a bar tile while a recording's slide is showing starts the recording at that bar (the
    // first time the piece plays it). false = no recording showing, so the metronome takes the tap.
    function recJumpToBlock(blockId) {
        const slide = recActiveSlide();
        if (!recScoreOn() || !slide) return false;
        const player = recPlayerOf(slide);
        const map = recMapFor(slide.data);
        const place = map ? map.places.findIndex(p => p.blockId === blockId && p.kind === 'main') : -1;
        const mv = recMovement(slide.data);
        if (player && place === -1 && mv) { showWarningToast(`This recording is of ${FlowJourney.movementLabel(mv, true)} - tap a bar in it.`); return true; }
        if (!player || place === -1) return true; // a recording is showing: the tap is for it, even if it can't be used yet
        if (flowLoopPlan) {
            const loop = FlowJourney.mapLoop(map, flowLoop.startBar, flowLoop.endBar, 0);
            if (loop.ok && (place < loop.fromPlace || place > loop.toPlace)) { showWarningToast(`${flowLoopRangeText()} are repeating - turn repeat off to play from there.`); return true; }
        }
        try { player.seek(map.places[place].startMs); player.play(); } catch (error) { /* not ready yet */ }
        recStartTicker();
        return true;
    }
    // ===== ML-587: a practice's count-in before a recording or video =====
    // In a practice a recording's slide has a Play of its own: the practice's count-in (off / first time only / every
    // time round, and how many bars) clicks on the metronome's sound at the speed of the bar it starts on, at the play
    // speed, with the big count-down over the slide - then the recording plays from the bars being practised. With the
    // count-in every time round, the recording stops at the end of each go and counts in again.
    const recCountPlayer = createMetronomePlayer();
    recCountPlayer.setVisualLatencyMs(metroState.latencyMs);
    let recCounting = null; // { slideKey, totalClicks, then }
    const recCountInCoverHtml = (slide) => `<div class="count-in-cover hidden-group" id="recCountIn-${flowMediaSlideKey(slide)}" aria-hidden="true"><div class="rest-ring"><svg class="rest-ring-svg" viewBox="0 0 120 120"><circle class="rest-ring-track" cx="60" cy="60" r="52"></circle><circle class="rest-ring-left" cx="60" cy="60" r="52" pathLength="100"></circle></svg><div class="rest-ring-num"><strong>4</strong><span>get ready</span></div></div></div>`;
    const recInPractice = () => !!flowSession && flowSession.mode !== 'runthrough';
    // Where the practised bars start on the recording, and that bar's block
    function recPracticeStart(slide) {
        const map = recMapFor(slide.data);
        const loop = map && flowLoopPlan ? FlowJourney.mapLoop(map, flowLoop.startBar, flowLoop.endBar, REC_LOOP_LEAD_MS) : null;
        if (!loop || !loop.ok) return { startMs: null, block: currentFlowBlocks.find(b => b.barCount > 0) };
        return { startMs: loop.startMs, block: currentFlowBlocks.find(b => b.id === map.places[loop.fromPlace].blockId) };
    }
    function recCountInStop() {
        if (!recCounting) return;
        if (recCountPlayer.isPlaying()) recCountPlayer.pause();
        recCountPlayer.setClickFilter(null);
        showCountIn(`recCountIn-${recCounting.slideKey}`, 0);
        recCounting = null;
    }
    // Counts the practice's count-in, then runs then() - straight away when the count-in is off
    function recCountInThen(slide, then) {
        recCountInStop();
        const bars = practiceCountInWhen() === 'off' ? 0 : practiceCountInBars();
        const { block } = recPracticeStart(slide);
        if (!bars || !block) { then(); return; }
        const beats = metroBlkBeatsPerBarFor(block);
        recCounting = { slideKey: flowMediaSlideKey(slide), totalClicks: bars * beats, then };
        recCountPlayer.setConductorBpm(block.bpm * recSpeedOf(slide) / 100);
        recCountPlayer.setConductorBeatsPerBar(beats);
        recCountPlayer.setNotesPerBeat(1);
        recCountPlayer.setSubdivisionFactor(1);
        recCountPlayer.setVolume(flowVolume / 100);
        recCountPlayer.setClickFilter((ci) => ci < recCounting.totalClicks); // nothing sounds once the music starts
        recCountPlayer.resetToBarStart();
        recCountPlayer.play();
    }
    recCountPlayer.onBeat((info) => {
        const c = recCounting;
        if (!c || !info || info.ended) return;
        const left = c.totalClicks - info.clickIndex;
        if (left > 0) { showCountIn(`recCountIn-${c.slideKey}`, left, c.totalClicks); return; }
        const then = c.then;
        recCountInStop();
        then();
    });
    function recPlayInPractice() {
        const slide = recActiveSlide();
        const player = recPlayerOf(slide);
        if (!slide || !player) return;
        if (recCounting || player.playing()) { recCountInStop(); pauseFlowMediaSlide(slide); renderRecScoreControls(); return; }
        if (flowPlayer.isPlaying()) pauseFlow();
        const { startMs } = recPracticeStart(slide);
        if (startMs !== null) { try { player.seek(startMs); } catch (error) { /* not ready yet */ } }
        recCountInThen(slide, () => {
            try { if (startMs !== null) player.seek(startMs); player.play(); } catch (error) { /* not ready yet */ }
            recStartTicker();
            renderRecScoreControls();
        });
        renderRecScoreControls();
    }

    // Choosing here sets the one play speed - the metronome follows it too (ML-599)
    async function openRecSpeedChoice() {
        await ensurePlaySpeeds();
        const slide = recActiveSlide();
        const now = recSpeedOf(slide);
        const word = (pct) => (pct === 100 ? 'as recorded' : pct < 100 ? 'slower, same pitch' : 'faster, same pitch');
        openFlowChoiceModal('Play speed', recSpeedsFor(slide).map(pct => ({ label: `${pct}% - ${word(pct)}`, value: pct, selected: pct === now })), (opt) => {
            // in a practice it's a Custom speed for this go, as the Level pop-up's (ML-588)
            if (flowSession) { flowSession.custom = true; flowSession.customPercent = opt.value; }
            setFlowSpeedPercent(opt.value);
            if (flowSession) renderFlowSessionControls();
        });
    }

    // --- Marking a recording: its start, the bars and its end (ML-488; ML-597 made it one pop-up, on Edit -> Media) ---
    // Its own player. The place being marked steps on by one after each mark, so tapping along bar by bar marks a run
    // of bars; ◀ ▶ or a typed bar number moves it. The start and end are the clip (ML-312) - the same rules as the
    // old start-and-end pop-up (FlowJourney.cleanClip / nudgeClip), which the Recordings tool still uses.
    let barMap = null; // { recordingId, marks: [...], clip: { startMs, endMs }, place, places, media, yt, movement }
    const barMapPositionMs = () => {
        if (!barMap) return 0;
        if (barMap.media) return (barMap.media.currentTime || 0) * 1000;
        try { return (barMap.yt && barMap.yt.getCurrentTime ? barMap.yt.getCurrentTime() : 0) * 1000; } catch (error) { return 0; }
    };
    const barMapDurationMs = () => {
        if (!barMap) return null;
        let seconds = 0;
        if (barMap.media) seconds = barMap.media.duration;
        else { try { seconds = barMap.yt && barMap.yt.getDuration ? barMap.yt.getDuration() : 0; } catch (error) { seconds = 0; } }
        return Number.isFinite(seconds) && seconds > 0 ? seconds * 1000 : null;
    };
    function barMapClipMark(which) {
        if (!barMap) return;
        const at = Math.round(barMapPositionMs());
        const next = { ...barMap.clip, [which === 'start' ? 'startMs' : 'endMs']: at };
        // A start put after the end (or an end before the start) lets go of the other - the one just tapped is meant
        if (next.startMs && next.endMs && next.endMs - next.startMs < FlowJourney.CLIP_MIN_LENGTH_MS) next[which === 'start' ? 'endMs' : 'startMs'] = null;
        const checked = FlowJourney.cleanClip(next, barMapDurationMs());
        if (!checked.ok) { showWarningToast(which === 'end' && at < FlowJourney.CLIP_MIN_LENGTH_MS ? 'Play it to where the piece ends, then tap Ends here.' : checked.message); return; }
        barMap.clip = { startMs: checked.startMs, endMs: checked.endMs };
        renderBarMapModal();
    }
    function barMapClipNudge(which, deltaMs) {
        if (!barMap) return;
        barMap.clip = FlowJourney.nudgeClip(barMap.clip, which, deltaMs, barMapDurationMs());
        renderBarMapModal();
        // Hear where the mark now is: the start plays from it; the end plays its last two seconds
        barMapSeekAndPlay(which === 'start' ? (barMap.clip.startMs || 0) : Math.max(barMap.clip.startMs || 0, (barMap.clip.endMs || barMapDurationMs() || 0) - 2000));
    }
    // ML-598: "Bars 1 to 16: 0:42 on the recording, 0:40 at the piece's speeds (5% slower)" - one line a stretch
    const stretchClock = (ms) => (ms >= 60000 ? FlowJourney.clockText(ms) : `${(ms / 1000).toFixed(1)}s`);
    function recordingStretchLines(blocks, r, marks, clip) {
        const places = FlowJourney.journeyPlaces(blocks, recOpts(r));
        return FlowJourney.recordingStretches(blocks, recOpts(r), marks, clip).map((s) => {
            const from = FlowJourney.placeLabel(places, s.fromPlace);
            const to = FlowJourney.placeLabel(places, s.toPlace);
            const bars = s.fromPlace === s.toPlace ? from : `${from.replace(/^Bar /, 'Bars ')} to ${to.replace(/^Bar /, '')}`;
            const pct = s.pieceMs ? Math.round((s.playedMs / s.pieceMs - 1) * 100) : 0;
            const diff = pct === 0 ? 'the same' : `${Math.abs(pct)}% ${pct > 0 ? 'slower' : 'faster'}`;
            return `${bars}: ${stretchClock(s.playedMs)} on the recording, ${stretchClock(s.pieceMs)} at the piece's speeds (${diff})`;
        });
    }
    function barMapSeekAndPlay(ms) {
        if (!barMap) return;
        if (barMap.media) { barMap.media.currentTime = ms / 1000; barMap.media.play().catch(() => { /* wants a tap on the player first */ }); }
        else if (barMap.yt && barMap.yt.seekTo) { try { barMap.yt.seekTo(ms / 1000, true); barMap.yt.playVideo(); } catch (error) { /* not ready yet */ } }
    }
    function renderBarMapModal() {
        if (!barMap) return;
        const label = FlowJourney.placeLabel(barMap.places, barMap.place);
        document.getElementById('barMapPlaceLbl').textContent = label;
        document.getElementById('barMapMarkBtnLbl').textContent = `This is ${label.charAt(0).toLowerCase()}${label.slice(1)}`;
        document.getElementById('barMapPrevBtn').disabled = barMap.place <= 0;
        document.getElementById('barMapNextBtn').disabled = barMap.place >= barMap.places.length - 1;
        const used = FlowJourney.usableMarks(barMap.places, barMap.marks);
        const list = document.getElementById('barMapList');
        list.innerHTML = used.length
            ? used.map(m => `
                <div class="history-item">
                    <div class="history-details"><div><strong>${escapeHtml(FlowJourney.placeLabel(barMap.places, m.place))}</strong><span>at ${escapeHtml(FlowJourney.clockText(m.atMs))}</span></div></div>
                    <div class="flex-row gap-sm">
                        <button type="button" class="btn-text" data-act="barmap-play" data-arg="${m.place}" aria-label="Play from ${escapeHtml(FlowJourney.placeLabel(barMap.places, m.place))}">Play</button>
                        <button type="button" class="btn-text btn-text-danger" data-act="barmap-remove" data-arg="${m.place}" aria-label="Remove the mark on ${escapeHtml(FlowJourney.placeLabel(barMap.places, m.place))}">Remove</button>
                    </div>
                </div>`).join('')
            : `<p class="text-muted">No bars marked yet. Until one is, ${barMap.movement ? `bar ${barMap.movement.startBar} (the start of ${escapeHtml(FlowJourney.movementLabel(barMap.movement, false))})` : 'bar 1'} is taken to be at the recording's start mark and the rest follows the piece's speeds.</p>`;
        document.getElementById('barMapCount').textContent = used.length ? `${used.length} bar${used.length === 1 ? '' : 's'} marked` : '';
        const { clip } = barMap;
        document.getElementById('barMapStartTime').textContent = clip.startMs ? FlowJourney.clockText(clip.startMs) : 'The very start';
        document.getElementById('barMapEndTime').textContent = clip.endMs ? FlowJourney.clockText(clip.endMs) : 'The very end';
        const r = (currentFlowDetail?.recordings || []).find(x => String(x.id) === String(barMap.recordingId));
        const lines = r ? recordingStretchLines(currentFlowBlocks, r, barMap.marks, clip) : [];
        document.getElementById('barMapStretches').innerHTML = lines.length
            ? lines.map(l => `<p class="text-sm mb-2">${escapeHtml(l)}</p>`).join('')
            : '<p class="text-sm text-muted">Tap Ends here, or mark a bar, to see how long the bars take on the recording.</p>';
    }
    function openBarMapModal(recordingId) {
        const r = (currentFlowDetail?.recordings || []).find(x => String(x.id) === String(recordingId));
        const places = r ? FlowJourney.journeyPlaces(currentFlowBlocks, recOpts(r)) : []; // ML-531: a movement's recording - its bars
        if (!r) return;
        if (!places.length) { showWarningToast('Add the piece\'s bars first - then mark where they fall in the recording.'); return; }
        stopFlowEditorMedia(); // the row's own preview must not play under the pop-up's
        const isYoutube = r.type === 'youtube';
        barMap = { recordingId: r.id, marks: FlowJourney.usableMarks(places, r.marks || []), clip: recordingClip(r), places, place: 0, media: null, yt: null, movement: recMovement(r) };
        // Start on the bar after the last one marked - the next one you will want.
        if (barMap.marks.length) barMap.place = Math.min(places.length - 1, barMap.marks[barMap.marks.length - 1].place + 1);
        document.getElementById('barMapName').textContent = r.title;
        const host = document.getElementById('barMapPlayerHost');
        if (isYoutube) {
            host.innerHTML = `<div class="flow-media-player-video"><iframe id="barMapYtFrame" src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(r.youtubeVideoId)}?enablejsapi=1&amp;origin=${encodeURIComponent(location.origin)}" title="${escapeHtml(r.title)}" allow="accelerometer; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></div>`;
            const mine = barMap;
            ensureFlowYtApi().then((YT) => {
                const frame = document.getElementById('barMapYtFrame');
                if (barMap !== mine || !frame) return;
                mine.yt = new YT.Player(frame, {});
            });
        } else {
            host.innerHTML = (r.mimeType || '').startsWith('video/')
                ? `<div class="flow-media-player-video"><video id="barMapMedia" controls preload="metadata" src="${escapeHtml(r.blobUrl)}"></video></div>`
                : `<audio id="barMapMedia" class="flow-media-player-audio" controls preload="metadata" src="${escapeHtml(r.blobUrl)}"></audio>`;
            barMap.media = document.getElementById('barMapMedia');
        }
        document.getElementById('barMapBarInput').value = '';
        renderBarMapModal();
        showModal('barMapModal');
    }
    function closeBarMapModal() {
        if (barMap) {
            try { if (barMap.media) barMap.media.pause(); } catch (error) { /* nothing playing */ }
            try { if (barMap.yt && barMap.yt.destroy) barMap.yt.destroy(); } catch (error) { /* already gone */ }
        }
        barMap = null;
        document.getElementById('barMapPlayerHost').innerHTML = '';
        hideModal('barMapModal');
    }
    function barMapStep(by) {
        if (!barMap) return;
        barMap.place = Math.min(barMap.places.length - 1, Math.max(0, barMap.place + by));
        renderBarMapModal();
    }
    function barMapGoToTypedBar() {
        if (!barMap) return;
        const n = Math.round(Number(document.getElementById('barMapBarInput').value));
        const place = barMap.places.findIndex(p => p.number === n && p.kind === 'main');
        if (place === -1) { showWarningToast(barMap.movement ? `This recording is of ${FlowJourney.movementLabel(barMap.movement, false)}: bars ${barMap.movement.startBar} to ${barMap.movement.endBar}.` : `This piece has no bar ${Number.isFinite(n) ? n : 'like that'}.`); return; }
        barMap.place = place;
        renderBarMapModal();
    }
    // "This is bar 33": the bar being marked is where the player is now. Then on to the next bar.
    function barMapMarkHere() {
        if (!barMap) return;
        const p = barMap.places[barMap.place];
        const atMs = Math.round(barMapPositionMs());
        const others = barMap.marks.filter(m => m.place !== p.place);
        const before = others.filter(m => m.place < p.place).pop();
        const after = others.find(m => m.place > p.place);
        if (before && atMs <= before.atMs) { showWarningToast(`${FlowJourney.placeLabel(barMap.places, before.place)} is marked later than this (${FlowJourney.clockText(before.atMs)}). Play on to where this bar starts, or remove that mark.`); return; }
        if (after && atMs >= after.atMs) { showWarningToast(`${FlowJourney.placeLabel(barMap.places, after.place)} is marked earlier than this (${FlowJourney.clockText(after.atMs)}). Go back to where this bar starts, or remove that mark.`); return; }
        barMap.marks = [...others, { place: p.place, number: p.number, pass: p.pass, atMs }].sort((a, b) => a.place - b.place);
        if (barMap.place < barMap.places.length - 1) barMap.place++;
        renderBarMapModal();
    }
    function barMapRemove(place) {
        if (!barMap) return;
        barMap.marks = barMap.marks.filter(m => m.place !== place);
        renderBarMapModal();
    }
    function barMapPlayFrom(place) {
        const m = barMap && barMap.marks.find(x => x.place === place);
        if (m) barMapSeekAndPlay(m.atMs);
    }
    // Done. In Edit (and for a recording not saved yet) the start, end and marks are kept until Save, like everything
    // else there (saveFlowMediaEdits, saveFlowMarkEdits); a new piece being made saves them at once.
    async function saveBarMapModal(opts = {}) {
        if (!barMap) return false;
        const { recordingId, marks, clip } = barMap;
        const rec = (currentFlowDetail?.recordings || []).find(x => String(x.id) === String(recordingId));
        if (!rec) return false;
        const before = recordingClip(rec);
        const clipChanged = (before.startMs || null) !== (clip.startMs || null) || (before.endMs || null) !== (clip.endMs || null);
        try {
            if (flowEditMode === 'edit' || typeof recordingId === 'string') {
                currentFlowDetail.recordings = currentFlowDetail.recordings.map(x => (String(x.id) === String(recordingId) ? { ...x, clipStartMs: clip.startMs, clipEndMs: clip.endMs, marks } : x));
            } else {
                if (clipChanged) currentFlowDetail = await API.flows.recordings.setClip(currentFlowId, recordingId, { startMs: clip.startMs, endMs: clip.endMs });
                currentFlowDetail = await API.flows.recordings.setMarks(currentFlowId, recordingId, { marks });
            }
        } catch (error) {
            showWarningToast('That couldn\'t be saved: ' + error.message);
            return false;
        }
        closeBarMapModal();
        renderFlowRecordingsList();
        // ML-597: the speeds were matched to this recording and where it starts or ends has moved - offer the old ones
        if (clipChanged && opts.offer !== false) offerSpeedsBack(recordingId, `where ${rec.title} starts or ends has changed`);
        return true;
    }

    // ML-533: the piece's own speeds matched to a recording's marks, so the metronome lands where the recording does
    // (FlowJourney.matchSpeeds). The marks are kept first; then it says what would change and asks. ML-597: in Edit the
    // new speeds are kept until Save like any other change to the bars, and the speeds from before the first match are
    // kept on the piece (speedsBeforeMatch) so they can be put back later.
    async function matchSpeedsToBarMap() {
        if (!barMap) return;
        const recordingId = barMap.recordingId;
        if (!FlowJourney.usableMarks(barMap.places, barMap.marks).length) { showWarningToast('Mark at least one bar first - where the speed changes, and after a pause.'); return; }
        if (!(await saveBarMapModal({ offer: false }))) return; // matching again is the answer to "the speeds no longer fit"
        const r = (currentFlowDetail.recordings || []).find(x => String(x.id) === String(recordingId));
        if (!r) return;
        const out = FlowJourney.matchSpeeds(currentFlowBlocks, recOpts(r), r.marks || [], recordingClip(r));
        if (!out.ok) { showWarningToast('Mark at least one bar first.'); return; }
        if (!out.changes.length) { showSuccessToast('The piece\'s speeds already match this recording.'); return; }
        const range = (c) => (c.fromBar === c.toBar ? `bar ${c.fromBar}` : `bars ${c.fromBar}-${c.toBar}`);
        const most = Math.max(...out.changes.map(c => Math.abs(c.newBpm - c.oldBpm)));
        const list = out.changes.slice(0, 6).map(c => `${range(c)}: ${c.oldBpm} to ${c.newBpm}`).join('; ') + (out.changes.length > 6 ? `; and ${out.changes.length - 6} more` : '');
        const near = out.maxErrorSeconds < 0.05 ? 'exactly' : `to within ${out.maxErrorSeconds.toFixed(out.maxErrorSeconds < 1 ? 2 : 1)} seconds`;
        const onStarts = out.inside.length ? ' at the start of a block of bars' : '';
        const secs = (s) => `${s.toFixed(s < 1 ? 2 : 1)} seconds`;
        const worst = out.inside.length ? Math.max(...out.inside.map(m => m.errorSeconds)) : 0;
        const inside = out.inside.length ? ` ${out.inside.length === 1 ? `The mark on bar ${out.inside[0].number} is` : `${out.inside.length} marks (bars ${out.inside.map(m => m.number).join(', ')}) are`} part-way through a block of bars, where the speed can't change: ${out.inside.length === 1 ? 'it would be' : 'they would be up to'} ${secs(worst)} out. To meet ${out.inside.length === 1 ? 'it' : 'them'} too, split the bars there in the edit screen, then match again.` : '';
        const band = currentFlowDetail.ownerBandId ? ' Everyone in the band will play at these speeds.' : ''; // ML-597: said plainly on a band's piece
        showConfirmModal('Match the piece\'s speeds?',
            `${out.changes.length} speed${out.changes.length === 1 ? '' : 's'} would change, by up to ${most} bpm (${list}). The metronome would then meet the bars you marked${onStarts} ${near}.${inside}${band} The speeds from before are kept, so you can put them back.`,
            () => applyMatchedSpeeds(out, r.id), false, 'Change the speeds', 'Leave them');
    }

    // ML-597: the bars' speeds and speed changes, block by block - the real (saved) blocks only
    const speedsOfBlocks = () => currentFlowBlocks.filter(b => typeof b.id !== 'string').map(b => ({ id: b.id, bpm: b.bpm, ramps: (b.ramps || []).map(x => ({ ...x })) }));
    // Puts speeds onto the piece: in Edit onto the bars being edited (saved with Save); otherwise saved now
    async function writeBlockSpeeds(list, speedsBeforeMatch) {
        const byId = new Map(list.map(b => [String(b.id), b]));
        if (flowEditMode === 'edit') {
            currentFlowBlocks.forEach(b => { const s = byId.get(String(b.id)); if (s) { b.bpm = s.bpm; b.ramps = (s.ramps || []).map(x => ({ ...x })); } });
            currentFlowDetail.speedsBeforeMatch = speedsBeforeMatch;
            renderFlowBlocksStudio();
            renderFlowRecordingsList();
            return;
        }
        for (const b of list) await API.flows.blocks.update(b.id, { bpm: b.bpm, ramps: b.ramps });
        currentFlowDetail = await API.flows.update(currentFlowId, { speedsBeforeMatch });
        const blocks = await API.flows.blocks.list(currentFlowId);
        flowLeadInBlock = blocks.find(x => x.isLeadIn) || null;
        currentFlowBlocks = blocks.filter(x => !x.isLeadIn);
        renderFlowBlocksStudio();
        renderFlowRecordingsList();
    }
    async function applyMatchedSpeeds(out, recordingId) {
        const before = speedsOfBlocks();
        const keptBefore = currentFlowDetail.speedsBeforeMatch || null;
        // The speeds from before the FIRST match are the ones kept - matching again (to this or another recording) keeps them
        const kept = { recordingId: typeof recordingId === 'string' ? null : recordingId, blocks: keptBefore ? keptBefore.blocks : before };
        const changed = new Map(out.changes.map(c => [String(c.blockId), { id: c.blockId, bpm: c.newBpm, ramps: out.blocks[c.blockIndex].ramps || [] }]));
        const after = before.map(b => changed.get(String(b.id)) || b);
        try {
            await writeBlockSpeeds(after, kept);
            const saveWord = flowEditMode === 'edit' ? ' - Save to keep them' : '';
            showUndoToast(`${out.changes.length} speed${out.changes.length === 1 ? '' : 's'} changed to match the recording${saveWord}`, async () => {
                try { await writeBlockSpeeds(before, keptBefore); } catch (e) { showWarningToast('The old speeds couldn\'t be put back: ' + e.message); }
            });
        } catch (e) {
            showWarningToast('The speeds couldn\'t all be saved: ' + e.message);
        }
    }
    // ML-597: the speeds from before the first match, back on the bars that are still there
    async function restoreSpeedsBeforeMatch() {
        const kept = currentFlowDetail && currentFlowDetail.speedsBeforeMatch;
        if (!kept) return;
        try {
            await writeBlockSpeeds(kept.blocks, null);
            showSuccessToast(flowEditMode === 'edit' ? 'The original speeds are back - Save to keep them' : 'The original speeds are back');
        } catch (e) { showWarningToast('The original speeds couldn\'t be put back: ' + e.message); }
    }
    // Offered - never done on its own (owner, 23 Oct 2026) - when the recording the speeds were matched to is taken off,
    // or where it starts or ends moves.
    function offerSpeedsBack(recordingId, why) {
        const kept = currentFlowDetail && currentFlowDetail.speedsBeforeMatch;
        if (!kept || kept.recordingId === null || String(kept.recordingId) !== String(recordingId)) return;
        // after whatever pop-up asked first has closed (the confirm pop-up closes itself once its answer has run)
        setTimeout(() => showConfirmModal('Put the original speeds back?', `The piece's speeds were matched to this recording, and ${why}. Put back the speeds the piece had before, or keep the matched ones?`,
            () => restoreSpeedsBeforeMatch(), false, 'Put them back', 'Keep these speeds'), 0);
    }

    // ===== ML-489: the Recordings tool (the rehearsal score, step B) =====
    // Whole rehearsal recordings: uploaded once from a phone's own recorder (the app does not record),
    // then given to pieces - each piece gets a cut, set in the start-and-end pop-up (ML-312). Anyone can
    // use one on their own pieces; the server only offers a band's pieces to its organisers. How many a
    // member may keep is a limit by account type. docs/rehearsal-score.md; specs/components/rehearsal-score.md.
    let recordingsData = null; // the server's answer: { recordings, pieces, limit, used, maxBytes, folder }
    const megabytes = (bytes) => (bytes >= 1024 * 1024 * 10 ? Math.round(bytes / (1024 * 1024)) : Math.round(bytes / (1024 * 1024) * 10) / 10);
    function renderRecordings() {
        const d = recordingsData;
        const list = document.getElementById('recordingsList');
        if (!d || !list) return;
        const full = d.used >= d.limit;
        const maxMb = Math.round(d.maxBytes / (1024 * 1024));
        document.getElementById('recordingsUploadLbl').textContent = `Upload a rehearsal recording (up to ${maxMb} MB)`;
        document.getElementById('recordingsUploadBtn').disabled = full;
        // Said once, plainly, and it blocks nothing else (specs/README.md, "No pressure")
        document.getElementById('recordingsCount').textContent = full
            ? `You are keeping ${d.used} of ${d.limit} recording${d.limit === 1 ? '' : 's'}. Delete one you have finished with to add another.`
            : `${d.used} of ${d.limit} recording${d.limit === 1 ? '' : 's'} kept.`;
        list.innerHTML = d.recordings.length ? d.recordings.map(r => {
            const about = [r.type === 'youtube' ? 'YouTube video' : '', r.fileSizeBytes ? `${megabytes(r.fileSizeBytes)} MB` : '', r.recordedOn ? `recorded ${plDateText(r.recordedOn)}` : ''].filter(Boolean).join(' · ');
            const cuts = r.cuts.length ? r.cuts.map(c => `
                <div class="history-item">
                    <div class="history-details"><div><strong>${escapeHtml(c.pieceTitle)}${c.movement ? ` · Mvt ${c.movement}` : ''}</strong><span>${escapeHtml(FlowJourney.clipLabel({ startMs: c.clipStartMs, endMs: c.clipEndMs }))}${c.band ? ` · ${escapeHtml(c.band)}` : ''}</span></div></div>
                    <div class="flex-row gap-sm">
                        <button type="button" class="btn-text" data-act="recordings-cut-change" data-arg="${c.id}" aria-label="Change where ${escapeHtml(c.pieceTitle)} starts and ends">Change</button>
                        <button type="button" class="btn-text btn-text-danger" data-act="recordings-cut-remove" data-arg="${c.id}" aria-label="Take this recording off ${escapeHtml(c.pieceTitle)}">Remove</button>
                    </div>
                </div>`).join('') : '<p class="text-muted">Not on a piece yet.</p>';
            return `
                <section class="flow-card" data-recording-id="${r.id}">
                    <div class="flow-card-header">
                        <div><span class="flow-card-label">${escapeHtml(r.title)}</span>${about ? `<p class="flow-card-sublabel">${escapeHtml(about)}</p>` : ''}</div>
                        <span class="flow-pill">${r.cuts.length} piece${r.cuts.length === 1 ? '' : 's'}</span>
                    </div>
                    ${cuts}
                    <button type="button" class="flow-action-btn flow-action-btn-wide" data-act="recordings-give" data-arg="${r.id}" aria-haspopup="dialog"><span class="material-symbols-outlined" aria-hidden="true">library_add</span> Give it to a piece</button>
                    <button type="button" class="btn-text btn-text-danger" data-act="recordings-delete" data-arg="${r.id}">Delete this recording</button>
                </section>`;
        }).join('') : '<p class="text-muted">No recordings here yet.</p>';
    }
    async function openRecordings() {
        document.getElementById('recordingsList').innerHTML = recordingsData ? document.getElementById('recordingsList').innerHTML : '<p class="text-muted">Loading...</p>';
        try {
            recordingsData = await apiCall('/api/recordings');
            renderRecordings();
        } catch (error) {
            document.getElementById('recordingsList').innerHTML = `<p class="text-muted">${escapeHtml(error.message)}</p>`;
        }
    }
    const recordingById = (id) => (recordingsData ? recordingsData.recordings.find(r => String(r.id) === String(id)) : null);
    const recordingCutById = (id) => {
        for (const r of (recordingsData ? recordingsData.recordings : [])) {
            const cut = r.cuts.find(c => String(c.id) === String(id));
            if (cut) return { rec: r, cut };
        }
        return null;
    };
    // "Give it to a piece": which piece (one pop-up), then where it starts and ends (the next).
    // ML-532: what the start-and-end pop-up plays - the stored file, or the YouTube video
    const recordingsSource = (rec) => (rec.type === 'youtube' ? { type: 'youtube', youtubeVideoId: rec.youtubeVideoId } : { type: 'upload', blobUrl: rec.blobUrl, mimeType: rec.mimeType });
    // ML-531: a piece in movements can take it once for the whole piece or once per movement - which movement comes
    // between the piece and the start and end.
    function recordingsGive(recordingId) {
        const rec = recordingById(recordingId);
        if (!rec) return;
        const free = (p) => {
            const mine = rec.cuts.filter(c => c.scoreId === p.id);
            const moves = p.movements || [];
            return [...(mine.some(c => !c.movement) ? [] : [null]), ...moves.filter(m => !mine.some(c => c.movement === m.number)).map(m => m.number)];
        };
        const pieces = recordingsData.pieces.filter(p => ((p.movements || []).length ? free(p).length : !rec.cuts.some(c => c.scoreId === p.id)));
        if (!pieces.length) { showWarningToast(recordingsData.pieces.length ? 'It is already on every piece you can add it to.' : 'Make a piece first (Add a piece), then give this recording to it.'); return; }
        const setStartAndEnd = (piece, m) => openClipPopup({
            title: `${piece.title}${m ? ` · ${FlowJourney.movementLabel(m, false)}` : ''} - in ${rec.title}`, ...recordingsSource(rec), clip: { startMs: null, endMs: null },
            onSave: async (clip) => {
                recordingsData = await apiCall(`/api/recordings/${rec.id}/cuts`, 'POST', { scoreId: piece.id, startMs: clip.startMs, endMs: clip.endMs, movement: m ? m.number : null });
                renderRecordings();
                showSuccessToast(`It is on ${piece.title}${m ? ` (${FlowJourney.movementLabel(m, true)})` : ''} now.`);
            }
        });
        openFlowChoiceModal('Which piece?', pieces.map(p => ({
            html: `<span><strong>${escapeHtml(p.title)}</strong>${p.band ? `<br><span class="text-sm text-muted">${escapeHtml(p.band)}</span>` : ''}</span>`, piece: p
        })), (opt) => {
            const p = opt.piece;
            if (!(p.movements || []).length) { setStartAndEnd(p, null); return; }
            const left = free(p);
            openFlowChoiceModal('Which movement is it of?', left.map(n => {
                const m = n ? p.movements.find(x => x.number === n) : null;
                return { m, html: m ? addPieceRow(FlowJourney.movementLabel(m, true), `Bars ${m.startBar}-${m.endBar}`) : addPieceRow('The whole piece', `All ${p.movements.length} movements`) };
            }), (o) => setStartAndEnd(p, o.m));
        });
    }
    function recordingsCutChange(cutId) {
        const found = recordingCutById(cutId);
        if (!found) return;
        const { rec, cut } = found;
        openClipPopup({
            title: `${cut.pieceTitle} - in ${rec.title}`, ...recordingsSource(rec), clip: { startMs: cut.clipStartMs, endMs: cut.clipEndMs },
            onSave: async (clip) => {
                await API.flows.recordings.setClip(cut.scoreId, cut.id, { startMs: clip.startMs, endMs: clip.endMs });
                await openRecordings();
            }
        });
    }
    function recordingsCutRemove(cutId) {
        const found = recordingCutById(cutId);
        if (!found) return;
        showConfirmModal('Take it off the piece', `Take this recording off "${found.cut.pieceTitle}"? The recording stays here.`, async () => {
            try {
                await API.flows.recordings.delete(found.cut.scoreId, found.cut.id);
                await openRecordings();
            } catch (error) { showWarningToast(error.message); }
        }, true, 'Take it off');
    }
    function recordingsDelete(recordingId) {
        const rec = recordingById(recordingId);
        if (!rec) return;
        const on = rec.cuts.length ? ` It will come off ${rec.cuts.length === 1 ? `"${rec.cuts[0].pieceTitle}"` : `${rec.cuts.length} pieces`} too.` : '';
        showConfirmModal('Delete recording', `Delete "${rec.title}"?${on} Keep your own copy of the file if you may want it again - this can't be undone.`, async () => {
            try {
                recordingsData = await apiCall(`/api/recordings/${rec.id}`, 'DELETE');
                renderRecordings();
            } catch (error) { showWarningToast(error.message); }
        }, true, 'Delete');
    }
    // "Delete this list's recordings" on a practice list (the owner, 8 Oct 2026): the limit only works if
    // clearing up after a concert is easy. It is about the member's OWN uploads in the Recordings tool:
    // one that is only on this list's pieces is deleted, file and all; one that is also on a piece outside
    // the list just comes off this list's pieces. Says what it will do first.
    async function plClearRecordings() {
        const l = plState.list;
        if (!l) return;
        let data;
        try { data = await apiCall('/api/recordings'); } catch (error) { showWarningToast(error.message); return; }
        const inList = new Set(l.pieces.map(p => Number(p.scoreId)));
        const whole = [];   // recordings to delete
        const cuts = [];    // cuts to take off, where the recording is used elsewhere too
        data.recordings.forEach(r => {
            const here = r.cuts.filter(c => inList.has(c.scoreId));
            if (!here.length) return;
            if (here.length === r.cuts.length) whole.push(r); else cuts.push(...here);
        });
        if (!whole.length && !cuts.length) { showInfoToast('None of your recordings are on this list\'s pieces.'); return; }
        const says = [
            whole.length ? `${whole.length} recording${whole.length === 1 ? '' : 's'} will be deleted (${whole.map(r => `"${r.title}"`).join(', ')}).` : '',
            cuts.length ? `${cuts.length === 1 ? 'One is' : `${cuts.length} are`} also on pieces outside this list, so ${cuts.length === 1 ? 'it' : 'they'} will only come off this list's pieces.` : '',
            'Keep your own copies of the files if you may want them again - this can\'t be undone.'
        ].filter(Boolean).join(' ');
        showConfirmModal(`Delete this list's recordings`, says, async () => {
            try {
                for (const r of whole) await apiCall(`/api/recordings/${r.id}`, 'DELETE');
                for (const c of cuts) await API.flows.recordings.delete(c.scoreId, c.id);
                recordingsData = null;
                showSuccessToast(whole.length ? `${whole.length} recording${whole.length === 1 ? '' : 's'} deleted` : 'Taken off this list\'s pieces');
            } catch (error) { showWarningToast(error.message); }
        }, true, 'Delete');
    }
    document.getElementById('plClearRecordingsBtn')?.addEventListener('click', plClearRecordings);

    document.getElementById('recordingsUploadBtn')?.addEventListener('click', () => withUploadRights(() => document.getElementById('recordingsFileInput')?.click())); // ML-278
    document.getElementById('recordingsFileInput')?.addEventListener('change', async (e) => {
        const file = e.target.files[0];
        e.target.value = '';
        if (!file || !recordingsData) return;
        const maxMb = Math.round(recordingsData.maxBytes / (1024 * 1024));
        if (file.size > recordingsData.maxBytes) {
            showWarningToast(`"${file.name}" is ${Math.round(file.size / (1024 * 1024))} MB and the most is ${maxMb} MB. Record at your phone's ordinary quality setting - a "lossless" or WAV recording is about ten times the size.`);
            return;
        }
        // Sound only (the Children's Code check, 8 Oct 2026): a video of a band is more than practising needs
        if (!/\.(mp3|m4a|wav)$/i.test(file.name) || /^video\//.test(file.type)) { showWarningToast('That kind of file can\'t be used here. Save the recording as sound only: m4a or mp3.'); return; }
        const box = document.getElementById('recordingsUploadProgress');
        const percentEl = document.getElementById('recordingsUploadPercent');
        const fillEl = document.getElementById('recordingsUploadFill');
        document.getElementById('recordingsUploadName').innerText = file.name;
        percentEl.innerText = '0%';
        fillEl.style.setProperty('--progress', '0%');
        box.classList.remove('hidden-group');
        document.getElementById('recordingsUploadBtn').disabled = true;
        try {
            // Sent in parts (multipart): a part that fails is sent again, so a dropped connection in a
            // band room doesn't mean starting a 60 MB upload from nothing.
            const blob = await uploadToStore(`${recordingsData.folder}/${file.name}`, file, {
                access: 'public',
                multipart: true,
                handleUploadUrl: `${API_BASE_URL}/api/recordings/upload-token`,
                onUploadProgress: (progress) => {
                    const pct = Math.round(progress.percentage);
                    percentEl.innerText = `${pct}%`;
                    fillEl.style.setProperty('--progress', `${pct}%`);
                }
            });
            recordingsData = await apiCall('/api/recordings', 'POST', { blobUrl: blob.url, blobPathname: blob.pathname, fileName: file.name, fileSizeBytes: file.size, mimeType: blob.contentType || file.type });
            showSuccessToast('Recording uploaded');
        } catch (error) {
            showWarningToast('The upload didn\'t finish: ' + error.message);
        } finally {
            box.classList.add('hidden-group');
            renderRecordings();
        }
    });

    // When there's more than one slide, renderFlowMediaCarousel pads the track with one preview
    // slide on each end (a clone of the last slide up front, a clone of the first slide at the
    // back - see flowMediaSlidePreviewHtml) so wrap-around swiping has something to animate into.
    // That shifts every real slide's track position (data-track-slot) one place to the right - this
    // is the shift amount, 0 when there's only the metronome slide and no padding was added.
    function flowMediaTrackOffset() {
        return flowMediaSlides.length > 1 ? 1 : 0;
    }

    // Pixels, not a percentage transform - .flow-media-slide's flex:0 0 100% makes the track's own
    // rendered width N-times the viewport's (that's what makes it overflow rather than shrink to
    // fit), so translateX(-slot*100%) would resolve against that N-times width, not the viewport -
    // wrong distance for anything past the first slide. `slot` defaults to the active slide's own
    // track position, but a wrap transition passes the padding slide's position explicitly.
    function applyFlowMediaTrackPosition(slot) {
        const viewport = document.getElementById('flowMediaViewport');
        const track = document.getElementById('flowMediaTrack');
        if (!viewport || !track) return;
        if (slot === undefined) slot = flowMediaActiveIndex + flowMediaTrackOffset();
        const width = viewport.getBoundingClientRect().width;
        setMove(track, -(slot * width));
    }

    function updateFlowMediaViewportHeight() {
        const viewport = document.getElementById('flowMediaViewport');
        const track = document.getElementById('flowMediaTrack');
        if (!viewport || !track) return;
        const activeEl = track.children[flowMediaActiveIndex + flowMediaTrackOffset()];
        if (activeEl) viewport.style.setProperty('--viewport-h', `${activeEl.scrollHeight}px`);
    }

    function renderFlowMediaDots() {
        const dotsEl = document.getElementById('flowMediaDots');
        if (!dotsEl) return;
        if (flowMediaSlides.length <= 1) {
            dotsEl.classList.add('hidden-group');
            dotsEl.innerHTML = '';
            return;
        }
        dotsEl.classList.remove('hidden-group');
        dotsEl.innerHTML = flowMediaSlides.map((slide, i) => {
            const iconHtml = slide.type === 'metronome' ? FLOW_METRONOME_ICON_SVG : `<span class="material-symbols-outlined">${slide.type === 'audio' ? 'music_note' : 'smart_display'}</span>`;
            const label = slide.type === 'metronome' ? 'Metronome' : `${slide.type === 'audio' ? 'Audio' : 'Video'} - ${slide.data.title}`;
            return `<button type="button" class="flow-media-dot${i === flowMediaActiveIndex ? ' active' : ''}" data-slide-index="${i}" aria-label="${escapeHtml(label)}">${iconHtml}</button>`;
        }).join('');
        dotsEl.querySelectorAll('[data-slide-index]').forEach(btn => {
            btn.addEventListener('click', () => goToFlowMediaSlide(Number(btn.dataset.slideIndex)));
        });
    }

    // Index sync (ticket's own term) - the active carousel slide and its indicator dot always
    // move together, whichever one triggered the change (dot tap, swipe, or a no-op call that just
    // needs to snap the track back to where it already was). Wraps round at either end, so
    // continuing to swipe past the last slide lands back on the first (and vice versa) - `rawIndex`
    // arriving as exactly -1 or exactly flowMediaSlides.length (one step past either end, only ever
    // sent by the swipe handler below) is what triggers the wrap-through-the-padding-slide
    // animation rather than a plain cut to the target slide.
    function goToFlowMediaSlide(rawIndex) {
        const count = flowMediaSlides.length;
        const targetIndex = ((rawIndex % count) + count) % count;
        const offset = flowMediaTrackOffset();
        const isForwardWrap = offset && rawIndex === count;
        const isBackwardWrap = offset && rawIndex === -1;
        if (targetIndex === flowMediaActiveIndex && !isForwardWrap && !isBackwardWrap) {
            applyFlowMediaTrackPosition();
            return;
        }
        pauseFlowMediaSlide(flowMediaSlides[flowMediaActiveIndex]);
        const track = document.getElementById('flowMediaTrack');
        flowMediaActiveIndex = targetIndex;
        const realSlot = flowMediaActiveIndex + offset;
        if ((isForwardWrap || isBackwardWrap) && track) {
            // Animate on into the padding slide at the far end (the "coming in" slide the user
            // just swiped toward), then hop back onto the real slide sitting in its place with the
            // transition switched off for that one frame - to the eye it's one continuous slide.
            applyFlowMediaTrackPosition(isForwardWrap ? count + offset : 0);
            track.addEventListener('transitionend', function onFlowMediaWrapEnd(e) {
                if (e.propertyName && e.propertyName !== 'transform') return;
                track.removeEventListener('transitionend', onFlowMediaWrapEnd);
                track.classList.add('no-transition');
                applyFlowMediaTrackPosition(realSlot);
                void track.offsetWidth; // force reflow so the transition below doesn't apply to this jump
                track.classList.remove('no-transition');
            }, { once: true });
        } else {
            applyFlowMediaTrackPosition();
        }
        updateFlowMediaViewportHeight();
        document.querySelectorAll('#flowMediaDots .flow-media-dot').forEach((btn, i) => {
            btn.classList.toggle('active', i === flowMediaActiveIndex);
        });
    }

    // Horizontal swipe on the carousel viewport - same lock/abandon technique as Quick Play's own
    // swipe-to-delete (wireQpBarSwipe): nothing transforms until the gesture actually commits to
    // "this is a horizontal swipe" (enough X travel while Y travel stays small), a clearly-vertical
    // drag before that point is left alone entirely so touch-action:pan-y can still scroll the page.
    const FLOW_MEDIA_SWIPE_LOCK_X_PX = 10;
    const FLOW_MEDIA_SWIPE_LOCK_Y_MAX_PX = 15;
    const FLOW_MEDIA_SWIPE_COMMIT_RATIO = 0.2;
    function wireFlowMediaSwipe() {
        const viewport = document.getElementById('flowMediaViewport');
        const track = document.getElementById('flowMediaTrack');
        if (!viewport || !track) return;
        let startX = 0, startY = 0, tracking = false, locked = false, abandoned = false, baseOffsetPx = 0;

        function onMove(e) {
            if (!tracking || abandoned) return;
            const dx = e.clientX - startX;
            const dy = e.clientY - startY;
            if (!locked) {
                if (Math.abs(dx) > FLOW_MEDIA_SWIPE_LOCK_X_PX && Math.abs(dy) < FLOW_MEDIA_SWIPE_LOCK_Y_MAX_PX) {
                    locked = true;
                    track.classList.add('no-transition');
                } else if (Math.abs(dy) >= FLOW_MEDIA_SWIPE_LOCK_Y_MAX_PX) {
                    abandoned = true;
                    return;
                } else {
                    return;
                }
            }
            e.preventDefault();
            const width = viewport.getBoundingClientRect().width;
            // Bounds include the padding slides at each end (flowMediaTrackOffset) so the drag can
            // continue past the last/first real slide onto whichever preview is coming in next.
            const slotOffset = flowMediaTrackOffset();
            const rightmostSlot = flowMediaSlides.length - 1 + 2 * slotOffset;
            const min = -rightmostSlot * width;
            const posPx = Math.min(0, Math.max(min, baseOffsetPx + dx));
            setMove(track, posPx);
        }
        function onUp(e) {
            if (!tracking) return;
            tracking = false;
            document.removeEventListener('pointermove', onMove);
            document.removeEventListener('pointerup', onUp);
            track.classList.remove('no-transition');
            if (!locked) return;
            const dx = e.clientX - startX;
            const width = viewport.getBoundingClientRect().width;
            if (Math.abs(dx) > width * FLOW_MEDIA_SWIPE_COMMIT_RATIO) {
                goToFlowMediaSlide(flowMediaActiveIndex + (dx < 0 ? 1 : -1));
            } else {
                goToFlowMediaSlide(flowMediaActiveIndex);
            }
        }
        // a11y: only records where a swipe/drag gesture starts - nothing activates on press (WCAG 2.5.2)
        viewport.addEventListener('pointerdown', (e) => {
            if (e.target.closest('audio, iframe, button, input')) return;
            startX = e.clientX;
            startY = e.clientY;
            baseOffsetPx = -(flowMediaActiveIndex + flowMediaTrackOffset()) * viewport.getBoundingClientRect().width;
            tracking = true;
            locked = false;
            abandoned = false;
            document.addEventListener('pointermove', onMove);
            document.addEventListener('pointerup', onUp);
        });
    }
    let flowMediaSwipeWired = false;

    // ML-600: the slides are in pixels (applyFlowMediaTrackPosition) and the viewport's height is the showing slide's
    // (updateFlowMediaViewportHeight), so when the screen changes width - a window dragged narrower, the rail folded, a
    // tablet turned - both are measured again, with no slide, along with the metronome row's width. Before, they kept
    // the old size until you switched between the metronome and a recording.
    var flowPlayRowClicks = 0; // var: renderFlowPlaybackRow can run before this line has
    let flowMediaResizeFrame = 0;
    if (typeof ResizeObserver !== 'undefined') {
        const viewport = document.getElementById('flowMediaViewport');
        let lastWidth = 0;
        if (viewport) new ResizeObserver(() => {
            const width = viewport.getBoundingClientRect().width;
            if (!width || width === lastWidth) return; // hidden, or only its height changed
            lastWidth = width;
            cancelAnimationFrame(flowMediaResizeFrame);
            flowMediaResizeFrame = requestAnimationFrame(() => {
                const track = document.getElementById('flowMediaTrack');
                if (track) track.classList.add('no-transition');
                applyFlowMediaTrackPosition();
                if (track) { void track.offsetWidth; track.classList.remove('no-transition'); }
                if (flowPlayRowClicks) metroApplyDisplayWidth('flowPlayRowViewport', 'flowPlayRowContent', flowPlayRowClicks);
                updateFlowMediaViewportHeight();
            });
        }).observe(viewport);
    }

    // Renders the carousel for the flow that's just loaded (buildFlowMediaSlides already ran) -
    // appends fresh audio/video slide markup after the always-present metronome slide, pads either
    // end with a wrap-around preview slide (see flowMediaSlidePreviewHtml), wires the YT players
    // for any video slides, and (re)measures the active slide's height.
    function renderFlowMediaCarousel() {
        const track = document.getElementById('flowMediaTrack');
        if (!track) return;
        // The metronome slide is the view's own static markup, kept by data-slide-type rather than
        // by position - a previous render may have left a wrap-around preview clone in front of it
        // (also data-slide-type="metronome", so excluded here by its own data-clone marker).
        const metronomeEl = track.querySelector('.flow-media-slide[data-slide-type="metronome"]:not([data-clone])');
        Array.from(track.children).forEach(child => { if (child !== metronomeEl) track.removeChild(child); });
        flowMediaSlides.slice(1).forEach(slide => {
            track.insertAdjacentHTML('beforeend', flowMediaSlideHtml(slide));
        });
        if (flowMediaSlides.length > 1) {
            track.insertAdjacentHTML('afterbegin', flowMediaSlidePreviewHtml(flowMediaSlides[flowMediaSlides.length - 1]));
            track.insertAdjacentHTML('beforeend', flowMediaSlidePreviewHtml(flowMediaSlides[0]));
        }

        track.querySelectorAll('audio[data-flow-media-key]').forEach(el => {
            el.addEventListener('play', () => stopAllFlowMediaExcept(el.dataset.flowMediaKey));
            // ML-312: the recording starts at the piece and stops when it is over
            const slide = flowMediaSlides.find(s => s.type === 'audio' && flowMediaSlideKey(s) === el.dataset.flowMediaKey);
            if (slide) keepPlayerToClip(el, () => recordingClip(slide.data));
            el.addEventListener('play', recStartTicker); // ML-488
        });
        renderRecScoreControls();

        const videoSlides = flowMediaSlides.filter(s => s.type === 'video');
        if (videoSlides.length) {
            ensureFlowYtApi().then((YT) => {
                videoSlides.forEach(slide => {
                    const id = slide.data.id;
                    const frameEl = document.getElementById(`flowYtFrame-${id}`);
                    if (!frameEl || flowYtPlayers[id]) return;
                    flowYtPlayers[id] = new YT.Player(frameEl, {
                        events: {
                            onStateChange: (e) => {
                                if (e.data !== YT.PlayerState.PLAYING) return;
                                stopAllFlowMediaExcept(`video-${id}`);
                                recStartTicker(); // ML-488
                                // ML-312: YouTube starts at the clip itself (start/end on the frame's
                                // address); this covers Play pressed after the slider was dragged outside it.
                                const clip = recordingClip(slide.data);
                                try {
                                    if ((clip.startMs || clip.endMs) && FlowJourney.clipAction(clip, e.target.getCurrentTime() * 1000, false) === 'seek') e.target.seekTo((clip.startMs || 0) / 1000, true);
                                } catch (error) { /* the player went away */ }
                            }
                        }
                    });
                });
            });
        }

        applyFlowMediaTrackPosition();
        renderFlowMediaDots();
        updateFlowMediaViewportHeight();

        if (!flowMediaSwipeWired) {
            wireFlowMediaSwipe();
            flowMediaSwipeWired = true;
        }
    }

    // The tiles, plus what the repeat control adds on top of them (ML-302).
    // Which block's tile is lit: where a recording is, when a recording's slide is showing and it has been
    // played (ML-488); otherwise where the metronome is.
    function flowActiveTileBlockId() {
        if (recScoreOn() && recActiveSlide() && recTileBlockId !== null) return recTileBlockId;
        return flowPlayQueue[flowPlayIndex] ? flowPlayQueue[flowPlayIndex].blockId : null;
    }
    // The tile that is playing is kept at the top (the owner, 12 Oct 2026): where you are and the controls
    // stay pinned under the top bar (.play-side, style.css) and, when the lit tile changes while something
    // is playing, the tiles scroll so its row is the first one under them. Never while stopped, so looking
    // around the piece isn't undone. --play-pin-h is how much of the screen the top bar and the pinned part
    // cover above the tiles (the top bar alone when the pinned part sits beside them, or isn't pinned) - a run-time value the tiles'
    // scroll-margin reads.
    function flowSetPinHeight() {
        const view = document.getElementById('flowPlayView');
        const side = document.getElementById('flowPlaySide');
        const tiles = document.getElementById('flowPlayTiles');
        if (!view || !side || !tiles) return;
        const sideBox = side.getBoundingClientRect();
        const above = getComputedStyle(side).position === 'sticky' && tiles.getBoundingClientRect().left < sideBox.right;
        const header = document.querySelector('.top-bar-sticky-group');
        view.style.setProperty('--play-pin-h', `${(header ? header.offsetHeight : 0) + (above ? Math.round(sideBox.height) : 0)}px`);
    }
    let flowLastLitTileId = null;
    function flowKeepLitTileInView() {
        const id = flowActiveTileBlockId();
        if (id === flowLastLitTileId) return;
        flowLastLitTileId = id;
        const rec = recPlayerOf(recActiveSlide());
        let playing = flowPlayer.isPlaying();
        if (!playing && rec) { try { playing = rec.playing(); } catch (error) { playing = false; } }
        if (!playing) return;
        const el = document.querySelector('#flowPlayTiles .metroBlk-tile-active, #flowPlayTiles [aria-current="true"]');
        if (!el) return;
        flowSetPinHeight();
        el.scrollIntoView({ block: 'start', inline: 'nearest', behavior: scrollMotion() });
    }
    function renderFlowPlaybackTiles() {
        renderFlowPlaybackTileList();
        markFlowLoopTiles();
        renderFlowLoopButton();
        flowKeepLitTileInView();
    }
    // ML-529: a heading over the first bar of each movement, when the piece has more than one - "Mvt 2 · Harvest".
    // It spans the whole row of tiles in every layout.
    function flowMovementHeadHtml(idx) {
        const moves = FlowJourney.movements(currentFlowBlocks);
        if (moves.length < 2) return '';
        const m = moves.find(x => x.startBlock === idx);
        if (!m) return '';
        // how long this movement takes as played, as the piece's own time does (flowPlaySeconds)
        return `<h3 class="section-title flow-movement-head">${escapeHtml(FlowJourney.movementLabel(m, false))}${m.title ? ` · ${escapeHtml(m.title)}` : ''} <span class="text-sm text-muted">${flowTimeText(flowPlaySeconds(m.number))}</span></h3>`;
    }
    function renderFlowPlaybackTileList() {
        const leadInSlot = document.getElementById('flowPlayLeadInSlot');
        const tilesUi = document.getElementById('flowPlayTiles');
        const currentId = flowActiveTileBlockId();
        // ML-113: the lead-in is the first tile in every layout, the same shape as the bars after it -
        // part of the journey, not a special row.
        if (leadInSlot) leadInSlot.innerHTML = '';
        const leadActive = !!flowLeadInBlock && flowLeadInBlock.id === currentId;
        if (tilesUi) {
            // Time signature/tempo alone didn't identify a block at a glance - every block now leads
            // with whichever of the two actually distinguishes it: its rehearsal mark in a square box,
            // or (when there isn't one) its starting bar number within the flow, plain, no box. bpm and
            // bar count drop down to supporting lines below, smallest last, same as before.
            renderFlowPlayLayoutToggle();
            const twoCol = flowPlayLayout === '2';
            const oneCol = flowPlayLayout === '1';
            tilesUi.classList.toggle('metroBlk-tile-strip', flowPlayLayout === '4');
            tilesUi.classList.toggle('flow-play-tile-strip', flowPlayLayout === '4');
            tilesUi.classList.toggle('flow-bar-grid-2', twoCol);
            tilesUi.classList.toggle('flow-bar-list-1', oneCol);
            // ML-530: with one movement chosen, only its tiles (and the lead-in only with the first)
            const only = flowChosenMovement();
            const shows = (idx) => !only || (idx >= only.startBlock && idx <= only.endBlock);
            const withLeadIn = !only || only.number === 1;
            if (oneCol) {
                tilesUi.innerHTML = (withLeadIn ? flowLeadInPlayTileHtml('1', leadActive) : '') + currentFlowBlocks.map((s, idx) => (!shows(idx) ? '' :
                    flowMovementHeadHtml(idx) + flowBarFullTileHtml(s, idx, currentFlowBlocks[idx + 1], { active: s.id === currentId }))).join('');
                return;
            }
            if (twoCol) {
                tilesUi.innerHTML = (withLeadIn ? flowLeadInPlayTileHtml('2', leadActive) : '') + currentFlowBlocks.map((s, idx) => (!shows(idx) ? '' :
                    flowMovementHeadHtml(idx) + flowBarDetailTileHtml(s, idx, currentFlowBlocks[idx + 1], { play: true, active: s.id === currentId }))).join('');
                return;
            }
            let startBar = 1;
            let leadInTile = '';
            if (flowLeadInBlock && currentFlowBlocks.length && withLeadIn) {
                const lead = flowLeadInBlock;
                const bpm = currentFlowBlocks[0].bpm; // a lead-in plays at bar 1's tempo
                leadInTile = '<div role="button" tabindex="0" class="metroBlk-tile' + (lead.id === currentId ? ' metroBlk-tile-active' : '') + '" data-block-id="' + lead.id + '" title="Lead-in, ' + bpm + ' bpm, 1 bar" aria-label="Jump to the lead-in, ' + bpm + ' bpm, 1 bar" data-act="flow-jump" data-arg="' + lead.id + '"><div class="metroBlk-tile-sig text-md">Lead&#8209;in</div><div class="metroBlk-tile-bpm">' + bpm + ' bpm</div><div class="metroBlk-tile-bars">1 bar</div></div>';
            }
            tilesUi.innerHTML = leadInTile + currentFlowBlocks.map((s, idx) => {
                const tile = flowBarSummaryTile(s, startBar);
                startBar += s.barCount || 0;
                if (!shows(idx)) return '';
                return flowMovementHeadHtml(idx) + `<div role="button" tabindex="0" class="metroBlk-tile${s.id === currentId ? ' metroBlk-tile-active' : ''}" data-block-id="${s.id}" title="${tile.name}" aria-label="Jump to ${tile.name}" data-act="flow-jump" data-arg="${s.id}">${tile.inner}</div>`;
            }).join('');
        }
    }

    // ML-209/ML-207: Play Flow's own layout switch - 1 column (every setting, flowBarFullTileHtml),
    // 2 columns (flowBarDetailTileHtml) or 4 columns (the default). Kept apart from the Bars tab's
    // flowBarLayout - the two screens show different things - and remembered per device the same way.
    const FLOW_PLAY_LAYOUT_KEY = 'flowPlayLayout';
    const FLOW_PLAY_LAYOUTS = ['1', '2', '4'];
    let flowPlayLayout = (() => {
        try {
            const saved = localStorage.getItem(FLOW_PLAY_LAYOUT_KEY);
            return FLOW_PLAY_LAYOUTS.includes(saved) ? saved : '4';
        } catch (e) { return '4'; }
    })();
    function renderFlowPlayLayoutToggle() {
        document.querySelectorAll('[data-flow-play-layout]').forEach(btn => {
            btn.setAttribute('aria-pressed', String(btn.dataset.flowPlayLayout === flowPlayLayout));
        });
    }
    document.querySelectorAll('[data-flow-play-layout]').forEach(btn => {
        btn.addEventListener('click', () => {
            if (btn.dataset.flowPlayLayout === flowPlayLayout) return;
            flowPlayLayout = btn.dataset.flowPlayLayout;
            try { localStorage.setItem(FLOW_PLAY_LAYOUT_KEY, flowPlayLayout); } catch (e) { /* not remembered - fine */ }
            renderFlowPlaybackTiles();
        });
    });

    // One bar as a compact tile: its rehearsal mark (boxed) or starting bar number, then bpm, then bar
    // count. Shared by Play Flow's tile strip (above) and the Bars tab's 4-column layout
    // (flowBarGridTileHtml, ML-206), so the two always look identical. Returns the inner markup plus
    // a plain-text name for the tile's title/aria-label.
    function flowBarSummaryTile(s, startBar) {
        // Rehearsal-mark follow-up to ML-219: a short mark ("A", "B2") keeps the big boxed
        // headline; a longer one drops to a smaller size and wraps to at most 2 lines (then "…")
        // so it can never spill out of a narrow tile in the 4-column grid. The full name is on
        // the tile's tooltip/accessible name and leads the now-playing line (flowNowPlayingLabel).
        const mark = s.rehearsalMark;
        const headline = mark
            ? `<div class="metroBlk-tile-mark-box${mark.length > 3 ? ' metroBlk-tile-mark-box-long' : ''}">${escapeHtml(mark)}</div>`
            : `<div class="metroBlk-tile-sig">${startBar}</div>`;
        const bars = `${s.barCount} bar${s.barCount === 1 ? '' : 's'}`;
        return {
            name: `${mark ? escapeHtml(mark) : `Bar ${startBar}`}, ${s.bpm} bpm, ${bars}`,
            inner: `${headline}<div class="metroBlk-tile-bpm">${s.bpm} bpm</div><div class="metroBlk-tile-bars">${bars}</div>`
        };
    }

    function renderFlowPlaybackRow() {
        if (!flowPlayQueue.length) {
            renderFlowPlaybackTiles();
            return;
        }
        const pos = flowScreenPosition();
        const block = flowPassageBlock(pos.p);
        const subFactor = flowPassageSubFactor(pos.p, block);
        const labelEl = document.getElementById('flowPlayRowLabel');
        if (labelEl) labelEl.innerHTML = flowNowPlayingLabel(); // ML-130: label carries a real fermata glyph, not plain text

        const beatsPerBar = block ? metroBlkBeatsPerBarFor(block) : 4;
        const totalBaseClicks = beatsPerBar * subFactor;
        const trackLeftPct = metroBlkLeftPctFn(totalBaseClicks + 1);
        const endLeftStyle = metroLeftStyle(trackLeftPct(totalBaseClicks));
        buildMetroDotRow('flowPlayRowDots', totalBaseClicks, subFactor, false, trackLeftPct);
        flowPlayRowClicks = totalBaseClicks + 1; // ML-600: measured again when the screen changes width
        metroApplyDisplayWidth('flowPlayRowViewport', 'flowPlayRowContent', flowPlayRowClicks);
        connectMetroBlkDotsWithTrack('flowPlayRowDots', endLeftStyle);
        greyOutSkippedDots('flowPlayRowDots', block, subFactor);
        // ML-130: NOT always the passage's first bar - a sub-beats/play-speed change mid-block
        // re-renders this row from wherever playback currently sits, so it uses the real current bar.
        if (pos.p.kind !== 'rest') renderFermataMarkers('flowPlayRowDots', block, pos.bar, subFactor);
        if (!flowPlayer.isPlaying()) resetMetroScrollPosition('flowPlayRowContent');

        renderFlowSubdivideLabel();
        renderFlowPlaybackTiles();
    }

    function updateFlowPlayIcon() {
        const el = document.getElementById('flowPlayIcon');
        if (el) el.innerText = flowPlayer.isPlaying() ? 'pause' : 'play_arrow';
        if (!flowPlayer.isPlaying()) showCountIn('flowCountIn', 0);
    }
    // ML-542: the big count-in on the play screen, Warm-ups and Scales - the beats left as a number in a ring
    // that empties beat by beat (the rest screen's ring), covering the controls but never the music. The small
    // "Get ready" line stays for screen readers. left 0 (or less) hides it.
    function showCountIn(id, left, total) {
        const el = document.getElementById(id);
        if (!el) return;
        setShown(el, left > 0);
        if (!(left > 0)) return;
        el.querySelector('.rest-ring-num strong').textContent = left;
        el.querySelector('.rest-ring').style.setProperty('--rest-left', (left / Math.max(left, total)).toFixed(4));
    }

    function playFlow() {
        if (!flowPlayQueue.length) return;
        // ML-166 "Exclusive Playback" - starting the metronome stops any audio/video slide.
        stopAllFlowMediaExcept('metronome');
        flowPlayer.play();
        window.Usage?.begin('rehearse'); // ML-22: finished at the end, or after a minute
        updateFlowPlayIcon();
        flowLastLitTileId = null; // pressing Play brings the bar that plays to the top, wherever you had scrolled to
        renderFlowPlaybackRow();
    }
    function pauseFlow() {
        flowPlayer.pause();
        window.Usage?.end('rehearse');
        updateFlowPlayIcon();
    }
    function resetFlow() {
        jumpFlowToStart();
        renderFlowPlaybackRow();
    }
    setupPlayButtonHoldReset('flowPlayBtn', () => { if (flowPlayer.isPlaying()) pauseFlow(); else playFlow(); }, resetFlow);
    document.getElementById('flowResetBtn')?.addEventListener('click', resetFlow);

    // ML-193 test hook - LOCAL DEVELOPMENT ONLY. Switched on by the back-test suite setting
    // localStorage 'tml.testClock' = '1' before the app loads, and only ever on localhost/127.0.0.1,
    // so it can never be active on sandbox or production. It puts Play Flow's player on the test
    // clock (silent, no timers) and exposes window.__flowTest to step through a Flow one click at a
    // time and read exactly what the screen shows at each step.
    (function flowTestHook() {
        let on = false;
        try { on = ['localhost', '127.0.0.1'].includes(location.hostname) && localStorage.getItem('tml.testClock') === '1'; } catch (e) { on = false; }
        if (!on) return;
        flowPlayer.setTestClock(true);
        let last = null;
        flowPlayer.onBeat(info => { last = info; });
        const text = (id) => (document.getElementById(id)?.textContent || '').replace(/\s+/g, ' ').trim();
        function snapshot() {
            const pos = flowScreenPosition();
            const p = pos && pos.p;
            const row = document.getElementById('flowPlayRowDots');
            return {
                ended: !!(last && last.ended),
                playing: flowPlayer.isPlaying(),
                passage: flowPlayIndex,
                kind: p ? p.kind : null,
                blockId: p ? p.blockId : null,
                blockIndex: p ? p.blockIndex : null,
                bar: pos ? pos.bar + 1 : null,             // 1-based bar within its block
                click: pos ? pos.clickInBar : null,        // 0-based click within that bar
                pass: p ? p.pass : null,
                via: p ? p.via : null,
                bpm: flowCurrentBpm === null ? null : Math.round(flowCurrentBpm * 100) / 100,
                time: last && typeof last.time === 'number' ? Math.round(last.time * 1000) / 1000 : null,
                intervalMs: last && last.intervalSeconds ? Math.round(last.intervalSeconds * 100000) / 100 : null,
                holding: !!(last && last.fermataHold),
                holdRemaining: last && last.fermataHold ? last.fermataHold.remaining : null,
                label: text('flowPlayRowLabel'),
                activeTiles: [...document.querySelectorAll('#flowPlayTiles .metroBlk-tile-active, #flowPlayLeadInSlot .metroBlk-tile-active')].map(el => Number(el.dataset.blockId)),
                markers: row ? [...row.querySelectorAll('.metro-fermata-marker')].map(m => m.dataset.kind) : [],
                dotCount: row ? row.querySelectorAll('.metro-dot').length : 0
            };
        }
        window.__flowTest = {
            // For the back-tests' own setup: the app's API client (seeding Flows as the logged-in test
            // account, through the same validation as the editor), and the two screens they drive.
            api: API,
            call: apiCall, // ML-489: any endpoint, as the signed-in test account (the Recordings tool has no entry in API)
            openPlay: (id) => goToFlowPlayView(id),
            // ML-302: repeat bars on ({ startBar, endBar, restBars }) or off (null), as the sheet does.
            setLoop: (settings) => { applyFlowLoop(settings ? { restBars: 0, ...settings } : null); return snapshot(); },
            setMovement: (n) => { setFlowMovement(n || null); return snapshot(); }, // ML-530
            // The bars as the editor currently holds them (staged, in Edit mode) - what a picker just set.
            blocks: () => JSON.parse(JSON.stringify({ leadIn: flowLeadInBlock, blocks: currentFlowBlocks })),
            // ML-557: a piece's path, and a practice list
            openPath: (id, opts) => openPiecePath(id, opts),
            openList: (id) => openPracticeList(id),
            openBars: (id, mode = 'edit') => { currentFlowId = id; flowEditMode = mode; flowEditRequestedTab = 'blocks'; switchView('flowDetailsHubView'); },
            journey: () => JSON.parse(JSON.stringify({ end: flowJourney.end, steps: flowJourney.steps, passages: flowPlayQueue.map(({ block, ...rest }) => rest) })),
            issues: () => JSON.parse(JSON.stringify(FlowJourney.checkFlow(currentFlowBlocks, { leadIn: flowLeadInBlock }))),
            play: () => { if (!flowPlayer.isPlaying()) playFlow(); return snapshot(); },
            state: snapshot,
            step(n = 1) {
                const out = [];
                for (let k = 0; k < n; k++) {
                    const info = flowPlayer.testStep();
                    if (!info) break;
                    out.push(snapshot());
                    if (info.ended) break;
                }
                return out;
            },
            // Every click to the end of the piece, as compact rows (capped so a runaway can't hang a test).
            runToEnd(max = 20000) {
                const out = [];
                for (let k = 0; k < max; k++) {
                    const info = flowPlayer.testStep();
                    if (!info) break;
                    const s = snapshot();
                    out.push({ passage: s.passage, kind: s.kind, blockId: s.blockId, bar: s.bar, click: s.click, pass: s.pass, bpm: s.bpm, time: s.time, holding: s.holding, ended: s.ended });
                    if (info.ended) break;
                }
                return out;
            }
        };
    })();

    // --- Sub-beats popup ("ported" from Quick Play's own qpSubdivideModal - own state, own modal,
    // same reasoning as flowPlayer being its own player instance) ---
    const FLOW_SUBDIVIDE_MIN = 2;
    const FLOW_SUBDIVIDE_MAX = 16;
    let flowSubdividePopupValue = FLOW_SUBDIVIDE_MIN;

    function flowSubdivideCurrentBlock() {
        return flowPlayQueue.length ? flowPassageBlock(flowPlayQueue[flowPlayIndex]) : null;
    }
    function renderFlowSubdivideLabel() {
        const block = flowSubdivideCurrentBlock();
        const lbl = document.getElementById('flowSubdivideLbl');
        if (lbl) lbl.innerText = metroBlkSubdivideDisplayValue(block ? flowSubFactorFor(block) : 1);
        const unitLbl = document.getElementById('flowSubdivideUnitLbl');
        if (unitLbl) unitLbl.innerText = flowSubBeatsMode === 'auto' ? 'auto sub beats' : 'sub beats';
    }
    function renderFlowSubdividePopupSlider() {
        const pct = ((flowSubdividePopupValue - FLOW_SUBDIVIDE_MIN) / (FLOW_SUBDIVIDE_MAX - FLOW_SUBDIVIDE_MIN)) * 100;
        document.getElementById('flowSubdivideSliderFill').style.setProperty('--pct', `${pct}%`);
        const thumb = document.getElementById('flowSubdivideSliderThumb');
        thumb.style.setProperty('--pct', `${pct}%`);
        thumb.setAttribute('aria-valuenow', flowSubdividePopupValue);
        thumb.setAttribute('aria-valuemax', FLOW_SUBDIVIDE_MAX);
        document.getElementById('flowSubdivideSliderMaxLbl').innerText = FLOW_SUBDIVIDE_MAX;
        document.getElementById('flowSubdividePopupValue').innerText = flowSubdividePopupValue;
    }
    function setFlowSubdividePopupValue(v) {
        flowSubdividePopupValue = Math.min(FLOW_SUBDIVIDE_MAX, Math.max(FLOW_SUBDIVIDE_MIN, Math.round(v)));
        renderFlowSubdividePopupSlider();
    }
    setupHoldStepper(document.getElementById('flowSubdivideMinus'), -1, (amount) => setFlowSubdividePopupValue(flowSubdividePopupValue + amount));
    setupHoldStepper(document.getElementById('flowSubdividePlus'), 1, (amount) => setFlowSubdividePopupValue(flowSubdividePopupValue + amount));
    setupSliderInteraction(document.getElementById('flowSubdivideSliderTrack'), document.getElementById('flowSubdivideSliderThumb'), {
        onDragRatio: (ratio) => setFlowSubdividePopupValue(FLOW_SUBDIVIDE_MIN + ratio * (FLOW_SUBDIVIDE_MAX - FLOW_SUBDIVIDE_MIN)),
        onArrowStep: (dir) => setFlowSubdividePopupValue(flowSubdividePopupValue + dir)
    });
    makeSliderReadoutEditable('flowSubdividePopupValue', () => flowSubdividePopupValue, (v) => setFlowSubdividePopupValue(v), { label: 'Sub beats', min: FLOW_SUBDIVIDE_MIN, max: FLOW_SUBDIVIDE_MAX });

    document.getElementById('flowSubdivideBtn')?.addEventListener('click', () => {
        // ML-588: in a practice that still follows the Level ('session'), it opens on what's playing - Auto or Off
        const sessionOn = flowSubBeatsMode === 'session' && flowSessionSubBeatsOn();
        document.getElementById('flowSubdivideOff').checked = flowSubBeatsMode === 'off' || (flowSubBeatsMode === 'session' && !sessionOn);
        document.getElementById('flowSubdivideAuto').checked = flowSubBeatsMode === 'auto' || sessionOn;
        document.getElementById('flowSubdivideFixed').checked = flowSubBeatsMode === 'fixed';
        document.getElementById('flowSubdivideBpmBox').classList.toggle('hidden-group', flowSubBeatsMode !== 'fixed');
        setFlowSubdividePopupValue(flowSubdivideOverride || FLOW_SUBDIVIDE_MIN);
        showModal('flowSubdivideModal');
    });
    document.querySelectorAll('input[name="flowSubdivideOnOff"]').forEach(radio => {
        radio.addEventListener('change', () => {
            document.getElementById('flowSubdivideBpmBox').classList.toggle('hidden-group', radio.value !== 'fixed');
        });
    });
    document.getElementById('flowSubdivideCancelBtn')?.addEventListener('click', () => {
        hideModal('flowSubdivideModal');
    });
    document.getElementById('flowSubdivideSaveBtn')?.addEventListener('click', () => {
        flowSubBeatsMode = document.querySelector('input[name="flowSubdivideOnOff"]:checked')?.value || 'off';
        flowSubdivideOverride = flowSubBeatsMode === 'fixed' ? flowSubdividePopupValue : null;
        hideModal('flowSubdivideModal');
        // ML-193: sub-beats change how many clicks each bar has, so the current passage is restarted
        // from the bar it's on, in the new click grid.
        const pos = flowScreenPosition();
        if (pos) flowStartSequenceAt(flowPlayIndex, pos.bar - pos.p.fromBar);
        renderFlowPlaybackRow();
        renderFlowSubdivideLabel();
    });

    // --- Repeat bars (ML-302) ---
    // A playback setting, not part of the piece: plays a start..end bar range over and over, with 0-5
    // quietly clicking rest bars between passes (and as a count-in before the first). What plays comes
    // from FlowJourney.loopPlan, so repeats and jumps inside the range still apply and the end bar can
    // be before the start bar. Remembered per piece on this device (tml.rehearseRepeat), on or off.
    const FLOW_LOOP_KEY = 'tml.rehearseRepeat';
    const FLOW_LOOP_MAX_REST = 5;
    let flowLoop = null;       // { startBar, endBar, restBars } while repeating, else null
    let flowLoopPlan = null;   // FlowJourney.loopPlan(...) for flowLoop - set only when it's playable
    let flowLoopPassCount = 1; // passes queued so far ("Repeat N")
    let flowLoopDraft = null;  // the sheet's unsaved settings

    // The piece Rehearse has open (goToFlowPlayView sets currentFlowDetail, not currentFlowId).
    function flowLoopPieceKey() {
        return String(currentFlowDetail ? currentFlowDetail.id : currentFlowId);
    }
    function flowLoopSavedAll() {
        try { return JSON.parse(localStorage.getItem(FLOW_LOOP_KEY) || '{}') || {}; } catch (e) { return {}; }
    }
    function flowLoopRemember(settings) {
        try {
            const all = flowLoopSavedAll();
            all[flowLoopPieceKey()] = settings;
            localStorage.setItem(FLOW_LOOP_KEY, JSON.stringify(all));
        } catch (e) { /* not remembered - fine */ }
    }
    function flowLoopOpts(settings) {
        return { startBar: settings.startBar, endBar: settings.endBar, restBars: settings.restBars, countInBars: flowSession ? practiceCountInBars() : undefined, leadIn: flowLeadInBlock, movement: flowMovementNow() };
    }

    // --- ML-530: one movement on its own. A piece in movements can play just one of them: the Movement value
    // box by the layout switch, one pop-up (the whole piece, or each movement). Remembered per piece on this
    // device (tml.rehearseMovement), like the repeat. Only that movement's tiles show, the repeat bars stay
    // inside it, and the end of it is the end. Never in a practice or a run-through - those have their own bars.
    const FLOW_MOVEMENT_KEY = 'tml.rehearseMovement';
    let flowMovement = null; // the movement number chosen for the open piece, or null for the whole piece
    function flowMovementSavedAll() {
        try { return JSON.parse(localStorage.getItem(FLOW_MOVEMENT_KEY) || '{}') || {}; } catch (e) { return {}; }
    }
    function flowLoadMovementForPiece() {
        const n = flowMovementSavedAll()[flowLoopPieceKey()];
        const moves = FlowJourney.movements(currentFlowBlocks);
        flowMovement = moves.length > 1 && moves.some(m => m.number === n) ? n : null;
    }
    // A practice has its own bars; a run-through of one movement (Prepare on a movement's path) plays just that movement
    const flowMovementNow = () => (flowSession ? (flowSession.mode === 'runthrough' && flowSession.chunk.movement) || null : flowMovement);
    function flowChosenMovement() {
        const n = flowMovementNow();
        return n ? FlowJourney.movements(currentFlowBlocks).find(m => m.number === n) || null : null;
    }
    function renderFlowMovementButton() {
        const btn = document.getElementById('flowMovementBtn');
        if (!btn) return;
        const moves = FlowJourney.movements(currentFlowBlocks);
        setShown(btn, moves.length > 1 && !flowSession);
        const m = flowChosenMovement();
        document.getElementById('flowMovementLbl').textContent = m ? String(m.number) : 'all';
        btn.setAttribute('aria-label', m ? `Movement: ${FlowJourney.movementLabel(m, true)}. Tap to choose another` : 'Movement: the whole piece. Tap to choose one');
    }
    function setFlowMovement(n) {
        try {
            const all = flowMovementSavedAll();
            if (n) all[flowLoopPieceKey()] = n; else delete all[flowLoopPieceKey()];
            localStorage.setItem(FLOW_MOVEMENT_KEY, JSON.stringify(all));
        } catch (e) { /* not remembered - fine */ }
        flowMovement = n;
        buildFlowPlayQueue();
        renderFlowPlaybackRow();
        buildFlowMediaSlides(); // ML-531: the recordings offered follow the movement
        renderFlowMediaCarousel();
    }
    function openFlowMovementChoice() {
        const moves = FlowJourney.movements(currentFlowBlocks);
        openFlowChoiceModal('Which movement?', [
            { n: null, selected: !flowMovement, html: addPieceRow('The whole piece', `All ${moves.length} movements, one after another`) },
            ...moves.map(m => ({ n: m.number, selected: flowMovement === m.number, html: addPieceRow(FlowJourney.movementLabel(m, true), m.startBar === m.endBar ? `Bar ${m.startBar}` : `Bars ${m.startBar}-${m.endBar}`) }))
        ], (opt) => setFlowMovement(opt.n));
    }
    document.getElementById('flowMovementBtn')?.addEventListener('click', openFlowMovementChoice);
    // The bars the repeat sheet offers: the chosen movement's, or the whole piece's.
    function flowLoopBounds() {
        const m = flowChosenMovement();
        return m ? { lo: m.startBar, hi: m.endBar } : { lo: 1, hi: flowLoopTotalBars() };
    }
    // Recomputes the plan for flowLoop - drops the repeat if the piece has changed so it no longer fits.
    function flowComputeLoopPlan() {
        flowLoopPlan = null;
        if (!flowLoop) return;
        const plan = FlowJourney.loopPlan(currentFlowBlocks, flowLoopOpts(flowLoop));
        if (plan.ok) flowLoopPlan = plan;
        else flowLoop = null;
    }
    function flowLoadLoopForPiece() {
        const saved = flowLoopSavedAll()[flowLoopPieceKey()];
        flowLoop = saved && saved.on ? { startBar: saved.startBar, endBar: saved.endBar, restBars: saved.restBars || 0 } : null;
        // ML-317: a practice loops its chunk with one gap bar between runs (what the chunk length rule
        // assumes) - never saved over the piece's own repeat setting. ML-587: or the count-in again, when it comes
        // every time round.
        // ML-390: a run-through plays the whole piece once - no loop.
        if (flowSession && flowSession.flowId === Number(flowLoopPieceKey())) flowLoop = flowSession.mode === 'runthrough' ? null : { startBar: flowSession.chunk.startBar, endBar: flowSession.chunk.endBar, restBars: practiceGapBars() };
        flowComputeLoopPlan();
    }
    function flowPassagesFor(steps, loopPass) {
        let restIndex = 0;
        return FlowJourney.passagesOf(steps).map(p => ({
            ...p, block: p.kind === 'leadIn' ? flowLeadInBlock : currentFlowBlocks[p.blockIndex],
            loopPass, restIndex: p.kind === 'rest' ? restIndex++ : null
        }));
    }
    // Back to the start: the piece, or the loop's first pass (count-in included).
    function flowResetPlayQueue() {
        flowLoopPassCount = 1;
        const countIn = flowSession && flowSession.mode === 'runthrough' ? FlowJourney.countInSteps(flowJourney.steps, practiceCountInBars()) : [];
        flowPlayQueue = flowLoopPlan ? flowPassagesFor(flowLoopPlan.countIn, 1) : flowPassagesFor([...countIn, ...flowJourney.steps], null);
    }
    function flowAppendLoopPass() {
        flowLoopPassCount++;
        flowPlayQueue.push(...flowPassagesFor(flowLoopPlan.between, flowLoopPassCount));
    }
    // "Bars 5-12", or "Bars 7-8 and 1-2" when the loop goes back on itself.
    function flowLoopRunsText(runs) {
        const run = ([a, b]) => (a === b ? `${a}` : `${a}–${b}`);
        if (runs.length === 1 && runs[0][0] === runs[0][1]) return `Bar ${runs[0][0]}`;
        return `Bars ${runs.map(run).join(' and ')}`;
    }
    function flowLoopRangeText() {
        return flowLoopPlan ? flowLoopRunsText(flowLoopPlan.runs) : '';
    }

    // The repeat box's value: "21–30", or - when the bar numbers are too long for the box (101–124) - smaller, the two
    // numbers on two lines (ML-550).
    function setLoopLabel(lbl, on) {
        const text = on ? `${flowLoop.startBar}–${flowLoop.endBar}` : 'off';
        const twoLines = on && text.length > 5;
        lbl.classList.toggle('is-two-line', twoLines);
        if (twoLines) lbl.replaceChildren(document.createTextNode(`${flowLoop.startBar}–`), document.createElement('br'), document.createTextNode(String(flowLoop.endBar)));
        else lbl.textContent = text;
    }
    function renderFlowLoopButton() {
        renderRecScoreControls(); // ML-488: a recording's slide shows the same repeat
        const btn = document.getElementById('flowLoopBtn');
        const lbl = document.getElementById('flowLoopLbl');
        if (!btn || !lbl) return;
        const on = !!flowLoopPlan;
        setLoopLabel(lbl, on);
        btn.classList.toggle('metroBlk-ctrl-value-btn-on', on);
        btn.setAttribute('aria-label', on
            ? `Repeat bars - ${flowLoopRangeText()}${flowLoop.restBars ? `, ${flowLoop.restBars} rest bar${flowLoop.restBars === 1 ? '' : 's'}` : ''}. Tap to change`
            : 'Repeat bars - off. Tap to set up');
    }
    // A dashed outline on the tiles the loop plays (tiles are blocks, so a block partly in the range
    // is outlined too).
    function markFlowLoopTiles() {
        const ids = new Set(flowLoopPlan ? flowLoopPlan.body.map(s => String(s.blockId)) : []);
        document.querySelectorAll('#flowPlayTiles [data-block-id]').forEach(el => {
            el.classList.toggle('flow-tile-in-repeat', ids.has(el.dataset.blockId));
        });
    }

    function applyFlowLoop(settings) {
        flowLoop = settings;
        flowComputeLoopPlan();
        const resumeBlockId = !flowLoopPlan && flowPlayQueue[flowPlayIndex] ? flowPlayQueue[flowPlayIndex].blockId : null;
        jumpFlowToStart();
        // Turning it off carries on from the bar you were on rather than the top of the piece.
        if (resumeBlockId !== null && currentFlowBlocks.some(b => b.id === resumeBlockId)) window.jumpFlowToPlayIndex(resumeBlockId);
        renderFlowPlaybackRow();
    }

    // The sheet.
    function flowLoopTotalBars() {
        return FlowJourney.totalBars(currentFlowBlocks);
    }
    function renderFlowLoopModal() {
        const d = flowLoopDraft;
        const { lo, hi: total } = flowLoopBounds();
        document.getElementById('flowLoopStartValue').innerText = `Bar ${d.startBar}`;
        document.getElementById('flowLoopEndValue').innerText = `Bar ${d.endBar}`;
        document.getElementById('flowLoopStartMinus').disabled = d.startBar <= lo;
        document.getElementById('flowLoopStartPlus').disabled = d.startBar >= total;
        document.getElementById('flowLoopEndMinus').disabled = d.endBar <= lo;
        document.getElementById('flowLoopEndPlus').disabled = d.endBar >= total;
        // The sliders under the steppers - a piece can have hundreds of bars.
        [['Start', d.startBar], ['End', d.endBar]].forEach(([key, bar]) => {
            const pct = total > lo ? ((bar - lo) / (total - lo)) * 100 : 0;
            document.getElementById(`flowLoop${key}MinLbl`).innerText = lo;
            document.getElementById(`flowLoop${key}SliderThumb`).setAttribute('aria-valuemin', lo);
            document.getElementById(`flowLoop${key}SliderFill`).style.setProperty('--pct', `${pct}%`);
            const thumb = document.getElementById(`flowLoop${key}SliderThumb`);
            thumb.style.setProperty('--pct', `${pct}%`);
            thumb.setAttribute('aria-valuemax', total);
            thumb.setAttribute('aria-valuenow', bar);
            thumb.setAttribute('aria-valuetext', `Bar ${bar}`);
            document.getElementById(`flowLoop${key}MaxLbl`).innerText = total;
        });
        const plan = FlowJourney.loopPlan(currentFlowBlocks, flowLoopOpts(d));
        const preview = document.getElementById('flowLoopPreview');
        if (plan.ok) {
            const parts = plan.runs.map(([a, b]) => (a === b ? `${a}` : `${a}–${b}`));
            preview.innerText = `Plays ${plan.runs.length > 1 ? 'bars ' : (parts[0].includes('–') ? 'bars ' : 'bar ')}${parts.join(', then ')}${d.restBars ? `, then ${d.restBars} rest bar${d.restBars === 1 ? '' : 's'}` : ''}, over and over.`;
        } else if (plan.reason === 'outsideMovement') {
            preview.innerText = `${FlowJourney.movementLabel(plan.movement, false)} is bars ${plan.movement.startBar} to ${plan.movement.endBar} - pick bars in it.`;
        } else if (plan.reason === 'endNotReached') {
            preview.innerText = `Bar ${d.endBar} doesn't come after bar ${d.startBar} in this piece. Pick a later end bar, or one that a repeat or jump goes back to.`;
        } else {
            preview.innerText = `Bar ${d.startBar} never plays in this piece - pick another start bar.`;
        }
        const grid = document.getElementById('flowLoopRestGrid');
        grid.innerHTML = Array.from({ length: FLOW_LOOP_MAX_REST + 1 }, (_, n) =>
            `<button type="button" class="flow-multiselect-num${d.restBars === n ? ' selected' : ''}" data-rest="${n}" aria-pressed="${d.restBars === n}">${n === 0 ? 'None' : n}</button>`).join('');
    }
    function openFlowLoopModal() {
        const { lo, hi: total } = flowLoopBounds();
        if (!total) return;
        const saved = flowLoopSavedAll()[flowLoopPieceKey()];
        let draft = flowLoop || (saved ? { startBar: saved.startBar, endBar: saved.endBar, restBars: saved.restBars || 0 } : null);
        if (!draft) {
            // First time: start at the bar on screen (or bar 1), four bars long.
            const p = flowPlayQueue[flowPlayIndex];
            const pos = flowScreenPosition();
            const start = p && p.kind === 'main' && pos ? FlowJourney.barNumberOf(currentFlowBlocks, p.blockIndex, pos.bar) : lo;
            draft = { startBar: start, endBar: Math.min(total, start + 3), restBars: 0 };
        }
        flowLoopDraft = {
            startBar: Math.min(total, Math.max(lo, draft.startBar)),
            endBar: Math.min(total, Math.max(lo, draft.endBar)),
            restBars: Math.min(FLOW_LOOP_MAX_REST, Math.max(0, draft.restBars || 0))
        };
        document.getElementById('flowLoopOffBtn').innerText = flowLoopPlan ? 'Turn off' : 'Cancel';
        renderFlowLoopModal();
        showModal('flowLoopModal');
        document.getElementById('flowLoopBtn')?.setAttribute('aria-expanded', 'true');
    }
    function closeFlowLoopModal() {
        hideModal('flowLoopModal');
        const btn = document.getElementById('flowLoopBtn');
        btn?.setAttribute('aria-expanded', 'false');
        btn?.focus();
    }
    function setFlowLoopDraftBar(key, value) {
        if (!flowLoopDraft) return;
        const { lo, hi: total } = flowLoopBounds();
        const before = flowLoopDraft[key];
        flowLoopDraft[key] = Math.min(total, Math.max(lo, Math.round(value)));
        // Moving the start past the end drags the end along (it can still be set earlier afterwards).
        if (key === 'startBar' && flowLoopDraft.startBar > before && flowLoopDraft.endBar < flowLoopDraft.startBar) flowLoopDraft.endBar = flowLoopDraft.startBar;
        renderFlowLoopModal();
    }
    function stepFlowLoopDraft(key, amount) {
        if (flowLoopDraft) setFlowLoopDraftBar(key, flowLoopDraft[key] + amount);
    }
    document.getElementById('flowLoopBtn')?.addEventListener('click', openFlowLoopModal);
    setupHoldStepper(document.getElementById('flowLoopStartMinus'), -1, (amount) => stepFlowLoopDraft('startBar', amount));
    setupHoldStepper(document.getElementById('flowLoopStartPlus'), 1, (amount) => stepFlowLoopDraft('startBar', amount));
    setupHoldStepper(document.getElementById('flowLoopEndMinus'), -1, (amount) => stepFlowLoopDraft('endBar', amount));
    setupHoldStepper(document.getElementById('flowLoopEndPlus'), 1, (amount) => stepFlowLoopDraft('endBar', amount));
    [['Start', 'startBar', 'Start bar'], ['End', 'endBar', 'End bar']].forEach(([key, field, label]) => {
        setupSliderInteraction(document.getElementById(`flowLoop${key}SliderTrack`), document.getElementById(`flowLoop${key}SliderThumb`), {
            onDragRatio: (ratio) => { const { lo, hi } = flowLoopBounds(); setFlowLoopDraftBar(field, lo + ratio * (hi - lo)); },
            onArrowStep: (dir) => stepFlowLoopDraft(field, dir)
        });
        // Tap the "Bar 12" readout to type a bar number.
        makeSliderReadoutEditable(`flowLoop${key}Value`, () => (flowLoopDraft ? flowLoopDraft[field] : 1), (v) => setFlowLoopDraftBar(field, v), { label, min: 1 });
    });
    document.getElementById('flowLoopRestGrid')?.addEventListener('click', (e) => {
        const btn = e.target.closest('[data-rest]');
        if (!btn) return;
        flowLoopDraft.restBars = Number(btn.dataset.rest);
        renderFlowLoopModal();
    });
    document.getElementById('flowLoopCloseBtn')?.addEventListener('click', closeFlowLoopModal);
    document.getElementById('flowLoopOffBtn')?.addEventListener('click', () => {
        if (flowLoopPlan) {
            flowLoopRemember({ ...flowLoop, on: false });
            applyFlowLoop(null);
        }
        closeFlowLoopModal();
    });
    document.getElementById('flowLoopSaveBtn')?.addEventListener('click', () => {
        const d = flowLoopDraft;
        const plan = FlowJourney.loopPlan(currentFlowBlocks, flowLoopOpts(d));
        if (!plan.ok) {
            showWarningToast(plan.reason === 'outsideMovement' ? `Pick bars in ${FlowJourney.movementLabel(plan.movement, false)} - bars ${plan.movement.startBar} to ${plan.movement.endBar}.`
                : plan.reason === 'endNotReached' ? `Bar ${d.endBar} doesn't come after bar ${d.startBar} - pick another end bar.` : `Bar ${d.startBar} never plays - pick another start bar.`);
            return;
        }
        flowLoopRemember({ ...d, on: true });
        applyFlowLoop({ ...d });
        closeFlowLoopModal();
    });

    // --- Play speed popup ("ported" from Quick Play's own - own state, admin-managed preset list) ---
    let flowSpeedPercent = 100;
    function renderFlowSpeedLabel() {
        document.getElementById('flowSpeedLbl').innerText = `${flowSpeedPercent}%`;
    }
    function setFlowSpeedPercent(p) {
        flowSpeedPercent = Math.min(1000, Math.max(1, p));
        flowPlayer.setSpeedPercent(flowSpeedPercent);
        renderFlowSpeedLabel(); // the player applies play speed to every click's own tempo - nothing to reconfigure
        renderFlowPlaybackRow();
        recApplySpeed(); // ML-599: a recording follows the same speed
    }
    // ML-596: the app's one list of play speeds (Admin -> Playback speeds) - the metronome, a practice's Custom speed
    // (ML-588), a recording or video (ML-599) and Warm-ups all offer it. Until it has loaded, or offline, the list as
    // seeded (migrations 025 and 151) - nothing keeps a list of its own.
    const DEFAULT_PLAY_SPEEDS = [30, 40, 50, 60, 70, 75, 80, 90, 100, 110, 120, 125, 130, 140, 150];
    let flowPlaybackSpeeds = [];
    const playSpeedChoices = () => (flowPlaybackSpeeds.length ? flowPlaybackSpeeds : DEFAULT_PLAY_SPEEDS);
    async function ensurePlaySpeeds() {
        if (!flowPlaybackSpeeds.length) { try { flowPlaybackSpeeds = await API.metronomeBlocks.playbackSpeeds.list(); } catch (e) { /* the seeded list stands in */ } }
        return playSpeedChoices();
    }
    async function loadFlowPlaybackSpeeds() {
        try {
            const speeds = await API.metronomeBlocks.playbackSpeeds.list();
            flowPlaybackSpeeds = speeds;
            const container = document.getElementById('flowSpeedOptions');
            if (container) container.innerHTML = speeds.map(p => `<button type="button" class="metroBlk-timesig-opt" data-value="${p}">${p}%</button>`).join('');
            document.querySelectorAll('#flowSpeedOptions .metroBlk-timesig-opt').forEach(btn => {
                btn.classList.toggle('selected', Number(btn.dataset.value) === flowSpeedPercent);
            });
        } catch (error) {
            showWarningToast('Error loading playback speeds: ' + error.message);
        }
    }
    document.getElementById('flowSpeedBtn')?.addEventListener('click', () => {
        document.querySelectorAll('#flowSpeedOptions .metroBlk-timesig-opt').forEach(btn => {
            btn.classList.toggle('selected', Number(btn.dataset.value) === flowSpeedPercent);
        });
        showModal('flowSpeedModal');
    });
    document.getElementById('flowSpeedOptions')?.addEventListener('click', (e) => {
        const btn = e.target.closest('.metroBlk-timesig-opt');
        if (!btn) return;
        setFlowSpeedPercent(Number(btn.dataset.value));
        hideModal('flowSpeedModal');
    });
    renderFlowSpeedLabel();

    // --- Volume ("ported" from Quick Play's own - own state, no calibration section, headphone
    // delay is the one shared setting via metroState.latencyMs/flowPlayerRef). Mute is just volume 0,
    // flowVolumeBeforeMute remembers the last non-zero value so unmuting restores it. ---
    let flowVolume = 80;
    let flowVolumeBeforeMute = 80;
    function renderFlowVolumeSlider() {
        const fill = document.getElementById('flowVolumeFill');
        const thumb = document.getElementById('flowVolumeThumb');
        if (!fill || !thumb) return;
        fill.style.setProperty('--pct', `${flowVolume}%`);
        thumb.style.setProperty('--pct', `${flowVolume}%`);
        thumb.setAttribute('aria-valuenow', flowVolume);
        const valueEl = document.getElementById('flowVolumeValue');
        if (valueEl) valueEl.innerText = `${flowVolume}%`;
        const muted = flowVolume === 0;
        document.getElementById('flowMuteIcon').innerText = muted ? 'volume_off' : 'volume_up';
        document.getElementById('flowMuteBtn')?.setAttribute('aria-pressed', String(muted));
        document.getElementById('flowVolumeRow')?.classList.toggle('is-muted', muted);
    }
    function setFlowVolume(v, force = false) {
        flowVolume = Math.round(Math.min(100, Math.max(0, v)));
        if (flowVolume > 0) flowVolumeBeforeMute = flowVolume;
        flowPlayer.setVolume(flowVolume / 100);
        renderFlowVolumeSlider();
        playVolumeTestClick(flowPlayer, force);
    }
    setupSliderInteraction(document.getElementById('flowVolumeTrack'), document.getElementById('flowVolumeThumb'), {
        onDragRatio: (ratio) => setFlowVolume(ratio * 100),
        onArrowStep: (dir) => setFlowVolume(flowVolume + dir * 5),
        onRelease: () => playVolumeTestClick(flowPlayer, true)
    });
    setupHoldStepper('flowVolumeMinus', -1, (amount) => setFlowVolume(flowVolume + amount, true));
    setupHoldStepper('flowVolumePlus', 1, (amount) => setFlowVolume(flowVolume + amount, true));
    makeSliderReadoutEditable('flowVolumeValue', () => flowVolume, (v) => setFlowVolume(v, true), { label: 'Volume', min: 0, max: 100 });
    document.getElementById('flowMuteBtn')?.addEventListener('click', () => {
        setFlowVolume(flowVolume > 0 ? 0 : (flowVolumeBeforeMute || 80), true);
    });
    document.getElementById('flowVolumeBtn')?.addEventListener('click', () => {
        renderFlowVolumeSlider();
        showModal('flowVolumeModal');
    });
    function closeFlowVolumePopup() {
        hideModal('flowVolumeModal');
    }
    document.getElementById('flowVolumeCloseBtn')?.addEventListener('click', closeFlowVolumePopup);
    document.getElementById('flowVolumeModal')?.addEventListener('click', (e) => {
        if (e.target === e.currentTarget) closeFlowVolumePopup();
    });
    renderFlowVolumeSlider();

    // --- Play Flow's own 3-dot menu (Edit details / Edit bars - ML-217: it opens the Bars tab) - replaces Quick Play's static
    // "Bars" title's Show history/Create flow links. Bare .dropdown-menu, same "only ever one
    // instance on screen" precedent as elsewhere in the app (e.g. the burger menu). Both items land
    // on the same Edit Flow view (Details/Media/Blocks tabs) now, just on a different starting tab -
    // see flowEditRequestedTab. ---
    function closeFlowPlayMenu() {
        document.getElementById('flowPlayMenu')?.classList.remove('show');
    }
    document.addEventListener('click', closeFlowPlayMenu);
    document.getElementById('flowPlayMenuBtn')?.addEventListener('click', (e) => {
        e.stopPropagation();
        document.getElementById('flowPlayMenu')?.classList.toggle('show');
    });
    document.getElementById('flowPlayMenuEditDetails')?.addEventListener('click', (e) => {
        e.stopPropagation();
        closeFlowPlayMenu();
        if (!currentFlowId) return;
        flowEditRequestedTab = 'details';
        flowEditMode = 'edit';
        switchView('flowDetailsHubView');
    });
    document.getElementById('flowPlayMenuEditFlow')?.addEventListener('click', (e) => {
        e.stopPropagation();
        closeFlowPlayMenu();
        if (!currentFlowId) return;
        flowEditRequestedTab = 'blocks';
        flowEditMode = 'edit';
        switchView('flowDetailsHubView');
    });
    document.getElementById('flowPlayMenuCopy')?.addEventListener('click', async (e) => {
        e.stopPropagation();
        closeFlowPlayMenu();
        if (currentFlowId) await copyFlowToMyLibrary(currentFlowId);
    });
    // ML-299: the pieces to play are Rehearse's list now (the library with create/import is My music).
    document.getElementById('flowPlayMenuLoadLibrary')?.addEventListener('click', (e) => {
        e.stopPropagation();
        closeFlowPlayMenu();
        switchView('rehearseView');
    });
    document.getElementById('flowPlayMenuCreateNew')?.addEventListener('click', (e) => {
        e.stopPropagation();
        closeFlowPlayMenu();
        switchView('addPieceView'); // ML-400
    });

    // ML-103: the old "+ Add new" button (a second, name-prompt-first "new setup" path alongside
    // the implicit scratch-on-visit) is retired - "Create your own" on the entry screen is now the
    // one, single way to start a new setup (metroBlkEntryCreateBtn above). createNamedAdhocSetup
    // stays in the backend/API client unused rather than deleted, in case a genuinely separate
    // "start a second new one without touching my in-progress scratch" need comes up later.

    // --- Build panel: block tiles ---
    // `beatsPlayedInBlock` (metroBlkBeatsPlayedInBlock) is only meaningful for whichever block is
    // actually current - pass it for that one row only, so a repeating block shows "x of y bars"
    // (or "x of y beats" for a partial lead-in) as it plays; omit it for upcoming-row previews,
    // which just show the plain total since they haven't started.
    // ML-172: bar identification leads now (which block/lead-in this is matters more at a glance than
    // the time signature/tempo that follow it), then time signature, then bpm - same reorder as
    // qpBlockLabel's own.
    // ML-130: the fermata glyph (+ ×N once there's more than one) appended to the "now playing"
    // label - counted across the WHOLE block, not just whichever bar is currently playing, since the
    // fermatas themselves are block-scoped data (two different bars of the same block can each carry
    // one, and that's still just "this block has 2"). Caesura is a separate follow-up, not counted
    // here yet. Returns '' (not undefined) when the block has none, so callers can always just
    // concatenate it straight onto the rest of the label.
    function metroBlkFermataLabelSuffix(block) {
        const count = (block.fermatas || []).filter(f => f.kind !== 'caesura').length;
        if (!count) return '';
        return ` · ${flowPauseIconSvg('fermata', true)}${count > 1 ? `×${count}` : ''}`;
    }

    // A lead-in no longer carries its own time signature/bpm (ML-35 follow-up - see the note on
    // removed Metronome Blocks lead-in editor) - it always inherits them from whichever segment is currently the
    // first regular (non-lead-in) block. Resolves that "effective" view for display/playback;
    // everything else about the lead-in (isLeadIn, barCount/pickupBeats) is unchanged. `segments`
    // is whichever array is authoritative for the caller's context - [leadIn, ...currentFlowBlocks]
    // for Rehearse.
    function metroBlkEffectiveBlock(block, segments) {
        if (!block || !block.isLeadIn) return block;
        const firstRegular = segments.find(s => !s.isLeadIn);
        if (!firstRegular) return block;
        return { ...block, bpm: firstRegular.bpm, numerator: firstRegular.numerator, denominator: firstRegular.denominator, timeSignatureLabel: firstRegular.timeSignatureLabel };
    }

    // "public:<id>" / "custom:<id>" of whichever time signature is currently chosen - the source of
    // truth now that the picker is a popup rather than a native <select> with its own .value. Shared
    // by both Blocks' own segment editor and Quick Play's per-block editors (only one picker can ever
    // be open at once) - whoever opens the modal sets this to their own current value first so
    // renderMetroSegTimeSigPicker highlights the right option.
    let metroSegTimeSigValue = null;
    // Which caller currently owns the picker - set right before the modal opens, so one shared modal
    // can serve both Blocks (updates its own segment fields) and Quick Play (updates one block's own
    // state) without this file hardcoding either caller's update logic.
    let metroSegTimeSigOnSelect = null;

    function metroSegTimeSigLabelFor(value) {
        if (!value) return '';
        const [type, id] = value.split(':');
        const list = type === 'public' ? metroBlkTimeSigCache.public : metroBlkTimeSigCache.custom;
        const found = list.find(t => t.id === Number(id));
        return found ? found.label : '';
    }
    // ML-153: three fixed preset grids (Simple/Compound/Asymmetric) instead of one column per
    // denominator - grouped by time_signature_options.family (db/migrations/030_time_signature_
    // family.sql), which is NULL for every catalog entry that isn't one of these 12 presets (those
    // stay reachable only via the custom builder below, same as before). The order within each
    // family is fixed to match the design exactly - family alone doesn't imply an order, and the
    // catalog's own sort_order (oldest-added-first) doesn't happen to match it. A family with zero
    // members (shouldn't happen given the migration, but if the catalog is ever edited down to
    // nothing) just renders no grid rather than an empty heading.
    const METRO_SEG_TIMESIG_FAMILY_LABELS = { simple: 'Simple', compound: 'Compound', asymmetric: 'Asymmetric' };
    const METRO_SEG_TIMESIG_FAMILY_ORDER = {
        simple: ['2/4', '3/4', '4/4', '2/2'],
        compound: ['6/8', '9/8', '12/8', '3/8'],
        asymmetric: ['5/4', '7/4', '5/8', '7/8']
    };
    function renderMetroSegTimeSigPicker() {
        const el = document.getElementById('metroSegTimeSigFamilies');
        if (!el) return;
        el.innerHTML = Object.keys(METRO_SEG_TIMESIG_FAMILY_LABELS).map(family => {
            const order = METRO_SEG_TIMESIG_FAMILY_ORDER[family];
            const members = metroBlkTimeSigCache.public
                .filter(t => t.family === family)
                .sort((a, b) => order.indexOf(a.label) - order.indexOf(b.label));
            if (!members.length) return '';
            return `<div class="metroSeg-timesig-family">
                <div class="flow-tile-section-label">${METRO_SEG_TIMESIG_FAMILY_LABELS[family]}</div>
                <div class="metroSeg-timesig-family-grid">
                    ${members.map(t => {
                        const value = `public:${t.id}`;
                        return `<button type="button" class="metroBlk-timesig-opt${value === metroSegTimeSigValue ? ' selected' : ''}" data-value="${value}">${escapeHtml(t.label)}</button>`;
                    }).join('')}
                </div>
            </div>`;
        }).join('');
        el.querySelectorAll('.metroBlk-timesig-opt').forEach(btn => {
            btn.addEventListener('click', () => selectMetroSegTimeSig(btn.dataset.value));
        });
        renderMetroSegTimeSigChips();
    }
    // Saved custom quick chips - tapping the label selects & closes immediately, same as a preset.
    // Only shown once there's at least one (metroSegTimeSigChipsRow starts hidden-group in the HTML).
    // The small × (stopPropagation'd so it never also triggers select) is this compact popup's only
    // way to get an unwanted signature out of the way now that the old "Your custom time signatures"
    // full management list (with separate Delete/Archive actions) is gone. It archives rather than
    // hard-deletes, so the row stays in account_time_signatures (still valid for any block already
    // using it) - just hidden from the chip row instead of destroyed. A true delete is still possible
    // via window.deleteMetroSegCustomTimeSig if ever needed, just not exposed from this compact UI.
    function renderMetroSegTimeSigChips() {
        const row = document.getElementById('metroSegTimeSigChipsRow');
        const chips = document.getElementById('metroSegTimeSigChips');
        if (!row || !chips) return;
        const custom = metroBlkTimeSigCache.custom;
        row.classList.toggle('hidden-group', !custom.length);
        chips.innerHTML = custom.map(t => `
            <span class="metroSeg-timesig-chip">
                <button type="button" class="metroSeg-timesig-chip-select" data-value="custom:${t.id}">${escapeHtml(t.label)}</button>
                <button type="button" class="metroSeg-timesig-chip-remove" data-remove-id="${t.id}" aria-label="Archive ${escapeHtml(t.label)}">&times;</button>
            </span>`).join('');
        chips.querySelectorAll('.metroSeg-timesig-chip-select').forEach(btn => {
            btn.addEventListener('click', () => selectMetroSegTimeSig(btn.dataset.value));
        });
        chips.querySelectorAll('.metroSeg-timesig-chip-remove').forEach(btn => {
            btn.addEventListener('click', (e) => {
                e.stopPropagation();
                archiveMetroSegCustomTimeSig(Number(btn.dataset.removeId));
            });
        });
    }
    // Picking a real signature applies immediately and closes, same as the note-value picker - no
    // separate "apply" step. The [x]/Done are the only ways to close without changing anything.
    function selectMetroSegTimeSig(value) {
        metroSegTimeSigValue = value;
        metroSegTimeSigOnSelect?.(value);
        hideModal('metroSegTimeSigModal');
    }
    // ML-148-style scrim dismissal - tapping the dark backdrop outside the card closes it, same as
    // Done/[x] (every change already applies live, there's no separate "save" step to lose).
    document.getElementById('metroSegTimeSigModal')?.addEventListener('click', (e) => {
        if (e.target === e.currentTarget) hideModal(e.currentTarget);
    });

    // "Your custom time signatures" - every one the account has, active or archived, with how many
    // blocks (across every setup) actually use it. Zero usage -> can delete outright; still in use
    // -> archive instead (stays valid for whatever already references it, just stops being offered
    // for a new block). Only shown at all once there's at least one.
    async function renderMetroSegCustomSigManageList() {
        const section = document.getElementById('metroSegCustomSigManageSection');
        const list = document.getElementById('metroSegCustomSigManageList');
        if (!section || !list) return;
        try {
            const custom = await API.metronomeBlocks.timeSignatures.listCustomWithUsage();
            section.classList.toggle('hidden-group', !custom.length);
            list.innerHTML = custom.map(t => {
                const usageText = t.usageCount === 0 ? 'Not used' : `Used in ${t.usageCount} block${t.usageCount === 1 ? '' : 's'}`;
                const archivedTag = t.active ? '' : ' &middot; archived';
                let actionHtml = '';
                if (t.usageCount === 0) {
                    actionHtml = `<button class="btn-icon-delete" aria-label="Delete ${escapeHtml(t.label)}" data-act="timesig-delete" data-arg="${t.id}"><span class="material-symbols-outlined">delete</span></button>`;
                } else if (t.active) {
                    actionHtml = `<button class="btn-edit btn-inline-xs" data-act="timesig-archive" data-arg="${t.id}">Archive</button>`;
                }
                return `<div class="history-item items-center">
                    <div class="grow"><strong>${escapeHtml(t.label)}</strong>${archivedTag}<div class="text-sm text-muted">${usageText}</div></div>
                    ${actionHtml}
                </div>`;
            }).join('');
        } catch (error) {
            showWarningToast('Error loading custom time signatures: ' + error.message);
        }
    }

    async function refreshMetroSegTimeSigEverywhere() {
        await loadMetroBlkTimeSignatures();
        renderMetroSegTimeSigPicker();
        renderMetroSegCustomSigManageList();
    }

    window.deleteMetroSegCustomTimeSig = function(id) {
        showConfirmModal('Delete time signature', 'Delete this custom time signature?', async () => {
            try {
                await API.metronomeBlocks.timeSignatures.deleteCustom(id);
                showSuccessToast('Deleted');
                await refreshMetroSegTimeSigEverywhere();
            } catch (error) {
                showWarningToast('Error: ' + error.message);
            }
        });
    }

    window.archiveMetroSegCustomTimeSig = function(id) {
        showConfirmModal('Archive time signature', 'Archive this time signature? It stays valid for blocks that already use it, but won’t be offered for new ones.', async () => {
            try {
                await API.metronomeBlocks.timeSignatures.archiveCustom(id);
                showSuccessToast('Archived');
                await refreshMetroSegTimeSigEverywhere();
            } catch (error) {
                showWarningToast('Error: ' + error.message);
            }
        }, false);
    }

    // Tap = +-1, hold = repeats, accelerating to +-10 per step after 15 taps' worth - same feel as
    // the single-bar metronome's own BPM stepper (setupMetroBpmStepper), generalised here to take
    // any step-applying callback so both the BPM and bar-count controls above can share it.
    function setupHoldStepper(btnOrId, direction, applyStep) {
        const btn = typeof btnOrId === 'string' ? document.getElementById(btnOrId) : btnOrId;
        if (!btn) return;
        const REPEAT_MS = 100;
        const INITIAL_DELAY_MS = 400;
        const ACCELERATE_AFTER = 15;
        let repeatTimer = null;
        let startTimer = null;
        let unitStepsTaken = 0;

        function step() {
            applyStep((unitStepsTaken >= ACCELERATE_AFTER ? 10 : 1) * direction);
            if (unitStepsTaken < ACCELERATE_AFTER) unitStepsTaken++;
        }
        function begin(e) {
            e.preventDefault();
            step();
            startTimer = setTimeout(() => { repeatTimer = setInterval(step, REPEAT_MS); }, INITIAL_DELAY_MS);
        }
        function end() {
            clearTimeout(startTimer);
            clearInterval(repeatTimer);
            unitStepsTaken = 0;
        }
        // a11y: press-and-hold repeats the step - each step is reversible with the opposite stepper (WCAG 2.5.2)
        btn.addEventListener('pointerdown', begin);
        btn.addEventListener('pointerup', end);
        btn.addEventListener('pointerleave', end);
        btn.addEventListener('pointercancel', end);
    }

    // Generic press-and-hold-to-reset behaviour for a Play/Pause button: a normal tap calls
    // onToggle(), a press held past holdMs calls onReset() instead and suppresses the click that
    // follows on release (so lifting off doesn't also toggle play/pause). Shared by every metronome-
    // family tool's own Play button (Quick Play, Blocks/Flow) rather than each tool wiring this up
    // itself - the one place this interaction's timing/behaviour lives, so it only needs changing
    // here to change it everywhere it's used.
    function setupPlayButtonHoldReset(btnOrId, onToggle, onReset, holdMs = 600) {
        const btn = typeof btnOrId === 'string' ? document.getElementById(btnOrId) : btnOrId;
        if (!btn) return;
        let holdTimer = null;
        let didHold = false;

        function begin(e) {
            e.preventDefault();
            didHold = false;
            holdTimer = setTimeout(() => {
                didHold = true;
                onReset();
            }, holdMs);
        }
        function cancelHold() {
            clearTimeout(holdTimer);
        }
        // a11y: only starts the press-and-hold timer; the tap action itself runs on click (WCAG 2.5.2)
        btn.addEventListener('pointerdown', begin);
        btn.addEventListener('pointerup', cancelHold);
        btn.addEventListener('pointerleave', cancelHold);
        btn.addEventListener('pointercancel', cancelHold);
        btn.addEventListener('click', () => {
            if (didHold) { didHold = false; return; }
            onToggle();
        });
    }

    // --- Note-value icons (real vector glyphs, not unicode musical symbols - see the CSS comment
    // on .metroBlk-note-picker for why). Shared with Quick Play's own per-block note picker
    // (qpOpenNotePicker) - same eight note values throughout the app, shortest to longest. Fraction
    // is of a semibreve (quaver = 1/8 = 0.125, etc.) - see metroSegNoteFraction. ---
    const METRO_NOTE_TYPES = [
        { key: 'semiquaver', label: 'Semiquaver', fraction: 0.0625 },
        { key: 'quaver', label: 'Quaver', fraction: 0.125 },
        { key: 'dotted-quaver', label: 'Dotted quaver', fraction: 0.1875 },
        { key: 'crotchet', label: 'Crotchet', fraction: 0.25 },
        { key: 'dotted-crotchet', label: 'Dotted crotchet', fraction: 0.375 },
        { key: 'minim', label: 'Minim', fraction: 0.5 },
        { key: 'dotted-minim', label: 'Dotted minim', fraction: 0.75 },
        { key: 'semibreve', label: 'Semibreve', fraction: 1 }
    ];
    // One shared viewBox/layout across all eight so they line up in a row regardless of whether a
    // given note has a stem/flag(s)/dot - notehead centre and stem position are fixed constants.
    function metroNoteIconSvg(key) {
        const head = '<ellipse cx="13" cy="44" rx="7.5" ry="5.2" transform="rotate(-20 13 44)"';
        const stem = '<rect x="19" y="6" width="2.6" height="38" fill="currentColor"/>';
        const flag = '<path d="M21.6 6 C30 10 29 20 21 26" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"/>';
        const flagLow = '<path d="M21.6 16 C30 20 29 30 21 36" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"/>';
        const dot = '<circle cx="27" cy="42" r="2.2" fill="currentColor"/>';
        switch (key) {
            case 'semibreve':
                return '<svg viewBox="0 0 32 56" class="metroBlk-note-svg"><ellipse cx="16" cy="28" rx="10" ry="6" fill="none" stroke="currentColor" stroke-width="3"/></svg>';
            case 'dotted-minim':
                return `<svg viewBox="0 0 32 56" class="metroBlk-note-svg">${head} fill="none" stroke="currentColor" stroke-width="2.6"/>${stem}${dot}</svg>`;
            case 'minim':
                return `<svg viewBox="0 0 32 56" class="metroBlk-note-svg">${head} fill="none" stroke="currentColor" stroke-width="2.6"/>${stem}</svg>`;
            case 'dotted-crotchet':
                return `<svg viewBox="0 0 32 56" class="metroBlk-note-svg">${head} fill="currentColor"/>${stem}${dot}</svg>`;
            case 'dotted-quaver':
                return `<svg viewBox="0 0 32 56" class="metroBlk-note-svg">${head} fill="currentColor"/>${stem}${flag}${dot}</svg>`;
            case 'quaver':
                return `<svg viewBox="0 0 32 56" class="metroBlk-note-svg">${head} fill="currentColor"/>${stem}${flag}</svg>`;
            case 'semiquaver':
                return `<svg viewBox="0 0 32 56" class="metroBlk-note-svg">${head} fill="currentColor"/>${stem}${flag}${flagLow}</svg>`;
            default: // crotchet
                return `<svg viewBox="0 0 32 56" class="metroBlk-note-svg">${head} fill="currentColor"/>${stem}</svg>`;
        }
    }

    document.getElementById('metroSegCustomSigAddBtn')?.addEventListener('click', async () => {
        const numerator = Number(document.getElementById('metroSegCustomNumerator').value);
        // Denominator is a <select> locked to 2/4/8/16 (ML-153 - a beat value has to actually be a
        // musical note power of two), so it can't itself be out of range - only beats needs checking.
        const denominator = Number(document.getElementById('metroSegCustomDenominator').value);
        if (!numerator || numerator < 1 || numerator > 32) return showWarningToast('Beats must be between 1 and 32.');
        try {
            const created = await API.metronomeBlocks.timeSignatures.createCustom(numerator, denominator);
            await loadMetroBlkTimeSignatures();
            selectMetroSegTimeSig(`custom:${created.id}`);
            document.getElementById('metroSegCustomNumerator').value = '4';
            document.getElementById('metroSegCustomDenominator').value = '4';
            showSuccessToast(`Added ${numerator}/${denominator}`);
        } catch (error) {
            showWarningToast('Error adding time signature: ' + error.message);
        }
    });

    async function loadMetroBlkTimeSignatures(token) {
        try {
            metroBlkTimeSigCache = await API.metronomeBlocks.timeSignatures.list(token);
        } catch (error) {
            showWarningToast('Error loading time signatures: ' + error.message);
        }
    }

    // A factor of 1 means "no subdivision" - shown as "0" (not "1") so the collapsed button and popup
    // both read as "0 sub beats" rather than a plain "1" that doesn't obviously mean off.
    function metroBlkSubdivideDisplayValue(v) { return v <= 1 ? '0' : String(v); }

    // --- Multi-row "now + upcoming" display ---
    // Takes the total dot count (beats * subdivide factor), not just the beat count - mirrors
    // metroTierGeometry's leftPct on the single-bar tool, now that subdivide is real here too.
    function metroBlkLeftPctFn(totalBaseClicks) {
        const unit = 100 / totalBaseClicks;
        return (k) => k * unit + unit / 2;
    }

    // Draws a line connecting the first dot to the last, reusing each dot's own already-computed
    // `left` (a padding-aware calc() from metroLeftStyle) rather than re-deriving the geometry -
    // keeps the track pinned exactly to the dots regardless of row width or edge padding.
    // Extends one further slot past the last dot (endLeftStyle, the same per-click spacing as
    // everywhere else in the row) with a small vertical tick, rather than stopping dead at the last
    // dot - that "click" of time between the last beat and looping back to the first still happens,
    // so the line shouldn't look like it just runs out.
    function connectMetroBlkDotsWithTrack(rowId, endLeftStyle) {
        const row = document.getElementById(rowId);
        if (!row) return;
        let track = row.querySelector('.metroBlk-row-track');
        if (!track) {
            track = document.createElement('div');
            track.className = 'metroBlk-row-track';
            row.insertBefore(track, row.firstChild);
        }
        let endTick = row.querySelector('.metroBlk-row-track-end');
        if (!endTick) {
            endTick = document.createElement('div');
            endTick.className = 'metroBlk-row-track-end';
            row.insertBefore(endTick, row.firstChild);
        }
        const dots = row.querySelectorAll('.metro-dot');
        if (dots.length < 2) { setShown(track, false); setShown(endTick, false); return; }
        setShown(track, true);
        setShown(endTick, true);
        track.style.setProperty('--track-start', dots[0].style.getPropertyValue('--dot-x'));
        track.style.setProperty('--track-end', endLeftStyle);
        endTick.style.setProperty('--track-end', endLeftStyle);
    }

    // A partial lead-in plays the LAST pickupBeats beats of the bar, not the first - a pickup/
    // anacrusis leads into the downbeat that follows, so on a 4-beat bar with a 1-beat pickup it's
    // beat 4 that sounds, not beat 1. Those unused leading beats are never actually scheduled (see
    // the player's start click), so this just makes that visually obvious upfront
    // rather than the dot simply never happening to light up.
    function greyOutSkippedDots(rowId, block, subFactor) {
        if (!block || !block.pickupBeats) return;
        const skippedCount = (block.numerator - block.pickupBeats) * subFactor;
        document.querySelectorAll(`#${rowId} .metro-dot`).forEach((dot, idx) => {
            dot.classList.toggle('metroBlk-dot-skipped', idx < skippedCount);
        });
    }

    // ========================================
    // QUICK PLAY - front page tool, replaces the old single-bar Metronome page. A simplified,
    // always-editable variant of Metronome Blocks/Flow above: no name, no lead-in, no saved-setups
    // library - every block's full detail entry is shown inline and stacked (createQuickPlayBlockEditor)
    // rather than a tile you tap to open an edit modal. Own player instance (qpPlayer) and own
    // sub-beats/play-speed/volume state, same reasoning as Blocks having its own rather than sharing
    // the old single-bar tool's - see the METRONOME ENGINE section up top for what IS shared (the
    // audio engine factory, dot/scroll helpers, slider/stepper interaction helpers). Every Play press
    // (from a stopped/reset state, not a pause resume) writes the current blocks in as one history row
    // via POST /api/metronome/quick-play - see saveQuickPlayHistory.
    // ========================================
    const qpPlayer = createMetronomePlayer();
    qpPlayerRef = qpPlayer;
    qpPlayer.setVisualLatencyMs(metroState.latencyMs);

    // One block: { timeSigValue, bpm, noteSelected, barCount }, same shape/meaning as a Blocks segment
    // minus everything lead-in-only (isLeadIn/pickupBeats/repeatLeadIn/quietSecondsBeforeLeadIn don't
    // exist here - Quick Play has no lead-in concept at all).
    let qpBlocks = [];
    // Resets to false on any edit (add/remove/change a block) or Reset - Play only writes history the
    // moment it actually (re)starts playback from a stopped state, not on every pause/resume toggle.
    let qpSavedThisRun = false;

    // Specifically 4/4 (the metronome's own stated default), not just whichever public signature
    // happens to sort first in the catalog - falls back to that only if 4/4 is somehow missing.
    function qpDefaultTimeSigValue() {
        const list = metroBlkTimeSigCache?.public || [];
        const fourFour = list.find(t => t.numerator === 4 && t.denominator === 4);
        const fallback = fourFour || list[0];
        return fallback ? `public:${fallback.id}` : null;
    }

    // Every block gets a stable id of its own, separate from its position in qpBlocks - add/move/
    // duplicate/delete all rebuild the DOM from scratch (renderQuickPlayBlocks), so the only way to
    // tell "this is the same bar, just somewhere else now" from "a different bar is now at this
    // index" for the FLIP animations below is to match on this rather than array index.
    let qpUidCounter = 0;
    function qpNewBlock(overrides = {}) {
        return { _uid: ++qpUidCounter, timeSigValue: qpDefaultTimeSigValue(), bpm: 100, noteSelected: 'crotchet', barCount: 1, ...overrides };
    }

    // The builder's landing state - seeded once per page load (not per visit), same spirit as Blocks'
    // scratch setup always having at least one block so the tool is immediately playable. Unlike
    // Blocks, nothing is persisted server-side until Play is actually pressed, so there's no server
    // round-trip needed just to open the page.
    function initQuickPlayBlocksIfNeeded() {
        if (qpBlocks.length) return;
        qpBlocks = [qpNewBlock()];
        renderQuickPlayBlocks();
        jumpQpToIndex(0);
    }

    function qpMarkUnsaved() {
        qpSavedThisRun = false;
        // ML-34 follow-up: every edit call site already routes through here, so this is the one place
        // that needs to know "something changed since Load" - flips on the "- edited" tag/undo icon
        // next to the loaded name. Guarded so it doesn't needlessly re-render on every single edit
        // once it's already showing.
        if (qpLoadedHistoryId !== null && !qpLoadedHistoryEdited) {
            qpLoadedHistoryEdited = true;
            renderQpLoadedHistoryLabel();
        }
    }

    // --- Per-block inline editor (time signature / note+BPM stepper+slider / bar-count stepper+slider) ---
    // Originally reused the Blocks segment-edit modal's own field markup; ML-103 later went the other
    // way and restyled that modal's own Standard fields (public/app.html's #metroSegStandardBox) to
    // match THIS card's qp-bar-fields-grid/qp-timesig-cell/qp-notelen-cell/qp-bpm-cell layout instead,
    // since it reads more cleanly - the two still don't share DOM/state (see below), just the same
    // classes now. Built fresh per block instance rather than a singleton modal's own DOM/state
    // (metroSegBpm etc.) - several of these are visible on screen at once, which that modal was never
    // designed for. Reuses the genuinely value-agnostic pieces directly: METRO_SLIDER_TIERS/
    // metroBestFitTier/METRO_MIN_BPM/METRO_MAX_BPM, setupSliderInteraction (already takes elements, not
    // ids), setupHoldStepper/makeSliderReadoutEditable (generalised below to take an element OR an id),
    // metroNoteIconSvg/METRO_NOTE_TYPES/metroSegDefaultNoteForDenominator, and metroBlkTimeSigCache for
    // the shared time-signature modal.
    function qpBlockNoteFraction(noteKey) {
        const t = METRO_NOTE_TYPES.find(x => x.key === noteKey);
        return t ? t.fraction : 0.25;
    }
    // Resolves a block's own numerator/denominator from whichever catalog its timeSigValue points
    // into - same lookup shape as metroSegSelectedDenominator/metroSegTimeSigLabelFor, just against
    // this block's own stored value instead of the segment modal's single in-flight one.
    function qpBlockTimeSig(block) {
        if (!block.timeSigValue) return { numerator: 4, denominator: 4 };
        const [sigType, sigId] = block.timeSigValue.split(':');
        const list = sigType === 'public' ? metroBlkTimeSigCache.public : metroBlkTimeSigCache.custom;
        const found = list.find(t => t.id === Number(sigId));
        return found ? { numerator: found.numerator, denominator: found.denominator } : { numerator: 4, denominator: 4 };
    }
    function qpBlockDenominator(block) { return qpBlockTimeSig(block).denominator; }
    function qpBlockTimeSigLabel(block) { return metroSegTimeSigLabelFor(block.timeSigValue) || 'Choose…'; }

    // Always exactly 1 bar per block, no repeat - that's a Flow-only concept (its own bar-count
    // stepper/slider). Title is computed from position ("Bar N"), not stored, so move/duplicate/
    // delete never need to renumber anything - the next render just reads it off the new index.
    // ML-145: the outer .qp-block-box is just a clipping wrapper now (see the matching style.css
    // comment) - the delete underlay sits behind, the actual card content lives in .qp-block-surface,
    // which is what wireQpBarSwipe slides. The grab handle only renders once there's more than one bar
    // to reorder (matches the 3-dot menu's own Move up/down, which hide for the same reason).
    function qpBlockBoxHtml(block, index) {
        const grabHandle = qpBlocks.length > 1
            ? `<button type="button" class="qp-bar-grab-handle" data-qp-grab-handle aria-label="Drag to reorder Bar ${index + 1}"><span class="material-symbols-outlined">drag_indicator</span></button>`
            : '';
        // ML-80: Bar 1 is the only bar that can never actually be deleted on its own (qpDeleteBar
        // no-ops once qpBlocks.length <= 1) - swiping it used to reveal a Delete button that did
        // nothing when tapped. In that exact state, the underlay becomes "Reset" (qpResetAllBars)
        // instead, so the gesture has a real effect; with more than one bar, Bar 1 deletes normally.
        const isDeadEndDelete = index === 0 && qpBlocks.length <= 1;
        const deleteUnderlay = isDeadEndDelete
            ? `<div role="button" tabindex="0" class="qp-block-delete-underlay" data-qp-reset-all-btn aria-label="Delete all and reset">
                <span class="material-symbols-outlined">restart_alt</span>
                <span>Reset</span>
            </div>`
            : `<div role="button" tabindex="0" class="qp-block-delete-underlay" data-qp-delete-btn aria-label="Delete Bar ${index + 1}">
                <span class="material-symbols-outlined">delete</span>
                <span>Delete</span>
            </div>`;
        return `<div class="qp-block-box" data-qp-block-index="${index}" data-qp-uid="${block._uid}">
            ${deleteUnderlay}
            <div class="qp-block-surface">
                <div class="qp-block-header">
                    <div class="qp-block-header-left">
                        ${grabHandle}
                        <span class="qp-block-title">Bar ${index + 1}</span>
                    </div>
                    <button type="button" class="qp-bar-menu-btn" data-qp-menu-btn aria-label="Bar ${index + 1} options" aria-haspopup="menu" aria-expanded="false"><span class="material-symbols-outlined">more_vert</span></button>
                </div>
                <div class="qp-bar-fields-grid">
                    <button type="button" class="metroBlk-ctrl-value-btn qp-timesig-cell" data-qp-timesig-btn aria-label="Time signature - tap to change" aria-haspopup="dialog" aria-expanded="false">
                        <strong>${escapeHtml(qpBlockTimeSigLabel(block))}</strong>
                        <span class="metroBlk-ctrl-value-label">time</span>
                    </button>
                    <button type="button" class="metroBlk-ctrl-value-btn qp-notelen-cell" data-qp-note-btn aria-label="Beat note - tap to change" aria-haspopup="dialog" aria-expanded="false">
                        <span class="qp-note-btn-icon">${metroNoteIconSvg(block.noteSelected)}</span>
                        <span class="metroBlk-ctrl-value-label">beat note</span>
                    </button>
                    <div class="metroBlk-bpm-box qp-bpm-cell">
                        <div class="metro-speed-row no-margin qp-bpm-speed-row">
                            <button class="metro-bpm-step" type="button" data-qp-bpm-minus aria-label="Decrease beats per minute">&minus;</button>
                            <div class="metro-speed-readout">
                                <div data-qp-bpm-value>120</div>
                                <div class="metro-speed-sub">bpm</div>
                            </div>
                            <button class="metro-bpm-step" type="button" data-qp-bpm-plus aria-label="Increase beats per minute">+</button>
                        </div>
                        <div class="slider-wrap no-margin">
                            <div class="slider-track" data-qp-bpm-slider-track>
                                <div class="slider-fill" data-qp-bpm-slider-fill></div>
                                <div class="slider-thumb" data-qp-bpm-slider-thumb tabindex="0" role="slider" aria-label="Beats per minute" aria-valuemin="${METRO_MIN_BPM}" aria-valuenow="120"></div>
                            </div>
                            <div class="slider-scale"><span>${METRO_MIN_BPM}</span><span data-qp-bpm-slider-max-lbl>200</span></div>
                        </div>
                    </div>
                </div>
            </div>
        </div>`;
    }

    // Wires one block box's interactive controls, reading/writing straight into qpBlocks[index] -
    // called once per box right after it's inserted into the DOM (renderQuickPlayBlocks).
    function wireQpBlockBox(boxEl, index) {
        attachSpeedNames(boxEl);
        const block = qpBlocks[index];
        let bpmSliderMax = metroBestFitTier(Math.round(block.bpm / (qpBlockNoteFraction(block.noteSelected) * qpBlockDenominator(block))));

        const bpmValueEl = boxEl.querySelector('[data-qp-bpm-value]');
        const bpmTrack = boxEl.querySelector('[data-qp-bpm-slider-track]');
        const bpmFill = boxEl.querySelector('[data-qp-bpm-slider-fill]');
        const bpmThumb = boxEl.querySelector('[data-qp-bpm-slider-thumb]');
        const bpmMaxLbl = boxEl.querySelector('[data-qp-bpm-slider-max-lbl]');

        function displayedBpm() {
            return qpBlocks[index].bpm / (qpBlockNoteFraction(qpBlocks[index].noteSelected) * qpBlockDenominator(qpBlocks[index]));
        }
        function renderBpmSlider() {
            const displayed = Math.round(displayedBpm());
            const pct = ((displayed - METRO_MIN_BPM) / (bpmSliderMax - METRO_MIN_BPM)) * 100;
            bpmFill.style.setProperty('--pct', `${pct}%`);
            bpmThumb.style.setProperty('--pct', `${pct}%`);
            bpmThumb.setAttribute('aria-valuenow', displayed);
            bpmThumb.setAttribute('aria-valuemax', bpmSliderMax);
            bpmMaxLbl.innerText = bpmSliderMax;
            bpmValueEl.innerText = displayed;
        }
        function refreshBpmDisplay() {
            bpmSliderMax = metroBestFitTier(Math.round(displayedBpm()));
            renderBpmSlider();
        }
        // Holding the thumb at the track's edge keeps re-evaluating this on every pointermove even
        // without the pointer actually moving further - ratio stays ~1 (or ~0) but bpmSliderMax has
        // just grown (or shrunk), so the very next event re-hits the same edge-of-tier check against
        // the new tier and expands again, cascading straight through every tier in one continuous
        // hold instead of needing a further drag per tier. A short cooldown after each tier change
        // forces a beat between expansions so 350 is actually reachable/visible before 500 can happen.
        let bpmTierChangeCooldownUntil = 0;
        function bpmStepTier(value) {
            const now = Date.now();
            if (now < bpmTierChangeCooldownUntil) return;
            const idx = METRO_SLIDER_TIERS.indexOf(bpmSliderMax);
            if (idx < METRO_SLIDER_TIERS.length - 1 && value >= METRO_SLIDER_TIERS[idx]) {
                bpmSliderMax = METRO_SLIDER_TIERS[idx + 1];
                bpmTierChangeCooldownUntil = now + 350;
            } else if (idx > 0 && value < METRO_SLIDER_TIERS[idx - 1]) {
                bpmSliderMax = METRO_SLIDER_TIERS[idx - 1];
                bpmTierChangeCooldownUntil = now + 350;
            }
        }
        function setBpmFromDisplayed(displayedValue, opts = {}) {
            const clamped = Math.round(Math.min(METRO_MAX_BPM, Math.max(METRO_MIN_BPM, displayedValue)));
            if (opts.dragging) bpmStepTier(clamped); else bpmSliderMax = metroBestFitTier(clamped);
            qpBlocks[index].bpm = Math.round(clamped * qpBlockNoteFraction(qpBlocks[index].noteSelected) * qpBlockDenominator(qpBlocks[index]));
            renderBpmSlider();
            qpMarkUnsaved();
            renderQuickPlayRows();
        }

        setupHoldStepper(boxEl.querySelector('[data-qp-bpm-minus]'), -1, (amount) => setBpmFromDisplayed(Math.round(displayedBpm()) + amount));
        setupHoldStepper(boxEl.querySelector('[data-qp-bpm-plus]'), 1, (amount) => setBpmFromDisplayed(Math.round(displayedBpm()) + amount));
        setupSliderInteraction(bpmTrack, bpmThumb, {
            onDragRatio: (ratio) => setBpmFromDisplayed(METRO_MIN_BPM + ratio * (bpmSliderMax - METRO_MIN_BPM), { dragging: true }),
            onArrowStep: (dir) => setBpmFromDisplayed(Math.round(displayedBpm()) + dir, { dragging: true })
        });
        makeSliderReadoutEditable(bpmValueEl, () => Math.round(displayedBpm()), (v) => setBpmFromDisplayed(v), { label: 'Beats per minute', min: METRO_MIN_BPM, max: METRO_MAX_BPM });

        // The note button's icon lives in its own inner span (not the button's whole innerHTML) so
        // qpOpenNotePicker's anchor swap only replaces the glyph, leaving the "note length" label
        // below it untouched.
        boxEl.querySelector('[data-qp-note-btn]')?.addEventListener('click', (e) => {
            const iconEl = e.currentTarget.querySelector('.qp-note-btn-icon');
            qpOpenNotePicker(iconEl, index, () => { refreshBpmDisplay(); renderBpmSlider(); renderQuickPlayRows(); });
        });
        boxEl.querySelector('[data-qp-timesig-btn]')?.addEventListener('click', () => {
            qpOpenTimeSigPicker(index, () => {
                boxEl.querySelector('[data-qp-timesig-btn] strong').innerText = qpBlockTimeSigLabel(qpBlocks[index]);
                refreshBpmDisplay();
                renderBpmSlider();
                renderQuickPlayRows();
            });
        });
        boxEl.querySelector('[data-qp-menu-btn]')?.addEventListener('click', (e) => {
            e.stopPropagation();
            openQpBarMenu(e.currentTarget, index);
        });
        wireQpBarGrabHandle(boxEl.querySelector('[data-qp-grab-handle]'), boxEl, index);
        wireQpBarSwipe(boxEl, index);

        renderBpmSlider();
    }

    // Shared note-value picker modal (#metroSegNoteModal) - same reasoning as the time-signature modal
    // below: one popup, only ever open for one block at a time, so it's fine to reuse directly rather
    // than duplicate. onPicked runs after qpBlocks[index].noteSelected is updated, so the caller can
    // refresh its own displayed "note = bpm" readout.
    function qpOpenNotePicker(anchorBtn, index, onPicked) {
        const el = document.getElementById('metroSegNotePicker');
        if (!el) return;
        el.innerHTML = METRO_NOTE_TYPES.map(t => `
            <button type="button" class="metroBlk-note-btn${t.key === qpBlocks[index].noteSelected ? ' selected' : ''}" data-note="${t.key}" aria-label="${t.label}" aria-pressed="${t.key === qpBlocks[index].noteSelected}">
                ${metroNoteIconSvg(t.key)}
            </button>
        `).join('');
        el.querySelectorAll('.metroBlk-note-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                qpBlocks[index].noteSelected = btn.dataset.note;
                anchorBtn.innerHTML = metroNoteIconSvg(btn.dataset.note);
                hideModal('metroSegNoteModal');
                qpMarkUnsaved();
                onPicked();
            }, { once: true });
        });
        showModal('metroSegNoteModal');
    }

    // Shared time-signature modal (#metroSegTimeSigModal) - see metroSegTimeSigOnSelect above for how
    // one modal serves both Blocks' segment editor and this.
    function qpOpenTimeSigPicker(index, onPicked) {
        metroSegTimeSigValue = qpBlocks[index].timeSigValue;
        metroSegTimeSigOnSelect = (value) => {
            qpBlocks[index].timeSigValue = value;
            qpMarkUnsaved();
            onPicked();
        };
        renderMetroSegTimeSigPicker();
        showModal('metroSegTimeSigModal');
    }

    function renderQuickPlayBlocks() {
        const container = document.getElementById('qpBlocks');
        if (!container) return;
        qpOpenSwipeIndex = null; // a full rebuild throws every node away - any open swipe is stale
        container.innerHTML = qpBlocks.map((b, i) => qpBlockBoxHtml(b, i)).join('');
        container.querySelectorAll('[data-qp-block-index]').forEach(boxEl => {
            wireQpBlockBox(boxEl, Number(boxEl.dataset.qpBlockIndex));
        });
    }

    // Generic grab-handle-driven vertical reorder gesture, shared by Quick Play's own bar boxes
    // (wireQpBarGrabHandle) and Flow's block cards (wireFlowBlockGrabHandle). Picking up the handle
    // live-follows the pointer with a translateY on the whole box, and gives the card (surfaceSelector,
    // a child of boxEl) a gold, thicker border (.drag-reorder-highlight) for the duration - clear
    // "this is the one moving" feedback the whole gesture through. Releasing past the threshold
    // deliberately leaves both the transform and the highlight in place (NOT reset here) and calls
    // onMoveUp/onMoveDown - whichever animated swap that triggers (qpSwapBarPositions/
    // flowSwapBlockPositions, both built on animateFlipReorder below) captures the box's current,
    // already-dragged position as its FLIP "before" state (so the box continues smoothly on to its new
    // slot instead of snapping back to its original position first - the bug this replaced) and
    // re-applies the highlight to the freshly re-rendered element until the settle animation actually
    // finishes, so the border reads as one continuous highlight across the whole gesture rather than
    // flickering off between the live-drag and settle phases. Releasing short of the threshold springs
    // back (and clears the highlight) instead, since nothing moved.
    function wireVerticalDragHandle(handleEl, boxEl, thresholdPx, onMoveUp, onMoveDown, surfaceSelector) {
        if (!handleEl) return;
        let startY = 0, dragging = false;
        function onMove(e) {
            if (!dragging) return;
            setMove(boxEl, 0, e.clientY - startY);
        }
        function onUp(e) {
            if (!dragging) return;
            dragging = false;
            document.removeEventListener('pointermove', onMove);
            document.removeEventListener('pointerup', onUp);
            const dy = e.clientY - startY;
            if (Math.abs(dy) > thresholdPx) {
                if (dy < 0) onMoveUp(); else onMoveDown();
            } else {
                boxEl.classList.remove('no-transition');
                boxEl.classList.add('transition-transform');
                clearMove(boxEl);
                boxEl.querySelector(surfaceSelector)?.classList.remove('drag-reorder-highlight');
            }
        }
        // a11y: only records where a swipe/drag gesture starts - nothing activates on press (WCAG 2.5.2)
        handleEl.addEventListener('pointerdown', (e) => {
            e.preventDefault();
            e.stopPropagation();
            boxEl.querySelector(surfaceSelector)?.classList.add('drag-reorder-highlight');
            startY = e.clientY;
            dragging = true;
            boxEl.classList.remove('transition-transform');
            boxEl.classList.add('no-transition');
            document.addEventListener('pointermove', onMove);
            document.addEventListener('pointerup', onUp);
        });
    }

    // FLIP (First-Last-Invert-Play): measures every item's current on-screen position before a
    // structural change, lets `rerender` rebuild the DOM as normal (titles/bar numbers are
    // position-derived off the underlying array, so a full rebuild is the simplest way to keep them
    // correct), then animates each surviving item from its old position to its new one. Matched by
    // `itemAttr` (e.g. `data-qp-uid`/`data-block-id`), not DOM node identity or array index - the
    // rebuild throws every node away, and index alone can't tell "this item moved" from "a different
    // item is now sitting at this index". An item with no "before" entry is brand new (add/duplicate)
    // and fades in instead of sliding, since there's no old position for it to slide from. raiseUid
    // optionally lifts one item's z-index for the duration, so on a move it visibly passes over the
    // item it's swapping with rather than both just sliding past each other flat - also re-applies the
    // gold-border drag-reorder-highlight (wireVerticalDragHandle) to that same raised element, on the
    // freshly re-rendered node, clearing it once its settle transition actually finishes - so the
    // border reads as one continuous highlight across the live-drag and settle phases rather than
    // flickering off in between. Shared by Quick Play's own bar boxes (qpAnimateBlocksChange) and
    // Flow's block cards (flowAnimateBlocksChange) - same technique, one implementation, rather than
    // two copies drifting apart.
    function animateFlipReorder({ containerId, itemAttr, mutate, rerender, raiseUid, animatingClass, surfaceSelector }) {
        const container = document.getElementById(containerId);
        const before = new Map();
        if (container) {
            container.querySelectorAll(`[${itemAttr}]`).forEach(el => {
                before.set(el.getAttribute(itemAttr), el.getBoundingClientRect());
            });
        }
        mutate();
        rerender();
        if (!container) return;
        const afterEls = [...container.querySelectorAll(`[${itemAttr}]`)];
        afterEls.forEach(el => {
            const uid = el.getAttribute(itemAttr);
            const prev = before.get(uid);
            if (raiseUid !== undefined && String(raiseUid) === uid) {
                el.classList.add('is-raised');
                el.querySelector(surfaceSelector)?.classList.add('drag-reorder-highlight');
            }
            if (prev) {
                const now = el.getBoundingClientRect();
                const dx = prev.left - now.left;
                const dy = prev.top - now.top;
                if (dx || dy) setMove(el, dx, dy);
            } else {
                el.classList.add('is-faded');
            }
        });
        // Two nested rAFs, not one - a single frame can still coalesce with the "before" styles just
        // written above on some browsers and jump straight to the end state with no visible motion.
        // The first rAF waits for that initial (inverted) frame to actually paint; only the second
        // one swaps in the transition + real values.
        requestAnimationFrame(() => {
            requestAnimationFrame(() => {
                afterEls.forEach(el => {
                    el.classList.add(animatingClass);
                    clearMove(el);
                    el.classList.remove('is-faded');
                    el.addEventListener('transitionend', () => {
                        el.classList.remove(animatingClass);
                        el.classList.remove('is-raised');
                        el.querySelector(surfaceSelector)?.classList.remove('drag-reorder-highlight');
                    }, { once: true });
                });
            });
        });
    }
    function qpAnimateBlocksChange(mutate, { raiseUid } = {}) {
        animateFlipReorder({
            containerId: 'qpBlocks', itemAttr: 'data-qp-uid', mutate,
            rerender: renderQuickPlayBlocks, raiseUid, animatingClass: 'qp-block-animating',
            surfaceSelector: '.qp-block-surface'
        });
    }
    // data-block-id is already on every .flow-block-box (flowBlockCardHtml) for the swipe/grab-handle
    // wiring - reused here as the same stable identity FLIP needs, no extra markup required.
    function flowAnimateBlocksChange(mutate, { raiseUid } = {}) {
        animateFlipReorder({
            containerId: 'flowBlocksList', itemAttr: 'data-block-id', mutate,
            rerender: renderFlowBlocksList, raiseUid, animatingClass: 'flow-block-animating',
            surfaceSelector: '.flow-block-card'
        });
    }

    // Raw position swap (no toast, no bounds checking) - the one place the actual array mutation for
    // a move happens, so qpMoveBarUp/Down (which add the undo toast) and their own undo callbacks
    // (which must NOT show a second toast) can both go through the same animated swap.
    function qpSwapBarPositions(i, j) {
        const movedUid = qpBlocks[i]._uid;
        qpAnimateBlocksChange(() => {
            [qpBlocks[i], qpBlocks[j]] = [qpBlocks[j], qpBlocks[i]];
        }, { raiseUid: movedUid });
        qpMarkUnsaved();
        qpSyncAfterBlocksChanged();
    }

    // Menu and swipe (wireQpBarSwipe) both call these directly, so there's exactly one place each
    // action's behaviour (and its undo toast) is implemented.
    function qpMoveBarUp(index) {
        if (index <= 0) return;
        qpSwapBarPositions(index, index - 1);
        showUndoToast(`Bar ${index + 1} moved up`, () => qpSwapBarPositions(index - 1, index));
    }
    function qpMoveBarDown(index) {
        if (index >= qpBlocks.length - 1) return;
        qpSwapBarPositions(index, index + 1);
        showUndoToast(`Bar ${index + 1} moved down`, () => qpSwapBarPositions(index + 1, index));
    }

    // Exit animation (fly off to the left, the standard swipe-to-delete direction) before the actual
    // removal - qpAnimateBlocksChange then handles the remaining bars sliding up to close the gap,
    // same as any other structural change. Offers an undo toast that re-inserts the exact removed
    // block back at its original index.
    function qpDeleteBar(index) {
        if (qpBlocks.length <= 1) return;
        const container = document.getElementById('qpBlocks');
        const el = container?.querySelector(`[data-qp-block-index="${index}"]`);
        const removedBlock = qpBlocks[index];
        const barNumber = index + 1;
        const finish = () => {
            qpMarkUnsaved();
            qpAnimateBlocksChange(() => { qpBlocks.splice(index, 1); });
            qpSyncAfterBlocksChanged();
            showUndoToast(`Bar ${barNumber} deleted`, () => {
                qpMarkUnsaved();
                qpAnimateBlocksChange(() => { qpBlocks.splice(index, 0, removedBlock); });
                qpSyncAfterBlocksChanged();
            });
        };
        if (!el) { finish(); return; }
        el.classList.add('qp-block-animating');
        setMove(el, '-100%');
        el.classList.add('is-faded');
        el.addEventListener('transitionend', finish, { once: true });
    }

    // ML-80: "back to where you were if you first landed" - clears every bar and reduces the setup
    // back to the one default 4/4 block, same as initQuickPlayBlocksIfNeeded's own starting state.
    // Reachable from Bar 1's own 3-dot menu (always) and Bar 1's swipe-left underlay (only when it's
    // the sole remaining bar - see qpBlockBoxHtml).
    function qpResetAllBars() {
        showConfirmModal('Delete all and reset', 'Delete every bar and start again with a single default bar (4/4, 100bpm)?', () => {
            qpOpenSwipeIndex = null;
            qpLoadedHistoryId = null;
            qpLoadedHistoryName = null;
            qpLoadedHistoryEdited = false;
            qpLoadedHistorySnapshot = null;
            renderQpLoadedHistoryLabel();
            qpAnimateBlocksChange(() => { qpBlocks = [qpNewBlock()]; });
            qpMarkUnsaved();
            qpSyncAfterBlocksChanged();
        });
    }

    // ML-145: replaces the old free 2-axis drag-anywhere-on-the-box gesture, which called
    // e.preventDefault() on every pointerdown regardless of direction and so blocked native page
    // scroll from ever starting on a bar card at all. Two independent, purpose-built gestures now:
    // wireQpBarGrabHandle owns vertical reordering, scoped strictly to the small handle
    // (touch-action:none there only, see style.css); wireQpBarSwipe owns horizontal swipe-to-reveal
    // delete, and only intercepts the gesture at all once it's confirmed horizontal (see the lock
    // check below) - anything more vertical than that is left untouched so touch-action:pan-y on
    // .qp-block-box lets the browser's own scroll handle it.
    const QP_REORDER_THRESHOLD_PX = 40;
    const QP_SWIPE_LOCK_X_PX = 30;
    const QP_SWIPE_LOCK_Y_MAX_PX = 15;
    const QP_SWIPE_OPEN_PX = 96; // keep in sync with .qp-block-delete-underlay's width in style.css
    const QP_SWIPE_SNAP_THRESHOLD_PX = 48;
    const QP_SWIPE_EXCLUDE_SELECTOR = 'button, input, [role="slider"], [role="button"], .slider-track, .slider-thumb';

    // Which bar (if any) is currently swiped open, revealing its delete underlay - at most one at a
    // time, matching the ticket's "tapping outside an open card... snaps it back". Tracked by index
    // rather than a DOM reference since a re-render (renderQuickPlayBlocks) throws every node away;
    // that same re-render resets this to null (stale DOM either way).
    let qpOpenSwipeIndex = null;
    function qpSwipeSurfaceFor(index) {
        return document.querySelector(`#qpBlocks [data-qp-block-index="${index}"] .qp-block-surface`);
    }
    function qpSetSwipeOffset(index, offset, animate) {
        const surface = qpSwipeSurfaceFor(index);
        if (!surface) return;
        swipeTo(surface, offset, animate);
    }
    function qpCloseOpenSwipe(animate = true) {
        if (qpOpenSwipeIndex === null) return;
        qpSetSwipeOffset(qpOpenSwipeIndex, 0, animate);
        qpOpenSwipeIndex = null;
    }
    // "Tapping anywhere outside an open card... snaps the card back" - a document-level listener
    // rather than a per-card blur/outside-click check, same pattern as closeQpBarMenu below.
    // a11y: closes an open swipe card when tapping elsewhere - harmless and reversible, not an activation (WCAG 2.5.2)
    document.addEventListener('pointerdown', (e) => {
        if (qpOpenSwipeIndex === null) return;
        const openBoxEl = document.querySelector(`#qpBlocks [data-qp-block-index="${qpOpenSwipeIndex}"]`);
        if (openBoxEl && !openBoxEl.contains(e.target)) qpCloseOpenSwipe();
    });

    // Vertical reordering, scoped strictly to the grab handle (only rendered once there are 2+ bars -
    // see qpBlockBoxHtml). Single-step swap (qpMoveBarUp/Down), same as the menu's own Move up/down -
    // this refactor is about where the gesture is allowed to start, not building a full drag-to-
    // arbitrary-position sortable list. wireVerticalDragHandle (shared with Flow's own
    // wireFlowBlockGrabHandle) owns the actual gesture/animation handoff.
    function wireQpBarGrabHandle(handleEl, boxEl, index) {
        wireVerticalDragHandle(handleEl, boxEl, QP_REORDER_THRESHOLD_PX,
            () => qpMoveBarUp(index), () => qpMoveBarDown(index), '.qp-block-surface');
    }

    // Horizontal swipe-to-reveal delete. Doesn't touch anything (no transform, no preventDefault)
    // until the gesture actually locks into "this is a horizontal swipe" (>30px horizontal travel
    // while vertical travel is still <15px) - a clearly-vertical drag before that point is treated as
    // a scroll attempt and left alone entirely, letting touch-action:pan-y do its job.
    function wireQpBarSwipe(boxEl, index) {
        const surfaceEl = boxEl.querySelector('.qp-block-surface');
        let startX = 0, startY = 0, tracking = false, locked = false, abandoned = false;

        function currentBaseOffset() { return qpOpenSwipeIndex === index ? -QP_SWIPE_OPEN_PX : 0; }

        function onMove(e) {
            if (!tracking || abandoned) return;
            const dx = e.clientX - startX;
            const dy = e.clientY - startY;
            if (!locked) {
                if (Math.abs(dx) > QP_SWIPE_LOCK_X_PX && Math.abs(dy) < QP_SWIPE_LOCK_Y_MAX_PX) {
                    locked = true;
                    // Only one card open at a time - starting a fresh swipe elsewhere closes any other.
                    if (qpOpenSwipeIndex !== null && qpOpenSwipeIndex !== index) qpCloseOpenSwipe(false);
                } else if (Math.abs(dy) >= QP_SWIPE_LOCK_Y_MAX_PX) {
                    abandoned = true; // a scroll, not a swipe - stop tracking, never transform
                    return;
                } else {
                    return; // not enough travel yet either way
                }
            }
            e.preventDefault();
            const offset = Math.min(0, Math.max(-QP_SWIPE_OPEN_PX, currentBaseOffset() + dx));
            swipeTo(surfaceEl, offset, false, true);
        }
        function onUp(e) {
            if (!tracking) return;
            tracking = false;
            document.removeEventListener('pointermove', onMove);
            document.removeEventListener('pointerup', onUp);
            if (!locked) return;
            const dx = e.clientX - startX;
            const finalOffset = Math.min(0, Math.max(-QP_SWIPE_OPEN_PX, currentBaseOffset() + dx));
            if (Math.abs(finalOffset) > QP_SWIPE_SNAP_THRESHOLD_PX) {
                qpSetSwipeOffset(index, -QP_SWIPE_OPEN_PX, true);
                qpOpenSwipeIndex = index;
            } else {
                qpSetSwipeOffset(index, 0, true);
                if (qpOpenSwipeIndex === index) qpOpenSwipeIndex = null;
            }
        }
        // a11y: only records where a swipe/drag gesture starts - nothing activates on press (WCAG 2.5.2)
        boxEl.addEventListener('pointerdown', (e) => {
            if (e.target.closest(QP_SWIPE_EXCLUDE_SELECTOR)) return;
            startX = e.clientX;
            startY = e.clientY;
            tracking = true;
            locked = false;
            abandoned = false;
            document.addEventListener('pointermove', onMove);
            document.addEventListener('pointerup', onUp);
        });
        // Tapping the revealed delete button deletes - swiping left never deletes on its own on
        // release, only opens the reveal (per the ticket: "Swiping left must not delete immediately").
        boxEl.querySelector('[data-qp-delete-btn]')?.addEventListener('click', (e) => {
            e.stopPropagation();
            qpOpenSwipeIndex = null;
            qpDeleteBar(index);
        });
        // ML-80: the dead-end-delete swap above (qpBlockBoxHtml) renders this instead of the normal
        // delete button when Bar 1 is the only bar.
        boxEl.querySelector('[data-qp-reset-all-btn]')?.addEventListener('click', (e) => {
            e.stopPropagation();
            qpOpenSwipeIndex = null;
            qpResetAllBars();
        });
    }

    document.getElementById('qpAddBlockBtn')?.addEventListener('click', () => {
        const last = qpBlocks[qpBlocks.length - 1];
        qpAnimateBlocksChange(() => {
            qpBlocks.push(last ? { ...last, _uid: ++qpUidCounter } : qpNewBlock());
        });
        // ML-154 follow-up: scrolls to the "+ Add bar" button itself, not just the new bar box above
        // it - scrolling only the box left the button that landed it there just out of view below the
        // fold, defeating the point if you wanted to add another straight after.
        document.getElementById('qpAddBlockBtn')?.scrollIntoView({ behavior: scrollMotion(), block: 'end' });
        qpMarkUnsaved();
        qpSyncAfterBlocksChanged();
    });

    // --- Per-bar options menu (Move up/down, Duplicate, Delete) - one shared floating menu
    // repositioned against whichever bar's 3-dot button was tapped, same pattern as Blocks' own
    // openMetroBlkTileMenu. Move up/down/Delete are hidden (not just disabled) when they don't apply -
    // with only one bar, index 0 is simultaneously "first" and "last" and the list "can't shrink
    // further", so all three hide on their own and only Duplicate is left, matching the request
    // exactly without a separate one-bar special case. ---
    let qpBarMenuTargetIndex = null;

    window.openQpBarMenu = function(btnEl, index) {
        const menu = document.getElementById('qpBarMenu');
        if (!menu) return;
        closeAllMetroPopupMenus();
        qpBarMenuTargetIndex = index;
        const total = qpBlocks.length;
        document.getElementById('qpBarMenuMoveUp')?.classList.toggle('hidden-group', index === 0);
        document.getElementById('qpBarMenuMoveDown')?.classList.toggle('hidden-group', index === total - 1);
        document.getElementById('qpBarMenuDelete')?.classList.toggle('hidden-group', total <= 1);
        // ML-80: only ever offered from Bar 1's own menu, regardless of how many bars exist.
        document.getElementById('qpBarMenuResetAll')?.classList.toggle('hidden-group', index !== 0);

        const btnRect = btnEl.getBoundingClientRect();
        menu.classList.add('show');
        const menuWidth = menu.offsetWidth;
        const menuHeight = menu.offsetHeight;
        let left = btnRect.right - menuWidth;
        left = Math.max(8, Math.min(left, window.innerWidth - menuWidth - 8));
        let top = btnRect.bottom + 4;
        top = Math.min(top, window.innerHeight - menuHeight - 8);
        placeAt(menu, left, top);
    };
    function closeQpBarMenu() {
        document.getElementById('qpBarMenu')?.classList.remove('show');
    }
    document.addEventListener('click', closeQpBarMenu);

    document.getElementById('qpBarMenuMoveUp')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const i = qpBarMenuTargetIndex;
        closeQpBarMenu();
        if (i !== null) qpMoveBarUp(i);
    });
    document.getElementById('qpBarMenuMoveDown')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const i = qpBarMenuTargetIndex;
        closeQpBarMenu();
        if (i !== null) qpMoveBarDown(i);
    });
    // Puts an exact copy at the END of the list, not right after the source (per the request) -
    // regardless of where the source bar sits.
    document.getElementById('qpBarMenuDuplicate')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const i = qpBarMenuTargetIndex;
        closeQpBarMenu();
        const source = i === null ? null : qpBlocks[i];
        if (!source) return;
        qpAnimateBlocksChange(() => {
            qpBlocks.push({ ...source, _uid: ++qpUidCounter });
        });
        qpMarkUnsaved();
        qpSyncAfterBlocksChanged();
    });
    document.getElementById('qpBarMenuDelete')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const i = qpBarMenuTargetIndex;
        closeQpBarMenu();
        if (i !== null) qpDeleteBar(i);
    });
    document.getElementById('qpBarMenuResetAll')?.addEventListener('click', (e) => {
        e.stopPropagation();
        closeQpBarMenu();
        qpResetAllBars();
    });

    // --- Playback (simpler than a Flow's since there's
    // no lead-in to special-case, and no separate play-queue array either: qpBlocks IS the queue,
    // read live, so an edit to a block's fields (bpm/time signature/bar count) is reflected
    // immediately without any separate "rebuild the queue" step - see qpSyncAfterBlocksChanged for
    // the one thing that DOES need explicit handling: keeping qpPlayIndex in range after an add/
    // delete changes how many blocks there are.) ---
    let qpPlayIndex = 0;
    let qpClicksPlayedInBlock = 0;

    // Reuses Blocks' own meter table (metroBlkMeterInfo/METRO_BLK_METER_TABLE) rather than
    // reinventing it - it's already generic over any { numerator, denominator }, not tied to
    // a Flow block's own shape.
    function qpMeterInfo(block) {
        return metroBlkMeterInfo({ ...qpBlockTimeSig(block), isLeadIn: false });
    }
    function qpBeatsPerBarFor(block) {
        return qpMeterInfo(block).macroBeatsPerBar;
    }
    // Sub-beats mode is a playback-only overlay, same idea as Rehearse's own flowSubBeatsMode/
    // metroBlkSubdivideOverride - one setting applies across the whole sequence, not stored per block.
    let qpSubBeatsMode = 'off';
    let qpSubdivideOverride = null;
    function qpSubFactorFor(block) {
        if (!block || qpSubBeatsMode === 'off') return 1;
        if (qpSubBeatsMode === 'fixed' && qpSubdivideOverride) return qpSubdivideOverride;
        return qpMeterInfo(block).subdivisionFactor;
    }

    // "Bar X of Y" here means which bar in the whole list is current (qpPlayIndex/qpBlocks.length) -
    // not a within-block repeat count like Blocks' own "x of y bars" (every Quick Play bar is always
    // exactly 1 bar, no repeat, so that reading was always trivially "1 of 1" and never actually told
    // you anything). Word-first ("Bar 1 of 4") rather than number-first ("1 of 4 bar") to match the
    // block boxes' own "Bar N" heading - if Flow ever wants an equivalent for its own setups, "Block X
    // of Y" would sit alongside this same way.
    // ML-172: bar identification leads now - knowing "which bar am I on" matters more at a glance
    // than the time signature/tempo that follow it.
    function qpBlockLabel(block) {
        return `Bar ${qpPlayIndex + 1} of ${qpBlocks.length} · ${qpBlockTimeSigLabel(block)} · ${block.bpm} bpm`;
    }

    function applyQpBlockToPlayer(block) {
        qpPlayer.setConductorBpm(block.bpm);
        qpPlayer.setConductorBeatsPerBar(qpBeatsPerBarFor(block));
        qpPlayer.setNotesPerBeat(qpSubFactorFor(block));
        qpPlayer.setSubdivisionFactor(1);
        qpPlayer.setLowPitch(false);
    }

    function jumpQpToIndex(index) {
        qpPlayIndex = index;
        qpClicksPlayedInBlock = 0;
        if (!qpBlocks.length) return;
        const block = qpBlocks[index];
        applyQpBlockToPlayer(block);
        qpPlayer.resetToBarStart();
    }

    // The only thing an add/delete needs beyond re-rendering: qpPlayIndex has to stay a valid index
    // into the (now different-length) qpBlocks array. Skipped entirely while playing, same reasoning
    // as Rehearse's rebuilt play queue - an edit made in the background while a sequence is
    // sounding shouldn't yank the current block out from under it.
    function qpSyncAfterBlocksChanged() {
        qpPlayIndex = Math.min(qpPlayIndex, qpBlocks.length - 1);
        if (!qpPlayer.isPlaying()) jumpQpToIndex(qpPlayIndex);
        renderQuickPlayRows();
    }

    function advanceQp() {
        let next = qpPlayIndex + 1;
        if (next >= qpBlocks.length) next = 0;
        jumpQpToIndex(next);
        setTimeout(renderQuickPlayRows, 130);
    }

    // No mid-block label refresh needed any more - "Bar X of Y" only ever changes at a block
    // boundary (qpPlayIndex advancing), which advanceQp's own renderQuickPlayRows call already
    // covers. Every Quick Play block is exactly 1 bar, so there's no in-between "2 of 4 bars" state
    // to track within a single block the way Blocks' own repeat count needs.
    function onQpBeat(beatInfo) {
        const block = qpBlocks[qpPlayIndex];
        if (!block) return;
        const subFactor = qpSubFactorFor(block);
        flashTierDot('qpRow0Dots', beatInfo.clickIndexInBar);

        // ML-155: pan the row to keep the current beat in view once there are too many circles to fit
        // (same "camera clamp" metroScrollFollow does for Rehearse's row, onFlowBeat) - this
        // was wired up for Blocks but never ported to Quick Play, so the lit dot just marched off the
        // right edge with nothing bringing it back into view. Same totalBaseClicks+1 basis renderQuickPlayRows
        // lays the dots out on, so the math can't drift out of step with where they actually are.
        if (beatInfo.isConductorBeat) {
            const totalBaseClicks = beatInfo.conductorBeatsPerBar * subFactor;
            const nextIndex = (beatInfo.conductorBeatIndex + 1) % beatInfo.conductorBeatsPerBar;
            const trackUnit = 100 / (totalBaseClicks + 1);
            const trackLeftPct = (k) => k * trackUnit + trackUnit / 2;
            metroScrollFollow('qpRow0Viewport', 'qpRow0Content', trackLeftPct(beatInfo.conductorBeatIndex * subFactor), trackLeftPct(nextIndex * subFactor), beatInfo.secondsPerConductorBeat);
        }

        qpClicksPlayedInBlock++;
        const targetClicks = block.barCount * qpBeatsPerBarFor(block) * subFactor;
        const isFinalClickOfBlock = qpClicksPlayedInBlock >= targetClicks;
        if (isFinalClickOfBlock) advanceQp();
    }
    qpPlayer.onBeat(onQpBeat);

    function renderQuickPlayRows() {
        if (!qpBlocks.length) return;
        const block = qpBlocks[qpPlayIndex];
        const subFactor = qpSubFactorFor(block);
        const label = block ? qpBlockLabel(block) : '';
        const labelEl = document.getElementById('qpRow0Label');
        if (labelEl) labelEl.innerText = label;

        const beatsPerBar = block ? qpBeatsPerBarFor(block) : 4;
        const totalBaseClicks = beatsPerBar * subFactor;
        // Laid out over totalBaseClicks+1 slots, not totalBaseClicks - reserves room for the
        // connecting line's own one-slot extension past the last dot (connectMetroBlkDotsWithTrack),
        // same reasoning as renderFlowPlaybackRow.
        const trackLeftPct = (k) => k * (100 / (totalBaseClicks + 1)) + (100 / (totalBaseClicks + 1)) / 2;
        const endLeftStyle = metroLeftStyle(trackLeftPct(totalBaseClicks));
        buildMetroDotRow('qpRow0Dots', totalBaseClicks, subFactor, false, trackLeftPct);
        metroApplyDisplayWidth('qpRow0Viewport', 'qpRow0Content', totalBaseClicks + 1);
        connectMetroBlkDotsWithTrack('qpRow0Dots', endLeftStyle);
        if (!qpPlayer.isPlaying()) resetMetroScrollPosition('qpRow0Content');

        renderQpSubdivideLabel();
        renderQpActiveBoxHighlight();
    }

    // Highlights whichever bar box is actually sounding right now, only while playing (not on a
    // plain pause/stop) - cheap, no rebuild, just toggles a class on whichever box already matches
    // qpPlayIndex, same idea as Rehearse's active tile.
    function renderQpActiveBoxHighlight() {
        const playing = qpPlayer.isPlaying();
        document.querySelectorAll('#qpBlocks [data-qp-block-index]').forEach(el => {
            el.classList.toggle('qp-block-playing', playing && Number(el.dataset.qpBlockIndex) === qpPlayIndex);
        });
    }

    window.addEventListener('resize', () => {
        const view = document.getElementById('quickPlayView');
        if (isShown(view)) renderQuickPlayRows();
    });

    // --- Transport ---
    function updateQPPlayIcon() {
        const icon = document.getElementById('qpPlayIcon');
        if (icon) icon.innerText = qpPlayer.isPlaying() ? 'pause' : 'play_arrow';
    }

    // Builds a local "YYYY-MM-DD HH:MM:SS" timestamp (wall-clock local time, not UTC) - used as the
    // history row's name in place of a chosen one, per the request ("date and time, local, including
    // seconds").
    function qpLocalTimestamp() {
        const d = new Date();
        const pad = (n) => String(n).padStart(2, '0');
        return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
    }

    // Which history row (if any) is currently loaded into Quick Play - null means "nothing loaded,
    // a fresh Play writes a brand new history entry" (the original behaviour). Set by the Load button
    // below, cleared by qpClearLoadedHistory (the X next to the loaded name) and qpResetAllBars.
    let qpLoadedHistoryId = null;
    let qpLoadedHistoryName = null;
    // Whether qpBlocks has changed since it was loaded (qpMarkUnsaved flips this on) - drives the
    // "- edited" tag and its undo icon.
    let qpLoadedHistoryEdited = false;
    // A plain-data snapshot of the blocks exactly as loaded (no _uid - qpRevertToLoadedHistory
    // assigns fresh ones) - kept around for the whole time something's loaded, regardless of any
    // auto-save/overwrite that happens in between, so "revert" always means "back to what was
    // actually loaded", not "back to whatever's currently on the server".
    let qpLoadedHistorySnapshot = null;

    // Shows the loaded entry's name under the "Bars" title, with the "- edited"/undo pair and the X
    // that clears it - hidden entirely whenever nothing is loaded.
    function renderQpLoadedHistoryLabel() {
        const row = document.getElementById('qpLoadedHistoryRow');
        if (!row) return;
        row.classList.toggle('hidden-group', qpLoadedHistoryId === null);
        const nameEl = document.getElementById('qpLoadedHistoryName');
        if (nameEl && qpLoadedHistoryName !== null) nameEl.innerText = qpFormatHistoryLabel(qpLoadedHistoryName);
        document.getElementById('qpLoadedHistoryEditedTag')?.classList.toggle('hidden-group', !qpLoadedHistoryEdited);
        document.getElementById('qpLoadedHistoryUndoBtn')?.classList.toggle('hidden-group', !qpLoadedHistoryEdited);
    }

    // Reverts to exactly what was loaded (qpLoadedHistorySnapshot), even if an auto-save already
    // overwrote the history row itself with edited bars in the meantime - the next Play re-saves this
    // reverted state back over that (qpSavedThisRun reset, same as any other change).
    function qpRevertToLoadedHistory() {
        if (!qpLoadedHistorySnapshot) return;
        qpAnimateBlocksChange(() => {
            qpBlocks = qpLoadedHistorySnapshot.map(b => ({ ...b, _uid: ++qpUidCounter }));
        });
        qpLoadedHistoryEdited = false;
        qpSavedThisRun = false;
        renderQpLoadedHistoryLabel();
        qpSyncAfterBlocksChanged();
    }
    document.getElementById('qpLoadedHistoryUndoBtn')?.addEventListener('click', qpRevertToLoadedHistory);

    function qpBlocksPayload() {
        return qpBlocks.map(b => ({
            barCount: b.barCount,
            bpm: b.bpm,
            noteValue: b.noteSelected,
            timeSignatureId: b.timeSigValue?.startsWith('public:') ? Number(b.timeSigValue.split(':')[1]) : null,
            accountTimeSignatureId: b.timeSigValue?.startsWith('custom:') ? Number(b.timeSigValue.split(':')[1]) : null
        }));
    }

    // Writes the current blocks in as one history row - fire-and-forget (a failed write must never
    // block playback actually starting). Runs once per "fresh" play (see qpSavedThisRun), not on every
    // pause/resume toggle. Once a history row is loaded (qpLoadedHistoryId), this overwrites that same
    // row's bars instead of creating a new entry every time - "override the saved version", per the
    // request - until it's cleared (qpClearLoadedHistory) or the bars are reset (qpResetAllBars).
    async function saveQuickPlayHistory() {
        if (!isFeatureEnabled('metronome_history')) return; // ML-345: no history for this account type
        try {
            if (qpLoadedHistoryId !== null) {
                await API.metronomeBlocks.quickPlay.overwriteHistory(qpLoadedHistoryId, qpBlocksPayload());
            } else {
                await API.metronomeBlocks.quickPlay.save(qpLocalTimestamp(), qpBlocksPayload());
            }
        } catch (error) {
            showWarningToast('Error saving play history: ' + error.message);
        }
    }

    // --- ML-163: "Save to flow" - turns the current bar-by-bar qpBlocks into a Flow's multi-bar
    // blocks. Quick Play has no merge concept of its own (every qpBlocks entry is exactly one bar),
    // so this confirms how consecutive identical bars (same timeSigValue/noteSelected/bpm) will
    // combine before a Flow (and its blocks) actually get created - see the modal's own HTML comment.
    // qpMergeBlocks is the editable working state once the modal's open; qpBlocks itself is never
    // touched by any of this. ---
    let qpMergeBlocks = [];
    let qpMergeFlatMode = false;
    // Which pending (freshly split-out) block's Merge above/below choice is currently showing - at
    // most one at a time, closed again by qpMergeToggleMenu or whenever the list re-renders after an
    // edit elsewhere.
    let qpMergeOpenMenuKey = null;
    let qpMergeKeyCounter = 0;

    function qpBarsMatch(a, b) {
        return a.timeSigValue === b.timeSigValue && a.noteSelected === b.noteSelected && a.bpm === b.bpm;
    }
    // bpm is stored raw (same meaning as a segment's own bpm column - see qpBlocksPayload above); the
    // number shown to the user throughout the rest of Quick Play is that raw value re-expressed per
    // the block's own beat unit, so this screen matches rather than showing an unfamiliar figure.
    function qpMergeDisplayedBpm(bar) {
        return Math.round(bar.bpm / (qpBlockNoteFraction(bar.noteSelected) * qpBlockDenominator(bar)));
    }
    function qpMergeBarFieldsHtml(bar) {
        const noteType = METRO_NOTE_TYPES.find(t => t.key === bar.noteSelected);
        return `<span>${escapeHtml(metroSegTimeSigLabelFor(bar.timeSigValue) || '—')}</span>` +
            `<span>${escapeHtml(noteType ? noteType.label : '')}</span>` +
            `<span>${qpMergeDisplayedBpm(bar)} bpm</span>`;
    }

    // Default grouping: greedily merges each bar into the previous block whenever it matches, which
    // is the "minimise the number of blocks" default per the request - every group starts as a single
    // real block, never "pending" (that flag only ever applies to a block created by splitting one
    // apart below).
    function qpComputeDefaultMergeBlocks() {
        const result = [];
        qpBlocks.forEach((b, i) => {
            const bar = { timeSigValue: b.timeSigValue, noteSelected: b.noteSelected, bpm: b.bpm, barNumber: i + 1 };
            const last = result[result.length - 1];
            if (last && qpBarsMatch(last.bars[last.bars.length - 1], bar)) {
                last.bars.push(bar);
            } else {
                result.push({ key: ++qpMergeKeyCounter, bars: [bar], pending: false });
            }
        });
        return result;
    }

    function openQpMergeBarsModal() {
        qpMergeBlocks = qpComputeDefaultMergeBlocks();
        qpMergeFlatMode = !qpMergeBlocks.some(g => g.bars.length > 1);
        qpMergeOpenMenuKey = null;
        renderQpMergeBarsModal();
        showModal('qpMergeBarsModal');
    }

    // Peels one specific bar out of a multi-bar block into a new block of its own, right where it
    // was - "as it leaves the bar", not just the group as a whole, so any bar in the middle of a
    // block can be split out, not only the first/last. Whatever's left on either side stays merged
    // (it was already identical to itself). The new block starts "pending" - its own connector
    // becomes the Merge above/below choice (qpMergeToggleMenu/qpMergeInto) rather than a plain arrow.
    function qpMergeSplitBar(groupKey, barIndex) {
        const gi = qpMergeBlocks.findIndex(g => g.key === groupKey);
        if (gi === -1) return;
        const group = qpMergeBlocks[gi];
        const bar = group.bars[barIndex];
        if (!bar) return;
        const leftBars = group.bars.slice(0, barIndex);
        const rightBars = group.bars.slice(barIndex + 1);
        const newGroups = [];
        if (leftBars.length) newGroups.push({ key: ++qpMergeKeyCounter, bars: leftBars, pending: false });
        newGroups.push({ key: ++qpMergeKeyCounter, bars: [bar], pending: true });
        if (rightBars.length) newGroups.push({ key: ++qpMergeKeyCounter, bars: rightBars, pending: false });
        qpMergeBlocks.splice(gi, 1, ...newGroups);
        qpMergeOpenMenuKey = null;
        renderQpMergeBarsModal();
    }

    function qpMergeToggleMenu(groupKey) {
        qpMergeOpenMenuKey = qpMergeOpenMenuKey === groupKey ? null : groupKey;
        renderQpMergeBarsModal();
    }

    // Always an explicit tap on one specific direction - never auto-picked, even when only one of
    // "above"/"below" is actually possible, so re-merging is always a deliberate choice rather than
    // something that just happens on its own.
    function qpMergeInto(groupKey, direction) {
        const gi = qpMergeBlocks.findIndex(g => g.key === groupKey);
        if (gi === -1) return;
        const group = qpMergeBlocks[gi];
        const bar = group.bars[0];
        if (direction === 'above') {
            const target = qpMergeBlocks[gi - 1];
            if (!target || !qpBarsMatch(target.bars[target.bars.length - 1], bar)) return;
            target.bars.push(bar);
        } else {
            const target = qpMergeBlocks[gi + 1];
            if (!target || !qpBarsMatch(target.bars[0], bar)) return;
            target.bars.unshift(bar);
        }
        qpMergeBlocks.splice(gi, 1);
        qpMergeOpenMenuKey = null;
        renderQpMergeBarsModal();
    }

    function renderQpMergeGroupHtml(group, gi) {
        const isMultiBar = group.bars.length > 1;
        const barsHtml = group.bars.map((bar, bi) => `
            <div class="qp-merge-bar-row">
                <span class="qp-merge-bar-num">Bar ${bar.barNumber}</span>
                <span class="qp-merge-bar-fields">${qpMergeBarFieldsHtml(bar)}</span>
                ${isMultiBar ? `<button type="button" class="qp-merge-split-btn" data-qp-merge-split data-group-key="${group.key}" data-bar-index="${bi}" aria-label="Bar ${bar.barNumber} merges into Block ${gi + 1} - tap to split into its own block"><span class="material-symbols-outlined">link</span></button>` : ''}
            </div>
        `).join('');

        let connector;
        if (group.pending) {
            const above = qpMergeBlocks[gi - 1];
            const below = qpMergeBlocks[gi + 1];
            const canAbove = !!(above && qpBarsMatch(above.bars[above.bars.length - 1], group.bars[0]));
            const canBelow = !!(below && qpBarsMatch(below.bars[0], group.bars[0]));
            const menuOpen = qpMergeOpenMenuKey === group.key;
            connector = `<button type="button" class="qp-merge-branch-btn" data-qp-merge-toggle-menu data-group-key="${group.key}" aria-label="Bar ${group.bars[0].barNumber} is its own block - tap for merge options"><span class="material-symbols-outlined">call_split</span></button>` +
                (menuOpen ? `<div class="qp-merge-menu">
                    <button type="button" class="qp-merge-menu-btn" data-qp-merge-into data-group-key="${group.key}" data-direction="above" ${canAbove ? '' : 'disabled title="Different time signature, beat note or tempo"'}>Merge above</button>
                    <button type="button" class="qp-merge-menu-btn" data-qp-merge-into data-group-key="${group.key}" data-direction="below" ${canBelow ? '' : 'disabled title="Different time signature, beat note or tempo"'}>Merge below</button>
                </div>` : '');
        } else {
            connector = '<span class="material-symbols-outlined qp-merge-arrow" aria-hidden="true">arrow_forward</span>';
        }

        const repBar = group.bars[0];
        return `<div class="qp-merge-group">
            <div class="qp-merge-bars">${barsHtml}</div>
            <div class="qp-merge-connector">${connector}</div>
            <div class="qp-merge-block">
                <div class="qp-merge-block-head"><span>Block ${gi + 1}</span><span class="qp-merge-block-badge">${group.bars.length} ${group.bars.length === 1 ? 'bar' : 'bars'}</span></div>
                <div class="qp-merge-block-fields">${qpMergeBarFieldsHtml(repBar)}</div>
            </div>
        </div>`;
    }

    function wireQpMergeGroupControls() {
        const list = document.getElementById('qpMergeBarsList');
        list.querySelectorAll('[data-qp-merge-split]').forEach(btn => {
            btn.addEventListener('click', () => qpMergeSplitBar(Number(btn.dataset.groupKey), Number(btn.dataset.barIndex)));
        });
        list.querySelectorAll('[data-qp-merge-toggle-menu]').forEach(btn => {
            btn.addEventListener('click', () => qpMergeToggleMenu(Number(btn.dataset.groupKey)));
        });
        list.querySelectorAll('[data-qp-merge-into]').forEach(btn => {
            if (btn.disabled) return;
            btn.addEventListener('click', () => qpMergeInto(Number(btn.dataset.groupKey), btn.dataset.direction));
        });
    }

    function renderQpMergeBarsModal() {
        const subtitle = document.getElementById('qpMergeBarsSubtitle');
        const list = document.getElementById('qpMergeBarsList');

        if (qpMergeFlatMode) {
            const n = qpBlocks.length;
            subtitle.textContent = `Every bar is different, so nothing can merge - ${n} bar${n === 1 ? '' : 's'} will become ${n} block${n === 1 ? '' : 's'}.`;
            list.innerHTML = qpBlocks.map((b, i) => `
                <div class="qp-merge-flat-row">
                    <span class="qp-merge-bar-num">Bar ${i + 1}</span>
                    <span class="qp-merge-bar-fields">${qpMergeBarFieldsHtml({ timeSigValue: b.timeSigValue, noteSelected: b.noteSelected, bpm: b.bpm })}</span>
                </div>
            `).join('');
            return;
        }

        const blockCount = qpMergeBlocks.length;
        subtitle.textContent = `${qpBlocks.length} bars will become ${blockCount} block${blockCount === 1 ? '' : 's'}.`;
        list.innerHTML = qpMergeBlocks.map((group, gi) => renderQpMergeGroupHtml(group, gi)).join('');
        wireQpMergeGroupControls();
    }

    // Creates the flow, then adds one block per current group/bar in order - sequential, not
    // Promise.all, since each block's order_index is assigned server-side as "current max + 1"
    // (createFlowBlock) and would race if these ran in parallel.
    async function qpMergeSaveToFlow() {
        const saveBtn = document.getElementById('qpMergeBarsSaveBtn');
        saveBtn.disabled = true;
        try {
            const flow = await API.flows.create({});
            // POST /flows always seeds one default starter block (ML-179 follow-up, "never a truly
            // empty flow") - fine for "Create your own", but here the merged bars ARE the content, so
            // that placeholder has to go before adding them, not sit stranded ahead of Block 1.
            const seededBlocks = await API.flows.blocks.list(flow.id);
            for (const seeded of seededBlocks) await API.flows.blocks.delete(seeded.id);
            const groups = qpMergeFlatMode
                ? qpBlocks.map(b => ({ bars: [{ timeSigValue: b.timeSigValue, noteSelected: b.noteSelected, bpm: b.bpm }] }))
                : qpMergeBlocks;
            for (const group of groups) {
                const bar = group.bars[0];
                await API.flows.blocks.create(flow.id, {
                    barCount: group.bars.length,
                    bpm: bar.bpm,
                    noteValue: bar.noteSelected,
                    timeSignatureId: bar.timeSigValue?.startsWith('public:') ? Number(bar.timeSigValue.split(':')[1]) : null,
                    accountTimeSignatureId: bar.timeSigValue?.startsWith('custom:') ? Number(bar.timeSigValue.split(':')[1]) : null
                });
            }
            hideModal('qpMergeBarsModal');
            if (document.getElementById('qpMergeGoToFlowsToggle').checked) {
                currentFlowId = flow.id;
                flowEditMode = 'edit';
                await goToFlowPlayView(flow.id);
            } else {
                showSuccessToast(`Saved to "${flow.title}"`);
            }
        } catch (error) {
            showWarningToast('Error saving to flow: ' + error.message);
        } finally {
            saveBtn.disabled = false;
        }
    }

    document.getElementById('qpSaveToFlowBtn')?.addEventListener('click', openQpMergeBarsModal);
    document.getElementById('qpMergeBarsCancelBtn')?.addEventListener('click', () => {
        hideModal('qpMergeBarsModal');
    });
    document.getElementById('qpMergeBarsSaveBtn')?.addEventListener('click', qpMergeSaveToFlow);

    // --- ML-34: "Show history" - browse/rename/favourite/delete past history rows and load one
    // back into qpBlocks. qpLocalTimestamp's stored format ("YYYY-MM-DD HH:MM:SS") is kept as-is
    // (an earlier, deliberate choice - see its own comment above) - this only reformats it for
    // display, so a still-default-named row reads as "17 Sep 2026 14:32" here without touching what's
    // actually stored or renamed rows (which show exactly what the user typed).
    function qpFormatHistoryLabel(name) {
        const d = new Date(String(name).replace(' ', 'T'));
        if (isNaN(d.getTime())) return name;
        const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        const pad = (n) => String(n).padStart(2, '0');
        return `${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
    }

    // ML-34 follow-up: "Duplicate" names itself "<name> (copy)", or "<name> (copy 2)"/"(copy 3)"/...
    // if that's already taken - e.g. duplicating a favourite more than once. Always computed off the
    // original's own base name (stripping any existing "(copy...)" suffix first), not the source
    // being duplicated, so duplicating a copy chains "(copy)", "(copy 2)", "(copy 3)" rather than
    // compounding into "(copy) (copy)".
    function qpBaseHistoryName(name) {
        return String(name).replace(/\s*\(copy(?:\s+\d+)?\)\s*$/i, '');
    }
    function qpNextDuplicateName(name) {
        const base = qpBaseHistoryName(name);
        const existing = new Set(qpHistoryData.map(r => r.name));
        if (!existing.has(`${base} (copy)`)) return `${base} (copy)`;
        let n = 2;
        while (existing.has(`${base} (copy ${n})`)) n++;
        return `${base} (copy ${n})`;
    }

    let qpHistoryData = [];
    let qpHistoryFilter = 'all';
    let qpHistorySelectedId = null;
    let qpHistoryMenuTargetId = null;

    async function loadQpHistory() {
        const list = document.getElementById('qpHistoryList');
        if (list) list.innerHTML = 'Loading…';
        try {
            qpHistoryData = await API.metronomeBlocks.quickPlay.history();
            renderQpHistoryList();
        } catch (error) {
            showWarningToast('Error loading history: ' + error.message);
        }
    }

    function renderQpHistoryList() {
        const list = document.getElementById('qpHistoryList');
        if (!list) return;
        const rows = qpHistoryFilter === 'favorites' ? qpHistoryData.filter(r => r.isFavorite) : qpHistoryData;
        // ML-383: the list stops at this account type's limit (favourites included) - say so under it
        const limit = appData.limits?.metronome_history_shown;
        const note = document.getElementById('qpHistoryLimitNote');
        if (note) {
            note.textContent = Number.isFinite(limit) ? `Limited to the last ${limit} metronome play${limit === 1 ? '' : 's'}` : '';
            setShown(note, Number.isFinite(limit));
        }
        if (!rows.length) {
            list.innerHTML = `<p class="text-muted">${qpHistoryFilter === 'favorites' ? 'No favourites yet.' : 'No history yet - play something for a couple of seconds and it\'ll show up here.'}</p>`;
        } else {
            list.innerHTML = rows.map(r => `
                <div class="history-item clickable qp-history-item${r.id === qpHistorySelectedId ? ' qp-history-item-selected' : ''}" data-qp-history-id="${r.id}">
                    <div role="button" tabindex="0" class="qp-history-item-body" data-qp-history-select>
                        ${r.isFavorite ? '<span class="material-symbols-outlined qp-history-star" aria-hidden="true">star</span>' : ''}
                        <div>
                            <strong>${escapeHtml(qpFormatHistoryLabel(r.name))}</strong>
                            <div class="text-sm text-muted">${r.blockCount} bar${r.blockCount === 1 ? '' : 's'}</div>
                        </div>
                    </div>
                    <button type="button" class="list-item-menu-btn" data-qp-history-menu-btn aria-label="Options for ${escapeHtml(qpFormatHistoryLabel(r.name))}" aria-haspopup="menu" aria-expanded="false"><span class="material-symbols-outlined">more_vert</span></button>
                </div>
            `).join('');
        }
        list.querySelectorAll('[data-qp-history-select]').forEach(el => {
            el.addEventListener('click', () => {
                const id = Number(el.closest('.qp-history-item').dataset.qpHistoryId);
                qpHistorySelectedId = qpHistorySelectedId === id ? null : id;
                renderQpHistoryList();
            });
        });
        list.querySelectorAll('[data-qp-history-menu-btn]').forEach(btn => {
            btn.addEventListener('click', (e) => {
                e.stopPropagation();
                const id = Number(btn.closest('.qp-history-item').dataset.qpHistoryId);
                openQpHistoryItemMenu(e.currentTarget, id);
            });
        });
        const loadBtn = document.getElementById('qpHistoryLoadBtn');
        if (loadBtn) loadBtn.disabled = qpHistorySelectedId === null || !rows.some(r => r.id === qpHistorySelectedId);
    }

    function openQpHistoryItemMenu(btnEl, id) {
        const menu = document.getElementById('qpHistoryItemMenu');
        if (!menu) return;
        closeAllMetroPopupMenus();
        qpHistoryMenuTargetId = id;
        const entry = qpHistoryData.find(r => r.id === id);
        // Only the label changes - the item's icon (ML-285) sits beside it in the same button.
        const favText = document.getElementById('qpHistoryItemFavoriteText');
        if (favText) favText.textContent = entry?.isFavorite ? 'Remove from favourites' : 'Set as favourite';

        const btnRect = btnEl.getBoundingClientRect();
        menu.classList.add('show');
        const menuWidth = menu.offsetWidth;
        const menuHeight = menu.offsetHeight;
        let left = btnRect.right - menuWidth;
        left = Math.max(8, Math.min(left, window.innerWidth - menuWidth - 8));
        let top = btnRect.bottom + 4;
        top = Math.min(top, window.innerHeight - menuHeight - 8);
        placeAt(menu, left, top);
    }
    function closeQpHistoryItemMenu() {
        document.getElementById('qpHistoryItemMenu')?.classList.remove('show');
    }
    document.addEventListener('click', closeQpHistoryItemMenu);

    document.getElementById('qpHistoryItemRename')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const id = qpHistoryMenuTargetId;
        closeQpHistoryItemMenu();
        const entry = qpHistoryData.find(r => r.id === id);
        if (!entry) return;
        showPromptModal('Rename', qpFormatHistoryLabel(entry.name), async (newName) => {
            if (!newName) return;
            try {
                await API.metronomeBlocks.setups.rename(id, newName);
                await loadQpHistory();
            } catch (error) {
                showWarningToast('Error renaming: ' + error.message);
            }
        });
    });
    document.getElementById('qpHistoryItemFavoriteToggle')?.addEventListener('click', async (e) => {
        e.stopPropagation();
        const id = qpHistoryMenuTargetId;
        closeQpHistoryItemMenu();
        const entry = qpHistoryData.find(r => r.id === id);
        if (!entry) return;
        try {
            await API.metronomeBlocks.setups.setFavorite(id, !entry.isFavorite);
            await loadQpHistory();
        } catch (error) {
            showWarningToast('Error updating favourite: ' + error.message);
        }
    });
    document.getElementById('qpHistoryItemDelete')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const id = qpHistoryMenuTargetId;
        closeQpHistoryItemMenu();
        const entry = qpHistoryData.find(r => r.id === id);
        if (!entry) return;
        showConfirmModal('Delete history entry', `Delete "${qpFormatHistoryLabel(entry.name)}" from history?`, async () => {
            try {
                await API.metronomeBlocks.setups.delete(id);
                if (qpHistorySelectedId === id) qpHistorySelectedId = null;
                await loadQpHistory();
            } catch (error) {
                showWarningToast('Error deleting: ' + error.message);
            }
        });
    });
    // ML-34 follow-up: most useful on a favourite - keeps it pristine while you iterate on a variant.
    document.getElementById('qpHistoryItemDuplicate')?.addEventListener('click', async (e) => {
        e.stopPropagation();
        const id = qpHistoryMenuTargetId;
        closeQpHistoryItemMenu();
        const entry = qpHistoryData.find(r => r.id === id);
        if (!entry) return;
        try {
            const created = await API.metronomeBlocks.quickPlay.duplicateHistory(id, qpNextDuplicateName(entry.name));
            qpHistorySelectedId = created.id;
            await loadQpHistory();
            showSuccessToast('Duplicated');
        } catch (error) {
            showWarningToast('Error duplicating: ' + error.message);
        }
    });

    document.querySelectorAll('#qpHistoryFilterRadios input[type="radio"]').forEach(r => {
        r.addEventListener('change', (e) => {
            qpHistoryFilter = e.target.value;
            renderQpHistoryList();
        });
    });

    function openQpHistoryModal() {
        qpHistorySelectedId = null;
        qpHistoryFilter = 'all';
        document.getElementById('qpHistoryFilterAll').checked = true;
        showModal('qpHistoryModal');
        loadQpHistory();
    }
    document.getElementById('qpShowHistoryBtn')?.addEventListener('click', openQpHistoryModal);
    document.getElementById('qpHistoryCloseBtn')?.addEventListener('click', () => {
        hideModal('qpHistoryModal');
    });

    // Maps a saved setup's full segment DTOs (server shape - see toSegmentDto) back into qpBlocks'
    // own flatter { timeSigValue, bpm, noteSelected, barCount } shape (qpNewBlock). Quick Play has no
    // lead-in concept, but a history row never has one anyway (createQuickPlaySetup always inserts
    // is_lead_in = false) - the filter is just defensive.
    function qpBlocksFromSegments(segments) {
        return segments.filter(s => !s.isLeadIn).map(s => ({
            _uid: ++qpUidCounter,
            timeSigValue: s.timeSignatureId ? `public:${s.timeSignatureId}` : (s.accountTimeSignatureId ? `custom:${s.accountTimeSignatureId}` : qpDefaultTimeSigValue()),
            bpm: s.bpm,
            noteSelected: s.noteValue || 'crotchet',
            barCount: s.barCount || 1
        }));
    }

    document.getElementById('qpHistoryLoadBtn')?.addEventListener('click', async () => {
        const id = qpHistorySelectedId;
        if (id === null) return;
        try {
            const setup = await API.metronomeBlocks.setups.get(id);
            const blocks = qpBlocksFromSegments(setup.segments);
            if (!blocks.length) return showWarningToast('That history entry has no bars to load.');
            qpBlocks = blocks;
            qpLoadedHistoryId = setup.id;
            qpLoadedHistoryName = setup.name;
            qpLoadedHistoryEdited = false;
            qpLoadedHistorySnapshot = blocks.map(b => ({ timeSigValue: b.timeSigValue, bpm: b.bpm, noteSelected: b.noteSelected, barCount: b.barCount }));
            renderQpLoadedHistoryLabel();
            // Not qpMarkUnsaved() - loading isn't itself an edit, it just needs the same "next Play
            // writes fresh" reset qpMarkUnsaved would otherwise also give it.
            qpSavedThisRun = false;
            qpSyncAfterBlocksChanged();
            renderQuickPlayBlocks();
            hideModal('qpHistoryModal');
            showSuccessToast('Loaded from history');
        } catch (error) {
            showWarningToast('Error loading history entry: ' + error.message);
        }
    });

    // The X next to the loaded name (ML-34 follow-up) - unlinks from that history row and resets to
    // the same single-default-bar starting point as qpResetAllBars, but with no confirmation: nothing
    // is destroyed (the loaded entry is untouched in history, and the in-progress bars weren't
    // themselves ever saved anywhere), it's just clearing what's currently loaded. qpMarkUnsaved
    // already means the usual 2-second-played gate applies again before anything new is written.
    function qpClearLoadedHistory() {
        qpLoadedHistoryId = null;
        qpLoadedHistoryName = null;
        qpLoadedHistoryEdited = false;
        qpLoadedHistorySnapshot = null;
        renderQpLoadedHistoryLabel();
        qpAnimateBlocksChange(() => { qpBlocks = [qpNewBlock()]; });
        qpMarkUnsaved();
        qpSyncAfterBlocksChanged();
    }
    document.getElementById('qpLoadedHistoryClearBtn')?.addEventListener('click', qpClearLoadedHistory);

    // ML-34: only actually written to history once played continuously for a couple of seconds - a
    // Play immediately followed by Stop/Pause shouldn't leave a "nothing really happened" row behind.
    // Not cleared on pause: if it fires while paused, the isPlaying() check below just skips (no
    // save, no reschedule) and the next fresh Play press starts a new one (qpHistorySaveTimer is null
    // again by then) - simpler than tracking accumulated play time across pauses.
    let qpHistorySaveTimer = null;
    function playQuickPlay() {
        if (!qpBlocks.length) return showWarningToast('Add at least one time block first.');
        // Pushes whatever's currently in qpBlocks[qpPlayIndex] into the engine fresh - covers the case
        // where that block's own bpm/time-signature was edited while paused/stopped (fields are read
        // live everywhere else, but the engine's own internal tempo/beatsPerBar only updates when
        // explicitly told to). Doesn't touch position, so this is always safe to call, resume included.
        applyQpBlockToPlayer(qpBlocks[qpPlayIndex]);
        window.Usage?.begin('metronome'); // ML-22: finished after 30 seconds played
        if (!qpSavedThisRun && !qpHistorySaveTimer) {
            qpHistorySaveTimer = setTimeout(() => {
                qpHistorySaveTimer = null;
                if (qpPlayer.isPlaying() && !qpSavedThisRun) {
                    qpSavedThisRun = true;
                    saveQuickPlayHistory();
                }
            }, 2000);
        }
        qpPlayer.play();
        updateQPPlayIcon();
        syncWakeLock();
        renderQuickPlayRows();
    }

    function pauseQuickPlay() {
        qpPlayer.pause();
        window.Usage?.end('metronome');
        updateQPPlayIcon();
        syncWakeLock();
        renderQpActiveBoxHighlight();
    }

    function resetQuickPlay() {
        jumpQpToIndex(0);
        qpMarkUnsaved();
        renderQuickPlayRows();
    }

    // ML-146: a plain Reset button sits next to Play now (matching Blocks' own transport row) -
    // press-and-hold on Play still works too, via the same shared setupPlayButtonHoldReset Blocks'
    // own Play button uses (see the METRONOME ENGINE section).
    setupPlayButtonHoldReset('qpPlayBtn',
        () => { if (qpPlayer.isPlaying()) pauseQuickPlay(); else playQuickPlay(); },
        resetQuickPlay
    );
    document.getElementById('qpResetBtn')?.addEventListener('click', resetQuickPlay);

    // --- Sub-beats popup (ported from Blocks' own metroBlkSubdivideModal - own state, own modal, same
    // reasoning as qpPlayer being its own player instance) ---
    // Fixed 2-16 range, no tiered expansion (unlike the BPM slider above) - sub beats past 16 has no
    // real musical meaning here, so the slider just hard-caps rather than growing into a wider range.
    const QP_SUBDIVIDE_MIN = 2;
    const QP_SUBDIVIDE_MAX = 16;
    let qpSubdividePopupValue = QP_SUBDIVIDE_MIN;

    function renderQpSubdivideLabel() {
        const block = qpBlocks[qpPlayIndex];
        const display = block ? (qpSubFactorFor(block) <= 1 ? '0' : String(qpSubFactorFor(block))) : '0';
        const lbl = document.getElementById('qpSubdivideLbl');
        if (lbl) lbl.innerText = display;
        // ML-165: same "call out Auto specifically" treatment as Blocks' own renderMetroBlkSubdivideLabels.
        const unitLbl = document.getElementById('qpSubdivideUnitLbl');
        if (unitLbl) unitLbl.innerText = qpSubBeatsMode === 'auto' ? 'auto sub beats' : 'sub beats';
    }

    function renderQpSubdividePopupSlider() {
        const pct = ((qpSubdividePopupValue - QP_SUBDIVIDE_MIN) / (QP_SUBDIVIDE_MAX - QP_SUBDIVIDE_MIN)) * 100;
        document.getElementById('qpSubdivideSliderFill').style.setProperty('--pct', `${pct}%`);
        const thumb = document.getElementById('qpSubdivideSliderThumb');
        thumb.style.setProperty('--pct', `${pct}%`);
        thumb.setAttribute('aria-valuenow', qpSubdividePopupValue);
        thumb.setAttribute('aria-valuemax', QP_SUBDIVIDE_MAX);
        document.getElementById('qpSubdivideSliderMaxLbl').innerText = QP_SUBDIVIDE_MAX;
        document.getElementById('qpSubdividePopupValue').innerText = qpSubdividePopupValue;
    }
    function setQpSubdividePopupValue(v) {
        qpSubdividePopupValue = Math.min(QP_SUBDIVIDE_MAX, Math.max(QP_SUBDIVIDE_MIN, Math.round(v)));
        renderQpSubdividePopupSlider();
    }
    setupHoldStepper(document.getElementById('qpSubdivideMinus'), -1, (amount) => setQpSubdividePopupValue(qpSubdividePopupValue + amount));
    setupHoldStepper(document.getElementById('qpSubdividePlus'), 1, (amount) => setQpSubdividePopupValue(qpSubdividePopupValue + amount));
    setupSliderInteraction(document.getElementById('qpSubdivideSliderTrack'), document.getElementById('qpSubdivideSliderThumb'), {
        onDragRatio: (ratio) => setQpSubdividePopupValue(QP_SUBDIVIDE_MIN + ratio * (QP_SUBDIVIDE_MAX - QP_SUBDIVIDE_MIN)),
        onArrowStep: (dir) => setQpSubdividePopupValue(qpSubdividePopupValue + dir)
    });
    makeSliderReadoutEditable('qpSubdividePopupValue', () => qpSubdividePopupValue, (v) => setQpSubdividePopupValue(v), { label: 'Sub beats', min: QP_SUBDIVIDE_MIN, max: QP_SUBDIVIDE_MAX });

    document.getElementById('qpSubdivideBtn')?.addEventListener('click', () => {
        document.getElementById('qpSubdivideOff').checked = qpSubBeatsMode === 'off';
        document.getElementById('qpSubdivideAuto').checked = qpSubBeatsMode === 'auto';
        document.getElementById('qpSubdivideFixed').checked = qpSubBeatsMode === 'fixed';
        document.getElementById('qpSubdivideBpmBox').classList.toggle('hidden-group', qpSubBeatsMode !== 'fixed');
        setQpSubdividePopupValue(qpSubdivideOverride || QP_SUBDIVIDE_MIN);
        showModal('qpSubdivideModal');
    });
    document.querySelectorAll('input[name="qpSubdivideOnOff"]').forEach(radio => {
        radio.addEventListener('change', () => {
            document.getElementById('qpSubdivideBpmBox').classList.toggle('hidden-group', radio.value !== 'fixed');
        });
    });
    document.getElementById('qpSubdivideCancelBtn')?.addEventListener('click', () => {
        hideModal('qpSubdivideModal');
    });
    document.getElementById('qpSubdivideSaveBtn')?.addEventListener('click', () => {
        qpSubBeatsMode = document.querySelector('input[name="qpSubdivideOnOff"]:checked')?.value || 'off';
        qpSubdivideOverride = qpSubBeatsMode === 'fixed' ? qpSubdividePopupValue : null;
        hideModal('qpSubdivideModal');
        const block = qpBlocks[qpPlayIndex];
        if (block) applyQpBlockToPlayer(block);
        renderQuickPlayRows();
    });

    // --- Play speed popup (ported from Blocks' - own state, own modal, admin-managed preset list) ---
    let qpSpeedPercent = 100;
    function renderQpSpeedLabel() {
        document.getElementById('qpSpeedLbl').innerText = `${qpSpeedPercent}%`;
    }
    function setQpSpeedPercent(p) {
        qpSpeedPercent = Math.min(1000, Math.max(1, p));
        qpPlayer.setSpeedPercent(qpSpeedPercent);
        renderQpSpeedLabel();
        const block = qpBlocks[qpPlayIndex];
        if (block) applyQpBlockToPlayer(block);
        renderQuickPlayRows();
    }
    async function loadQuickPlayPlaybackSpeeds() {
        try {
            const speeds = await API.metronomeBlocks.playbackSpeeds.list();
            const container = document.getElementById('qpSpeedOptions');
            if (container) container.innerHTML = speeds.map(p => `<button type="button" class="metroBlk-timesig-opt" data-value="${p}">${p}%</button>`).join('');
            document.querySelectorAll('#qpSpeedOptions .metroBlk-timesig-opt').forEach(btn => {
                btn.classList.toggle('selected', Number(btn.dataset.value) === qpSpeedPercent);
            });
        } catch (error) {
            showWarningToast('Error loading playback speeds: ' + error.message);
        }
    }
    document.getElementById('qpSpeedBtn')?.addEventListener('click', () => {
        document.querySelectorAll('#qpSpeedOptions .metroBlk-timesig-opt').forEach(btn => {
            btn.classList.toggle('selected', Number(btn.dataset.value) === qpSpeedPercent);
        });
        showModal('qpSpeedModal');
    });
    document.getElementById('qpSpeedOptions')?.addEventListener('click', (e) => {
        const btn = e.target.closest('.metroBlk-timesig-opt');
        if (!btn) return;
        setQpSpeedPercent(Number(btn.dataset.value));
        hideModal('qpSpeedModal');
    });
    renderQpSpeedLabel();

    // --- Volume (ported from Blocks' - own state, no calibration section, headphone delay is the one
    // shared setting via metroState.latencyMs/qpPlayerRef). Mute is just volume 0 (ML-148) -
    // qpVolumeBeforeMute remembers the last non-zero value so unmuting restores it. ---
    let qpVolume = 80;
    let qpVolumeBeforeMute = 80;
    function renderQpVolumeSlider() {
        const fill = document.getElementById('qpVolumeFill');
        const thumb = document.getElementById('qpVolumeThumb');
        if (!fill || !thumb) return;
        fill.style.setProperty('--pct', `${qpVolume}%`);
        thumb.style.setProperty('--pct', `${qpVolume}%`);
        thumb.setAttribute('aria-valuenow', qpVolume);
        const valueEl = document.getElementById('qpVolumeValue');
        if (valueEl) valueEl.innerText = `${qpVolume}%`;
        const muted = qpVolume === 0;
        document.getElementById('qpMuteIcon').innerText = muted ? 'volume_off' : 'volume_up';
        document.getElementById('qpMuteBtn')?.setAttribute('aria-pressed', String(muted));
        document.getElementById('qpVolumeRow')?.classList.toggle('is-muted', muted);
    }
    // `force` (ML-148) bypasses the test-click throttle - see playVolumeTestClick.
    function setQpVolume(v, force = false) {
        qpVolume = Math.round(Math.min(100, Math.max(0, v)));
        if (qpVolume > 0) qpVolumeBeforeMute = qpVolume;
        qpPlayer.setVolume(qpVolume / 100);
        renderQpVolumeSlider();
        playVolumeTestClick(qpPlayer, force);
    }
    setupSliderInteraction(document.getElementById('qpVolumeTrack'), document.getElementById('qpVolumeThumb'), {
        onDragRatio: (ratio) => setQpVolume(ratio * 100),
        onArrowStep: (dir) => setQpVolume(qpVolume + dir * 5),
        onRelease: () => playVolumeTestClick(qpPlayer, true)
    });
    setupHoldStepper('qpVolumeMinus', -1, (amount) => setQpVolume(qpVolume + amount, true));
    setupHoldStepper('qpVolumePlus', 1, (amount) => setQpVolume(qpVolume + amount, true));
    makeSliderReadoutEditable('qpVolumeValue', () => qpVolume, (v) => setQpVolume(v, true), { label: 'Volume', min: 0, max: 100 });
    document.getElementById('qpMuteBtn')?.addEventListener('click', () => {
        setQpVolume(qpVolume > 0 ? 0 : (qpVolumeBeforeMute || 80), true);
    });
    document.getElementById('qpVolumeBtn')?.addEventListener('click', () => {
        renderQpVolumeSlider();
        showModal('qpVolumeModal');
    });
    function closeQpVolumePopup() {
        hideModal('qpVolumeModal');
    }
    document.getElementById('qpVolumeCloseBtn')?.addEventListener('click', closeQpVolumePopup);
    // ML-148: tapping the dark scrim outside the card dismisses it too - see the matching Blocks
    // comment on metroBlkVolumeModal.
    document.getElementById('qpVolumeModal')?.addEventListener('click', (e) => {
        if (e.target === e.currentTarget) closeQpVolumePopup();
    });
    renderQpVolumeSlider();

    // ========================================
    // TUNER
    // ========================================
    const NOTE_NAMES_SHARP = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
    const NOTE_NAMES_FLAT = ['C', 'D♭', 'D', 'E♭', 'E', 'F', 'G♭', 'G', 'A♭', 'A', 'B♭', 'B'];
    // Fixed-do chromatic solfège - same sharps/flats spelling choice (TUNER_USE_FLATS_KEY) as the
    // letter names above, just a different alphabet for the same 12 pitch classes.
    const NOTE_NAMES_SOLFEGE_SHARP = ['Do', 'Di', 'Re', 'Ri', 'Mi', 'Fa', 'Fi', 'Sol', 'Si', 'La', 'Li', 'Ti'];
    const NOTE_NAMES_SOLFEGE_FLAT = ['Do', 'Ra', 'Re', 'Me', 'Mi', 'Fa', 'Se', 'Sol', 'Le', 'La', 'Te', 'Ti'];
    const A4_MIDI = 69;
    // The tuning reference itself - adjustable (TUNER_A4_KEY, the A4 popup further below), not the
    // fixed 440 it used to be. Read by tunerFreqToMidi, so this is a real input to the pitch math, not
    // just a display label - every note reading in the app (main Tuner, Flow/Metronome mini tuner)
    // resolves against whatever this is currently set to. Seeded from localStorage right here (not
    // just inside startTuner, unlike tunerTransposition/tunerShowConcert/etc.) since the mini tuner shares
    // tunerFreqToMidi too and can be opened without the full Tuner view ever having run first.
    const TUNER_A4_KEY = 'tunerA4Freq';
    let tunerA4Freq = parseInt(localStorage.getItem(TUNER_A4_KEY), 10) || 440;

    // written = concert + offset semitones (mod 12) - the standard band transposition conventions
    // (Bb = 2: clarinet/trumpet/tenor sax..., Eb = 9: alto/bari sax..., F = 7: horn). Octave isn't
    // tracked, only the pitch class, since that's all a tuner readout needs. Both the full Tuner view
    // and (since ML-225) the Flow/Metronome mini tuner store this as the offset itself.
    const TUNER_ZONE_CENTS = 15; // "in tune" green-zone half-width
    const TUNER_USE_FLATS_KEY = 'tunerUseFlats';
    // The full Tuner view's transposition, as a semitone offset (0-11, C=0) rather than one of only 4
    // named presets - real transposing instruments exist well beyond Bb/Eb/F (D trumpet, A clarinet...),
    // and the underlying math (writtenMidi = concertMidi + offset) already only ever needed the number.
    // Seeded from localStorage right here (not just inside startTuner, unlike tunerShowConcert/etc.)
    // for the same reason as tunerA4Freq above - shared with the mini tuner's own seeding, further down.
    const TUNER_TRANSPOSITION_KEY = 'tunerTransposition';
    let tunerTransposition = parseInt(localStorage.getItem(TUNER_TRANSPOSITION_KEY), 10) || 0;
    // Whether the "right now" card's Concert column shows at all - off collapses to just the written/
    // instrument note, same single-column layout as when the transposition IS 0 (concert pitch itself,
    // see updateTunerTranspositionLabel).
    const TUNER_SHOW_CONCERT_KEY = 'tunerShowConcert';
    // 'letters' (C, D, E...) or 'solfege' (Do, Re, Mi...) - read by tunerMidiToName, so this affects
    // every note readout app-wide (main Tuner, and the Flow/Metronome mini tuner), not just this view.
    const TUNER_NOTE_STYLE_KEY = 'tunerNoteStyle';
    // Small Hz readout under each visible note (both columns show the same value - Hz is the actual
    // physical frequency, which transposition only relabels, never changes) and a small octave suffix
    // right after each big note letter. Both off by default.
    const TUNER_SHOW_HZ_KEY = 'tunerShowHz';
    const TUNER_SHOW_OCTAVE_KEY = 'tunerShowOctave';
    let tunerShowConcert = true;
    // Read at load, not only when the tuner opens (startTuner) - ML-257: the transposition names on the
    // Settings screen follow it too, before the tuner has ever been opened this session.
    let tunerNoteStyle = (() => { try { return localStorage.getItem(TUNER_NOTE_STYLE_KEY) || 'letters'; } catch (e) { return 'letters'; } })();
    let tunerShowHz = false;
    let tunerShowOctave = false;
    // ML-181: pitch/dynamics history strips (full Tuner view only) - a fixed-length ring buffer of
    // { cents, inTune, note, db } samples, one pushed roughly every TUNER_HISTORY_SAMPLE_MS (10/sec,
    // not every animation frame - 60 DOM bars/sec would be both unreadable and wasteful to re-render).
    // cents/note/inTune are null on a silent sample (see pushTunerHistorySample) so the pitch strip
    // shows a gap rather than a fabricated flat line; db is always real, even during silence, since
    // "how loud is nothing" is still meaningful for the dynamics strip.
    //
    // BUFFER vs VIEW (pause/rewind follow-up): tunerHistory itself retains a much longer window
    // (BUFFER) than what's ever shown at once (VIEW). Live, the visible slice is always the most
    // recent VIEW_MS of the buffer, same "last few seconds scrolling by" look as before. Pausing
    // (setTunerPaused) stops new samples from being appended and reveals a scrub slider that walks
    // tunerScrubOffsetSamples back through the already-captured BUFFER, one VIEW_MS-wide slice at a
    // time - so a whole phrase can be reviewed after playing it, not just the instant it happened.
    const TUNER_HISTORY_BUFFER_MS = 30000;
    const TUNER_HISTORY_VIEW_MS = 4000;
    const TUNER_HISTORY_SAMPLE_MS = 100;
    let tunerHistory = [];
    let tunerHistoryLastSampleAt = 0;
    // Resets to null on every silent gap (not just on tuner open) - so the same note attacking again
    // after a pause still gets its own label, rather than being treated as "no change" from before
    // the pause.
    let tunerHistoryLastNote = null;
    let tunerPaused = false;
    // Samples back from the live edge (0 = live/most recent). Only meaningful while tunerPaused -
    // always reset to 0 on resume so unpausing always snaps back to live.
    let tunerScrubOffsetSamples = 0;
    // ML-103 follow-up: how a fermata sustained hold sounds (tone/silent/count) - a playback
    // preference, not per-block, so it lives here rather than in the block editor. Same
    // localStorage-only pattern as the tuner defaults above (device-local, no account sync) -
    // nothing in the metronome player reads this yet (fermata playback itself isn't wired into the
    // audio engine), this is just where a future playback engine should look.
    const FERMATA_PLAYBACK_MODE_KEY = 'fermataPlaybackMode';
    // Below this, tunerAutoCorrelate gives up on pitch-tracking (there's nothing to lock onto) - also
    // used by renderTunerPitch to decide whether a no-pitch sample is genuine silence (dynamics should
    // show nothing too) vs a loud-but-untracked moment like a breath attack or key click (dynamics
    // should still show what was actually happening, even though pitch couldn't).
    const TUNER_QUIET_RMS = 0.01;

    function tunerFreqToMidi(freq) { return A4_MIDI + 12 * Math.log2(freq / tunerA4Freq); }

    // ML-181: dBFS relative to a full-scale sample of 1.0 - the same RMS math tunerAutoCorrelate
    // already computes internally (just to gate itself on quiet input), exposed here separately for
    // the dynamics history strip. Math.max floors it at 1e-4 (-80dB) so true digital silence doesn't
    // produce -Infinity.
    function tunerRmsToDb(rms) { return 20 * Math.log10(Math.max(rms, 1e-4)); }

    // Just the note letter/accidental - no octave number, per the tuner's simplified readout.
    function tunerMidiToName(midi) {
        const rounded = Math.round(midi);
        const useFlats = localStorage.getItem(TUNER_USE_FLATS_KEY) === 'true';
        const useSolfege = tunerNoteStyle === 'solfege';
        const names = useSolfege
            ? (useFlats ? NOTE_NAMES_SOLFEGE_FLAT : NOTE_NAMES_SOLFEGE_SHARP)
            : (useFlats ? NOTE_NAMES_FLAT : NOTE_NAMES_SHARP);
        return names[((rounded % 12) + 12) % 12];
    }

    // ML-225: a transposition is stored as how far written sits ABOVE concert (written = concert +
    // offset), so the instrument's key - the concert pitch its written C sounds - is that offset
    // counted DOWN from C (B♭ = 2, E♭ = 9, F = 7). Every label used to name the offset itself as the
    // key, which showed a B♭ instrument as "D instrument". Follows the sharps/flats setting (ML-224),
    // with a proper ♯ to match ♭, and - ML-257 - the note-name setting too: in solfège the instrument
    // is named in solfège ("Te instrument", "Concert pitch (Do)"), matching the notes the tuner shows.
    function tunerInstrumentKeyName(offset) {
        const useFlats = localStorage.getItem(TUNER_USE_FLATS_KEY) === 'true';
        const key = (((12 - offset) % 12) + 12) % 12;
        const names = tunerNoteStyle === 'solfege'
            ? (useFlats ? NOTE_NAMES_SOLFEGE_FLAT : NOTE_NAMES_SOLFEGE_SHARP)
            : (useFlats ? NOTE_NAMES_FLAT : NOTE_NAMES_SHARP);
        return names[key].replace('#', '♯');
    }
    // All 12 transpositions as stored offsets, in instrument-key order (C, C♯/D♭, D...) - the one
    // list the Settings select, the Tuner's Transposition popup and the Flow/Metronome mini tuner's
    // Instrument popup all show, so the three can't drift apart again.
    function tunerTranspositionOffsetsByKey() {
        return Array.from({ length: 12 }, (_, key) => (12 - key) % 12);
    }
    function tunerTranspositionLabel(offset) {
        return offset === 0 ? `Concert pitch (${tunerInstrumentKeyName(0)})` : `${tunerInstrumentKeyName(offset)} instrument`;
    }
    // Rebuilt rather than static HTML so the names follow the sharps/flats setting (ML-224) - called
    // on startup, on opening Settings, and whenever sharps/flats changes (renderTunerSettingsModal).
    function renderTunerTranspositionSetting() {
        const select = document.getElementById('tunerTranspositionSetting');
        if (!select) return;
        select.innerHTML = tunerTranspositionOffsetsByKey()
            .map(o => `<option value="${o}">${tunerTranspositionLabel(o)}</option>`).join('');
        select.value = String(parseInt(localStorage.getItem(TUNER_TRANSPOSITION_KEY), 10) || 0);
    }

    // Autocorrelation-based pitch detection (ACF2+ style): far more stable than zero-crossing for a
    // single monophonic instrument close to the mic. Returns -1 when the signal is too quiet to trust.
    function tunerAutoCorrelate(buf, sampleRate) {
        const SIZE = buf.length;
        let rms = 0;
        for (let i = 0; i < SIZE; i++) rms += buf[i] * buf[i];
        rms = Math.sqrt(rms / SIZE);
        if (rms < TUNER_QUIET_RMS) return -1;

        let r1 = 0, r2 = SIZE - 1;
        const threshold = 0.2;
        for (let i = 0; i < SIZE / 2; i++) { if (Math.abs(buf[i]) < threshold) { r1 = i; break; } }
        for (let i = 1; i < SIZE / 2; i++) { if (Math.abs(buf[SIZE - i]) < threshold) { r2 = SIZE - i; break; } }

        const trimmed = buf.slice(r1, r2);
        const newSize = trimmed.length;
        if (newSize < 2) return -1;
        const c = new Array(newSize).fill(0);
        for (let lag = 0; lag < newSize; lag++) {
            for (let i = 0; i < newSize - lag; i++) c[lag] += trimmed[i] * trimmed[i + lag];
        }

        let d = 0;
        while (d < newSize - 1 && c[d] > c[d + 1]) d++;
        let maxVal = -1, maxPos = -1;
        for (let i = d; i < newSize; i++) {
            if (c[i] > maxVal) { maxVal = c[i]; maxPos = i; }
        }
        if (maxPos <= 0) return -1;

        // Parabolic interpolation around the peak for sub-sample precision.
        let T0 = maxPos;
        const x1 = c[T0 - 1] || 0, x2 = c[T0], x3 = c[T0 + 1] || 0;
        const a = (x1 + x3 - 2 * x2) / 2;
        const b = (x3 - x1) / 2;
        if (a) T0 = T0 - b / (2 * a);

        return T0 > 0 ? sampleRate / T0 : -1;
    }

    // Standalone pitch-detection engine, structured the same way as the metronome player above
    // (own audio graph, own lifecycle, exposes start/stop/onPitch) so it can be dropped into another
    // view later as an add-in without rewriting the mic/analysis plumbing.
    function createTunerEngine() {
        let audioCtx = null;
        let ownsAudioCtx = false; // ML-132 test: false when audioCtx is a shared context borrowed via start()'s sharedAudioCtx - stop() must never close a context this engine doesn't own
        let analyser = null;
        let micStream = null;
        let dataArray = null;
        let rafId = null;
        const listeners = [];

        function tick() {
            analyser.getFloatTimeDomainData(dataArray);
            const freq = tunerAutoCorrelate(dataArray, audioCtx.sampleRate);
            // ML-181: rms is computed again here (tunerAutoCorrelate already computes its own copy
            // internally, just to gate itself on quiet input) rather than threading it out of that
            // function's return value - keeps tunerAutoCorrelate's own return type (a plain number,
            // freq or -1) untouched, and this is one cheap pass over a 2048-sample buffer, not
            // something worth the coupling to save.
            let rmsSum = 0;
            for (let i = 0; i < dataArray.length; i++) rmsSum += dataArray[i] * dataArray[i];
            const rms = Math.sqrt(rmsSum / dataArray.length);
            listeners.forEach(cb => cb(freq, rms));
            rafId = requestAnimationFrame(tick);
        }

        return {
            // ML-132 test: sharedAudioCtx, when passed, is an already-live AudioContext (currently
            // the metronome player behind whichever tuner-capable view is open - see
            // activeMetroPlayerForTuner/getAudioContext) that this engine's mic graph is routed
            // through INSTEAD of creating its own. The idea being tested: Chrome's Android audio-focus
            // ducking triggers between two separate AudioContext instances, so collapsing the
            // metronome synth and the mic input into one shared graph may avoid it - see the ML-132
            // comment thread just below for the (currently Chrome-Android-ineffective) audioSession
            // attempt this sits alongside. The full Tuner view has no metronome behind it, so it
            // always calls start() with no argument and keeps today's own-context behaviour.
            async start(sharedAudioCtx) {
                if (audioCtx) return true;
                // ML-132: on Android, opening a mic stream makes the OS itself ("audio focus")
                // duck other concurrently-playing audio, including the metronome's own separate
                // AudioContext - not something the getUserMedia constraints below can prevent (they
                // stop Chrome's own echo-cancel/gain processing from colouring the pitch reading,
                // a different concern). navigator.audioSession is the actual API for telling the OS
                // "this page intentionally plays and records together, don't duck" - set it before
                // requesting the mic, per the spec's own guidance, not after. Currently a no-op on
                // Chrome for Android (not yet implemented there as of this writing - see ML-132's
                // own comment thread), so this doesn't fully resolve the ticket's own report today,
                // but it's free/harmless and already fixes the same class of issue on Safari/iOS
                // (supported since 16.4) and whichever Chrome version eventually adds it.
                if ('audioSession' in navigator) {
                    try { navigator.audioSession.type = 'play-and-record'; } catch { /* unsupported type value on this browser - ignore */ }
                }
                try {
                    micStream = await navigator.mediaDevices.getUserMedia({
                        audio: { echoCancellation: false, noiseSuppression: false, autoGainControl: false }
                    });
                } catch (err) {
                    if ('audioSession' in navigator) {
                        try { navigator.audioSession.type = 'auto'; } catch { /* ignore */ }
                    }
                    return false;
                }
                if (sharedAudioCtx) {
                    audioCtx = sharedAudioCtx;
                    ownsAudioCtx = false;
                    if (audioCtx.state === 'suspended') audioCtx.resume();
                } else {
                    const Ctx = window.AudioContext || window.webkitAudioContext;
                    audioCtx = new Ctx();
                    ownsAudioCtx = true;
                }
                // AnalyserNode only, deliberately never connected on to audioCtx.destination - it
                // exists purely for tunerAutoCorrelate to read from, not to be heard. On a shared
                // context this matters even more than before: wiring the mic straight to destination
                // would feed it back into whatever the metronome side of the same graph is playing.
                const source = audioCtx.createMediaStreamSource(micStream);
                analyser = audioCtx.createAnalyser();
                analyser.fftSize = 2048;
                dataArray = new Float32Array(analyser.fftSize);
                source.connect(analyser);
                tick();
                return true;
            },
            stop() {
                if (rafId) cancelAnimationFrame(rafId);
                rafId = null;
                if (micStream) micStream.getTracks().forEach(t => t.stop());
                micStream = null;
                // A shared context is owned by whichever metronome player handed it out (see
                // getAudioContext) - it keeps running its own playback/prewarm lifecycle regardless of
                // this tuner session, so only close a context this engine created for itself.
                if (audioCtx && ownsAudioCtx) audioCtx.close();
                audioCtx = null;
                ownsAudioCtx = false;
                analyser = null;
                // Hands control back to the browser's own default session-type resolution once the
                // mic's no longer in use, rather than leaving 'play-and-record' pinned for the rest
                // of the page's life (e.g. plain metronome playback with the tuner closed should go
                // back to reading as ordinary 'playback', not still act like the record mode is live).
                if ('audioSession' in navigator) {
                    try { navigator.audioSession.type = 'auto'; } catch { /* ignore */ }
                }
            },
            isActive() { return !!audioCtx; },
            onPitch(cb) { listeners.push(cb); }
        };
    }

    const tunerEngine = createTunerEngine();

    // Also decides whether the "right now" card's Concert column is worth showing at all - it's
    // redundant whenever it would just repeat the other column, either because the transposition IS 0
    // (concert pitch, nothing to transpose) or because tunerShowConcert is off - so call this again
    // whenever any of those change (the Transposition tile group, the Sharps/flats and Note names tile
    // groups too since the label text depends on both of those, and the Show concert toggle), not just
    // when the transposition itself changes.
    function updateTunerTranspositionLabel() {
        const isConcert = tunerTransposition === 0;
        // Top card keeps saying "Concert" (not the bare note letter a non-zero transposition gets) -
        // "Concert" reads better than a bare "C" sitting above another "C" in the other column.
        document.getElementById('tunerInstrumentLabel').innerText =
            isConcert ? 'Concert' : `${tunerInstrumentKeyName(tunerTransposition)} instrument`;
        const concertCol = document.getElementById('tunerConcertCol');
        if (concertCol) concertCol.classList.toggle('hidden-group', isConcert || !tunerShowConcert);
    }

    // Show concert/Hz/octave live as 3 pill toggles in #tunerSettingsModal (opened off the cog on
    // #tunerCard) instead of 3 separate tap-to-open tile pickers - this just keeps both copies of each
    // one (the popup's own toggle and its Settings-screen counterpart) showing the current state,
    // called whenever the popup opens and isn't itself the thing that just changed.
    function syncTunerDisplayToggles() {
        const concertToggle = document.getElementById('tunerShowConcertToggle');
        const hzToggle = document.getElementById('tunerShowHzToggle');
        const octaveToggle = document.getElementById('tunerShowOctaveToggle');
        if (concertToggle) concertToggle.checked = tunerShowConcert;
        if (hzToggle) hzToggle.checked = tunerShowHz;
        if (octaveToggle) octaveToggle.checked = tunerShowOctave;
    }

    function renderTunerIdle() {
        document.getElementById('tunerNoteDisplay').innerText = '–';
        document.getElementById('tunerConcertDisplay').innerText = '–';
        document.getElementById('tunerNoteOctave').classList.add('hidden-group');
        document.getElementById('tunerConcertOctave').classList.add('hidden-group');
        document.getElementById('tunerNoteHz').classList.add('hidden-group');
        document.getElementById('tunerConcertHz').classList.add('hidden-group');
        document.getElementById('tunerNeedle').style.setProperty('--needle-pos', '50%');
        document.getElementById('tunerNeedle').classList.remove('in-tune');
        document.getElementById('tunerCard').classList.remove('in-tune', 'out-of-tune');
        const tuneEl = document.getElementById('tunerTuneState');
        if (tuneEl) tuneEl.innerText = 'Play a note';
        const announceEl = document.getElementById('tunerTuneAnnounce');
        if (announceEl) { announceEl.dataset.state = ''; announceEl.innerText = ''; }
        // ML-181: fresh history every time the tuner (re)opens - a previous session's trace lingering
        // on screen while nothing's been played yet this time would misrepresent what's live.
        tunerHistory = [];
        tunerHistoryLastSampleAt = 0;
        tunerHistoryLastNote = null;
        setTunerPaused(false);
        renderTunerHistoryGraphs();
    }

    // Appends one sample to the shared ring buffer and re-renders both strips from it - a full
    // innerHTML rebuild each time (only ~40 visible bars at once, at most 10 pushes/sec), same "just
    // re-render the list" convention the rest of this app already uses rather than incrementally
    // patching individual bar elements. Trims against the full BUFFER length, not the (shorter) VIEW -
    // see the TUNER_HISTORY_BUFFER_MS/VIEW_MS comment above.
    function pushTunerHistorySample(sample) {
        tunerHistory.push(sample);
        const maxSamples = Math.ceil(TUNER_HISTORY_BUFFER_MS / TUNER_HISTORY_SAMPLE_MS);
        if (tunerHistory.length > maxSamples) tunerHistory.shift();
        renderTunerHistoryGraphs();
    }

    // Freezes/unfreezes the history strips. The slider itself is always visible/rendered
    // (renderTunerScrubSlider, called from renderTunerHistoryGraphs) - this just flips whether it's
    // interactive (#tunerScrubSliderWrap.disabled) and, on resume, snaps back to the live edge.
    function setTunerPaused(paused) {
        tunerPaused = paused;
        const icon = document.getElementById('tunerPauseIcon');
        const btn = document.getElementById('tunerPauseBtn');
        if (btn) {
            btn.setAttribute('aria-pressed', String(paused));
            // Names the action the button performs NEXT (same convention as every other play/pause
            // toggle in this app, e.g. updateMetroBlkPlayIcon) - "Resume history" once already paused,
            // not a static "Pause history" that stops matching what tapping it actually does.
            btn.setAttribute('aria-label', paused ? 'Resume history' : 'Pause history');
        }
        if (icon) icon.innerText = paused ? 'play_arrow' : 'pause';
        tunerScrubOffsetSamples = 0; // resume live, or start a fresh pause right where the live view already was
        renderTunerHistoryGraphs();
    }
    document.getElementById('tunerPauseBtn')?.addEventListener('click', () => setTunerPaused(!tunerPaused));

    // Same shared slider component as the bpm/volume sliders elsewhere (.slider-track/.slider-fill/
    // .slider-thumb, setupSliderInteraction) rather than a native <input type=range>, so it matches
    // their exact look. Ratio runs left(0)=fully rewound to right(1)=live, opposite of
    // tunerScrubOffsetSamples itself (0=live) - inverted below. Guarded on tunerPaused since the
    // slider stays in the DOM (just visually disabled, #tunerScrubSliderWrap.disabled) rather than
    // being removed/hidden while live, and pointer-events:none doesn't stop a keyboard arrow event
    // reaching the still-focusable thumb.
    function tunerScrubMaxOffsetSamples() {
        const viewSamples = Math.ceil(TUNER_HISTORY_VIEW_MS / TUNER_HISTORY_SAMPLE_MS);
        return Math.max(0, tunerHistory.length - viewSamples);
    }
    setupSliderInteraction(document.getElementById('tunerScrubSliderTrack'), document.getElementById('tunerScrubSliderThumb'), {
        onDragRatio: (ratio) => {
            if (!tunerPaused) return;
            const maxOffsetSamples = tunerScrubMaxOffsetSamples();
            tunerScrubOffsetSamples = Math.round((1 - ratio) * maxOffsetSamples);
            renderTunerHistoryGraphs();
        },
        onArrowStep: (dir) => {
            if (!tunerPaused) return;
            const maxOffsetSamples = tunerScrubMaxOffsetSamples();
            // dir=1 is right/up (setupSliderInteraction) - right moves toward live, i.e. decreases offset.
            tunerScrubOffsetSamples = Math.min(maxOffsetSamples, Math.max(0, tunerScrubOffsetSamples - dir * 5));
            renderTunerHistoryGraphs();
        }
    });

    // maxOffsetSamples is passed in rather than recomputed - renderTunerHistoryGraphs already has it
    // from laying out the visible slice, and it must be the exact same value both places use or the
    // slider's position would disagree with what the graphs above it are actually showing.
    function renderTunerScrubSlider(maxOffsetSamples) {
        const fill = document.getElementById('tunerScrubSliderFill');
        const thumb = document.getElementById('tunerScrubSliderThumb');
        const wrap = document.getElementById('tunerScrubSliderWrap');
        const minLbl = document.getElementById('tunerScrubSliderMinLbl');
        if (!fill || !thumb) return;
        const pct = maxOffsetSamples > 0 ? ((maxOffsetSamples - tunerScrubOffsetSamples) / maxOffsetSamples) * 100 : 100;
        fill.style.setProperty('--pct', `${pct}%`);
        thumb.style.setProperty('--pct', `${pct}%`);
        const offsetSec = Math.round((tunerScrubOffsetSamples * TUNER_HISTORY_SAMPLE_MS) / 1000);
        thumb.setAttribute('aria-valuenow', String(offsetSec));
        const maxOffsetSec = Math.round((maxOffsetSamples * TUNER_HISTORY_SAMPLE_MS) / 1000);
        thumb.setAttribute('aria-valuemax', String(maxOffsetSec));
        // NOT maxOffsetSec - that's how far the thumb's own reference point (the visible window's
        // RIGHT edge) can travel, which undercounts by a whole view-width: once scrubbed all the way
        // left, the window's LEFT edge (what you can actually still see) reaches viewSamples further
        // back than maxOffsetSec alone suggests. tunerHistory.length is the true amount currently
        // buffered - grows with the session and naturally caps at TUNER_HISTORY_BUFFER_MS/1000 (30s,
        // matching the "(max 30s)" heading) once the ring buffer is full, without needing its own cap
        // here.
        if (minLbl) minLbl.innerText = `-${Math.round((tunerHistory.length * TUNER_HISTORY_SAMPLE_MS) / 1000)}s`;
        if (wrap) wrap.classList.toggle('disabled', !tunerPaused);
    }

    // Bipolar strip (cents, ±50, 0 in the middle) - see the .tuner-pitch-graph-bars/.tuner-history-bar*
    // CSS comment for why each sample is a flex "slot" wrapping an absolutely-positioned bar, rather
    // than the slot itself being the bar. Unipolar strip (dB, 0 at top/-60 at bottom, baseline at the
    // bottom) is simpler - flex items can just set their own height directly. Renders only the visible
    // VIEW_MS slice of the BUFFER (see tunerScrubOffsetSamples), not the whole retained buffer.
    function renderTunerHistoryGraphs() {
        const pitchEl = document.getElementById('tunerPitchGraphBars');
        const dynamicsEl = document.getElementById('tunerDynamicsBars');
        if (!pitchEl || !dynamicsEl) return;

        const viewSamples = Math.ceil(TUNER_HISTORY_VIEW_MS / TUNER_HISTORY_SAMPLE_MS);
        const maxOffset = Math.max(0, tunerHistory.length - viewSamples);
        if (tunerScrubOffsetSamples > maxOffset) tunerScrubOffsetSamples = maxOffset;
        const end = tunerHistory.length - tunerScrubOffsetSamples;
        const start = Math.max(0, end - viewSamples);
        const visible = tunerHistory.slice(start, end);
        // Every render lays out exactly viewSamples flex slots, padded with empty ones at the start
        // when the buffer hasn't filled up yet (only possible early in a session, or right after
        // renderTunerIdle resets it) - each flex:1 slot is then always the same width, rather than a
        // handful of samples stretching to fill the whole row the moment the tuner opens and then
        // visibly shrinking back down to normal width as the buffer fills. Padding slots render nothing
        // at all (no bar, no gap-dot - those mean "silence", not "no data yet").
        const padCount = Math.max(0, viewSamples - visible.length);
        const pitchPad = '<div class="tuner-history-bar-slot"></div>'.repeat(padCount);
        const dynamicsPad = '<div class="tuner-dynamics-bar"></div>'.repeat(padCount);

        // Note-attack labels sit above their bar by default, but two attacks close together in time
        // would stack their labels on top of each other there - alternate below whenever a label lands
        // within NOTE_LABEL_MIN_GAP_SAMPLES of the previous one, so a run of close attacks reads
        // above/below/above/... instead of every close pair independently picking "above" and
        // colliding anyway.
        const NOTE_LABEL_MIN_GAP_SAMPLES = 4; // ~0.4s apart - closer than this and stacked labels start to overlap
        let lastLabelIdx = -Infinity;
        let lastLabelSide = 'above';
        const labelSides = visible.map((s, i) => {
            if (!s.note) return null;
            const side = (i - lastLabelIdx) < NOTE_LABEL_MIN_GAP_SAMPLES
                ? (lastLabelSide === 'above' ? 'below' : 'above')
                : 'above';
            lastLabelIdx = i;
            lastLabelSide = side;
            return side;
        });

        pitchEl.innerHTML = pitchPad + visible.map((s, i) => {
            if (s.cents === null) return `<div class="tuner-history-bar-slot"><div class="tuner-history-bar-gap"></div></div>`;
            const centerPct = 50 - s.cents; // same 1-cent-per-percentage-point mapping tunerBarNeedle uses
            const top = Math.min(50, centerPct);
            const height = Math.max(Math.abs(centerPct - 50), 1.5); // floor so an exact 0c sample still shows a sliver
            const label = s.note ? `<span class="tuner-history-bar-label${labelSides[i] === 'below' ? ' below' : ''}">${escapeHtml(s.note)}</span>` : '';
            return `<div class="tuner-history-bar-slot"><div class="tuner-history-bar${s.inTune ? ' in-tune' : ''}" style="--bar-top:${top}%; --bar-h:${height}%;">${label}</div></div>`;
        }).join('');

        dynamicsEl.innerHTML = dynamicsPad + visible.map((s) => {
            // s.db is null on a genuinely quiet sample (pushTunerHistorySample/renderTunerPitch) - a
            // flat/empty bar there, matching the pitch strip's own gap at the same moment, rather than
            // the ~33%-height bar TUNER_QUIET_RMS's cutoff (-40dBFS) would otherwise floor-map to. A
            // loud-but-untracked moment (breath attack, key click) still has a real s.db and still
            // shows its true height - only true silence flatlines both strips together.
            if (s.db === null) return `<div class="tuner-dynamics-bar"></div>`;
            const norm = Math.max(0, Math.min(1, (s.db + 60) / 60));
            return `<div class="tuner-dynamics-bar" style="--bar-h:${Math.max(norm * 100, 1)}%;"></div>`;
        }).join('');

        // Shared horizontal time axis (#tunerGraphTimeAxis) - always TUNER_HISTORY_VIEW_MS wide, but
        // its right edge moves with tunerScrubOffsetSamples so it still reflects reality while
        // scrubbed (e.g. "-14s/-12s/-10s" well back in the buffer), not just while live.
        const timeAxisEl = document.getElementById('tunerGraphTimeAxis');
        if (timeAxisEl) {
            const rightEdgeSec = Math.round((tunerScrubOffsetSamples * TUNER_HISTORY_SAMPLE_MS) / 1000);
            const viewSec = TUNER_HISTORY_VIEW_MS / 1000;
            const rightLabel = rightEdgeSec === 0 ? 'now' : `-${rightEdgeSec}s`;
            timeAxisEl.innerHTML = `<span>-${rightEdgeSec + viewSec}s</span><span>-${rightEdgeSec + viewSec / 2}s</span><span>${rightLabel}</span>`;
        }

        renderTunerScrubSlider(maxOffset);
    }

    function renderTunerPitch(freq, rms) {
        if (!tunerEngine.isActive()) return; // stray frame from just before stop()
        if (freq > 0) window.Usage?.finish('tuner'); // ML-22: a note heard (once a use)
        const db = tunerRmsToDb(rms);
        const now = performance.now();
        // Live reading (note/needle below) keeps updating regardless of pause - only the history
        // strips freeze, so "pause" reviews the recent past without stopping you tuning right now.
        const dueForHistorySample = !tunerPaused && now - tunerHistoryLastSampleAt >= TUNER_HISTORY_SAMPLE_MS;

        if (!freq || freq < 0) {
            // No signal right now (gap between notes, breath, etc). Deliberately leave the note/needle
            // display showing whatever was last detected, rather than resetting to the idle state -
            // that reset only happens once, when the tuner first opens. The card's own border DOES
            // reset here though (neutral gray, neither .in-tune nor .out-of-tune) - a stale green/gold
            // outline surviving a rest would misrepresent "right now" as still being the last note.
            document.getElementById('tunerCard').classList.remove('in-tune', 'out-of-tune');
            if (dueForHistorySample) {
                tunerHistoryLastSampleAt = now;
                tunerHistoryLastNote = null; // the next real note re-attacks, even if it's the same pitch as before the gap
                // Genuinely quiet (below the same cutoff tunerAutoCorrelate itself gave up at) -
                // db: null flatlines the dynamics strip too, rather than showing a misleadingly tall
                // bar for "quiet" (TUNER_QUIET_RMS's cutoff is still -40dBFS, not silence). A loud but
                // untracked moment (breath attack, key click) keeps its real db - still worth seeing.
                pushTunerHistorySample({ cents: null, inTune: false, note: null, db: rms < TUNER_QUIET_RMS ? null : db });
            }
            return;
        }

        const concertMidi = tunerFreqToMidi(freq);
        const nearestConcertMidi = Math.round(concertMidi);
        const centsOff = (concertMidi - nearestConcertMidi) * 100;

        const writtenMidi = nearestConcertMidi + tunerTransposition;
        const writtenNote = tunerMidiToName(writtenMidi);

        document.getElementById('tunerNoteDisplay').innerText = writtenNote;
        document.getElementById('tunerConcertDisplay').innerText = tunerMidiToName(nearestConcertMidi);

        // tunerShowOctave/tunerShowHz: both off by default. Octave uses scientific pitch notation
        // (MIDI 60 = C4, MIDI 69 = A4/440Hz) computed per column since transposition can shift the
        // octave too, not just the letter. Hz is the same physical value under both columns - written
        // notation only renames the pitch, the actual frequency doesn't change.
        const concertOctaveEl = document.getElementById('tunerConcertOctave');
        const writtenOctaveEl = document.getElementById('tunerNoteOctave');
        if (concertOctaveEl) {
            concertOctaveEl.innerText = tunerShowOctave ? String(Math.floor(nearestConcertMidi / 12) - 1) : '';
            concertOctaveEl.classList.toggle('hidden-group', !tunerShowOctave);
        }
        if (writtenOctaveEl) {
            writtenOctaveEl.innerText = tunerShowOctave ? String(Math.floor(writtenMidi / 12) - 1) : '';
            writtenOctaveEl.classList.toggle('hidden-group', !tunerShowOctave);
        }
        const hzText = `${Math.round(freq)} Hz`;
        const concertHzEl = document.getElementById('tunerConcertHz');
        const writtenHzEl = document.getElementById('tunerNoteHz');
        if (concertHzEl) { concertHzEl.innerText = hzText; concertHzEl.classList.toggle('hidden-group', !tunerShowHz); }
        if (writtenHzEl) { writtenHzEl.innerText = hzText; writtenHzEl.classList.toggle('hidden-group', !tunerShowHz); }

        const clampedCents = Math.max(-50, Math.min(50, centsOff));
        const inTune = Math.abs(centsOff) <= TUNER_ZONE_CENTS;
        document.getElementById('tunerNeedle').style.setProperty('--needle-pos', `${50 + clampedCents}%`);
        document.getElementById('tunerNeedle').classList.toggle('in-tune', inTune);
        document.getElementById('tunerCard').classList.toggle('in-tune', inTune);
        document.getElementById('tunerCard').classList.toggle('out-of-tune', !inTune);
        // ML-210: the same state as text for anyone who can't rely on the colour. The visible line
        // updates every frame; the screen-reader announcement only when the state category changes.
        const tuneWord = inTune ? 'In tune' : (centsOff < 0 ? 'flat' : 'sharp');
        const tuneEl = document.getElementById('tunerTuneState');
        if (tuneEl) tuneEl.innerText = inTune ? 'In tune' : `${Math.round(Math.abs(centsOff))}¢ ${tuneWord}`;
        const announceEl = document.getElementById('tunerTuneAnnounce');
        if (announceEl && announceEl.dataset.state !== tuneWord) { announceEl.dataset.state = tuneWord; announceEl.innerText = inTune ? 'In tune' : tuneWord === 'flat' ? 'Flat' : 'Sharp'; }

        if (dueForHistorySample) {
            tunerHistoryLastSampleAt = now;
            const isAttack = writtenNote !== tunerHistoryLastNote;
            tunerHistoryLastNote = writtenNote;
            pushTunerHistorySample({ cents: clampedCents, inTune, note: isAttack ? writtenNote : null, db });
        }
    }

    tunerEngine.onPitch(renderTunerPitch);

    // Replaces the old plain <select>s / tap-to-open-own-modal pickers with tap-a-tile groups
    // (openFlowGlyphPicker's own shared tile markup, flowGlyphPickerTileHtml) rendered inline inside
    // #tunerSettingsModal, rather than each opening its own modal that auto-closes on pick - picking a
    // tile here should just update state and leave the rest of the settings popup open.
    // renderTunerSettingsModal rebuilds all 3 groups (plus the Tuning row and the Concert-column label,
    // both of which depend on some of these) on every change, same "just re-render the list" convention
    // the rest of this app already uses for anything list-shaped.
    function renderTunerInlineTiles(gridId, options, onSelect) {
        const grid = document.getElementById(gridId);
        if (!grid) return;
        grid.innerHTML = options.map(flowGlyphPickerTileHtml).join('');
        grid.querySelectorAll('.flow-picker-tile').forEach((btn, i) => {
            btn.addEventListener('click', () => onSelect(options[i]));
        });
    }
    // Note letter shown in the Transposition row button (#tunerSettingsModal) - kept as its own
    // function since it needs refreshing from several places (picking a tile, the Settings-screen
    // select, and just opening/re-rendering the Settings popup) independently of the label the "right
    // now" card itself shows (updateTunerTranspositionLabel).
    function updateTunerTranspositionRowValue() {
        const rowValue = document.getElementById('tunerTranspositionRowValue');
        if (rowValue) rowValue.innerText = tunerInstrumentKeyName(tunerTransposition);
    }
    // Transposition and Tuning reference open pop-ups of their own ON TOP of Tuner settings, which stays open underneath
    // (owner, 24 Oct 2026). Closing one - its X, a choice, the backdrop, Escape - closes just that one. (Before ML-591
    // they closed Settings first, so closing them left nothing open; ML-591 then put them in place under arrow rows.)
    function renderTunerSettingsModal() {
        const useFlats = localStorage.getItem(TUNER_USE_FLATS_KEY) === 'true';
        renderTunerInlineTiles('tunerAccidentalOptions', [
            { icon: '♯', caption: 'Sharps', ariaLabel: 'Sharps', selected: !useFlats, value: false },
            { icon: '♭', caption: 'Flats', ariaLabel: 'Flats', selected: useFlats, value: true }
        ], (opt) => {
            localStorage.setItem(TUNER_USE_FLATS_KEY, opt.value ? 'true' : 'false');
            const settingsToggle = document.getElementById('tunerUseFlatsToggle');
            if (settingsToggle) settingsToggle.checked = opt.value;
            renderTunerSettingsModal();
        });

        renderTunerInlineTiles('tunerNoteStyleOptions', [
            { icon: 'CDE', caption: 'Letters', ariaLabel: 'Letters (C, D, E...)', selected: tunerNoteStyle === 'letters', value: 'letters' },
            { icon: 'Do', caption: 'Solfège', ariaLabel: 'Solfège (Do, Re, Mi...)', selected: tunerNoteStyle === 'solfege', value: 'solfege' }
        ], (opt) => {
            tunerNoteStyle = opt.value;
            localStorage.setItem(TUNER_NOTE_STYLE_KEY, tunerNoteStyle);
            const settingsSelect = document.getElementById('tunerNoteStyleSetting');
            if (settingsSelect) settingsSelect.value = tunerNoteStyle;
            renderTunerSettingsModal();
        });

        updateTunerTranspositionLabel();
        updateTunerTranspositionRowValue();
        renderTunerTranspositionSetting();

        const a4RowValue = document.getElementById('tunerA4RowValue');
        if (a4RowValue) a4RowValue.innerText = `${tunerA4Freq}Hz`;

        syncTunerDisplayToggles();
    }
    document.getElementById('tunerUseFlatsToggle')?.addEventListener('change', (e) => {
        localStorage.setItem(TUNER_USE_FLATS_KEY, e.target.checked ? 'true' : 'false');
        renderTunerSettingsModal();
    });
    document.getElementById('tunerNoteStyleSetting')?.addEventListener('change', (e) => {
        tunerNoteStyle = e.target.value;
        localStorage.setItem(TUNER_NOTE_STYLE_KEY, tunerNoteStyle);
        renderTunerSettingsModal();
    });
    document.getElementById('tunerTranspositionSetting')?.addEventListener('change', (e) => {
        tunerTransposition = parseInt(e.target.value, 10) || 0;
        localStorage.setItem(TUNER_TRANSPOSITION_KEY, String(tunerTransposition));
        updateTunerTranspositionLabel();
        updateTunerTranspositionRowValue();
    });

    // Transposition's 12 tiles (the Flow editor's glyph-picker tiles), in its own pop-up - tap one to choose it, and that
    // pop-up closes, leaving Settings.
    function renderTunerTranspositionTiles() {
        const options = tunerTranspositionOffsetsByKey().map(o => ({
            icon: tunerInstrumentKeyName(o), caption: '', ariaLabel: tunerTranspositionLabel(o), selected: tunerTransposition === o, value: o
        }));
        renderTunerInlineTiles('tunerTranspositionOptions', options, (opt) => {
            tunerTransposition = opt.value;
            localStorage.setItem(TUNER_TRANSPOSITION_KEY, String(tunerTransposition));
            const settingsSelect = document.getElementById('tunerTranspositionSetting');
            if (settingsSelect) settingsSelect.value = String(tunerTransposition);
            updateTunerTranspositionLabel();
            updateTunerTranspositionRowValue();
            hideModal('tunerTranspositionModal');
        });
    }
    document.getElementById('tunerTranspositionBtn')?.addEventListener('click', () => { renderTunerTranspositionTiles(); showModal('tunerTranspositionModal'); });
    document.getElementById('tunerTranspositionCloseBtn')?.addEventListener('click', () => hideModal('tunerTranspositionModal'));

    // Settings-screen toggle for the "right now" card's Concert column (updateTunerTranspositionLabel
    // decides the actual hide/show, since it also depends on the transposition choice too) - the popup
    // trigger for this lives in #tunerSettingsModal now (see syncTunerDisplayToggles and the toggle
    // listeners below), not its own tap-to-open tile picker.
    document.getElementById('tunerShowConcertSetting')?.addEventListener('change', (e) => {
        tunerShowConcert = e.target.checked;
        localStorage.setItem(TUNER_SHOW_CONCERT_KEY, tunerShowConcert ? 'true' : 'false');
        updateTunerTranspositionLabel();
        const popupToggle = document.getElementById('tunerShowConcertToggle');
        if (popupToggle) popupToggle.checked = tunerShowConcert;
    });

    // #tunerSettingsModal - every Tuner setting, in one popup (syncTunerDisplayToggles/
    // renderTunerSettingsModal keep this popup and the Settings-screen rows showing the same state).
    // Closes on its own X or a tap on the dark backdrop outside .modal-content, unlike every other
    // modal in the app (which only close via an explicit button) - nothing here needs an explicit
    // Cancel/Save, it's just live picks/toggles.
    function openTunerSettingsModal() {
        renderTunerSettingsModal();
        showModal('tunerSettingsModal');
    }
    function closeTunerSettingsModal() {
        hideModal('tunerSettingsModal');
    }
    document.getElementById('tunerSettingsBtn')?.addEventListener('click', openTunerSettingsModal);
    document.getElementById('tunerSettingsCloseBtn')?.addEventListener('click', closeTunerSettingsModal);
    document.getElementById('tunerSettingsModal')?.addEventListener('click', (e) => {
        if (e.target.id === 'tunerSettingsModal') closeTunerSettingsModal();
    });
    document.getElementById('tunerShowConcertToggle')?.addEventListener('change', (e) => {
        tunerShowConcert = e.target.checked;
        localStorage.setItem(TUNER_SHOW_CONCERT_KEY, tunerShowConcert ? 'true' : 'false');
        updateTunerTranspositionLabel();
        const settingsToggle = document.getElementById('tunerShowConcertSetting');
        if (settingsToggle) settingsToggle.checked = tunerShowConcert;
    });
    document.getElementById('tunerShowHzToggle')?.addEventListener('change', (e) => {
        tunerShowHz = e.target.checked;
        localStorage.setItem(TUNER_SHOW_HZ_KEY, tunerShowHz ? 'true' : 'false');
        const settingsToggle = document.getElementById('tunerShowHzSetting');
        if (settingsToggle) settingsToggle.checked = tunerShowHz;
    });
    document.getElementById('tunerShowOctaveToggle')?.addEventListener('change', (e) => {
        tunerShowOctave = e.target.checked;
        localStorage.setItem(TUNER_SHOW_OCTAVE_KEY, tunerShowOctave ? 'true' : 'false');
        const settingsToggle = document.getElementById('tunerShowOctaveSetting');
        if (settingsToggle) settingsToggle.checked = tunerShowOctave;
    });
    document.getElementById('tunerShowHzSetting')?.addEventListener('change', (e) => {
        tunerShowHz = e.target.checked;
        localStorage.setItem(TUNER_SHOW_HZ_KEY, tunerShowHz ? 'true' : 'false');
        const popupToggle = document.getElementById('tunerShowHzToggle');
        if (popupToggle) popupToggle.checked = tunerShowHz;
    });
    document.getElementById('tunerShowOctaveSetting')?.addEventListener('change', (e) => {
        tunerShowOctave = e.target.checked;
        localStorage.setItem(TUNER_SHOW_OCTAVE_KEY, tunerShowOctave ? 'true' : 'false');
        const popupToggle = document.getElementById('tunerShowOctaveToggle');
        if (popupToggle) popupToggle.checked = tunerShowOctave;
    });

    // A4 tuning reference - feeds tunerFreqToMidi directly (see its own definition above), not just
    // cosmetic. Same minus/plus + typeable readout + slider shape as the Tempo (bpm) popup
    // (flowOpenBpmModal), just a fixed 415-466Hz range (a semitone either side of 440, the standard
    // adjustable span on a reference tuner) instead of that one's dynamic bpm tiers.
    const TUNER_A4_MIN = 415;
    const TUNER_A4_MAX = 466;
    const TUNER_A4_DEFAULT = 440;
    function renderTunerA4Slider() {
        const pct = ((tunerA4Freq - TUNER_A4_MIN) / (TUNER_A4_MAX - TUNER_A4_MIN)) * 100;
        const fill = document.getElementById('tunerA4SliderFill');
        const thumb = document.getElementById('tunerA4SliderThumb');
        if (fill) fill.style.setProperty('--pct', `${pct}%`);
        if (thumb) { thumb.style.setProperty('--pct', `${pct}%`); thumb.setAttribute('aria-valuenow', String(tunerA4Freq)); }
        const valueEl = document.getElementById('tunerA4PopupValue');
        if (valueEl) valueEl.innerText = String(tunerA4Freq);
        const rowValue = document.getElementById('tunerA4RowValue');
        if (rowValue) rowValue.innerText = `${tunerA4Freq}Hz`;
    }
    function setTunerA4(value) {
        tunerA4Freq = Math.round(Math.min(TUNER_A4_MAX, Math.max(TUNER_A4_MIN, value)));
        localStorage.setItem(TUNER_A4_KEY, String(tunerA4Freq));
        renderTunerA4Slider();
    }
    // Tuning reference: its stepper, slider and Reset in its own pop-up on top of Settings, open while you adjust.
    document.getElementById('tunerA4Btn')?.addEventListener('click', () => { renderTunerA4Slider(); showModal('tunerA4Modal'); });
    document.getElementById('tunerA4CloseBtn')?.addEventListener('click', () => hideModal('tunerA4Modal'));
    document.getElementById('tunerA4ResetBtn')?.addEventListener('click', () => setTunerA4(TUNER_A4_DEFAULT));
    setupHoldStepper('tunerA4Minus', -1, (amount) => setTunerA4(tunerA4Freq + amount));
    setupHoldStepper('tunerA4Plus', 1, (amount) => setTunerA4(tunerA4Freq + amount));
    setupSliderInteraction(document.getElementById('tunerA4SliderTrack'), document.getElementById('tunerA4SliderThumb'), {
        onDragRatio: (ratio) => setTunerA4(TUNER_A4_MIN + ratio * (TUNER_A4_MAX - TUNER_A4_MIN)),
        onArrowStep: (dir) => setTunerA4(tunerA4Freq + dir)
    });
    makeSliderReadoutEditable('tunerA4PopupValue', () => tunerA4Freq, (v) => setTunerA4(v), { label: 'A4 tuning reference', min: TUNER_A4_MIN, max: TUNER_A4_MAX });

    document.getElementById('fermataPlaybackModeSetting')?.addEventListener('change', (e) => {
        localStorage.setItem(FERMATA_PLAYBACK_MODE_KEY, e.target.value);
    });
    document.getElementById('tunerRetryBtn')?.addEventListener('click', startTuner);

    // Shows a real #tunerStatus message (requesting access / access denied) - unlike the old
    // "Listening..." toggle this element used to also carry, these two are genuine, infrequent state
    // changes, so it's fine for the card to make room for them; empty (.hidden-group) the rest of the
    // time rather than reserving blank space for a message that's usually not there.
    function setTunerStatusMessage(text) {
        const el = document.getElementById('tunerStatus');
        el.innerText = text;
        el.classList.toggle('hidden-group', !text);
    }

    async function startTuner() {
        // Restore whichever values were last picked (here or in Settings) rather than fixed defaults.
        tunerTransposition = parseInt(localStorage.getItem(TUNER_TRANSPOSITION_KEY), 10) || 0;
        tunerShowConcert = localStorage.getItem(TUNER_SHOW_CONCERT_KEY) !== 'false'; // defaults true (unset)
        tunerNoteStyle = localStorage.getItem(TUNER_NOTE_STYLE_KEY) || 'letters';
        tunerShowHz = localStorage.getItem(TUNER_SHOW_HZ_KEY) === 'true'; // defaults false (unset)
        tunerShowOctave = localStorage.getItem(TUNER_SHOW_OCTAVE_KEY) === 'true'; // defaults false (unset)
        tunerA4Freq = parseInt(localStorage.getItem(TUNER_A4_KEY), 10) || 440; // defaults 440 (unset/invalid)
        updateTunerTranspositionLabel();
        updateTunerTranspositionRowValue();
        renderTunerA4Slider();
        renderTunerIdle();

        document.getElementById('tunerRetryBtn').classList.add('hidden-group');
        setTunerStatusMessage('Requesting microphone access...');

        const ok = await tunerEngine.start();
        if (!ok) {
            setTunerStatusMessage('Microphone access is needed for the tuner. Check your browser/site permissions and try again.');
            document.getElementById('tunerRetryBtn').classList.remove('hidden-group');
            return;
        }
        setTunerStatusMessage('');
        window.Usage?.begin('tuner'); // ML-22: finished when a note is heard
    }

    function stopTuner() {
        tunerEngine.stop();
    }

    // --- The mini tuner ---
    // Shares the tunerEngine singleton above rather than running a second mic session - only one of
    // the full Tuner view / this mini widget is ever visible at a time, but they're independent
    // renderers subscribed to the same onPitch feed. One shared widget element, physically moved
    // into whichever of the MINI_TUNER_VIEWS is the active view (see switchView) rather than a copy
    // per screen - opening it elsewhere isn't possible, and navigating away from all of them always
    // closes it (see updateMetroBlkMiniTunerVisibility), same lifecycle as the full Tuner view itself.
    let metroBlkMiniTunerActive = false;
    // Which instrument the mini tuner is currently reading as - seeded from the persisted Settings
    // default each time it opens, but changing it here (ML-84) only ever updates this in-memory copy,
    // never localStorage: it's a "just for this session" override, not a new default.
    // ML-225: a semitone offset like tunerTransposition, not one of the old 4 named presets - the
    // Settings default can be any of the 12, and anything outside those 4 used to fall back to Concert.
    let metroBlkMiniTunerInstrument = 0;

    // One big note only, for whichever instrument is currently selected (ML-84) - showing concert AND
    // instrument readings side by side left nothing to actually read the note against without already
    // knowing which column was which, and the two-column box kept changing width as note names came
    // and go.
    function renderMetroBlkMiniTunerIdle() {
        document.getElementById('metroBlkMiniTunerNote').innerText = '–';
        document.getElementById('metroBlkMiniTunerNeedle').style.setProperty('--needle-pos', '50%');
        document.getElementById('metroBlkMiniTunerNeedle').classList.remove('in-tune');
        document.getElementById('metroBlkMiniTuner').classList.remove('in-tune');
    }

    function renderMetroBlkMiniTunerPitch(freq) {
        if (!metroBlkMiniTunerActive || !freq || freq < 0) return;
        const concertMidi = tunerFreqToMidi(freq);
        const nearestConcertMidi = Math.round(concertMidi);
        const centsOff = (concertMidi - nearestConcertMidi) * 100;
        const writtenMidi = nearestConcertMidi + metroBlkMiniTunerInstrument;

        document.getElementById('metroBlkMiniTunerNote').innerText = tunerMidiToName(writtenMidi);
        const clampedCents = Math.max(-50, Math.min(50, centsOff));
        const inTune = Math.abs(centsOff) <= TUNER_ZONE_CENTS;
        const needle = document.getElementById('metroBlkMiniTunerNeedle');
        needle.style.setProperty('--needle-pos', `${50 + clampedCents}%`);
        needle.classList.toggle('in-tune', inTune);
        document.getElementById('metroBlkMiniTuner').classList.toggle('in-tune', inTune);
    }
    tunerEngine.onPitch(renderMetroBlkMiniTunerPitch);

    // Short codes (B♭/E♭/F instruments, C for concert pitch) - the full-name text row underneath the
    // bar is gone (removed for height), so this button is the only place the current instrument shows.
    // Same 12 options, order and names as the Settings default (tunerTranspositionOffsetsByKey).
    function renderMetroBlkMiniTunerInstrumentOptions() {
        const grid = document.getElementById('metroBlkMiniTunerInstrumentOptions');
        if (!grid) return;
        grid.innerHTML = tunerTranspositionOffsetsByKey().map(o =>
            `<button type="button" class="metroBlk-timesig-opt" data-value="${o}" aria-label="${tunerTranspositionLabel(o)}">${o === 0 ? 'Concert' : tunerInstrumentKeyName(o)}</button>`
        ).join('');
    }

    // Keeps the instrument button's own text, and the popup's own "currently selected" highlight, in
    // sync with metroBlkMiniTunerInstrument - called on open and on every pick.
    function renderMetroBlkMiniTunerInstrumentBtn() {
        document.getElementById('metroBlkMiniTunerInstrumentBtnLbl').innerText = tunerInstrumentKeyName(metroBlkMiniTunerInstrument);
        document.querySelectorAll('#metroBlkMiniTunerInstrumentOptions .metroBlk-timesig-opt').forEach(btn => {
            btn.classList.toggle('selected', parseInt(btn.dataset.value, 10) === metroBlkMiniTunerInstrument);
        });
    }

    // The instrument button opens this popup directly now (no more 3-dot menu in between - Close is
    // its own dedicated icon button beside it instead, see metroBlkMiniTunerCloseBtn below).
    function openMetroBlkMiniTunerInstrumentPicker() {
        renderMetroBlkMiniTunerInstrumentOptions();
        renderMetroBlkMiniTunerInstrumentBtn();
        showModal('metroBlkMiniTunerInstrumentModal');
    }
    document.getElementById('metroBlkMiniTunerInstrumentBtn')?.addEventListener('click', openMetroBlkMiniTunerInstrumentPicker);
    document.getElementById('metroBlkMiniTunerInstrumentOptions')?.addEventListener('click', (e) => {
        const btn = e.target.closest('.metroBlk-timesig-opt');
        if (!btn) return;
        metroBlkMiniTunerInstrument = parseInt(btn.dataset.value, 10) || 0;
        renderMetroBlkMiniTunerInstrumentBtn();
        hideModal('metroBlkMiniTunerInstrumentModal');
    });
    document.getElementById('metroBlkMiniTunerCloseBtn')?.addEventListener('click', closeMetroBlkMiniTuner);

    // Shows/hides the top-bar toggle - visible only on a tuner-capable view (Flow/Metronome) AND only
    // while the tuner is currently closed (it disappears once open; Settings/Close live in the
    // widget's own 3-dot menu instead, so there's no second way to close it via this button). Reads
    // the current view fresh off viewStack rather than taking a parameter, so every caller (switchView,
    // starting/closing the tuner) can just call this one function instead of duplicating the check.
    function renderTopTunerToggleState() {
        const btn = document.getElementById('topTunerToggleBtn');
        if (!btn) return;
        const currentView = viewStack[viewStack.length - 1];
        const onTunerCapableView = MINI_TUNER_VIEWS.includes(currentView);
        btn.classList.toggle('hidden-group', !onTunerCapableView || metroBlkMiniTunerActive);
    }

    function openMetroBlkMiniTuner() {
        // Starts from the Settings default transposition every time it opens (ML-225: all 12 offsets
        // carry through now, not just the 4 this popup used to offer).
        metroBlkMiniTunerInstrument = parseInt(localStorage.getItem(TUNER_TRANSPOSITION_KEY), 10) || 0;
        renderMetroBlkMiniTunerInstrumentBtn();
        renderMetroBlkMiniTunerIdle();
        // .metroBlk-mini-tuner-open (not hidden-group) so opening/closing animates - see the CSS.
        document.getElementById('metroBlkMiniTuner').classList.add('metroBlk-mini-tuner-open');
    }

    // ML-132 test: which metronome engine's AudioContext the mini tuner widget should share, matching
    // whichever tool is actually behind it on the current view - same view pair renderTopTunerToggleState
    // already gates the widget's availability on. Neither player may have been pressed play yet (the
    // mini tuner can open before that), but getAudioContext() creates/warms the context regardless.
    function activeMetroPlayerForTuner() {
        const currentView = viewStack[viewStack.length - 1];
        if (currentView === 'quickPlayView') return qpPlayer;
        if (currentView === 'flowPlayView') return flowPlayer;
        if (currentView === 'scalesView') return scalesPlayer;
        if (currentView === 'warmupsView') return warmupsPlayer;
        return null;
    }

    async function startMetroBlkMiniTuner() {
        openMetroBlkMiniTuner();
        metroBlkMiniTunerActive = true;
        renderTopTunerToggleState();
        const ok = await tunerEngine.start(activeMetroPlayerForTuner()?.getAudioContext());
        if (!ok) {
            showWarningToast('Microphone access is needed for the tuner.');
            closeMetroBlkMiniTuner();
        }
    }

    function closeMetroBlkMiniTuner() {
        metroBlkMiniTunerActive = false;
        renderTopTunerToggleState();
        document.getElementById('metroBlkMiniTuner').classList.remove('metroBlk-mini-tuner-open');
        stopTuner();
    }

    // Only ever opens it now - closing happens via the tuner widget's own 3-dot menu instead (this
    // button is hidden the whole time the tuner's open, so it was never reachable to close it anyway).
    document.getElementById('topTunerToggleBtn')?.addEventListener('click', startMetroBlkMiniTuner);

    function updateMetroBlkMiniTunerVisibility(viewName) {
        if (!MINI_TUNER_VIEWS.includes(viewName)) {
            metroBlkMiniTunerActive = false;
            document.getElementById('metroBlkMiniTuner')?.classList.remove('metroBlk-mini-tuner-open');
        }
        renderTopTunerToggleState();
    }

    // ========================================
    // TUNING FORK (ML-158)
    // ========================================
    // A note to tune to: pick it on a stave, press play, and it sounds until you stop it. Decided with the
    // owner on 12 Oct 2026:
    //  - the note is shown as WRITTEN for your instrument (My instruments - its clef and transposition, in the
    //    clef you read, ML-528), with what it sounds as at concert pitch named under it;
    //  - it starts on the instrument's usual tuning note (TuningFork.usualNote: concert B flat for brass and
    //    woodwind, concert A otherwise, in the octave that sits nearest the middle of the stave);
    //  - it follows the Tuner's "A =" setting;
    //  - it is a tool of its own (#tuningForkView). A button on the Tuner that opened it as a pop-up was built
    //    and taken out again the same day: the owner didn't want it on the Tuner.
    // Nothing is sent to the server: the note for each instrument and the volume are kept on this device
    // ('tml.fork'), so it works offline. The switch is tuning_fork. specs/components/tuning-fork.md.
    const FORK_STORE = 'tml.fork';
    const FORK_CLEFS = ['treble', 'bass', 'alto', 'tenor'];
    const FORK_CLEF_MIDDLE = { treble: 71, bass: 50, alto: 60, tenor: 57 }; // the middle line, as a MIDI number
    const FORK_FALLBACK_RANGE = { low: 'C2', high: 'C7' }; // with no instrument (or one with no range): what a stave can show
    let fork = (() => {
        const start = { volume: 70, notes: {}, instrumentId: null };
        try { const saved = JSON.parse(localStorage.getItem(FORK_STORE) || 'null'); if (saved) return { ...start, ...saved, notes: { ...(saved.notes || {}) } }; } catch (e) { /* unreadable - start afresh */ }
        return start;
    })();
    const forkSave = () => { try { localStorage.setItem(FORK_STORE, JSON.stringify(fork)); } catch (e) { /* private browsing - this visit only */ } };
    let forkVolumeBeforeMute = fork.volume || 70;
    // The instrument the note is written for: the one chosen here, else the main one. null = none on the account.
    const forkInstrument = () => (myInstruments || []).find(i => i.id === fork.instrumentId) || (myInstruments || []).find(i => i.isPrimary) || (myInstruments || [])[0] || null;
    const forkClef = (inst) => (inst && FORK_CLEFS.includes(inst.theoryClef) ? inst.theoryClef : 'treble');
    const forkShift = (inst) => (inst && FORK_CLEFS.includes(inst.theoryClef) ? Number(inst.writtenToConcert) || 0 : 0); // concert = written + this
    const forkOuter = (inst) => (inst && FORK_CLEFS.includes(inst.theoryClef) && instrumentOuter(inst)) || FORK_FALLBACK_RANGE;
    // The usual tuning note, written for the instrument: a band tunes to concert B flat (written C on a B flat
    // instrument, G on an E flat one); strings and anything else to concert A. In the octave nearest the
    // middle of the stave that the instrument can play.
    function forkUsualNote(inst) {
        const concertPc = inst && ['brass', 'woodwind'].includes(inst.familyKey) ? 10 : 9;
        const shift = forkShift(inst), outer = forkOuter(inst);
        const lo = PlayRange.midiOf(outer.low), hi = PlayRange.midiOf(outer.high), middle = FORK_CLEF_MIDDLE[forkClef(inst)];
        let best = null;
        for (let written = 12; written <= 108; written++) {
            if ((((written + shift) % 12) + 12) % 12 !== concertPc || written < lo || written > hi) continue;
            if (best === null || Math.abs(written - middle) < Math.abs(best - middle)) best = written;
        }
        return PlayRange.pitchOf(best === null ? middle : best, 'usual');
    }
    const forkKey = (inst) => (inst ? String(inst.id) : 'none');
    function forkNote(inst = forkInstrument()) {
        const saved = fork.notes[forkKey(inst)];
        const outer = forkOuter(inst);
        if (saved && /^[A-G](#|b)?\d$/.test(saved) && PlayRange.midiOf(saved) >= PlayRange.midiOf(outer.low) && PlayRange.midiOf(saved) <= PlayRange.midiOf(outer.high)) return saved;
        return forkUsualNote(inst);
    }
    const forkConcertMidi = (inst = forkInstrument()) => PlayRange.midiOf(forkNote(inst)) + forkShift(inst);
    const forkFrequency = () => (tunerA4Freq || 440) * Math.pow(2, (forkConcertMidi() - 69) / 12);

    // --- The sound: one held note. A soft triangle with a quieter octave above it, so a low note (a tuba's
    // B flat) can still be heard on a phone's small speaker. Fades in and out; the pitch and the volume
    // follow a change while it sounds. Its own audio context, made on the first Play. ---
    let forkCtx = null;
    let forkVoice = null; // { oscs, gain } while sounding
    const forkSounding = () => !!forkVoice;
    const forkLevel = () => (fork.volume / 100) * 0.4;
    function forkStart() {
        if (forkVoice) return;
        if (!forkCtx) { const Ctx = window.AudioContext || window.webkitAudioContext; forkCtx = new Ctx(); }
        if (forkCtx.state === 'suspended') forkCtx.resume();
        const t = forkCtx.currentTime, freq = forkFrequency();
        const gain = forkCtx.createGain();
        gain.gain.setValueAtTime(0, t);
        gain.gain.linearRampToValueAtTime(forkLevel(), t + 0.04);
        gain.connect(forkCtx.destination);
        const oscs = [['triangle', 1, 1], ['sine', 2, 0.25]].map(([type, times, level]) => {
            const osc = forkCtx.createOscillator(), part = forkCtx.createGain();
            osc.type = type;
            osc.frequency.setValueAtTime(freq * times, t);
            part.gain.value = level;
            osc.connect(part).connect(gain);
            osc.start(t);
            return { osc, times };
        });
        forkVoice = { oscs, gain };
        window.Usage?.begin('tuning-fork'); // ML-22: finished after 5 seconds sounding
        renderFork();
    }
    function forkStop() {
        if (!forkVoice) return;
        window.Usage?.end('tuning-fork');
        const { oscs, gain } = forkVoice, t = forkCtx.currentTime;
        forkVoice = null;
        gain.gain.cancelScheduledValues(t);
        gain.gain.setTargetAtTime(0, t, 0.03);
        oscs.forEach(({ osc }) => osc.stop(t + 0.25));
        renderFork();
    }
    // A new note or a new "A =" while it sounds: slide to it, don't restart
    function forkRetune() {
        if (!forkVoice) return;
        const t = forkCtx.currentTime, freq = forkFrequency();
        forkVoice.oscs.forEach(({ osc, times }) => osc.frequency.setTargetAtTime(freq * times, t, 0.02));
    }
    function setForkVolume(v) {
        fork.volume = Math.round(Math.min(100, Math.max(0, v)));
        if (fork.volume > 0) forkVolumeBeforeMute = fork.volume;
        if (forkVoice) forkVoice.gain.gain.setTargetAtTime(forkLevel(), forkCtx.currentTime, 0.02);
        forkSave();
        renderForkVolume();
    }
    function setForkNote(pitch) {
        const inst = forkInstrument();
        fork.notes[forkKey(inst)] = pitch;
        forkSave();
        forkRetune();
        renderFork();
    }

    // --- The panel ---
    const forkConcertLabel = (inst) => PlayRange.label(PlayRange.pitchOf(forkConcertMidi(inst), 'flat')).replace(/\d+$/, '');
    function renderForkVolume() {
        const fill = document.getElementById('forkVolumeFill'), thumb = document.getElementById('forkVolumeThumb');
        if (!fill || !thumb) return;
        fill.style.setProperty('--pct', `${fork.volume}%`);
        thumb.style.setProperty('--pct', `${fork.volume}%`);
        thumb.setAttribute('aria-valuenow', fork.volume);
        thumb.setAttribute('aria-valuetext', `${fork.volume}%`);
        const muted = fork.volume === 0;
        document.getElementById('forkMuteIcon').textContent = muted ? 'volume_off' : 'volume_up';
        document.getElementById('forkMuteBtn').setAttribute('aria-pressed', String(muted));
        document.getElementById('forkVolumeRow').classList.toggle('is-muted', muted);
    }
    function renderFork() {
        const panel = document.getElementById('forkPanel');
        if (!panel) return;
        const inst = forkInstrument(), pitch = forkNote(inst), sounding = forkSounding();
        const written = PlayRange.label(pitch), shift = forkShift(inst);
        document.getElementById('forkStave').innerHTML = theoryScaleSvg(Notation.staff({ clef: forkClef(inst), items: [{ type: 'note', pitch }], stepRange: RANGE_PICKER_STEPS, minWidth: 12, tappable: true }), 1.4);
        document.getElementById('forkStave').setAttribute('aria-label', `Tuning note: ${written}. Tap the stave near a note to pick it`);
        document.getElementById('forkValue').textContent = written;
        document.getElementById('forkSub').textContent = shift ? `sounds as concert ${forkConcertLabel(inst)}` : 'concert pitch';
        const instBtn = document.getElementById('forkInstrumentBtn');
        setShown(instBtn, (myInstruments || []).length > 1);
        if (inst) instBtn.querySelector('strong').textContent = inst.name;
        setShown('forkNoInstrument', !inst);
        panel.classList.toggle('is-sounding', sounding);
        document.getElementById('forkPlayIcon').textContent = sounding ? 'stop' : 'play_arrow';
        document.getElementById('forkPlayLbl').textContent = sounding ? 'stop' : 'play';
        document.getElementById('forkPlayBtn').setAttribute('aria-pressed', String(sounding));
        document.getElementById('forkPlayBtn').setAttribute('aria-label', sounding ? `Stop the note (${written})` : `Play ${written}`);
        document.getElementById('forkUsualBtn').disabled = pitch === forkUsualNote(inst);
        renderForkVolume();
    }
    document.addEventListener('visibilitychange', () => { if (document.hidden) forkStop(); });

    document.getElementById('forkPlayBtn')?.addEventListener('click', () => (forkSounding() ? forkStop() : forkStart()));
    document.getElementById('forkStave')?.addEventListener('click', (e) => {
        const svg = e.currentTarget.querySelector('svg');
        if (!svg || e.detail === 0) return; // keyboard "click": - and + do the picking
        const inst = forkInstrument();
        const rect = svg.getBoundingClientRect(), vb = svg.viewBox.baseVal;
        const y = (e.clientY - rect.top) * (vb.height / rect.height);
        const step = Number(svg.dataset.stepHi) - (y - Number(svg.dataset.stepPad)) / (Notation.S / 2);
        setForkNote(PlayRange.pitchAtStep(step, forkClef(inst), forkOuter(inst)));
    });
    document.getElementById('forkMinus')?.addEventListener('click', () => setForkNote(PlayRange.stepSemitone(forkNote(), -1, forkOuter(forkInstrument()))));
    document.getElementById('forkPlus')?.addEventListener('click', () => setForkNote(PlayRange.stepSemitone(forkNote(), 1, forkOuter(forkInstrument()))));
    document.getElementById('forkUsualBtn')?.addEventListener('click', () => setForkNote(forkUsualNote(forkInstrument())));
    document.getElementById('forkInstrumentBtn')?.addEventListener('click', () => {
        const cur = forkInstrument();
        openFlowChoiceModal('Which instrument?', (myInstruments || []).map(i => ({ id: i.id, selected: !!cur && cur.id === i.id, html: `<span><strong>${escapeHtml(i.name)}</strong></span>${cur && cur.id === i.id ? '<span class="material-symbols-outlined" aria-hidden="true">check</span>' : ''}` })), (opt) => {
            fork.instrumentId = opt.id;
            forkSave();
            forkRetune();
            renderFork();
            document.getElementById('forkInstrumentBtn')?.focus();
        });
    });
    setupSliderInteraction(document.getElementById('forkVolumeTrack'), document.getElementById('forkVolumeThumb'), {
        onDragRatio: (ratio) => setForkVolume(ratio * 100),
        onArrowStep: (dir) => setForkVolume(fork.volume + dir * 5),
        onRelease: () => {}
    });
    document.getElementById('forkMuteBtn')?.addEventListener('click', () => setForkVolume(fork.volume > 0 ? 0 : (forkVolumeBeforeMute || 70)));

    // ========================================
    // WAKE LOCK (ML-59)
    // ========================================
    // Keeps the screen from sleeping while the timer or metronome is
    // actively running - both are meant to be glanced at/heard over several
    // minutes without touching the screen, so the OS's normal short sleep
    // timeout would otherwise kill the session. Re-synced (not just
    // acquired once) because the OS releases the lock on tab-hide, and on
    // some browsers on tab-return the lock needs to be re-requested rather
    // than resuming on its own.
    let wakeLock = null;

    async function acquireWakeLock() {
        if (wakeLock || !('wakeLock' in navigator)) return;
        try {
            wakeLock = await navigator.wakeLock.request('screen');
            wakeLock.addEventListener('release', () => { wakeLock = null; });
        } catch (err) {
            // Not fatal - e.g. permission denied or battery saver mode. The
            // screen can just sleep as normal in that case.
        }
    }

    function releaseWakeLockIfHeld() {
        if (wakeLock) wakeLock.release();
        wakeLock = null;
    }

    function isWakeLockNeeded() {
        return !!(timerState && timerState.running) || (typeof qpPlayer !== 'undefined' && qpPlayer.isPlaying());
    }

    function syncWakeLock() {
        if (isWakeLockNeeded()) acquireWakeLock(); else releaseWakeLockIfHeld();
    }

    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible') syncWakeLock();
    });

    // ========================================
    // TIMER (ML-7)
    // ========================================
    // Practice timer: pick a target duration (same duration_options list as the
    // save-session screen, ML-7/ML-29), count down, and on finish offer to log it
    // as a practice session via the existing save-session screen. Runs on a plain
    // setInterval that's independent of which view is on screen - navigating away
    // just shrinks it to the top-bar indicator (see updateTopTimerIndicator) rather
    // than stopping it. State lives in `timerState`: null when idle, otherwise
    // { targetSeconds, remainingSeconds, elapsedSeconds, running, openEnded }.
    // ML-184: "Open ended" (targetSeconds/remainingSeconds both null, openEnded true) counts up
    // instead of down and never finishes itself - timerTick just keeps banking elapsedSeconds until
    // Stop is pressed. Every display that normally reads "remaining .../left" reads elapsed/"done"
    // instead while openEnded is set - see updateTimerDisplays.
    let timerState = null;
    let timerIntervalId = null;

    // Best-effort push of the current timerState to the server so a later reload/relogin (see
    // restoreTimerSession) can pick back up with exactly the same amount of time left, to the
    // second - not just "aware a timer was going" (ML-197). Only called on actual state changes
    // (start/pause/resume/snooze/finish), never on a plain tick: while running, the server doesn't
    // need a fresher elapsed_seconds than whatever this last sent - getActiveTimerSession projects
    // it forward from updated_at using Postgres's own clock, so real wall-clock time keeps counting
    // against the remaining time even while the app is closed, exactly as if it had been a real
    // clock running the whole time. A pause freezes that projection (this same function fires again
    // on pause, moving the anchor to that instant) - only a running stretch should ever count.
    // Fire-and-forget: a failed sync (offline, etc) just delays how current the next restore's
    // anchor point is - it must never interrupt or stall the local timer itself.
    function syncActiveTimerSession() {
        if (!timerState) return;
        API.timer.syncActive({
            targetSeconds: timerState.targetSeconds,
            elapsedSeconds: timerState.elapsedSeconds,
            running: timerState.running
        }).catch(() => {});
    }

    // Rebuilds timerState from the server's already wall-clock-projected elapsedSeconds (see
    // getActiveTimerSession) - the counterpart to syncActiveTimerSession, used to recover a timer an
    // accidental reload/relogin would otherwise have silently lost (ML-197), with the same amount of
    // time left it would actually have if it had just kept a real clock running the whole time it
    // was away (or exactly where it was left, if it was paused when the app went away).
    function restoreTimerSession(active) {
        const { targetSeconds, elapsedSeconds, running } = active;
        const openEnded = targetSeconds === null;
        // A countdown that had already run out (or was seconds from it) by the time this reload
        // happened - nothing left to meaningfully resume. Drop the stale row rather than restoring
        // a ~0:00 timer that would just immediately re-trigger the finished-session flow on its own.
        if (!openEnded && elapsedSeconds >= targetSeconds) {
            API.timer.clearActive().catch(() => {});
            return;
        }
        timerState = {
            targetSeconds,
            remainingSeconds: openEnded ? null : targetSeconds - elapsedSeconds,
            elapsedSeconds,
            running,
            openEnded,
            forSession: !!(practiceRun && !practiceRun.done) // ML-421
        };
        clearInterval(timerIntervalId);
        // Always ticking (timerTick does nothing while paused): a timer that came back paused had no interval, so
        // pressing play on it after a reload did nothing (found with ML-422).
        timerIntervalId = setInterval(timerTick, 1000);
        if (timerState.forSession && !running && !practiceRun.pausedAt) { practiceRun.pausedAt = Date.now(); renderPracticeRun(); } // ML-422
        renderTimerScreen();
        updateTopTimerIndicator(viewStack[viewStack.length - 1]);
        syncWakeLock();
    }

    const TIMER_TODAY_SECONDS_KEY = 'timerTodaySeconds';
    const TIMER_TODAY_DATE_KEY = 'timerTodayDate';

    function timerTodayDateStr() {
        const d = new Date();
        return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    }

    // "Today" here is the timer tool's own live running total, separate from the
    // app's real session-history stats - it resets at local midnight and only
    // tracks time actually spent with the timer running.
    function getTimerTodaySeconds() {
        if (localStorage.getItem(TIMER_TODAY_DATE_KEY) !== timerTodayDateStr()) return 0;
        return Number(localStorage.getItem(TIMER_TODAY_SECONDS_KEY)) || 0;
    }

    function addTimerTodaySeconds(n) {
        const today = timerTodayDateStr();
        const current = localStorage.getItem(TIMER_TODAY_DATE_KEY) === today ? getTimerTodaySeconds() : 0;
        localStorage.setItem(TIMER_TODAY_DATE_KEY, today);
        localStorage.setItem(TIMER_TODAY_SECONDS_KEY, String(current + n));
    }

    function formatClock(totalSeconds) {
        const s = Math.max(0, Math.round(totalSeconds));
        const h = Math.floor(s / 3600);
        const m = Math.floor((s % 3600) / 60);
        const sec = s % 60;
        const mm = String(m).padStart(2, '0');
        const ss = String(sec).padStart(2, '0');
        return h > 0 ? `${h}:${mm}:${ss}` : `${mm}:${ss}`;
    }

    // ML-129 follow-up: the timer's collapsed top-bar state is exactly one of three things - nothing,
    // the idle icon (next to the tuner toggle, no timer running/paused yet), or the running pill
    // (also next to the tuner toggle, sized to its own content - it no longer replaces the title) -
    // and never any of them while the inline popup itself is open, or the Timer screen itself is the
    // active view (that page already shows everything).
    let timerInlineBoxOpen = false;
    function updateTopTimerIndicator(viewName) {
        const onTimerView = viewName === 'timerView';
        const showPill = !!timerState && !timerInlineBoxOpen && !onTimerView;
        const showIcon = !timerState && !timerInlineBoxOpen && !onTimerView;
        document.getElementById('topTimerPill')?.classList.toggle('hidden-group', !showPill);
        document.getElementById('topTimerIconBtn')?.classList.toggle('hidden-group', !showIcon);
    }

    // ML-293: the countdown ring on the Timer screen. Up to an hour, the full ring is the whole session.
    // Over an hour, the main ring is the last hour and the thin outer ring the part over it (up to a
    // second hour), which unwinds first; the badge says which hour you're in, counting down.
    const TIMER_RING_HOUR = 3600;
    // The Timer screen's ring and the pop-up's (ML-481) are the same ring. The screen hides its ring for an
    // open-ended session; the pop-up keeps the plain circle round the time done (.is-open-ended).
    function renderTimerRing() {
        drawTimerRing(document.getElementById('timerRemainingCard'), document.getElementById('timerRingHour'));
        const inline = document.getElementById('timerInlineTimeDisplay');
        if (!inline || !timerState) return;
        inline.classList.toggle('is-open-ended', !!timerState.openEnded);
        if (timerState.openEnded) {
            inline.classList.remove('has-lap');
            inline.classList.toggle('is-long', timerState.elapsedSeconds >= TIMER_RING_HOUR);
            setShown('timerInlineRingHour', false);
        } else drawTimerRing(inline, document.getElementById('timerInlineRingHour'));
    }
    function drawTimerRing(ring, hour) {
        if (!ring || !timerState || timerState.openEnded) return;
        const target = timerState.targetSeconds || 1;
        const left = Math.max(0, timerState.remainingSeconds);
        const overAnHour = target > TIMER_RING_HOUR;
        const main = overAnHour ? Math.min(left, TIMER_RING_HOUR) / TIMER_RING_HOUR : left / target;
        const lap = overAnHour ? Math.min(Math.max(left - TIMER_RING_HOUR, 0), TIMER_RING_HOUR) / TIMER_RING_HOUR : 0;
        ring.style.setProperty('--ring-left', main.toFixed(4));
        ring.style.setProperty('--lap-left', lap.toFixed(4));
        ring.classList.toggle('has-lap', lap > 0);
        ring.classList.toggle('is-running', !!timerState.running);
        ring.classList.toggle('is-long', left >= TIMER_RING_HOUR);
        if (hour) {
            setShown(hour, overAnHour);
            if (overAnHour) hour.textContent = `Hour ${Math.max(1, Math.ceil(left / TIMER_RING_HOUR))} of ${Math.ceil(target / TIMER_RING_HOUR)}`;
        }
    }

    function updateTimerPlayIcons() {
        const running = !!(timerState && timerState.running);
        document.getElementById('timerRemainingCard')?.classList.toggle('is-running', running);
        document.getElementById('timerInlineTimeDisplay')?.classList.toggle('is-running', running);
        const label = running ? 'Pause' : 'Play';
        const icon = running ? 'pause' : 'play_arrow';
        const fullIcon = document.getElementById('timerPlayIcon');
        const fullBtn = document.getElementById('timerPlayBtn');
        if (fullIcon) fullIcon.innerText = icon;
        if (fullBtn) fullBtn.setAttribute('aria-label', label);
        // The inline box's Play cell doubles as "Start" until a session actually exists.
        const inlineIcon = document.getElementById('timerInlinePlayIcon');
        const inlineLbl = document.getElementById('timerInlinePlayLbl');
        const inlineBtn = document.getElementById('timerInlinePlayBtn');
        if (inlineIcon) inlineIcon.innerText = timerState ? icon : 'play_arrow';
        if (inlineLbl) inlineLbl.innerText = timerState ? (running ? 'pause' : 'play') : 'start';
        if (inlineBtn) inlineBtn.setAttribute('aria-label', timerState ? label : 'Start');
        // Soft amber glow while actually running (not paused) - visually confirms time is
        // accumulating without an extra banner.
        document.getElementById('topTimerPill')?.classList.toggle('top-bar-timer-pill-running', running);
    }

    // ML-184: every "remaining .../left" slot shows elapsed/"done" instead once openEnded - there's no
    // countdown to be remaining from. primarySeconds is whichever of the two that slot actually means
    // right now. Open-ended also hides the standalone top card entirely (renderTimerScreen) rather
    // than showing that same elapsed figure a second time - "This session" below takes over as the
    // one combined display, relabelled "Time done" here to match.
    function updateTimerDisplays() {
        if (!timerState) return;
        const openEnded = timerState.openEnded;
        const primarySeconds = openEnded ? timerState.elapsedSeconds : timerState.remainingSeconds;
        const remainingEl = document.getElementById('timerRemainingDisplay');
        const elapsedEl = document.getElementById('timerElapsedDisplay');
        const todayEl = document.getElementById('timerTodayDisplay');
        if (remainingEl) remainingEl.innerText = formatClock(primarySeconds);
        if (elapsedEl) elapsedEl.innerText = formatClock(timerState.elapsedSeconds);
        if (todayEl) todayEl.innerText = formatClock(getTimerTodaySeconds());
        const remainingLabelEl = document.getElementById('timerRemainingLabel');
        if (remainingLabelEl) remainingLabelEl.innerText = openEnded ? 'Time done' : 'Time left in session';
        const elapsedLabelEl = document.getElementById('timerElapsedLabel');
        if (elapsedLabelEl) elapsedLabelEl.innerText = openEnded ? 'Time done' : 'This session';
        renderTimerRing();

        // The pill only has room for one figure, per the request ("has the time remaining") -
        // elapsed/"today" stay full-screen-only (timerElapsedDisplay/timerTodayDisplay above).
        const pillRemainingEl = document.getElementById('topTimerPillRemaining');
        if (pillRemainingEl) pillRemainingEl.innerText = formatClock(primarySeconds);
        const pillLeftLbl = document.getElementById('topTimerPillLeftLbl');
        if (pillLeftLbl) pillLeftLbl.innerText = openEnded ? 'done' : 'left';
        const inlineRemainingEl = document.getElementById('timerInlineRemainingLbl');
        if (inlineRemainingEl) inlineRemainingEl.innerText = formatClock(primarySeconds);
        const inlineLeftLbl = document.getElementById('timerInlineLeftLbl');
        if (inlineLeftLbl) inlineLeftLbl.innerText = openEnded ? 'Time done' : 'Time left';
    }

    // --- Inline box (ML-129 follow-up) - opened by tapping either the running pill or the idle
    // icon, stays open across navigation (it lives in .top-bar-sticky-group, same as the metronome
    // mini-bars), and keeps the timer counting down regardless of whether it's open or closed. ---

    // Staged duration, only meaningful while idle - Start reads this, the picker modal sets it.
    let timerPickedMinutes = null;

    function renderTimerInlineBox() {
        const running = !!timerState;
        document.getElementById('timerInlinePickBtn')?.classList.toggle('hidden-group', running);
        document.getElementById('timerInlineTimeDisplay')?.classList.toggle('hidden-group', !running);
        // Just the number now (no "min" suffix) - "XX min." was overflowing the fixed-width cell,
        // same reason the label underneath now says "minutes" instead of "duration".
        const pickLbl = document.getElementById('timerInlinePickLbl');
        if (pickLbl) pickLbl.innerText = timerPickedMinutes === 'open-ended' ? 'Open' : (timerPickedMinutes ? String(timerPickedMinutes) : 'Pick');
        const stopBtn = document.getElementById('timerInlineStopBtn');
        if (stopBtn) stopBtn.disabled = !running;
        updateTimerPlayIcons();
        if (running) updateTimerDisplays();
    }

    // ML-236: the quick timer starts on the user's usual practice length instead of "Pick" - the
    // most common Practise session length over the last 90 days, each snapped to the nearest preset
    // first (saved times are noisy: 23 and 27 minutes both count as 25). Ties go to the more recent.
    // No practise in that window: the admin-set default (duration_options.is_default), else 30.
    function suggestedTimerMinutes() {
        const presets = (appData.durations || []).filter(m => m > 0);
        const cutoff = new Date();
        cutoff.setDate(cutoff.getDate() - 90);
        const counts = new Map();
        const lastSeen = new Map();
        (rawData || []).forEach(d => {
            if (d.category !== 'Practise' || !(d.duration > 0)) return;
            const when = parseDateSafely(d.dateStr);
            if (!when || when < cutoff) return;
            const mins = presets.length
                ? presets.reduce((best, p) => Math.abs(p - d.duration) < Math.abs(best - d.duration) ? p : best, presets[0])
                : Math.round(d.duration);
            counts.set(mins, (counts.get(mins) || 0) + 1);
            if (!lastSeen.has(mins) || when > lastSeen.get(mins)) lastSeen.set(mins, when);
        });
        let best = null;
        counts.forEach((count, mins) => {
            if (best === null || count > counts.get(best) || (count === counts.get(best) && lastSeen.get(mins) > lastSeen.get(best))) best = mins;
        });
        return best ?? appData.defaultDuration ?? 30;
    }

    function openTimerInlineBox() {
        // Only seeds an idle timer nobody has picked a length for yet - never overrides a choice.
        if (!timerState && timerPickedMinutes === null) timerPickedMinutes = suggestedTimerMinutes();
        timerInlineBoxOpen = true;
        showModal('timerInlineBox');
        updateTopTimerIndicator(viewStack[viewStack.length - 1]);
        renderTimerInlineBox();
    }
    // Never stops the timer itself - just hides the popup again, same as the request ("This can be
    // kept open, and the timer will keep going... you can continue to use the screen as normal").
    function closeTimerInlineBox() {
        timerInlineBoxOpen = false;
        hideModal('timerInlineBox');
        updateTopTimerIndicator(viewStack[viewStack.length - 1]);
    }
    document.getElementById('topTimerPill')?.addEventListener('click', openTimerInlineBox);
    document.getElementById('topTimerIconBtn')?.addEventListener('click', openTimerInlineBox);
    document.getElementById('timerInlineCloseBtn')?.addEventListener('click', closeTimerInlineBox);
    // Tapping the backdrop (not the popup card itself) closes it too, per the request - the countdown
    // keeps going in the top pill either way.
    document.getElementById('timerInlineBox')?.addEventListener('click', (e) => {
        if (e.target.id === 'timerInlineBox') closeTimerInlineBox();
    });

    document.getElementById('timerInlinePlayBtn')?.addEventListener('click', () => {
        if (!timerState) {
            if (!timerPickedMinutes) { showWarningToast('Pick a duration first!'); return; }
            startTimerSession(timerPickedMinutes === 'open-ended' ? null : timerPickedMinutes * 60);
        } else {
            toggleTimerPlayPause();
        }
        renderTimerInlineBox();
    });
    document.getElementById('timerInlineStopBtn')?.addEventListener('click', finishTimerSession);

    // --- Duration picker modal (ML-129 follow-up) - only reachable from the inline box's "pick
    // duration" cell while idle. Its own copy of the duration radios (timerPickerDur* ids, populated
    // by renderDurationRadios above) rather than sharing timerDurationRadios' DOM nodes with the full
    // Timer page, so each stays independently usable regardless of which one is on screen. ---
    document.getElementById('timerInlinePickBtn')?.addEventListener('click', () => {
        document.querySelectorAll('input[name="timerPickerDurationOption"]').forEach(r => { r.checked = false; });
        document.getElementById('timerPickerCustomDurationGroup')?.classList.add('hidden-group');
        if (timerPickedMinutes) {
            const matching = document.getElementById(`timerPickerDur-${timerPickedMinutes}`);
            if (matching) {
                matching.checked = true;
            } else {
                const customRadio = document.getElementById('timerPickerDur-custom');
                if (customRadio) customRadio.checked = true;
                document.getElementById('timerPickerCustomDurationGroup')?.classList.remove('hidden-group');
                const customInput = document.getElementById('timerPickerCustomDuration');
                if (customInput) customInput.value = timerPickedMinutes;
            }
        }
        showModal('timerDurationPickerModal');
    });
    document.getElementById('timerPickerDurationRadios')?.addEventListener('change', (e) => {
        if (e.target.name !== 'timerPickerDurationOption') return;
        const customGroup = document.getElementById('timerPickerCustomDurationGroup');
        if (e.target.value === 'custom') {
            customGroup.classList.remove('hidden-group');
            document.getElementById('timerPickerCustomDuration')?.focus();
        } else {
            customGroup.classList.add('hidden-group');
        }
    });
    function closeTimerDurationPickerModal() {
        hideModal('timerDurationPickerModal');
    }
    document.getElementById('timerDurationPickerXBtn')?.addEventListener('click', closeTimerDurationPickerModal);
    document.getElementById('timerDurationPickerCancelBtn')?.addEventListener('click', closeTimerDurationPickerModal);
    document.getElementById('timerDurationPickerSaveBtn')?.addEventListener('click', () => {
        const radio = document.querySelector('input[name="timerPickerDurationOption"]:checked')?.value;
        if (radio === 'open-ended') {
            timerPickedMinutes = 'open-ended';
            closeTimerDurationPickerModal();
            renderTimerInlineBox();
            return;
        }
        const mins = Number(radio === 'custom' ? document.getElementById('timerPickerCustomDuration')?.value : radio);
        if (!mins || isNaN(mins) || mins <= 0) { showWarningToast('Pick a duration first!'); return; }
        timerPickedMinutes = mins;
        closeTimerDurationPickerModal();
        renderTimerInlineBox();
    });

    // Syncs the full-screen Timer view to whatever timerState currently is -
    // called on entering the view, so navigating back mid-session shows the
    // running controls rather than resetting to the picker.
    function renderTimerScreen() {
        document.getElementById('timerSetupGroup')?.classList.toggle('hidden-group', !!timerState);
        document.getElementById('timerRunningGroup')?.classList.toggle('hidden-group', !timerState);
        if (timerState) {
            // ML-184 follow-up: see the card's own HTML comment - open-ended combines into "This
            // session" below instead of showing the same elapsed figure twice.
            document.getElementById('timerRemainingCard')?.classList.toggle('hidden-group', !!timerState.openEnded);
            updateTimerDisplays();
            updateTimerPlayIcons();
        }
    }

    function timerTick() {
        if (!timerState || !timerState.running) return;
        timerState.elapsedSeconds++;
        addTimerTodaySeconds(1);
        // No per-tick sync to the server (ML-197) - while running, getActiveTimerSession projects
        // elapsed_seconds forward from the last sync's updated_at using Postgres's own clock, so the
        // anchor set by the last start/pause/resume/snooze stays accurate to the second on its own;
        // a mid-tick sync here would only add network chatter, not accuracy.
        // ML-184: open-ended never runs out on its own - just keep banking elapsed time until Stop.
        if (timerState.openEnded) {
            updateTimerDisplays();
            return;
        }
        timerState.remainingSeconds--;
        updateTimerDisplays();
        if (timerState.remainingSeconds <= 0) finishTimerSession(true);
    }

    // ML-303: time's up stops the music with it - whichever metronome is playing (Quick Play, Rehearse,
    // Scales, Warm-ups) pauses where it is, not back to the start. Returns what to start again, which
    // only "Just another 5 minutes" does; saving it or not leaves it paused. (The drills - Tempo, Pulse,
    // Pitch, Range, Rhythm - are rounds of their own and aren't touched.)
    function pauseMusicForTimer() {
        const resume = [];
        if (qpPlayer.isPlaying()) { pauseQuickPlay(); resume.push(playQuickPlay); }
        if (flowPlayer.isPlaying()) { pauseFlow(); resume.push(playFlow); }
        if (scalesPlayer.isPlaying()) { scalesPause(); resume.push(scalesPlay); }
        if (warmupsPlayer.isPlaying()) { warmupsPause(); resume.push(warmupsPlay); }
        return resume;
    }

    // targetSeconds is null for an open-ended session (ML-184) - no countdown, so remainingSeconds
    // stays null too and is never read while openEnded (see timerTick/updateTimerDisplays).
    function startTimerSession(targetSeconds) {
        const openEnded = targetSeconds === null;
        timerState = { targetSeconds, remainingSeconds: openEnded ? null : targetSeconds, elapsedSeconds: 0, running: true, openEnded };
        if (!practiceRun || practiceRun.done) window.Usage?.begin('timer'); // ML-22 (a practice session's timer is the session's)
        clearInterval(timerIntervalId);
        timerIntervalId = setInterval(timerTick, 1000);
        renderTimerScreen();
        // Not hardcoded to 'timerView' any more - this can now also be reached from the inline box
        // while on some other screen entirely, so the indicator has to reflect whichever view is
        // actually active (it stays hidden regardless while the box itself is open).
        updateTopTimerIndicator(viewStack[viewStack.length - 1]);
        syncWakeLock();
        syncActiveTimerSession(); // ML-197
    }

    function toggleTimerPlayPause() {
        if (!timerState) return;
        timerState.running = !timerState.running;
        if (timerState.forSession) sessionSetPaused(!timerState.running); // ML-422: the session's blocks pause and carry on with it
        updateTimerPlayIcons();
        syncWakeLock();
        syncActiveTimerSession(); // ML-197: pause/resume matters enough to push immediately, not wait for the next periodic tick sync
    }

    // ML-185: carries the elapsed time (and enough of the original session's shape to resume it)
    // from finishTimerSession into the "session finished" popup's own button handlers below, so
    // "Just another 5 minutes" can rebuild timerState from exactly where it left off.
    let timerPendingFinish = null;

    // Ends the current timer (whether the countdown ran out - timeUp - or Stop/Close was
    // pressed early) and - if any real time was logged - offers to save it as a
    // practice session via the existing save-session screen, pre-filled.
    function finishTimerSession(timeUp = false) {
        if (!timerState) return;
        clearInterval(timerIntervalId);
        timerIntervalId = null;
        const forSession = !!timerState.forSession; // ML-421: a practice session's timer - the session carries on and logs the time itself
        if (!forSession && timeUp === true) window.Usage?.finish('timer'); // ML-22: ran to the end
        const resumeMusic = timeUp === true && !forSession ? pauseMusicForTimer() : []; // the Stop buttons pass their click event
        const { elapsedSeconds, openEnded, targetSeconds } = timerState;
        timerState = null;
        renderTimerScreen();
        // Also closes the inline box if it was open - nothing left for it to control once the
        // session has actually ended (recomputes the top-bar indicator either way).
        closeTimerInlineBox();
        syncWakeLock();
        API.timer.clearActive().catch(() => {}); // ML-197: nothing left to resume once the session's actually over

        if (forSession) { if (timeUp === true) sessionOverTime(elapsedSeconds, targetSeconds); return; } // ML-422: over the session's time
        if (elapsedSeconds < 1) return;
        timerPendingFinish = { elapsedSeconds, openEnded, targetSeconds, resumeMusic };
        openTimerFinishedModal();
    }

    function openTimerFinishedModal() {
        const minutes = Math.max(1, Math.round(timerPendingFinish.elapsedSeconds / 60));
        document.getElementById('timerFinishedMessage').innerText = `Would you like to store this ${minutes} minute session as a practice session?`;
        showModal('timerFinishedModal');
    }
    function closeTimerFinishedModal() {
        hideModal('timerFinishedModal');
    }
    document.getElementById('timerFinishedYesBtn')?.addEventListener('click', () => {
        if (!timerPendingFinish) return closeTimerFinishedModal();
        const minutes = Math.max(1, Math.round(timerPendingFinish.elapsedSeconds / 60));
        timerPendingFinish = null;
        closeTimerFinishedModal();
        prefillEntryFormForTimer(minutes);
        switchView('entryForm');
    });
    document.getElementById('timerFinishedNoBtn')?.addEventListener('click', () => {
        timerPendingFinish = null;
        closeTimerFinishedModal();
    });
    // ML-185's "snooze" button - resumes from exactly the elapsed time already banked (not a fresh
    // 0:00), so however many times this gets pressed in a row, the total offered for saving next
    // keeps growing by 5 minutes each time rather than resetting. A countdown session gets 5 more
    // minutes added to its target and remaining; an open-ended one just keeps counting up (there was
    // never a target to extend).
    document.getElementById('timerFinishedExtendBtn')?.addEventListener('click', () => {
        if (!timerPendingFinish) return closeTimerFinishedModal();
        const { elapsedSeconds, openEnded, targetSeconds, resumeMusic } = timerPendingFinish;
        timerPendingFinish = null;
        closeTimerFinishedModal();
        resumeMusic.forEach(play => play()); // ML-303: the music picks up where time ran out
        timerState = {
            targetSeconds: openEnded ? null : (targetSeconds || 0) + 300,
            remainingSeconds: openEnded ? null : 300,
            elapsedSeconds,
            running: true,
            openEnded
        };
        clearInterval(timerIntervalId);
        timerIntervalId = setInterval(timerTick, 1000);
        renderTimerScreen();
        updateTopTimerIndicator(viewStack[viewStack.length - 1]);
        syncWakeLock();
        syncActiveTimerSession(); // ML-197
    });

    // Pre-selects Practise + the timer's actual duration on the save-session
    // screen - falls back to the Custom entry if the timer's minutes don't match
    // one of the duration_options presets (ML-7).
    function prefillEntryFormForTimer(minutes) {
        document.querySelectorAll('input[name="category"]').forEach(r => { r.checked = (r.value === 'Practise'); });
        document.getElementById('whoGroup')?.classList.add('hidden-group');
        document.querySelectorAll('input[name="durationOption"]').forEach(r => { r.checked = false; });
        const customGroup = document.getElementById('customDurationGroup');
        const matchingRadio = document.getElementById(`dur-${minutes}`);
        if (matchingRadio) {
            matchingRadio.checked = true;
            customGroup?.classList.add('hidden-group');
        } else {
            const customRadio = document.getElementById('dur-custom');
            if (customRadio) customRadio.checked = true;
            customGroup?.classList.remove('hidden-group');
            const customInput = document.getElementById('duration');
            if (customInput) customInput.value = minutes;
        }
        document.getElementById('date').valueAsDate = new Date();
    }

    document.getElementById('timerDurationRadios')?.addEventListener('change', (e) => {
        if (e.target.name !== 'timerDurationOption') return;
        const customGroup = document.getElementById('timerCustomDurationGroup');
        if (e.target.value === 'custom') {
            customGroup.classList.remove('hidden-group');
            document.getElementById('timerCustomDuration')?.focus();
        } else {
            customGroup.classList.add('hidden-group');
        }
    });

    document.getElementById('timerStartBtn')?.addEventListener('click', () => {
        const radio = document.querySelector('input[name="timerDurationOption"]:checked')?.value;
        if (radio === 'open-ended') { startTimerSession(null); return; }
        const mins = Number(radio === 'custom' ? document.getElementById('timerCustomDuration')?.value : radio);
        if (!mins || isNaN(mins) || mins <= 0) { showWarningToast('Pick a duration first!'); return; }
        startTimerSession(mins * 60);
    });

    document.getElementById('timerPlayBtn')?.addEventListener('click', toggleTimerPlayPause);
    document.getElementById('timerStopBtn')?.addEventListener('click', finishTimerSession);

    // ===== ML-356: Display and reading (docs/display-and-reading.md) =====
    // Saved on the account so they follow you to every device; a copy stays on the device
    // (tml.display) so display-prefs.js can apply them before the page draws next time.
    // dyslexia is the "Increased spacing" switch (more line, letter and word spacing, no italics) - ML-359.
    // reduceMotion is ML-603's switch: on = reduce motion everywhere, off = do what the device says (display-prefs.js).
    const DISPLAY_DEFAULTS = { darkMode: false, dyslexia: false, font: 'standard', background: 'standard', textSize: 'standard', reduceMotion: false };
    let displayPrefs = { ...DISPLAY_DEFAULTS };
    try { displayPrefs = { ...DISPLAY_DEFAULTS, ...JSON.parse(localStorage.getItem('tml.display') || '{}') }; } catch (e) { /* defaults */ }
    if (localStorage.getItem('tml.display') === null && localStorage.getItem('darkMode') === 'true') displayPrefs.darkMode = true;
    function useDisplayPrefs(prefs) {
        displayPrefs = { ...DISPLAY_DEFAULTS, ...prefs };
        window.applyDisplayPrefs(displayPrefs);
        try {
            localStorage.setItem('tml.display', JSON.stringify(displayPrefs));
            localStorage.setItem('darkMode', String(displayPrefs.darkMode)); // older copies of the app read this
        } catch (e) { /* the account copy is the real one */ }
        renderDisplaySettings();
    }
    async function loadDisplayPrefs() {
        try {
            const { prefs } = await apiCall('/api/account/display');
            // First time on the account: keep what this device already had (dark mode), and save it.
            if (!Object.keys(prefs).length) { saveDisplayPrefs(displayPrefs); return; }
            useDisplayPrefs(prefs);
        } catch (e) { renderDisplaySettings(); } // offline: the device's copy stands
    }
    async function saveDisplayPrefs(changes) {
        useDisplayPrefs({ ...displayPrefs, ...changes });
        try { await apiCall('/api/account/display', 'PUT', { prefs: displayPrefs }); }
        catch (e) { showWarningToast('Saved on this device only - ' + e.message); }
    }
    function displaySummary() {
        const bits = [displayPrefs.darkMode ? 'Dark mode' : 'Light mode'];
        if (displayPrefs.dyslexia) bits.push('more spacing');
        if (displayPrefs.font !== 'standard') bits.push(displayPrefs.font === 'lexend' ? 'Lexend' : 'OpenDyslexic');
        if (displayPrefs.textSize !== 'standard') bits.push(displayPrefs.textSize === 'larger' ? 'extra large text' : 'large text');
        if (displayPrefs.reduceMotion) bits.push('reduced motion');
        return bits.join(', ');
    }
    // The preview is pinned under the top bar, whose height changes with text size and a wrapping title:
    // --header-h follows it (a run-time value, specs/components/utilities-and-states.md).
    (() => {
        const header = document.querySelector('.top-bar-sticky-group');
        if (!header || typeof ResizeObserver === 'undefined') return;
        new ResizeObserver(() => document.documentElement.style.setProperty('--header-h', `${header.offsetHeight}px`)).observe(header);
    })();
    // The preview's line of music: a C major scale, up an octave (drawn by Notation, so it follows the colours).
    const DISPLAY_PREVIEW_SCALE = ['C4', 'D4', 'E4', 'F4', 'G4', 'A4', 'B4', 'C5'];
    function renderDisplayPreview() {
        const el = document.getElementById('displayPreviewStaff');
        if (!el || el.firstChild) return; // drawn once - colour, font and size come from the page
        const items = [];
        DISPLAY_PREVIEW_SCALE.forEach((pitch, i) => {
            items.push({ type: 'note', pitch, head: Notation.staffStep(pitch, 'treble') >= 4 ? 'noteQuarterDown' : 'noteQuarterUp' });
            if (i === 3) items.push({ type: 'barline', glyph: 'barlineSingle' });
        });
        items.push({ type: 'barline', glyph: 'barlineFinal' });
        el.innerHTML = Notation.staff({ clef: 'treble', items: [{ type: 'timeSig', top: 4, bottom: 4 }, ...items], noteGap: 2.4, label: 'Preview: a C major scale, one octave up' });
    }
    function renderDisplaySettings() {
        const light = document.getElementById('displayTheme-light');
        if (!light) return;
        light.checked = !displayPrefs.darkMode;
        document.getElementById('displayTheme-dark').checked = displayPrefs.darkMode;
        document.getElementById('readingSpacingToggle').checked = displayPrefs.dyslexia;
        document.getElementById('displayMotionToggle').checked = displayPrefs.reduceMotion;
        document.getElementById('displayMotionHelp').textContent = motionHelpText();
        [['readingFont', 'font'], ['readingBackground', 'background'], ['readingTextSize', 'textSize']].forEach(([name, key]) => {
            const r = document.getElementById(`${name}-${displayPrefs[key]}`);
            if (r) r.checked = true;
        });
        const sum = document.getElementById('settingsDisplaySummary');
        if (sum) sum.textContent = displaySummary();
        const reset = document.getElementById('displayResetBtn');
        if (reset) reset.disabled = readingIsStandard();
        renderDisplayPreview();
    }
    document.querySelectorAll('input[name="displayTheme"]').forEach(r => r.addEventListener('change', () => { if (r.checked) saveDisplayPrefs({ darkMode: r.value === 'dark' }); }));
    document.getElementById('readingSpacingToggle')?.addEventListener('change', (e) => saveDisplayPrefs({ dyslexia: e.target.checked }));
    document.getElementById('displayMotionToggle')?.addEventListener('change', (e) => saveDisplayPrefs({ reduceMotion: e.target.checked }));
    // With the switch off, a device that already asks for less motion still gets it - the help line says so.
    function motionHelpText() {
        return !displayPrefs.reduceMotion && deviceReducesMotion()
            ? 'Already on, because this device asks for less motion'
            : 'Things appear and go instead of sliding or fading';
    }
    try { window.matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change', renderDisplaySettings); } catch (e) { /* an old browser: the line catches up next time */ }
    // Reset to standard: the reading choices (background, font, text size, spacing) back to standard, with
    // an Undo. Light / Dark is left alone - it's a theme, not a reading aid. Always at the bottom; disabled
    // while they're all standard already.
    const READING_KEYS = ['font', 'background', 'textSize', 'dyslexia'];
    const readingIsStandard = () => READING_KEYS.every(k => displayPrefs[k] === DISPLAY_DEFAULTS[k]);
    document.getElementById('displayResetBtn')?.addEventListener('click', () => {
        const before = Object.fromEntries(READING_KEYS.map(k => [k, displayPrefs[k]]));
        saveDisplayPrefs(Object.fromEntries(READING_KEYS.map(k => [k, DISPLAY_DEFAULTS[k]])));
        showUndoToast('Reading settings back to standard', () => saveDisplayPrefs(before));
    });
    [['readingFont', 'font'], ['readingBackground', 'background'], ['readingTextSize', 'textSize']].forEach(([name, key]) => {
        document.querySelectorAll(`input[name="${name}"]`).forEach(r => r.addEventListener('change', () => { if (r.checked) saveDisplayPrefs({ [key]: r.value }); }));
    });
    renderDisplaySettings();

    // ========================================
    // THEORY PRACTICE (ML-260, screens ML-264, saving ML-265)
    // ========================================
    // Four views: theoryView (quiz list) -> theoryOptionsView -> theoryPlayView -> theoryResultsView.
    // Everything musical comes from elsewhere: questions, answers and scoring from TheoryEngine
    // (public/theoryEngine.js), every note/symbol drawn by Notation (public/notation.js, Bravura).
    // This section only runs the round: the clock, taps, feedback, saving and history.
    // docs/theory-practice.md has the rules.
    // var, not let: switchView (defined much earlier) reads these, and must never hit the temporal dead
    // zone if it runs before this part of the script has.
    var theoryQuizId = null;
    let theoryOptions = null;      // normalised options for theoryQuizId
    let theoryRoundId = TheoryEngine.DEFAULT_ROUND;
    let theoryRepeats = TheoryEngine.DEFAULT_REPEATS; // ML-354: the round done 1-5 times, best one counts
    var theoryRound = null;        // the round in progress, or null
    var theoryLastResult = null;   // what the results screen shows
    let theoryTicker = null;
    let theoryTestOffsetMs = 0;    // test hook's virtual clock (always 0 outside local tests)
    const THEORY_PROMPT_SCALE = 1.6;   // SVG user units -> px: a staff space is 16px on screen
    const THEORY_SYMBOL_SCALE = 1.4;   // symbols inside answer buttons (capped by the button, style.css)

    const theoryNow = () => performance.now() + theoryTestOffsetMs;
    function theoryNaming() {
        try { return localStorage.getItem(TUNER_NOTE_STYLE_KEY) === 'solfege' ? 'solfege' : 'letters'; } catch (e) { return 'letters'; }
    }
    function theoryStoredChoice(quizId) {
        try {
            const raw = JSON.parse(localStorage.getItem(`tml.theory.${quizId}`) || 'null');
            return raw && typeof raw === 'object' ? raw : {};
        } catch (e) { return {}; }
    }
    function theoryStoreChoice() {
        try { localStorage.setItem(`tml.theory.${theoryQuizId}`, JSON.stringify({ options: theoryOptions, round: theoryRoundId, repeats: theoryRepeats })); } catch (e) { /* per-device convenience only */ }
    }
    // Notation draws at 1 unit per px; scale its width/height (the viewBox keeps the drawing) so a
    // staff space is the same size on every question. CSS max-width shrinks it on a narrow phone.
    function theoryScaleSvg(svg, k) {
        return svg.replace(/width="([\d.]+)" height="([\d.]+)"/, (m, w, h) => `width="${Math.round(w * k)}" height="${Math.round(h * k)}"`);
    }
    function theoryVisual(render, label, k) {
        let svg;
        if (render.type === 'symbol') svg = Notation.symbol(render.glyph, { label });
        else if (render.type === 'staff') svg = Notation.staff({ ...render.staff, label });
        else if (render.type === 'hairpin') svg = Notation.hairpin(render.dir, { label });
        else if (render.type === 'tempo') svg = Notation.tempoMark(render.bpm, { label });
        else svg = Notation.textMark(render.text, { italic: render.italic, bold: render.bold, label });
        return theoryScaleSvg(svg, k);
    }
    // ML-396: a round's result is a Level 1-5, in the practice Level colours (silver 1-2, gold 3-5). On
    // screen "grade" only ever means the Theory grade picked; the stored column is still `grade`.
    const theoryLevelChip = (level, label) => `<span class="level-chip lv-${level}" role="img" aria-label="${escapeHtml(label || `Level ${level} of 5`)}">${level}</span>`;
    // The result itself: five steps rising in height and colour, yours ringed, the ones above it dashed.
    const theoryStepsHtml = (level) => [1, 2, 3, 4, 5].map(i => `<span class="theory-step theory-lv-h${i} ${i <= level ? `lv-${i}` : 'lv-0'}${i === level ? ' is-got' : ''}">${i}</span>`).join('');
    // The last rounds with one set of options, oldest first: a bar per round, coloured and sized by its
    // Level, the number inside. nowLast rings the newest and calls it "Now" (the results screen).
    function theoryLevelBarsHtml(recent, nowLast) {
        const when = (a) => new Date(a.startedAt).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
        return `<div class="theory-level-bars" role="img" aria-label="Levels of your last ${recent.length} ${recent.length === 1 ? 'round' : 'rounds'}: ${recent.map(a => a.grade).join(', ')}">${recent.map((a, i) => {
            const now = nowLast && i === recent.length - 1;
            return `<span class="theory-level-slot${now ? ' is-now' : ''}"><span class="theory-level-bar theory-lv-h${a.grade} lv-${a.grade}">${a.grade}</span><span class="theory-level-when">${now ? 'Now' : (a.label || when(a))}</span></span>`;
        }).join('')}</div>`;
    }
    function theoryWhen(iso) {
        const d = new Date(iso);
        const days = Math.floor((new Date().setHours(0, 0, 0, 0) - new Date(d).setHours(0, 0, 0, 0)) / 86400000);
        if (days <= 0) return 'today';
        if (days === 1) return 'yesterday';
        if (days < 7) return `${days} days ago`;
        return d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
    }

    // --- The home tile's icon: a Bravura treble clef, like every other piece of notation. ---
    (function renderTheoryToolIcon() {
        const el = document.getElementById('theoryToolIcon');
        if (el) el.outerHTML = Notation.symbol('gClef').replace('class="notation"', 'class="notation tool-icon-svg"');
    })();

    // --- My instrument (ML-309): which of My account's instruments, per device (tml.theory.instrument,
    // default the main one). Its clef is where every quiz's Clef option starts; picking another
    // instrument moves every quiz to that clef. No instruments = a link to My account instead.
    const THEORY_INSTRUMENT_KEY = 'tml.theory.instrument';
    function theoryInstrument() {
        let id = null;
        try { id = Number(localStorage.getItem(THEORY_INSTRUMENT_KEY)) || null; } catch (e) { /* per-device only */ }
        return myInstruments.find(i => i.id === id) || myInstruments.find(i => i.isPrimary) || myInstruments[0] || null;
    }
    function theoryInstrumentClefs(inst) {
        if (!inst) return null;
        if (inst.theoryClef === 'grand') return ['treble', 'bass'];
        return ['treble', 'bass', 'alto', 'tenor'].includes(inst.theoryClef) ? [inst.theoryClef] : null;
    }
    function renderTheoryInstrument() {
        const inst = theoryInstrument();
        setShown('theoryInstrumentGroup', !!inst);
        setShown('theoryInstrumentSetBtn', !inst);
        const sel = document.getElementById('theoryInstrument');
        if (!sel || !inst) return;
        sel.innerHTML = myInstruments.map(i => `<option value="${i.id}">${escapeHtml(i.name)}</option>`).join('');
        sel.value = String(inst.id);
    }
    document.getElementById('theoryInstrument')?.addEventListener('change', (e) => {
        try { localStorage.setItem(THEORY_INSTRUMENT_KEY, e.target.value); } catch (err) { /* per-device only */ }
        const clefs = theoryInstrumentClefs(theoryInstrument());
        if (!clefs) return;
        for (const q of TheoryEngine.QUIZZES) {
            if (!q.options.some(d => d.key === 'clefs')) continue;
            const stored = theoryStoredChoice(q.id);
            const options = TheoryEngine.normaliseOptions(q.id, { ...(stored.options || {}), clefs });
            try { localStorage.setItem(`tml.theory.${q.id}`, JSON.stringify({ ...stored, options })); } catch (err) { /* per-device only */ }
        }
    });
    document.getElementById('theoryInstrumentSetBtn')?.addEventListener('click', () => switchView('accountInstrumentsView'));

    // --- Quiz list ---
    async function renderTheoryList() {
        renderTheoryInstrument();
        const list = document.getElementById('theoryQuizList');
        // ML-301: every quiz has a subtitle (so the rows are the same height); one you haven't tried has
        // a "New" pill where the last Level goes. The Level chip says it all - no "Level 2 · today" line (owner, ML-396).
        const row = (q, last) => `
            <button type="button" class="history-item clickable theory-quiz-row" data-quiz="${q.id}">
                <span class="theory-quiz-icon">${theoryScaleSvg(Notation.symbol(q.icon), 0.8)}</span>
                <span class="history-details"><strong>${escapeHtml(q.title)}</strong>${escapeHtml(q.subtitle || '')}</span>
                ${last ? theoryLevelChip(last.grade, `Last Level ${last.grade} of 5`) : loaded ? '<span class="flow-pill flow-pill-accent">New</span>' : ''}
            </button>`;
        // SmartLearn adds "Your weak spots" at the end: a round of only the questions you've been missing.
        const weakRow = (weak) => {
            const n = weak.length, q = TheoryEngine.WEAK_SPOTS;
            return `
            <button type="button" class="history-item clickable theory-quiz-row" data-quiz="${q.id}">
                <span class="theory-quiz-icon">${theoryScaleSvg(Notation.symbol(q.icon), 0.8)}</span>
                <span class="history-details"><strong>${escapeHtml(q.title)}</strong>${n ? `${n} ${n === 1 ? 'question' : 'questions'} to work on` : 'Questions you miss collect here'}</span>
            </button>`;
        };
        let summary = {}, weak = null, loaded = false;
        const draw = () => {
            // ML-309 C: the grade-only quizzes (Intervals, Chords) only while Theory grades are on.
            list.innerHTML = TheoryEngine.QUIZZES.filter(q => !q.gradeOnly || theoryGradesOn()).map(q => row(q, summary[q.id])).join('') + (weak ? weakRow(weak) : '');
            list.querySelectorAll('[data-quiz]').forEach(b => b.addEventListener('click', () => openTheoryOptions(b.dataset.quiz)));
        };
        draw();
        const [s, w] = await Promise.all([API.theory.summary().catch(() => null), theoryLoadSmart()]);
        if (s) { summary = s.quizzes || {}; loaded = true; }
        if (w) weak = w.weak;
        draw();
    }
    function openTheoryOptions(quizId) {
        theoryQuizId = quizId;
        const stored = theoryStoredChoice(quizId);
        const first = stored.options ? {} : { clefs: theoryInstrumentClefs(theoryInstrument()) || undefined };
        theoryOptions = TheoryEngine.normaliseOptions(quizId, { ...first, ...(stored.options || {}), ...(theoryGradesOn() ? {} : { grade: 0 }) });
        theoryRoundId = TheoryEngine.round(stored.round).value;
        theoryRepeats = TheoryEngine.repeatsOf(stored.repeats);
        theoryPlayedStale = true;
        theoryPlayedAll = false;
        switchView('theoryOptionsView');
    }

    // --- Options: two sections of value boxes, two to a row (owner, 2026-10-01 - a row of pills per option
    // was too much at once). Content: Theory grade, Clef, and on Custom the quiz's own options; Length:
    // Round and Repeat. Each box opens a pop-up: the choice list (openFlowChoiceModal), or for Clef - a
    // multi-select - a pick list (#theoryPickModal). docs/theory-practice.md.
    const theoryRepeatsText = (n) => (n === 1 ? '×1 - one round' : `×${n} - best of ${n} rounds`);
    // ML-309: Theory grades (feature theory_grades) - "Custom" is the quiz's own options, 1-5 a grade.
    const theoryGradesOn = () => isFeatureEnabled('theory_grades');
    // Grade 1 at the top, Custom at the bottom.
    const THEORY_GRADE_DEF = { key: 'grade', label: 'Theory grade', choices: [...TheoryEngine.GRADE_CHOICES.map(g => ({ value: g, label: `Grade ${g}` })), { value: 0, label: 'Custom' }] };
    // The caption under a box's value: the option's name, shorter where the name is long.
    const THEORY_CAPTIONS = { grade: 'grade', range: 'range', upTo: 'sharps or flats', round: 'round', repeats: 'repeat' };
    const theoryCaption = (def) => THEORY_CAPTIONS[def.key] || def.label.toLowerCase();
    // Sharps and flats are drawn as the Bravura signs, so "both" fits in the box.
    const THEORY_ACCIDENTAL_GLYPHS = { sharps: ['accidentalSharp'], flats: ['accidentalFlat'], both: ['accidentalSharp', 'accidentalFlat'] };
    const theoryGlyphs = (names) => names.map(n => theoryScaleSvg(Notation.symbol(n), 0.6)).join(' ');
    function theoryChoiceLabel(def, value) {
        const label = def.choices.find(c => c.value === value).label;
        return def.key === 'upTo' ? `Up to ${label}` : label;
    }
    function theoryValueText(def, value) {
        if (!def.multi) return theoryChoiceLabel(def, value);
        const labels = value.map(v => theoryChoiceLabel(def, v));
        return labels.length <= 2 ? labels.join(', ') : `${labels.length} clefs`;
    }
    const theoryValueHtml = (def, value) => (def.key === 'accidentals' && THEORY_ACCIDENTAL_GLYPHS[value]
        ? theoryGlyphs(THEORY_ACCIDENTAL_GLYPHS[value]) : escapeHtml(theoryValueText(def, value)));
    // { def, valueHtml, ariaValue } -> a value box
    const theoryOptionBox = (b) => `
        <button type="button" class="metroBlk-ctrl-value-btn" id="theoryOptBtn-${b.def.key}" data-theory-opt="${b.def.key}" aria-haspopup="dialog" aria-label="${escapeHtml(`${b.def.label}: ${b.ariaValue} - tap to change`)}">
            <strong>${b.valueHtml}</strong><span class="metroBlk-ctrl-value-label">${escapeHtml(theoryCaption(b.def))}</span>
        </button>`;
    function renderTheoryOptions() {
        const quiz = TheoryEngine.quiz(theoryQuizId);
        const gradeClefs = theoryOptions.grade ? TheoryEngine.gradeContent(theoryOptions.grade).clefs : null;
        const choose = (key, value) => {
            theoryOptions = TheoryEngine.normaliseOptions(theoryQuizId, { ...theoryOptions, [key]: value });
            theoryStoreChoice();
            renderTheoryOptions(); // a grade, or the minor form's showIf, changes which boxes show
        };
        // A single choice: the choice list, the one on now ticked. rowHtml adds to a row's label (the signs).
        const pickOne = (def, current, onPick, rowHtml) => () => openFlowChoiceModal(def.label, def.choices.map(c => ({
            value: c.value, label: c.label, selected: c.value === current,
            html: rowHtml ? `<span>${escapeHtml(c.label)}${rowHtml(c.value)}</span>${c.value === current ? '<span class="material-symbols-outlined" aria-hidden="true">check</span>' : ''}` : undefined
        })), (opt) => onPick(opt.value));
        const content = [];
        // A grade-only quiz (ML-309 C) offers just its own grades - no Custom.
        if (theoryGradesOn() && quiz.options.length) {
            const def = quiz.gradeOnly ? { ...THEORY_GRADE_DEF, choices: THEORY_GRADE_DEF.choices.filter(c => quiz.grades.includes(c.value)) } : THEORY_GRADE_DEF;
            content.push({ def, value: theoryOptions.grade, open: pickOne(def, theoryOptions.grade, (v) => choose('grade', v)) });
        }
        for (const d of quiz.options.filter(x => TheoryEngine.optionVisible(x, theoryOptions))) {
            const def = d.key === 'clefs' && gradeClefs ? { ...d, choices: d.choices.filter(c => gradeClefs.includes(c.value)) } : d;
            const value = theoryOptions[d.key];
            const signs = d.key === 'accidentals' ? (v) => (THEORY_ACCIDENTAL_GLYPHS[v] ? ` ${theoryGlyphs(THEORY_ACCIDENTAL_GLYPHS[v])}` : '') : null;
            content.push({ def, value, open: d.multi ? () => openTheoryPick(def) : pickOne(def, value, (v) => choose(d.key, v), signs) });
        }
        const roundDef = { key: 'round', label: 'Round', choices: TheoryEngine.ROUNDS.map(r => ({ value: r.value, label: r.label })) };
        const repeatsDef = { key: 'repeats', label: 'Repeat', choices: TheoryEngine.REPEATS.map(n => ({ value: n, label: theoryRepeatsText(n) })) };
        const length = [
            { def: roundDef, value: theoryRoundId, open: pickOne(roundDef, theoryRoundId, (v) => { theoryRoundId = v; theoryStoreChoice(); renderTheoryOptions(); }) },
            // ML-354: a longer test is the same round again, x1-x5, the best one counting
            { def: repeatsDef, value: theoryRepeats, valueHtml: `&times;${theoryRepeats}`, ariaValue: theoryRepeatsText(theoryRepeats),
                open: pickOne(repeatsDef, theoryRepeats, (v) => { theoryRepeats = v; theoryStoreChoice(); renderTheoryOptions(); }) },
        ];
        for (const b of [...content, ...length]) {
            b.valueHtml = b.valueHtml || theoryValueHtml(b.def, b.value);
            b.ariaValue = b.ariaValue || theoryValueText(b.def, b.value);
        }
        const section = (id, title, boxes) => (boxes.length ? `
            <div class="tool-group" role="group" aria-labelledby="theoryOptTitle-${id}">
                <div class="tool-group-title" id="theoryOptTitle-${id}">${title}</div>
                <div class="metro-transport-grid metro-transport-grid-2">${boxes.map(theoryOptionBox).join('')}</div>
            </div>` : '');
        const form = document.getElementById('theoryOptionsForm');
        form.innerHTML = section('content', 'Content', content) + section('length', 'Length', length);
        for (const b of [...content, ...length]) form.querySelector(`[data-theory-opt="${b.def.key}"]`).addEventListener('click', b.open);
        renderTheoryPlayed();
        renderTheorySmartLearnNote();
        renderTheoryWeakList();
    }
    // Clef is a multi-select: a pick list, each tick applied as it's made (at least one clef stays ticked).
    function openTheoryPick(def) {
        const picked = new Set(theoryOptions[def.key]);
        const rows = def.choices.map(c => ({ key: c.value, html: escapeHtml(c.label) }));
        document.getElementById('theoryPickTitle').textContent = def.label;
        const draw = () => renderPickList(document.getElementById('theoryPickList'), null, rows, picked, () => {
            if (!picked.size) { theoryOptions[def.key].forEach(v => picked.add(v)); draw(); return; }
            const now = def.choices.map(c => c.value).filter(v => picked.has(v));
            if (now.join() === theoryOptions[def.key].join()) return;
            theoryOptions = TheoryEngine.normaliseOptions(theoryQuizId, { ...theoryOptions, [def.key]: now });
            theoryStoreChoice();
            renderTheoryOptions();
        });
        draw();
        showModal('theoryPickModal');
    }
    (() => {
        const modal = document.getElementById('theoryPickModal');
        if (!modal) return;
        modal.querySelectorAll('[data-modal-close]').forEach(b => b.addEventListener('click', () => hideModal(modal)));
        modal.addEventListener('click', (e) => { if (e.target === e.currentTarget) hideModal(modal); });
    })();
    // --- What I've played (ML-396): under Start, a row per set of options played in this quiz, newest
    // first, with the last Level. The row matching the boxes is ringed. Tapping one opens its pop-up
    // (the last rounds, what's included, what each Level takes, "Use these options"). Nothing shows
    // before the first round. Repeat isn't part of a set (x1 and x4 share one history).
    // "What's included in Grade N?" sits under the Content boxes until any round of that grade has
    // been played here - after that its row says it. Never for Custom: you chose those yourself.
    let theoryPlayed = null;       // { quizId, sets } from GET /api/theory/played
    var theoryPlayedStale = true;  // load again on the next draw: another quiz, or a round just saved
    let theoryPlayedAll = false;   // "Show more" tapped
    const THEORY_PLAYED_ROWS = 6;
    const theoryTimes = (n) => (n === 1 ? 'once' : n === 2 ? 'twice' : `${n} times`);
    const theoryCapital = (s) => s.charAt(0).toUpperCase() + s.slice(1);
    function renderTheoryPlayed() {
        const el = document.getElementById('theoryPlayed');
        const link = document.getElementById('theoryIncludedBtn');
        const sets = theoryPlayed && theoryPlayed.quizId === theoryQuizId ? theoryPlayed.sets : null;
        const grade = theoryOptions.grade;
        setShown(link, !!(sets && grade && !sets.some(s => s.options && s.options.grade === grade)));
        link.textContent = `What's included in Grade ${grade}?`;
        if (!sets || !sets.length) el.innerHTML = '';
        else {
            const key = TheoryEngine.settingsKey(theoryQuizId, theoryOptions, theoryRoundId);
            const shown = theoryPlayedAll ? sets : sets.slice(0, THEORY_PLAYED_ROWS);
            el.innerHTML = `<div class="section-title">What I've played</div>` + shown.map((s, i) => {
                const d = TheoryEngine.describeSet(theoryQuizId, s.options, s.roundType, { grades: theoryGradesOn() });
                const current = s.settingsKey === key;
                return `
                <button type="button" class="history-item clickable theory-quiz-row${current ? ' level-row-selected' : ''}" data-set="${i}"${current ? ' aria-current="true"' : ''}>
                    <span class="history-details"><strong>${escapeHtml(d.title)}</strong>${d.detail ? `${escapeHtml(d.detail)}<br>` : ''}${theoryCapital(theoryWhen(s.startedAt))} · played ${theoryTimes(s.rounds)}</span>
                    ${theoryLevelChip(s.grade, `Last Level ${s.grade} of 5`)}
                </button>`;
            }).join('') + (sets.length > shown.length ? '<button type="button" class="btn-text" id="theoryPlayedMoreBtn">Show more</button>' : '');
            el.querySelectorAll('[data-set]').forEach(b => b.addEventListener('click', () => openTheorySet(shown[Number(b.dataset.set)])));
            document.getElementById('theoryPlayedMoreBtn')?.addEventListener('click', () => { theoryPlayedAll = true; renderTheoryPlayed(); });
        }
        if (!theoryPlayedStale || theoryQuizId === TheoryEngine.WEAK_SPOTS.id) return;
        theoryPlayedStale = false;
        const quizId = theoryQuizId;
        API.theory.played(quizId).then(res => {
            theoryPlayed = { quizId, sets: (res && res.sets) || [] };
            if (theoryQuizId === quizId && isShown('theoryOptionsView')) renderTheoryPlayed();
        }).catch(() => { /* not essential */ });
    }
    document.getElementById('theoryIncludedBtn')?.addEventListener('click', () => openTheorySet(null));
    // The pop-up for one set of options: a played row (its last rounds, then "Use these options"), or
    // null = what the boxes say now (the "What's included" link - nothing played yet, so no chart).
    let theorySetShown = null;     // { options, roundId } "Use these options" applies, or null (Close)
    let drillSetApply = null;      // ML-406: a drill's played row is showing - what "Use these options" does
    async function openTheorySet(set) {
        const options = set ? TheoryEngine.normaliseOptions(theoryQuizId, { ...set.options, ...(theoryGradesOn() ? {} : { grade: 0 }) }) : theoryOptions;
        const roundId = set ? TheoryEngine.round(set.roundType).value : theoryRoundId;
        drillSetApply = null;
        let recent = [];
        if (set) { try { recent = (await API.theory.history(set.settingsKey)).recent || []; } catch (e) { /* the rest still shows */ } }
        theorySetShown = set ? { options, roundId } : null;
        const d = TheoryEngine.describeSet(theoryQuizId, options, roundId, { grades: theoryGradesOn() });
        document.getElementById('theorySetTitle').textContent = d.title;
        const sub = document.getElementById('theorySetSub');
        sub.textContent = [d.detail, set ? `Played ${theoryTimes(set.rounds)} · last played ${theoryWhen(set.startedAt)}` : ''].filter(Boolean).join(' · ');
        setShown(sub, !!sub.textContent);
        const inc = TheoryEngine.includedFor(theoryQuizId, options, roundId);
        const targets = TheoryEngine.levelTargets(theoryQuizId, options, roundId);
        document.getElementById('theorySetBody').innerHTML =
            (recent.length ? `<div class="section-title">My last rounds</div><div class="theory-level-trend">${theoryLevelBarsHtml(recent, false)}</div>` : '')
            + `<div class="section-title">What's included</div>`
            + (inc.staffs.length ? `<div class="theory-included-staffs">${inc.staffs.map(st => Notation.staff({ clef: st.clef, items: [{ type: 'note', pitch: st.low }, { type: 'note', pitch: st.high }], stepRange: st.stepRange, label: `The lowest and highest notes asked on the ${st.clef} staff` })).join('')}</div>` : '')
            + `<ul class="theory-included">${inc.lines.map(l => `<li><strong>${escapeHtml(l.label)}:</strong> ${escapeHtml(l.text)}</li>`).join('')}</ul>`
            + (targets ? `<div class="section-title">Levels for this round</div><div class="theory-level-key"><span><span class="level-chip lv-1">1</span>start</span>${targets.map(t => `<span><span class="level-chip lv-${t.level}">${t.level}</span>${t.right} right</span>`).join('')}</div>` : '');
        const use = document.getElementById('theorySetUseBtn');
        use.textContent = set ? 'Use these options' : 'Close';
        use.classList.toggle('btn-submit', !!set);
        use.classList.toggle('btn-nav', !set);
        showModal('theorySetModal');
    }
    (() => {
        const modal = document.getElementById('theorySetModal');
        if (!modal) return;
        modal.querySelectorAll('[data-modal-close]').forEach(b => b.addEventListener('click', () => hideModal(modal)));
        modal.addEventListener('click', (e) => { if (e.target === e.currentTarget) hideModal(modal); });
        document.getElementById('theorySetUseBtn').addEventListener('click', () => {
            hideModal(modal);
            if (drillSetApply) { const apply = drillSetApply; drillSetApply = null; apply(); return; }
            if (!theorySetShown) return;
            theoryOptions = theorySetShown.options;
            theoryRoundId = theorySetShown.roundId;
            theoryStoreChoice();
            renderTheoryOptions();
        });
    })();
    document.getElementById('theoryStartBtn')?.addEventListener('click', () => theoryStartRound());

    // --- Smart learn (ML-269, theory_smart_learn): the questions you get wrong are dealt first and more
    // often. The weights come from the server at the start of each round (it updates them from every
    // finished round); null = a plain shuffle with no memory - also the fallback if loading fails.
    const theorySmartLearnOn = () => isFeatureEnabled('theory_smart_learn');
    // { weights (what rounds deal by, review boost included), weak (the weak spots list) }, or null.
    async function theoryLoadSmart() {
        if (!theorySmartLearnOn()) return null;
        try {
            const res = await Promise.race([API.theory.weights(), new Promise((_, no) => setTimeout(() => no(new Error('slow')), 3000))]);
            return res && res.enabled ? res : null;
        } catch (e) { return null; }
    }
    // A weak spots round deals by the stored weights only (a review boost isn't a weak spot).
    async function theoryLoadWeights() {
        const smart = await theoryLoadSmart();
        if (!smart) return null;
        return theoryQuizId === TheoryEngine.WEAK_SPOTS.id ? Object.fromEntries(smart.weak.map(x => [x.id, x.weight])) : smart.weights;
    }
    // The weak spots options screen lists what's in the round, weakest first.
    async function renderTheoryWeakList() {
        const el = document.getElementById('theoryWeakList');
        if (!el) return;
        if (theoryQuizId !== TheoryEngine.WEAK_SPOTS.id) { el.innerHTML = ''; document.getElementById('theoryStartBtn').classList.remove('hidden-group'); return; }
        const smart = await theoryLoadSmart();
        const weak = smart ? smart.weak : [];
        const naming = theoryNaming();
        el.innerHTML = weak.length
            ? `<div class="section-title">To work on</div>` + weak.map(x => `
                <div class="history-item"><span class="history-details"><strong>${escapeHtml(TheoryEngine.describeQuestion(x.id, naming))}</strong>Needs work: ${x.weight} of 10 · missed ${x.wrong}, right ${x.right}</span></div>`).join('')
            : '<p class="theory-intro">Nothing to work on yet. Questions you get wrong in any quiz collect here, and leave once you\'ve got them right twice for every miss.</p>';
        document.getElementById('theoryStartBtn').classList.toggle('hidden-group', !weak.length);
    }
    // ML-396: SmartLearn has its own strip on the options screen - "SmartLearn applied" where the account
    // has it, "Learn faster with SmartLearn" where it doesn't - with Learn more, a pop-up saying what it
    // does and why it works. Without it the pop-up ends in "Upgrade now": there's no payment screen
    // yet, so that emails the owner the request (POST /api/upgrade-requests), once per device.
    const SMARTLEARN_ASKED_KEY = 'tml.upgradeAsked.theory_smart_learn';
    // The same strip on Theory's options and the Pitch and Tempo setup screens (ML-399: one switch for all).
    function renderSmartLearnStrip(boxId, textId) {
        const el = document.getElementById(boxId);
        if (!el) return;
        const on = theorySmartLearnOn();
        el.classList.toggle('is-on', on);
        document.getElementById(textId).textContent = on ? 'SmartLearn applied' : 'Learn faster with SmartLearn';
    }
    const renderTheorySmartLearnNote = () => renderSmartLearnStrip('theoryOptionsSmart', 'theorySmartText');
    // What SmartLearn took from a round, for the results box. s: { learning, missed, slower } from the
    // server; noun: 'question' / 'note' / 'speed'; nearly: what the not-quite ones are called.
    function smartLearnMessage(s, noun, nearly) {
        const learning = (s && s.learning) || 0, missed = (s && s.missed) || 0, slower = (s && s.slower) || 0;
        const n = (k) => `${k} ${noun}${k === 1 ? '' : 's'}`;
        // ML-407: learning counts only what this round gave it - a perfect round brings nothing back.
        return !learning ? 'SmartLearn: nothing from this round to bring back.'
            : !slower ? `SmartLearn will bring back ${n(learning)} from this round sooner, until you've got ${learning === 1 ? 'it' : 'them'} right.`
            : !missed ? `SmartLearn will bring back ${n(slower)} ${nearly}.`
            : `SmartLearn will bring back ${n(learning)}: ${missed} to get right, ${slower} ${nearly}.`;
    }
    // A drill's weights for one level, or null (SmartLearn off, slow, or failed) = the plain round.
    async function drillLoadWeights(tool, level) {
        if (!theorySmartLearnOn()) return null;
        try {
            const res = await Promise.race([API.drills.weights(tool, level), new Promise((_, no) => setTimeout(() => no(new Error('slow')), 3000))]);
            return res && res.enabled ? res.weights : null;
        } catch (e) { return null; }
    }
    // A back-test's fixed-seed round is the plain one unless it asks for SmartLearn (__drillTest.smart).
    const drillSmartFor = (seed) => seed === undefined || seed === null || !!(window.__drillTest && window.__drillTest.smart);
    function openSmartLearn() {
        const on = theorySmartLearnOn();
        let asked = false;
        try { asked = localStorage.getItem(SMARTLEARN_ASKED_KEY) === '1'; } catch (e) { /* per-device only */ }
        document.getElementById('smartLearnStatus').textContent = on ? 'SmartLearn is applied to every Theory, Pitch and Tempo round you play.' : 'SmartLearn is an upgrade - it isn\'t part of your account yet.';
        const btn = document.getElementById('smartLearnActionBtn');
        btn.textContent = on ? 'Close' : asked ? 'Upgrade requested' : 'Upgrade now';
        btn.disabled = !on && asked;
        btn.classList.toggle('btn-submit', !on);
        btn.classList.toggle('btn-nav', on);
        showModal('smartLearnModal');
    }
    document.querySelectorAll('.smartlearn-more').forEach(b => b.addEventListener('click', openSmartLearn)); // options and results
    (() => {
        const modal = document.getElementById('smartLearnModal');
        if (!modal) return;
        modal.querySelectorAll('[data-modal-close]').forEach(b => b.addEventListener('click', () => hideModal(modal)));
        modal.addEventListener('click', (e) => { if (e.target === e.currentTarget) hideModal(modal); });
        const btn = document.getElementById('smartLearnActionBtn');
        btn.addEventListener('click', async () => {
            if (theorySmartLearnOn()) { hideModal(modal); return; }
            btn.disabled = true;
            try {
                await API.upgrade.request('theory_smart_learn');
                try { localStorage.setItem(SMARTLEARN_ASKED_KEY, '1'); } catch (e) { /* per-device only */ }
                hideModal(modal);
                showSuccessToast("Thanks - we'll be in touch about SmartLearn");
            } catch (error) {
                btn.disabled = false;
                showWarningToast("Couldn't send your request: " + error.message);
            }
        });
    })();

    // --- The round ---
    function theoryRoundInProgress() { return !!(theoryRound && !theoryRound.ended); }
    function theoryElapsedMs(r) { return r.accumulatedMs + (r.runningSince === null ? 0 : theoryNow() - r.runningSince); }

    let theoryStarting = false;
    async function theoryStartRound(seed) {
        if (theoryStarting) return;
        theoryStarting = true;
        let weights;
        try { weights = await theoryLoadWeights(); } finally { theoryStarting = false; }
        const round = TheoryEngine.round(theoryRoundId);
        const source = TheoryEngine.questionSource(theoryQuizId, theoryOptions, { seed: seed ?? (Date.now() % 2147483647), naming: theoryNaming(), weights });
        if (!source.size) { showWarningToast('Nothing to work on yet - questions you get wrong collect here.'); return; } // an empty weak spots round
        // ML-354: block is which repeat this is (1..repeats); right/wrong and the clock are this block's.
        theoryRound = {
            quizId: theoryQuizId, options: theoryOptions, roundId: round.value, seconds: round.seconds || null, questions: round.questions || null,
            repeats: theoryRepeats, block: 1, blockMs: [], blockAnswered: 0,
            naming: theoryNaming(), source,
            startedAt: new Date().toISOString(), accumulatedMs: 0, runningSince: theoryNow(),
            right: 0, wrong: 0, answers: [], question: null, shownAt: 0, locked: false, ended: false
        };
        document.getElementById('theoryCountdown').classList.toggle('hidden-group', !theoryRound.seconds);
        setShown('theoryBreak', false);
        setShown('theoryPlayBody', true);
        // Replace the options screen's place in history? No - Back from Play (after the confirm) should
        // land on the options, so Play simply goes on top.
        switchView('theoryPlayView');
        theoryNextQuestion();
        clearInterval(theoryTicker);
        theoryTicker = setInterval(theoryTick, 100);
        theoryTick();
    }
    function theoryStopRound() {
        clearInterval(theoryTicker);
        theoryTicker = null;
        if (theoryRound) theoryRound.ended = true;
        theoryRound = null;
    }
    function theoryTick() {
        const r = theoryRound;
        if (!r || r.ended || r.resting) return;
        const elapsed = theoryElapsedMs(r);
        const clock = document.getElementById('theoryClock');
        if (r.seconds) {
            const left = Math.max(0, r.seconds * 1000 - elapsed);
            const secs = Math.ceil(left / 1000);
            clock.textContent = `${Math.floor(secs / 60)}:${String(secs % 60).padStart(2, '0')}`;
            const fill = document.getElementById('theoryCountdownFill');
            // ML-603: with reduced motion the bar steps down once a second, with the clock, instead of gliding
            fill.style.setProperty('--remaining', prefersReducedMotion() ? secs / r.seconds : left / (r.seconds * 1000));
            document.getElementById('theoryCountdown').setAttribute('aria-valuenow', String(Math.round(100 * left / (r.seconds * 1000))));
            if (left <= 0) theoryBlockDone();
        } else {
            const s = Math.floor(elapsed / 1000);
            clock.textContent = `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
        }
    }
    function theoryUpdateTally() {
        const r = theoryRound;
        const tally = r.questions
            ? `${Math.min(r.blockAnswered + 1, r.questions)} of ${r.questions}`
            : `${r.right} right${r.wrong ? ` · ${r.wrong} wrong` : ''}`;
        document.getElementById('theoryTally').textContent = r.repeats > 1 ? `Round ${r.block} of ${r.repeats} · ${tally}` : tally;
    }
    // ML-354: a block (one repeat) is over - keep its time, then the next ("Round 2 of 3"), or the results
    // after the last one.
    // ML-439: the next one doesn't start by itself. The clock stops on a screen that says how many rounds are
    // done, shows that round's Level and the rounds of this test so far, and waits for "Next round" - so you
    // are in control of when the clock starts again. (It used to run straight on.)
    function theoryBlockDone() {
        const r = theoryRound;
        if (!r || r.ended || r.resting) return;
        r.blockMs.push(r.seconds ? r.seconds * 1000 : Math.round(theoryElapsedMs(r)));
        if (r.block >= r.repeats) { theoryEndRound(); return; }
        r.resting = true;
        r.accumulatedMs = 0;
        r.runningSince = null;
        renderTheoryBreak();
    }
    function renderTheoryBreak() {
        const r = theoryRound;
        if (!r || !r.resting) return;
        // Each finished round's Level, worked out as the results screen will (scoreBlocks -> gradeFor)
        const levels = TheoryEngine.scoreBlocks(r.roundId, r.answers, r.repeats, r.blockMs).blockScores.slice(0, r.block).map(s => TheoryEngine.gradeFor(s));
        const level = levels[levels.length - 1];
        const left = r.repeats - r.block;
        document.getElementById('theoryBreakTitle').textContent = `Round ${r.block} of ${r.repeats} done`;
        const steps = document.getElementById('theoryBreakLevel');
        steps.innerHTML = theoryStepsHtml(level);
        steps.setAttribute('aria-label', `Level ${level} of 5`);
        document.getElementById('theoryBreakLine').textContent = `Level ${level} that round. Keep it up - ${left === 1 ? 'one more round' : `${left} more rounds`} to go.`;
        document.getElementById('theoryBreakTrend').innerHTML = theoryLevelBarsHtml(levels.map((grade, i) => ({ grade, label: `Round ${i + 1}` })), true);
        document.getElementById('theoryBreakNextBtn').textContent = left === 1 ? 'Last round' : 'Next round';
        setShown('theoryPlayBody', false);
        setShown('theoryBreak', true);
        document.getElementById('theoryBreakTitle').focus({ preventScroll: true });
    }
    function theoryBreakNext() {
        const r = theoryRound;
        if (!r || r.ended || !r.resting) return;
        r.resting = false;
        r.block++;
        r.blockAnswered = 0;
        r.right = 0;
        r.wrong = 0;
        r.accumulatedMs = 0;
        r.runningSince = document.hidden || (practiceRun && practiceRun.pausedAt) ? null : theoryNow();
        setShown('theoryBreak', false);
        setShown('theoryPlayBody', true);
        theoryNextQuestion();
        theoryTick();
    }
    document.getElementById('theoryBreakNextBtn')?.addEventListener('click', theoryBreakNext);
    function theoryNextQuestion() {
        const r = theoryRound;
        if (!r || r.ended) return;
        const q = r.source.next();
        r.question = q;
        r.locked = false;
        document.getElementById('theoryQuestionText').textContent = q.prompt.text;
        const prompt = document.getElementById('theoryPrompt');
        if (q.prompt.staff) prompt.innerHTML = theoryScaleSvg(Notation.staff({ ...q.prompt.staff, label: q.prompt.label }), THEORY_PROMPT_SCALE);
        else if (q.prompt.render) prompt.innerHTML = theoryVisual(q.prompt.render, q.prompt.label, THEORY_PROMPT_SCALE * 1.4);
        else prompt.innerHTML = `<p class="theory-meaning">${escapeHtml(q.prompt.meaning)}</p>`;
        document.getElementById('theoryFeedback').textContent = '';
        const answers = document.getElementById('theoryAnswers');
        answers.className = `theory-answers theory-answers-${q.layout}`;
        answers.innerHTML = q.answers.map(a => q.layout === 'symbols'
            ? `<button type="button" class="theory-answer" data-id="${escapeHtml(a.id)}" aria-label="${escapeHtml(a.label)}">${theoryVisual(a.render, null, THEORY_SYMBOL_SCALE)}</button>`
            : `<button type="button" class="theory-answer" data-id="${escapeHtml(a.id)}"${(q.unused || []).includes(a.id) ? ' disabled' : ''}>${escapeHtml(a.label)}</button>`).join(''); // (ML-438: a key's note that isn't in this round is greyed out)
        answers.querySelectorAll('.theory-answer').forEach(b => b.addEventListener('click', () => theoryAnswer(b.dataset.id)));
        // ML-438: a scale with major and minor keys in play takes a second tap - Major or Minor, under the keyboard
        r.pick = null;
        theoryTypedAccidental = ''; // (a # or - typed for the last question doesn't carry over)
        const modes = document.getElementById('theoryModes');
        const modeRow = q.modes || q.shownModes || [];
        setShown(modes, modeRow.length > 0);
        // ML-516: a key signature's question says the mode, so there it is given - lit, and the other one can't
        // be tapped. The row is there on every question of a major-and-minor quiz; only the note is tapped.
        modes.innerHTML = modeRow.map(m => `<button type="button" class="theory-answer" data-id="${escapeHtml(m.id)}" aria-pressed="${q.modeGiven === m.id}"${q.modeGiven && q.modeGiven !== m.id ? ' disabled' : ''}>${escapeHtml(m.label)}</button>`).join('');
        if (q.modes) modes.querySelectorAll('.theory-answer').forEach(b => b.addEventListener('click', () => theoryAnswer(b.dataset.id, 'mode')));
        if (q.modes) answers.querySelectorAll('.theory-answer').forEach(b => b.setAttribute('aria-pressed', 'false'));
        theoryUpdateTally();
        r.shownAt = theoryNow();
    }
    function theoryMarkAnswer(id, state, box = 'theoryAnswers') {
        const b = document.querySelector(`#${box} .theory-answer[data-id="${CSS.escape(id)}"]`);
        if (!b) return;
        b.removeAttribute('aria-pressed'); // (a picked half of a two-tap answer is now right or wrong, not "picked")
        b.classList.add(state === 'right' ? 'theory-answer-right' : 'theory-answer-wrong');
        b.insertAdjacentHTML('afterbegin', `<span class="material-symbols-outlined" aria-hidden="true">${state === 'right' ? 'check' : 'close'}</span>`);
    }
    function theoryAnswer(id, part = 'note') {
        const r = theoryRound;
        if (!r || r.ended || r.locked || r.resting) return;
        // A tap in the first moment after a question appears is the tail end of the last one (a
        // double tap), not an answer to this one.
        if (theoryNow() - r.shownAt < TheoryEngine.TIMING.minAnswerMs) return;
        const q = r.question;
        // ML-438: a two-tap answer (the note and Major / Minor, in either order) waits for its other half -
        // what's picked so far is shown, and can be changed until the second half is tapped
        const twoTap = !!q.modes; // (ML-516: a key signature's given mode is `shownModes` - shown, not answered)
        if (twoTap) {
            r.pick = { ...(r.pick || {}), [part]: id };
            document.querySelectorAll(`#${part === 'mode' ? 'theoryModes' : 'theoryAnswers'} .theory-answer`).forEach(b => b.setAttribute('aria-pressed', String(b.dataset.id === id)));
            if (!r.pick.note || !r.pick.mode) return;
            id = `${r.pick.note} ${r.pick.mode}`;
        }
        const correct = id === q.correct;
        r.answers.push({ questionId: q.id, answerId: id, correct, ms: Math.round(theoryNow() - r.shownAt), block: r.block, ...(twoTap ? { taps: 2 } : {}) });
        r.blockAnswered++;
        // Smart learn: a later deal in this same round already knows, and a miss comes back 3 questions on.
        r.source.record(q.id, correct, r.answers[r.answers.length - 1].ms);
        r.locked = true;
        if (twoTap) {
            // each half is marked on its own: the note on the keyboard, Major / Minor underneath
            const cut = q.correct.lastIndexOf(' ');
            [['note', q.correct.slice(0, cut), 'theoryAnswers'], ['mode', q.correct.slice(cut + 1), 'theoryModes']].forEach(([half, right, box]) => {
                if (r.pick[half] !== right) theoryMarkAnswer(r.pick[half], 'wrong', box);
                theoryMarkAnswer(right, 'right', box);
            });
            if (correct) r.right++; else r.wrong++;
            if (!correct) document.getElementById('theoryFeedback').textContent = `Not quite: it's ${q.correctLabel}`;
        } else if (correct) {
            r.right++;
            theoryMarkAnswer(id, 'right');
        } else {
            r.wrong++;
            theoryMarkAnswer(id, 'wrong');
            theoryMarkAnswer(q.correct, 'right');
            const label = q.correctLabel || q.answers.find(a => a.id === q.correct).label;
            // A question can say why instead (the chromatic scale's Yes/No, ML-309 C).
            document.getElementById('theoryFeedback').textContent = q.feedback || `Not quite: it's ${label}`;
        }
        theoryUpdateTally();
        const finished = r.questions && r.blockAnswered >= r.questions;
        const block = r.block;
        // A right answer moves on almost at once (speed counts); a wrong one leaves the right answer
        // up long enough to learn it - which also costs time, so guessing doesn't pay. (A timed block
        // can run out meanwhile and move on by itself - then this one has nothing left to do.)
        // ML-439: with under half a second left there is no new question - the round ends there instead.
        setTimeout(() => {
            if (theoryRound !== r || r.ended || r.resting || r.block !== block) return;
            if (finished || (r.seconds && r.seconds * 1000 - theoryElapsedMs(r) < TheoryEngine.TIMING.lastQuestionMs)) theoryBlockDone();
            else theoryNextQuestion();
        }, correct ? 150 : TheoryEngine.TIMING.wrongRevealMs);
    }
    // Answering from a computer's keyboard (owner, 5 Oct 2026 - typing C did nothing):
    //   A to G         that note (Note names, and the Keys keyboard)
    //   # or + first   the sharp:  # then F  is F sharp
    //   - first        the flat:   - then B  is B flat
    //   1 to 9         the 1st to 9th answer, on a question whose answers aren't notes
    //   M / m          Major / minor (capital for major), on a scale's second tap
    //   Enter          Next round, on the screen between rounds
    // A key press is a tap on that answer's button, so everything a tap does (and refuses) is the same.
    let theoryTypedAccidental = '';
    document.addEventListener('keydown', (e) => {
        const r = theoryRound;
        if (!r || r.ended || !isShown('theoryPlayView') || e.ctrlKey || e.metaKey || e.altKey || document.querySelector('.modal.show')) return;
        if (['INPUT', 'TEXTAREA', 'SELECT'].includes(e.target.tagName)) return;
        if (r.resting) { if (e.key === 'Enter') { e.preventDefault(); theoryBreakNext(); } return; }
        const q = r.question;
        if (!q) return;
        const tap = (box, id) => { const b = document.querySelector(`#${box} .theory-answer[data-id="${CSS.escape(id)}"]`); if (b && !b.disabled) { e.preventDefault(); b.click(); } };
        const noteLayout = q.layout === 'notes' || q.layout === 'keyboard';
        if (noteLayout && (e.key === '#' || e.key === '+')) { theoryTypedAccidental = '#'; e.preventDefault(); return; }
        if (noteLayout && e.key === '-') { theoryTypedAccidental = 'b'; e.preventDefault(); return; }
        if (q.modes && (e.key === 'M' || e.key === 'm')) { tap('theoryModes', e.key === 'M' ? 'major' : 'minor'); return; }
        if (noteLayout && /^[a-gA-G]$/.test(e.key)) {
            const id = e.key.toUpperCase() + theoryTypedAccidental;
            theoryTypedAccidental = '';
            tap('theoryAnswers', id);
            return;
        }
        if (!noteLayout && /^[1-9]$/.test(e.key)) {
            const a = q.answers[Number(e.key) - 1];
            if (a) tap('theoryAnswers', a.id);
        }
    });

    // The clock stops while the app is in the background (a phone call, switching apps).
    document.addEventListener('visibilitychange', () => {
        const r = theoryRound;
        if (!r || r.ended) return;
        if (document.hidden && r.runningSince !== null) { r.accumulatedMs += theoryNow() - r.runningSince; r.runningSince = null; }
        else if (!document.hidden && r.runningSince === null && !r.resting && !(practiceRun && practiceRun.pausedAt)) { r.runningSince = theoryNow(); theoryTick(); }
    });

    async function theoryEndRound() {
        const r = theoryRound;
        if (!r || r.ended) return;
        clearInterval(theoryTicker);
        theoryTicker = null;
        r.ended = true;
        // ML-354: the best block is the result (theoryBlockDone has kept every block's time).
        const local = TheoryEngine.scoreBlocks(r.roundId, r.answers, r.repeats, r.blockMs);
        theoryLastResult = { round: r, durationMs: local.ms, score: local.score, grade: local.grade, right: local.right, wrong: local.wrong,
            bestBlock: local.bestBlock, blockScores: local.blockScores, saved: null, saving: true };
        theoryRound = null;
        // Results replaces Play in the back history: Back from Results goes to the options.
        if (viewStack[viewStack.length - 1] === 'theoryPlayView') viewStack.pop();
        switchView('theoryResultsView');
        renderTheoryResults();
        try {
            const out = await API.theory.save({
                quizId: r.quizId, roundType: r.roundId, repeats: r.repeats, options: r.options, naming: r.naming,
                blockMs: r.blockMs, startedAt: r.startedAt, answers: r.answers
            });
            // ML-220: offline, the round waits on this device - the result shows, the Level comes after the sync
            if (out.queued) showSuccessToast(out.message); else theoryLastResult.saved = out;
        } catch (e) {
            showWarningToast("Couldn't save this round. Your result is below, but it won't be in your history.");
        }
        if (theoryBlock && theoryLastResult.saved) theoryBlockRoundDone(theoryLastResult.saved.attempt.grade); // ML-418
        theoryPlayedStale = true; // the options screen's list has a new last round
        theoryLastResult.saving = false;
        renderTheoryResults();
    }
    function renderTheoryResults() {
        const res = theoryLastResult;
        if (!res) return;
        renderTheoryBlockResults(); // ML-418: Next quiz, in a session's Theory block
        const r = res.round;
        const saved = res.saved;
        // ML-396: the result is a Level (the stored grade). The score isn't shown - the Level is worked
        // out from it, so both would say the same thing twice; it still decides which round is the best.
        const level = saved ? saved.attempt.grade : res.grade;
        // ML-354: right and time are the best round's - the one the Level comes from.
        const right = saved ? saved.attempt.right : res.right;
        const wrong = saved ? saved.attempt.wrong : res.wrong;
        document.getElementById('theoryResultsOptions').textContent = `${TheoryEngine.quiz(r.quizId).title} · ${TheoryEngine.describeOptions(r.quizId, r.options, r.roundId)}${r.repeats > 1 ? ` × ${r.repeats}` : ''}`;
        const rounds = document.getElementById('theoryResultRounds');
        setShown(rounds, r.repeats > 1);
        rounds.textContent = `Your rounds: ${res.blockScores.map(s => `Level ${TheoryEngine.gradeFor(s)}`).join(', ')}. Round ${res.bestBlock} was the best, so it counts.`;
        const levelEl = document.getElementById('theoryResultLevel');
        levelEl.innerHTML = theoryStepsHtml(level);
        levelEl.setAttribute('aria-label', `Level ${level} of 5`);
        // One box, kept positive: how many were right out of how many were answered.
        document.getElementById('theoryResultRight').textContent = `${right} out of ${right + wrong}`;
        const secs = Math.round(res.durationMs / 1000);
        document.getElementById('theoryResultTime').textContent = r.seconds ? `${r.seconds} s` : `${Math.floor(secs / 60)}:${String(secs % 60).padStart(2, '0')}`;
        const best = document.getElementById('theoryResultBest');
        if (res.saving) best.textContent = `Level ${level}`;
        else if (!saved) best.textContent = `Level ${level} (not saved)`;
        else if (saved.isFirst) best.textContent = `Level ${level} · your first round with these options`;
        else if (saved.isNewBest) best.textContent = `Level ${level} · your best yet with these options`;
        else best.textContent = saved.best.grade > level ? `Level ${level} · your best is Level ${saved.best.grade}` : `Level ${level}`;
        // "2 more right answers for Level 5" - what to do next, from the best round's own answers.
        const gap = TheoryEngine.nextLevelGap(r.roundId, r.answers.filter(a => a.block === res.bestBlock));
        const next = document.getElementById('theoryResultNext');
        setShown(next, !!gap);
        if (gap) next.textContent = `${gap.more} more right ${gap.more === 1 ? 'answer' : 'answers'} for Level ${gap.level}`;
        const smart = document.getElementById('theoryResultSmart');
        const learning = saved && saved.smartLearn ? saved.smartLearn.learning : null;
        setShown('theoryResultSmartBox', learning !== null && learning !== undefined);
        // ML-399: what it brings back is what you missed, and what you got right but took longer over.
        smart.textContent = smartLearnMessage(saved && saved.smartLearn, 'question', 'you took a little longer over');
        renderTheoryTrend(saved ? saved.recent : []);
    }
    // The last rounds with these options, oldest first, this one ringed.
    function renderTheoryTrend(recent) {
        const el = document.getElementById('theoryTrend');
        el.innerHTML = recent.length ? theoryLevelBarsHtml(recent, true) : '<p class="text-muted">Your rounds with these options will show here.</p>';
    }
    document.getElementById('theoryAgainBtn')?.addEventListener('click', () => {
        // Results is replaced by the new round, so Back still goes to the options.
        if (viewStack[viewStack.length - 1] === 'theoryResultsView') viewStack.pop();
        theoryStartRound();
    });
    document.getElementById('theoryChangeBtn')?.addEventListener('click', () => goBack());
    // ML-396: two more ways out of the results - the Theory list, and Home.
    document.getElementById('theoryOtherBtn')?.addEventListener('click', () => backToView('theoryView'));
    document.getElementById('theoryHomeBtn')?.addEventListener('click', () => backToView('mainView'));


    // ===== ML-418: a practice session's Theory block =====
    // Nothing to play: the block works through Theory quizzes, each done twice (two 30-second rounds, the
    // better one counts), then the next - about three quizzes in the five minutes. Which ones is
    // PracticePlan.theoryQueue: with SmartLearn, your lowest Levels in the lowest grade that isn't sorted
    // (every quiz at Level 5); without it, quiz by quiz from the start, carrying on where you stopped.
    // Your own Theory options and Repeat are left alone and come back when the block ends.
    const THEORY_BLOCK_CURSOR = 'tml.theory.block.cursor';
    var theoryBlock = null; // var: switchView and the session read it - { queue, i, levels, smart, saved }
    // Every quiz at every Theory grade it has (the quiz's own options when Theory grades are off)
    function theoryBlockItems() {
        const quizzes = TheoryEngine.QUIZZES.filter(q => !q.gradeOnly || theoryGradesOn());
        const grades = theoryGradesOn() ? [1, 2, 3, 4, 5] : [0];
        const items = [];
        grades.forEach(g => quizzes.forEach(q => {
            if (g && q.grades && !q.grades.includes(g)) return;
            let ok = true;
            try { ok = (TheoryEngine.normaliseOptions(q.id, { grade: g }).grade || 0) === g; } catch (e) { ok = false; }
            if (ok) items.push({ key: `${q.id}|${g}`, quizId: q.id, grade: g });
        }));
        return items;
    }
    const theoryBlockLabel = (it) => `${TheoryEngine.quiz(it.quizId).title}${it.grade ? ` · Grade ${it.grade}` : ''}`;
    async function startTheoryBlock() {
        let levels = {};
        try { levels = (await API.theory.levels()).levels || {}; } catch (e) { /* starts from the top */ }
        const smart = isFeatureEnabled('theory_smart_learn');
        let cursor = null;
        try { cursor = localStorage.getItem(THEORY_BLOCK_CURSOR); } catch (e) { /* from the start */ }
        const queue = PracticePlan.theoryQueue(theoryBlockItems(), levels, smart, cursor);
        if (!queue.length) { switchView('theoryView'); return; }
        theoryBlock = { queue, i: 0, levels, smart, saved: { quizId: theoryQuizId, options: theoryOptions, roundId: theoryRoundId, repeats: theoryRepeats } };
        await theoryBlockPlay();
    }
    async function theoryBlockPlay() {
        const B = theoryBlock;
        if (!B) return;
        const it = B.queue[B.i % B.queue.length];
        theoryStopRound();
        theoryQuizId = it.quizId;
        theoryOptions = TheoryEngine.normaliseOptions(it.quizId, { grade: it.grade });
        theoryRoundId = TheoryEngine.round(TheoryEngine.DEFAULT_ROUND).value;
        theoryRepeats = PracticePlan.THEORY_REPEATS;
        if (viewStack[viewStack.length - 1] === 'theoryResultsView') viewStack.pop(); // the next quiz takes its place
        theoryBlock = null; // (switchView would end the block while it changes screens)
        if (viewStack[viewStack.length - 1] !== 'theoryOptionsView') switchView('theoryOptionsView');
        theoryBlock = B;
        await theoryStartRound();
    }
    // A quiz's rounds are done: remember its Level and where the walk has got to
    function theoryBlockRoundDone(level) {
        const B = theoryBlock;
        if (!B) return;
        const it = B.queue[B.i % B.queue.length];
        B.levels[it.key] = level;
        try { localStorage.setItem(THEORY_BLOCK_CURSOR, it.key); } catch (e) { /* per device */ }
    }
    function theoryBlockNext() {
        const B = theoryBlock;
        if (!B) return;
        B.i++;
        // SmartLearn: after a lap of the queue, look again - a grade may be sorted now
        if (B.smart && B.i % B.queue.length === 0) { B.queue = PracticePlan.theoryQueue(theoryBlockItems(), B.levels, true, null); B.i = 0; }
        theoryBlockPlay();
    }
    // The block is over (its time ran out, or you left Theory): your own options and Repeat come back
    function theoryBlockEnd() {
        const B = theoryBlock;
        if (!B) return;
        theoryBlock = null;
        theoryStopRound(); // a round part-way through isn't saved - only finished rounds are
        theoryQuizId = B.saved.quizId;
        theoryOptions = B.saved.options;
        theoryRoundId = B.saved.roundId;
        theoryRepeats = B.saved.repeats;
    }
    // The results screen in a block: Next quiz, in place of Again and the ways out
    function renderTheoryBlockResults() {
        const B = theoryBlock;
        setShown('theoryBlockNextBtn', !!B);
        setShown('theoryAgainBtn', !B);
        setShown('theoryExits', !B);
        if (!B) return;
        const next = B.queue[(B.i + 1) % B.queue.length];
        document.getElementById('theoryBlockNextBtn').textContent = `Next: ${theoryBlockLabel(next)}`;
    }
    document.getElementById('theoryBlockNextBtn')?.addEventListener('click', theoryBlockNext);

    // ========================================
    // QUICK PIECE ENTRY (Jira ML-424, ML-428) - a new piece entered as an outline, by the bar numbers on the
    // music. Five stages across the top, with steps inside each (ML-428, owner 4 Oct 2026):
    //   About          - name (required), composer, arranger, publisher, notes
    //   Structure      - how long (bars, count-in, the main time and speed), then the rehearsal marks
    //   Tempo          - the bars that aren't the main time signature, then the bars where the speed changes
    //                    ("Time and speed" until 0.41 - shortened so the label fits on one line on a phone)
    //   Extras         - one yes/no question at a time: an intro? repeats? pauses? speeding up? signs and jumps?
    //   Media          - a recording? a YouTube link? a score or part? - then Save
    // Save turns the outline into the same blocks "Create your own" makes - the rules are
    // public/pieceOutline.js (docs/quick-piece-entry.md) - saves the details and the media with it, and
    // goes back to where Add a piece was opened from. It never opens the edit screen, so the whole piece
    // is one ML-199 authoring session (creation source 'quick'), timed step by step. New pieces only; a
    // piece is changed afterwards in the bar-by-bar editor.
    // ========================================
    const OUTLINE_STAGES = [{ name: 'About' }, { name: 'Structure' }, { name: 'Tempo' }, { name: 'Order of play' }, { name: 'Media' }]; // "Order of play" was "Extras" (owner, 5 Oct 2026)
    // `name` is the step's own name (its dot); `label` is what the step before calls it on its Next button. An Extras step has `kinds` (the extras
    // it asks about); a Media step has `media` (which list in outline.media).
    const OUTLINE_STEPS = [
        { key: 'about', name: 'About', stage: 0, label: 'about the piece', question: () => 'What is the piece?' },
        { key: 'howLong', name: 'How long', stage: 1, label: 'how long', question: () => 'How long is the piece?' },
        { key: 'marks', name: 'Rehearsal marks', stage: 1, label: 'rehearsal marks', question: () => 'Where are the rehearsal marks?' },
        // Time and speed are a step each (11 steps; one combined page was tried on 5 Oct 2026 and was too long). Each
        // carries its own "most of it" answer as tiles above its table of switches - so each heading covers its
        // whole page. A switch is sudden, at a bar; the gradual changes (a rall. or accel.) are the step after.
        { key: 'time', name: 'Time signature', stage: 2, label: 'time signature', question: () => 'What time signature is it in?' },
        { key: 'speed', name: 'Speed', stage: 2, label: 'speed', question: () => 'What speed is it?' },
        { key: 'xRamps', name: 'Gradual speed changes', stage: 2, label: 'gradual speed changes', kinds: ['ramp'], add: 'Add a rall. or accel.', addMore: 'Add another rall. or accel.', question: () => 'Where does the speed change gradually?' },
        // Pauses are a speed thing too, so they follow the gradual changes; what is left in Extras - the introduction,
        // repeats, then signs and jumps - is the order the piece is played in (owner, 5 Oct 2026)
        { key: 'xPauses', name: 'Pauses and breaks', stage: 2, label: 'pauses', kinds: ['pause'], table: 'pause', question: () => 'Are there any pauses or breaks?' },
        { key: 'xIntro', name: 'Intro', stage: 3, label: 'introduction', kinds: ['intro'], one: true, add: 'Add the intro', question: () => 'Introduction' },
        { key: 'xRepeats', name: 'Repeats', stage: 3, label: 'repeats', kinds: ['repeat', 'repeatEndings'], table: 'repeat', question: () => 'Are there any repeats?' },
        { key: 'xSigns', name: 'Signs and jumps', stage: 3, label: 'signs and jumps', kinds: ['sign'], add: 'Add a sign or jump', addMore: 'Add another sign or jump', question: () => 'Are there any signs or jumps?' },
        { key: 'media', name: 'Media', stage: 4, label: 'media', media: true, question: () => 'Anything to add to it?' }
    ];
    const OUTLINE_MARK_KINDS = [
        { key: 'numbers', label: 'Bar numbers', sub: 'Each mark is the number of its bar - 7, 21, 30...' },
        { key: 'text', label: 'Letters, words or numbers', sub: "A, B, C... · Verse, Chorus · or 1, 2, 3 that aren't the bar numbers" },
        { key: 'none', label: 'None', sub: 'This piece has no rehearsal marks' }
    ];
    const OUTLINE_EXTRAS = {
        repeat: { label: 'Repeat', sub: 'Some bars are played more than once', icon: 'repeat' },
        repeatEndings: { label: 'Repeat with 1st and 2nd endings', sub: 'A different ending each time round', icon: 'repeat_one' },
        pause: { label: 'Pause', sub: 'A held note or a break (fermata, caesura)', icon: 'pause_circle' },
        ramp: { label: 'Rall. or accel.', sub: 'Getting gradually slower or faster over some bars', icon: 'trending_up' },
        sign: { label: 'Sign and jump', sub: 'D.S., D.C., Coda, Fine', icon: 'redo' },
        intro: { label: 'Intro', sub: 'Bars played once before the piece proper', icon: 'first_page' }
    };
    var outline = null; // var: switchView and goBack read it

    function outlineSigInfo(key) {
        if (!key) return null;
        const [type, id] = String(key).split(':');
        return (type === 'public' ? metroBlkTimeSigCache.public : metroBlkTimeSigCache.custom).find(t => t.id === Number(id)) || null;
    }
    const outlineSigLabel = (key) => { const s = outlineSigInfo(key); return s ? s.label : '?'; };
    // ML-445: the beat note is always a real note - one not picked yet is a crotchet, which is what the bar
    // editor shows for it too - and it is shown as its picture (the pop-up's), with its name for a screen reader
    const outlineNoteKey = (key) => (METRO_NOTE_TYPES.some(n => n.key === key) ? key : 'crotchet');
    const outlineNoteLabel = (key) => METRO_NOTE_TYPES.find(n => n.key === outlineNoteKey(key)).label;
    const outlineNoteIcon = (key) => `<span role="img" aria-label="${escapeHtml(outlineNoteLabel(key))}">${metroNoteIconSvg(outlineNoteKey(key))}</span>`;
    const outlineStepKey = () => OUTLINE_STEPS[outline.step].key;

    // Leaving Quick entry (the < at the top, the menu) keeps what was typed. Coming back to it asks which you
    // want - carry on with that piece, or start a new one (which throws it away). That question is the only way a
    // piece is thrown away: there is no Cancel or "Start again" on the steps (owner, 5 Oct 2026 - one more thing on
    // every page, next to a < that already leaves). `answered`: the question has just been answered.
    async function openPieceOutline(target, answered) {
        if (!metroBlkTimeSigCache.public.length) { try { await loadMetroBlkTimeSignatures(); } catch (e) { /* the pickers say so */ } }
        if (outline && outline.step === 0 && !Object.values(outline.about).some(v => String(v).trim())) outlineClose(); // nothing typed: nothing to ask about
        if (outline && !answered) {
            const name = outline.about.title.trim() || 'the piece you started';
            openFlowChoiceModal('You started a piece earlier', [
                { key: 'carry', html: addPieceRow(`Carry on with "${name}"`, 'Everything you typed is still there') },
                { key: 'new', html: addPieceRow('Start a new piece', `"${name}" is thrown away`) }
            ], (opt) => {
                if (opt.key === 'new') outlineClose();
                openPieceOutline(target, true);
            });
            return;
        }
        if (!outline) {
            const common = metroBlkTimeSigCache.public.find(t => t.numerator === 4 && t.denominator === 4) || metroBlkTimeSigCache.public[0];
            outline = {
                step: 0, target,
                about: { title: '', composer: '', arranger: '', publisher: '', notes: '' },
                media: { audio: [], video: [], docs: [] }, // files and links held until Save
                o: { bars: null, leadIn: false, mainSig: common ? `public:${common.id}` : null, mainBpm: 120, mainNote: null, markKind: 'numbers', marks: [], time: {}, speeds: [], extras: [] },
                marksText: '', markRows: [{ bar: '', label: '' }], speedRows: [{ bar: '', bpm: '', noteValue: undefined }],
                timeRows: [{ bar: '', sig: '', key: '', bars: '', end: '' }],
                repeatRows: [{ from: '', to: '', times: '', e1From: '', e2To: '' }], pauseRows: [{ bar: '', beat: '', holdBeats: '', kind: '' }],
                stats: { startedAtMs: Date.now(), lastInputAtMs: Date.now(), active: 0, taps: 0, keys: 0, tick: null, steps: OUTLINE_STEPS.map(s => ({ step: s.key, seconds: 0, taps: 0, keys: 0, visits: 0 })) }
            };
            outline.stats.steps[0].visits = 1;
        } else {
            outline.target = target;
        }
        if (viewStack[viewStack.length - 1] === 'addPieceView') viewStack.pop();
        switchView('pieceOutlineView');
    }
    function outlineClose() {
        if (outline && outline.stats.tick) clearInterval(outline.stats.tick);
        outline = null;
    }
    // The stopwatch: active seconds (idle and a hidden page don't count), taps and keys, for the step you're on.
    function outlineStatsTick() {
        const s = outline && outline.stats;
        if (!s || viewStack[viewStack.length - 1] !== 'pieceOutlineView' || document.visibilityState !== 'visible') return;
        if (Date.now() - s.lastInputAtMs > FLOW_STATS_IDLE_THRESHOLD_SECONDS * 1000) return;
        s.active += 1;
        s.steps[outline.step].seconds += 1;
    }
    ['pointerdown', 'keydown'].forEach(evt => document.addEventListener(evt, () => {
        if (!outline || viewStack[viewStack.length - 1] !== 'pieceOutlineView') return;
        const s = outline.stats;
        s.lastInputAtMs = Date.now();
        const k = evt === 'pointerdown' ? 'taps' : 'keys';
        s[k] += 1;
        s.steps[outline.step][k] += 1;
    }, { capture: true, passive: true }));

    function outlineGoStep(n) {
        outline.step = Math.max(0, Math.min(OUTLINE_STEPS.length - 1, n));
        outline.stats.steps[outline.step].visits += 1;
        renderOutline();
        window.scrollTo({ top: 0 });
        // ML-444: the number of bars is typed every time, so the cursor is already in its box
        if (outlineStepKey() === 'howLong') document.getElementById('outlineBars')?.focus({ preventScroll: true });
    }
    // The outline as blocks, each with its time signature's beats (the journey engine's check needs them),
    // plus what won't work: the extras that clash, and anything the bar-by-bar editor's own check refuses.
    function outlineBuild() {
        outlineTimeApply(); // the time rows as bars, whatever step is showing
        outlineMovesApply(); // ML-529: the movements
        outlineIntroApply(); // the intro's switch and bars as an extra
        outlineRowsApply(); // and the repeat and pause rows as extras
        const built = PieceOutline.buildBlocks(outline.o);
        const blocks = built.blocks.map(b => { const s = outlineSigInfo(b.sig); return { ...b, numerator: s ? s.numerator : 4, denominator: s ? s.denominator : 4, timeSignatureLabel: s ? s.label : '' }; });
        const errors = FlowJourney.checkFlow(blocks).filter(i => i.severity === 'error').map(i => i.message);
        return { blocks, clashes: built.clashes, errors };
    }

    function renderOutline() {
        if (!outline) return;
        const st = outline.stats;
        if (!st.tick) st.tick = setInterval(outlineStatsTick, 1000);
        const cur = OUTLINE_STEPS[outline.step];
        // ML-449: where you are is one bar - a piece a step, a wider gap between stages - and one line under it
        // ("Tempo · step 4 of 11"). Getting about is Back and Next, together at the bottom of the screen on every
        // step. (It was five labelled stage bars, then "Tempo: 1 of 2" and a row of dots.)
        const total = OUTLINE_STEPS.length;
        const bar = document.getElementById('outlineBar');
        bar.setAttribute('aria-label', `Step ${outline.step + 1} of ${total}: ${OUTLINE_STAGES[cur.stage].name}`);
        bar.innerHTML = OUTLINE_STEPS.map((s, i) => `<span class="step-bar-piece${i < outline.step ? ' is-done' : i === outline.step ? ' is-now' : ''}${i < total - 1 && OUTLINE_STEPS[i + 1].stage !== s.stage ? ' ends-stage' : ''}"></span>`).join('');
        document.getElementById('outlineWhereText').innerHTML = `<strong>${escapeHtml(OUTLINE_STAGES[cur.stage].name)}</strong> · step ${outline.step + 1} of ${total}`;
        document.getElementById('outlineQuestion').textContent = cur.question();
        const html = cur.kinds ? outlineExtrasStepHtml(cur) : cur.media ? outlineMediaStepHtml(cur)
            : { about: outlineAboutHtml, howLong: outlineHowLongHtml, marks: outlineMarksHtml, time: outlineTimeStepHtml, speed: outlineSpeedStepHtml }[cur.key]();
        document.getElementById('outlineBody').innerHTML = outlineReadPanelHtml() + html; // ML-246: what to check, when the piece was read from a photo
        // Back (not on the first step) and Next - Save on the last step, which is off while something won't work
        const last = outline.step === total - 1;
        let blocked = false;
        if (last) { const built = outlineBuild(); blocked = !!(built.clashes.length || built.errors.length); }
        document.getElementById('outlineFoot').innerHTML = `${outline.step > 0 ? '<button type="button" class="btn-cancel btn-nav no-margin" data-outline="back">Back</button>' : ''}<button type="button" class="btn-submit no-margin" data-outline="${last ? 'save' : 'next'}"${blocked ? ' disabled' : ''}>${outlineNextLabel()}</button>`;
        if (cur.key === 'marks') outlineMarksRefresh();
        if (cur.key === 'time') outlineTimeRefresh();
        if (cur.key === 'speed') outlineSpeedRefresh();
        if (cur.table && document.getElementById('outlineRowsCheck')) outlineRowsRefresh(cur.table);
    }
    // What the Next button says: the step it goes to, or Save on the last one
    const outlineNextLabel = () => { const next = OUTLINE_STEPS[outline.step + 1]; return next ? `Next: ${next.label}` : 'Save the piece'; };
    const outlineValueBtn = (action, value, label) => `<button type="button" class="metroBlk-ctrl-value-btn w-full" data-outline="${action}" aria-haspopup="dialog" aria-label="${escapeHtml(label)}: ${escapeHtml(value)} - tap to change"><strong>${escapeHtml(value)}</strong><span class="metroBlk-ctrl-value-label">${escapeHtml(label)}</span></button>`;
    const outlineNumField = (id, value, label, attrs = '') => `<label class="outline-field"><input type="number" inputmode="numeric" id="${id}" value="${value === null || value === undefined ? '' : escapeHtml(String(value))}" enterkeyhint="next" ${attrs}><span class="outline-field-label">${escapeHtml(label)}</span></label>`;
    function outlineSummaryText() {
        const s = PieceOutline.summary(outline.o);
        const plural = (n, w) => `${n} ${w}${n === 1 ? '' : 's'}`;
        return `<strong>${plural(s.bars, 'bar')} · ${plural(s.marks, 'mark')} · ${plural(s.speeds, 'speed')}${s.extras ? ` · ${plural(s.extras, 'extra')}` : ''}.</strong> Saving will make ${plural(s.blocks, 'block')} for you.`;
    }

    // --- Step 1: how long ---
    // The three "most of it is in" answers are the bar editor's own tiles (.flow-tile: taller, so the beat note's
    // picture has room - owner, 5 Oct 2026), each opening its pop-up
    const outlineTile = (action, value, label, name) => `<button type="button" class="flow-tile" data-outline="${action}" aria-haspopup="dialog" aria-label="${escapeHtml(label)}: ${escapeHtml(name)} - tap to change"><span class="flow-tile-value">${value}</span><span class="flow-tile-label">${escapeHtml(label)}</span></button>`;
    function outlineHowLongHtml() {
        const o = outline.o;
        return `
            ${outlineNumField('outlineBars', o.bars, 'bars in the piece', 'min="1" max="2000" placeholder="e.g. 32"')}
            <div class="display-toggle-row">
                <span id="outlineLeadInLabel">A count-in bar<span class="display-toggle-help">A bar of clicks before bar 1</span></span><label class="toggle-switch"><input type="checkbox" id="outlineLeadIn" aria-labelledby="outlineLeadInLabel"${o.leadIn ? ' checked' : ''}><span class="toggle-slider"></span></label>
            </div>
            ${outlineMovesHtml()}
`;
    }
    // ML-529: a piece in movements - a switch (off to start with), and on, a table: the bar each movement starts at
    // (as printed - the numbers carry on) and its name. Shown with the piece_movements feature, or when a read
    // brought movements in.
    const outlineMoves = () => { if (!outline.moves) outline.moves = { on: false, rows: [{ bar: '1', title: '' }, { bar: '', title: '' }] }; return outline.moves; };
    const outlineMoveRowHtml = (r, i) => `<div class="outline-row outline-row-marks">
        <input type="number" inputmode="numeric" data-move-row="${i}" data-move-col="bar" value="${escapeHtml(String(r.bar))}" placeholder="bar" aria-label="Movement ${i + 1}: the bar it starts at" enterkeyhint="next">
        <input type="text" data-move-row="${i}" data-move-col="title" value="${escapeHtml(r.title)}" placeholder="e.g. Harvest" maxlength="80" aria-label="Movement ${i + 1}: its name" enterkeyhint="next" autocomplete="off"></div>`;
    function outlineMovesHtml() {
        const m = outlineMoves();
        if (!isFeatureEnabled('piece_movements') && !m.on) return '';
        return `
            <div class="display-toggle-row">
                <span id="outlineMovesLabel">It's in movements<span class="display-toggle-help">One piece in several parts, like a suite</span></span><label class="toggle-switch"><input type="checkbox" id="outlineMovesOn" aria-labelledby="outlineMovesLabel"${m.on ? ' checked' : ''}><span class="toggle-slider"></span></label>
            </div>
            ${m.on ? `
            <p class="text-sm text-muted no-margin">The bar each movement starts at, as printed on the music, and its name. The bar numbers carry on from one movement to the next; the rehearsal marks can start again at A.</p>
            <div class="outline-table" id="outlineMoveRows">
                <div class="outline-row outline-row-marks" aria-hidden="true"><span class="outline-th">Starts at bar</span><span class="outline-th">Name</span></div>
                ${m.rows.map(outlineMoveRowHtml).join('')}
            </div>
            <p class="text-sm text-muted no-margin" id="outlineMovesCheck" aria-live="polite"></p>` : ''}`;
    }
    // The rows as o.movements. Returns the bars typed that aren't bars of the piece.
    function outlineMovesApply() {
        const m = outlineMoves(), o = outline.o;
        const typed = m.on ? m.rows.filter(r => String(r.bar).trim() !== '') : [];
        const bad = typed.filter(r => !(Number.isInteger(Number(r.bar)) && Number(r.bar) >= 1 && (!o.bars || Number(r.bar) <= o.bars))).map(r => String(r.bar));
        o.movements = typed.filter(r => !bad.includes(String(r.bar))).map(r => ({ bar: Number(r.bar), title: r.title }));
        return bad;
    }
    // The time signature step and the speed step are built the same way: what most of it is in as tiles (the bar
    // editor's), then the table of where it switches.
    function outlineTimeStepHtml() {
        const o = outline.o;
        return `
            <div class="section-title" id="outlineMainLabel">Most of it is in</div>
            <div class="flow-tile-grid flow-tile-grid-3" role="group" aria-labelledby="outlineMainLabel">
                ${outlineTile('mainSig', escapeHtml(outlineSigLabel(o.mainSig)), 'time', outlineSigLabel(o.mainSig))}
            </div>
            <div class="section-title">Where it switches</div>
            ${outlineTimeHtml()}`;
    }
    function outlineSpeedStepHtml() {
        const o = outline.o;
        return `
            <div class="section-title" id="outlineMainLabel">It starts at</div>
            <div class="flow-tile-grid flow-tile-grid-3" role="group" aria-labelledby="outlineMainLabel">
                ${outlineTile('mainBpm', String(o.mainBpm), 'bpm', String(o.mainBpm))}
                ${outlineTile('mainNote', metroNoteIconSvg(outlineNoteKey(o.mainNote)), 'beat note', outlineNoteLabel(o.mainNote))}
            </div>
            <div class="section-title">Where it switches</div>
            ${outlineSpeedHtml()}`;
    }
    function outlineHowLongRead() {
        const bars = Number(document.getElementById('outlineBars')?.value);
        if (!Number.isInteger(bars) || bars < 1 || bars > PieceOutline.MAX_BARS) { showWarningToast(`How many bars? 1 to ${PieceOutline.MAX_BARS}.`); return false; }
        outline.o.bars = bars;
        return true;
    }
    function outlinePickSig(current, onPick) {
        metroSegTimeSigValue = current;
        metroSegTimeSigOnSelect = onPick;
        renderMetroSegTimeSigPicker();
        showModal('metroSegTimeSigModal');
    }
    // The same Beat note pop-up the bar-by-bar editor uses; `allowSame` adds "Same as the row above"
    function outlinePickNote(current, onPick) {
        const el = document.getElementById('metroSegNotePicker');
        if (!el) return;
        el.innerHTML = METRO_NOTE_TYPES.map(t => `<button type="button" class="metroBlk-note-btn${t.key === current ? ' selected' : ''}" data-note="${t.key}" aria-label="${t.label}" aria-pressed="${t.key === current}">${metroNoteIconSvg(t.key)}</button>`).join('');
        el.querySelectorAll('.metroBlk-note-btn').forEach(btn => btn.addEventListener('click', () => { hideModal('metroSegNoteModal'); onPick(btn.dataset.note); }, { once: true }));
        showModal('metroSegNoteModal');
    }

    // --- Step 2: marks ---
    function outlineMarksHtml() {
        const o = outline.o;
        const kind = OUTLINE_MARK_KINDS.find(k => k.key === o.markKind);
        let inner = '';
        if (o.markKind === 'numbers') {
            inner = `
                <p class="text-sm text-muted no-margin" id="outlineMarksHelp">Type the bar numbers. Spaces, commas or semicolons between them all work. For letters, words, or numbers that aren't the bar numbers (A, Verse 2, figure 5), change "Bar numbers" above.</p>
                <textarea id="outlineMarksText" class="outline-list" rows="4" inputmode="decimal" aria-label="The bar numbers of the rehearsal marks" aria-describedby="outlineMarksHelp" placeholder="e.g. 10, 12, 15 or 10 12 15">${escapeHtml(outline.marksText)}</textarea>`;
        } else if (o.markKind === 'text') {
            inner = `
                <p class="text-sm text-muted no-margin">Bar, then its mark. Enter (Next on a phone) moves on, and a new row appears by itself.</p>
                <div class="outline-table" id="outlineMarkRows">
                    <div class="outline-row outline-row-marks" aria-hidden="true"><span class="outline-th">At bar</span><span class="outline-th">Mark</span></div>
                    ${outline.markRows.map((r, i) => outlineMarkRowHtml(r, i)).join('')}
                </div>`;
        } else {
            inner = '<p class="text-sm text-muted no-margin">No rehearsal marks - the bars are shown as one block in the next step.</p>';
        }
        return `
            ${outlineValueBtn('markKind', kind.label, 'content of rehearsal marks')}
            ${inner}
            <p class="text-sm text-muted no-margin" id="outlineMarksCount" aria-live="polite"></p>
            <div class="outline-chips" id="outlineMarksChips"></div>`;
    }
    const outlineMarkRowHtml = (r, i) => `<div class="outline-row outline-row-marks">
        <input type="number" inputmode="numeric" data-mark-row="${i}" data-mark-col="bar" value="${escapeHtml(String(r.bar))}" placeholder="bar" aria-label="Row ${i + 1}: bar number" enterkeyhint="next">
        <input type="text" data-mark-row="${i}" data-mark-col="label" value="${escapeHtml(r.label)}" placeholder="e.g. A or 5" maxlength="20" aria-label="Row ${i + 1}: the mark" enterkeyhint="next" autocapitalize="characters" autocomplete="off"></div>`;
    // Reads what's typed into the outline and says what was understood (the count, the chips, what wasn't a bar).
    function outlineMarksRefresh() {
        const o = outline.o;
        let bad = [];
        if (o.markKind === 'numbers') {
            const parsed = PieceOutline.parseBarList(outline.marksText, o.bars);
            o.marks = parsed.bars.map(bar => ({ bar }));
            bad = parsed.bad;
        } else if (o.markKind === 'text') {
            o.marks = outline.markRows.filter(r => r.bar !== '' && String(r.label).trim()).map(r => ({ bar: Number(r.bar), label: r.label }));
            bad = outline.markRows.filter(r => r.bar !== '' && !(Number.isInteger(Number(r.bar)) && Number(r.bar) >= 1 && Number(r.bar) <= o.bars)).map(r => String(r.bar));
        }
        const marks = PieceOutline.marksOf(o);
        const count = document.getElementById('outlineMarksCount');
        const chips = document.getElementById('outlineMarksChips');
        if (!count || !chips) return;
        count.innerHTML = o.markKind === 'none' ? '' : (marks.length
            ? `<strong>${marks.length} mark${marks.length === 1 ? '' : 's'} so far</strong> · last one at bar ${marks[marks.length - 1].bar} of ${o.bars}`
            : 'No marks yet.') + (bad.length ? ` <span class="text-danger">Not a bar of this piece: ${escapeHtml(bad.slice(0, 6).join(', '))}</span>` : '');
        chips.innerHTML = o.markKind === 'numbers' ? marks.map(m => `<span class="outline-chip">${escapeHtml(m.label)}</span>`).join('') : '';
    }

    // The main time signature (step "How long") is what MOST of the piece is in, not what it starts in (owner,
    // 4 Oct 2026) - so a row for bar 1 is ordinary, and the bars before the first row are in the main time.
    // --- Tempo, 1 of 2: time signatures (ML-425) - a table you type down, like Speed. A row says "from this bar it
    // is in this time, for this many bars" - then the piece goes back to what most of it is in, until the next row
    // (one 2/4 bar is one row). The time is typed like 3/4, or picked from the usual pop-up. It replaced tapping
    // every bar: on production no piece had more than five changes, but that step took up to 41 taps.
    // ML-442: how long a row lasts is asked two ways - "bars" and "to bar" - and each fills in the other. One of
    // them is needed: a row no longer "carries on to the next change" (owner, 5 Oct 2026 - you have to know the
    // length anyway).
    // key is '' (not null) while nothing usable is typed: a row counts as blank only when every value is ''
    const outlineTimeBlank = () => ({ bar: '', sig: '', key: '', bars: '', end: '' });
    // What was typed, as numbers - or null when it isn't a time signature the app can keep: the same limits as
    // "add my own" in the time signature pop-up (1 to 32 beats, of a 2, 4, 8 or 16)
    function outlineSigParts(text) {
        const m = String(text || '').trim().match(/^(\d{1,2})\D+(\d{1,2})$/); // anything at all between the two numbers
        if (!m) return null;
        const n = Number(m[1]);
        const d = Number(m[2]);
        return n >= 1 && n <= 32 && [2, 4, 8, 16].includes(d) ? { n, d } : null;
    }
    // What was typed -> one of the app's time signatures ('public:3' / 'custom:7'), or null
    function outlineSigFromText(text) {
        const p = outlineSigParts(text);
        if (!p) return null;
        const hit = (list) => (list || []).find(t => Number(t.numerator) === p.n && Number(t.denominator) === p.d);
        const shared = hit(metroBlkTimeSigCache.public);
        if (shared) return `public:${shared.id}`;
        const own = hit(metroBlkTimeSigCache.custom);
        return own ? `custom:${own.id}` : null;
    }
    // ML-440: a time signature that is typed in and isn't in the list is added to the player's own, quietly -
    // it used to stop the step with nothing to say why. Keyed "7/8" -> the request, so one is asked for once.
    const outlineSigAdding = new Map();
    function outlineSigAdd(text) {
        const p = outlineSigParts(text);
        if (!p || outlineSigFromText(text)) return;
        const name = `${p.n}/${p.d}`;
        if (outlineSigAdding.has(name)) return;
        outlineSigAdding.set(name, API.metronomeBlocks.timeSignatures.createCustom(p.n, p.d)
            .then(() => loadMetroBlkTimeSignatures())
            .catch((error) => showWarningToast(`Couldn't add ${name}: ${error.message}`))
            .finally(() => {
                outlineSigAdding.delete(name);
                if (!outline) return;
                outline.timeRows.forEach(r => { if (!r.key) r.key = outlineSigFromText(r.sig) || ''; });
                if (outlineStepKey() === 'time') outlineTimeRefresh();
            }));
    }
    const outlineTimeIsBlank = (r) => r.bar === '' && r.sig === '' && r.bars === '' && (r.end === '' || r.end === undefined);
    // What stops a row being used, in words, and which of its boxes that is about - null when it's fine (or blank)
    function outlineTimeProblem(r, o) {
        if (outlineTimeIsBlank(r)) return null;
        const bar = Number(r.bar);
        if (r.bar === '' || !Number.isInteger(bar) || bar < 1 || bar > o.bars) return { cols: ['bar'], message: `the bar it starts at is a number from 1 to ${o.bars}.` };
        const typed = String(r.sig).trim();
        if (!typed) return { cols: ['sig'], message: 'it needs a time signature, typed like 3/4.' };
        if (!r.key) {
            const p = outlineSigParts(typed);
            if (!p) return { cols: ['sig'], message: `${typed} isn't a time signature - type it like 3/4: 1 to 32 on top, and 2, 4, 8 or 16 underneath.` };
            if (outlineSigAdding.has(`${p.n}/${p.d}`)) return null; // being added - the row is checked again when it's back
            return { cols: ['sig'], message: `${typed} couldn't be added - check the connection and type it again.` };
        }
        if (r.bars === '' && (r.end === '' || r.end === undefined)) return { cols: ['bars', 'end'], message: 'say how many bars it lasts, or the bar it ends on.' };
        const bars = Number(r.bars);
        if (r.bars === '' || !Number.isInteger(bars) || bars < 1) return { cols: ['bars', 'end'], message: `it can't end before bar ${bar}, where it starts.` };
        if (bar + bars - 1 > o.bars) return { cols: ['bars', 'end'], message: `it ends after the last bar of the piece (${o.bars}).` };
        return null;
    }
    const outlineTimeUsable = (r, o) => !!r.key && !outlineTimeIsBlank(r) && !outlineTimeProblem(r, o);
    // "Bars" and "to bar" say the same thing: whichever was typed works out the other (and a new start bar keeps
    // the length). Returns the columns it changed, so their boxes can be filled in.
    function outlineTimeSync(row, col) {
        const whole = (v) => v !== '' && v !== undefined && Number.isInteger(Number(v));
        const fromBars = () => { row.end = whole(row.bar) && whole(row.bars) && Number(row.bars) >= 1 ? String(Number(row.bar) + Number(row.bars) - 1) : ''; return ['end']; };
        const fromEnd = () => { row.bars = whole(row.bar) && whole(row.end) && Number(row.end) >= Number(row.bar) ? String(Number(row.end) - Number(row.bar) + 1) : ''; return ['bars']; };
        if (col === 'bars') return fromBars();
        if (col === 'end') return fromEnd();
        if (col === 'bar') return whole(row.bars) ? fromBars() : (whole(row.end) ? fromEnd() : []);
        return [];
    }
    // The rows -> o.time (the bars that aren't in the main time). Needs no screen, so Save can rely on it.
    function outlineTimeApply() {
        const o = outline.o;
        if (!outline.timeRows || !outline.timeRows.length) outline.timeRows = [outlineTimeBlank()];
        const time = {};
        // In bar order, so where two rows overlap the later one wins; every bar no row covers is in the main time
        outline.timeRows.filter(r => outlineTimeUsable(r, o))
            .map(r => ({ bar: Number(r.bar), key: r.key, bars: Number(r.bars) })).sort((a, b) => a.bar - b.bar)
            .forEach(r => { for (let b = r.bar; b < r.bar + r.bars; b++) { if (r.key === o.mainSig) delete time[b]; else time[b] = r.key; } });
        o.time = time;
    }
    function outlineTimeHtml() {
        const o = outline.o;
        outlineTimeApply();
        const main = escapeHtml(outlineSigLabel(o.mainSig));
        return `
            <p class="text-sm text-muted no-margin">A switch happens at a bar, all at once. Add a row for each stretch that isn't in ${main} - type it like ${outlineSigExample()}. That can be bar 1, if it starts differently.</p>
            <div class="outline-table" id="outlineTimeRows">
                <div class="outline-row outline-row-time" aria-hidden="true"><span class="outline-th">From bar</span><span class="outline-th">Time</span><span class="outline-th">Bars</span><span class="outline-th">To bar</span></div>
                <div class="outline-row outline-row-time"><span class="outline-cell-fixed">Rest of it</span><span class="outline-cell-fixed">${main}</span><span class="outline-cell-fixed">-</span><span class="outline-cell-fixed">-</span></div>
                ${outline.timeRows.map((r, i) => outlineTimeRowHtml(r, i)).join('')}
            </div>
            <p class="text-sm text-muted no-margin">Fill in how many bars it lasts or the bar it ends on - the other fills itself in. After that the piece is back in ${main}. A single 2/4 bar is 1 bar.</p>
            <p class="text-sm text-muted no-margin" id="outlineTimeCheck" aria-live="polite"></p>
            <p class="outline-sum no-margin" id="outlineTimeSum"></p>`;
    }
    // The example time signature in the hints: 3/4 - or 4/4 when most of the piece is in 3/4 itself. The empty box
    // says "e.g.", so it doesn't look filled in already (owner, 5 Oct 2026).
    const outlineSigExample = () => (outlineSigLabel(outline.o.mainSig) === '3/4' ? '4/4' : '3/4');
    const outlineTimeRowHtml = (r, i) => `<div class="outline-row outline-row-time">
        <input type="number" inputmode="numeric" data-time-row="${i}" data-time-col="bar" value="${escapeHtml(String(r.bar))}" placeholder="bar" aria-label="Row ${i + 1}: from bar" enterkeyhint="next">
        <span class="outline-sig-cell"><input type="text" data-time-row="${i}" data-time-col="sig" value="${escapeHtml(r.sig)}" placeholder="e.g. ${outlineSigExample()}" maxlength="7" autocomplete="off" autocapitalize="off" spellcheck="false" aria-label="Row ${i + 1}: time signature, typed like 3/4" enterkeyhint="next"><button type="button" class="outline-cell-btn" data-time-pick="${i}" aria-haspopup="dialog" aria-label="Row ${i + 1}: choose the time signature from the list"><span class="material-symbols-outlined" aria-hidden="true">list</span></button></span>
        <input type="number" inputmode="numeric" data-time-row="${i}" data-time-col="bars" value="${escapeHtml(String(r.bars))}" placeholder="bars" aria-label="Row ${i + 1}: how many bars it lasts" enterkeyhint="next">
        <input type="number" inputmode="numeric" data-time-row="${i}" data-time-col="end" value="${escapeHtml(String(r.end === undefined ? '' : r.end))}" placeholder="to" aria-label="Row ${i + 1}: the bar it ends on" enterkeyhint="next"></div>`;
    // Reads the rows, marks the boxes that stop a row being used and says why, and what the piece comes to.
    // While typing, the row being typed in isn't told off yet (finishing: true checks them all).
    function outlineTimeRefresh({ finishing = false } = {}) {
        const o = outline.o;
        outlineTimeApply();
        const active = document.activeElement;
        const typingIn = !finishing && active && active.dataset && active.dataset.timeRow !== undefined ? Number(active.dataset.timeRow) : -1;
        const problems = outline.timeRows.map((r, i) => ({ i, p: outlineTimeProblem(r, o) })).filter(x => x.p);
        const adding = outline.timeRows.some(r => !r.key && !outlineTimeIsBlank(r) && !outlineTimeProblem(r, o));
        const shown = problems.filter(x => x.i !== typingIn);
        document.querySelectorAll('#outlineTimeRows input[data-time-row]').forEach(el => {
            const hit = shown.find(x => x.i === Number(el.dataset.timeRow));
            if (hit && hit.p.cols.includes(el.dataset.timeCol)) el.setAttribute('aria-invalid', 'true'); else el.removeAttribute('aria-invalid');
        });
        const check = document.getElementById('outlineTimeCheck');
        if (check) check.innerHTML = shown.length ? `<span class="text-danger">${shown.map(x => `Row ${x.i + 1}: ${escapeHtml(x.p.message)}`).join(' ')}</span>` : '';
        const sum = PieceOutline.timeSummary(o);
        const main = outlineSigLabel(o.mainSig);
        const el = document.getElementById('outlineTimeSum');
        if (el) el.innerHTML = sum.length ? `So far: ${sum.map(x => `<strong>${escapeHtml(outlineSigLabel(x.sig))}</strong> ${x.bars} bar${x.bars === 1 ? '' : 's'}`).join(' · ')} · everything else is ${escapeHtml(main)}` : `Every bar is ${escapeHtml(main)} so far. If that's right, go straight on.`;
        return !problems.length && !adding;
    }
    // The pop-up's answer goes into the row's box as words, exactly as if it had been typed
    function outlineTimePick(i) {
        const row = outline.timeRows[i];
        if (!row) return;
        outlinePickSig(row.key || outline.o.mainSig, (value) => {
            row.key = value;
            row.sig = outlineSigLabel(value);
            outlineGrowTable(outline.timeRows, outlineTimeBlank, outlineTimeRowHtml, 'outlineTimeRows');
            outlineRerenderKeeping(`[data-time-row="${i}"][data-time-col="bars"]`);
        });
    }

    // Redraws the step and puts keyboard focus back where it was (a redraw throws the buttons away)
    function outlineRerenderKeeping(selector) {
        const y = window.scrollY;
        renderOutline();
        window.scrollTo({ top: y });
        if (selector) document.querySelector(`#outlineBody ${selector}`)?.focus({ preventScroll: true });
    }

    // --- Step 4: speed (a table) ---
    function outlineSpeedHtml() {
        const o = outline.o;
        return `
            <p class="text-sm text-muted no-margin">Add a row for each bar where the speed switches, all at once - it carries on from there. A rall. or accel. is the next step.</p>
            <div class="outline-table" id="outlineSpeedRows">
                <div class="outline-row outline-row-speed" aria-hidden="true"><span class="outline-th">From bar</span><span class="outline-th">bpm</span><span class="outline-th">Beat note</span></div>
                <div class="outline-row outline-row-speed"><span class="outline-cell-fixed">Start</span><span class="outline-cell-fixed" id="outlineSpeedStartBpm">${o.mainBpm}</span><span class="outline-cell-fixed" id="outlineSpeedStartNote">${outlineNoteIcon(o.mainNote)}</span></div>
                ${outline.speedRows.map((r, i) => outlineSpeedRowHtml(r, i)).join('')}
            </div>
            <p class="text-sm text-muted no-margin">The beat note stays the same as the row above unless you change it.</p>
            <p class="text-sm text-muted no-margin" id="outlineSpeedCheck" aria-live="polite"></p>
            <p class="outline-sum no-margin" id="outlineSpeedSum"></p>`;
    }
    // A row's beat note as it will be: its own if one was picked, else the nearest row above's that has one, else the
    // piece's. The button always shows that note - it used to say "same" (owner, 5 Oct 2026: show what it actually is).
    function outlineSpeedRowNote(i) {
        for (let k = i; k >= 0; k--) if (outline.speedRows[k] && outline.speedRows[k].noteValue) return outline.speedRows[k].noteValue;
        return outline.o.mainNote;
    }
    const outlineSpeedRowHtml = (r, i) => `<div class="outline-row outline-row-speed">
        <input type="number" inputmode="numeric" data-speed-row="${i}" data-speed-col="bar" value="${escapeHtml(String(r.bar))}" placeholder="bar" aria-label="Row ${i + 1}: from bar" enterkeyhint="next">
        <input type="number" inputmode="numeric" data-speed-row="${i}" data-speed-col="bpm" value="${escapeHtml(String(r.bpm))}" placeholder="bpm" aria-label="Row ${i + 1}: bpm" enterkeyhint="next">
        <button type="button" class="outline-cell-btn" data-speed-note="${i}" aria-haspopup="dialog" aria-label="Row ${i + 1}: beat note, ${escapeHtml(outlineNoteLabel(outlineSpeedRowNote(i)))} - tap to change">${metroNoteIconSvg(outlineNoteKey(outlineSpeedRowNote(i)))}</button></div>`;
    function outlineSpeedRefresh() {
        const o = outline.o;
        // A row left wholly blank is ignored (the table always ends in one). A row for bar 1 is the
        // starting speed, so it changes "Start" instead of being refused (owner, 4 Oct 2026).
        const rows = outline.speedRows.filter(r => r.bar !== '' || r.bpm !== '');
        const usable = (r) => r.bar !== '' && r.bpm !== '' && Number.isInteger(Number(r.bar)) && Number(r.bar) >= 1 && Number(r.bar) <= o.bars && Number(r.bpm) >= 20 && Number(r.bpm) <= 400;
        const start = rows.filter(r => usable(r) && Number(r.bar) === 1).pop();
        if (start) {
            o.mainBpm = Number(start.bpm);
            if (start.noteValue !== undefined) o.mainNote = start.noteValue;
            // (the Start row, and the tiles above the table, follow a bar 1 row)
            ['#outlineSpeedStartBpm', '[data-outline="mainBpm"] .flow-tile-value'].forEach(sel => { const el = document.querySelector(`#outlineBody ${sel}`); if (el) el.textContent = o.mainBpm; });
            const noteTile = document.querySelector('#outlineBody [data-outline="mainNote"] .flow-tile-value');
            if (noteTile) noteTile.innerHTML = metroNoteIconSvg(outlineNoteKey(o.mainNote));
            const note = document.getElementById('outlineSpeedStartNote');
            if (note) note.innerHTML = outlineNoteIcon(o.mainNote);
        }
        o.speeds = rows.filter(r => r.bar !== '' && r.bpm !== '' && Number(r.bar) !== 1).map(r => ({ bar: Number(r.bar), bpm: Number(r.bpm), noteValue: r.noteValue }));
        const bad = outline.speedRows.map((r, i) => ((r.bar !== '' || r.bpm !== '') && !usable(r) ? i + 1 : 0)).filter(Boolean);
        const check = document.getElementById('outlineSpeedCheck');
        if (check) check.innerHTML = bad.length ? `<span class="text-danger">${bad.length === 1 ? `Row ${bad[0]}` : `Rows ${bad.join(', ')}`} can't be used yet: ${bad.length === 1 ? 'it needs' : 'each needs'} a bar from 1 to ${o.bars} and a speed from 20 to 400.</span>` : '';
        const sum = document.getElementById('outlineSpeedSum');
        if (sum) sum.innerHTML = outlineSummaryText();
        return !bad.length;
    }

    // --- ML-435: repeats and pauses are tables you type down, like Speed and Time. On production each one took a
    // tap to add, a pop-up, the numbers and a tap to confirm - about four taps each; a row needs none.
    //   repeats: from bar, to bar, times played (2 if left empty), and - for 1st and 2nd endings - the bar the 1st
    //            ending starts at and the bar the last ending ends at (the bar after the repeat unless typed)
    //   pauses:  in bar, on beat (1 if empty), beats held (2 if empty), and Pause (held) or Break (silent)
    // The rows become the same extras the pop-up made (outlineRowsApply), so everything after is unchanged.
    const OUTLINE_ROW_TABLES = {
        repeat: {
            rows: 'repeatRows', id: 'outlineRepeatRows', css: 'outline-row-repeat', types: ['repeat', 'repeatEndings'],
            // e2Auto: '1' while the last ending is the filled-in bar. mids (ML-460): the bars the endings between the
            // 1st and the last end at, as "18,20" - a different ending for each time through, typed in the Endings pop-up
            blank: () => ({ from: '', to: '', times: '', e1From: '', e2To: '', e2Auto: '', mids: '' }),
            cols: [['from', 'From bar', 'from bar', 'bar'], ['to', 'To bar', 'to bar', 'bar'], ['times', 'Times', 'times played - 2 if empty', 'e.g. 2'], ['e1From', '1st ending', 'the bar the 1st ending starts at - empty for a plain repeat', 'bar'], ['e2To', 'Last ending', 'the bar the last ending ends at - the bar after the repeat if empty', 'bar']],
            // Played 3 or more times there are still two endings: the 1st is for every time but the last, the last
            // ending for the last time (PieceOutline.buildBlocks) - so the columns say 1st and Last, not 1st and 2nd.
            help: 'Bars played more than once. Leave "times" empty for twice - for a hymn or carol sung through 6 times, put 6. For 1st and 2nd time bars, fill in the bar the 1st ending starts at; "to bar" is where it ends. The last ending is taken as the one bar after the repeat - change it if it is longer. Played 3 or more times, the 1st ending is for every time but the last - for a different ending each time (1. 2. 3.), tap the row\'s Endings button.',
            extra(r) {
                const n = (v) => (v === '' ? NaN : Number(v));
                const mids = r.mids ? r.mids.split(',').map(n) : [];
                // played twice unless it says - or once for each ending, when there are more than two
                const base = { from: n(r.from), to: n(r.to), times: r.times === '' ? mids.length + 2 : n(r.times) };
                if (r.e1From === '' && r.e2To === '' && !mids.length) return { type: 'repeat', ...base };
                // the last ending is nearly always the one bar after the repeat, so that is what an empty box means
                return { type: 'repeatEndings', ...base, e1From: n(r.e1From), e2To: r.e2To === '' ? base.to + 1 : n(r.e2To), ...(mids.length ? { mids } : {}) };
            },
            // How many endings the row has: none for a plain repeat, else the 1st, the last and any between
            endings: (r) => (r.e1From === '' && r.e2To === '' && !r.mids ? 0 : (r.mids ? r.mids.split(',').length : 0) + 2),
            // As the 1st ending (or the end of the repeat) is typed, the last ending's box is filled in with the bar
            // after the repeat - until a different bar is typed there. Returns the columns it changed.
            sync(r, col) {
                if (col === 'e2To') { r.e2Auto = ''; return []; }
                if (!['to', 'e1From'].includes(col) || (r.e2To !== '' && !r.e2Auto)) return [];
                const to = Number(r.to);
                const fill = r.e1From !== '' && r.to !== '' && Number.isInteger(to) ? String(to + 1) : '';
                r.e2To = fill;
                r.e2Auto = fill ? '1' : '';
                return ['e2To'];
            },
            started: (r) => r.from !== '' || r.to !== '' || r.times !== '' || r.e1From !== '' || r.e2To !== '' || !!r.mids,
            ready: (r) => r.from !== '' && r.to !== '' && !(r.e1From === '' && (r.e2To !== '' || !!r.mids))
        },
        pause: {
            rows: 'pauseRows', id: 'outlinePauseRows', css: 'outline-row-pause', types: ['pause'],
            blank: () => ({ bar: '', beat: '', holdBeats: '', kind: '' }),
            cols: [['bar', 'In bar', 'in bar', 'bar'], ['beat', 'On beat', 'on beat - 1 if empty', 'e.g. 1'], ['holdBeats', 'Beats held', 'beats held - 2 if empty', 'e.g. 2']],
            help: 'A held note or a silent break. Leave "on beat" empty for beat 1 and "beats held" empty for 2.',
            extra(r) {
                const n = (v) => (v === '' ? NaN : Number(v));
                const kind = r.kind === 'caesura' ? 'caesura' : 'fermata';
                return { type: 'pause', kind, bar: n(r.bar), beat: r.beat === '' ? 1 : n(r.beat), holdBeats: r.holdBeats === '' ? 2 : n(r.holdBeats), playbackMode: kind === 'caesura' ? 'silent' : 'tone' };
            },
            started: (r) => r.bar !== '' || r.beat !== '' || r.holdBeats !== '',
            ready: (r) => r.bar !== ''
        }
    };
    const outlineRowsOf = (t) => { if (!outline[t.rows] || !outline[t.rows].length) outline[t.rows] = [t.blank()]; return outline[t.rows]; };
    // The typed rows -> o.extras (the extras of those kinds are replaced; the others are left alone). Returns
    // what is wrong with each row that can't be used: [{ row, message }], rows counted from 1.
    function outlineRowsApply() {
        const o = outline.o;
        const problems = {};
        let extras = o.extras.filter(x => !Object.values(OUTLINE_ROW_TABLES).some(t => t.types.includes(x.type)));
        Object.entries(OUTLINE_ROW_TABLES).forEach(([key, t]) => {
            problems[key] = [];
            outlineRowsOf(t).forEach((r, i) => {
                if (!t.started(r)) return;
                if (!t.ready(r)) { problems[key].push({ row: i + 1, message: key === 'repeat' ? (r.from !== '' && r.to !== '' ? 'a last ending needs the bar the 1st ending starts at' : 'it needs a from bar and a to bar') : 'it needs a bar' }); return; }
                const x = t.extra(r);
                const problem = PieceOutline.extraProblem(o, x);
                if (problem) { problems[key].push({ row: i + 1, message: problem }); return; }
                extras.push({ ...x, row: { table: key, index: i + 1 } });
            });
        });
        extras.sort((a, b) => (a.from ?? a.bar) - (b.from ?? b.bar));
        o.extras = extras;
        // A row that is fine by itself can still clash with the piece or another extra
        const built = PieceOutline.buildBlocks(o);
        built.clashes.forEach(c => { const x = o.extras[c.extra]; if (x && x.row) problems[x.row.table].push({ row: x.row.index, message: c.message }); });
        return problems;
    }
    const outlineEndsLabel = (i, n) => `Row ${i + 1}: ${n ? `${n} endings` : 'no endings'} - tap to change`;
    const outlineTableRowHtml = (t) => (r, i) => `<div class="outline-row ${t.css}">
        ${t.cols.map(([col, , label, hint]) => `<input type="number" inputmode="${col === 'holdBeats' ? 'decimal' : 'numeric'}" ${col === 'holdBeats' ? 'step="any" ' : ''}data-xrow="${i}" data-xcol="${col}" value="${escapeHtml(String(r[col]))}" placeholder="${hint}" aria-label="Row ${i + 1}: ${label}" enterkeyhint="next">`).join('')}
        ${t === OUTLINE_ROW_TABLES.pause ? `<button type="button" class="outline-cell-btn" data-xkind="${i}" aria-haspopup="dialog" aria-label="Row ${i + 1}: ${r.kind === 'caesura' ? 'a caesura - a silent break' : 'a fermata - a held pause'} - tap to change">${theoryGlyphs([r.kind === 'caesura' ? 'caesura' : 'fermataAbove'])}</button>` : ''}
        ${t === OUTLINE_ROW_TABLES.repeat ? `<button type="button" class="outline-cell-btn" data-xends="${i}" aria-haspopup="dialog" aria-label="${outlineEndsLabel(i, t.endings(r))}">${t.endings(r)}</button>` : ''}</div>`;
    function outlineTableHtml(key) {
        const t = OUTLINE_ROW_TABLES[key];
        const rows = outlineRowsOf(t);
        return `
            <p class="text-sm text-muted no-margin">${escapeHtml(t.help)}</p>
            <div class="outline-table" id="${t.id}" data-xtable="${key}">
                <div class="outline-row ${t.css}" aria-hidden="true">${t.cols.map(([, head]) => `<span class="outline-th">${head}</span>`).join('')}${key === 'pause' ? '<span class="outline-th">Kind</span>' : ''}${key === 'repeat' ? '<span class="outline-th">Endings</span>' : ''}</div>
                ${rows.map(outlineTableRowHtml(t)).join('')}
            </div>
            <p class="text-sm text-muted no-margin" id="outlineRowsCheck" aria-live="polite"></p>`;
    }
    // Reads the rows of the table on screen, says which can't be used and why, and what the piece comes to
    function outlineRowsRefresh(key) {
        const problems = outlineRowsApply()[key] || [];
        const check = document.getElementById('outlineRowsCheck');
        if (check) check.innerHTML = problems.length ? `<span class="text-danger">${problems.map(p => `Row ${p.row}: ${escapeHtml(p.message)}`).join(' ')}</span>` : '';
        const sum = document.querySelector('#outlineBody .outline-sum');
        if (sum) sum.innerHTML = outlineSummaryText();
        return !problems.length;
    }

    // --- Extras and Media: one yes/no question a step. Yes lets you add as many as there are; No moves on. ---
    const outlineStepExtras = (step) => outline.o.extras.map((x, i) => ({ x, i })).filter(e => step.kinds.includes(e.x.type));
    const outlineStepCount = (step) => (step.kinds ? outlineStepExtras(step).length : Object.values(outline.media).reduce((n, l) => n + l.length, 0));
    // ML-448: no Yes / No on these steps (owner, 5 Oct 2026). The question stays as the heading; the answer is "no"
    // until something is added, so Next just carries on - and the way to add one (the table, or "+ Add") is there
    // straight away. What was added is taken out where it shows: its pop-up, its row, or by emptying a table row.
    const OUTLINE_NONE_LINE = '<p class="text-sm text-muted no-margin">If not, go straight on.</p>';
    // Two steps say what to look for instead, with the signs themselves drawn in the notation font (owner, 5 Oct 2026)
    const OUTLINE_STEP_HINTS = {
        xPauses: () => `Add any fermatas (${theoryGlyphs(['fermataAbove'])}) or caesuras (${theoryGlyphs(['caesura'])}).`,
        // (the kinds of file are the ones the upload accepts - allowedContentTypes in server/routes/api.js)
        // (a sudden change of speed is the Speed step's - this one is the speed sliding over some bars)
        xRamps: () => 'The speed changing gradually over some bars - a rall., rit. or accel. A sudden switch of speed belongs on the step before this one.',
        xSigns: () => `Add any segno (${theoryScaleSvg(Notation.symbol('segno'), 0.32)}) or coda (${theoryScaleSvg(Notation.symbol('coda'), 0.32)}) signs, and the jumps that go with them - D.S., D.C., To Coda, Fine.`
    };
    const outlineNoneLine = (step) => (OUTLINE_STEP_HINTS[step.key] ? `<p class="text-sm text-muted no-margin">${OUTLINE_STEP_HINTS[step.key]()}</p>` : OUTLINE_NONE_LINE);
    // --- The intro (owner, 5 Oct 2026): there is only ever one and it is two numbers, so it has no pop-up - a
    // switch (off to start with) and, when it is on, its bars on the step itself.
    const outlineIntro = () => { if (!outline.intro) outline.intro = { on: false, from: '', to: '' }; return outline.intro; };
    // The switch and boxes -> the one intro extra (or none). What is wrong with it, in words, or null.
    function outlineIntroApply() {
        const o = outline.o, it = outlineIntro();
        o.extras = o.extras.filter(x => x.type !== 'intro');
        if (!it.on) return null;
        if (it.from === '') return 'Say which bar the introduction starts at - or switch it off.';
        const x = { type: 'intro', from: Number(it.from), to: it.to === '' ? null : Number(it.to) };
        const problem = PieceOutline.extraProblem(o, x);
        if (problem) return problem;
        o.extras.push(x);
        o.extras.sort((a, b) => (a.from ?? a.bar) - (b.from ?? b.bar));
        const clash = PieceOutline.buildBlocks(o).clashes.find(c => o.extras[c.extra] === x);
        return clash ? clash.message : null;
    }
    function outlineIntroRefresh() {
        const problem = outlineIntroApply();
        const check = document.getElementById('outlineIntroCheck');
        if (check) check.textContent = problem && outlineIntro().from !== '' ? problem : '';
        const sum = document.querySelector('#outlineBody .outline-sum');
        if (sum) sum.innerHTML = outlineSummaryText();
        return !problem;
    }
    function outlineIntroStepHtml() {
        const it = outlineIntro();
        outlineIntroApply();
        return `
            <div class="display-toggle-row">
                <span id="outlineIntroLabel">Include an introduction<span class="display-toggle-help">Bars from later in the piece that are played first</span></span><label class="toggle-switch"><input type="checkbox" id="outlineIntroOn" aria-labelledby="outlineIntroLabel"${it.on ? ' checked' : ''}><span class="toggle-slider"></span></label>
            </div>
            ${it.on ? `<div class="outline-pair">${outlineNumField('outlineIntroFrom', it.from, 'from bar', 'min="1"')}${outlineNumField('outlineIntroTo', it.to, 'to bar (or leave empty)', 'min="1"')}</div>
            <p class="text-sm text-muted no-margin">Leave "to bar" empty if the introduction runs to the end of the piece.</p>
            <p class="text-sm text-danger no-margin" id="outlineIntroCheck" aria-live="polite"></p>` : ''}
            <p class="outline-sum no-margin">${outlineSummaryText()}</p>`;
    }
    function outlineExtrasStepHtml(step) {
        if (step.key === 'xIntro') return outlineIntroStepHtml();
        if (step.table) {
            outlineRowsApply();
            return `
            ${outlineNoneLine(step)}
            ${outlineTableHtml(step.table)}
            <p class="outline-sum no-margin">${outlineSummaryText()}</p>`;
        }
        const built = outlineBuild();
        const mine = outlineStepExtras(step);
        const clashOf = (i) => built.clashes.find(c => c.extra === i);
        const rows = mine.map(({ x, i }) => {
            const d = PieceOutline.describeExtra(x);
            const clash = clashOf(i);
            return `<button type="button" class="outline-extra${clash ? ' has-clash' : ''}" data-outline-extra="${i}" aria-haspopup="dialog">
                <span class="material-symbols-outlined" aria-hidden="true">${OUTLINE_EXTRAS[x.type].icon}</span>
                <span class="outline-extra-text"><strong>${escapeHtml(d.title)}</strong><span class="text-sm text-muted">${escapeHtml(d.sub)}</span>${clash ? `<span class="outline-extra-clash">${flowWarningIconSvg('flow-tile-warning-icon')}<span>${escapeHtml(clash.message)}</span></span>` : ''}</span>
                <span class="material-symbols-outlined" aria-hidden="true">chevron_right</span></button>`;
        }).join('');
        const canAdd = !(step.one && mine.length);
        const blocked = mine.some(({ i }) => clashOf(i));
        return `
            ${mine.length ? '' : outlineNoneLine(step)}
            ${rows}
            ${canAdd ? `<button type="button" class="outline-add" data-outline="addExtra" aria-haspopup="dialog">+ ${mine.length ? step.addMore : step.add}</button>` : ''}
            ${blocked ? '<p class="text-sm text-danger no-margin" role="alert">Fix what is marked before going on.</p>' : ''}
            <p class="outline-sum no-margin">${outlineSummaryText()}</p>`;
    }
    // --- Media: ONE step, the last (owner, 5 Oct 2026 - it was three, one question each, which was three taps of
    // Next for something rarely added straight away). Three things can be added on it, each optional: files with
    // the music on them, YouTube links, and the written music. Nothing has to be touched to save.
    const OUTLINE_MEDIA = [
        { list: 'audio', title: 'MP3 / MP4 files', hint: `A file with the music on it: MP3, M4A, WAV or MP4, up to ${MAX_PIECE_FILE_MB} MB.`, icon: 'music_note', add: 'Choose an MP3 / MP4 file', addMore: 'Add another file', input: 'outlineAudioInput' },
        { list: 'video', title: 'YouTube links', hint: 'A recording of it on YouTube.', icon: 'smart_display', add: 'Add a YouTube link', addMore: 'Add another YouTube link' },
        { list: 'docs', title: 'Scores and parts', hint: `The written music: PDF, MusicXML, MuseScore (.mscz), Sibelius (.sib) or Finale (.musx), up to ${MAX_PIECE_FILE_MB} MB.`, icon: 'description', add: 'Choose a score or part', addMore: 'Add another file', input: 'outlineDocsInput' }
    ];
    function outlineMediaStepHtml() {
        const sizeOf = (f) => (f.size ? `${(f.size / (1024 * 1024)).toFixed(1)} MB` : '');
        const sections = OUTLINE_MEDIA.map((m) => {
            const items = outline.media[m.list];
            // A row is the button that takes it out again
            const rows = items.map((f, i) => {
                const title = m.list === 'video' ? (f.title || 'YouTube video') : f.name;
                return `<button type="button" class="outline-extra" data-outline-media-remove="${i}" data-media-list="${m.list}" aria-label="Remove ${escapeHtml(title)}">
                <span class="material-symbols-outlined" aria-hidden="true">${m.icon}</span>
                <span class="outline-extra-text"><strong>${escapeHtml(title)}</strong><span class="text-sm text-muted">${escapeHtml(m.list === 'video' ? f.url : sizeOf(f))}</span></span>
                <span class="material-symbols-outlined" aria-hidden="true">close</span></button>`;
            }).join('');
            // The YouTube boxes only show once its "+ Add" is tapped, so the step starts as three buttons
            const add = m.list === 'video' && outline.videoOpen
                ? `<div class="form-group no-margin"><label for="outlineVideoUrl">YouTube link</label><input type="url" id="outlineVideoUrl" inputmode="url" placeholder="https://youtu.be/..." autocomplete="off" enterkeyhint="next"></div>
               <div class="form-group no-margin"><label for="outlineVideoTitle">What to call it (optional)</label><input type="text" id="outlineVideoTitle" maxlength="120" autocomplete="off" enterkeyhint="done"></div>
               <button type="button" class="outline-add" data-outline="addVideo">+ Add the link</button>`
                : `<button type="button" class="outline-add" data-outline="pickFile" data-media-list="${m.list}">+ ${items.length ? m.addMore : m.add}</button>`;
            return `<div class="section-title">${m.title}</div>
            <p class="text-sm text-muted no-margin">${m.hint}</p>
            ${rows}${add}`;
        }).join('');
        const built = outlineBuild();
        const blocked = !!(built.clashes.length || built.errors.length);
        const other = built.clashes.length ? '' : built.errors.map(m => `<p class="outline-extra-clash">${flowWarningIconSvg('flow-tile-warning-icon')}<span>${escapeHtml(m)}</span></p>`).join('');
        return `
            <p class="text-sm text-muted no-margin">All of this can be added later too, from My music. If there is nothing to add, save the piece. Files are uploaded when you save.</p>
            ${sections}
            ${outlineReadKeepHtml()}
            ${other}<p class="outline-sum no-margin">${outlineSummaryText()}</p>
            ${blocked ? '<p class="text-sm text-danger no-margin" role="alert">Something earlier needs fixing before the piece can be saved. Use Back to go to it.</p>' : ''}`;
    }
    // "+ Add": the pop-up for the one kind this step has (or the choice of kinds); on Media, the file picker of the
    // list asked for, or the YouTube boxes
    function outlineAddForStep(step, list) {
        if (step.media) {
            const m = OUTLINE_MEDIA.find(x => x.list === list);
            if (!m) return;
            if (m.list === 'video') { outline.videoOpen = true; outlineRerenderKeeping('#outlineVideoUrl'); return; }
            withUploadRights(() => document.getElementById(m.input)?.click()); // ML-278
            return;
        }
        if (step.table) { document.querySelector(`#${OUTLINE_ROW_TABLES[step.table].id} input`)?.focus(); return; }
        if (step.kinds.length === 1) { outlineOpenExtra(null, step.kinds[0]); return; }
            openFlowChoiceModal('Which kind?', step.kinds.map(k => ({ key: k, html: `<span class="material-symbols-outlined" aria-hidden="true">${OUTLINE_EXTRAS[k].icon}</span><span><strong>${OUTLINE_EXTRAS[k].label}</strong><br><span class="text-sm text-muted">${OUTLINE_EXTRAS[k].sub}</span></span>` })), (opt) => outlineOpenExtra(null, opt.key));
    }
    function outlineAddVideo() {
        const url = (document.getElementById('outlineVideoUrl')?.value || '').trim();
        const title = (document.getElementById('outlineVideoTitle')?.value || '').trim();
        if (!url) { showWarningToast('Paste the YouTube link first.'); return; }
        if (!flowParseYouTubeId(url)) { showWarningToast("That doesn't look like a YouTube link."); return; }
        outline.media.video.push({ url, title });
        outline.videoOpen = false;
        outlineRerenderKeeping('#outlineVideoUrl');
    }
    ['outlineAudioInput', 'outlineDocsInput'].forEach(id => document.getElementById(id)?.addEventListener('change', (e) => {
        const files = [...e.target.files].filter(f => !pieceFileTooBig(f));
        e.target.value = '';
        if (!outline || !files.length) return;
        const list = id === 'outlineAudioInput' ? 'audio' : 'docs';
        outline.media[list].push(...files);
        outlineRerenderKeeping(`[data-outline="pickFile"][data-media-list="${list}"]`);
    }));

    let outlineExtraDraft = null; // { index (null = new), x }
    const OUTLINE_EXTRA_DEFAULTS = {
        repeat: () => ({ type: 'repeat', from: '', to: '', times: 2 }),
        repeatEndings: () => ({ type: 'repeatEndings', from: '', to: '', times: 2, e1From: '', e2To: '' }),
        pause: () => ({ type: 'pause', kind: 'fermata', bar: '', beat: 1, holdBeats: 2, playbackMode: 'tone' }),
        ramp: () => ({ type: 'ramp', from: '', to: '', startBeat: 1, target: 'next', bpm: '' }),
        sign: () => ({ type: 'sign', sign: 'segno', bar: '' }),
        intro: () => ({ type: 'intro', from: '', to: '' })
    };
    function outlineOpenExtra(index, type) {
        const x = index === null ? OUTLINE_EXTRA_DEFAULTS[type]() : { ...outline.o.extras[index] };
        if (x.type === 'intro' && x.to === null) x.to = '';
        outlineExtraDraft = { index, x };
        document.getElementById('outlineExtraTitle').textContent = OUTLINE_EXTRAS[x.type].label;
        document.getElementById('outlineExtraSaveBtn').textContent = index === null ? 'Add it' : 'Save the change';
        setShown('outlineExtraRemoveBtn', index !== null);
        renderOutlineExtraForm();
        showModal('outlineExtraModal');
        document.querySelector('#outlineExtraForm input[type="number"]')?.focus();
    }
    function renderOutlineExtraForm() {
        const x = outlineExtraDraft.x;
        const num = (key, label, attrs = '') => `<label class="outline-field"><input type="number" inputmode="numeric" data-x="${key}" value="${escapeHtml(String(x[key] ?? ''))}" enterkeyhint="next" ${attrs}><span class="outline-field-label">${escapeHtml(label)}</span></label>`;
        const pills = (key, options, label) => `<div class="radio-group" role="radiogroup" aria-label="${escapeHtml(label)}">${options.map(([v, l]) => `<input type="radio" id="outlineX-${key}-${v}" name="outlineX-${key}" data-x-radio="${key}" value="${v}"${x[key] === v ? ' checked' : ''}><label for="outlineX-${key}-${v}">${escapeHtml(l)}</label>`).join('')}</div>`;
        const head = (t) => `<span class="outline-th">${t}</span>`;
        let html = '';
        if (x.type === 'repeat') html = `<div class="outline-three">${num('from', 'from bar')}${num('to', 'to bar')}${num('times', 'times played', 'min="2" max="9"')}</div>`;
        if (x.type === 'repeatEndings') html = `${head('The repeat, up to the end of the 1st ending')}<div class="outline-three">${num('from', 'from bar')}${num('to', 'to bar')}${num('times', 'times played', 'min="2" max="9"')}</div>
            <div class="outline-pair"><div>${head('1st ending')}${num('e1From', 'starts at bar')}</div><div>${head('2nd ending')}${num('e2To', 'ends at bar')}</div></div>`;
        if (x.type === 'pause') html = `${pills('kind', [['fermata', 'Pause (held)'], ['caesura', 'Break (silent)']], 'What kind')}
            <div class="outline-three">${num('bar', 'in bar')}${num('beat', 'on beat', 'min="1"')}${num('holdBeats', 'beats held', 'min="1" step="any"')}</div>`; // no "how it sounds": that's each player's own setting (Settings → Metronome & playback), not the piece's
        if (x.type === 'ramp') html = `<div class="outline-three">${num('from', 'from bar')}${num('to', 'to bar')}${num('startBeat', 'starting on beat', 'min="1"')}</div>
            ${pills('target', [['next', 'To the next speed'], ['custom', 'To a speed I type']], 'What speed it reaches')}
            ${x.target === 'custom' ? num('bpm', 'bpm to reach', 'min="20" max="400"') : ''}`;
        // Signs and jumps are the bar editor's own tiles (its Jump sign and Jump instruction pop-ups), both sets in
        // this one pop-up, with the bar underneath (owner, 5 Oct 2026 - it was a list of words). Fine is with the jumps.
        if (x.type === 'sign') {
            const coda = flowSignIconSvg('coda', true);
            const tile = (key, icon, caption) => `<button type="button" class="flow-picker-tile${x.sign === key ? ' selected' : ''}" data-x-sign="${key}" aria-label="${escapeHtml(PieceOutline.SIGNS[key].label)}" aria-pressed="${x.sign === key}"><span class="flow-picker-tile-icon-row">${icon}</span><span class="flow-picker-tile-label">${caption}</span></button>`;
            html = `${head('A sign, for jumps to land on')}
            <div class="flow-tile-grid flow-tile-grid-3-centered">${tile('segno', flowSignIconSvg('segno'), 'Segno')}${tile('coda', flowSignIconSvg('coda'), 'Coda')}</div>
            ${head('A jump: where to go after the bar')}
            <div class="flow-tile-grid flow-tile-grid-3-centered">${tile('dsCoda', `D.S. al ${coda}`, 'Segno to Coda')}${tile('dcCoda', `D.C. al ${coda}`, 'Start to Coda')}${tile('toCoda', `To ${coda}`, 'Jump to Coda')}${tile('ds', 'D.S.', 'Segno to Fine')}${tile('dc', 'D.C.', 'Start to Fine')}${tile('fine', 'Fine', 'Stop here')}</div>
            ${num('bar', PieceOutline.SIGNS[x.sign].at === 'start' ? 'at the start of bar' : 'at the end of bar')}`;
        }
        if (x.type === 'intro') html = `<div class="outline-pair">${num('from', 'from bar')}${num('to', 'to bar (or leave empty)')}</div>`;
        document.getElementById('outlineExtraForm').innerHTML = html;
        outlineExtraCheck();
    }
    // The draft with its numbers as numbers (an empty box stays empty, so the check can say what's missing)
    function outlineExtraClean() {
        const x = { ...outlineExtraDraft.x };
        ['from', 'to', 'times', 'e1From', 'e2To', 'bar', 'beat', 'holdBeats', 'startBeat', 'bpm'].forEach(k => { if (k in x) x[k] = x[k] === '' || x[k] === null ? NaN : Number(x[k]); });
        if (x.type === 'intro') x.to = Number.isNaN(x.to) ? null : x.to;
        if (x.type === 'ramp' && x.target !== 'custom') x.bpm = null;
        return x;
    }
    // In plain words what it will do - or what's wrong with it
    function outlineExtraCheck() {
        const x = outlineExtraClean();
        const el = document.getElementById('outlineExtraCheck');
        const o = outline.o;
        let problem = PieceOutline.extraProblem(o, x);
        if (!problem) {
            const extras = o.extras.slice();
            const at = outlineExtraDraft.index === null ? extras.length : outlineExtraDraft.index;
            extras[at] = x;
            const clash = PieceOutline.buildBlocks({ ...o, extras }).clashes.find(c => c.extra === at);
            if (clash) problem = clash.message;
        }
        const empty = Object.entries(outlineExtraDraft.x).some(([k, v]) => v === '' && !(x.type === 'intro' && k === 'to') && !(k === 'bpm' && x.target !== 'custom'));
        if (empty) { el.textContent = 'Fill in the bar numbers.'; el.classList.remove('text-danger'); return false; }
        if (problem) { el.textContent = problem; el.classList.add('text-danger'); return false; }
        const d = PieceOutline.describeExtra(x);
        let text = `${d.title}. ${d.sub}.`;
        if (x.type === 'repeatEndings') text = `Plays bars ${x.from}-${x.to}, then ${x.e1From > x.from ? `${x.from}-${x.e1From - 1} and ` : ''}on to bar ${x.to + 1}${x.e2To > x.to + 1 ? `-${x.e2To}` : ''}.`;
        el.textContent = text;
        el.classList.remove('text-danger');
        return true;
    }
    document.getElementById('outlineExtraForm')?.addEventListener('input', (e) => {
        const key = e.target.dataset.x;
        if (!key || !outlineExtraDraft) return;
        outlineExtraDraft.x[key] = e.target.value;
        outlineExtraCheck();
    });
    document.getElementById('outlineExtraForm')?.addEventListener('click', (e) => {
        const tile = e.target.closest('[data-x-sign]');
        if (!tile || !outlineExtraDraft) return;
        outlineExtraDraft.x.sign = tile.dataset.xSign;
        renderOutlineExtraForm();
        document.querySelector('#outlineExtraForm input[data-x="bar"]')?.focus();
    });
    document.getElementById('outlineExtraForm')?.addEventListener('change', (e) => {
        const key = e.target.dataset.xRadio;
        if (!key || !outlineExtraDraft) return;
        outlineExtraDraft.x[key] = e.target.value;
        renderOutlineExtraForm();
        document.getElementById(e.target.id)?.focus();
    });
    // --- ML-460: a repeat row's endings, in the same pop-up. The table's two boxes do a 1st and a last ending; this
    // is where a different ending for each time through goes (1. 2. 3. ...): where the 1st ending starts, then the
    // bar each ending after it ends at. An emptied box takes its ending out; Done writes the row's boxes.
    function outlineOpenEndings(i) {
        const r = outline.repeatRows[i];
        const ends = [...(r.mids ? r.mids.split(',') : []), r.e2To];
        outlineExtraDraft = { endsRow: i, e1From: r.e1From, ends };
        document.getElementById('outlineExtraTitle').textContent = 'Endings';
        document.getElementById('outlineExtraSaveBtn').textContent = 'Done';
        setShown('outlineExtraRemoveBtn', false);
        renderOutlineEndingsForm();
        showModal('outlineExtraModal');
        document.querySelector('#outlineExtraForm input[type="number"]')?.focus();
    }
    function renderOutlineEndingsForm() {
        const d = outlineExtraDraft;
        const num = (key, value, label) => `<label class="outline-field"><input type="number" inputmode="numeric" data-ends="${key}" value="${escapeHtml(String(value))}" enterkeyhint="next" min="1"><span class="outline-field-label">${escapeHtml(label)}</span></label>`;
        document.getElementById('outlineExtraForm').innerHTML = `
            <div class="outline-pair">${num('e1From', d.e1From, '1st ending starts at bar')}${d.ends.map((v, k) => num(k, v, `${PieceOutline.ordinal(k + 2)} ending ends at bar`)).join('')}</div>
            <button type="button" class="outline-add" data-ends-add>+ Add another ending</button>
            <p class="text-sm text-muted no-margin">The 1st ending ends where the repeat does. To take an ending out, empty its box.</p>`;
        outlineEndingsCheck();
    }
    // The row as it would be with what is typed in the pop-up
    function outlineEndingsRow() {
        const d = outlineExtraDraft, r = outline.repeatRows[d.endsRow];
        const ends = d.ends.filter(v => v !== '');
        const row = { ...r, e1From: d.e1From, e2To: ends.length ? ends[ends.length - 1] : '', mids: ends.slice(0, -1).join(','), e2Auto: '' };
        // as in the table: with only the 1st ending typed, the last is the one bar after the repeat
        if (row.e1From !== '' && row.e2To === '' && r.to !== '' && Number.isInteger(Number(r.to))) { row.e2To = String(Number(r.to) + 1); row.e2Auto = '1'; }
        return row;
    }
    // In plain words which bars each time through plays - or what's wrong
    function outlineEndingsCheck() {
        const el = document.getElementById('outlineExtraCheck');
        const say = (text, bad) => { el.textContent = text; el.classList.toggle('text-danger', !!bad); };
        const t = OUTLINE_ROW_TABLES.repeat, row = outlineEndingsRow();
        if (row.from === '' || row.to === '') return say('Fill in the repeat\'s from bar and to bar in the table first.');
        if (!t.endings(row)) return say('No endings: the same bars each time.');
        if (!t.ready(row)) return say('Which bar does the 1st ending start at?');
        const x = t.extra(row);
        const problem = PieceOutline.extraProblem(outline.o, x);
        if (problem) return say(problem, true);
        const bars = (a, b) => (a === b ? `${a}` : `${a}-${b}`);
        say(PieceOutline.endingsOf(x).map((e, k) => {
            const when = e.passes.length > 1 ? `Times ${e.passes[0]} to ${e.passes[e.passes.length - 1]}` : `Time ${e.passes[0]}`;
            return `${when}: bars ${k ? `${x.e1From > x.from ? `${bars(x.from, x.e1From - 1)}, then ` : ''}${bars(e.from, e.to)}` : bars(x.from, x.to)}.`;
        }).join(' '));
    }
    document.getElementById('outlineExtraForm')?.addEventListener('input', (e) => {
        const key = e.target.dataset.ends;
        if (key === undefined || !outlineExtraDraft || !outlineExtraDraft.ends) return;
        if (key === 'e1From') outlineExtraDraft.e1From = e.target.value;
        else outlineExtraDraft.ends[Number(key)] = e.target.value;
        outlineEndingsCheck();
    });
    document.getElementById('outlineExtraForm')?.addEventListener('click', (e) => {
        if (!e.target.closest('[data-ends-add]') || !outlineExtraDraft || !outlineExtraDraft.ends) return;
        outlineExtraDraft.ends.push('');
        renderOutlineEndingsForm();
        document.querySelector(`#outlineExtraForm input[data-ends="${outlineExtraDraft.ends.length - 1}"]`)?.focus();
    });
    function outlineEndingsDone() {
        const i = outlineExtraDraft.endsRow, t = OUTLINE_ROW_TABLES.repeat, rows = outlineRowsOf(t);
        rows[i] = outlineEndingsRow();
        if (t.started(rows[rows.length - 1])) rows.push(t.blank());
        outlineExtraDraft = null;
        hideModal('outlineExtraModal');
        outlineRerenderKeeping(`[data-xends="${i}"]`);
    }
    document.getElementById('outlineExtraSaveBtn')?.addEventListener('click', () => {
        if (!outlineExtraDraft) return;
        if (outlineExtraDraft.ends) { outlineEndingsDone(); return; }
        const filled = !Object.entries(outlineExtraDraft.x).some(([k, v]) => v === '' && !(outlineExtraDraft.x.type === 'intro' && k === 'to') && !(k === 'bpm' && outlineExtraDraft.x.target !== 'custom'));
        if (!filled) { showWarningToast('Fill in the bar numbers first.'); return; }
        const x = outlineExtraClean();
        if (outlineExtraDraft.index === null) outline.o.extras.push(x);
        else outline.o.extras[outlineExtraDraft.index] = x;
        outline.o.extras.sort((a, b) => (a.from ?? a.bar) - (b.from ?? b.bar));
        outlineExtraDraft = null;
        hideModal('outlineExtraModal');
        renderOutline();
    });
    document.getElementById('outlineExtraRemoveBtn')?.addEventListener('click', () => {
        if (!outlineExtraDraft || outlineExtraDraft.index === null) return;
        outline.o.extras.splice(outlineExtraDraft.index, 1);
        outlineExtraDraft = null;
        hideModal('outlineExtraModal');
        renderOutline();
    });

    // --- Save: the piece, its blocks, its details and its media, in one go - then back where you came from ---
    async function outlineSave(btn) {
        const built = outlineBuild();
        if (built.clashes.length || built.errors.length) { showWarningToast('Fix what is marked before saving.'); return; }
        const target = outline.target;
        const about = outline.about;
        const media = outline.media;
        const payload = built.blocks.map(b => {
            const [type, id] = String(b.sig).split(':');
            return { ...flowBlockPayload(b), timeSignatureId: type === 'public' ? Number(id) : null, accountTimeSignatureId: type === 'public' ? null : Number(id) };
        });
        const say = (text) => { btn.textContent = text; };
        btn.disabled = true;
        say('Saving...');
        let created;
        try {
            created = await API.flows.create({ ...(target && target.bandId ? { bandId: target.bandId } : {}), name: about.title });
            try {
                await API.flows.blocks.replaceAll(created.id, payload);
            } catch (error) {
                await API.flows.delete(created.id).catch(() => { /* left as an empty piece in My music */ });
                throw error;
            }
        } catch (error) {
            btn.disabled = false;
            say('Save the piece');
            showWarningToast("The piece couldn't be saved: " + error.message);
            return;
        }
        // The piece exists from here on: anything below that fails is said at the end, not undone.
        const failed = [];
        const details = {};
        if (about.composer) details.composer = about.composer;
        if (about.arranger) details.arranger = about.arranger;
        if (about.publisher) details.publisher = about.publisher;
        if (about.notes) details.description = about.notes;
        if (Object.keys(details).length) await API.flows.update(created.id, details).catch(() => failed.push('the composer and notes'));
        addPieceTarget = target;
        await addPieceToTargetList(created.id);
        for (const v of media.video) await API.flows.recordings.addYouTube(created.id, { url: v.url, title: v.title }).catch(() => failed.push(v.title || v.url));
        const files = [...media.audio.map(f => ['recordings', f]), ...media.docs.map(f => ['documents', f])];
        for (let i = 0; i < files.length; i++) {
            const [kind, file] = files[i];
            say(`Uploading ${i + 1} of ${files.length}...`);
            try {
                // Straight from this browser to Blob storage, then attached to the piece - as the edit screen's Media tab does
                const blob = await uploadToStore(`flows/${created.id}/${kind}/${file.name}`, file, {
                    access: 'public',
                    handleUploadUrl: `${API_BASE_URL}/api/flows/${created.id}/${kind}/upload-token`,
                    onUploadProgress: (progress) => say(`Uploading ${i + 1} of ${files.length}: ${Math.round(progress.percentage)}%`)
                });
                const uploaded = { blobUrl: blob.url, blobPathname: blob.pathname, fileName: file.name, fileSizeBytes: file.size, mimeType: blob.contentType || file.type };
                if (kind === 'recordings') await API.flows.recordings.addUploaded(created.id, uploaded);
                else await API.flows.documents.add(created.id, uploaded);
            } catch (error) {
                failed.push(file.name);
            }
        }
        const st = outline.stats;
        const counts = PieceOutline.summary(outline.o);
        const totalBars = outline.o.bars;
        // The stopwatch (ML-199): one finished 'create' row, source 'quick', with the steps - the whole piece,
        // since nothing is left to do on the edit screen (ML-428)
        flowStatsRequest(`/api/flows/${created.id}/authoring-sessions`, 'POST', { kind: 'create', creationSource: outline.source === 'photo' ? 'photo' : 'quick', deviceKind: flowStatsDeviceKind(), idleThresholdSeconds: FLOW_STATS_IDLE_THRESHOLD_SECONDS, blockCountStart: 0 })
            .then(row => row && flowStatsRequest(`/api/flows/authoring-sessions/${row.id}`, 'PUT', {
                activeSeconds: st.active, barsActiveSeconds: st.active, elapsedSeconds: Math.round((Date.now() - st.startedAtMs) / 1000),
                blockCountEnd: payload.length, totalBarsEnd: totalBars, blocksAdded: payload.length, blocksEdited: 0, blocksDeleted: 0,
                tapCount: st.taps, keyCount: st.keys, steps: st.steps, outlineCounts: counts, outcome: 'completed'
            }));
        if (outline.read) await outlineReadSaved(created.id, say, failed); // ML-246: the log, and the owner's test copy
        if (failed.length) showWarningToast(`"${about.title}" is saved, but these couldn't be added: ${failed.join(', ')}. Add them from My music.`);
        else showSuccessToast(`"${about.title}" is saved: ${payload.length} blocks. Entered in ${fmtMinSec(st.active)} · ${st.taps} taps · ${st.keys} keys.`);
        outlineClose();
        while (['pieceOutlineView', 'addPieceView'].includes(viewStack[viewStack.length - 1])) viewStack.pop();
        if (target && target.listId !== null && target.listName && isFeatureEnabled('practice_levels')) {
            // ML-403: made for a practice list - My music opens on Practice lists, where the list now has it
            musicTabNext = { screen: 'mymusic', tab: 'lists' };
            switchView('metroBuilderView');
        } else {
            switchView(viewStack[viewStack.length - 1] || 'mainView', true);
        }
        pieceReadOfferNext(); // ML-246: the file held more than one piece
    }

    // ========================================
    // A PIECE FROM A PHOTO OR PDF (ML-246)
    // The third way into Quick entry: photos of the part (or a PDF) are sent to be read - bars, time
    // signatures, speeds, marks, repeats, signs - and Quick entry opens already filled in, with a rating
    // that says how much to check (docs/piece-from-photo.md). The pages go to the file store, are read by
    // the server and deleted there; nothing of them is kept. Every step of Quick entry then shows one
    // button at the top ("Read from your photo: Medium confidence") that opens the list of what to check.
    // Rules for the read and the rating: public/pieceRead.js, run on the server.
    // ========================================
    const PIECE_READ_MAX_FILES = 12; // as MAX_READ_FILES / MAX_READ_BYTES in server/services/pieceReader.js
    const PIECE_READ_MAX_MB = 24;
    const pieceReadBtn = document.getElementById('metroBlkEntryPhotoBtn');
    const pieceReadInput = document.getElementById('pieceReadInput');
    let pieceReadBusy = false;
    let pieceReadMore = null; // the pieces of a read not opened yet (a file can hold several): { read, pieces, target }
    let pieceReadAllowance = null; // asked for while the file chooser is open: { limit, used, left, startsAgainOn }
    const pieceReadDay = (iso) => new Date(`${iso}T12:00:00`).toLocaleDateString('en-GB', { day: 'numeric', month: 'long' });
    // The tile's help line ends with the reads left this quarter, asked for each time Add a piece opens and
    // after each read - for everyone, the owner included (22 Oct 2026). None left: the tile is disabled until
    // they reset. None at all for the account type: the tile isn't shown. No count when the server can't be asked.
    async function pieceReadShowAllowance() {
        if (!pieceReadBtn || pieceReadBusy || !isFeatureEnabled('piece_from_photo') || !isFeatureEnabled('piece_quick_entry')) return;
        const help = pieceReadBtn.querySelector('.metro-help-text');
        if (!help.dataset.base) help.dataset.base = help.textContent;
        const a = await apiCall('/api/piece-read/allowance').catch(() => null);
        if (pieceReadBusy) return;
        if (a && a.limit === 0) { setShown(pieceReadBtn, false); return; }
        pieceReadBtn.disabled = !!a && a.left === 0;
        help.textContent = a
            ? `${help.dataset.base}. ${a.left} of ${a.limit} ${a.limit === 1 ? 'read' : 'reads'} remaining which reset on ${pieceReadDay(a.startsAgainOn)}` // the owner's words
            : help.dataset.base;
    }
    pieceReadBtn?.addEventListener('click', () => {
        if (pieceReadBusy || !isFeatureEnabled('piece_from_photo')) return;
        pieceReadAllowance = apiCall('/api/piece-read/allowance').catch(() => null); // the server refuses anyway
        withUploadRights(() => pieceReadInput.click()); // ML-278
    });
    pieceReadInput?.addEventListener('change', () => {
        const files = [...pieceReadInput.files];
        pieceReadInput.value = '';
        if (files.length) pieceReadStart(files);
    });
    // What stops a choice of files being sent, in words - or null. One PDF, or photos; never both.
    function pieceReadProblem(files) {
        const isPdf = (f) => f.type === 'application/pdf' || /\.pdf$/i.test(f.name);
        const isPhoto = (f) => ['image/jpeg', 'image/png', 'image/webp'].includes(f.type);
        if (files.some(f => !isPdf(f) && !isPhoto(f))) return 'Choose photos (JPEG, PNG or WebP) or a PDF.';
        if (files.some(isPdf) && files.length > 1) return 'Choose one PDF, or photos - not both together.';
        if (files.length > PIECE_READ_MAX_FILES) return `That is more than ${PIECE_READ_MAX_FILES} photos. Send the piece in fewer, or as one PDF.`;
        if (files.reduce((n, f) => n + f.size, 0) > PIECE_READ_MAX_MB * 1024 * 1024) return `Those are more than ${PIECE_READ_MAX_MB} MB together, which is more than can be read in one go.`;
        return null;
    }
    async function pieceReadUpload(files, folder, say) {
        const sent = [];
        for (let i = 0; i < files.length; i++) {
            const ext = (files[i].name.match(/\.[a-z0-9]{2,5}$/i) || [''])[0].toLowerCase();
            const blob = await uploadToStore(`${folder}/${accountProfile.id}/${Date.now()}-${i + 1}${ext}`, files[i], {
                access: 'public',
                handleUploadUrl: `${API_BASE_URL}/api/piece-read/upload-token`,
                onUploadProgress: (progress) => say(`Sending ${files.length > 1 ? `${i + 1} of ${files.length}` : 'it'}: ${Math.round(progress.percentage)}%`)
            });
            sent.push({ blobUrl: blob.url, blobPathname: blob.pathname });
        }
        return sent;
    }
    async function pieceReadStart(files) {
        const problem = pieceReadProblem(files);
        if (problem) { showWarningToast(problem); return; }
        // The allowance (a number of reads a quarter, by account type): said before anything is sent
        const allowance = await pieceReadAllowance;
        if (allowance && allowance.left === 0) {
            showWarningToast(allowance.limit === 0 ? "Reading a piece from a photo isn't included on your account."
                : `You have used this quarter's ${allowance.limit} photo reads. They reset on ${pieceReadDay(allowance.startsAgainOn)}.`);
            return;
        }
        const target = addPieceTakeTarget();
        const help = pieceReadBtn.querySelector('.metro-help-text');
        const was = help.textContent;
        const say = (text) => { help.textContent = text; };
        let ticking = null;
        pieceReadBusy = true;
        pieceReadBtn.disabled = true;
        pieceReadBtn.setAttribute('aria-busy', 'true');
        try {
            if (!accountProfile) accountProfile = await API.account.get();
            const sent = await pieceReadUpload(files, 'piece-read', say);
            // A long part can take a few minutes: the line counts up, so it is plain it hasn't stopped
            const began = Date.now();
            const tick = () => { const s = Math.round((Date.now() - began) / 1000); say(`Reading the music: ${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')} so far`); };
            tick();
            ticking = setInterval(tick, 1000);
            showInfoToast('Reading the music. A short piece takes about a minute, a long one a few - stay on this screen.');
            const result = await apiCall('/api/piece-read', 'POST', { files: sent });
            const read = { id: result.readId, files, kind: files.length === 1 && /pdf/i.test(files[0].type + files[0].name) ? 'PDF' : (files.length > 1 ? 'photos' : 'photo') };
            pieceReadChoose(read, result.pieces, target);
        } catch (error) {
            // Said in a pop-up that stays, not a toast: after minutes of waiting, a message that has gone
            // by the time you look back is the same as nothing happening (owner, 12 Oct 2026)
            showConfirmModal("The music couldn't be read", error.offline ? 'Reading a piece from a photo needs a connection.' : (error.message || 'Something went wrong while it was being read.'),
                () => withUploadRights(() => pieceReadInput.click()), false, 'Choose again', 'Close');
        } finally {
            if (ticking) clearInterval(ticking);
            pieceReadBusy = false;
            pieceReadBtn.disabled = false;
            pieceReadBtn.removeAttribute('aria-busy');
            say(was);
            pieceReadShowAllowance(); // one fewer left
        }
    }
    const pieceReadLevelWord = (level) => ({ high: 'High', medium: 'Medium', low: 'Low' }[level] || 'Medium');
    // One piece: straight into Quick entry. Several (movements, or two pieces on one PDF): which one first -
    // the rest are offered again after each is saved, so the file is only read (and paid for) once.
    // ML-529: the movements of one work also come as one piece in movements (whole) - offered first, the
    // movements one at a time below it.
    function pieceReadChoose(read, pieces, target) {
        if (!pieces.length) return;
        const whole = pieces.find(p => p.whole);
        const parts = pieces.filter(p => !p.whole);
        if (parts.length === 1 && !whole) { pieceReadMore = null; outlineOpenFromRead(target, parts[0], read); return; }
        pieceReadMore = { read, pieces: parts, target };
        const rows = parts.map(p => ({ piece: p, html: addPieceRow(p.about.name || `Piece ${p.index + 1}`, `${whole ? 'This movement as a piece of its own · ' : ''}${p.outline.bars} bars · ${pieceReadLevelWord(p.rating.level)} confidence`) }));
        if (whole) rows.unshift({ piece: whole, html: addPieceRow(`${whole.about.name || 'The whole piece'}, as one piece`, `With its ${whole.movements} movements · ${whole.outline.bars} bars · ${pieceReadLevelWord(whole.rating.level)} confidence`) });
        openFlowChoiceModal(whole ? `${parts.length} movements of one piece were read` : `${parts.length} pieces were read - which one?`, rows, (opt) => {
            if (opt.piece.whole) pieceReadMore = null;
            else pieceReadMore.pieces = pieceReadMore.pieces.filter(p => p !== opt.piece);
            outlineOpenFromRead(target, opt.piece, read);
        });
    }
    // The read as Quick entry's own state. The tables' rows are what Quick entry works from (o.time and the
    // repeat and pause extras are rebuilt from them), so each is filled in as if it had been typed.
    async function outlineOpenFromRead(target, piece, read) {
        outlineClose();
        try { await loadMetroBlkTimeSignatures(); } catch (e) { /* a time signature made for this read shows as "?" until it loads */ }
        await openPieceOutline(target, true);
        if (!outline) return;
        const r = piece.outline, o = outline.o;
        const text = (v) => String(v || '');
        outline.source = 'photo';
        outline.read = { id: read.id, index: piece.index, rating: piece.rating, files: read.files, kind: read.kind, keep: false };
        outline.about = { title: text(piece.about.name), composer: text(piece.about.composer), arranger: text(piece.about.arranger), publisher: text(piece.about.publisher), notes: '' };
        Object.assign(o, {
            bars: r.bars, mainSig: outlineSigInfo(r.mainSig) ? r.mainSig : o.mainSig, mainBpm: r.mainBpm, mainNote: r.mainNote || null, markKind: r.markKind,
            marks: r.marks.map(m => (r.markKind === 'numbers' ? { bar: m.bar } : { bar: m.bar, label: m.label })),
            speeds: r.speeds.map(s => ({ ...s })), movements: (r.movements || []).map(m => ({ ...m })),
            extras: r.extras.filter(x => x.type === 'ramp' || x.type === 'sign').map(x => (x.type === 'ramp' ? { startBeat: 1, ...x } : { ...x }))
        });
        outline.marksText = r.markKind === 'numbers' ? r.marks.map(m => m.bar).join(', ') : '';
        outline.markRows = [...(r.markKind === 'text' ? r.marks.map(m => ({ bar: String(m.bar), label: m.label })) : []), { bar: '', label: '' }];
        outline.speedRows = [...r.speeds.map(s => ({ bar: String(s.bar), bpm: String(s.bpm), noteValue: s.noteValue })), { bar: '', bpm: '', noteValue: undefined }];
        outline.moves = (r.movements || []).length ? { on: true, rows: [...r.movements.map(m => ({ bar: String(m.bar), title: m.title || '' })), { bar: '', title: '' }] } : null;
        const runs = [];
        Object.keys(r.time).map(Number).sort((a, b) => a - b).forEach(bar => {
            const key = r.time[bar], last = runs[runs.length - 1];
            if (last && last.key === key && last.bar + last.bars === bar) last.bars++;
            else runs.push({ bar, key, bars: 1 });
        });
        outline.timeRows = [...runs.filter(x => outlineSigInfo(x.key)).map(x => ({ bar: String(x.bar), sig: outlineSigLabel(x.key), key: x.key, bars: String(x.bars), end: String(x.bar + x.bars - 1) })), outlineTimeBlank()];
        const repeats = OUTLINE_ROW_TABLES.repeat, pauses = OUTLINE_ROW_TABLES.pause;
        outline.repeatRows = [...r.extras.filter(x => x.type === 'repeat' || x.type === 'repeatEndings').map(x => ({ ...repeats.blank(), from: String(x.from), to: String(x.to), times: x.times === 2 ? '' : String(x.times), e1From: x.e1From ? String(x.e1From) : '', e2To: x.e2To ? String(x.e2To) : '' })), repeats.blank()];
        outline.pauseRows = [...r.extras.filter(x => x.type === 'pause').map(x => ({ ...pauses.blank(), bar: String(x.bar), beat: x.beat === 1 ? '' : String(x.beat), kind: x.kind === 'caesura' ? 'caesura' : '' })), pauses.blank()];
        renderOutline();
    }
    // The one button at the top of every step, and the pop-up it opens (one button, one pop-up).
    function outlineReadPanelHtml() {
        const read = outline && outline.read;
        if (!read) return '';
        const n = read.rating.checks.length;
        return `<button type="button" class="outline-extra${read.rating.level === 'low' ? ' has-clash' : ''}" data-outline="readChecks" aria-haspopup="dialog">
            <span class="material-symbols-outlined" aria-hidden="true">photo_camera</span>
            <span class="outline-extra-text"><strong>Read from your ${read.kind}: ${pieceReadLevelWord(read.rating.level)} confidence</strong><span class="text-sm text-muted">${n === 1 ? '1 thing to check - tap to see it' : `${n} things to check - tap to see them`}</span></span>
            <span class="material-symbols-outlined" aria-hidden="true">chevron_right</span></button>`;
    }
    // Which step a check is about, so tapping it goes there
    const OUTLINE_READ_STEP = { time: 'time', 'free-bar': 'time', speed: 'speed', ramp: 'xRamps', number: 'marks', special: 'xRepeats', 'left-out': 'xRepeats' };
    function outlineReadShowChecks() {
        const said = { low: 'Look at this first', medium: 'Worth a look', info: 'For you to decide' };
        openFlowChoiceModal(`${pieceReadLevelWord(outline.read.rating.level)} confidence - what to check`, outline.read.rating.checks.map(c => ({ check: c, html: addPieceRow(c.text, said[c.level] || said.medium) })), (opt) => {
            const key = OUTLINE_READ_STEP[opt.check.kind] || 'howLong';
            const step = OUTLINE_STEPS.findIndex(s => s.key === key);
            if (step > -1 && step !== outline.step) outlineGoStep(step);
        });
    }
    // The owner's test library: a switch on the last step, his alone. On, the pages are kept (sent again, to
    // the tests folder) with the read and the piece as saved, so the read can be done again later.
    function outlineReadKeepHtml() {
        const read = outline && outline.read;
        if (!read || !currentAccountIsSuperAdmin || !read.files || !read.files.length) return '';
        return `<div class="display-toggle-row">
                <span id="outlineReadKeepLabel">Keep this as a test<span class="display-toggle-help">The ${read.kind} is kept so the read can be tried again later. Only you see this.</span></span><label class="toggle-switch"><input type="checkbox" id="outlineReadKeep" aria-labelledby="outlineReadKeepLabel"${read.keep ? ' checked' : ''}><span class="toggle-slider"></span></label>
            </div>`;
    }
    // After Save: the outline as saved goes in the log beside what was read (and the pages, for a test).
    async function outlineReadSaved(flowId, say, failed) {
        const read = outline.read;
        try {
            let testFiles = null;
            if (read.keep && currentAccountIsSuperAdmin) {
                say('Keeping the test...');
                testFiles = await pieceReadUpload(read.files, 'piece-read-tests', say);
            }
            await apiCall(`/api/piece-read/${read.id}/saved`, 'PUT', { index: read.index, flowId, saved: outline.o, ...(testFiles ? { testFiles } : {}) });
        } catch (error) {
            if (read.keep) failed.push('the test copy of the ' + read.kind);
        }
    }
    // A file with more pieces in it: after one is saved, the rest are offered again
    function pieceReadOfferNext() {
        const more = pieceReadMore;
        if (!more || !more.pieces.length) { pieceReadMore = null; return false; }
        openFlowChoiceModal('There is more in that file', [
            ...more.pieces.map(p => ({ piece: p, html: addPieceRow(p.about.name || `Piece ${p.index + 1}`, `${p.outline.bars} bars · ${pieceReadLevelWord(p.rating.level)} confidence`) })),
            { done: true, html: addPieceRow('No more from this file', 'What was read of the others is thrown away') }
        ], (opt) => {
            if (opt.done) { pieceReadMore = null; return; }
            more.pieces = more.pieces.filter(p => p !== opt.piece);
            outlineOpenFromRead(more.target, opt.piece, more.read);
        });
        return true;
    }

    // --- One listener for the whole screen ---
    const outlineView = document.getElementById('pieceOutlineView');
    outlineView?.addEventListener('click', (e) => {
        if (!outline) return;
        const t = e.target.closest('button');
        if (!t) return;
        const o = outline.o;
        if (t.dataset.timePick !== undefined) { outlineTimePick(Number(t.dataset.timePick)); return; }
        if (t.dataset.xkind !== undefined) {
            const row = outline.pauseRows[Number(t.dataset.xkind)];
            const which = t.dataset.xkind;
            openFlowChoiceModal('Pause or break', [['', 'Fermata', 'The note is held', 'fermataAbove'], ['caesura', 'Caesura', 'A silent break', 'caesura']].map(([kind, title, sub, glyph]) => ({ kind, selected: (row.kind === 'caesura' ? 'caesura' : '') === kind, html: `${theoryGlyphs([glyph])}${addPieceRow(title, sub)}` })), (opt) => {
                row.kind = opt.kind; // '' is a pause (held), so an untouched row still counts as blank
                outlineRerenderKeeping(`[data-xkind="${which}"]`);
            });
            return;
        }
        if (t.dataset.xends !== undefined) { outlineOpenEndings(Number(t.dataset.xends)); return; }
        if (t.dataset.outlineExtra !== undefined) { outlineOpenExtra(Number(t.dataset.outlineExtra)); return; }
        if (t.dataset.outlineMediaRemove !== undefined) { outline.media[t.dataset.mediaList].splice(Number(t.dataset.outlineMediaRemove), 1); renderOutline(); return; }
        if (t.dataset.speedNote !== undefined) {
            const i = Number(t.dataset.speedNote);
            outlinePickNote(outlineNoteKey(outlineSpeedRowNote(i)), (note) => { outline.speedRows[i].noteValue = note; outlineRerenderKeeping(`[data-speed-note="${i}"]`); });
            return;
        }
        const action = t.dataset.outline;
        if (action === 'back') {
            // Back just keeps what's typed - nothing is checked until you come forward again
            if (outlineStepKey() === 'howLong') outlineHowLongKeep();
            outlineGoStep(outline.step - 1);
        } else if (action === 'next') {
            outlineLeaveStepWhenReady().then(ok => { if (ok) outlineGoStep(outline.step + 1); });
        } else if (action === 'mainSig') {
            outlineHowLongKeep();
            outlinePickSig(o.mainSig, (value) => { o.mainSig = value; renderOutline(); });
        } else if (action === 'mainBpm') {
            // The bpm is a value box like its neighbours (owner, 4 Oct 2026): the same Tempo pop-up as a block's bpm.
            outlineHowLongKeep();
            flowOpenBpmModal(null, { value: o.mainBpm, typeFirst: true, onApply: (bpm) => { o.mainBpm = Math.min(400, Math.max(20, bpm)); renderOutline(); } });
        } else if (action === 'mainNote') {
            outlineHowLongKeep();
            outlinePickNote(outlineNoteKey(o.mainNote), (note) => { o.mainNote = note; renderOutline(); });
        } else if (action === 'markKind') {
            openFlowChoiceModal('Content of rehearsal marks', OUTLINE_MARK_KINDS.map(k => ({ key: k.key, selected: k.key === o.markKind, html: `<span><strong>${k.label}</strong><br><span class="text-sm text-muted">${k.sub}</span></span>` })), (opt) => { o.markKind = opt.key; renderOutline(); });
        } else if (action === 'addExtra' || action === 'pickFile') {
            outlineAddForStep(OUTLINE_STEPS[outline.step], t.dataset.mediaList);
        } else if (action === 'readChecks') {
            outlineReadShowChecks();
        } else if (action === 'addVideo') {
            outlineAddVideo();
        } else if (action === 'save') {
            outlineSave(t);
        }
    });
    // ML-440: what stops a table is said in words (the note under the table, repeated in the toast) - it used to
    // say "the rows that are marked" when nothing was
    function outlineRowsToast(checkId) {
        const said = (document.getElementById(checkId)?.textContent || '').trim();
        const row = (said.match(/^Rows? [\d, ]*\d/) || [])[0];
        showWarningToast(`${row || 'A row'} can't be used yet - see the note in red.`);
    }
    // A time signature being added (ML-440) is waited for, so Next straight after typing it still goes on
    async function outlineLeaveStepWhenReady() {
        if (outlineSigAdding.size) await Promise.all([...outlineSigAdding.values()]);
        return !!outline && outlineLeaveStep();
    }
    // Leaving a step for a later one (Next, or a dot further on): reads what's typed and says what stops it
    function outlineLeaveStep() {
        const cur = OUTLINE_STEPS[outline.step];
        if (cur.key === 'about' && !outline.about.title.trim()) { showWarningToast('Give the piece a name first.'); document.getElementById('outlineAbout-title')?.focus(); return false; }
        if (cur.key === 'about') Object.keys(outline.about).forEach(k => { outline.about[k] = outline.about[k].trim(); });
        if (cur.table && !outlineRowsRefresh(cur.table)) { outlineRowsToast('outlineRowsCheck'); return false; }
        if (cur.kinds && !cur.table && outlineStepExtras(cur).some(({ i }) => outlineBuild().clashes.find(c => c.extra === i))) { showWarningToast('Fix what is marked before going on.'); return false; }
        if (cur.key === 'howLong' && !outlineHowLongRead()) return false;
        if (cur.key === 'howLong') {
            const bad = outlineMovesApply();
            if (bad.length) { showWarningToast(`A movement starts at a bar of the piece - ${bad.slice(0, 3).join(', ')} isn't one.`); return false; }
            if (outlineMoves().on && PieceOutline.movementsOf(outline.o).length < 2) { showWarningToast('Say where the second movement starts, or switch movements off.'); return false; }
        }
        if (cur.key === 'xIntro') { const problem = outlineIntroApply(); if (problem) { const check = document.getElementById('outlineIntroCheck'); if (check) check.textContent = problem; showWarningToast(problem); return false; } }
        if (cur.key === 'marks') outlineMarksRefresh();
        if (cur.key === 'time' && !outline.o.mainSig) { showWarningToast('Pick the time signature most of it is in.'); return false; }
        if (cur.key === 'time' && !outlineTimeRefresh({ finishing: true })) { outlineRowsToast('outlineTimeCheck'); return false; }
        if (cur.key === 'speed' && !outlineSpeedRefresh()) { outlineRowsToast('outlineSpeedCheck'); return false; }
        // A bar 1 row has done its job (it set the starting speed) - it doesn't stay to undo a later change on step 1
        if (cur.key === 'speed') outline.speedRows = outline.speedRows.filter(r => Number(r.bar) !== 1 || r.bar === '');
        return true;
    }
    // What's typed on step 1 is kept when a pop-up redraws the step
    function outlineHowLongKeep() {
        const bars = Number(document.getElementById('outlineBars')?.value);
        if (Number.isInteger(bars) && bars >= 1 && bars <= PieceOutline.MAX_BARS) outline.o.bars = bars;
    }
    outlineView?.addEventListener('change', (e) => {
        if (!outline) return;
        if (e.target.id === 'outlineReadKeep' && outline.read) outline.read.keep = e.target.checked; // ML-246
        if (e.target.id === 'outlineLeadIn') outline.o.leadIn = e.target.checked;
        if (e.target.id === 'outlineMovesOn') {
            outlineHowLongKeep();
            outlineMoves().on = e.target.checked;
            outlineRerenderKeeping(e.target.checked ? '[data-move-row="1"][data-move-col="bar"]' : '#outlineMovesOn');
        }
        if (e.target.id === 'outlineIntroOn') {
            outlineIntro().on = e.target.checked;
            outlineRerenderKeeping(e.target.checked ? '#outlineIntroFrom' : '#outlineIntroOn');
        }
    });
    // A table's last row filling in adds the next one (the rows already there are left alone, so typing isn't interrupted)
    function outlineGrowTable(rows, blank, rowHtml, tableId) {
        const last = rows[rows.length - 1];
        if (!Object.values(last).some(v => v !== '' && v !== undefined)) return;
        rows.push(blank());
        document.getElementById(tableId)?.insertAdjacentHTML('beforeend', rowHtml(rows[rows.length - 1], rows.length - 1));
    }
    outlineView?.addEventListener('input', (e) => {
        if (!outline) return;
        const t = e.target;
        if (t.dataset.about) { outline.about[t.dataset.about] = t.value; return; }
        if (t.id === 'outlineBars') { outlineHowLongKeep(); return; } // kept as typed, so leaving and coming back doesn't lose it
        if (t.id === 'outlineMarksText') { outline.marksText = t.value; outlineMarksRefresh(); return; }
        if (t.id === 'outlineIntroFrom' || t.id === 'outlineIntroTo') { outlineIntro()[t.id === 'outlineIntroFrom' ? 'from' : 'to'] = t.value; outlineIntroRefresh(); return; }
        if (t.dataset.moveRow !== undefined) {
            outlineMoves().rows[Number(t.dataset.moveRow)][t.dataset.moveCol] = t.value;
            outlineGrowTable(outlineMoves().rows, () => ({ bar: '', title: '' }), outlineMoveRowHtml, 'outlineMoveRows');
            const bad = outlineMovesApply();
            const check = document.getElementById('outlineMovesCheck');
            if (check) check.innerHTML = bad.length ? `<span class="text-danger">Not a bar of this piece: ${escapeHtml(bad.slice(0, 6).join(', '))}</span>` : '';
            return;
        }
        if (t.dataset.markRow !== undefined) {
            outline.markRows[Number(t.dataset.markRow)][t.dataset.markCol] = t.value;
            outlineGrowTable(outline.markRows, () => ({ bar: '', label: '' }), outlineMarkRowHtml, 'outlineMarkRows');
            outlineMarksRefresh();
            return;
        }
        if (t.dataset.xrow !== undefined) {
            const key = t.closest('[data-xtable]').dataset.xtable;
            const table = OUTLINE_ROW_TABLES[key];
            const xrow = outlineRowsOf(table)[Number(t.dataset.xrow)];
            xrow[t.dataset.xcol] = t.value;
            // (a repeat's last ending fills itself in with the bar after the repeat)
            if (table.sync) table.sync(xrow, t.dataset.xcol).forEach(col => { const box = document.querySelector(`#${table.id} [data-xrow="${t.dataset.xrow}"][data-xcol="${col}"]`); if (box) box.value = xrow[col]; });
            // (and a repeat row's Endings button counts them as they are typed)
            const endsBtn = table.endings && document.querySelector(`#${table.id} [data-xends="${t.dataset.xrow}"]`);
            if (endsBtn) { const n = table.endings(xrow); endsBtn.textContent = n; endsBtn.setAttribute('aria-label', outlineEndsLabel(Number(t.dataset.xrow), n)); }
            outlineGrowTable(outlineRowsOf(table), table.blank, outlineTableRowHtml(table), table.id);
            outlineRowsRefresh(key);
            return;
        }
        if (t.dataset.timeRow !== undefined) {
            const row = outline.timeRows[Number(t.dataset.timeRow)];
            // two numbers with anything between them ("17 4", "17.4", "17-4") are written as 17/4 in the box as you type
            const tidy = t.dataset.timeCol === 'sig' && t.value.match(/^\s*(\d{1,2})\D+(\d{1,2})\s*$/);
            if (tidy && t.value !== `${tidy[1]}/${tidy[2]}`) t.value = `${tidy[1]}/${tidy[2]}`;
            row[t.dataset.timeCol] = t.value;
            if (t.dataset.timeCol === 'sig') { row.key = outlineSigFromText(t.value) || ''; if (!row.key) outlineSigAdd(t.value); }
            outlineTimeSync(row, t.dataset.timeCol).forEach(col => { const box = document.querySelector(`#outlineTimeRows [data-time-row="${t.dataset.timeRow}"][data-time-col="${col}"]`); if (box) box.value = row[col]; });
            outlineGrowTable(outline.timeRows, outlineTimeBlank, outlineTimeRowHtml, 'outlineTimeRows');
            outlineTimeRefresh();
            return;
        }
        if (t.dataset.speedRow !== undefined) {
            outline.speedRows[Number(t.dataset.speedRow)][t.dataset.speedCol] = t.value;
            outlineGrowTable(outline.speedRows, () => ({ bar: '', bpm: '', noteValue: undefined }), outlineSpeedRowHtml, 'outlineSpeedRows');
            outlineSpeedRefresh();
        }
    });
    outlineView?.addEventListener('focusin', (e) => {
        const t = e.target;
        if (!outline || t.dataset.timeCol !== 'sig' || t.value || !window.matchMedia('(pointer: coarse)').matches) return;
        t.blur();
        outlineTimePick(Number(t.dataset.timeRow));
    });
    // Enter (Next / Done on a phone's keyboard) always moves on (ML-450):
    //  - in a table, along the row and on to the next row's first box (the buttons in a row are skipped, so typing
    //    isn't interrupted); on the untouched last row there is nothing more to add, so it presses Next;
    //  - anywhere else on a step, to the next thing on it - a box, Notes (ML-446; inside Notes Enter is a new
    //    line), a Yes / No choice or a button - and when nothing comes after, it presses Next.
    // On a button Enter presses the button, as everywhere. The last step's Save is never pressed this way.
    outlineView?.addEventListener('keydown', (e) => {
        const t = e.target;
        if (e.key !== 'Enter' || t.tagName !== 'INPUT' || !outline) return;
        const pressNext = () => document.querySelector('#outlineFoot [data-outline="next"]')?.click();
        const row = t.closest('.outline-row');
        let stops;
        if (row) {
            if (!row.nextElementSibling && [...row.querySelectorAll('input')].every(i => i.value === '')) { e.preventDefault(); pressNext(); return; }
            stops = [...outlineView.querySelectorAll('.outline-row input')];
        } else {
            // a Yes / No pair is one stop: the answer that is picked (or its first), and never the pair you are in
            const group = (el) => [...outlineView.querySelectorAll(`#outlineBody input[type="radio"][name="${el.name}"]`)];
            stops = [...outlineView.querySelectorAll('#outlineBody input:not([type="file"]), #outlineBody textarea, #outlineBody button:not([disabled])')]
                .filter(el => el === t || el.type !== 'radio' || (el.name !== t.name && el === (group(el).find(r => r.checked) || group(el)[0])));
        }
        e.preventDefault();
        const next = stops[stops.indexOf(t) + 1];
        if (!next) { pressNext(); return; }
        next.focus();
        if (next.tagName === 'INPUT' && next.type !== 'radio') next.select?.();
    });
    // In an extra's pop-up Enter moves to the next box, like Tab
    document.getElementById('outlineExtraForm')?.addEventListener('keydown', (e) => {
        if (e.key !== 'Enter' || e.target.tagName !== 'INPUT') return;
        const boxes = [...e.currentTarget.querySelectorAll('input:not([type="radio"]), textarea')];
        const next = boxes[boxes.indexOf(e.target) + 1];
        if (!next) return;
        e.preventDefault();
        next.focus();
        next.select?.();
    });
    document.getElementById('metroBlkEntryQuickBtn')?.addEventListener('click', () => openPieceOutline(addPieceTakeTarget()));

    // ========================================
    // DRILLS (Jira ML-298 Tap tempo, ML-295 Gap trainer, ML-296 Ear - on screen Tempo, Pulse, Pitch)
    // ========================================
    // Three home-screen tools on one engine (public/drills.js: levels, rounds, scoring - the server
    // re-scores every saved round from the same details). Each has a setup screen (level pills, your
    // best, Start), its own play screen, and they share the results screen (drillResultsView). The
    // chosen level is remembered on the device (localStorage tml.drills.<tool>). See docs/drills.md and
    // specs/components/drills.md.
    // On screen they're Tempo, Pulse and Pitch (tool groups, 2026-09-26); the ids stay tapTempo / gapTrainer / ear.
    const DRILL_TITLES = { tapTempo: 'Tempo', gapTrainer: 'Pulse', ear: 'Pitch', rhythm: 'Rhythm' };
    function drillStored(tool) { try { return JSON.parse(localStorage.getItem(`tml.drills.${tool}`) || '{}') || {}; } catch (e) { return {}; } }
    function drillStore(tool, v) { try { localStorage.setItem(`tml.drills.${tool}`, JSON.stringify(v)); } catch (e) { /* per-device convenience only */ } }
    const drillNow = () => performance.now();
    const drillSeed = () => (window.__drillTest && window.__drillTest.seed) || (Date.now() % 2147483647);

    // Option groups as one-tap pills (the Theory options look), each with an optional line under it.
    // ML-406: each option is a value box (the answer over what it is, two to a row - as Theory's options)
    // opening the choice pop-up, where each choice has its explanation under it. A group with `open`
    // brings its own pop-up (Rhythm's rhythm tiles). "One button, one pop-up" - specs/README.md.
    function renderDrillOptions(tool, groups, onChange) {
        const form = document.getElementById(`${tool}Options`);
        const text = (g) => { const c = g.choices && g.choices.find(x => x.value === g.value); return g.valueText || (c ? c.label : ''); };
        form.innerHTML = `<div class="metro-transport-grid metro-transport-grid-2">${groups.map(g => `
            <button type="button" class="metroBlk-ctrl-value-btn" data-drill-opt="${g.key}" aria-haspopup="dialog" aria-label="${escapeHtml(`${g.label}: ${text(g)} - tap to change`)}">
                <strong>${escapeHtml(text(g))}</strong><span class="metroBlk-ctrl-value-label">${escapeHtml((g.caption || g.label).toLowerCase())}</span>
            </button>`).join('')}</div>`;
        groups.forEach(g => form.querySelector(`[data-drill-opt="${g.key}"]`).addEventListener('click', () => {
            if (g.open) { g.open(); return; }
            openFlowChoiceModal(g.label, g.choices.map(c => ({
                value: c.value, selected: c.value === g.value,
                html: `<span><strong>${escapeHtml(c.label)}</strong>${c.desc ? `<br><span class="text-sm text-muted">${escapeHtml(c.desc)}</span>` : ''}</span>${c.value === g.value ? '<span class="material-symbols-outlined" aria-hidden="true">check</span>' : ''}`
            })), (opt) => onChange(g.key, opt.value));
        }));
    }
    // A round's result is a Level 1-5 (the stored grade), as Theory's - the score isn't shown.
    async function renderDrillBest(tool, level, elId, stillCurrent) {
        const el = document.getElementById(elId);
        if (!el) return;
        el.textContent = '';
        try {
            const h = await API.drills.history(tool, level);
            if (stillCurrent && !stillCurrent()) return;
            el.textContent = h.best ? `Your best with these options: Level ${h.best.grade}` : "You haven't tried these options yet.";
        } catch (e) { /* not essential */ }
    }
    // "What I've played" under Start, as Theory's: a row per set of options played, newest first, with
    // its last Level. describe(key) -> { title, detail } (null = no longer offered); a row opens the
    // shared set pop-up (its last rounds, then "Use these options" -> apply(key)). levelOf, when given,
    // says the Level to show for a key (Rhythm: the rhythm's own Level) instead of the last round's.
    const DRILL_PLAYED_ROWS = 5;
    const drillPlayedAll = {};
    async function renderDrillPlayed(tool, { describe, apply, currentKey, levelOf }) {
        const el = document.getElementById(`${tool}Played`);
        if (!el) return;
        let levels = {};
        try { levels = (await API.drills.summary(tool)).levels || {}; } catch (e) { return; }
        const sets = Object.entries(levels).map(([key, v]) => ({ key, ...v, d: describe(key), level: levelOf ? levelOf(key) : v.lastGrade }))
            .filter(x => x.d && x.level >= 1).sort((a, b) => String(b.lastAt).localeCompare(String(a.lastAt)));
        if (!sets.length) { el.innerHTML = ''; return; }
        const shown = drillPlayedAll[tool] ? sets : sets.slice(0, DRILL_PLAYED_ROWS);
        el.innerHTML = `<div class="section-title">What I've played</div>` + shown.map((x, i) => {
            const current = x.key === currentKey;
            return `
            <button type="button" class="history-item clickable theory-quiz-row${current ? ' level-row-selected' : ''}" data-set="${i}"${current ? ' aria-current="true"' : ''} aria-haspopup="dialog">
                <span class="history-details"><strong>${escapeHtml(x.d.title)}</strong>${x.d.detail ? `${escapeHtml(x.d.detail)}<br>` : ''}${theoryCapital(theoryWhen(x.lastAt))} · played ${theoryTimes(x.rounds)}</span>
                ${theoryLevelChip(x.level, `Last Level ${x.level} of 5`)}
            </button>`;
        }).join('') + (sets.length > shown.length ? `<button type="button" class="btn-text" data-more>Show more</button>` : '');
        el.querySelectorAll('[data-set]').forEach(b => b.addEventListener('click', () => openDrillSet(tool, shown[Number(b.dataset.set)], apply, !levelOf)));
        el.querySelector('[data-more]')?.addEventListener('click', () => { drillPlayedAll[tool] = true; renderDrillPlayed(tool, { describe, apply, currentKey, levelOf }); });
    }
    async function openDrillSet(tool, x, apply, withRounds) {
        let recent = [];
        if (withRounds) { try { recent = (await API.drills.history(tool, x.key)).recent || []; } catch (e) { /* the rest still shows */ } }
        theorySetShown = null;
        drillSetApply = () => apply(x.key);
        document.getElementById('theorySetTitle').textContent = x.d.title;
        const sub = document.getElementById('theorySetSub');
        sub.textContent = [x.d.detail, `Played ${theoryTimes(x.rounds)} · last played ${theoryWhen(x.lastAt)}`].filter(Boolean).join(' · ');
        setShown(sub, true);
        document.getElementById('theorySetBody').innerHTML = recent.length
            ? `<div class="section-title">My last rounds</div><div class="theory-level-trend">${theoryLevelBarsHtml(recent, false)}</div>`
            : `<p class="theory-best-line">${theoryLevelChip(x.level, `Level ${x.level} of 5`)}</p>`;
        const use = document.getElementById('theorySetUseBtn');
        use.textContent = 'Use these options';
        use.classList.add('btn-submit');
        use.classList.remove('btn-nav');
        showModal('theorySetModal');
    }
    // ML-406: the Skills list - Theory's list style, a row per tool that's on, with the Level of the last
    // round played in it (or "New"). Rhythm shows the Level of the rhythm played last.
    async function renderSkillsHub() {
        const list = document.getElementById('skillsHubList');
        if (!list) return;
        const tools = skillsHubTools();
        const draw = (last, loaded) => {
            list.innerHTML = tools.map(t => `
            <button type="button" class="history-item clickable theory-quiz-row" data-skill-view="${t.view}">
                <span class="theory-quiz-icon"><span class="material-symbols-outlined" aria-hidden="true">${t.icon}</span></span>
                <span class="history-details"><strong>${escapeHtml(t.title)}</strong>${escapeHtml(t.about)}</span>
                ${last[t.id] ? theoryLevelChip(last[t.id], `Last Level ${last[t.id]} of 5`) : loaded ? '<span class="flow-pill flow-pill-accent">New</span>' : ''}
            </button>`).join('') || '<p class="text-muted">No skills tools are switched on.</p>';
            list.querySelectorAll('[data-skill-view]').forEach(b => b.addEventListener('click', () => switchView(b.dataset.skillView)));
        };
        draw({}, false);
        const last = {};
        await Promise.all(tools.map(async t => {
            try {
                const newest = Object.entries((await API.drills.summary(t.id)).levels || {}).sort((a, b) => String(b[1].lastAt).localeCompare(String(a[1].lastAt)))[0];
                if (!newest) return;
                if (t.id !== 'rhythm') { last[t.id] = newest[1].lastGrade; return; }
                const mine = (await API.rhythm.levels()).patterns || {};
                last[t.id] = (mine[newest[0]] && mine[newest[0]].level) || Math.max(0, ...Object.values(mine).map(m => m.level || 0)) || 0;
            } catch (e) { /* the row still opens the tool */ }
        }));
        if (isShown('skillsHubView')) draw(last, true);
    }
    async function saveDrill(tool, level, startedAt, t0, details) {
        try {
            const saved = await API.drills.save(tool, { level, startedAt, durationMs: Math.round(drillNow() - t0), details });
            if (saved && saved.queued) { showSuccessToast(saved.message); return null; } // ML-220: waiting to sync
            if (saved && saved.result) skillDrillSaved(tool, level, saved.result.grade); // ML-321: grade 4+ passes a skill step
            return saved;
        } catch (e) {
            showWarningToast('Round not saved: ' + e.message);
            return null;
        }
    }
    const drillPadFlash = (pad) => { pad.classList.add('is-hit'); setTimeout(() => pad.classList.remove('is-hit'), 90); };
    // A pad is played on pointerdown (a click fires too late to time a beat by); a click with no pointer
    // behind it (keyboard, switch access, a screen reader) counts too.
    function wireDrillPad(id, onHit) {
        const pad = document.getElementById(id);
        if (!pad) return;
        // a11y: pointerdown is essential here (WCAG 2.5.2 exception) - a tap IS the moment the finger lands,
        // like a drum; timing it on release would make every beat late. Keyboard/AT taps use click below.
        pad.addEventListener('pointerdown', (e) => { if (e.button > 0) return; e.preventDefault(); drillPadFlash(pad); onHit(); });
        pad.addEventListener('click', (e) => { if (e.detail === 0) { drillPadFlash(pad); onHit(); } });
    }

    // --- The shared results screen ---
    let drillLast = null; // { tool, again }
    // ML-406: the result is a Level 1-5 (the stored grade), shown as Theory's five steps with its last
    // rounds as Level bars - no score and no "grade" on screen, and the words stay positive. `level` /
    // `bestText` let a tool say its own (Rhythm: the rhythm's Level, reached by speed); noTrend hides
    // the last rounds where a round has no Level of its own.
    function showDrillResults({ tool, levelLabel, result, saved, stats, rows, again, playView, smart, level, bestText, noTrend }) {
        drillLast = { tool, again };
        // ML-399: smart = { noun, nearly } for a tool SmartLearn works in (Pitch, Tempo) - its box above Again.
        const smartLearn = smart && saved && saved.smartLearn;
        setShown('drillResultSmartBox', !!smartLearn);
        if (smartLearn) document.getElementById('drillResultSmart').textContent = smartLearnMessage(smartLearn, smart.noun, smart.nearly);
        document.getElementById('drillResultsLevel').textContent = `${DRILL_TITLES[tool]} · ${levelLabel}`;
        const lv = level === undefined ? result.grade : level;
        const steps = document.getElementById('drillResultSteps');
        steps.innerHTML = theoryStepsHtml(lv);
        steps.setAttribute('aria-label', lv ? `Level ${lv} of 5` : 'No Level yet');
        const best = document.getElementById('drillResultBest');
        const bestLevel = saved && saved.best ? saved.best.grade : null;
        if (bestText) best.textContent = bestText;
        else if (!saved) best.textContent = `Level ${lv} (not saved)`;
        else if (saved.previousBest === null) best.textContent = `Level ${lv} · your first round with these options`;
        else if (saved.newBest) best.textContent = `Level ${lv} · your best yet with these options`;
        else best.textContent = bestLevel > lv ? `Level ${lv} · your best is Level ${bestLevel}` : `Level ${lv}`;
        document.getElementById('drillResultStats').innerHTML = stats.map(([label, value]) => `<div class="stat-card"><span class="label">${escapeHtml(label)}</span><span class="value">${escapeHtml(String(value))}</span></div>`).join('');
        document.getElementById('drillResultDetail').innerHTML = rows.map(([a, b]) => `<li><span>${escapeHtml(a)}</span><strong>${escapeHtml(b)}</strong></li>`).join('');
        const recent = saved ? saved.recent : [];
        setShown('drillTrendBlock', !noTrend);
        document.getElementById('drillTrend').innerHTML = recent.length ? theoryLevelBarsHtml(recent, true) : '<p class="text-muted">Your rounds with these options will show here.</p>';
        // Results replaces the play screen, so Back (and "Change options") lands on the setup screen.
        if (viewStack[viewStack.length - 1] === playView) viewStack.pop();
        switchView('drillResultsView');
    }
    document.getElementById('drillAgainBtn')?.addEventListener('click', () => {
        if (viewStack[viewStack.length - 1] === 'drillResultsView') viewStack.pop();
        drillLast?.again();
    });
    document.getElementById('drillChangeBtn')?.addEventListener('click', () => goBack());
    // ML-406: two more ways out, as Theory's results - the Skills list, and Home.
    document.getElementById('drillOtherBtn')?.addEventListener('click', () => backToView('skillsHubView'));
    document.getElementById('drillHomeBtn')?.addEventListener('click', () => backToView('mainView'));

    // ---------------------------------------- Tap tempo (ML-298)
    const tapState = (() => {
        const s = drillStored('tapTempo');
        return { level: Drills.TAP.LEVELS.some(l => l.id === s.level) ? s.level : 'listen' };
    })();
    function renderTapTempoSetup() {
        renderDrillOptions('tapTempo', [{ key: 'level', label: 'Help', value: tapState.level, choices: Drills.TAP.LEVELS.map(l => ({ value: l.id, label: l.label, desc: l.desc })) }],
            (k, v) => { tapState.level = v; drillStore('tapTempo', tapState); renderTapTempoSetup(); });
        const lv = tapState.level;
        renderDrillBest('tapTempo', lv, 'tapTempoBest', () => tapState.level === lv);
        renderSmartLearnStrip('tapTempoSmart', 'tapTempoSmartText');
        renderDrillPlayed('tapTempo', {
            currentKey: lv,
            describe: (key) => { const l = Drills.TAP.LEVELS.find(x => x.id === key); return l ? { title: l.label, detail: l.desc } : null; },
            apply: (key) => { tapState.level = key; drillStore('tapTempo', tapState); renderTapTempoSetup(); },
        });
    }
    document.getElementById('tapTempoStartBtn')?.addEventListener('click', () => tapStart());

    // Listen first: one bar of the speed, then silence while you carry on.
    const tapPlayer = createMetronomePlayer();
    tapPlayer.setVisualLatencyMs(metroState.latencyMs);
    let tapCountIn = 0;
    tapPlayer.onBeat(() => {
        if (tapCountIn <= 0) return;
        tapCountIn--;
        if (tapCountIn === 0) { tapPlayer.pause(); tapPlayer.setClickFilter(null); if (tapRound && !tapRound.locked) document.getElementById('tapTempoFeedback').textContent = 'Keep it going'; }
    });
    let tapRound = null;
    async function tapStart(seed) {
        const level = Drills.tapLevel(tapState.level);
        // ML-399 SmartLearn: more of the speed bands you've been off on.
        const weights = drillSmartFor(seed) ? await drillLoadWeights('tapTempo', level.id) : null;
        seed = seed ?? drillSeed();
        tapRound = { level, seed, targets: Drills.tapTargets(level.id, seed, weights), taps: [], i: 0, current: [], locked: false, startedAt: new Date().toISOString(), t0: drillNow() };
        switchView('tapTempoPlayView');
        tapShowTarget();
    }
    function tapStop() {
        tapCountIn = 0;
        if (tapPlayer.isPlaying()) tapPlayer.pause();
        tapPlayer.setClickFilter(null);
        tapRound = null;
    }
    const tapRel = (list) => list.map(x => Math.round((x - list[0]) * 10) / 10);
    const tapTargetText = (t) => (t.band ? t.name : `${t.bpm} bpm`);
    function tapShowTarget() {
        const r = tapRound, t = r.targets[r.i];
        r.current = [];
        r.locked = false;
        document.getElementById('tapTempoStep').textContent = `Speed ${r.i + 1} of ${r.targets.length}`;
        document.getElementById('tapTempoCount').textContent = `0 of ${Drills.TAP.TAPS} taps`;
        document.getElementById('tapTempoAsk').textContent = t.band ? 'Tap anywhere in this speed' : 'Tap at this speed';
        document.getElementById('tapTempoPrompt').innerHTML = t.band
            ? theoryVisual({ type: 'text', text: t.name, bold: true }, t.name, THEORY_PROMPT_SCALE * 1.4)
            : theoryScaleSvg(Notation.tempoMark(t.bpm, { label: `Crotchet equals ${t.bpm}` }), THEORY_PROMPT_SCALE * 1.4);
        setShown('tapTempoMeter', r.level.live);
        document.getElementById('tapTempoNeedle').style.setProperty('--pos', '0');
        document.getElementById('tapTempoFeedback').textContent = '';
        setShown('tapTempoNextBtn', false);
        document.getElementById('tapTempoPad').disabled = false;
        if (r.level.countIn && !t.band) {
            // One bar at the speed; a click filter keeps anything after it silent while it stops.
            tapCountIn = 4;
            tapPlayer.setConductorBpm(t.bpm);
            tapPlayer.setConductorBeatsPerBar(4);
            tapPlayer.setNotesPerBeat(1);
            tapPlayer.setSubdivisionFactor(1);
            tapPlayer.setClickFilter((ci) => ci < 4);
            tapPlayer.resetToBarStart();
            tapPlayer.play();
            document.getElementById('tapTempoFeedback').textContent = 'Listen - join in when you like';
        }
    }
    function tapHit() {
        const r = tapRound;
        if (!r || r.locked) return;
        r.current.push(drillNow());
        const n = r.current.length;
        document.getElementById('tapTempoCount').textContent = `${n} of ${Drills.TAP.TAPS} taps`;
        const t = r.targets[r.i];
        if (r.level.live && !t.band && tapCountIn <= 0) {
            const live = Drills.tapLive(t.bpm, tapRel(r.current));
            if (live) {
                document.getElementById('tapTempoNeedle').style.setProperty('--pos', live.pos.toFixed(3));
                document.getElementById('tapTempoFeedback').textContent = live.verdict === 'on' ? 'On it' : live.verdict === 'slow' ? 'A bit faster' : 'A bit slower';
            }
        }
        if (n >= Drills.TAP.TAPS) tapFinishTarget();
    }
    wireDrillPad('tapTempoPad', tapHit);
    function tapFinishTarget() {
        const r = tapRound, t = r.targets[r.i];
        r.locked = true;
        tapCountIn = 0;
        if (tapPlayer.isPlaying()) tapPlayer.pause();
        r.taps[r.i] = tapRel(r.current);
        const res = Drills.tapScoreOne(t, r.taps[r.i]);
        const bpm = Math.round(res.bpm);
        const verdict = t.band
            ? (res.error === 0 ? `in ${t.name}'s range (${t.min}-${t.max}${t.max === 200 ? '+' : ''})` : `too ${res.direction} for ${t.name} (${t.min}-${t.max}${t.max === 200 ? '+' : ''})`)
            : (res.direction === 'on' ? 'spot on' : `${res.error}% too ${res.direction}`);
        document.getElementById('tapTempoFeedback').textContent = `You tapped ${bpm} bpm - ${verdict}. ${res.points} points.`;
        document.getElementById('tapTempoPad').disabled = true;
        const next = document.getElementById('tapTempoNextBtn');
        next.textContent = r.i === r.targets.length - 1 ? 'See your score' : 'Next speed';
        setShown(next, true);
        next.focus();
    }
    document.getElementById('tapTempoNextBtn')?.addEventListener('click', () => {
        const r = tapRound;
        if (!r) return;
        r.i++;
        if (r.i < r.targets.length) tapShowTarget(); else tapEnd();
    });
    async function tapEnd() {
        const r = tapRound;
        const details = { targets: r.targets.map(t => (t.band ? { band: t.band } : { bpm: t.bpm })), taps: r.taps };
        const local = Drills.tapScoreRound(r.level.id, details);
        const saved = await saveDrill('tapTempo', r.level.id, r.startedAt, r.t0, details);
        const result = saved ? saved.result : local;
        const errs = result.results.filter(x => x.error !== null).map(x => x.error);
        tapStop();
        showDrillResults({
            tool: 'tapTempo', levelLabel: r.level.label, result, saved, playView: 'tapTempoPlayView',
            smart: { noun: 'speed', nearly: 'you were close on' },
            stats: [['Average miss', errs.length ? `${(errs.reduce((a, b) => a + b, 0) / errs.length).toFixed(1)}%` : '-'],
                ['Spot on', `${result.results.filter(x => x.error !== null && x.error <= 2).length} of ${r.targets.length}`], ['Steadiness', errs.length ? `${Math.round(100 - result.results.reduce((a, x) => a + (x.spread || 0), 0) / r.targets.length)}%` : '-']],
            rows: r.targets.map((t, i) => [`${tapTargetText(t)}${t.band ? ` (${t.min}-${t.max}${t.max === 200 ? '+' : ''})` : ''}`, result.results[i].bpm === null ? 'not finished' : `${Math.round(result.results[i].bpm)} bpm`]),
            again: () => tapStart(),
        });
    }

    // ---------------------------------------- Gap trainer (ML-295)
    const gapState = (() => {
        const s = drillStored('gapTrainer');
        return {
            pattern: Drills.GAP.PATTERNS.some(p => p.id === s.pattern) ? s.pattern : 'bars3on1off',
            bpm: Drills.GAP.BPMS.includes(s.bpm) ? s.bpm : Drills.GAP.DEFAULT_BPM,
        };
    })();
    function renderGapTrainerSetup() {
        renderDrillOptions('gapTrainer', [
            { key: 'pattern', label: 'Drill', value: gapState.pattern, choices: Drills.GAP.PATTERNS.map(x => ({ value: x.id, label: x.label, desc: x.desc })) },
            { key: 'bpm', label: 'Speed (bpm)', value: gapState.bpm, choices: Drills.GAP.BPMS.map(b => ({ value: b, label: String(b), desc: TheoryEngine.speedLabel(b) })) },
        ], (k, v) => { gapState[k] = v; drillStore('gapTrainer', gapState); renderGapTrainerSetup(); });
        const pat = gapState.pattern;
        renderDrillBest('gapTrainer', pat, 'gapTrainerBest', () => gapState.pattern === pat);
        renderDrillPlayed('gapTrainer', {
            currentKey: pat,
            describe: (key) => { const x = Drills.GAP.PATTERNS.find(q => q.id === key); return x ? { title: x.label, detail: x.desc } : null; },
            apply: (key) => { gapState.pattern = key; drillStore('gapTrainer', gapState); renderGapTrainerSetup(); },
        });
    }
    document.getElementById('gapTrainerStartBtn')?.addEventListener('click', () => gapStart());

    const gapPlayer = createMetronomePlayer();
    gapPlayer.setVisualLatencyMs(metroState.latencyMs);
    let gapRound = null;
    function gapStart(seed) {
        seed = seed ?? drillSeed();
        const sched = Drills.gapSchedule(gapState.pattern, seed);
        const G = Drills.GAP;
        gapRound = { pattern: Drills.gapPattern(gapState.pattern), bpm: gapState.bpm, seed, sched, taps: [], t0: null, done: false, startedAt: new Date().toISOString(), started: drillNow() };
        switchView('gapTrainerPlayView');
        document.getElementById('gapTrainerBeats').innerHTML = Array.from({ length: G.BARS }, (_, bar) =>
            `<div class="drill-bar">${sched.beats.filter(b => b.bar === bar).map(b => `<span class="drill-beat${b.silent ? ' is-silent' : ''}" data-k="${bar * G.BEATS + b.beat}"></span>`).join('')}</div>`).join('');
        document.getElementById('gapTrainerBar').textContent = 'Get ready';
        document.getElementById('gapTrainerState').textContent = `${gapRound.bpm} bpm`;
        document.getElementById('gapTrainerFeedback').textContent = 'A bar to count you in - tap every beat from bar 1';
        gapPlayer.setConductorBpm(gapRound.bpm);
        gapPlayer.setConductorBeatsPerBar(G.BEATS);
        gapPlayer.setNotesPerBeat(sched.clicksPerBeat);
        gapPlayer.setSubdivisionFactor(1);
        gapPlayer.setClickFilter((ci, perBar) => {
            const bar = Math.floor(ci / perBar) - G.COUNT_IN_BARS;
            return bar < G.BARS && sched.heard(bar, ci % perBar);
        });
        gapPlayer.resetToBarStart();
        gapPlayer.play();
    }
    function gapStop() {
        if (gapPlayer.isPlaying()) gapPlayer.pause();
        gapPlayer.setClickFilter(null);
        gapPlayer.resetToBarStart();
        if (gapRound) gapRound.done = true;
        gapRound = null;
    }
    gapPlayer.onBeat((info) => {
        const r = gapRound;
        if (!r || r.done || info.ended) return;
        const G = Drills.GAP, cpb = r.sched.clicksPerBeat, perBar = G.BEATS * cpb;
        const ci = info.clickIndex;
        if (r.t0 === null) r.t0 = info.time - (ci * 60 / r.bpm / cpb) + G.COUNT_IN_BARS * G.BEATS * 60 / r.bpm;
        const bar = Math.floor(ci / perBar) - G.COUNT_IN_BARS, click = ci % perBar;
        if (bar >= G.BARS) { gapFinish(); return; }
        if (click % cpb) return; // the "and" between beats (Offbeats)
        const beat = click / cpb;
        document.querySelectorAll('#gapTrainerBeats .is-now').forEach(el => el.classList.remove('is-now'));
        if (bar < 0) {
            document.getElementById('gapTrainerBar').textContent = `Count-in ${beat + 1}`;
            return;
        }
        document.querySelector(`#gapTrainerBeats [data-k="${bar * G.BEATS + beat}"]`)?.classList.add('is-now');
        document.getElementById('gapTrainerBar').textContent = `Bar ${bar + 1} of ${G.BARS}`;
        if (beat === 0) document.getElementById('gapTrainerFeedback').textContent = r.sched.silentBars.includes(bar) ? 'Silent - keep going' : '';
    });
    wireDrillPad('gapTrainerPad', () => {
        const r = gapRound;
        if (!r || r.done) return;
        const now = gapPlayer.audioNow();
        if (now !== null) r.taps.push(now);
    });
    document.getElementById('gapTrainerStopBtn')?.addEventListener('click', () => { gapStop(); goBack(); });
    // Taps go in as seconds from bar 1 beat 1, less the output delay set in Settings (a click is heard
    // that much after it's scheduled, and you tap to what you hear).
    function gapTapsRelative(r) {
        const lag = (metroState.latencyMs || 0) / 1000;
        return r.taps.map(t => Math.round((t - r.t0 - lag) * 1000) / 1000).filter(t => t > -5 && t < 120);
    }
    async function gapFinish(tapsOverride) {
        const r = gapRound;
        if (!r || r.done) return;
        r.done = true;
        if (gapPlayer.isPlaying()) gapPlayer.pause();
        gapPlayer.setClickFilter(null);
        gapPlayer.resetToBarStart();
        const details = { bpm: r.bpm, seed: r.seed, taps: tapsOverride || (r.t0 === null ? [] : gapTapsRelative(r)) };
        const local = Drills.gapScoreRound(r.pattern.id, details);
        const saved = await saveDrill('gapTrainer', r.pattern.id, r.startedAt, r.started, details);
        const result = saved ? saved.result : local;
        gapRound = null;
        const ms = (v) => (v === null ? '-' : Math.abs(v) <= result.onTimeMs ? 'on the beat' : `${Math.abs(v)} ms ${v < 0 ? 'early' : 'late'}`);
        showDrillResults({
            tool: 'gapTrainer', levelLabel: `${r.pattern.label} · ${r.bpm} bpm`, result, saved, playView: 'gapTrainerPlayView',
            stats: [['Drift in the gaps', ms(result.drift)], ['Beats tapped', `${result.results.length - result.missed} of ${result.results.length}`]],
            rows: result.landings.length
                ? result.landings.map((v, i) => [`Back in after gap ${i + 1}`, v === null ? 'no tap' : ms(v)])
                : [['Silent beats', `${result.results.filter(x => x.silent).length} of ${result.results.length}`]],
            again: () => gapStart(),
        });
    }

    // ---------------------------------------- Ear (ML-296)
    const earState = (() => {
        const s = drillStored('ear');
        const sets = { reference: 'root5', single: 'naturals', playback: 'naturals', ...(s.sets || {}) };
        Object.keys(sets).forEach(m => { try { Drills.earSet(m, sets[m]); } catch (e) { sets[m] = m === 'reference' ? 'root5' : 'naturals'; } });
        return { mode: Drills.EAR.MODES.some(m => m.id === s.mode) ? s.mode : 'reference', sets };
    })();
    const earSpell = (name) => TheoryEngine.spellName(name, theoryNaming());
    function renderEarSetup() {
        const setId = earState.sets[earState.mode];
        const list = earState.mode === 'reference' ? Drills.EAR.LEVELS : Drills.EAR.NOTE_SETS;
        renderDrillOptions('ear', [
            { key: 'mode', label: 'How', value: earState.mode, choices: Drills.EAR.MODES.map(m => ({ value: m.id, label: m.label, desc: m.desc })) },
            { key: 'set', label: 'Notes', value: setId, choices: list.map(x => ({ value: x.id, label: x.label, desc: x.desc || '' })) },
        ], (k, v) => { if (k === 'mode') earState.mode = v; else earState.sets[earState.mode] = v; drillStore('ear', earState); renderEarSetup(); });
        // Notes are named in written pitch for the tuner's instrument (a B-flat cornet's C sounds B-flat).
        const tr = ((tunerTransposition % 12) + 12) % 12;
        const note = document.getElementById('earTransposeNote');
        setShown(note, tr !== 0);
        note.textContent = tr ? `Notes are named for your ${earSpell(Drills.NAME_OF[(12 - tr) % 12])} instrument (the tuner's setting), so your home note C sounds concert ${earSpell(Drills.NAME_OF[(12 - tr) % 12])}.` : '';
        const key = Drills.earLevelKey(earState.mode, setId);
        renderDrillBest('ear', key, 'earBest', () => Drills.earLevelKey(earState.mode, earState.sets[earState.mode]) === key);
        renderSmartLearnStrip('earSmart', 'earSmartText');
        // A played row's key is "how:notes".
        const parts = (k) => { const i = k.indexOf(':'); return [k.slice(0, i), k.slice(i + 1)]; };
        renderDrillPlayed('ear', {
            currentKey: key,
            describe: (k) => { try { const [m, st] = parts(k); return { title: `${Drills.earMode(m).label} · ${Drills.earSet(m, st).label}`, detail: Drills.earSet(m, st).desc || '' }; } catch (e) { return null; } },
            apply: (k) => { const [m, st] = parts(k); earState.mode = m; earState.sets[m] = st; drillStore('ear', earState); renderEarSetup(); },
        });
    }
    document.getElementById('earStartBtn')?.addEventListener('click', () => earStart());

    // A brass-like note, synthesised: two slightly detuned sawtooths through a low-pass filter that opens
    // on the attack, with a soft start and end.
    let earCtx = null;
    function earAudio() {
        if (!earCtx) { const Ctx = window.AudioContext || window.webkitAudioContext; earCtx = new Ctx(); }
        if (earCtx.state === 'suspended') earCtx.resume();
        return earCtx;
    }
    function earPlayTone(freq, when, dur) {
        const ctx = earAudio();
        const t = ctx.currentTime + when, vol = 0.22;
        const out = ctx.createGain();
        out.gain.setValueAtTime(0.0001, t);
        out.gain.exponentialRampToValueAtTime(vol, t + 0.05);
        out.gain.setValueAtTime(vol, t + dur - 0.15);
        out.gain.exponentialRampToValueAtTime(0.0001, t + dur);
        const lp = ctx.createBiquadFilter();
        lp.type = 'lowpass';
        lp.Q.value = 1;
        lp.frequency.setValueAtTime(freq * 1.5, t);
        lp.frequency.exponentialRampToValueAtTime(freq * 5, t + 0.08);
        lp.frequency.exponentialRampToValueAtTime(freq * 3, t + dur);
        [0, 5].forEach(cents => {
            const o = ctx.createOscillator();
            o.type = 'sawtooth';
            o.frequency.value = freq;
            o.detune.value = cents;
            o.connect(lp);
            o.start(t);
            o.stop(t + dur + 0.05);
        });
        lp.connect(out);
        out.connect(ctx.destination);
    }
    let earRound = null, earTuner = null;
    async function earStart(seed) {
        const mode = earState.mode, setId = earState.sets[mode];
        // ML-399 SmartLearn: the notes you've missed or hesitated on come up more, and (smart) a note
        // you get wrong comes back three notes later.
        const smart = drillSmartFor(seed) && theorySmartLearnOn();
        const weights = smart ? await drillLoadWeights('ear', Drills.earLevelKey(mode, setId)) : null;
        seed = seed ?? drillSeed();
        earRound = {
            mode, setId, smart, key: Drills.earLevelKey(mode, setId), label: `${Drills.earMode(mode).label} · ${Drills.earSet(mode, setId).label}`,
            qs: Drills.earQuestions(mode, setId, seed, weights), i: 0, answers: [], right: 0, transposition: ((tunerTransposition % 12) + 12) % 12,
            startedAt: new Date().toISOString(), t0: drillNow(), locked: false,
        };
        switchView('earPlayView');
        if (mode === 'playback') {
            if (!earTuner) { earTuner = createTunerEngine(); earTuner.onPitch(earOnPitch); }
            const ok = await earTuner.start();
            if (!ok) { showWarningToast('Play it back needs the microphone - allow it and try again.'); earStop(); goBack(); return; }
        }
        earShowQuestion();
    }
    function earStop() {
        if (earRound) clearTimeout(earRound.timer);
        earRound = null;
        if (earTuner && earTuner.isActive()) earTuner.stop();
    }
    function earShowQuestion() {
        const r = earRound;
        if (!r) return;
        const playback = r.mode === 'playback';
        r.locked = false;
        r.stable = 0;
        r.lastPc = null;
        r.replays = 0;        // Play again taps on this note - a hesitation (SmartLearn)
        r.answerFrom = null;  // when the note first finished playing - the answer is timed from there
        document.getElementById('earStep').textContent = `${r.i + 1} of ${r.qs.length}`;
        document.getElementById('earTally').textContent = `${r.right} right`;
        document.getElementById('earAsk').textContent = r.mode === 'reference' ? 'Home note, then the mystery note. Which is it?' : playback ? 'Listen, then play or sing it back' : 'Which note is this?';
        document.getElementById('earPrompt').innerHTML = '<span class="material-symbols-outlined drill-ear-icon" aria-hidden="true">hearing</span>';
        document.getElementById('earFeedback').textContent = '';
        setShown('earNextBtn', false);
        setShown('earSkipBtn', playback);
        setShown('earListen', false);
        document.getElementById('earHeard').textContent = '';
        const answers = document.getElementById('earAnswers');
        if (playback) {
            answers.innerHTML = '';
            answers.className = 'theory-answers hidden-group';
        } else {
            const names = Drills.earAnswers(r.mode, r.setId);
            const layout = names.length === 12 ? 'keyboard' : names.length === 7 ? 'notes' : 'choices';
            const buttons = names.length === 12 ? TheoryEngine.KEYBOARD_BUTTONS : names;
            answers.className = `theory-answers theory-answers-${layout}`;
            answers.innerHTML = buttons.map(n => `<button type="button" class="theory-answer" data-id="${escapeHtml(n)}">${escapeHtml(earSpell(n))}</button>`).join('');
            answers.querySelectorAll('.theory-answer').forEach(b => b.addEventListener('click', () => earAnswer(b.dataset.id)));
        }
        earPlayQuestion();
    }
    function earPlayQuestion() {
        const r = earRound;
        if (!r) return;
        const q = r.qs[r.i];
        const f = (m) => Drills.midiToFreq(Drills.earConcertMidi(m, r.transposition), tunerA4Freq);
        let at = 0.05;
        if (r.mode === 'reference') { earPlayTone(f(Drills.EAR.HOME_MIDI), at, 0.9); at += 1.2; }
        earPlayTone(f(q.midi), at, 1.2);
        if (r.answerFrom === null) r.answerFrom = drillNow() + (at + 1.2) * 1000;
        if (r.mode === 'playback' && !r.locked) {
            // Don't listen to the phone's own note - only once it has finished.
            r.listenFrom = drillNow() + (at + 1.4) * 1000;
            clearTimeout(r.timer);
            r.timer = setTimeout(() => earPlaybackAnswer(null), (at + 1.4) * 1000 + 8000);
            setTimeout(() => { if (earRound === r && !r.locked) { setShown('earListen', true); document.getElementById('earHeard').textContent = ''; } }, (at + 1.4) * 1000);
        }
    }
    document.getElementById('earReplayBtn')?.addEventListener('click', () => { if (earRound && !earRound.locked) earRound.replays++; earPlayQuestion(); });
    document.getElementById('earSkipBtn')?.addEventListener('click', () => earPlaybackAnswer(null));
    const earPitchName = (q) => `${q.name}${Math.floor(q.midi / 12) - 1}`;
    function earReveal(correct, youText) {
        const r = earRound, q = r.qs[r.i];
        r.locked = true;
        clearTimeout(r.timer);
        if (correct) r.right++;
        document.getElementById('earTally').textContent = `${r.right} right`;
        document.getElementById('earPrompt').innerHTML = theoryScaleSvg(Notation.staff({ clef: 'treble', items: [{ type: 'note', pitch: earPitchName(q) }], label: `${earSpell(q.name)} on the treble staff` }), THEORY_PROMPT_SCALE);
        document.getElementById('earFeedback').textContent = correct ? `Yes - ${earSpell(q.name)}` : `It was ${earSpell(q.name)}${youText ? ` - ${youText}` : ''}`;
        setShown('earSkipBtn', false);
        setShown('earListen', false);
        const next = document.getElementById('earNextBtn');
        next.textContent = r.i === r.qs.length - 1 ? 'See your score' : 'Next note';
        setShown(next, true);
    }
    function earMark(id, state) {
        const b = document.querySelector(`#earAnswers .theory-answer[data-id="${CSS.escape(id)}"]`);
        if (!b || b.classList.contains('theory-answer-right')) return;
        b.classList.add(state === 'right' ? 'theory-answer-right' : 'theory-answer-wrong');
        b.insertAdjacentHTML('afterbegin', `<span class="material-symbols-outlined" aria-hidden="true">${state === 'right' ? 'check' : 'close'}</span>`);
    }
    function earAnswer(name) {
        const r = earRound;
        if (!r || r.locked) return;
        const q = r.qs[r.i];
        const pc = ((q.midi % 12) + 12) % 12;
        const correct = Drills.pcOf(name) === pc;
        r.answers.push({ midi: q.midi, answer: name, ms: Math.max(0, Math.round(drillNow() - r.answerFrom)), replays: r.replays });
        if (!correct && r.smart) Drills.earRetry(r.qs, r.i);
        if (!correct) earMark(name, 'wrong');
        // The right button: the note's own spelling, or its other name on the keyboard (C# for Db).
        const rightId = [...document.querySelectorAll('#earAnswers .theory-answer')].map(b => b.dataset.id).find(id => id === q.name) ||
            [...document.querySelectorAll('#earAnswers .theory-answer')].map(b => b.dataset.id).find(id => Drills.pcOf(id) === pc);
        if (correct) earMark(name, 'right'); else if (rightId) earMark(rightId, 'right');
        earReveal(correct);
    }
    function earOnPitch(freq, rms) {
        const r = earRound;
        if (!r || r.mode !== 'playback' || r.locked || drillNow() < (r.listenFrom || Infinity)) return;
        const h = freq > 0 && rms > 0.01 ? Drills.earHeard(freq, r.transposition, tunerA4Freq) : null;
        if (!h) { r.stable = 0; return; }
        const pc = ((h.writtenMidi % 12) + 12) % 12;
        document.getElementById('earHeard').textContent = earSpell(Drills.NAME_OF[pc]);
        if (pc === r.lastPc) r.stable++; else { r.lastPc = pc; r.stable = 1; }
        if (r.stable >= 12) earPlaybackAnswer(h.writtenMidi); // held for about a fifth of a second
    }
    function earPlaybackAnswer(writtenMidi) {
        const r = earRound;
        if (!r || r.locked) return;
        const q = r.qs[r.i];
        r.answers.push({ midi: q.midi, answer: writtenMidi, replays: r.replays });
        const correct = writtenMidi !== null && ((writtenMidi % 12) + 12) % 12 === ((q.midi % 12) + 12) % 12;
        if (!correct && r.smart) Drills.earRetry(r.qs, r.i);
        earReveal(correct, writtenMidi === null ? 'nothing heard' : `you played ${earSpell(Drills.NAME_OF[((writtenMidi % 12) + 12) % 12])}`);
    }
    document.getElementById('earNextBtn')?.addEventListener('click', () => {
        const r = earRound;
        if (!r) return;
        r.i++;
        if (r.i < r.qs.length) earShowQuestion(); else earEnd();
    });
    async function earEnd() {
        const r = earRound;
        if (earTuner && earTuner.isActive()) earTuner.stop();
        const details = { questions: r.answers };
        const local = Drills.earScoreRound(r.key, details);
        const saved = await saveDrill('ear', r.key, r.startedAt, r.t0, details);
        const result = saved ? saved.result : local;
        earRound = null;
        const answerText = (a) => (a.answer === null ? 'nothing heard' : typeof a.answer === 'number' ? earSpell(Drills.NAME_OF[((a.answer % 12) + 12) % 12]) : earSpell(a.answer));
        showDrillResults({
            tool: 'ear', levelLabel: r.label, result, saved, playView: 'earPlayView',
            smart: { noun: 'note', nearly: 'you took a little longer over' },
            stats: [['Right', `${result.right} out of ${r.qs.length}`]],
            rows: r.answers.map((a, i) => [`${i + 1}. ${earSpell(r.qs[i].name)}`, result.results[i].correct ? 'right' : `you: ${answerText(a)}`]),
            again: () => earStart(),
        });
    }

    // Local testing only (localhost): back-tests start rounds with a fixed seed and feed taps directly,
    // since real taps can't be timed from a script. Never present on a deployed site.
    if (['localhost', '127.0.0.1'].includes(window.location.hostname)) {
        window.__drillTest = {
            seed: null,
            tap: {
                start: (level, seed) => { tapState.level = level; tapStart(seed); },
                round: () => tapRound && JSON.parse(JSON.stringify({ targets: tapRound.targets, i: tapRound.i })),
                // taps: ms timestamps for the current speed (replaces the pad)
                feed: (taps) => { const r = tapRound; if (!r || r.locked) return; r.current = []; taps.forEach(ms => { r.current.push(ms); }); document.getElementById('tapTempoCount').textContent = `${r.current.length} of ${Drills.TAP.TAPS} taps`; tapFinishTarget(); },
            },
            gap: {
                start: (pattern, bpm, seed) => { gapState.pattern = pattern; gapState.bpm = bpm; gapStart(seed); },
                schedule: () => gapRound && JSON.parse(JSON.stringify({ silentBars: gapRound.sched.silentBars, beats: gapRound.sched.beats })),
                finish: (taps) => gapFinish(taps),
            },
            ear: {
                start: (mode, set, seed) => { earState.mode = mode; earState.sets[mode] = set; return earStart(seed); },
                question: () => earRound && JSON.parse(JSON.stringify(earRound.qs[earRound.i])),
                round: () => earRound && JSON.parse(JSON.stringify(earRound.qs)), // every note of the round, in order
            },
        };
    }

    // ========================================
    // RANGE (Jira ML-305 / ML-322)
    // ========================================
    // Your comfortable range per instrument (My instruments (☰ menu) -> My range..., or the
    // Range screen's own button) and the Range tool: play the scale to your top note (or down to your
    // bottom one), then hold the next note - the tuner counts the beats (or you say Held it / Not yet),
    // each note beyond your range gets a Level, and at Level 5 it asks to move your range. Rules in
    // public/range.js (PlayRange); saved by server/services/range.js; docs/range.md. Feature range_trainer.
    const RANGE_STORE = 'tml.range'; // per device: { instrumentId, direction, bpm }
    let rangeState = (() => { try { return { direction: 'up', bpm: 60, instrumentId: null, ...(JSON.parse(localStorage.getItem(RANGE_STORE) || '{}') || {}) }; } catch (e) { return { direction: 'up', bpm: 60, instrumentId: null }; } })();
    const rangeStore = () => { try { localStorage.setItem(RANGE_STORE, JSON.stringify(rangeState)); } catch (e) { /* per device only */ } };
    let rangeData = null;       // GET /api/range: your instruments, their ranges and Levels
    let rangeGo = null;         // the go in progress (listening), or null
    let rangePick = null;       // the range picker while it's open
    let rangeTuner = null;      // one microphone engine for both the go and "Measure it"
    const rangePlayer = createMetronomePlayer();
    rangePlayer.setVisualLatencyMs(metroState.latencyMs);
    const RANGE_BPMS = [50, 60, 72];
    const rangeLabel = (p) => (p ? PlayRange.label(p) : '');
    const rangeBeatsText = (b) => `${Math.round(b * 10) / 10} beat${Math.round(b * 10) === 10 ? '' : 's'}`;

    async function rangeLoad() {
        try { rangeData = await API.range.get(); } catch (e) { rangeData = { instruments: [] }; }
        return rangeData;
    }
    // The instruments Range works on (a typical range known), and the one picked (per device, else main).
    const rangeInstruments = () => ((rangeData && rangeData.instruments) || []).filter(i => i.outer);
    function rangeInstrument() {
        const list = rangeInstruments();
        return list.find(i => i.instrumentId === rangeState.instrumentId) || list.find(i => i.isPrimary) || list[0] || null;
    }
    const rangeOf = (inst) => ({ bottom: inst.bottom, top: inst.top });
    const rangeLevelOf = (inst, midi) => inst.levels.find(l => l.midi === midi) || { level: 0, streak: 0, bestBeats: 0, goes: 0 };

    async function renderRangeView() {
        await rangeLoad();
        renderRangeSetup();
    }
    function renderRangeSetup() {
        const list = rangeInstruments(), inst = rangeInstrument();
        const setBtn = document.getElementById('rangeSetBtn');
        if (!inst) {
            renderDrillOptions('range', [], () => {});
            document.getElementById('rangeSummary').textContent = 'Range works on a wind, brass or string instrument. Add the one you play in ☰ → My instruments.';
            setBtn.textContent = 'My instruments';
            setBtn.onclick = () => switchView('accountInstrumentsView');
            setShown('rangeWork', false);
            return;
        }
        const groups = [];
        if (list.length > 1) groups.push({ key: 'instrument', label: 'Instrument', value: inst.instrumentId, choices: list.map(i => ({ value: i.instrumentId, label: i.name })) });
        groups.push({ key: 'direction', label: 'Work on', value: rangeState.direction, choices: [{ value: 'up', label: 'Top notes' }, { value: 'down', label: 'Bottom notes' }] });
        groups.push({ key: 'bpm', label: 'Speed', value: rangeState.bpm, choices: RANGE_BPMS.map(b => ({ value: b, label: `${b} bpm`, desc: 'One beat of the hold is one click' })) });
        renderDrillOptions('range', groups, (key, value) => {
            if (key === 'instrument') rangeState.instrumentId = value; else rangeState[key] = value;
            rangeStore();
            rangeStop();
            renderRangeSetup();
        });
        const set = !PlayRange.checkRange(rangeOf(inst), inst.outer);
        document.getElementById('rangeSummary').textContent = set
            ? `Your comfortable range on ${inst.name}: ${rangeLabel(inst.bottom)} to ${rangeLabel(inst.top)}.`
            : `Set the notes you can play comfortably on ${inst.name} first.`;
        setBtn.textContent = set ? 'Change your range' : 'Set your range';
        setBtn.onclick = () => openRangePicker(inst.instrumentId);
        setShown('rangeWork', set);
        document.getElementById('rangeFeedback').textContent = '';
        if (set) renderRangeWork();
    }
    function renderRangeWork() {
        const inst = rangeInstrument();
        if (!inst) return;
        const dir = rangeState.direction, range = rangeOf(inst);
        const r = PlayRange.run(range, inst.outer, dir);
        const staff = document.getElementById('rangeStaff');
        if (!r) {
            staff.innerHTML = '';
            document.getElementById('rangeTargetLine').textContent = dir === 'up'
                ? `${rangeLabel(inst.top)} is the top of ${inst.name}'s range - nothing higher to work on.`
                : `${rangeLabel(inst.bottom)} is the bottom of ${inst.name}'s range - nothing lower to work on.`;
            ['rangeLevels', 'rangeBeats'].forEach(id => { document.getElementById(id).innerHTML = ''; });
            ['rangeStartBtn', 'rangeHeldBtn', 'rangeNotYetBtn'].forEach(id => { document.getElementById(id).disabled = true; });
            return;
        }
        ['rangeStartBtn', 'rangeHeldBtn', 'rangeNotYetBtn'].forEach(id => { document.getElementById(id).disabled = false; });
        const written = PlayRange.writeRun(r.notes);
        const items = written.map((n, i) => ({ type: 'note', pitch: n.pitch, accidental: n.accidental, cls: i === written.length - 1 ? 'is-now' : null }));
        const edge = dir === 'up' ? inst.top : inst.bottom;
        staff.innerHTML = Notation.staff({ clef: inst.clef, items, noteGap: 1.1, label: `The scale ${dir === 'up' ? 'up' : 'down'} to ${rangeLabel(edge)}, then ${rangeLabel(r.target.pitch)} to hold` });
        const lv = rangeLevelOf(inst, r.target.midi);
        document.getElementById('rangeTargetLine').textContent = lv.level === 5
            ? `${rangeLabel(r.target.pitch)} is at Level 5 - after your next go, it asks to make it your new ${dir === 'up' ? 'top' : 'bottom'} note`
            : lv.goes
            ? `Hold ${rangeLabel(r.target.pitch)}: Level ${lv.level} · best ${rangeBeatsText(lv.bestBeats)} · ${Math.min(lv.streak, PlayRange.IN_A_ROW)} of ${PlayRange.IN_A_ROW} in a row at 8 beats`
            : `Hold ${rangeLabel(r.target.pitch)}: not tried yet`;
        // Every note beyond your range (nearest first, the one you're on marked), each its own Level.
        const beyond = PlayRange.notesBeyond(range, inst.outer, dir).slice(0, 12);
        const strip = document.getElementById('rangeLevels');
        strip.innerHTML = beyond.map((n, i) => `<span class="level-cell lv-${rangeLevelOf(inst, n.midi).level}${i === 0 ? ' is-marked' : ''}"></span>`).join('');
        strip.setAttribute('aria-label', 'Notes beyond your range: ' + beyond.map(n => { const l = rangeLevelOf(inst, n.midi).level; return `${rangeLabel(n.pitch)} ${l ? `Level ${l}` : 'not tried'}`; }).join(', '));
        rangeShowBeats(0);
    }
    // Eight dots, one per beat of the hold that makes a Level 5 go.
    function rangeShowBeats(beats) {
        const el = document.getElementById('rangeBeats');
        el.innerHTML = Array.from({ length: PlayRange.HOLD_BEATS }, (_, i) => `<span class="drill-beat${i < Math.floor(beats) ? ' is-now' : ''}"></span>`).join('');
    }

    // --- A go with the microphone: a bar of clicks, then clicks all the way; play the scale, then hold. ---
    function rangeEnsureTuner() {
        if (!rangeTuner) { rangeTuner = createTunerEngine(); rangeTuner.onPitch(rangeOnPitch); }
        return rangeTuner;
    }
    async function rangeStart() {
        if (rangeGo) { rangeFinish(); return; } // the button is Stop while listening
        const inst = rangeInstrument();
        const r = inst && PlayRange.run(rangeOf(inst), inst.outer, rangeState.direction);
        if (!r) return;
        const ok = await rangeEnsureTuner().start();
        if (!ok) { showWarningToast('Range listens with the microphone - allow it, or use Held it / Not yet.'); return; }
        rangeGo = { inst, direction: rangeState.direction, bpm: rangeState.bpm, target: r.target, tracker: PlayRange.holdTracker(r.target.midi, rangeState.bpm), t0: drillNow(), heard: null };
        rangeGo.timer = setTimeout(() => rangeFinish(), 60000);
        rangePlayer.setConductorBpm(rangeGo.bpm);
        rangePlayer.setConductorBeatsPerBar(4);
        rangePlayer.setNotesPerBeat(1);
        rangePlayer.setSubdivisionFactor(1);
        rangePlayer.setClickFilter(null);
        rangePlayer.resetToBarStart();
        rangePlayer.play();
        document.getElementById('rangeStartBtn').textContent = 'Stop';
        document.getElementById('rangeFeedback').textContent = `Play the scale, then hold ${rangeLabel(r.target.pitch)}`;
        rangeShowBeats(0);
    }
    function rangeOnPitch(freq, rms) {
        const heard = (inst) => (freq > 0 && rms > 0.01 ? PlayRange.heardWritten(freq, inst.writtenToConcert, tunerA4Freq) : null);
        if (rangePick && rangePick.measurer) return rangeMeasureFeed(heard(rangePick.inst));
        const g = rangeGo;
        if (!g || g.done) return;
        const h = heard(g.inst);
        const st = g.tracker.feed(drillNow() - g.t0, h ? h.midi : null);
        rangeShowBeats(st.beats);
        const fb = document.getElementById('rangeFeedback');
        if (st.holding) fb.textContent = `Holding ${rangeLabel(g.target.pitch)}: ${rangeBeatsText(st.beats)}`;
        else if (h && h.midi !== g.heard) { g.heard = h.midi; fb.textContent = `Hearing ${rangeLabel(PlayRange.pitchOf(h.midi, 'usual'))} - hold ${rangeLabel(g.target.pitch)}`; }
        if (st.done) rangeFinish();
    }
    // Stops listening and the clicks (leaving the screen, or Stop) without saving anything.
    function rangeStop() {
        const g = rangeGo;
        if (g) { g.done = true; clearTimeout(g.timer); }
        rangeGo = null;
        if (rangePlayer.isPlaying()) rangePlayer.pause();
        if (rangeTuner && rangeTuner.isActive() && !(rangePick && rangePick.measurer)) rangeTuner.stop();
        const btn = document.getElementById('rangeStartBtn');
        if (btn) btn.textContent = 'Start - listen with the microphone';
    }
    async function rangeFinish() {
        const g = rangeGo;
        if (!g || g.done) return;
        const st = g.tracker.state(drillNow() - g.t0);
        rangeStop();
        if (!(st.beats > 0)) {
            document.getElementById('rangeFeedback').textContent = `I didn't hear ${rangeLabel(g.target.pitch)} - try again, or use Held it / Not yet.`;
            return;
        }
        await rangeSaveGo(g.inst, g.direction, st.beats, g.bpm, 'mic');
    }
    // A go, measured or self-rated: saved (the server works out the Level), then maybe "move your range?".
    async function rangeSaveGo(inst, direction, beats, bpm, method) {
        let out;
        try { out = await API.range.go(inst.instrumentId, { direction, beats, bpm, method }); }
        catch (e) { showWarningToast('Not saved: ' + e.message); return; }
        // ML-220: offline, the go waits to sync - the server works out the Level when it arrives
        if (out.queued) {
            document.getElementById('rangeFeedback').textContent = method === 'self' ? (beats >= PlayRange.HOLD_BEATS ? 'Held' : 'Not yet') + ' - saved on this device' : `Held ${rangeBeatsText(beats)} - saved on this device`;
            rangeShowBeats(beats);
            return;
        }
        const i = inst.levels.findIndex(l => l.midi === out.midi);
        const lv = { midi: out.midi, note: out.note, level: out.level, bestBeats: out.bestBeats, streak: out.streak, goes: out.goes };
        if (i >= 0) inst.levels[i] = lv; else inst.levels.push(lv);
        const inRow = out.streak > 0 && out.level < 5 ? ` · ${out.streak} of ${PlayRange.IN_A_ROW} in a row` : '';
        document.getElementById('rangeFeedback').textContent = method === 'self'
            ? `${rangeLabel(out.note)}: ${beats >= PlayRange.HOLD_BEATS ? 'held' : 'not yet'} - Level ${out.level}${inRow}`
            : `${rangeLabel(out.note)}: held ${rangeBeatsText(beats)} - Level ${out.level}${inRow}`;
        renderRangeWork();
        rangeShowBeats(beats);
        rangeSkillGo(direction, false);
        // Asks on the go that reaches Level 5, and again after any later go if you said Not yet.
        if (out.level === 5) rangeAskToMove(inst, direction, out.note);
    }
    function rangeAskToMove(inst, direction, note) {
        const which = direction === 'up' ? 'top' : 'bottom';
        showConfirmModal('Move your range?',
            `${rangeLabel(note)} is at Level 5 - held for 8 beats three goes in a row. Make it your new ${which} note on ${inst.name}?`,
            async () => {
                try {
                    rangeData = await API.range.move(inst.instrumentId, direction);
                    rangeSkillGo(direction, true);
                    renderRangeSetup();
                    showSuccessToast(`Your ${which} note is now ${rangeLabel(note)}`);
                } catch (e) { showWarningToast('Not moved: ' + e.message); }
            }, false, 'Move it', 'Not yet');
    }
    document.getElementById('rangeStartBtn')?.addEventListener('click', () => rangeStart());
    document.getElementById('rangeHeldBtn')?.addEventListener('click', () => { const inst = rangeInstrument(); if (inst) { rangeStop(); rangeSaveGo(inst, rangeState.direction, PlayRange.SELF_BEATS.held, rangeState.bpm, 'self'); } });
    document.getElementById('rangeNotYetBtn')?.addEventListener('click', () => { const inst = rangeInstrument(); if (inst) { rangeStop(); rangeSaveGo(inst, rangeState.direction, PlayRange.SELF_BEATS.notYet, rangeState.bpm, 'self'); } });

    // --- Skills (ML-321): "Range - top notes" / "Range - bottom notes" on your main instrument. The step
    // is always the note just beyond your range (it moves with your range), so every go counts as
    // practice and moving your range passes the step.
    function rangeSkillSteps(direction) {
        const inst = rangeInstrument();
        if (!inst || PlayRange.checkRange(rangeOf(inst), inst.outer)) return [{ id: 'set', label: 'Set your range' }];
        return PlayRange.notesBeyond(rangeOf(inst), inst.outer, direction).map(n => ({ id: n.pitch, label: `Hold ${rangeLabel(n.pitch)}` }));
    }
    function rangeSkillGo(direction, moved) {
        const s = (skillsData || []).find(x => x.key === `range:${direction}`);
        if (!s || !s.steps.length) return;
        API.skills.result({ key: s.key, stepIndex: 0, passed: moved, grade: null, stepCount: s.steps.length })
            .then(out => { if (!out.queued) applySkillsResponse({ skills: out.skills }); })
            .catch(() => { /* the go itself is saved; the skill's "last practised" can wait */ });
        if (practiceRun && practiceRun.blocks[practiceRun.index] && practiceRun.blocks[practiceRun.index].skill) practiceRun.blocks[practiceRun.index].skillRated = true;
    }

    // --- The range picker: two staves (bottom, top) - tap near a note, then -/+ a semitone - or measure
    // it with the tuner. Used from the Range screen and from My instruments (☰ menu).
    async function openRangePicker(instrumentId, then) {
        if (!rangeData) await rangeLoad();
        const inst = ((rangeData && rangeData.instruments) || []).find(i => i.instrumentId === instrumentId && i.outer);
        if (!inst) { showWarningToast('Range doesn\'t apply to this instrument.'); return; }
        const outer = inst.outer;
        // Not set yet: start on the bottom and top lines of the stave, inside the instrument's range.
        const start = (step) => PlayRange.pitchAtStep(step, inst.clef, outer);
        rangePick = { inst, then, bottom: inst.bottom || start(0), top: inst.top || start(8), measurer: null };
        document.getElementById('rangePickerTitle').textContent = `My range - ${inst.name}`;
        document.getElementById('rangeMeasureStatus').textContent = '';
        document.getElementById('rangeMeasureBtn').textContent = 'Measure it with the tuner';
        renderRangePicker();
        showModal('rangePickerModal');
    }
    // The stave shows the notes the instrument reaches around a normal stave; a note further out still
    // draws (the stave grows) and -/+ reach it.
    const RANGE_PICKER_STEPS = [-6, 14];
    function renderRangePicker() {
        const p = rangePick;
        if (!p) return;
        for (const edge of ['bottom', 'top']) {
            const cap = edge === 'bottom' ? 'Bottom' : 'Top';
            const pitch = p[edge];
            document.getElementById(`range${cap}Stave`).innerHTML = theoryScaleSvg(Notation.staff({ clef: p.inst.clef, items: [{ type: 'note', pitch }], stepRange: RANGE_PICKER_STEPS, minWidth: 12, tappable: true }), 1.4);
            document.getElementById(`range${cap}Stave`).setAttribute('aria-label', `${cap} note: ${rangeLabel(pitch)}. Tap the stave near a note to pick it`);
            document.getElementById(`range${cap}Value`).textContent = rangeLabel(pitch);
        }
        // ML-384: the range bar under the two staves, as See your range draws it, redrawn as the notes move -
        // in the instrument's written pitch, like the staves. The outer limit comes with the instrument.
        const m = (x) => (x ? PlayRange.midiOf(x) : null);
        const o = p.inst.outer;
        const bar = RangeBar.html(p.inst, { low: m(o.low), usualHigh: m(o.usualHigh || o.high), bottom: m(p.bottom), top: m(p.top),
            stretch: m(o.high) - m(o.usualHigh || o.high) });
        document.getElementById('rangePickerBar').innerHTML = bar.html;
        document.getElementById('rangePickerBarText').textContent = bar.text;
    }
    // A tap's height on the stave -> the staff step there -> that natural note (inside the range).
    function rangePickerTap(edge, e) {
        const p = rangePick;
        const svg = e.currentTarget.querySelector('svg');
        if (!p || !svg || e.detail === 0) return; // keyboard "click": -/+ do the picking
        const rect = svg.getBoundingClientRect(), vb = svg.viewBox.baseVal;
        const y = (e.clientY - rect.top) * (vb.height / rect.height);
        const step = Number(svg.dataset.stepHi) - (y - Number(svg.dataset.stepPad)) / (Notation.S / 2);
        p[edge] = PlayRange.pitchAtStep(step, p.inst.clef, p.inst.outer);
        renderRangePicker();
    }
    for (const edge of ['bottom', 'top']) {
        const cap = edge === 'bottom' ? 'Bottom' : 'Top';
        document.getElementById(`range${cap}Stave`)?.addEventListener('click', (e) => rangePickerTap(edge, e));
        document.getElementById(`range${cap}Minus`)?.addEventListener('click', () => { if (rangePick) { rangePick[edge] = PlayRange.stepSemitone(rangePick[edge], -1, rangePick.inst.outer); renderRangePicker(); } });
        document.getElementById(`range${cap}Plus`)?.addEventListener('click', () => { if (rangePick) { rangePick[edge] = PlayRange.stepSemitone(rangePick[edge], 1, rangePick.inst.outer); renderRangePicker(); } });
    }
    // Measure it: play slowly down to your lowest note and up to your highest; each note held steady for
    // a second counts. Stop measuring puts the lowest and highest into the picker (still to save).
    async function rangeMeasureToggle() {
        const p = rangePick;
        if (!p) return;
        const status = document.getElementById('rangeMeasureStatus');
        if (p.measurer) {
            const res = p.measurer.result();
            rangeMeasureEnd();
            if (res.bottom) p.bottom = res.bottom;
            if (res.top && (!res.bottom || res.high > res.low)) p.top = res.top;
            status.textContent = res.bottom ? `Measured: ${rangeLabel(res.bottom)} to ${rangeLabel(res.top)}. Adjust with − and + if you like, then Save.` : 'Nothing held long enough to measure - try again, holding each note for a second.';
            renderRangePicker();
            return;
        }
        rangeStop();
        const ok = await rangeEnsureTuner().start();
        if (!ok) { status.textContent = 'Measuring needs the microphone - allow it and try again, or pick the notes on the staves.'; return; }
        p.measurer = PlayRange.rangeMeasurer(p.inst.outer);
        p.measureT0 = drillNow();
        document.getElementById('rangeMeasureBtn').textContent = 'Stop measuring';
        status.textContent = 'Play slowly down to your lowest comfortable note, then up to your highest - hold each for a second.';
    }
    function rangeMeasureFeed(h) {
        const p = rangePick;
        const res = p.measurer.feed(drillNow() - p.measureT0, h ? h.midi : null);
        const parts = [];
        if (res.now !== null) parts.push(`Hearing ${rangeLabel(PlayRange.pitchOf(res.now, 'usual'))}`);
        if (res.bottom) parts.push(`lowest held ${rangeLabel(res.bottom)}`, `highest held ${rangeLabel(res.top)}`);
        if (parts.length) document.getElementById('rangeMeasureStatus').textContent = parts.join(' · ');
    }
    function rangeMeasureEnd() {
        if (rangePick) rangePick.measurer = null;
        if (rangeTuner && rangeTuner.isActive()) rangeTuner.stop();
        document.getElementById('rangeMeasureBtn').textContent = 'Measure it with the tuner';
    }
    function closeRangePicker() {
        rangeMeasureEnd();
        rangePick = null;
        hideModal('rangePickerModal');
    }
    async function saveRangePicker() {
        const p = rangePick;
        if (!p) return;
        const problem = PlayRange.checkRange({ bottom: p.bottom, top: p.top }, p.inst.outer);
        if (problem) { showWarningToast(problem); return; }
        try {
            rangeData = await API.range.set(p.inst.instrumentId, p.bottom, p.top);
            const mine = myInstruments.find(i => i.id === p.inst.instrumentId);
            if (mine) { mine.bottomNote = p.bottom; mine.topNote = p.top; }
        } catch (e) { showWarningToast('Not saved: ' + e.message); return; }
        const then = p.then;
        closeRangePicker();
        if (isShown('rangeView')) renderRangeSetup();
        if (isShown('accountInstrumentsView')) renderAccountInstruments();
        if (then) then();
    }
    document.getElementById('rangeMeasureBtn')?.addEventListener('click', rangeMeasureToggle);
    document.getElementById('rangePickerSaveBtn')?.addEventListener('click', saveRangePicker);
    document.getElementById('rangePickerCancelBtn')?.addEventListener('click', closeRangePicker);
    document.getElementById('rangePickerCloseBtn')?.addEventListener('click', closeRangePicker);

    // ========================================
    // RHYTHM (Jira ML-306)
    // ========================================
    // Word rhythms and the Takadimi crib sheet: pick one (or play through a set), a bar's count-in, then
    // tap it on the pad (scored strictly) or clap / sing / play it into the microphone (scored leniently).
    // Each rhythm has a speed Level (1-5); a round at a Level's speed with grade 4+ reaches it. Rounds
    // save as drill rounds (tool 'rhythm'), so they share the drill results screen, history and Skills.
    // Rules: public/rhythm.js; docs/rhythm.md. Feature rhythm_trainer.
    const rhythmState = (() => {
        const s = drillStored('rhythm');
        const set = Rhythm.SETS.some(x => x.id === s.set) ? s.set : 'words';
        const pattern = Rhythm.PATTERNS.some(p => p.id === s.pattern && p.set === set) ? s.pattern : Rhythm.patternsIn(set)[0].id;
        return { set, pattern, method: Rhythm.METHODS.includes(s.method) ? s.method : 'tap', bpm: Number(s.bpm) || null };
    })();
    let rhythmMine = {};            // { patternId: { level, word } } from the server
    let rhythmRound = null;
    let rhythmTuner = null;
    const rhythmPlayer = createMetronomePlayer();
    rhythmPlayer.setVisualLatencyMs(metroState.latencyMs);
    const rhythmLevel = (id) => (rhythmMine[id] && rhythmMine[id].level) || 0;
    const rhythmSvg = (items, k) => theoryScaleSvg(Notation.staff({ clef: 'treble', hideClef: true, items, beatWidth: 5 }), k);

    async function renderRhythmView() {
        try { rhythmMine = (await API.rhythm.levels()).patterns || {}; } catch (e) { rhythmMine = {}; }
        renderRhythmSetup();
    }
    const rhythmName = (q) => (rhythmMine[q.id] && rhythmMine[q.id].word) || q.name;
    function renderRhythmSetup() {
        const p = Rhythm.pattern(rhythmState.pattern);
        const bpms = Rhythm.levelBpms(p);
        if (!bpms.includes(rhythmState.bpm)) rhythmState.bpm = Rhythm.nextBpm(p, rhythmLevel(p.id));
        const set = Rhythm.setOf(rhythmState.set);
        renderDrillOptions('rhythm', [
            { key: 'set', label: 'Rhythms', value: rhythmState.set, choices: Rhythm.SETS.map(x => ({ value: x.id, label: x.label, desc: x.desc })) },
            // The rhythm itself is picked from its notation, in a pop-up.
            { key: 'pattern', label: 'Rhythm', valueText: rhythmName(p), open: openRhythmPicker },
            { key: 'method', label: 'How', value: rhythmState.method, choices: [
                { value: 'tap', label: 'Tap', desc: 'Tap the pad on every note. Scored exactly.' },
                { value: 'mic', label: 'Clap, sing or play', desc: 'The microphone listens for each note starting - scored more forgivingly than tapping.' }] },
            { key: 'bpm', label: `Speed (${p.meter === Rhythm.COMPOUND ? 'dotted crotchets' : 'crotchets'} a minute)`, caption: 'speed', value: rhythmState.bpm,
                choices: bpms.map((b, i) => ({ value: b, label: `Level ${i + 1} · ${b}`, desc: `Play it well at this speed to reach Level ${i + 1}` })) },
        ], (k, v) => {
            rhythmState[k] = v;
            if (k === 'set') { rhythmState.pattern = Rhythm.patternsIn(v)[0].id; rhythmState.bpm = null; }
            drillStore('rhythm', rhythmState);
            renderRhythmSetup();
        });
        const lv = rhythmLevel(p.id);
        document.getElementById('rhythmPatternLine').textContent = `${rhythmName(p)}: ${lv ? `Level ${lv}` : 'not tried yet'}${lv < 5 ? ` · next: Level ${lv + 1} at ${bpms[lv]} bpm` : ' · top Level'}`;
        setShown('rhythmWordBtn', p.set !== 'words');
        document.getElementById('rhythmSheetBtn').textContent = `Play through all ${Rhythm.patternsIn(rhythmState.set).length} (${set.label.toLowerCase()})`;
        renderDrillPlayed('rhythm', {
            currentKey: p.id,
            levelOf: (key) => rhythmLevel(key),
            describe: (key) => { try { const q = Rhythm.pattern(key); return { title: rhythmName(q), detail: Rhythm.setOf(q.set).label }; } catch (e) { return null; } },
            apply: (key) => { const q = Rhythm.pattern(key); rhythmState.set = q.set; rhythmState.pattern = q.id; rhythmState.bpm = null; drillStore('rhythm', rhythmState); renderRhythmSetup(); },
        });
    }
    // The set's rhythms in the choice pop-up, each drawn as one beat (or two), with its name and Level.
    function openRhythmPicker() {
        openFlowChoiceModal('Rhythm', [], () => {});
        const box = document.getElementById('flowChoiceOptions');
        box.innerHTML = `<div class="flow-tile-grid flow-tile-grid-3 mb-4" role="group" aria-label="Rhythms">${Rhythm.patternsIn(rhythmState.set).map(q => {
            const lv = rhythmLevel(q.id), on = q.id === rhythmState.pattern;
            const items = Rhythm.barItems({ ...q, meter: { ...q.meter, beats: q.beats } }, { withTimeSig: false, barline: null, words: false });
            return `<button type="button" class="flow-picker-tile${on ? ' selected' : ''}" data-rhythm="${q.id}" aria-pressed="${on}" aria-label="${escapeHtml(rhythmName(q))}, ${lv ? `Level ${lv}` : 'not tried yet'}">
                <span class="flow-picker-tile-icon-row">${rhythmSvg(items, 0.8)}</span>
                <span class="flow-picker-tile-label">${escapeHtml(rhythmName(q))}${lv ? ` · L${lv}` : ''}</span>
            </button>`;
        }).join('')}</div>`;
        box.querySelectorAll('[data-rhythm]').forEach(b => b.addEventListener('click', () => {
            hideModal('flowChoiceModal');
            rhythmState.pattern = b.dataset.rhythm;
            rhythmState.bpm = Rhythm.nextBpm(Rhythm.pattern(b.dataset.rhythm), rhythmLevel(b.dataset.rhythm));
            drillStore('rhythm', rhythmState);
            renderRhythmSetup();
        }));
    }
    // Your own word for a rhythm - a small extra, behind a link (owner, 3 Oct 2026: the point is to play
    // the notes, not the wording).
    document.getElementById('rhythmWordBtn')?.addEventListener('click', () => {
        const id = rhythmState.pattern;
        showPromptModal('My own word for this rhythm', (rhythmMine[id] && rhythmMine[id].word) || '', async (word) => {
            try { rhythmMine = (await API.rhythm.setWord(id, word)).patterns || {}; renderRhythmSetup(); }
            catch (err) { showWarningToast('Not saved: ' + err.message); }
        });
    });

    // --- A round: a bar's count-in, then the bars; the note playing is lit as it goes. ---
    async function rhythmStart(level, seed) {
        const sched = Rhythm.schedule(level);
        const bpm = rhythmState.bpm;
        const method = rhythmState.method;
        rhythmRound = { level, sched, bpm, method, taps: [], t0: null, done: false, startedAt: new Date().toISOString(), started: drillNow(), barShown: -1 };
        switchView('rhythmPlayView');
        setShown('rhythmPad', method === 'tap');
        document.getElementById('rhythmBar').textContent = 'Get ready';
        document.getElementById('rhythmState').textContent = `${bpm} bpm`;
        document.getElementById('rhythmFeedback').textContent = method === 'tap' ? 'A bar to count you in - tap every note from bar 1' : 'A bar to count you in - then clap, sing or play every note';
        rhythmShowBar(0);
        if (method === 'mic') {
            if (!rhythmTuner) {
                rhythmTuner = createTunerEngine();
                rhythmTuner.onPitch((freq, rms) => {
                    const r = rhythmRound;
                    if (!r || r.done || !r.detector) return;
                    const now = rhythmPlayer.audioNow();
                    if (now !== null && r.detector.feed(now, rms) !== null) r.taps.push(now);
                });
            }
            const ok = await rhythmTuner.start(rhythmPlayer.getAudioContext());
            if (!ok) { showWarningToast('Listening needs the microphone - allow it, or choose Tap.'); rhythmStop(); goBack(); return; }
            rhythmRound.detector = Rhythm.onsetDetector();
        }
        rhythmPlayer.setConductorBpm(bpm);
        rhythmPlayer.setConductorBeatsPerBar(sched.meter.beats);
        rhythmPlayer.setNotesPerBeat(1);
        rhythmPlayer.setSubdivisionFactor(1);
        rhythmPlayer.setClickFilter(null);
        rhythmPlayer.resetToBarStart();
        rhythmPlayer.play();
        rhythmTick();
    }
    // One bar on the stave (a single rhythm shows its bar between repeat signs; a whole set shows the
    // bar being played).
    function rhythmShowBar(bar) {
        const r = rhythmRound;
        if (!r || r.barShown === bar) return;
        r.barShown = bar;
        const p = r.sched.bars[Math.min(bar, r.sched.bars.length - 1)];
        const single = !r.level.startsWith('sheet:');
        const items = Rhythm.barItems(p, { clsPrefix: 'rn-', barline: single ? 'repeatRight' : 'barlineSingle' });
        if (single) items.splice(1, 0, { type: 'barline', glyph: 'repeatLeft', gapAfter: 0.8 });
        document.getElementById('rhythmStaff').innerHTML = rhythmSvg(items, 1.2).replace('aria-hidden="true" focusable="false"', `role="img" aria-label="${escapeHtml(p.name)}, one bar"`);
    }
    rhythmPlayer.onBeat((info) => {
        const r = rhythmRound;
        if (!r || r.done || info.ended) return;
        const perBar = r.sched.meter.beats, spb = 60 / r.bpm;
        const ci = info.clickIndex;
        if (r.t0 === null) r.t0 = info.time - ci * spb + Rhythm.ROUND.COUNT_IN_BARS * perBar * spb;
        const bar = Math.floor(ci / perBar) - Rhythm.ROUND.COUNT_IN_BARS;
        if (bar >= r.sched.bars.length) { rhythmFinish(); return; }
        const beat = ci % perBar;
        if (bar < 0) { document.getElementById('rhythmBar').textContent = `Count-in ${beat + 1}`; return; }
        document.getElementById('rhythmBar').textContent = `Bar ${bar + 1} of ${r.sched.bars.length}`;
        if (beat === 0 && bar === 0) document.getElementById('rhythmFeedback').textContent = '';
    });
    // Lights the note playing now (by the audio clock, less the output delay you hear the click with).
    function rhythmTick() {
        const r = rhythmRound;
        if (!r || r.done) return;
        const now = rhythmPlayer.audioNow();
        if (r.t0 !== null && now !== null) {
            const beats = (now - r.t0 - (metroState.latencyMs || 0) / 1000) * r.bpm / 60;
            let cur = null;
            for (const o of r.sched.onsets) { if (o.beat <= beats + 1e-6) cur = o; else break; }
            if (cur && beats < r.sched.totalBeats) {
                rhythmShowBar(cur.bar);
                if (r.lit !== `${cur.bar}:${cur.index}`) {
                    r.lit = `${cur.bar}:${cur.index}`;
                    document.querySelectorAll('#rhythmStaff .is-now').forEach(el => el.classList.remove('is-now'));
                    document.querySelectorAll(`#rhythmStaff .rn-${cur.index}`).forEach(el => el.classList.add('is-now'));
                }
            }
        }
        requestAnimationFrame(rhythmTick);
    }
    wireDrillPad('rhythmPad', () => {
        const r = rhythmRound;
        if (!r || r.done || r.method !== 'tap') return;
        const now = rhythmPlayer.audioNow();
        if (now !== null) r.taps.push(now);
    });
    function rhythmStop() {
        if (rhythmPlayer.isPlaying()) rhythmPlayer.pause();
        rhythmPlayer.resetToBarStart();
        if (rhythmTuner && rhythmTuner.isActive()) rhythmTuner.stop();
        if (rhythmRound) rhythmRound.done = true;
        rhythmRound = null;
    }
    document.getElementById('rhythmStopBtn')?.addEventListener('click', () => { rhythmStop(); goBack(); });
    // Taps (or heard note starts) go in as seconds from bar 1 beat 1, less the output delay set in
    // Settings (you play to the click you hear, that much after it's scheduled).
    function rhythmTapsRelative(r) {
        const lag = (metroState.latencyMs || 0) / 1000;
        return r.taps.map(t => Math.round((t - r.t0 - lag) * 1000) / 1000).filter(t => t > -5 && t < 300);
    }
    async function rhythmFinish(tapsOverride) {
        const r = rhythmRound;
        if (!r || r.done) return;
        r.done = true;
        if (rhythmPlayer.isPlaying()) rhythmPlayer.pause();
        rhythmPlayer.resetToBarStart();
        if (rhythmTuner && rhythmTuner.isActive()) rhythmTuner.stop();
        const details = { bpm: r.bpm, method: r.method, taps: tapsOverride || (r.t0 === null ? [] : rhythmTapsRelative(r)) };
        const local = Rhythm.scoreRound(r.level, details);
        const before = { ...rhythmMine };
        const saved = await saveDrill('rhythm', r.level, r.startedAt, r.started, details);
        const result = saved ? saved.result : local;
        rhythmRound = null;
        // Levels reached this round.
        const ups = ((saved && saved.rhythmLevels) || []).filter(x => x.level > ((before[x.pattern] && before[x.pattern].level) || 0));
        for (const x of (saved && saved.rhythmLevels) || []) rhythmMine[x.pattern] = { ...(rhythmMine[x.pattern] || {}), level: x.level };
        if (ups.length) showSuccessToast(ups.length === 1 ? `${Rhythm.pattern(ups[0].pattern).name}: Level ${ups[0].level}` : `${ups.length} rhythms went up a Level`);
        // Reached the Level you were playing at: next time, the next Level's speed.
        if (ups.some(x => x.pattern === rhythmState.pattern)) { rhythmState.bpm = Rhythm.nextBpm(Rhythm.pattern(rhythmState.pattern), rhythmLevel(rhythmState.pattern)); drillStore('rhythm', rhythmState); }
        const ms = (v) => (v === null ? '-' : Math.abs(v) <= result.onTimeMs ? 'on time' : `${Math.abs(v)} ms ${v < 0 ? 'early' : 'late'}`);
        const sheet = r.level.startsWith('sheet:');
        const label = sheet ? `All ${Rhythm.setOf(r.level.slice(6)).label.toLowerCase()}` : Rhythm.pattern(r.level).name;
        // ML-406: the Level shown is the rhythm's own - the fastest speed it's been played well at (for
        // the whole set, the lowest of its rhythms).
        const ids = sheet ? Rhythm.patternsIn(r.level.slice(6)).map(q => q.id) : [r.level];
        const lvNow = Math.min(...ids.map(rhythmLevel));
        const went = ups.filter(x => ids.includes(x.pattern)).length;
        showDrillResults({
            tool: 'rhythm', levelLabel: `${label} · ${r.bpm} bpm · ${r.method === 'tap' ? 'tapped' : 'listened'}`, result, saved, playView: 'rhythmPlayView',
            level: lvNow, noTrend: true,
            bestText: !saved ? 'Not saved' : sheet ? (went ? `${went} ${went === 1 ? 'rhythm' : 'rhythms'} went up a Level` : 'Keep going - each rhythm goes up a Level when you play it well at this speed')
                : went ? `Level ${lvNow} reached` : lvNow >= 5 ? 'Level 5 - the top Level' : `Level ${lvNow + 1} is next - play it well at its speed to reach it`,
            stats: [['Notes on time', `${result.onTime} out of ${result.results.length}`]],
            rows: sheet
                ? result.perPattern.map(pp => [Rhythm.pattern(pp.pattern).name, rhythmLevel(pp.pattern) ? `Level ${rhythmLevel(pp.pattern)}` : 'not there yet'])
                : [['On average', ms(result.drift)], ...(r.method === 'mic' ? [['Steady delay taken out', `${result.shift} ms`]] : [])],
            again: () => rhythmStart(r.level),
        });
    }
    document.getElementById('rhythmStartBtn')?.addEventListener('click', () => rhythmStart(rhythmState.pattern));
    document.getElementById('rhythmSheetBtn')?.addEventListener('click', () => rhythmStart(`sheet:${rhythmState.set}`));

    // ========================================
    // SPEED NAMES (Jira ML-297)
    // ========================================
    // The Italian speed name under every bpm readout ("Moderato"), from TheoryEngine.speedLabel - the
    // same bands the Theory quiz's Speeds set teaches. A band with two names shows both ("Adagio /
    // Lento"). It watches the number, so no tempo control needs its own code; readouts built later
    // (Quick Play's bar boxes) call attachSpeedNames on their own box.
    function attachSpeedNames(root = document) {
        root.querySelectorAll('.metro-speed-readout').forEach(readout => {
            if (readout.querySelector('.metro-speed-name')) return;
            if (readout.querySelector('.metro-speed-sub')?.textContent.trim() !== 'bpm') return;
            const value = readout.firstElementChild;
            const name = document.createElement('div');
            name.className = 'metro-speed-name';
            readout.appendChild(name);
            const update = () => { name.textContent = TheoryEngine.speedLabel(parseInt(value.textContent, 10)); };
            new MutationObserver(update).observe(value, { childList: true, characterData: true, subtree: true });
            update();
        });
    }
    attachSpeedNames();

    // ========================================
    // SCALES PRACTICE (Jira ML-9, ML-589)
    // ========================================
    // "My scales" (ML-357) is the list: your instrument, clef, direction and grades - the ABRSM scales those
    // grades ask for that you can play. ML-589 (owner, 23 Oct 2026) lays it out as Warm-ups (ML-586): the title opens
    // Choose a scale, one Settings button holds the rest (saved on the account - accounts.scale_prefs, checked by
    // ScaleGrades.cleanPrefs; a copy on the device, 'tml.scales', with the scale you were on), and the bar at the bottom
    // of the screen has Previous / Next scale, or with the metronome Previous / Play / Next: each scale plays once or
    // twice and it carries straight on to the next - or Keep repeating goes round the one scale until you move on.
    // Every scale is drawn at the music size (shared with Warm-ups), as many notes on a line as fit, and the line
    // being played is kept in view. Scales are built and spelled by TheoryEngine.buildScale / writeScale and drawn by
    // Notation.staff. See specs/components/scales.md.
    const SCALES_STORE = 'tml.scales';
    // ML-357: grades (ticked in Grades) + gradeInstrumentId pick the ABRSM list; pattern and tonicOctave
    // (and extended, Grades 7-8's printed top and bottom notes) are how a grade list plays a scale (down to
    // the dominant; which octave it starts in). pool is the old My scales, no longer shown.
    const SCALES_DEFAULTS = { keyId: 'C major', form: 'major', minorForm: 'harmonic', type: 'scale', octaves: 1, clef: 'treble',
        ...ScaleGrades.PREF_DEFAULTS, grades: ScaleGrades.PREF_DEFAULTS.grades.slice(),
        pattern: null, tonicOctave: null, extended: null,
        pool: { maxSharps: 3, maxFlats: 3, forms: ['major', 'harmonic'], types: ['scale'] } };
    const SCALES_BEATS_PER_BAR = 4;
    const SCALES_BPM_MAX = 200;
    const SCALES_NPB = [[1, 'crotchets'], [2, 'quavers'], [3, 'triplets'], [4, 'semiquavers']];
    const SCALES_DIRECTIONS = { up: ['arrow_upward', 'up'], down: ['arrow_downward', 'down'], both: ['swap_vert', 'up & down'], downUp: ['swap_vert', 'down & up'] };
    // The arrows read left to right in the order you play: up & down is up-arrow first; down & up is the same icon flipped (.scales-dir-flip).
    const scalesDirIconHtml = (v) => `<span class="material-symbols-outlined${v === 'downUp' ? ' scales-dir-flip' : ''}" aria-hidden="true">${(SCALES_DIRECTIONS[v] || SCALES_DIRECTIONS.both)[0]}</span>`;
    const SCALES_TYPES = [['scale', 'Scale'], ['arpeggio', 'Arpeggio'], ['chromatic', 'Chromatic'], ['dom7', 'Dominant 7th'], ['thirds', 'Scale in thirds'], ['wholetone', 'Whole-tone scale'], ['dim7', 'Diminished 7th']];
    // Kinds named by their starting note or key ("Diminished 7th on G♯") rather than "<key> <form> <kind>"
    const SCALES_NAMED_WHOLE = ['dom7', 'chromatic', 'wholetone', 'dim7'];
    // Detail (ML-357): how much of the scale to show while you play
    const SCALES_DETAILS = [['notes', 'Notes', 'name, key and notes'], ['key', 'Key', 'just name and key'], ['name', 'Name', 'just the name']];
    const SCALES_CLEFS = [['treble', 'Treble'], ['bass', 'Bass'], ['tenor', 'Tenor']];
    // ML-589: play each one - once or twice then on to the next scale, or keep repeating this one (owner)
    const SCALES_TIMES = [[1, 'Once', '1×'], [2, 'Twice', '2×'], [0, 'Keep repeating', '<span class="material-symbols-outlined" aria-hidden="true">repeat</span>']];
    const scalesTypeName = (t) => (SCALES_TYPES.find(([v]) => v === t) || SCALES_TYPES[0])[1];
    const scalesLength = () => ScaleGrades.lengthLabel(scales.octaves, scales.pattern);
    const scalesClone = (o) => ({ ...o, grades: [...(o.grades || [1])], pool: { ...o.pool, forms: [...o.pool.forms], types: [...o.pool.types] } });
    let scales = (() => {
        try {
            const saved = JSON.parse(localStorage.getItem(SCALES_STORE) || 'null');
            // ML-357: "From memory" became Detail - Name
            if (saved && saved.memory && !saved.detail) saved.detail = 'name';
            if (saved) return scalesClone({ ...SCALES_DEFAULTS, ...saved, pool: { ...SCALES_DEFAULTS.pool, ...(saved.pool || {}) } });
        } catch (e) { /* unreadable - start from the defaults */ }
        return scalesClone(SCALES_DEFAULTS);
    })();
    if (!TheoryEngine.ALL_KEYS.some(k => k.id === scales.keyId)) scales.keyId = SCALES_DEFAULTS.keyId;
    // ML-528: Scales starts in the clef you read your instrument in (My instruments), each time you come to
    // it. The Clef button still changes it - for this visit; it is no longer a setting of this device.
    let scalesClefPicked = false;
    function scalesUseMyClef() {
        if (scalesClefPicked || scalesLadder) return;
        const inst = scalesGradeInstrument();
        const clef = inst && SCALES_CLEFS.some(([v]) => v === inst.theoryClef) ? inst.theoryClef : null;
        if (!clef || clef === scales.clef) return;
        scales.clef = clef;
        scales.tonicOctave = null;
        scalesSave();
    }
    function scalesSave() {
        if (scalesLadder) return; // ML-391: a Scales block borrows the settings - yours come back after it
        try { localStorage.setItem(SCALES_STORE, JSON.stringify(scales)); } catch (e) { /* private browsing - still works for this visit */ }
    }
    // ML-589: the account's copy - read once a visit; the first time (nothing saved yet) this device's settings go to it.
    const scalesPrefsOf = () => Object.fromEntries(Object.keys(ScaleGrades.PREF_DEFAULTS).map(k => [k, scales[k]]));
    let scalesPrefsRead = false, scalesPrefsTimer = null;
    async function scalesLoadPrefs() {
        if (scalesPrefsRead) return;
        try {
            const { prefs } = await apiCall('/api/account/scales');
            scalesPrefsRead = true;
            if (!prefs || !Object.keys(prefs).length) { scalesSavePrefs(); return; }
            // A Scales block that has just started borrows the settings: yours go to what comes back after it
            if (scalesLadder) { scalesLadder.saved = JSON.stringify({ ...JSON.parse(scalesLadder.saved), ...ScaleGrades.cleanPrefs(prefs) }); return; }
            Object.assign(scales, ScaleGrades.cleanPrefs(prefs));
            scalesPlayer.setVolume(scales.volume / 100);
            scalesSave();
        } catch (e) { /* offline, or an old value: this device's copy stands */ }
    }
    function scalesSavePrefs() {
        scalesSave();
        if (scalesLadder) return;
        clearTimeout(scalesPrefsTimer);
        try { const clean = ScaleGrades.cleanPrefs(scalesPrefsOf()); scalesPrefsTimer = setTimeout(() => { apiCall('/api/account/scales', 'PUT', { prefs: clean }).catch(() => { /* kept on this device - the next change sends them again */ }); }, 600); }
        catch (e) { /* an old device value the account won't take - it stays on this device */ }
    }
    // What is changed, counted (anonymous - analytics.js), as Warm-ups'
    function scalesTrack(setting, value) {
        try { window.posthog?.capture?.('scales setting', { setting, value }); } catch (e) { /* counting is never in the way */ }
    }
    function scalesSetPref(key, value) {
        scales[key] = value;
        scalesSavePrefs();
        scalesTrack(key, value);
    }
    const scalesMode = () => (scales.keyId.endsWith(' minor') ? 'minor' : 'major');
    const scalesTonic = () => scales.keyId.split(' ')[0];
    const scalesName = (tonic) => TheoryEngine.spellName(tonic, theoryNaming());
    let scalesWritten = null; // { scale, notes, barLength } - what's on the stave now
    // With the metronome, every scale plays in a Scales block (ML-391); on its own it's the switch in Settings.
    const scalesMetronomeOn = () => !!scalesLadder || scales.metronome !== false;
    // One scale going round until you move on: Keep repeating, a Scales block (you answer Got it / Not yet), or a
    // Skills step (it's practising that one scale).
    const scalesKeepsOne = () => !!scalesLadder || (skillContext && skillContext.tool === 'scales') || scales.times === 0;

    // --- The list: your scales in grid order, or shuffled once a visit (ML-589); a Scales block's are its own ---
    let scalesShuffled = null, scalesPoolCache = null;
    function scalesList() {
        const pool = scalesPoolCache || (scalesPoolCache = scalesGradeGrid().pool);
        if (!scales.shuffle) return pool;
        const key = pool.map(PracticePlan.scaleKey).join();
        if (!scalesShuffled || scalesShuffled.key !== key) {
            const order = pool.slice();
            for (let i = order.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
            scalesShuffled = { key, order };
        }
        return scalesShuffled.order;
    }
    const scalesPickSame = (a, b) => !!a && !!b && a.keyId === b.keyId && a.form === b.form && a.type === b.type && a.octaves === b.octaves && (a.pattern || null) === (b.pattern || null);
    const scalesCurrentPick = () => ({ keyId: scales.keyId, form: scales.form, type: scales.type, octaves: scales.octaves, pattern: scales.pattern, tonicOctave: scales.tonicOctave, extended: scales.extended });
    // The scale on screen's place in the list (-1: not in it - a Skills step, or the list changed)
    function scalesListPos() {
        const list = scalesLadder ? [] : scalesList();
        return { list, i: list.findIndex(scalesSame) };
    }

    // --- The stave: every scale at the music size (Warm-ups' setting, shared - ML-589) ---
    // The notes are cut into lines at the beat groups the old rows used (4 notes, 3 at 3 a beat), as many groups on
    // a line as fit the width, the lines evened out (as Warmups.fitRows); all but the last are spread to the full
    // width when they're over half way there. A group too wide on its own shrinks to fit.
    function scalesFitGroups(units, width, measure) {
        const pack = (w) => {
            const groups = [];
            let done = 0;
            while (done < units) {
                let n = 1;
                while (done + n < units && measure(done, done + n + 1) <= w) n++;
                groups.push(n);
                done += n;
            }
            return groups;
        };
        let best = pack(width);
        let lo = width / 2, hi = width;
        for (let k = 0; k < 8 && best.length > 1; k++) {
            const mid = (lo + hi) / 2, g = pack(mid);
            if (g.length <= best.length) { best = g; hi = mid; } else lo = mid;
        }
        return best;
    }
    function renderScales() {
        const scale = TheoryEngine.buildScale(scales);
        const barLength = SCALES_BEATS_PER_BAR * scales.npb;
        const notes = TheoryEngine.writeScale(scale, barLength);
        scalesWritten = { scale, notes, barLength };
        scalesPoolCache = null;
        // Settings' boxes that a Scales block's Level changes, kept current
        document.getElementById('scalesNpbVal').textContent = scales.npb;
        document.getElementById('scalesDetailBtnVal').textContent = (SCALES_DETAILS.find(([v]) => v === scales.detail) || SCALES_DETAILS[0])[1];

        const minor = scalesMode() === 'minor';
        document.getElementById('scalesTitle').textContent = SCALES_NAMED_WHOLE.includes(scales.type) ? scale.title : scale.title.replace(/^\S+/, scalesName(scalesTonic()));
        scalesShowSub();
        renderScalesLadder(); // ML-391
        const detail = SCALES_DETAILS.some(([v]) => v === scales.detail) ? scales.detail : 'notes';
        // Detail: Name is the name only ("B♭ minor" / "harmonic · scale · 2 octaves · up & down") in place of
        // the stave; Key is a blank stave with the key signature; Notes is the scale written out.
        setShown('scalesStaff', detail !== 'name');
        setShown('scalesMemory', detail === 'name');
        document.getElementById('scalesMemoryName').textContent = SCALES_NAMED_WHOLE.includes(scales.type) ? scale.title : `${scalesName(scalesTonic())} ${scalesMode()}`;
        // "harmonic · scale · 2 octaves · up & down" - a named-whole kind has its name already; a fixed shape (a dominant 7th, in thirds, down to the dominant, extended range) no direction
        document.getElementById('scalesMemoryDetail').textContent = [minor && scales.type === 'scale' ? scale.form : null, SCALES_NAMED_WHOLE.includes(scales.type) ? null : scalesTypeName(scales.type).toLowerCase(), scalesLength(), scale.pattern || ['dom7', 'thirds'].includes(scales.type) ? null : SCALES_DIRECTIONS[scales.direction][1]].filter(Boolean).join(' · ');

        const staff = document.getElementById('scalesStaff');
        const sizeScale = WARMUPS_SIZE_SCALE[warmups.size] || WARMUPS_SIZE_SCALE.medium;
        const width = (staff.clientWidth || 320) / sizeScale; // in staff units
        const atSize = (svg) => svg.replace(/ width="([\d.]+)" height="([\d.]+)"/, (m, w, h) => ` width="${(w * sizeScale).toFixed(1)}" height="${(h * sizeScale).toFixed(1)}"`);
        if (detail === 'key') {
            // A stave with just the clef and key signature - the name says what to play, you find the notes.
            staff.innerHTML = `<div class="warmups-row">${atSize(Notation.staff({ clef: scales.clef, keySignature: scale.keySignature || undefined, items: [], minWidth: 48, label: `${scale.title}: the key signature only` }))}</div>`;
            scalesLitRow = null;
            scalesLight(scalesLitIndex);
            renderScalesDock();
            return;
        }
        const steps = notes.map(n => Notation.staffStep(n.pitch, scales.clef));
        // ML-386: a last bar that isn't full is made up with rests, one per missing note (the notes are drawn
        // as crotchets), so every bar has the right count - in 4/4 a missing 3rd and 4th beat is one minim
        // rest, as it's engraved. Each rest carries the note-slot classes it covers, so it lights up as the
        // metronome plays through it.
        const restSlots = (barLength - (notes.length % barLength)) % barLength;
        const rests = [];
        for (let s = 0; s < restSlots;) {
            const idx = notes.length + s;
            const beatInBar = idx % barLength;
            const minim = scales.npb === 1 && beatInBar % 2 === 0 && restSlots - s >= 2;
            const w = minim ? 2 : 1;
            rests.push({ type: 'mark', glyph: minim ? 'restHalf' : 'restQuarter', step: 4,
                cls: `scales-note scales-rest ${Array.from({ length: w }, (_, k) => `scales-note-${idx + k}`).join(' ')}` });
            s += w;
        }
        const stepRange = [Math.min(-3, ...steps) - 1, Math.max(10, ...steps) + 1];
        // A line of notes from..to-1: 4/4 on the first when it's one note a beat, bar lines every 4 beats, the
        // rests and a final bar line on the last. Stems go down from the middle line up.
        const rowOf = (from, to) => {
            const items = [];
            if (from === 0 && scales.npb === 1) items.push({ type: 'timeSig', top: 4, bottom: 4 });
            notes.slice(from, to).forEach((n, j) => {
                const idx = from + j;
                items.push({ type: 'note', pitch: n.pitch, accidental: n.accidental, head: steps[idx] >= 4 ? 'noteQuarterDown' : 'noteQuarterUp', cls: `scales-note scales-note-${idx}` });
                if (idx === notes.length - 1) items.push(...rests, { type: 'barline', glyph: 'barlineFinal' });
                else if ((idx + 1) % barLength === 0) items.push({ type: 'barline', glyph: 'barlineSingle' });
            });
            return { items, from, to, last: to >= notes.length };
        };
        const opts = (r, extra) => ({ clef: scales.clef, keySignature: scale.keySignature || undefined, items: r.items, stepRange, noteGap: 2, label: `${scale.title}, notes ${r.from + 1} to ${r.to}`, ...extra });
        const naturalWidth = (svg) => parseFloat(/width="([\d.]+)"/.exec(svg)[1]);
        const unit = scales.npb === 3 ? 3 : 4;
        const units = Math.ceil(notes.length / unit);
        const groups = scalesFitGroups(units, width, (a, b) => naturalWidth(Notation.staff(opts(rowOf(a * unit, Math.min(b * unit, notes.length))))));
        let at = 0;
        staff.innerHTML = groups.map((g, i) => {
            const r = rowOf(at * unit, Math.min((at + g) * unit, notes.length));
            at += g;
            let svg = Notation.staff(opts(r));
            const natural = naturalWidth(svg);
            if (i < groups.length - 1 && natural < width && natural > width * 0.5) svg = Notation.staff(opts(r, { justify: width / 10 }));
            return `<div class="warmups-row" data-from="${r.from}" data-to="${r.last ? notes.length + restSlots - 1 : r.to - 1}">${atSize(svg)}</div>`;
        }).join('');
        scalesLitRow = null;
        scalesLight(scalesLitIndex);
        renderScalesDock();
    }
    // Redrawn when the width changes (turning the phone, a wider window).
    let scalesStaffWidth = 0;
    if (typeof ResizeObserver !== 'undefined') {
        new ResizeObserver(() => {
            const w = document.getElementById('scalesStaff')?.clientWidth || 0;
            if (!w || w === scalesStaffWidth) return;
            scalesStaffWidth = w;
            if (isShown('scalesView')) renderScales();
        }).observe(document.getElementById('scalesStaff'));
    }
    let scalesLitIndex = -1, scalesLitRow = null;
    function scalesLight(i) {
        scalesLitIndex = i;
        document.querySelectorAll('#scalesStaff .is-now').forEach(el => el.classList.remove('is-now'));
        const progress = document.getElementById('scalesMemoryProgress');
        if (progress) progress.textContent = i >= 0 && scalesWritten ? (i < scalesWritten.notes.length ? `Note ${i + 1} of ${scalesWritten.notes.length}` : 'Rest') : '';
        if (i < 0) return;
        if (scales.light !== false) document.querySelectorAll(`#scalesStaff .scales-note-${i}`).forEach(el => el.classList.add('is-now')); // ML-589: a setting, as Warm-ups'
        // The line being played stays in view, near the top, with the next line under it (as Warm-ups).
        const row = [...document.querySelectorAll('#scalesStaff .warmups-row[data-from]')].find(r => i >= Number(r.dataset.from) && i <= Number(r.dataset.to));
        if (!row || row === scalesLitRow) return;
        scalesLitRow = row;
        const dock = document.getElementById('scalesDock').getBoundingClientRect();
        const header = document.querySelector('.top-bar-sticky-group');
        const top = header ? header.getBoundingClientRect().bottom : 0;
        const bottom = (row.nextElementSibling || row).getBoundingClientRect().bottom;
        if (row.getBoundingClientRect().top < top || bottom > dock.top) row.scrollIntoView({ block: 'start', behavior: scrollMotion() });
    }
    // "1 octave · treble · 3 of 18" - in a Scales block, how this Level is played instead of the place in the list
    function scalesShowSub() {
        const sub = document.getElementById('scalesSub');
        if (!sub) return;
        const level = scaleSubText(); // ML-391
        let place = '';
        if (!level) { const { list, i } = scalesListPos(); if (i >= 0) place = `${i + 1} of ${list.length}`; }
        sub.textContent = [scalesLength(), scales.clef, level || place].filter(Boolean).join(' · ');
    }

    // --- The bar at the bottom (ML-589, as Warm-ups): own pace - Previous, Next scale; with the metronome -
    // Previous, Play, Next; in a Scales block - Not yet, Play, Got it ---
    let scalesPass = 0, scalesListDone = false, scalesCountdown = 0;
    const SCALES_TIMES_WORDS = { 0: 'keep repeating', 1: 'play once', 2: 'play twice' };
    function renderScalesDock() {
        const L = scalesLadder;
        const metro = scalesMetronomeOn();
        const playing = scalesPlayer.isPlaying();
        const { list, i } = scalesListPos();
        setShown('scalesPrevBtn', !L);
        setShown('scalesNextMainBtn', !L && !metro);
        setShown('scalesNextBtn', !L && metro);
        setShown('scalesNotYetBtn', !!L);
        setShown('scalesGotItBtn', !!L);
        setShown('scalesPlayBtn', metro && !(scalesCountdown > 0));
        setShown('scalesCountIn', metro && scalesCountdown > 0);
        ['scalesPrevBtn', 'scalesNextBtn', 'scalesNextMainBtn'].forEach(id => { document.getElementById(id).disabled = list.length < 2 && !(list.length === 1 && i < 0); });
        const blockOf = L ? Math.max(PracticePlan.SCALES_PER_BLOCK, L.count) : 0;
        document.getElementById('scalesProgress').style.setProperty('--pct', `${L ? (L.count / blockOf) * 100 : list.length && i >= 0 ? ((i + 1) / list.length) * 100 : 0}%`);
        const next = list.length > 1 ? list[i < 0 ? 0 : (i + 1) % list.length] : null;
        let now = '', after = '';
        if (scalesListDone) now = 'That\'s the whole list - well done!';
        else if (L) {
            now = `${scales.bpm} bpm · ${scalesCountdown > 0 ? 'count-in' : 'set by the Level'}`;
            after = `Scale ${L.count} of ${blockOf}`;
        } else if (!metro) after = next ? `Next up: ${scaleTitleFor(next)}` : '';
        else {
            const t = scales.times;
            const what = scalesCountdown > 0 ? 'count-in' : !playing ? SCALES_TIMES_WORDS[t] : t === 2 ? `${scalesPass + 1 === 1 ? '1st' : '2nd'} time of 2` : t === 0 ? 'keep repeating' : '';
            now = `${scales.bpm} bpm${what ? ` · ${what}` : ''}`;
            after = scalesKeepsOne() || !next ? '' : i === list.length - 1 ? 'The last one' : `Next: ${scaleTitleFor(next)}`;
        }
        document.getElementById('scalesStatusNow').textContent = now;
        document.getElementById('scalesStatusNext').textContent = after;
    }
    function scalesShowCountIn(left, total) {
        if (left > 0) {
            document.getElementById('scalesCountInNum').textContent = left;
            const heard = total - left + 1;
            document.getElementById('scalesCountInDots').innerHTML = Array.from({ length: total }, (_, k) => `<span class="warmups-countin-dot${k < heard ? ' is-done' : ''}"></span>`).join('');
            document.getElementById('scalesCountIn').setAttribute('aria-label', `Get ready - ${left} - tap to stop`);
        }
        renderScalesDock();
    }

    // --- Playing: one click per note (notes / beat clicks each beat); a count-in bar before each scale ---
    // With the metronome the list is one metronome sequence (the player's ML-193 sequence mode, as Warm-ups): each
    // scale is a passage (its count-in bar, then its notes once or twice), and the player asks for the next one on the
    // beat the last ends - so it carries straight on in time - and stops after the last. Keep repeating, a Scales
    // block and a Skills step go round the one scale (no sequence): the count-in only at the start.
    const scalesPlayer = createMetronomePlayer();
    scalesPlayer.setVisualLatencyMs(metroState.latencyMs);
    let scalesTick = 0, scalesCountInClicks = 0, scalesToolLoop = null;
    const scalesPassClicks = (notesCount, barLength) => Math.ceil(notesCount / barLength) * barLength;
    function scalesPassageFor(pick, tag) {
        const barLength = SCALES_BEATS_PER_BAR * scales.npb;
        const n = TheoryEngine.writeScale(TheoryEngine.buildScale({ ...scales, ...scalesPickFields(pick) }), barLength).length;
        const countIn = scales.countIn ? SCALES_BEATS_PER_BAR * scales.npb : 0;
        return { bpm: scales.bpm, beatsPerBar: SCALES_BEATS_PER_BAR, notesPerBeat: scales.npb, startClick: 0, boundaryClicks: countIn + scales.times * scalesPassClicks(n, barLength), tag };
    }
    // The player's boundary call - a little ahead of the beat, while the clicks are being scheduled.
    function scalesLoopBoundary() {
        const L = scalesToolLoop;
        if (!L || !L.queued) return null;
        const list = scalesList();
        const i = list.findIndex(p => scalesPickSame(p, L.queued.pick));
        if (i < 0 || i + 1 >= list.length) return null; // the end of the list
        const pick = list[i + 1];
        L.queued = { pick, tag: `s:${++L.n}` };
        return scalesPassageFor(pick, L.queued.tag);
    }
    // The next scale's first click has sounded: show it (without stopping the player).
    function scalesLoopArrive() {
        const L = scalesToolLoop, q = L.queued;
        L.tag = q.tag;
        Object.assign(scales, scalesPickFields(q.pick));
        if (q.pick.form !== 'major') scales.minorForm = q.pick.form;
        scalesSave();
        scalesTick = 0;
        scalesCountdown = 0;
        scalesPass = 0;
        renderScales();
        scalesCountInClicks = scales.countIn ? SCALES_BEATS_PER_BAR * scales.npb : 0;
    }
    scalesPlayer.onBeat((info) => {
        // ML-589: the list has been played to the end
        if (info && info.ended) { scalesStop(); scalesListDone = true; window.Usage?.finish('scales'); renderScalesDock(); return; } // ML-22: played to the end
        const L = scalesToolLoop;
        if (L && L.tag && info && info.tag && info.tag !== L.tag) scalesLoopArrive();
        const w = scalesWritten;
        if (!w) return;
        const k = scalesTick++ - scalesCountInClicks;
        if (k < 0) {
            const remaining = Math.ceil(-k / scales.npb);
            if (remaining !== scalesCountdown) { scalesCountdown = remaining; scalesShowCountIn(remaining, Math.round(scalesCountInClicks / scales.npb)); }
            scalesLight(-1);
            return;
        }
        if (scalesCountdown) { scalesCountdown = 0; scalesShowCountIn(0); }
        // The last bar is made up with rests (ML-386) - they light up in turn - then round again (or on to the next).
        const pass = scalesPassClicks(w.notes.length, w.barLength);
        const p = Math.floor(k / pass);
        if (p !== scalesPass) { scalesPass = p; renderScalesDock(); }
        scalesLight(k % pass);
    });
    function scalesUpdatePlayUi() {
        const playing = scalesPlayer.isPlaying();
        document.getElementById('scalesPlayIcon').textContent = playing ? 'pause' : 'play_arrow';
        document.getElementById('scalesPlayLbl').textContent = playing ? 'Pause' : 'Play';
        document.getElementById('scalesPlayBtn').setAttribute('aria-pressed', String(playing));
        renderScalesDock();
    }
    function scalesPlay() {
        if (!scalesMetronomeOn()) return;
        if (!scalesWritten) renderScales();
        scalesListDone = false;
        if (scalesTick === 0) scalesCountInClicks = scales.countIn ? SCALES_BEATS_PER_BAR * scales.npb : 0;
        if (!scalesKeepsOne()) {
            const L = scalesToolLoop || (scalesToolLoop = { n: 0 });
            if (L.tag) { scalesPlayer.play(); scalesUpdatePlayUi(); return; } // carrying on where it paused
            L.tag = `s:${++L.n}`;
            L.queued = { pick: scalesCurrentPick(), tag: L.tag };
            scalesPlayer.setSequence(scalesPassageFor(L.queued.pick, L.tag), scalesLoopBoundary);
        } else scalesPlayer.clearSequence();
        scalesPlayer.setConductorBpm(scales.bpm);
        scalesPlayer.setConductorBeatsPerBar(SCALES_BEATS_PER_BAR);
        scalesPlayer.setNotesPerBeat(scales.npb);
        scalesPlayer.setSubdivisionFactor(1);
        scalesPlayer.play();
        window.Usage?.begin('scales'); // ML-22
        scalesUpdatePlayUi();
    }
    function scalesPause() {
        scalesPlayer.pause();
        window.Usage?.end('scales');
        if (scalesCountdown) { scalesCountdown = 0; scalesShowCountIn(0); }
        scalesUpdatePlayUi();
    }
    // Back to the start, stopped: the next Play counts in again (if the count-in is on).
    function scalesStop() {
        if (scalesPlayer.isPlaying()) scalesPlayer.pause();
        scalesPlayer.resetToBarStart();
        scalesPlayer.clearSequence();
        if (scalesToolLoop) scalesToolLoop.tag = null;
        scalesTick = 0;
        scalesCountdown = 0;
        scalesPass = 0;
        scalesListDone = false;
        scalesLight(-1);
        scalesShowSub();
        scalesUpdatePlayUi();
    }
    // Back to the start - and carrying on playing if it was.
    function scalesReset() {
        const wasPlaying = scalesPlayer.isPlaying();
        scalesStop();
        if (wasPlaying) scalesPlay();
    }
    setupPlayButtonHoldReset('scalesPlayBtn', () => { if (scalesPlayer.isPlaying()) scalesPause(); else scalesPlay(); }, scalesStop);
    document.getElementById('scalesCountIn')?.addEventListener('click', scalesPause);
    // A different scale (or rhythm) starts again from the top.
    function scalesChanged() {
        scalesSave();
        renderScales();
        scalesReset();
    }

    // --- Speed (its own pop-up now - ML-589; the same pieces as the Metronome's) ---
    function scalesRenderBpm() {
        const pct = ((scales.bpm - METRO_MIN_BPM) / (SCALES_BPM_MAX - METRO_MIN_BPM)) * 100;
        document.getElementById('scalesBpmFill')?.style.setProperty('--pct', `${pct}%`);
        const thumb = document.getElementById('scalesBpmThumb');
        thumb?.style.setProperty('--pct', `${pct}%`);
        thumb?.setAttribute('aria-valuenow', String(scales.bpm));
        const val = document.getElementById('scalesBpmVal');
        if (val) val.textContent = scales.bpm;
        document.getElementById('scalesSpeedVal').textContent = `${scales.bpm} bpm`;
        renderScalesDock();
    }
    function scalesSetBpm(v) {
        scales.bpm = Math.round(Math.min(SCALES_BPM_MAX, Math.max(METRO_MIN_BPM, v)));
        scalesPlayer.setConductorBpm(scales.bpm);
        scalesRenderBpm();
        scalesSavePrefs();
    }
    setupHoldStepper('scalesBpmMinus', -1, (amount) => scalesSetBpm(scales.bpm + amount));
    setupHoldStepper('scalesBpmPlus', 1, (amount) => scalesSetBpm(scales.bpm + amount));
    setupSliderInteraction(document.getElementById('scalesBpmTrack'), document.getElementById('scalesBpmThumb'), {
        onDragRatio: (ratio) => scalesSetBpm(METRO_MIN_BPM + ratio * (SCALES_BPM_MAX - METRO_MIN_BPM)),
        onArrowStep: (dir) => scalesSetBpm(scales.bpm + dir),
    });
    makeSliderReadoutEditable('scalesBpmVal', () => scales.bpm, (v) => scalesSetBpm(v), { label: 'Beats per minute', min: METRO_MIN_BPM, max: SCALES_BPM_MAX });
    document.getElementById('scalesSpeedBtn')?.addEventListener('click', () => { scalesRenderBpm(); showModal('scalesSpeedModal'); });
    document.getElementById('scalesSpeedModal')?.addEventListener('click', (e) => { if (e.target.closest('[data-modal-close]')) scalesTrack('bpm', scales.bpm); });

    // --- Volume (the Metronome tool's pop-up: -/+, slider, mute; a test click while stopped) ---
    let scalesVolumeBeforeMute = scales.volume || 80;
    function scalesRenderVolume() {
        const v = scales.volume;
        document.getElementById('scalesVolumeFill')?.style.setProperty('--pct', `${v}%`);
        const thumb = document.getElementById('scalesVolumeThumb');
        thumb?.style.setProperty('--pct', `${v}%`);
        thumb?.setAttribute('aria-valuenow', String(v));
        const val = document.getElementById('scalesVolumeValue');
        if (val) val.textContent = `${v}%`;
        document.getElementById('scalesVolumeVal').textContent = v === 0 ? 'Off' : `${v}%`;
        const muted = v === 0;
        document.getElementById('scalesMuteIcon').textContent = muted ? 'volume_off' : 'volume_up';
        document.getElementById('scalesMuteBtn')?.setAttribute('aria-pressed', String(muted));
        document.getElementById('scalesVolumeRow')?.classList.toggle('is-muted', muted);
    }
    function scalesSetVolume(v, force = false) {
        scales.volume = Math.round(Math.min(100, Math.max(0, v)));
        if (scales.volume > 0) scalesVolumeBeforeMute = scales.volume;
        scalesPlayer.setVolume(scales.volume / 100);
        scalesRenderVolume();
        scalesSavePrefs();
        playVolumeTestClick(scalesPlayer, force);
    }
    scalesPlayer.setVolume((scales.volume ?? 80) / 100);
    setupSliderInteraction(document.getElementById('scalesVolumeTrack'), document.getElementById('scalesVolumeThumb'), {
        onDragRatio: (ratio) => scalesSetVolume(ratio * 100),
        onArrowStep: (dir) => scalesSetVolume(scales.volume + dir * 5),
        onRelease: () => playVolumeTestClick(scalesPlayer, true),
    });
    setupHoldStepper('scalesVolumeMinus', -1, (amount) => scalesSetVolume(scales.volume + amount, true));
    setupHoldStepper('scalesVolumePlus', 1, (amount) => scalesSetVolume(scales.volume + amount, true));
    makeSliderReadoutEditable('scalesVolumeValue', () => scales.volume, (v) => scalesSetVolume(v, true), { label: 'Volume', min: 0, max: 100 });
    document.getElementById('scalesMuteBtn')?.addEventListener('click', () => scalesSetVolume(scales.volume > 0 ? 0 : scalesVolumeBeforeMute, true));
    document.getElementById('scalesVolumeBtn')?.addEventListener('click', () => { scalesRenderVolume(); showModal('scalesVolumeModal'); });

    // --- Pickers: tap a tile to choose ---
    const scalesTile = (value, caption, selected, attrs = '', option = '') =>
        `<button type="button" class="flow-picker-tile${selected ? ' selected' : ''}" aria-pressed="${selected}" data-option="${usageOptionKey(option)}" ${attrs}><span class="flow-picker-tile-icon-row">${value}</span>${caption ? `<span class="flow-picker-tile-label">${escapeHtml(caption)}</span>` : ''}</button>`;
    function scalesFillGrid(gridId, options, onPick) {
        const grid = document.getElementById(gridId);
        if (!grid) return;
        grid.innerHTML = options.map(o => scalesTile(o.value, o.caption, o.selected, o.attrs || '', o.v)).join(''); // ML-22: data-option, so each choice is counted
        grid.querySelectorAll('.flow-picker-tile').forEach((btn, i) => btn.addEventListener('click', () => onPick(options[i])));
    }

    // --- Settings (ML-589): my scales, how they're shown, the metronome; each value box opens its own pop-up ---
    function scalesRenderSettings() {
        const inst = scalesGradeInstrument();
        const L = scalesLadder;
        document.getElementById('scalesInstrumentVal').textContent = inst ? inst.name : 'None';
        document.getElementById('scalesClefBtnVal').textContent = (SCALES_CLEFS.find(([v]) => v === scales.clef) || SCALES_CLEFS[0])[1];
        document.getElementById('scalesGradesVal').textContent = scales.grades.length ? scalesGradesText(scales.grades).replace('everything else', 'all else') : 'None';
        document.getElementById('scalesSizeVal').textContent = (WARMUPS_SIZE_LABELS.find(([v]) => v === warmups.size) || WARMUPS_SIZE_LABELS[1])[1];
        document.getElementById('scalesShuffleToggle').checked = !!scales.shuffle;
        const [, dirLabel] = SCALES_DIRECTIONS[scales.direction] || SCALES_DIRECTIONS.both;
        document.getElementById('scalesDirBtnVal').textContent = dirLabel.charAt(0).toUpperCase() + dirLabel.slice(1);
        document.getElementById('scalesDetailBtnVal').textContent = (SCALES_DETAILS.find(([v]) => v === scales.detail) || SCALES_DETAILS[0])[1];
        const metro = scalesMetronomeOn();
        document.getElementById('scalesMetronomeToggle').checked = metro;
        setShown('scalesMetronomeSettings', metro);
        setShown('scalesLightRow', metro);
        document.getElementById('scalesLightToggle').checked = scales.light !== false;
        document.getElementById('scalesSpeedVal').textContent = `${scales.bpm} bpm`;
        document.getElementById('scalesNpbVal').textContent = scales.npb;
        document.getElementById('scalesRepeatVal').textContent = (SCALES_TIMES.find(([n]) => n === scales.times) || SCALES_TIMES[1])[1];
        document.getElementById('scalesCountInVal').textContent = scales.countIn ? '1 bar' : 'None';
        scalesRenderVolume();
        // In a Scales block (ML-391) the Level sets what's shown and the speed, and the block has its own scales.
        ['scalesInstrumentBtn', 'scalesPoolBtn', 'scalesShuffleToggle', 'scalesDetailBtn', 'scalesMetronomeToggle', 'scalesSpeedBtn', 'scalesNpbBtn', 'scalesRepeatBtn'].forEach(id => { document.getElementById(id).disabled = !!L; });
        document.querySelector('#scalesMetronomeLbl .display-toggle-help').textContent = L ? 'In a Scales block the Level sets the speed' : 'It plays each scale, then carries on to the next';
        setShown('scalesSettingsRangeBtn', !!inst);
        const { grid, pool } = scalesGradeGrid();
        document.getElementById('scalesSettingsCount').textContent = grid && scales.grades.length ? `${pool.length} scale${pool.length === 1 ? '' : 's'} in your list${grid.needed > pool.length ? ` (of ${grid.needed} needed)` : ''}` : '';
    }
    // A change to what's in the list or how it's drawn: back to the start, redrawn.
    function scalesSettingsChanged() {
        scalesPoolCache = null;
        scalesRenderSettings();
        scalesChanged();
    }
    document.getElementById('scalesSettingsBtn')?.addEventListener('click', async () => {
        if (!myInstruments || !myInstruments.length) await loadMyInstruments();
        scalesRenderSettings();
        showModal('scalesSettingsModal');
    });
    document.getElementById('scalesInstrumentBtn')?.addEventListener('click', () => {
        renderInstrumentChoice(document.getElementById('scalesGradeInstrument'), scalesGradeInstrument(), (id) => {
            scalesClefPicked = false; // the new instrument, in the clef you read it in
            scalesSetPref('gradeInstrumentId', id);
            scalesUseMyClef();
            hideModal('scalesInstrumentModal');
            if (scaleLevelsOn()) loadScaleLevels().then(renderScalesLadder); // ML-391: this instrument's Levels
            scalesSettingsChanged();
        });
        showModal('scalesInstrumentModal');
    });
    document.getElementById('scalesSizeBtn')?.addEventListener('click', () => {
        scalesFillGrid('scalesSizeGrid', WARMUPS_SIZE_LABELS.map(([v, l]) => ({ value: l, caption: '', selected: warmups.size === v, v })),
            (o) => { warmupsSetPref('size', o.v); scalesTrack('size', o.v); hideModal('scalesSizeModal'); scalesRenderSettings(); renderScales(); }); // shared with Warm-ups
        showModal('scalesSizeModal');
    });
    document.getElementById('scalesShuffleToggle')?.addEventListener('change', (e) => { scalesShuffled = null; scalesSetPref('shuffle', e.target.checked); scalesSettingsChanged(); });
    document.getElementById('scalesMetronomeToggle')?.addEventListener('change', (e) => { scalesSetPref('metronome', e.target.checked); if (!e.target.checked) scalesStop(); scalesSettingsChanged(); });
    document.getElementById('scalesLightToggle')?.addEventListener('change', (e) => { scalesSetPref('light', e.target.checked); scalesLight(scalesLitIndex); });
    document.getElementById('scalesSettingsRangeBtn')?.addEventListener('click', () => {
        const inst = scalesGradeInstrument();
        renderMyRange({ inst, clef: scales.clef, ctx: scalesGradeContext(inst), what: 'every scale the grades need', over: 'scalesSettingsModal', after: scalesRenderSettings });
    });
    document.getElementById('scalesClefBtn')?.addEventListener('click', () => {
        scalesFillGrid('scalesClefGrid', SCALES_CLEFS.map(([v, l]) => ({ value: l, caption: 'clef', selected: scales.clef === v, v })),
            (o) => { scales.clef = o.v; scales.tonicOctave = null; scalesClefPicked = true; scalesTrack('clef', o.v); hideModal('scalesClefModal'); scalesSettingsChanged(); });
        showModal('scalesClefModal');
    });
    document.getElementById('scalesDirBtn')?.addEventListener('click', () => {
        scalesFillGrid('scalesDirGrid', Object.entries(SCALES_DIRECTIONS).map(([v, [, l]]) => ({ value: scalesDirIconHtml(v), caption: l, selected: scales.direction === v, v, attrs: `aria-label="${l}"` })),
            (o) => { scalesSetPref('direction', o.v); hideModal('scalesDirModal'); scalesSettingsChanged(); });
        showModal('scalesDirModal');
    });
    document.getElementById('scalesDetailBtn')?.addEventListener('click', () => {
        scalesFillGrid('scalesDetailGrid', SCALES_DETAILS.map(([v, l, cap]) => ({ value: l, caption: cap, selected: scales.detail === v, v })),
            (o) => { scalesSetPref('detail', o.v); hideModal('scalesDetailModal'); scalesRenderSettings(); renderScales(); });
        showModal('scalesDetailModal');
    });
    document.getElementById('scalesNpbBtn')?.addEventListener('click', () => {
        scalesFillGrid('scalesNpbGrid', SCALES_NPB.map(([n, l]) => ({ value: n, caption: l, selected: scales.npb === n, v: n })),
            (o) => { scalesSetPref('npb', o.v); hideModal('scalesNpbModal'); scalesSettingsChanged(); });
        showModal('scalesNpbModal');
    });
    document.getElementById('scalesRepeatBtn')?.addEventListener('click', () => {
        scalesFillGrid('scalesRepeatGrid', SCALES_TIMES.map(([n, l, v]) => ({ value: v, caption: l.toLowerCase(), selected: scales.times === n, v: n, attrs: `aria-label="Play each one: ${l.toLowerCase()}"` })),
            (o) => { scalesSetPref('times', o.v); hideModal('scalesRepeatModal'); scalesSettingsChanged(); });
        showModal('scalesRepeatModal');
    });
    document.getElementById('scalesCountInBtn')?.addEventListener('click', () => {
        scalesFillGrid('scalesCountInGrid', [[0, 'None'], [1, '1 bar']].map(([n, l]) => ({ value: l, caption: '', selected: scales.countIn === n, v: n })),
            (o) => { scalesSetPref('countIn', o.v); hideModal('scalesCountInModal'); scalesSettingsChanged(); });
        showModal('scalesCountInModal');
    });

    // Opening the screen: the account's settings (once a visit), your clef, the scale you were on.
    async function openScalesView() {
        scalesListDone = false;
        scalesUseMyClef();
        renderScales();
        scalesRenderBpm();
        scalesRenderVolume();
        scalesUpdatePlayUi();
        scalesPlayer.prewarm();
        const first = !scalesPrefsRead;
        await Promise.all([scalesLoadPrefs(), warmupsLoadPrefs()]); // the music size is Warm-ups'
        if (!myInstruments || !myInstruments.length) await loadMyInstruments();
        scalesPlayer.keepAwake(scalesMetronomeOn()); // ML-586: the headphones stay awake while it's open
        if (first && isShown('scalesView')) { scalesUseMyClef(); renderScales(); scalesRenderBpm(); scalesRenderVolume(); }
    }

    // --- My scales (ML-357): the ABRSM grade lists, and Previous / Next / Shuffle ---
    // Tick the grades and choose the instrument; ScaleGrades works out which scales those grades ask for
    // on it and whether each fits the instrument and your range (docs/scales-grades.md). The ready and
    // other-octave ones are the list, in grid order (majors, then minors; keys in chromatic order).
    const scalesGradeInstrument = () => (myInstruments || []).find(i => i.id === scales.gradeInstrumentId) || (myInstruments || []).find(i => i.isPrimary) || (myInstruments || [])[0] || null;
    // For bass- or tenor-clef brass that's usually written in treble (a baritone or euphonium in a brass
    // band), the ABRSM list is at concert pitch - so the instrument's and your written range move by its
    // transposition to be compared with it.
    function scalesGradeContext(inst) {
        const shift = inst && inst.familyKey === 'brass' && inst.theoryClef === 'treble' && scales.clef !== 'treble' ? Number(inst.writtenToConcert) || 0 : 0;
        const at = (pitch) => { const m = pitch ? ScaleGrades.midiOf(pitch) : null; return m == null ? null : m + shift; };
        // high: the outer limit, a 4th above the usual top on brass and woodwind (ML-370) - once your range
        // is set; until then (when every scale the instrument plays counts as in your list) the usual top.
        const outer = instrumentOuter(inst);
        return { clef: scales.clef, shift, low: at(inst && inst.rangeLow), high: at(inst && (inst.topNote && outer ? outer.high : inst.rangeHigh)), usualHigh: at(inst && inst.rangeHigh), bottom: at(inst && inst.bottomNote), top: at(inst && inst.topNote) };
    }
    // No ABRSM list for the instrument (or no instrument): Everything else is still every scale.
    function scalesGradeGrid() {
        const inst = scalesGradeInstrument();
        const group = inst ? ScaleGrades.groupFor(inst.scaleLists, scales.clef) : null; // ML-609: by its key, not its name
        if (!group && !scales.grades.includes(ScaleGrades.EVERYTHING)) return { inst, group, grid: null, pool: [] };
        const grid = ScaleGrades.grid(group ? group.id : null, scales.grades, scalesGradeContext(inst));
        return { inst, group, grid, pool: grid.pool };
    }
    const scalesGradeHead = (title, cols) => `<div class="scale-grid-head" aria-hidden="true"><span class="scale-grid-label">${title}</span>${cols.map(c => { const n = scalesName(c); return `<span>${escapeHtml(n[0])}<span class="scale-grid-acc">${escapeHtml(n.slice(1)) || '&nbsp;'}</span></span>`; }).join('')}</div>`;
    const SCALE_CELL = { ready: ['is-ready', '', 'in your list'], other: ['is-other', '8', 'in your list, another octave'], locked: ['is-locked', '<span class="material-symbols-outlined">lock</span>', 'outside your range'], beyond: ['is-beyond', '&times;', 'beyond the instrument'], no: ['is-no', '', ''] };
    // The ticked grades in a few words: "1-3 & 5", "1-7", "1, 3, 5 & 7", "... & everything else"
    function scalesGradesText(grades) {
        const runs = [];
        for (const n of grades.filter(Number.isInteger).sort((a, b) => a - b)) {
            const r = runs[runs.length - 1];
            if (r && n === r[1] + 1) r[1] = n; else runs.push([n, n]);
        }
        const parts = runs.flatMap(([a, b]) => (b - a >= 2 ? [`${a}-${b}`] : a === b ? [String(a)] : [String(a), String(b)]));
        if (grades.includes(ScaleGrades.EVERYTHING)) parts.push('everything else');
        return parts.length > 1 ? `${parts.slice(0, -1).join(', ')} & ${parts[parts.length - 1]}` : (parts[0] || '');
    }
    function scalesRenderPool() {
        const levelsOn = scaleLevelsOn() && !!scaleLevels.instrumentId; // ML-391: each box holds its Level
        const cellKey = (c) => PracticePlan.scaleKey({ type: c.item.kind, keyId: c.item.keyId, form: c.item.form, octaves: c.item.octaves, pattern: c.item.pattern });
        const levelCell = (c) => { const rec = scaleLevelOf(cellKey(c)); return `<span class="scale-grid-cell is-level lv-${rec.level}" aria-hidden="true">${rec.learnt ? '<span class="material-symbols-outlined">star</span>' : rec.level}</span>`; };
        document.querySelectorAll('input[name="scalesGrade"]').forEach(el => { el.checked = scales.grades.includes(el.value === ScaleGrades.EVERYTHING ? el.value : Number(el.value)); });
        document.getElementById('scalesGradesSummary').textContent = scales.grades.length ? `· ${scalesGradesText(scales.grades)}` : '';
        const inst = scalesGradeInstrument(); // ML-589: chosen in Settings now
        const { group, grid, pool } = scalesGradeGrid();
        const name = document.getElementById('scalesGradeListName');
        const box = document.getElementById('scalesGradeGrid');
        setShown('scalesSeeRangeBtn', !!inst);
        const everything = scales.grades.includes(ScaleGrades.EVERYTHING);
        setShown('scalesGradeDisclaimer', !!group); // ML-313: with an ABRSM list, say whose requirements they are
        if (group) {
            const pitchNote = group.clef === 'bass' && inst.theoryClef === 'treble' && inst.familyKey === 'brass' ? ', concert pitch' : '';
            name.textContent = `ABRSM list: ${group.name}${pitchNote}.`;
        } else {
            name.textContent = (inst ? `There's no ABRSM brass or woodwind list for ${inst.name} in the ${scales.clef} clef` : 'Add the instrument you play in ☰ → My instruments for its grade lists')
                + (everything ? ' - Everything else has every scale.' : ' - tick Everything else for every scale.');
        }
        const row = (r) => {
            const said = Object.entries(SCALE_CELL).filter(([k]) => k !== 'no').map(([k, [, , words]]) => {
                const inList = levelsOn && (k === 'ready' || k === 'other');
                const keys = r.cells.filter(c => c.state === k).map(c => scalesName(c.item ? c.item.keyId.split(' ')[0] : c.tonic)
                    + (inList ? (() => { const rec = scaleLevelOf(cellKey(c)); return rec.learnt ? ' (learnt)' : ` (Level ${rec.level})`; })() : ''));
                return keys.length ? `${words}: ${keys.join(', ')}` : '';
            }).filter(Boolean).join('; ');
            return `<div class="scale-grid-row" role="img" aria-label="${escapeHtml(`${r.label}, ${r.sub}. ${said || 'none needed'}`)}"><span class="scale-grid-label" aria-hidden="true">${escapeHtml(r.label)}<span class="scale-grid-sub">${escapeHtml(r.sub)}</span></span>${r.cells.map(c => (levelsOn && (c.state === 'ready' || c.state === 'other') ? levelCell(c) : `<span class="scale-grid-cell ${SCALE_CELL[c.state][0]}" aria-hidden="true">${SCALE_CELL[c.state][1]}</span>`)).join('')}</div>`;
        };
        const sec = (key, title, cols) => (grid.sections[key].length ? `<div class="scale-grid">${scalesGradeHead(title, cols)}${grid.sections[key].map(row).join('')}</div>` : '');
        box.innerHTML = !scales.grades.length ? '<p class="text-sm">Tick a grade, or Everything else, to see its scales.</p>'
            : grid ? sec('major', 'Major keys', ScaleGrades.MAJOR_COLUMNS) + sec('minor', 'Minor keys', ScaleGrades.MINOR_COLUMNS) : '';
        setShown('scalesLevelLegend', levelsOn);
        setShown('scalesListLegend', !levelsOn);
        const goal = document.getElementById('scalesPoolGoal');
        const mine = levelsOn && grid && scales.grades.length ? pool.map(x => ({ ...x, key: PracticePlan.scaleKey(x) })) : [];
        goal.innerHTML = mine.length ? scaleGoalHtml(PracticePlan.scaleProgress(mine, scaleLevels.records)) : '';
        setShown(goal, mine.length > 0);
        document.getElementById('scalesPoolCount').textContent = grid && scales.grades.length ? `${pool.length} scale${pool.length === 1 ? '' : 's'} in your list${grid.needed > pool.length ? ` (of ${grid.needed} needed)` : ''}` : '';
    }
    document.querySelectorAll('input[name="scalesGrade"]').forEach(input => input.addEventListener('change', () => {
        scales.grades = [...document.querySelectorAll('input[name="scalesGrade"]:checked')].map(x => (x.value === ScaleGrades.EVERYTHING ? x.value : Number(x.value)));
        // (kept in grade order, Everything else last)
        scales.grades.sort((a, b) => (a === ScaleGrades.EVERYTHING) - (b === ScaleGrades.EVERYTHING) || a - b);
        scalesSavePrefs();
        scalesTrack('grades', scales.grades.join(','));
        scalesRenderPool();
        scalesPoolCache = null;
        scalesRenderSettings(); // ML-589: Grades opens from Settings
        renderScales();
    }));
    document.getElementById('scalesPoolBtn')?.addEventListener('click', async () => {
        if (!myInstruments || !myInstruments.length) await loadMyInstruments();
        await loadScaleLevels(); // ML-391
        scalesRenderPool();
        showModal('scalesPoolModal');
    });

    // See your range: the notes you can play comfortably, named and on a stave in the scales' clef.
    // See your range (shared by Scales and Warm-ups, ML-361): inst, the clef to draw it in, ctx (MIDI numbers
    // in that clef's pitch world: bottom / top your range, low / high the instrument's, shift if moved to
    // concert pitch), what counts as in your list until a range is set, the pop-up it opens over, and what
    // to redraw once a range is saved.
    // ML-370: your range inside the instrument's, as one bar with the key under it - drawn by
    // public/rangeBar.js (RangeBar.html; ML-384 moved it there so every screen draws it the same way).
    function renderMyRange({ inst, clef, ctx, what, over, after }) {
        // ML-370: "Your range" on its own, the instrument under it in smaller type (a long name didn't fit).
        const instLine = document.getElementById('scalesMyRangeInstrument');
        instLine.textContent = inst ? inst.name : '';
        setShown(instLine, !!inst);
        const staff = document.getElementById('scalesMyRangeStaff');
        const barBox = document.getElementById('scalesMyRangeBar');
        const text = document.getElementById('scalesMyRangeText');
        const setBtn = document.getElementById('scalesMyRangeSetBtn');
        const named = (m) => PlayRange.label(PlayRange.pitchOf(m, 'usual'));
        if (inst && ctx.bottom != null && ctx.top != null) {
            const notes = [ctx.bottom, ctx.top].map(m => PlayRange.pitchOf(m, 'usual'));
            staff.innerHTML = Notation.staff({ clef, noteGap: 3, label: `Your range: ${named(ctx.bottom)} to ${named(ctx.top)}`,
                items: notes.map(pitch => ({ type: 'note', pitch })) });
            const bar = RangeBar.html(inst, ctx);
            barBox.innerHTML = bar.html;
            text.textContent = (ctx.shift ? 'At concert pitch, as the bass-clef grade lists are written. ' : '') + bar.text;
            setBtn.textContent = 'Change your range';
        } else {
            staff.innerHTML = '';
            barBox.innerHTML = '';
            text.textContent = inst ? `You haven't set the notes you can play comfortably on ${inst.name} yet - until you do, ${what} counts as in your list.` : 'Add the instrument you play in ☰ → My instruments first.';
            setBtn.textContent = inst ? 'Set your range' : 'My instruments';
        }
        setShown(setBtn, true);
        // The range picker opens over the pop-up (which redraws once it's saved); without the Range tool,
        // or an instrument, it's My instruments.
        setBtn.onclick = () => {
            hideModal('scalesMyRangeModal');
            if (inst && isFeatureEnabled('range_trainer')) { rangeData = null; openRangePicker(inst.id, after); return; }
            hideModal(over);
            switchView('accountInstrumentsView');
        };
        showModal('scalesMyRangeModal');
    }
    function scalesRenderMyRange() {
        const inst = scalesGradeInstrument();
        renderMyRange({ inst, clef: scales.clef, ctx: scalesGradeContext(inst), what: 'every scale the grades need', over: 'scalesPoolModal', after: scalesRenderPool });
    }
    document.getElementById('scalesSeeRangeBtn')?.addEventListener('click', scalesRenderMyRange);

    // Choose a scale: your list, row by row as in the My scales grid, each key a button (the grid's own boxes
    // are too small to tap - 44px targets). Tap one to play it.
    async function scalesRenderChoose() {
        const pool = await scalesGradePool();
        const { grid } = scalesGradeGrid();
        const list = document.getElementById('scalesChooseList');
        document.getElementById('scalesChooseIntro').textContent = pool.length
            ? `The ${pool.length} scale${pool.length === 1 ? '' : 's'} in your list. Tap one to play it.`
            : 'Nothing in your list yet - choose your grades in Settings.';
        if (!grid || !pool.length) { list.innerHTML = ''; return; }
        const picks = [];
        const group = (section, title) => grid.sections[section].map(r => {
            const cells = r.cells.filter(c => c.state === 'ready' || c.state === 'other');
            if (!cells.length) return '';
            const keys = cells.map(c => {
                const pick = pool.find(x => x.keyId === c.item.keyId && x.form === c.item.form && x.type === c.item.kind && x.octaves === c.item.octaves && (x.pattern || null) === (c.item.pattern || null));
                picks.push(pick);
                const on = scalesSame(pick);
                const key = scalesName(c.item.keyId.split(' ')[0]);
                return `<button type="button" class="flow-picker-tile${on ? ' selected' : ''}" data-pick="${picks.length - 1}" aria-pressed="${on}" aria-label="${escapeHtml(`${key} ${section}, ${r.label.toLowerCase()}, ${r.sub}${c.state === 'other' ? ', another octave' : ''}`)}"><span class="flow-picker-tile-icon-row">${escapeHtml(key)}</span>${c.state === 'other' ? '<span class="flow-picker-tile-label">8</span>' : ''}</button>`;
            }).join('');
            return `<div class="scales-choose-group"><h3 class="scales-choose-label">${/minor/i.test(r.label) ? '' : `${escapeHtml(title)} · `}${escapeHtml(r.label)}<span class="scale-grid-sub">${escapeHtml(r.sub)}</span></h3><div class="scales-choose-keys">${keys}</div></div>`;
        }).join('');
        list.innerHTML = group('major', 'Major') + group('minor', 'Minor');
        list.querySelectorAll('[data-pick]').forEach(btn => btn.addEventListener('click', () => {
            hideModal('scalesChooseModal');
            scalesGo(picks[Number(btn.dataset.pick)]);
        }));
    }
    document.getElementById('scalesChooseBtn')?.addEventListener('click', async () => { if (scalesLadder) return; await scalesRenderChoose(); showModal('scalesChooseModal'); });
    document.getElementById('scalesChooseEditBtn')?.addEventListener('click', () => { hideModal('scalesChooseModal'); document.getElementById('scalesPoolBtn')?.click(); });


    // ===== ML-391: Scales Levels =====
    // Every scale in your list has a Level 1-5 on this instrument (PracticePlan.SCALE_LEVELS: the notes
    // slowly, the notes faster, just the key, just the name, the name at full speed), then it's learnt.
    // A practice session's Scales block walks through three of them (scalesLadder): the Level sets what's
    // shown and the speed, you say Got it or Not yet, and the next one comes. Lowest Level first, so every
    // scale moves up together. Behind its own switch (scales_levels); off, a Scales block opens the tool as
    // before. The rules are PracticePlan.scale* (tests: server/test/scaleLevels.test.js); the record is
    // /api/practice/scale-levels. docs/practice-sessions.md, "Scales Levels".
    function scaleLevelsOn() { return isFeatureEnabled('scales_levels') && isFeatureEnabled('practice_levels'); }
    var scaleLevels = { instrumentId: null, records: {} }; // this instrument's records: { scaleKey: { level, learnt, lastPlayed, lastUpOn } }
    var scalesLadder = null; // var: scalesSave and switchView read it - a Scales block in progress: { saved, items, family, played, count, current }
    async function loadScaleLevels() {
        if (!scaleLevelsOn()) return scaleLevels;
        if (!myInstruments || !myInstruments.length) await loadMyInstruments().catch(() => {});
        const inst = scalesGradeInstrument();
        if (!inst) { scaleLevels = { instrumentId: null, records: {} }; return scaleLevels; }
        try { scaleLevels = { instrumentId: inst.id, records: (await API.scaleLevels.get(inst.id)).records || {} }; }
        catch (e) { scaleLevels = { instrumentId: inst.id, records: {} }; }
        return scaleLevels;
    }
    // Your list with each scale's id, and the speed family of its ABRSM list (trombones are slower)
    function scaleLevelItems() {
        const { inst, group, pool } = scalesGradeGrid();
        const data = group ? ScaleGrades.DATA[group.id] : null;
        const family = PracticePlan.scaleSpeedFamily(group && group.id, data ? data.family : (inst && inst.familyKey === 'woodwind' ? 'woodwind' : 'brass'));
        return { family, items: pool.map(p => ({ ...p, key: PracticePlan.scaleKey(p) })) };
    }
    function scaleLevelOf(key) { return PracticePlan.scaleRecord((scaleLevels || {}).records, key); }
    // "D harmonic minor scale", as the Scales screen titles it
    function scaleTitleFor(p) {
        const scale = TheoryEngine.buildScale({ ...scales, keyId: p.keyId, form: p.form, minorForm: p.form !== 'major' ? p.form : scales.minorForm, type: p.type, octaves: p.octaves, pattern: p.pattern || null, tonicOctave: Number.isInteger(p.tonicOctave) ? p.tonicOctave : null, extended: p.extended || null });
        return SCALES_NAMED_WHOLE.includes(p.type) ? scale.title : scale.title.replace(/^\S+/, scalesName(p.keyId.split(' ')[0]));
    }
    const scaleShortName = (p) => scaleTitleFor(p).replace(/ scale$/, '');
    const scaleToday = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; };
    const scaleLevelChip = (rec) => (rec.learnt ? '<span class="level-chip lv-5"><span class="material-symbols-outlined" aria-hidden="true">star</span></span>' : `<span class="level-chip lv-${rec.level}">${rec.level}</span>`);
    // Every scale's Level as one bar (a learnt one counts with the 5s), for the set-up card and the celebration
    const scaleLevelMap = (items) => items.map(it => scaleLevelOf(it.key).level).sort((a, b) => a - b);
    const scaleGoalHtml = (p) => (p.low == null ? '<span class="material-symbols-outlined" aria-hidden="true">star</span> Every scale is learnt'
        : `<span class="material-symbols-outlined" aria-hidden="true">trending_up</span> Next goal: every <span class="level-chip lv-${p.low}">${p.low}</span> ${p.low < PracticePlan.SCALE_TOP_LEVEL ? `up to <span class="level-chip lv-${p.low + 1}">${p.low + 1}</span>` : 'learnt'} · ${p.toGo} to go`);

    // --- A Scales block ---
    // False when there's nothing to walk through (the switch is off, no instrument, an empty list): the
    // block then opens the Scales tool as it always did.
    async function startScalesLadder() {
        if (!scaleLevelsOn()) return false;
        await loadScaleLevels();
        const { family, items } = scaleLevelItems();
        if (!scaleLevels.instrumentId || !items.length) return false;
        switchView('scalesView');
        // Your own Scales settings come back when the block ends (scalesLadderEnd)
        scalesLadder = { saved: JSON.stringify(scales), items, family, played: new Set(), count: 0, current: null, busy: false };
        scalesLadderNext();
        return true;
    }
    function scalesLadderNext() {
        const L = scalesLadder;
        if (!L) return;
        let queue = PracticePlan.scalePool(L.items, scaleLevels.records, Date.now(), [...L.played]);
        if (!queue.length) { L.played.clear(); queue = PracticePlan.scalePool(L.items, scaleLevels.records, Date.now()); }
        // Every scale learnt and none due back yet: the one played longest ago, to keep it
        if (!queue.length) queue = L.items.map(it => ({ ...it, rec: scaleLevelOf(it.key), revisit: true })).sort((a, b) => (Date.parse(a.rec.lastPlayed) || 0) - (Date.parse(b.rec.lastPlayed) || 0));
        L.current = queue[0];
        L.count++;
        L.shownAt = Date.now();
        L.nudged = false;
        scalesLadderShow();
    }
    // The current scale at its Level: what's shown (Detail) and the speed come from the Level
    function scalesLadderShow() {
        const L = scalesLadder;
        if (!L || !L.current) return;
        const rec = scaleLevelOf(L.current.key);
        const spec = PracticePlan.scaleLevelSpec(rec.level);
        const speed = PracticePlan.scaleSpeed(L.current, rec.level, L.family, scales.grades);
        if (scalesPlayer.isPlaying()) scalesPause();
        scales.detail = spec.detail;
        scales.npb = speed.npb;
        scales.bpm = Math.min(SCALES_BPM_MAX, Math.max(METRO_MIN_BPM, speed.bpm));
        scales.metronome = true;
        scalesGo(L.current); // draws it (scalesSave leaves your saved settings alone during a block)
        scalesPlayer.setConductorBpm(scales.bpm);
        scalesRenderBpm();
    }
    // Leaving the Scales screen (or the block ending) puts your own settings back
    function scalesLadderEnd() {
        const L = scalesLadder;
        if (!L) return;
        scalesLadder = null;
        if (scalesPlayer.isPlaying()) scalesPause();
        try { Object.assign(scales, JSON.parse(L.saved)); } catch (e) { /* keeps what it had */ }
        renderScales();
        scalesRenderBpm();
    }
    // What the screen shows for a block (two boxes and Not yet / Got it) or, outside one, the scale's Level link
    function renderScalesLadder() {
        // ML-589: the Level box beside Settings; Not yet / Play / Got it and "Scale 2 of 3" are in the bar at the bottom
        const L = scalesLadder;
        setShown('scalesLadderLevelBtn', !!(L && L.current));
        // In a block the title is just its name - the block picks its three scales, so there's no list to open
        setShown('scalesSubIcon', !L);
        document.getElementById('scalesChooseBtn').setAttribute('aria-disabled', String(!!L));
        const link = document.getElementById('scalesLevelLink');
        if (L && L.current) {
            const rec = scaleLevelOf(L.current.key);
            const chip = document.getElementById('scalesLadderLevelChip');
            chip.className = `level-chip lv-${rec.level}`;
            chip.innerHTML = rec.learnt ? '<span class="material-symbols-outlined" aria-hidden="true">star</span>' : String(rec.level);
            document.getElementById('scalesLadderLevelBtn').setAttribute('aria-label', `${rec.learnt ? 'Learnt' : `Level ${rec.level}`} - tap for what each Level means`);
            setShown(link, false);
            return;
        }
        // Outside a block: a scale that's in your list says its Level, and a tap sets it by hand
        const mine = scaleLevelsOn() && scaleLevels && scaleLevels.instrumentId ? scaleLevelItems().items.find(scalesSame) : null;
        setShown(link, !!mine);
        if (mine) { const rec = scaleLevelOf(mine.key); link.textContent = `${rec.learnt ? 'Learnt ★' : `Level ${rec.level}`} - change`; }
    }
    function scaleSubText() {
        const L = scalesLadder;
        if (!L || !L.current) return '';
        const rec = scaleLevelOf(L.current.key);
        return rec.learnt ? 'still got it?' : PracticePlan.scaleLevelSpec(rec.level).label.toLowerCase();
    }
    // The stars: every scale has left a Level, or a scale is learnt
    function showScaleUp({ title, pair, sub, items }) {
        document.getElementById('scaleUpTitle').textContent = title;
        document.getElementById('scaleUpPair').innerHTML = pair;
        document.getElementById('scaleUpSub').textContent = sub;
        const p = PracticePlan.scaleProgress(items, scaleLevels.records);
        document.getElementById('scaleUpGoalText').innerHTML = scaleGoalHtml(p);
        const bar = document.getElementById('scaleUpGoalBar');
        bar.innerHTML = levelBarHtml(scaleLevelMap(items), { noun: 'scale' });
        sizeLevelBars(bar);
        setShown('scaleUpGoal', true);
        const stars = document.getElementById('scaleUpStars');
        stars.classList.remove('is-celebrating');
        showModal('scaleUpModal');
        requestAnimationFrame(() => stars.classList.add('is-celebrating'));
    }
    document.getElementById('scaleUpOkBtn')?.addEventListener('click', () => hideModal('scaleUpModal'));
    // After an answer: a small message for each scale; the stars only for the big moments
    function scaleAnswerSay(item, res, before, items) {
        const name = scaleShortName(item);
        const after = PracticePlan.scaleProgress(items, scaleLevels.records);
        const arrow = '<span class="material-symbols-outlined" aria-hidden="true">arrow_forward</span>';
        if (res.outcome === 'learnt') {
            showScaleUp({ title: `${name} is learnt!`, pair: `<span class="level-chip lv-5">5</span>${arrow}<span class="level-chip lv-5"><span class="material-symbols-outlined">star</span></span>`, sub: 'By name, at full speed. It will come back now and then so it stays learnt.', items });
            return;
        }
        if (before.low != null && after.low != null && after.low > before.low) {
            const next = PracticePlan.scaleLevelSpec(after.low);
            showScaleUp({ title: `Every scale is at Level ${after.low}!`, pair: `<span class="level-chip lv-${before.low}">${before.low}</span>${arrow}<span class="level-chip lv-${after.low}">${after.low}</span>`, sub: `All ${items.length} of your scales have left Level ${before.low}. Next: ${next.label.toLowerCase()}.`, items });
            return;
        }
        const say = {
            up: `${name}: up to Level ${res.record.level}`,
            held: `${name}: it has gone up today already - again tomorrow`,
            kept: `${name}: still got it ★`,
            back: `${name}: back to Level 4 for a polish`,
            stay: `${name}: again next time`
        }[res.outcome];
        if (say) showSuccessToast(say);
    }
    async function scaleAnswerSave(item, gotIt, items) {
        const before = PracticePlan.scaleProgress(items, scaleLevels.records);
        let res = await API.scaleLevels.answer({ instrumentId: scaleLevels.instrumentId, key: item.key, gotIt, today: scaleToday() });
        // ML-220: offline, the answer waits to sync - the same rule the server uses moves the Level here
        if (res.queued) res = PracticePlan.scaleAnswer(scaleLevels.records[item.key], gotIt, scaleToday());
        scaleLevels.records[item.key] = res.record;
        scaleAnswerSay(item, res, before, items);
    }
    async function scalesLadderAnswer(gotIt) {
        const L = scalesLadder;
        if (!L || !L.current || L.busy) return;
        L.busy = true;
        const cur = L.current;
        try { await scaleAnswerSave(cur, gotIt, L.items); }
        catch (e) { showWarningToast('Not saved: ' + e.message); }
        L.played.add(cur.key);
        L.busy = false;
        if (scalesLadder === L) scalesLadderNext();
    }
    document.getElementById('scalesGotItBtn')?.addEventListener('click', () => { window.Usage?.finish('scales'); scalesLadderAnswer(true); }); // ML-22: answered
    document.getElementById('scalesNotYetBtn')?.addEventListener('click', () => { window.Usage?.finish('scales'); scalesLadderAnswer(false); });
    // The block's time ran out on a scale: one last "Got it?" for it (the Skills block's pop-up), then on
    function askScaleRating(cur, items, then) {
        const rec = scaleLevelOf(cur.key);
        document.getElementById('skillRateTitle').textContent = `${scaleShortName(cur)}: got it?`;
        document.getElementById('skillRateSub').textContent = rec.learnt ? 'Still got it, by name at full speed?' : `Level ${rec.level}: ${PracticePlan.scaleLevelSpec(rec.level).label.toLowerCase()}`;
        document.getElementById('skillRateNext').textContent = rec.learnt ? 'It keeps its star' : rec.level >= PracticePlan.SCALE_TOP_LEVEL ? 'Then it is learnt' : `Next time: ${PracticePlan.scaleLevelSpec(rec.level + 1).label.toLowerCase()}`;
        const done = (gotIt) => {
            hideModal('skillRateModal');
            (gotIt === null ? Promise.resolve() : scaleAnswerSave(cur, gotIt, items).catch(e => showWarningToast('Not saved: ' + e.message))).then(() => then && then());
        };
        document.getElementById('skillRateYesBtn').onclick = () => done(true);
        document.getElementById('skillRateNoBtn').onclick = () => done(false);
        document.getElementById('skillRateCloseBtn').onclick = () => done(null);
        showModal('skillRateModal');
    }
    // What each Level means for a scale - and setting one by hand (you know it already, or it got too hard)
    function openScaleLevelPicker(item, family, after) {
        const rec = scaleLevelOf(item.key);
        const options = PracticePlan.SCALE_LEVELS.map(l => {
            const sp = PracticePlan.scaleSpeed(item, l.level, family, scales.grades);
            const speed = l.level === PracticePlan.SCALE_TOP_LEVEL ? `Grade ${sp.grade} speed: ${sp.npb} notes a beat at ${sp.bpm} · then it is learnt` : `${l.percent}% of full speed`;
            return { key: l.level, title: l.label, sub: l.level === PracticePlan.SCALE_TOP_LEVEL ? speed : `${l.sub} · ${speed}`, selected: !rec.learnt && rec.level === l.level };
        });
        openChooser(scaleTitleFor(item), options, async (v) => {
            try {
                let res = await API.scaleLevels.setLevel({ instrumentId: scaleLevels.instrumentId, key: item.key, level: Number(v) });
                if (res.queued) res = { record: { ...PracticePlan.scaleRecord(scaleLevels.records, item.key), level: Number(v), learnt: false } }; // ML-220: waiting to sync
                scaleLevels.records[item.key] = res.record;
                showSuccessToast(`${scaleShortName(item)}: Level ${res.record.level}`);
            } catch (e) { showWarningToast('Not saved: ' + e.message); }
            if (after) after();
        });
        const box = document.getElementById('sessionBlockOptions');
        box.querySelectorAll('[data-opt]').forEach((b, i) => {
            b.classList.add('flex-row', 'gap-sm', 'items-center');
            b.querySelector(':scope > span').classList.add('grow');
            b.insertAdjacentHTML('afterbegin', `<span class="level-chip lv-${i + 1}" aria-hidden="true">${i + 1}</span>`);
        });
        box.insertAdjacentHTML('afterbegin', `<p class="metro-help-text">${rec.learnt ? 'This scale is learnt.' : `This scale is at Level ${rec.level}.`} Got it moves it up one. Tap a Level to set it yourself - if you know this one already, or it has got too hard.</p>`);
    }
    document.getElementById('scalesLadderLevelBtn')?.addEventListener('click', () => {
        const L = scalesLadder;
        if (L && L.current) openScaleLevelPicker(L.current, L.family, () => { if (scalesLadder === L) scalesLadderShow(); });
    });
    document.getElementById('scalesLevelLink')?.addEventListener('click', () => {
        const { family, items } = scaleLevelItems();
        const mine = items.find(scalesSame);
        if (mine) openScaleLevelPicker(mine, family, renderScalesLadder);
    });

    // Previous / Next go through your list in order (or shuffled - Settings), wrapping round. Previous goes back to the
    // start of the scale you're on first when it's under way (it took Reset's place, ML-589), as Warm-ups.
    const scalesSame = (p) => scalesPickSame(p, scales);
    function scalesPickFields(p) {
        return { keyId: p.keyId, form: p.form, type: p.type, octaves: p.octaves, pattern: p.pattern || null,
            tonicOctave: Number.isInteger(p.tonicOctave) ? p.tonicOctave : null, extended: p.extended || null }; // extended: Grades 7-8's printed top and bottom notes
    }
    function scalesGo(pick) {
        if (!pick) { showWarningToast('Nothing in your list yet - choose your grades in Settings.'); return; }
        Object.assign(scales, scalesPickFields(pick));
        if (pick.form !== 'major') scales.minorForm = pick.form;
        scalesChanged();
    }
    // The instruments load at sign-in; if that hasn't finished (or failed offline), wait for it here.
    async function scalesGradePool() {
        if (!myInstruments || !myInstruments.length) await loadMyInstruments();
        return scalesGradeGrid().pool;
    }
    async function scalesStep(dir) {
        await scalesGradePool();
        scalesPoolCache = null;
        const list = scalesList();
        const i = list.findIndex(scalesSame);
        // Not in your list (a Skills step, or the list changed): Next starts at the first, Previous at the last
        scalesGo(list[i < 0 ? (dir > 0 ? 0 : list.length - 1) : (i + dir + list.length) % list.length]);
    }
    function scalesGoDir(dir) {
        if (dir < 0 && scalesMetronomeOn() && scalesTick - scalesCountInClicks > SCALES_BEATS_PER_BAR * scales.npb) { scalesReset(); return; }
        scalesStep(dir);
    }
    document.getElementById('scalesNextBtn')?.addEventListener('click', () => scalesGoDir(1));
    document.getElementById('scalesNextMainBtn')?.addEventListener('click', () => scalesGoDir(1));
    document.getElementById('scalesPrevBtn')?.addEventListener('click', () => scalesGoDir(-1));

    // Every Scales pop-up closes on its × / Done (the backdrop and Escape are a11y.js's).
    ['scalesSettingsModal', 'scalesInstrumentModal', 'scalesSizeModal', 'scalesSpeedModal', 'scalesRepeatModal', 'scalesClefModal', 'scalesDirModal', 'scalesDetailModal', 'scalesNpbModal', 'scalesCountInModal', 'scalesPoolModal', 'scalesChooseModal', 'scalesMyRangeModal', 'scalesVolumeModal'].forEach(id => {
        const modal = document.getElementById(id);
        if (!modal) return;
        modal.querySelectorAll('[data-modal-close]').forEach(b => b.addEventListener('click', () => hideModal(modal)));
    });

    // Home tile icon: three rising crotchets on a scrap of staff, drawn in Bravura like Theory's clef.
    (function renderScalesToolIcon() {
        const el = document.getElementById('scalesToolIcon');
        if (!el) return;
        const svg = Notation.staff({ clef: 'treble', hideClef: true, noteGap: 0.6, items: ['E4', 'G4', 'B4'].map(pitch => ({ type: 'note', pitch, head: 'noteQuarterUp' })) });
        el.outerHTML = svg.replace('class="notation"', 'class="notation tool-icon-svg"');
    })();

    // ========================================
    // WARM-UPS (Jira ML-294, ML-586)
    // ========================================
    // Brass warm-up exercises, one at a time, through the topics chosen in Settings, in order (Admin -> Warm-ups
    // sets the order and the notes) or shuffled. Written for treble-clef brass; bass clef is the same exercise
    // down a major 9th (Warmups.pitchFor). ML-586 (owner, 23 Oct 2026): two ways to use it - at your own pace
    // (Previous / Next warm-up) or with the metronome, which plays each one (twice by default) at its own speed
    // and carries straight on to the next. Everything else is under one Settings button, saved on the account
    // (accounts.warmup_prefs - the same on every device; a copy on the device, 'tml.warmups', for offline and
    // for where you were). Every warm-up is drawn at the same music size, as many bars on a line as fit; the line
    // being played is kept in view, and the count-in shows in the bar at the bottom of the screen, which never
    // moves. A warm-up outside your comfortable range (or beyond the instrument) is locked - left out of the
    // list until your range grows. See specs/components/warmups.md and docs/warmups.md.
    const WARMUPS_STORE = 'tml.warmups';
    // clef is only used once clefSet (chosen in Settings) - until then it's the one you read your instrument in.
    let warmups = (() => {
        const base = { ...Warmups.PREF_DEFAULTS, kinds: Warmups.PREF_DEFAULTS.kinds.slice(), clef: 'treble', clefSet: false, currentId: null };
        try {
            const saved = JSON.parse(localStorage.getItem(WARMUPS_STORE) || 'null');
            if (saved) {
                // ML-586: the old "repeat" (once by default) isn't carried over - "play each one" starts at twice (owner).
                let prefs = {};
                try { prefs = Warmups.cleanPrefs(Object.fromEntries(Object.keys(Warmups.PREF_DEFAULTS).filter(k => k in saved).map(k => [k, saved[k]]))); } catch (e) { /* an old value - defaults */ }
                // ML-528: the clef is the one you read your instrument in (My instruments); choosing another is for this visit only.
                return { ...base, ...prefs, currentId: saved.currentId ?? null };
            }
        } catch (e) { /* unreadable - defaults */ }
        return base;
    })();
    const warmupsPrefsOf = () => Object.fromEntries(Object.keys(Warmups.PREF_DEFAULTS).map(k => [k, warmups[k]]));
    function warmupsSave() {
        try { localStorage.setItem(WARMUPS_STORE, JSON.stringify({ ...warmupsPrefsOf(), currentId: warmups.currentId })); } catch (e) { /* private browsing */ }
    }
    // The account's copy - read once a visit; the first time (nothing saved yet) this device's settings are saved to it.
    let warmupsPrefsRead = false, warmupsPrefsTimer = null;
    async function warmupsLoadPrefs() {
        if (warmupsPrefsRead) return;
        try {
            const { prefs } = await apiCall('/api/account/warmups');
            warmupsPrefsRead = true;
            if (!prefs || !Object.keys(prefs).length) { warmupsSavePrefs(); return; }
            Object.assign(warmups, Warmups.cleanPrefs(prefs));
            warmupsPlayer.setVolume(warmups.volume / 100);
            warmupsSave();
        } catch (e) { /* offline, or an old value: this device's copy stands */ }
    }
    function warmupsSavePrefs() {
        warmupsSave();
        clearTimeout(warmupsPrefsTimer);
        // A moment after the last change (the volume slider sends many)
        warmupsPrefsTimer = setTimeout(() => { apiCall('/api/account/warmups', 'PUT', { prefs: warmupsPrefsOf() }).catch(() => { /* kept on this device - the next change sends them again */ }); }, 600);
    }
    // ML-586: what is changed, counted (anonymous - analytics.js) so the screen can be simplified by what's used.
    function warmupsTrack(setting, value) {
        try { window.posthog?.capture?.('warm-ups setting', { setting, value }); } catch (e) { /* counting is never in the way */ }
    }
    function warmupsSetPref(key, value) {
        warmups[key] = value;
        warmupsSavePrefs();
        warmupsTrack(key, value);
    }

    let warmupsAll = null;      // every switched-on exercise, from the server (loaded once a visit)
    let warmupsBpm = 72;        // this exercise's speed - its own, at the chosen percentage
    // ML-321: while practising a Warm-ups skill, only that kind (whatever Settings is set to).
    // ML-343: a session's warm-up list (sessionWarmupIds) - just its exercises, in its order.
    const warmupsChosen = () => (sessionWarmupIds
        ? sessionWarmupIds.map(id => (warmupsAll || []).find(ex => ex.id === id)).filter(Boolean)
        : (warmupsAll || []).filter(ex => (skillWarmupsKind ? ex.kind === skillWarmupsKind : warmups.kinds.includes(ex.kind))));
    // ML-361: the instrument (Settings; your main one to start with) and its range. The clef is the one you
    // read it in until another is chosen in Settings (a euphonium can read any).
    const warmupsInstrument = () => (myInstruments || []).find(i => i.id === warmups.instrumentId) || (myInstruments || []).find(i => i.isPrimary) || (myInstruments || [])[0] || null;
    const warmupsOwnClef = (inst) => (inst && ['bass', 'tenor'].includes(inst.theoryClef) ? inst.theoryClef : 'treble');
    const warmupsClef = () => (warmups.clefSet ? warmups.clef : warmupsOwnClef(warmupsInstrument()));
    // In the instrument's own clef, where its range and yours are written: ready / locked (outside your
    // range for now) / beyond (the instrument can't play it).
    // high is the outer limit - a 4th above the usual top on brass and woodwind (ML-370) - so a warm-up up
    // there is locked until your range reaches it, not beyond the instrument. Until your range is set
    // (every warm-up the instrument plays counts as in your list) it's the usual top.
    function warmupsRangeOf(inst) {
        const m = (x) => (x ? Warmups.midi(x) : null);
        const outer = instrumentOuter(inst);
        return inst ? { low: m(inst.rangeLow), high: m(inst.topNote && outer ? outer.high : inst.rangeHigh), usualHigh: m(inst.rangeHigh), bottom: m(inst.bottomNote), top: m(inst.topNote) } : {};
    }
    function warmupsState(ex, inst = warmupsInstrument()) {
        const sp = inst && Warmups.span(ex, warmupsOwnClef(inst));
        if (!sp) return 'ready';
        const r = warmupsRangeOf(inst);
        if ((r.low != null && sp[0] < r.low) || (r.high != null && sp[1] > r.high)) return 'beyond';
        if ((r.bottom != null && sp[0] < r.bottom) || (r.top != null && sp[1] > r.top)) return 'locked';
        return 'ready';
    }
    function warmupsWhy(ex) {
        const inst = warmupsInstrument(), sp = Warmups.span(ex, warmupsOwnClef(inst)), r = warmupsRangeOf(inst);
        const named = (x) => PlayRange.label(PlayRange.pitchOf(x, 'usual'));
        if (warmupsState(ex, inst) === 'beyond') return `beyond the ${inst.name}`;
        return r.top != null && sp[1] > r.top ? `goes up to ${named(sp[1])} - outside your range` : `goes down to ${named(sp[0])} - outside your range`;
    }
    // ML-586: Shuffle - one mixed-up order a visit (made again when the list changes), so Previous goes back.
    // A session's or a skill's list keeps its own order.
    let warmupsShuffled = null;
    function warmupsOrdered(list) {
        if (!warmups.shuffle || sessionWarmupIds || skillWarmupsKind) return list;
        const key = list.map(ex => ex.id).join();
        if (!warmupsShuffled || warmupsShuffled.key !== key) {
            const order = list.map(ex => ex.id);
            for (let i = order.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
            warmupsShuffled = { key, order };
        }
        return warmupsShuffled.order.map(id => list.find(ex => ex.id === id));
    }
    // The list Previous / Next go through: the chosen ones you can play.
    const warmupsList = () => warmupsOrdered(warmupsChosen().filter(ex => warmupsState(ex) === 'ready'));
    function warmupsCurrent() {
        const list = warmupsList();
        return list.find(ex => ex.id === warmups.currentId) || list[0] || null;
    }
    async function warmupsLoad() {
        await warmupsLoadPrefs();
        if (warmupsAll) return;
        try {
            warmupsAll = (await API.warmups.list()).exercises;
        } catch (error) {
            warmupsAll = null;
            showWarningToast('Error loading warm-ups: ' + error.message);
        }
    }

    // --- Own pace or with the metronome ---
    // In a session's Warm-up block it starts with the metronome (ML-390) whatever the setting; switching it off
    // there is for that block only. sessionWarmupLoop.metronome holds it.
    const warmupsMetronomeOn = () => (sessionWarmupLoop ? sessionWarmupLoop.metronome !== false : warmups.metronome === true);
    // Each warm-up at its own speed, at the chosen percentage (and, in a session, a little faster each round).
    const warmupsBpmOf = (ex, round = 1) => PracticePlan.warmupRoundBpm(Math.round(ex.bpm * warmups.speed / 100), round);

    // --- The exercise ---
    let warmupsTimeline = null;
    // With the metronome the list is one metronome sequence (the player's ML-193 sequence mode): each warm-up is
    // a passage (its count-in bar, then its notes once or twice), and the player asks for the next one on the
    // beat the last one ends - so it carries straight on in time. Stopping and restarting the player between
    // exercises sounded the next bar's first click twice (owner, 1 Oct 2026).
    // ML-390: in a session (sessionWarmupLoop) the list plays on a loop until the block ends, a little faster each
    // round; ML-586: on the tool's own (warmupsToolLoop) it stops after the last one.
    // A loop: { round, tag (the passage on screen), queued (the last one handed to the player), metronome (session) }.
    let warmupsToolLoop = null;
    const warmupsLoop = () => sessionWarmupLoop || warmupsToolLoop;
    function warmupsPassage(ex, round, tag) {
        const tl = Warmups.timeline(ex);
        const countIn = warmups.countIn ? ex.beatsPerBar * tl.notesPerBeat : 0;
        return { bpm: warmupsBpmOf(ex, round), beatsPerBar: ex.beatsPerBar, notesPerBeat: tl.notesPerBeat, startClick: 0, boundaryClicks: countIn + warmups.times * tl.totalClicks, tag };
    }
    // The stave ends with a repeat sign when the metronome plays it more than once in a row (ML-538).
    const warmupsRepeats = () => warmupsMetronomeOn() && warmups.times > 1;
    // The player's boundary call - a little ahead of the beat, while the clicks are being scheduled.
    function warmupsLoopBoundary() {
        const L = warmupsLoop();
        const list = warmupsList();
        if (!L || !L.queued || !list.length) return null;
        const i = list.findIndex(ex => ex.id === L.queued.ex.id);
        if (L !== sessionWarmupLoop && (i < 0 || i + 1 >= list.length)) return null; // the end of the list
        const round = L.queued.round + (i + 1 >= list.length ? 1 : 0);
        const ex = list[(i + 1) % list.length];
        L.queued = { ex, round, tag: `${ex.id}:${round}:${++L.n}` };
        return warmupsPassage(ex, round, L.queued.tag);
    }
    // The next exercise's first click has sounded: show it (without stopping the player).
    function warmupsLoopArrive() {
        const L = warmupsLoop(), q = L.queued;
        L.tag = q.tag;
        L.round = q.round;
        warmups.currentId = q.ex.id;
        warmupsBpm = warmupsBpmOf(q.ex, q.round);
        warmupsSave();
        warmupsTick = 0;
        warmupsCountdown = 0;
        warmupsPass = 0;
        renderWarmups();
        warmupsCountInClicks = warmups.countIn ? q.ex.beatsPerBar * warmupsTimeline.notesPerBeat : 0;
    }

    // --- Drawing: one music size for every warm-up (ML-586) ---
    // Staff units (a stave space is 10) to screen pixels, per music size. Medium fits a bar of eight quavers and a
    // held note on one line of a phone (the long tones used to be drawn at about 1, quavers at about 0.8); a line holds as many whole bars as fit the width, and all but the last line are spread to
    // the full width (the notes stay the same size - only the space between them grows).
    const WARMUPS_SIZE_SCALE = { small: 0.72, medium: 0.85, large: 1.1 };
    const WARMUPS_SIZE_LABELS = [['small', 'Small'], ['medium', 'Medium'], ['large', 'Large']];
    const warmupsSvgWidth = (svg) => parseFloat(/width="([\d.]+)"/.exec(svg)[1]);
    function renderWarmupsStaff(ex) {
        const staff = document.getElementById('warmupsStaff');
        const clef = warmupsClef();
        const stepRange = Warmups.stepRange(ex, clef);
        const scale = WARMUPS_SIZE_SCALE[warmups.size] || WARMUPS_SIZE_SCALE.medium;
        const width = (staff.clientWidth || 320) / scale; // in staff units
        const opts = (r, extra) => ({ clef, items: r.items, spans: r.spans, stepRange, noteGap: 1.6, label: `${ex.title}, notes ${r.from + 1} to ${r.to + 1}`, ...extra });
        const rows = Warmups.fitRows(ex, clef, width, (r) => warmupsSvgWidth(Notation.staff(opts(r))), { repeat: warmupsRepeats() });
        staff.innerHTML = rows.map((r, i) => {
            let svg = Notation.staff(opts(r));
            // Spread out only when it's over half way across already - a held note alone on a line stays as it is.
            const natural = warmupsSvgWidth(svg);
            if (i < rows.length - 1 && natural < width && natural > width * 0.5) svg = Notation.staff(opts(r, { justify: width / 10 }));
            // Drawn at the music size: the width and height scaled (a line wider than the screen shrinks to fit).
            svg = svg.replace(/ width="([\d.]+)" height="([\d.]+)"/, (m, w, h) => ` width="${(w * scale).toFixed(1)}" height="${(h * scale).toFixed(1)}"`);
            return `<div class="warmups-row" data-from="${r.from}" data-to="${r.to}">${svg}</div>`;
        }).join('');
        warmupsLitRow = null;
    }
    // Redrawn when the width changes (turning the phone, a wider window).
    let warmupsStaffWidth = 0;
    if (typeof ResizeObserver !== 'undefined') {
        new ResizeObserver(() => {
            const w = document.getElementById('warmupsStaff')?.clientWidth || 0;
            if (!w || w === warmupsStaffWidth) return;
            warmupsStaffWidth = w;
            if (isShown('warmupsView') && warmupsCurrent()) { renderWarmupsStaff(warmupsCurrent()); warmupsLight(warmupsLitIndex); }
        }).observe(document.getElementById('warmupsStaff'));
    }

    function renderWarmups() {
        const ex = warmupsCurrent();
        const list = warmupsList();
        const staff = document.getElementById('warmupsStaff');
        if (!ex) {
            warmupsTimeline = null;
            const locked = warmupsChosen().length;
            document.getElementById('warmupsTitle').textContent = warmupsAll ? 'No warm-ups to show' : 'Warm-ups';
            document.getElementById('warmupsSub').textContent = !warmupsAll ? '' : locked ? 'They\'re all outside your range for now - see Settings.' : 'Choose some topics in Settings.';
            document.getElementById('warmupsTip').textContent = '';
            staff.innerHTML = '';
            renderWarmupsDock();
            return;
        }
        warmups.currentId = ex.id;
        const kindLabel = (Warmups.KINDS.find(k => k.id === ex.kind) || {}).label || ex.kind;
        document.getElementById('warmupsTitle').textContent = ex.title;
        document.getElementById('warmupsSub').textContent = kindLabel; // ML-607: not "5 of 65" - you only play some of them
        document.getElementById('warmupsTip').textContent = ex.tip || '';
        warmupsTimeline = Warmups.timeline(ex);
        renderWarmupsStaff(ex);
        warmupsLight(warmupsLitIndex);
        renderWarmupsDock();
    }
    let warmupsLitIndex = -1, warmupsLitRow = null;
    function warmupsLight(i) {
        warmupsLitIndex = i;
        document.querySelectorAll('#warmupsStaff .is-now').forEach(el => el.classList.remove('is-now'));
        if (i < 0) return;
        if (warmups.light) document.querySelectorAll(`#warmupsStaff .warmup-note-${i}`).forEach(el => el.classList.add('is-now')); // a setting - off for a player who doesn't need it
        // The line being played stays in view, near the top, with the next line under it (ML-586).
        const row = [...document.querySelectorAll('#warmupsStaff .warmups-row')].find(r => i >= Number(r.dataset.from) && i <= Number(r.dataset.to));
        if (!row || row === warmupsLitRow) return;
        warmupsLitRow = row;
        const dock = document.getElementById('warmupsDock').getBoundingClientRect();
        const header = document.querySelector('.top-bar-sticky-group');
        const top = header ? header.getBoundingClientRect().bottom : 0;
        const bottom = (row.nextElementSibling || row).getBoundingClientRect().bottom;
        if (row.getBoundingClientRect().top < top || bottom > dock.top) row.scrollIntoView({ block: 'start', behavior: scrollMotion() });
    }

    // --- The bar at the bottom: own pace - Previous, Next warm-up; with the metronome - Previous, Play, Next ---
    let warmupsPass = 0, warmupsListDone = false;
    const WARMUPS_TIMES_WORDS = ['', 'once', 'twice'];
    function renderWarmupsDock() {
        const list = warmupsList(), ex = warmupsCurrent();
        const metro = warmupsMetronomeOn();
        const playing = warmupsPlayer.isPlaying();
        setShown('warmupsNextMainBtn', !metro);
        setShown('warmupsNextBtn', metro);
        setShown('warmupsPlayBtn', metro && !(warmupsCountdown > 0));
        setShown('warmupsCountIn', metro && warmupsCountdown > 0);
        ['warmupsPrevBtn', 'warmupsNextBtn', 'warmupsNextMainBtn'].forEach(id => { document.getElementById(id).disabled = list.length < 2; });
        document.getElementById('warmupsPlayBtn').disabled = !ex;
        // ML-607: what is playing only - no bar of how far through the list and nothing about what comes next
        let now = '';
        if (warmupsListDone) now = 'That\'s the whole list - well done!';
        else if (ex && metro) {
            const times = warmups.times;
            const what = warmupsCountdown > 0 ? 'count-in' : !playing ? `play ${WARMUPS_TIMES_WORDS[times]}` : times > 1 ? `${warmupsPass + 1 === 1 ? '1st' : '2nd'} time of ${times}` : '';
            now = `${warmupsBpm} bpm${what ? ` · ${what}` : ''}`;
        }
        document.getElementById('warmupsStatusNow').textContent = now;
        setShown('warmupsStatus', !!now);
    }
    function warmupsShowCountIn(left, total) {
        const num = document.getElementById('warmupsCountInNum');
        if (left > 0) {
            num.textContent = left;
            const heard = total - left + 1;
            document.getElementById('warmupsCountInDots').innerHTML = Array.from({ length: total }, (_, k) => `<span class="warmups-countin-dot${k < heard ? ' is-done' : ''}"></span>`).join('');
            document.getElementById('warmupsCountIn').setAttribute('aria-label', `Get ready - ${left} - tap to stop`);
        }
        renderWarmupsDock();
    }

    // --- Playing: one click per crotchet (per quaver when there are quavers); a count-in bar before each ---
    const warmupsPlayer = createMetronomePlayer();
    warmupsPlayer.setVisualLatencyMs(metroState.latencyMs);
    warmupsPlayer.setVolume((warmups.volume ?? 80) / 100);
    let warmupsTick = 0, warmupsCountInClicks = 0, warmupsCountdown = 0;
    warmupsPlayer.onBeat((info) => {
        // ML-586: the tool's list has been played to the end
        if (info && info.ended) { warmupsReset(); warmupsListDone = true; window.Usage?.finish('warmups'); renderWarmupsDock(); return; } // ML-22: played to the end
        // ML-541: the block's time ran out during a time through - it's finished when the next one (or the next
        // warm-up) starts
        const finishing = practiceRun && practiceRun.finishingGo;
        if (finishing && finishing.kind === 'warmup' && warmupsTimeline
            && ((info && info.tag && info.tag !== finishing.tag) || Math.floor((warmupsTick - warmupsCountInClicks) / warmupsTimeline.totalClicks) > finishing.pass)) { sessionGoFinished(); return; }
        const L = warmupsLoop();
        if (L && L.tag && info && info.tag && info.tag !== L.tag) warmupsLoopArrive();
        const tl = warmupsTimeline;
        if (!tl) return;
        const k = warmupsTick++ - warmupsCountInClicks;
        if (k < 0) {
            const remaining = Math.ceil(-k / tl.notesPerBeat);
            if (remaining !== warmupsCountdown) { warmupsCountdown = remaining; warmupsShowCountIn(remaining, Math.round(warmupsCountInClicks / tl.notesPerBeat)); }
            warmupsLight(-1);
            return;
        }
        if (warmupsCountdown) { warmupsCountdown = 0; warmupsShowCountIn(0); }
        const pass = Math.floor(k / tl.totalClicks);
        if (pass !== warmupsPass) { warmupsPass = pass; renderWarmupsDock(); }
        warmupsLight(Warmups.noteAt(tl, k % tl.totalClicks));
    });
    function warmupsUpdatePlayUi() {
        const playing = warmupsPlayer.isPlaying();
        document.getElementById('warmupsPlayIcon').textContent = playing ? 'pause' : 'play_arrow';
        document.getElementById('warmupsPlayLbl').textContent = playing ? 'Pause' : 'Play';
        document.getElementById('warmupsPlayBtn').setAttribute('aria-pressed', String(playing));
        renderWarmupsDock();
    }
    function warmupsPlay() {
        if (!warmupsMetronomeOn()) return;
        const ex = warmupsCurrent();
        if (!ex || !warmupsTimeline) return;
        warmupsListDone = false;
        if (warmupsTick === 0) warmupsCountInClicks = warmups.countIn ? ex.beatsPerBar * warmupsTimeline.notesPerBeat : 0;
        let L = warmupsLoop();
        if (!L) L = warmupsToolLoop = { round: 1 };
        if (L.tag) { warmupsPlayer.play(); warmupsUpdatePlayUi(); return; } // carrying on where it paused
        // It starts from the warm-up on screen.
        L.n = (L.n || 0) + 1;
        L.tag = `${ex.id}:${L.round}:${L.n}`;
        L.queued = { ex, round: L.round, tag: L.tag };
        warmupsPlayer.setSequence({ ...warmupsPassage(ex, L.round, L.tag), bpm: warmupsBpm }, warmupsLoopBoundary);
        warmupsPlayer.setConductorBpm(warmupsBpm);
        warmupsPlayer.setConductorBeatsPerBar(ex.beatsPerBar);
        warmupsPlayer.setNotesPerBeat(warmupsTimeline.notesPerBeat);
        warmupsPlayer.setSubdivisionFactor(1);
        warmupsPlayer.play();
        window.Usage?.begin('warmups'); // ML-22
        warmupsUpdatePlayUi();
    }
    function warmupsPause() {
        warmupsPlayer.pause();
        window.Usage?.end('warmups');
        if (warmupsCountdown) { warmupsCountdown = 0; warmupsShowCountIn(0); }
        warmupsUpdatePlayUi();
    }
    function warmupsReset() {
        if (warmupsPlayer.isPlaying()) warmupsPlayer.pause();
        warmupsPlayer.resetToBarStart();
        warmupsPlayer.clearSequence();
        const L = warmupsLoop();
        if (L) L.tag = null; // the next Play starts again from the warm-up on screen
        warmupsTick = 0;
        warmupsCountdown = 0;
        warmupsPass = 0;
        warmupsListDone = false;
        warmupsLight(-1);
        warmupsUpdatePlayUi();
    }
    setupPlayButtonHoldReset('warmupsPlayBtn', () => { if (warmupsPlayer.isPlaying()) warmupsPause(); else warmupsPlay(); }, warmupsReset);
    document.getElementById('warmupsCountIn')?.addEventListener('click', warmupsPause);
    // Another exercise: back to the start, at its own speed.
    function warmupsShow(ex) {
        if (!ex) return;
        warmups.currentId = ex.id;
        const L = warmupsLoop();
        warmupsBpm = warmupsBpmOf(ex, L ? L.round : 1);
        warmupsSave();
        warmupsReset();
        renderWarmups();
    }
    function warmupsStep(dir) {
        const list = warmupsList();
        if (!list.length) return;
        const i = list.indexOf(warmupsCurrent());
        warmupsShow(list[(i + dir + list.length) % list.length]);
    }
    // Previous goes back to the start of the warm-up you're on first (it took Reset's place), then to the one before;
    // with the metronome playing, Previous and Next carry on playing.
    function warmupsGo(dir) {
        const playing = warmupsPlayer.isPlaying();
        const tl = warmupsTimeline;
        if (dir < 0 && warmupsMetronomeOn() && tl && warmupsTick - warmupsCountInClicks > tl.clicksPerBar) warmupsReset();
        else warmupsStep(dir);
        if (playing) warmupsPlay();
    }
    document.getElementById('warmupsPrevBtn')?.addEventListener('click', () => warmupsGo(-1));
    document.getElementById('warmupsNextBtn')?.addEventListener('click', () => warmupsGo(1));
    document.getElementById('warmupsNextMainBtn')?.addEventListener('click', () => warmupsGo(1));

    // --- Volume ---
    let warmupsVolumeBeforeMute = warmups.volume || 80;
    function warmupsRenderVolume() {
        const v = warmups.volume;
        document.getElementById('warmupsVolumeFill')?.style.setProperty('--pct', `${v}%`);
        const thumb = document.getElementById('warmupsVolumeThumb');
        thumb?.style.setProperty('--pct', `${v}%`);
        thumb?.setAttribute('aria-valuenow', String(v));
        document.getElementById('warmupsVolumeValue').textContent = `${v}%`;
        document.getElementById('warmupsVolumeVal').textContent = v === 0 ? 'Off' : `${v}%`;
        const muted = v === 0;
        document.getElementById('warmupsMuteIcon').textContent = muted ? 'volume_off' : 'volume_up';
        document.getElementById('warmupsMuteBtn')?.setAttribute('aria-pressed', String(muted));
        document.getElementById('warmupsVolumeRow')?.classList.toggle('is-muted', muted);
    }
    function warmupsSetVolume(v, force = false) {
        warmups.volume = Math.round(Math.min(100, Math.max(0, v)));
        if (warmups.volume > 0) warmupsVolumeBeforeMute = warmups.volume;
        warmupsPlayer.setVolume(warmups.volume / 100);
        warmupsRenderVolume();
        warmupsSavePrefs();
        playVolumeTestClick(warmupsPlayer, force);
    }
    setupSliderInteraction(document.getElementById('warmupsVolumeTrack'), document.getElementById('warmupsVolumeThumb'), {
        onDragRatio: (ratio) => warmupsSetVolume(ratio * 100),
        onArrowStep: (dir) => warmupsSetVolume(warmups.volume + dir * 5),
        onRelease: () => playVolumeTestClick(warmupsPlayer, true),
    });
    setupHoldStepper('warmupsVolumeMinus', -1, (amount) => warmupsSetVolume(warmups.volume + amount, true));
    setupHoldStepper('warmupsVolumePlus', 1, (amount) => warmupsSetVolume(warmups.volume + amount, true));
    makeSliderReadoutEditable('warmupsVolumeValue', () => warmups.volume, (v) => warmupsSetVolume(v, true), { label: 'Volume', min: 0, max: 100 });
    document.getElementById('warmupsMuteBtn')?.addEventListener('click', () => warmupsSetVolume(warmups.volume > 0 ? 0 : warmupsVolumeBeforeMute, true));
    document.getElementById('warmupsVolumeBtn')?.addEventListener('click', () => { warmupsRenderVolume(); showModal('warmupsVolumeModal'); });
    document.getElementById('warmupsVolumeModal')?.addEventListener('click', (e) => { if (e.target.closest('[data-modal-close]')) warmupsTrack('volume', warmups.volume); });

    // --- Settings (ML-586): my warm-ups, then the metronome; each value box opens its own pop-up ---
    const warmupsKindLabel = (k) => (Warmups.KINDS.find(x => x.id === k) || {}).label || k;
    // About how long a list takes, each at its own speed
    const warmupsMinutes = (list) => Math.max(1, Math.round(list.reduce((t, ex) => t + (ex.notes || []).reduce((b, n) => b + Warmups.beatsOf(n), 0) * warmups.times / warmupsBpmOf(ex), 0)));
    const warmupsSpeedWord = (p) => (p === 100 ? 'Their own' : `${p}%`);
    function warmupsRenderSettings() {
        const inst = warmupsInstrument();
        document.getElementById('warmupsInstrumentVal').textContent = inst ? inst.name : 'None';
        document.getElementById('warmupsClefVal').textContent = (SCALES_CLEFS.find(([v]) => v === warmupsClef()) || SCALES_CLEFS[0])[1];
        document.getElementById('warmupsTopicsVal').textContent = warmups.kinds.length === Warmups.KIND_IDS.length ? 'All' : `${warmups.kinds.length} of ${Warmups.KIND_IDS.length}`;
        document.getElementById('warmupsSizeVal').textContent = (WARMUPS_SIZE_LABELS.find(([v]) => v === warmups.size) || WARMUPS_SIZE_LABELS[1])[1];
        document.getElementById('warmupsShuffleToggle').checked = warmups.shuffle;
        const metro = warmupsMetronomeOn();
        document.getElementById('warmupsMetronomeToggle').checked = metro;
        setShown('warmupsMetronomeSettings', metro);
        setShown('warmupsLightRow', metro);
        document.getElementById('warmupsLightToggle').checked = warmups.light;
        document.getElementById('warmupsSpeedVal').textContent = warmupsSpeedWord(warmups.speed);
        document.getElementById('warmupsRepeatVal').textContent = warmups.times === 1 ? 'Once' : 'Twice';
        document.getElementById('warmupsCountInVal').textContent = warmups.countIn ? '1 bar' : 'None';
        warmupsRenderVolume();
        // In a session the topics and the order are the session's, and the metronome switch is for this block only.
        const inSession = !!sessionWarmupLoop;
        document.getElementById('warmupsTopicsBtn').disabled = inSession || !!skillWarmupsKind;
        document.getElementById('warmupsShuffleToggle').disabled = inSession || !!skillWarmupsKind;
        document.querySelector('#warmupsMetronomeLbl .display-toggle-help').textContent = inSession ? 'For this warm-up block - it carries on to the next' : 'It plays each warm-up, then carries on to the next';
        setShown('warmupsSeeRangeBtn', !!inst);
        const chosen = warmupsChosen(), mine = warmupsList();
        document.getElementById('warmupsCount').textContent = !warmupsAll ? ''
            : `${mine.length} warm-up${mine.length === 1 ? '' : 's'} in your list${chosen.length > mine.length ? ` (of ${chosen.length})` : ''}${mine.length ? `, about ${warmupsMinutes(mine)} minute${warmupsMinutes(mine) === 1 ? '' : 's'}` : ''}`;
        const locked = chosen.filter(ex => warmupsState(ex) === 'locked').length, beyond = chosen.filter(ex => warmupsState(ex) === 'beyond').length;
        document.getElementById('warmupsLockedNote').textContent = [locked ? `${locked} ${locked === 1 ? 'is' : 'are'} locked - outside your range for now. They come into your list as your range grows.` : '', beyond && inst ? `${beyond} ${beyond === 1 ? 'is' : 'are'} beyond the ${inst.name}.` : ''].filter(Boolean).join(' ');
    }
    // A change to what's in the list or how it's drawn: back to the start, redrawn.
    function warmupsSettingsChanged() {
        warmupsReset();
        const ex = warmupsCurrent();
        if (ex) warmupsBpm = warmupsBpmOf(ex, warmupsLoop() ? warmupsLoop().round : 1);
        warmupsRenderSettings();
        renderWarmups();
    }
    document.getElementById('warmupsSettingsBtn')?.addEventListener('click', async () => {
        if (!myInstruments || !myInstruments.length) await loadMyInstruments();
        warmupsRenderSettings();
        showModal('warmupsSettingsModal');
    });
    document.getElementById('warmupsInstrumentBtn')?.addEventListener('click', () => {
        const draw = () => renderInstrumentChoice(document.getElementById('warmupsInstrument'), warmupsInstrument(), (id) => {
            warmups.clefSet = false; // the new instrument's own clef
            warmupsSetPref('instrumentId', id);
            hideModal('warmupsInstrumentModal');
            warmupsSettingsChanged();
        });
        draw();
        showModal('warmupsInstrumentModal');
    });
    document.getElementById('warmupsClefBtn')?.addEventListener('click', () => {
        scalesFillGrid('warmupsClefGrid', SCALES_CLEFS.map(([v, l]) => ({ value: l, caption: 'clef', selected: warmupsClef() === v, v })),
            (o) => { warmups.clef = o.v; warmups.clefSet = true; warmupsTrack('clef', o.v); hideModal('warmupsClefModal'); warmupsSettingsChanged(); });
        showModal('warmupsClefModal');
    });
    document.getElementById('warmupsTopicsBtn')?.addEventListener('click', () => {
        const inst = warmupsInstrument(), all = warmupsAll || [];
        const rows = Warmups.KINDS.map(k => {
            const exs = all.filter(ex => ex.kind === k.id);
            const locked = exs.filter(ex => warmupsState(ex, inst) !== 'ready').length;
            return { key: k.id, html: `<strong>${escapeHtml(k.label)}</strong><br><span class="text-sm text-muted">${exs.length} warm-up${exs.length === 1 ? '' : 's'}${locked ? ` · ${locked} locked` : ''}</span>` };
        });
        const picked = new Set(warmups.kinds);
        renderPickList(document.getElementById('warmupsKindsList'), document.getElementById('warmupsKindsBar'), rows, picked, () => {
            const kinds = Warmups.KIND_IDS.filter(k => picked.has(k));
            if (kinds.join() !== warmups.kinds.join()) { warmupsSetPref('kinds', kinds); warmupsSettingsChanged(); }
        }, '');
        showModal('warmupsTopicsModal');
    });
    document.getElementById('warmupsSizeBtn')?.addEventListener('click', () => {
        scalesFillGrid('warmupsSizeGrid', WARMUPS_SIZE_LABELS.map(([v, l]) => ({ value: l, caption: '', selected: warmups.size === v, v })),
            (o) => { warmupsSetPref('size', o.v); hideModal('warmupsSizeModal'); warmupsSettingsChanged(); });
        showModal('warmupsSizeModal');
    });
    document.getElementById('warmupsShuffleToggle')?.addEventListener('change', (e) => {
        warmupsShuffled = null;
        warmupsSetPref('shuffle', e.target.checked);
        warmupsSettingsChanged();
    });
    document.getElementById('warmupsMetronomeToggle')?.addEventListener('change', (e) => {
        if (sessionWarmupLoop) { sessionWarmupLoop.metronome = e.target.checked; warmupsTrack('metronome (session)', e.target.checked); }
        else warmupsSetPref('metronome', e.target.checked);
        warmupsPlayer.keepAwake(warmupsMetronomeOn());
        warmupsSettingsChanged();
    });
    document.getElementById('warmupsLightToggle')?.addEventListener('change', (e) => {
        warmupsSetPref('light', e.target.checked);
        warmupsLight(warmupsLitIndex); // takes effect on the note playing now - no need to stop
    });
    document.getElementById('warmupsSpeedBtn')?.addEventListener('click', () => {
        // ML-596: the one list of play speeds (Admin -> Playback speeds), as the metronome's
        const fill = () => scalesFillGrid('warmupsSpeedGrid', playSpeedChoices().map(p => ({ value: `${p}%`, caption: p === 100 ? 'their own' : '', selected: warmups.speed === p, v: p })),
            (o) => { warmupsSetPref('speed', o.v); hideModal('warmupsSpeedModal'); warmupsSettingsChanged(); });
        fill();
        showModal('warmupsSpeedModal');
        if (!flowPlaybackSpeeds.length) ensurePlaySpeeds().then(fill);
    });
    document.getElementById('warmupsRepeatBtn')?.addEventListener('click', () => {
        scalesFillGrid('warmupsRepeatGrid', Warmups.TIMES.map(n => ({ value: `${n}×`, caption: n === 1 ? 'once' : 'twice', selected: warmups.times === n, v: n, attrs: `aria-label="Play each one ${n === 1 ? 'once' : 'twice'}"` })),
            (o) => { warmupsSetPref('times', o.v); hideModal('warmupsRepeatModal'); warmupsSettingsChanged(); });
        showModal('warmupsRepeatModal');
    });
    document.getElementById('warmupsCountInBtn')?.addEventListener('click', () => {
        scalesFillGrid('warmupsCountInGrid', [[0, 'None'], [1, '1 bar']].map(([n, l]) => ({ value: l, caption: '', selected: warmups.countIn === n, v: n })),
            (o) => { warmupsSetPref('countIn', o.v); hideModal('warmupsCountInModal'); warmupsSettingsChanged(); });
        showModal('warmupsCountInModal');
    });
    document.getElementById('warmupsSeeRangeBtn')?.addEventListener('click', () => {
        const inst = warmupsInstrument();
        renderMyRange({ inst, clef: warmupsOwnClef(inst), ctx: { shift: 0, ...warmupsRangeOf(inst) }, what: 'every warm-up', over: 'warmupsSettingsModal', after: () => { warmupsRenderSettings(); renderWarmups(); } });
    });
    // My warm-ups (the title): the chosen topics, each warm-up a row; the locked ones in place with a lock and why
    // (aria-disabled, so they're still read out).
    function warmupsRenderChoose() {
        const chosen = warmupsChosen(), mine = warmupsList(), cur = warmupsCurrent();
        const locked = chosen.length - mine.length;
        document.getElementById('warmupsChooseIntro').textContent = !chosen.length ? 'Nothing chosen yet - choose some topics in Settings.'
            : `${mine.length} warm-up${mine.length === 1 ? '' : 's'}, about ${warmupsMinutes(mine)} minute${warmupsMinutes(mine) === 1 ? '' : 's'}. Tap one to go to it${locked ? ' - the locked ones are outside your range for now' : ''}.`;
        const list = document.getElementById('warmupsChooseList');
        list.innerHTML = Warmups.KINDS.filter(k => chosen.some(ex => ex.kind === k.id)).map(k => {
            const exs = chosen.filter(ex => ex.kind === k.id), ok = exs.filter(ex => mine.includes(ex)).length;
            return `<div class="scales-choose-group"><h3 class="scales-choose-label">${escapeHtml(k.label)}<span class="scale-grid-sub">${ok === exs.length ? `${exs.length} warm-up${exs.length === 1 ? '' : 's'}` : `${ok} of ${exs.length} in your list`}</span></h3>${exs.map((ex, i) => mine.includes(ex)
                ? `<button type="button" class="flow-choice-option level-answer warmups-choose-row${cur && ex.id === cur.id ? ' selected' : ''}" data-warmup="${ex.id}" aria-pressed="${!!(cur && ex.id === cur.id)}"><span class="grow">${i + 1}. ${escapeHtml(ex.title)}</span><span class="text-sm text-muted">${warmupsBpmOf(ex)} bpm</span></button>`
                : `<button type="button" class="flow-choice-option level-answer warmups-choose-row is-locked" data-warmup-locked aria-disabled="true"><span class="grow">${i + 1}. ${escapeHtml(ex.title)}<br><span class="text-sm text-muted">${escapeHtml(warmupsWhy(ex))}</span></span><span class="material-symbols-outlined" aria-hidden="true">lock</span></button>`).join('')}</div>`;
        }).join('');
        list.querySelectorAll('[data-warmup]').forEach(b => b.addEventListener('click', () => {
            hideModal('warmupsChooseModal');
            const playing = warmupsPlayer.isPlaying();
            warmupsShow((warmupsAll || []).find(ex => ex.id === Number(b.dataset.warmup)));
            if (playing) warmupsPlay();
        }));
    }
    document.getElementById('warmupsChooseBtn')?.addEventListener('click', async () => {
        if (!myInstruments || !myInstruments.length) await loadMyInstruments();
        warmupsRenderChoose();
        showModal('warmupsChooseModal');
    });
    document.getElementById('warmupsChooseEditBtn')?.addEventListener('click', () => { hideModal('warmupsChooseModal'); document.getElementById('warmupsSettingsBtn')?.click(); });
    ['warmupsSettingsModal', 'warmupsInstrumentModal', 'warmupsTopicsModal', 'warmupsClefModal', 'warmupsSizeModal', 'warmupsSpeedModal', 'warmupsChooseModal', 'warmupsRepeatModal', 'warmupsCountInModal', 'warmupsVolumeModal'].forEach(id => {
        const modal = document.getElementById(id);
        if (!modal) return;
        modal.querySelectorAll('[data-modal-close]').forEach(b => b.addEventListener('click', () => hideModal(modal)));
    });

    // Opening the screen: load the settings and the exercises (once a visit), show the one you were on at its speed.
    async function openWarmupsView() {
        warmupsListDone = false;
        warmupsRenderVolume();
        warmupsUpdatePlayUi();
        renderWarmups();
        warmupsPlayer.prewarm();
        const first = !warmupsAll;
        await warmupsLoad();
        if (!myInstruments || !myInstruments.length) await loadMyInstruments();
        warmupsPlayer.setVolume(warmups.volume / 100);
        warmupsPlayer.keepAwake(warmupsMetronomeOn()); // ML-586: the headphones stay awake while it's open
        if (first) {
            const ex = warmupsCurrent();
            if (ex) warmupsBpm = warmupsBpmOf(ex, warmupsLoop() ? warmupsLoop().round : 1);
        }
        renderWarmups();
    }

    // Theory test hook - LOCAL DEVELOPMENT ONLY, same switch as the Flow one above (localhost +
    // localStorage 'tml.testClock' = '1'). Lets the back-tests start a round with a fixed seed, read the
    // right answer, and move the round's clock on without waiting.
    (function theoryTestHook() {
        let on = false;
        try { on = ['localhost', '127.0.0.1'].includes(location.hostname) && localStorage.getItem('tml.testClock') === '1'; } catch (e) { on = false; }
        if (!on) return;
        window.__theoryTest = {
            start: async (quizId, options, roundId, seed) => {
                theoryStopRound(); // a round still running is simply dropped, not asked about
                theoryQuizId = quizId;
                theoryOptions = TheoryEngine.normaliseOptions(quizId, options);
                theoryRoundId = TheoryEngine.round(roundId).value;
                switchView('theoryOptionsView');
                await theoryStartRound(seed);
            },
            question: () => theoryRound && JSON.parse(JSON.stringify(theoryRound.question)),
            state: () => theoryRound ? { right: theoryRound.right, wrong: theoryRound.wrong, answered: theoryRound.answers.length, locked: theoryRound.locked, block: theoryRound.block, resting: !!theoryRound.resting } : null,
            repeats: (n) => { theoryRepeats = TheoryEngine.repeatsOf(n); },
            advance: (ms) => { theoryTestOffsetMs += ms; theoryTick(); },
            result: () => theoryLastResult && JSON.parse(JSON.stringify({ score: theoryLastResult.score, grade: theoryLastResult.grade, saving: theoryLastResult.saving, saved: theoryLastResult.saved }))
        };
    })();

    // Initialize app on page load
    window.addEventListener('load', initializeApp);

    // ML-197: pull-to-refresh in an installed/standalone PWA reloads the whole page - and with it,
    // silently drops the in-memory timerState above (before that state was itself made
    // server-recoverable, this used to just lose the running timer outright). Scoped to standalone
    // mode only, via a CSS class rather than a blanket overscroll-behavior rule in style.css - an
    // ordinary mobile browser tab still gets pull-to-refresh, where it's an expected gesture rather
    // than an accidental one, and iOS Safari's own `navigator.standalone` is checked too (its PWA
    // mode doesn't set the `display-mode` media feature).
    if (window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone) {
        document.documentElement.classList.add('installed-app');
    }

    // Register service worker so the app can be installed (Add to Home
    // Screen / desktop install prompt on Chrome and Android require one).
    if ('serviceWorker' in navigator) {
        window.addEventListener('load', () => {
            navigator.serviceWorker.register('sw.js').catch(err => {
                console.warn('Service worker registration failed:', err);
            });
        });
    }
